import { useEffect, useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Link, MousePointer, Activity, Settings2, RefreshCw, Lightbulb } from "lucide-react";
import { Button } from "@/components/ui/button";
import { supabase } from "@/integrations/supabase/client";
import { useMetaPixels, MetaPixel } from "@/hooks/useMetaPixels";
import { Skeleton } from "@/components/ui/skeleton";

const CTA_OPTIONS = [
  { value: "LEARN_MORE", label: "Saiba Mais" },
  { value: "SHOP_NOW", label: "Comprar Agora" },
  { value: "SIGN_UP", label: "Cadastre-se" },
  { value: "DOWNLOAD", label: "Baixar" },
  { value: "CONTACT_US", label: "Fale Conosco" },
  { value: "GET_QUOTE", label: "Solicitar Orçamento" },
  { value: "BOOK_NOW", label: "Reservar Agora" },
  { value: "WATCH_MORE", label: "Assistir Mais" },
  { value: "APPLY_NOW", label: "Inscreva-se" },
  { value: "GET_OFFER", label: "Ver Oferta" },
  { value: "SEND_MESSAGE", label: "Enviar Mensagem" },
  { value: "SEND_WHATSAPP_MESSAGE", label: "Enviar WhatsApp" },
  { value: "CALL_NOW", label: "Ligar Agora" },
  { value: "NO_BUTTON", label: "Sem Botão" },
];

const DEFAULT_URL_PARAMS = "utm_source={{site_source_name}}&utm_medium=paid&utm_campaign={{campaign.name}}&utm_content={{ad.name}}";

export interface PublishingDefaults {
  default_destination_url: string | null;
  default_primary_text: string | null;
  default_headline: string | null;
  default_description: string | null;
  default_cta: string | null;
  default_pixel_id: string | null;
  default_url_params: string | null;
}

interface Props {
  config: PublishingDefaults;
  onChange: (config: Partial<PublishingDefaults>) => void;
  clientId: string;
  companyId: string;
  compact?: boolean;
}

export function PublishingDefaultsConfig({ config, onChange, clientId, companyId, compact = false }: Props) {
  const [suggestedUrl, setSuggestedUrl] = useState<string | null>(null);
  const [loadingUrl, setLoadingUrl] = useState(false);
  const { pixels, loading: loadingPixels, fetchPixels, syncPixels, syncing } = useMetaPixels(clientId, companyId);

  // Fetch suggested URL from active campaigns
  useEffect(() => {
    const fetchSuggestedUrl = async () => {
      if (!clientId) return;

      setLoadingUrl(true);
      try {
        // Get URL from ads of active campaigns
        const { data } = await supabase
          .from("ads")
          .select("link_url")
          .eq("client_id", clientId)
          .eq("is_active", true)
          .not("link_url", "is", null)
          .limit(1);

        if (data && data.length > 0 && data[0].link_url) {
          // Clean up URL - remove existing utm params
          try {
            const url = new URL(data[0].link_url);
            url.search = ""; // Remove all query params
            setSuggestedUrl(url.toString());
          } catch {
            setSuggestedUrl(data[0].link_url.split("?")[0]);
          }
        }
      } catch (error) {
        console.error("Error fetching suggested URL:", error);
      } finally {
        setLoadingUrl(false);
      }
    };

    fetchSuggestedUrl();
  }, [clientId]);

  // Fetch pixels on mount
  useEffect(() => {
    if (clientId && companyId) {
      fetchPixels();
    }
  }, [clientId, companyId, fetchPixels]);

  // Set default URL params if not set
  useEffect(() => {
    if (!config.default_url_params) {
      onChange({ default_url_params: DEFAULT_URL_PARAMS });
    }
  }, []);

  const handleUseSuggestedUrl = () => {
    if (suggestedUrl) {
      onChange({ default_destination_url: suggestedUrl });
    }
  };

  const primaryPixel = pixels.find(p => p.is_primary);

  if (compact) {
    return (
      <div className="space-y-4">
        <div className="grid gap-4 md:grid-cols-2">
          <div className="space-y-2">
            <Label htmlFor="destination_url" className="flex items-center gap-2 text-sm">
              <Link className="h-3.5 w-3.5" />
              URL de Destino
            </Label>
            <div className="flex gap-2">
              <Input
                id="destination_url"
                placeholder="https://seusite.com/pagina"
                value={config.default_destination_url || ""}
                onChange={(e) => onChange({ default_destination_url: e.target.value || null })}
                className="flex-1"
              />
              {suggestedUrl && !config.default_destination_url && (
                <Button
                  type="button"
                  variant="outline"
                  size="icon"
                  onClick={handleUseSuggestedUrl}
                  title="Usar URL sugerida"
                >
                  <Lightbulb className="h-4 w-4" />
                </Button>
              )}
            </div>
            {suggestedUrl && !config.default_destination_url && (
              <p className="text-xs text-muted-foreground">
                Sugestão: {suggestedUrl}
              </p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="cta" className="flex items-center gap-2 text-sm">
              <MousePointer className="h-3.5 w-3.5" />
              Botão CTA
            </Label>
            <Select
              value={config.default_cta || "LEARN_MORE"}
              onValueChange={(value) => onChange({ default_cta: value })}
            >
              <SelectTrigger id="cta">
                <SelectValue placeholder="Selecione o CTA" />
              </SelectTrigger>
              <SelectContent>
                {CTA_OPTIONS.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="grid gap-4 md:grid-cols-2">
          <div className="space-y-2">
            <Label htmlFor="pixel_id" className="flex items-center gap-2 text-sm">
              <Activity className="h-3.5 w-3.5" />
              Pixel
            </Label>
            <div className="flex gap-2">
              {loadingPixels ? (
                <Skeleton className="h-10 flex-1" />
              ) : (
                <Select
                  value={config.default_pixel_id || "none"}
                  onValueChange={(value) => onChange({ default_pixel_id: value === "none" ? null : value })}
                >
                  <SelectTrigger id="pixel_id" className="flex-1">
                    <SelectValue placeholder="Selecione um Pixel" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">Nenhum</SelectItem>
                    {pixels.map((pixel) => (
                      <SelectItem key={pixel.id} value={pixel.pixel_id}>
                        {pixel.pixel_name} {pixel.is_primary && "(Principal)"}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
              <Button
                type="button"
                variant="outline"
                size="icon"
                onClick={syncPixels}
                disabled={syncing}
                title="Sincronizar pixels"
              >
                <RefreshCw className={`h-4 w-4 ${syncing ? "animate-spin" : ""}`} />
              </Button>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="url_params" className="flex items-center gap-2 text-sm">
              <Settings2 className="h-3.5 w-3.5" />
              Parâmetros URL
            </Label>
            <Input
              id="url_params"
              placeholder="utm_source={{site_source_name}}&utm_medium=paid"
              value={config.default_url_params || ""}
              onChange={(e) => onChange({ default_url_params: e.target.value || null })}
            />
          </div>
        </div>
      </div>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Settings2 className="h-5 w-5" />
          Configurações Padrão de Publicação
        </CardTitle>
        <CardDescription>
          Defina valores padrão que serão usados ao publicar anúncios no Meta
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="space-y-2">
          <Label htmlFor="destination_url" className="flex items-center gap-2">
            <Link className="h-4 w-4" />
            URL de Destino
          </Label>
          <div className="flex gap-2">
            <Input
              id="destination_url"
              placeholder="https://seusite.com/pagina"
              value={config.default_destination_url || ""}
              onChange={(e) => onChange({ default_destination_url: e.target.value || null })}
              className="flex-1"
            />
            {suggestedUrl && !config.default_destination_url && (
              <Button
                type="button"
                variant="outline"
                onClick={handleUseSuggestedUrl}
                className="shrink-0"
              >
                <Lightbulb className="h-4 w-4 mr-2" />
                Usar Sugestão
              </Button>
            )}
          </div>
          {loadingUrl ? (
            <Skeleton className="h-4 w-48" />
          ) : suggestedUrl && !config.default_destination_url ? (
            <p className="text-xs text-muted-foreground flex items-center gap-1">
              <Lightbulb className="h-3 w-3" />
              Sugestão baseada em campanhas ativas: <span className="font-medium">{suggestedUrl}</span>
            </p>
          ) : (
            <p className="text-xs text-muted-foreground">
              Página para onde os usuários serão direcionados
            </p>
          )}
        </div>

        <div className="space-y-2">
          <Label htmlFor="cta" className="flex items-center gap-2">
            <MousePointer className="h-4 w-4" />
            Botão CTA
          </Label>
          <Select
            value={config.default_cta || "LEARN_MORE"}
            onValueChange={(value) => onChange({ default_cta: value })}
          >
            <SelectTrigger id="cta">
              <SelectValue placeholder="Selecione o CTA" />
            </SelectTrigger>
            <SelectContent>
              {CTA_OPTIONS.map((option) => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground">
            Texto do botão de ação do anúncio
          </p>
        </div>

        <div className="space-y-2">
          <Label htmlFor="pixel_id" className="flex items-center gap-2">
            <Activity className="h-4 w-4" />
            Pixel de Rastreamento
          </Label>
          <div className="flex gap-2">
            {loadingPixels ? (
              <Skeleton className="h-10 flex-1" />
            ) : (
              <Select
                value={config.default_pixel_id || "none"}
                onValueChange={(value) => onChange({ default_pixel_id: value === "none" ? null : value })}
              >
                <SelectTrigger id="pixel_id" className="flex-1">
                  <SelectValue placeholder="Selecione um Pixel" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">
                    {pixels.length === 0 ? "Nenhum pixel encontrado" : "Nenhum"}
                  </SelectItem>
                  {pixels.map((pixel) => (
                    <SelectItem key={pixel.id} value={pixel.pixel_id}>
                      {pixel.pixel_name} {pixel.is_primary && "(Principal)"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
            <Button
              type="button"
              variant="outline"
              onClick={syncPixels}
              disabled={syncing}
              className="shrink-0"
            >
              <RefreshCw className={`h-4 w-4 mr-2 ${syncing ? "animate-spin" : ""}`} />
              Sincronizar
            </Button>
          </div>
          <p className="text-xs text-muted-foreground">
            {pixels.length > 0 
              ? `${pixels.length} pixel(s) disponível(is)${primaryPixel ? ` • Principal: ${primaryPixel.pixel_name}` : ""}`
              : "Clique em Sincronizar para buscar os pixels da conta"
            }
          </p>
        </div>

        <div className="space-y-2">
          <Label htmlFor="url_params" className="flex items-center gap-2">
            <Settings2 className="h-4 w-4" />
            Parâmetros URL (UTM)
          </Label>
          <Input
            id="url_params"
            placeholder="utm_source={{site_source_name}}&utm_medium=paid&utm_campaign={{campaign.name}}"
            value={config.default_url_params || ""}
            onChange={(e) => onChange({ default_url_params: e.target.value || null })}
          />
          <div className="text-xs text-muted-foreground space-y-1">
            <p>Parâmetros adicionados à URL de destino. Use variáveis dinâmicas:</p>
            <ul className="list-disc list-inside ml-2 space-y-0.5">
              <li><code className="bg-muted px-1 rounded">{"{{campaign.name}}"}</code> - Nome da campanha</li>
              <li><code className="bg-muted px-1 rounded">{"{{adset.name}}"}</code> - Nome do conjunto</li>
              <li><code className="bg-muted px-1 rounded">{"{{ad.name}}"}</code> - Nome do anúncio</li>
              <li><code className="bg-muted px-1 rounded">{"{{site_source_name}}"}</code> - Plataforma (fb/ig)</li>
            </ul>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Search, Bot, Plus } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useCompany } from "@/contexts/CompanyContext";
import { CreateAgentModal } from "./CreateAgentModal";

interface Agent {
  id: string;
  agent_name: string;
  description: string | null;
  client_id: string | null;
}

interface SquadAgentLibraryProps {
  clientId?: string;
  onDragStart: (event: React.DragEvent, agent: Agent) => void;
}

export function SquadAgentLibrary({ clientId, onDragStart }: SquadAgentLibraryProps) {
  const [agents, setAgents] = useState<Agent[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [createModalOpen, setCreateModalOpen] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const { activeCompany } = useCompany();

  const fetchAgents = async () => {
    if (!activeCompany?.company_id) return;
    let query = supabase
      .from("ia_agents")
      .select("id, agent_name, description, client_id")
      .eq("company_id", activeCompany.company_id);

    if (clientId) {
      query = query.or(`client_id.eq.${clientId},client_id.is.null`);
    }

    const { data } = await query.order("agent_name");
    setAgents((data || []) as Agent[]);
  };

  useEffect(() => {
    fetchAgents();
  }, [activeCompany?.company_id, clientId, refreshKey]);

  const filtered = agents.filter((a) =>
    a.agent_name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="w-64 border-r bg-card h-full flex flex-col">
      <div className="p-4 border-b space-y-3">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="font-semibold text-sm">Agentes Disponíveis</h3>
            <p className="text-xs text-muted-foreground mt-1">Arraste para o canvas</p>
          </div>
          <Button
            variant="outline"
            size="icon"
            className="h-8 w-8 shrink-0"
            onClick={() => setCreateModalOpen(true)}
            title="Criar novo agente"
          >
            <Plus className="h-4 w-4" />
          </Button>
        </div>
        <div className="relative">
          <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Buscar agentes..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-8 h-9"
          />
        </div>
      </div>

      <ScrollArea className="flex-1">
        <div className="p-4 space-y-2">
          {filtered.map((agent) => (
            <div
              key={agent.id}
              draggable
              onDragStart={(e) => onDragStart(e, agent)}
              className="px-3 py-2.5 rounded-md border bg-background cursor-grab active:cursor-grabbing hover:border-primary hover:bg-accent transition-colors"
            >
              <div className="flex items-center gap-2">
                <Bot className="h-4 w-4 shrink-0 text-primary" />
                <div className="min-w-0">
                  <div className="text-sm font-medium truncate">{agent.agent_name}</div>
                  {agent.description && (
                    <div className="text-xs text-muted-foreground truncate">{agent.description}</div>
                  )}
                </div>
              </div>
            </div>
          ))}
          {filtered.length === 0 && (
            <div className="text-center py-8 text-sm text-muted-foreground">
              Nenhum agente encontrado
            </div>
          )}
        </div>
      </ScrollArea>

      <CreateAgentModal
        open={createModalOpen}
        onOpenChange={setCreateModalOpen}
        defaultClientId={clientId}
        onAgentCreated={() => setRefreshKey((k) => k + 1)}
      />
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { toast } from "sonner";
import { SearchableClientSelect } from "@/components/ui/searchable-client-select";
import { Settings, Brain, FileText, Bot, Puzzle, MessageCircle, Save, UserCheck } from "lucide-react";
import { Switch } from "@/components/ui/switch";
import { useRef } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { AlertCircle } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { useIAAgents } from "@/hooks/useIAAgents";
import { useClients } from "@/hooks/useClients";
import { useCompany } from "@/contexts/CompanyContext";
import { supabase } from "@/integrations/supabase/client";
import { KnowledgeDocumentsManager } from "@/components/agents/KnowledgeDocumentsManager";
import { TelegramBotConfig } from "@/components/agents/TelegramBotConfig";
import { AgentSkillsConfig } from "@/components/agents/AgentSkillsConfig";
import { PromptSkillInjector } from "@/components/agents/PromptSkillInjector";
import { ChatMessages } from "@/components/ai-chat/ChatMessages";
import { ChatInput } from "@/components/ai-chat/ChatInput";
import { AgentConversationsSidebar } from "@/components/agents/AgentConversationsSidebar";
import { cn } from "@/lib/utils";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

type Section = "chat" | "geral" | "prompt" | "conhecimento" | "skills" | "telegram";

const menuItems: { id: Section; label: string; icon: React.ElementType }[] = [
  { id: "chat", label: "Chat", icon: MessageCircle },
  { id: "geral", label: "Geral", icon: Settings },
  { id: "prompt", label: "Prompt & Instruções", icon: Brain },
  { id: "conhecimento", label: "Conhecimento", icon: FileText },
  { id: "skills", label: "Skills", icon: Puzzle },
  { id: "telegram", label: "Telegram Bot", icon: Bot },
];

interface AgentEditContentProps {
  agentId: string;
  defaultSection?: Section;
  showChat?: boolean;
  onSaved?: () => void;
}

export function AgentEditContent({
  agentId,
  defaultSection = "geral",
  showChat = true,
  onSaved,
}: AgentEditContentProps) {
  const {
    currentAgent,
    conversations,
    currentConversation,
    messages,
    loading,
    loadAgent,
    updateAgent,
    createConversation,
    loadConversation,
    renameConversation,
    deleteConversation,
    sendMessage,
  } = useIAAgents();
  const { clients } = useClients();
  const { activeCompany } = useCompany();

  const syncCollaboratorStatus = async (agentId: string, isCollaborator: boolean, agentName: string) => {
    if (!activeCompany?.company_id) return;

    const { data: existingEmployee } = await supabase
      .from('employees')
      .select('id')
      .eq('ia_agent_id', agentId as unknown)
      .eq('company_id', activeCompany.company_id)
      .maybeSingle();

    if (isCollaborator && !existingEmployee) {
      const { error } = await supabase.from('employees').insert({
        company_id: activeCompany.company_id,
        name: `🤖 ${agentName}`,
        email: `agent-${agentId}@ai.internal`,
        role: 'Agente IA',
        status: 'active',
        start_date: new Date().toISOString().split('T')[0],
        user_id: agentId,
        ia_agent_id: agentId,
      } as unknown);
      if (error) {
        console.error('Error creating collaborator employee:', error);
        toast.error('Erro ao criar colaborador. Tente desativar e reativar.');
      }
    } else if (!isCollaborator && existingEmployee) {
      await supabase.from('employees').delete().eq('id', existingEmployee.id);
    } else if (isCollaborator && existingEmployee) {
      await supabase.from('employees').update({
        name: `🤖 ${agentName}`,
      }).eq('id', existingEmployee.id);
    }
  };

  const [saving, setSaving] = useState(false);
  const [activeSection, setActiveSection] = useState<Section>(defaultSection);
  const [formData, setFormData] = useState({
    agent_name: "",
    description: "",
    prompt_base: "",
    additional_instructions: "",
    output_instructions: "",
    client_id: "none",
    is_collaborator: false,
  });
  const [showWarning, setShowWarning] = useState(false);
  const promptRef = useRef<HTMLTextAreaElement>(null);

  const handleInsertSkill = (skillTag: string) => {
    const textarea = promptRef.current;
    if (!textarea) {
      setFormData(prev => ({ ...prev, prompt_base: prev.prompt_base + " " + skillTag }));
      return;
    }
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const text = formData.prompt_base;
    const newText = text.substring(0, start) + skillTag + text.substring(end);
    setFormData(prev => ({ ...prev, prompt_base: newText }));
    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(start + skillTag.length, start + skillTag.length);
    }, 0);
  };

  useEffect(() => {
    if (agentId) {
      loadAgent(agentId);
    }
  }, [agentId]);

  useEffect(() => {
    if (currentAgent) {
      setFormData({
        agent_name: currentAgent.agent_name,
        description: currentAgent.description || "",
        prompt_base: currentAgent.prompt_base,
        additional_instructions: currentAgent.additional_instructions || "",
        output_instructions: (currentAgent as unknown).output_instructions || "",
        client_id: currentAgent.client_id || "none",
        is_collaborator: (currentAgent as unknown).is_collaborator || false,
      });
    }
  }, [currentAgent]);

  const handleSubmit = async (e?: React.FormEvent) => {
    e?.preventDefault();

    if (formData.prompt_base.length < 50) {
      setShowWarning(true);
      setActiveSection("prompt");
      return;
    }

    setSaving(true);
    try {
      const { is_collaborator, ...rest } = formData;
      await updateAgent(agentId, {
        ...rest,
        client_id: rest.client_id === "none" ? null : rest.client_id,
        is_collaborator,
      } as unknown);

      await syncCollaboratorStatus(agentId, is_collaborator, formData.agent_name);

      onSaved?.();
    } finally {
      setSaving(false);
    }
  };

  const handleSendMessage = async (message: string) => {
    if (!currentConversation && agentId) {
      await createConversation(agentId);
    }
    await sendMessage(message);
  };

  const handleNewConversation = async () => {
    if (agentId) {
      await createConversation(agentId);
    }
  };

  const visibleMenuItems = showChat ? menuItems : menuItems.filter((m) => m.id !== "chat");

  if (!currentAgent) {
    return (
      <div className="flex items-center justify-center h-full">
        <p className="text-muted-foreground">Carregando agente...</p>
      </div>
    );
  }

  const isChat = activeSection === "chat";

  return (
    <div className="flex gap-6 h-[calc(100vh-180px)]">
      {/* Sidebar Card — same pattern as SettingsLayout */}
      <Card className="w-80 p-6 shrink-0">
        <div className="space-y-6">
          <div>
            <h2 className="text-lg font-semibold text-foreground">{currentAgent.agent_name}</h2>
            <p className="text-sm text-muted-foreground">
              Configurações do agente
            </p>
          </div>

          <Separator />

          <nav className="space-y-1">
            {visibleMenuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => setActiveSection(item.id)}
                className={cn(
                  "flex items-center gap-3 p-3 rounded-lg transition-colors w-full text-left",
                  activeSection === item.id
                    ? "bg-primary text-primary-foreground"
                    : "hover:bg-muted text-muted-foreground hover:text-foreground"
                )}
              >
                <item.icon className="h-4 w-4 shrink-0" />
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium">{item.label}</div>
                </div>
              </button>
            ))}
          </nav>

          {!isChat && (
            <>
              <Separator />
              <Button onClick={() => handleSubmit()} disabled={saving} className="w-full">
                <Save className="w-4 h-4 mr-2" />
                {saving ? "Salvando..." : "Salvar Alterações"}
              </Button>
            </>
          )}
        </div>
      </Card>

      {/* Content */}
      <div className="flex-1 min-w-0">
        {isChat ? (
          <Card className="flex h-full overflow-hidden min-h-0">
            <AgentConversationsSidebar
              conversations={conversations}
              currentConversation={currentConversation}
              onConversationSelect={loadConversation}
              onConversationDelete={deleteConversation}
              onConversationRename={renameConversation}
              onNewConversation={handleNewConversation}
            />
            <div className="flex-1 flex flex-col">
              {currentConversation ? (
                <>
                  <div className="flex-1 overflow-hidden">
                    <ChatMessages messages={messages} loading={loading} />
                  </div>
                  <div className="border-t border-border p-4">
                    <ChatInput onSendMessage={handleSendMessage} disabled={loading} />
                  </div>
                </>
              ) : (
                <div className="flex-1 flex items-center justify-center text-center">
                  <div>
                    <MessageCircle className="w-12 h-12 mx-auto text-muted-foreground mb-4" />
                    <h3 className="text-lg font-medium mb-2">Nenhuma conversa selecionada</h3>
                    <p className="text-muted-foreground mb-4">
                      Crie uma nova conversa para começar a interagir com {currentAgent.agent_name}
                    </p>
                    <Button onClick={handleNewConversation}>Nova Conversa</Button>
                  </div>
                </div>
              )}
            </div>
          </Card>
        ) : (
          <Card className="p-6 overflow-y-auto max-h-[calc(100vh-220px)]">
            {activeSection === "geral" && (
              <div className="space-y-6">
                <h2 className="text-lg font-semibold mb-4">Configurações Gerais</h2>
                <div>
                  <Label htmlFor="agent_name">Nome do Agente *</Label>
                  <Input
                    id="agent_name"
                    value={formData.agent_name}
                    onChange={(e) => setFormData({ ...formData, agent_name: e.target.value })}
                    placeholder="Ex: Assistente de Marketing"
                    required
                  />
                </div>
                <div>
                  <Label htmlFor="description">Descrição Resumida</Label>
                  <Input
                    id="description"
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    placeholder="Breve descrição do agente (opcional)"
                  />
                </div>
                <div>
                  <Label htmlFor="client_id">Cliente Associado (Opcional)</Label>
                  <SearchableClientSelect
                    clients={clients.map(c => ({ id: c.id, name: c.name }))}
                    value={formData.client_id}
                    onValueChange={(value) => setFormData({ ...formData, client_id: value })}
                    noneLabel="Nenhum cliente específico"
                    placeholder="Selecione um cliente"
                  />
                  <p className="text-sm text-muted-foreground mt-1">
                    Quando associado, o agente terá acesso automático ao briefing, campanhas e métricas deste cliente.
                  </p>
                </div>

                {/* Collaborator Toggle */}
                <div className="flex items-center justify-between rounded-lg border border-border p-4">
                  <div className="space-y-0.5">
                    <div className="flex items-center gap-2">
                      <UserCheck className="w-4 h-4 text-primary" />
                      <Label htmlFor="is_collaborator" className="font-medium">Ativar como Colaborador</Label>
                    </div>
                    <p className="text-sm text-muted-foreground">
                      Quando ativado, este agente aparecerá como colaborador da empresa — podendo ser atribuído a tarefas, 
                      adicionado a squads e contactado no chat interno.
                    </p>
                  </div>
                  <Switch
                    id="is_collaborator"
                    checked={formData.is_collaborator}
                    onCheckedChange={(checked) => setFormData({ ...formData, is_collaborator: checked })}
                  />
                </div>
              </div>
            )}

            {activeSection === "prompt" && (
              <div className="space-y-6">
                <h2 className="text-lg font-semibold mb-4">Prompt & Instruções</h2>
                <div>
                  <Label htmlFor="prompt_base">Prompt Base do Agente *</Label>
                  <Textarea
                    id="prompt_base"
                    ref={promptRef}
                    value={formData.prompt_base}
                    onChange={(e) => {
                      setFormData({ ...formData, prompt_base: e.target.value });
                      if (e.target.value.length >= 50) setShowWarning(false);
                    }}
                    placeholder="Descreva como o agente deve se comportar, seu tom de voz, especialidades..."
                    className="min-h-[250px]"
                    required
                  />
                  <p className="text-sm text-muted-foreground mt-1">
                    {formData.prompt_base.length}/50 caracteres mínimos
                  </p>
                </div>
                <PromptSkillInjector agentId={agentId} onInsertSkill={handleInsertSkill} />
                <div>
                  <Label htmlFor="additional_instructions">Instruções Adicionais</Label>
                  <Textarea
                    id="additional_instructions"
                    value={formData.additional_instructions}
                    onChange={(e) =>
                      setFormData({ ...formData, additional_instructions: e.target.value })
                    }
                    placeholder="Contexto adicional, regras específicas... (opcional)"
                    className="min-h-[180px]"
                  />
                </div>
                {showWarning && (
                  <Alert variant="destructive">
                    <AlertCircle className="h-4 w-4" />
                    <AlertDescription>
                      O prompt deve ter no mínimo 50 caracteres. Seja mais específico sobre como o agente deve se comportar.
                    </AlertDescription>
                  </Alert>
                )}

                <Separator />

                <div>
                  <Label htmlFor="output_instructions">Instruções de Saída (Output)</Label>
                  <Textarea
                    id="output_instructions"
                    value={formData.output_instructions}
                    onChange={(e) =>
                      setFormData({ ...formData, output_instructions: e.target.value })
                    }
                    placeholder="Ex: Sempre inclua a URL da imagem gerada na resposta. Formate links como [texto](url). Liste todos os artefatos produzidos com seus respectivos links."
                    className="min-h-[120px]"
                  />
                  <p className="text-sm text-muted-foreground mt-1">
                    Define como o agente deve formatar suas respostas finais — quais dados incluir, como apresentar links, imagens e resultados.
                  </p>
                </div>
              </div>
            )}

            {activeSection === "conhecimento" && (
              <div className="space-y-6">
                <h2 className="text-lg font-semibold mb-4">Base de Conhecimento</h2>
                <KnowledgeDocumentsManager agentId={agentId} />
              </div>
            )}

            {activeSection === "skills" && (
              <div className="space-y-6">
                <h2 className="text-lg font-semibold mb-1">Skills do Agente</h2>
                <p className="text-sm text-muted-foreground">
                  Habilite as capacidades que este agente pode executar durante conversas.
                </p>
                <AgentSkillsConfig
                  agentId={agentId}
                  hasClient={formData.client_id !== "none"}
                />
              </div>
            )}

            {activeSection === "telegram" && (
              <div className="space-y-6">
                <h2 className="text-lg font-semibold mb-4">Integração com Telegram</h2>
                <TelegramBotConfig
                  agentId={agentId}
                  telegramBotToken={(currentAgent as unknown).telegram_bot_token || null}
                  telegramBotName={(currentAgent as unknown).telegram_bot_name || null}
                  onUpdate={() => loadAgent(agentId)}
                />
              </div>
            )}
          </Card>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Checkbox } from "@/components/ui/checkbox";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Loader2, Globe, Facebook, Instagram, Video, Play, RefreshCw, Check } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";

export interface PixelOption {
  id: string;
  pixel_id: string;
  pixel_name: string;
}

export interface PageOption {
  id: string;
  page_id: string;
  name: string;
}

export interface InstagramOption {
  id: string;
  instagram_id: string;
  username: string;
}

export interface VideoItem {
  id: string;
  title: string;
  description?: string;
  thumbnail_url?: string;
  created_time: string;
  length?: number;
  views?: number;
}

interface CreateAdvancedAudienceModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  clientId: string;
  onCreateWebsiteAudience: (params: {
    name: string;
    pixelId: string;
    retentionDays: number;
    ruleType: 'all_visitors' | 'url_contains' | 'url_equals' | 'event';
    urlValue?: string;
    eventName?: string;
  }) => Promise<void>;
  onCreateEngagementAudience: (params: {
    name: string;
    engagementType: 'page' | 'instagram' | 'video';
    sourceId: string;
    retentionDays: number;
    engagementEvent: string;
    videoPercentile?: number;
    videoIds?: string[];
  }) => Promise<void>;
  loading: boolean;
  pixels: PixelOption[];
  pages: PageOption[];
  instagramAccounts: InstagramOption[];
}

const WEBSITE_EVENTS = [
  { value: 'PageView', label: 'PageView - Visualização de página' },
  { value: 'ViewContent', label: 'ViewContent - Visualizou conteúdo' },
  { value: 'AddToCart', label: 'AddToCart - Adicionou ao carrinho' },
  { value: 'InitiateCheckout', label: 'InitiateCheckout - Iniciou checkout' },
  { value: 'Purchase', label: 'Purchase - Compra' },
  { value: 'Lead', label: 'Lead - Lead capturado' },
  { value: 'CompleteRegistration', label: 'CompleteRegistration - Registro completo' },
  { value: 'Contact', label: 'Contact - Contato' },
  { value: 'Search', label: 'Search - Pesquisa' },
];

const PAGE_EVENTS = [
  { value: 'page_engaged', label: 'Qualquer engajamento com a página' },
  { value: 'page_liked', label: 'Curtiu a página' },
  { value: 'page_visited', label: 'Visitou a página' },
  { value: 'page_messaged', label: 'Enviou mensagem para a página' },
  { value: 'page_cta_clicked', label: 'Clicou no CTA da página' },
  { value: 'page_saved_post', label: 'Salvou post da página' },
];

const INSTAGRAM_EVENTS = [
  { value: 'ig_business_profile_all', label: 'Qualquer interação com o perfil' },
  { value: 'ig_business_profile_engaged', label: 'Engajou com conteúdo' },
  { value: 'ig_business_profile_any', label: 'Visitou perfil ou interagiu' },
];

const VIDEO_PERCENTILES = [
  { value: 25, label: '25% do vídeo' },
  { value: 50, label: '50% do vídeo' },
  { value: 75, label: '75% do vídeo' },
  { value: 95, label: '95% do vídeo (ThruPlay)' },
];

export function CreateAdvancedAudienceModal({
  open,
  onOpenChange,
  clientId,
  onCreateWebsiteAudience,
  onCreateEngagementAudience,
  loading,
  pixels,
  pages,
  instagramAccounts,
}: CreateAdvancedAudienceModalProps) {
  const [activeTab, setActiveTab] = useState("website");

  // Website state
  const [websiteName, setWebsiteName] = useState("");
  const [selectedPixel, setSelectedPixel] = useState("");
  const [websiteRetention, setWebsiteRetention] = useState([30]);
  const [ruleType, setRuleType] = useState<'all_visitors' | 'url_contains' | 'url_equals' | 'event'>('all_visitors');
  const [urlValue, setUrlValue] = useState("");
  const [eventName, setEventName] = useState("");

  // Facebook Page state
  const [pageName, setPageName] = useState("");
  const [selectedPage, setSelectedPage] = useState("");
  const [pageRetention, setPageRetention] = useState([30]);
  const [pageEvent, setPageEvent] = useState("page_engaged");

  // Instagram state
  const [igName, setIgName] = useState("");
  const [selectedInstagram, setSelectedInstagram] = useState("");
  const [igRetention, setIgRetention] = useState([30]);
  const [igEvent, setIgEvent] = useState("ig_business_profile_all");

  // Video state
  const [videoName, setVideoName] = useState("");
  const [videoSource, setVideoSource] = useState<'facebook' | 'instagram'>('facebook');
  const [selectedVideoSourceId, setSelectedVideoSourceId] = useState("");
  const [videoRetention, setVideoRetention] = useState([30]);
  const [videoPercentile, setVideoPercentile] = useState(50);
  const [videos, setVideos] = useState<VideoItem[]>([]);
  const [selectedVideos, setSelectedVideos] = useState<string[]>([]);
  const [loadingVideos, setLoadingVideos] = useState(false);
  const [selectAllVideos, setSelectAllVideos] = useState(true);

  // Fetch videos when source changes
  useEffect(() => {
    if (selectedVideoSourceId && activeTab === 'video') {
      fetchVideos();
    }
  }, [selectedVideoSourceId, videoSource]);

  const fetchVideos = async () => {
    if (!selectedVideoSourceId || !clientId) return;

    setLoadingVideos(true);
    setVideos([]);
    setSelectedVideos([]);

    try {
      const { data, error } = await supabase.functions.invoke('fetch-meta-videos', {
        body: {
          clientId,
          source: videoSource,
          sourceId: selectedVideoSourceId,
          limit: 50,
        },
      });

      if (error) throw error;
      if (!data.success) throw new Error(data.error);

      setVideos(data.videos || []);
      // Default to all videos selected
      if (selectAllVideos) {
        setSelectedVideos((data.videos || []).map((v: VideoItem) => v.id));
      }
    } catch (error: unknown) {
      console.error('Error fetching videos:', error);
    } finally {
      setLoadingVideos(false);
    }
  };

  const toggleVideoSelection = (videoId: string) => {
    setSelectAllVideos(false);
    setSelectedVideos(prev => 
      prev.includes(videoId) 
        ? prev.filter(id => id !== videoId)
        : [...prev, videoId]
    );
  };

  const handleSelectAllVideos = (checked: boolean) => {
    setSelectAllVideos(checked);
    if (checked) {
      setSelectedVideos(videos.map(v => v.id));
    } else {
      setSelectedVideos([]);
    }
  };

  const resetForm = () => {
    setWebsiteName("");
    setSelectedPixel("");
    setWebsiteRetention([30]);
    setRuleType('all_visitors');
    setUrlValue("");
    setEventName("");
    setPageName("");
    setSelectedPage("");
    setPageRetention([30]);
    setPageEvent("page_engaged");
    setIgName("");
    setSelectedInstagram("");
    setIgRetention([30]);
    setIgEvent("ig_business_profile_all");
    setVideoName("");
    setVideoSource('facebook');
    setSelectedVideoSourceId("");
    setVideoRetention([30]);
    setVideoPercentile(50);
    setVideos([]);
    setSelectedVideos([]);
    setSelectAllVideos(true);
  };

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      resetForm();
    }
    onOpenChange(open);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      if (activeTab === "website") {
        if (!websiteName.trim() || !selectedPixel) return;
        await onCreateWebsiteAudience({
          name: websiteName.trim(),
          pixelId: selectedPixel,
          retentionDays: websiteRetention[0],
          ruleType,
          urlValue: urlValue.trim() || undefined,
          eventName: eventName || undefined,
        });
      } else if (activeTab === "page") {
        if (!pageName.trim() || !selectedPage) return;
        await onCreateEngagementAudience({
          name: pageName.trim(),
          engagementType: 'page',
          sourceId: selectedPage,
          retentionDays: pageRetention[0],
          engagementEvent: pageEvent,
        });
      } else if (activeTab === "instagram") {
        if (!igName.trim() || !selectedInstagram) return;
        await onCreateEngagementAudience({
          name: igName.trim(),
          engagementType: 'instagram',
          sourceId: selectedInstagram,
          retentionDays: igRetention[0],
          engagementEvent: igEvent,
        });
      } else if (activeTab === "video") {
        if (!videoName.trim() || !selectedVideoSourceId) return;
        await onCreateEngagementAudience({
          name: videoName.trim(),
          engagementType: 'video',
          sourceId: selectedVideoSourceId,
          retentionDays: videoRetention[0],
          engagementEvent: 'video_watched',
          videoPercentile,
          videoIds: selectAllVideos ? undefined : selectedVideos,
        });
      }
      resetForm();
    } catch (error) {
      console.error('Error creating advanced audience:', error);
    }
  };

  const isFormValid = () => {
    if (activeTab === "website") {
      if (!websiteName.trim() || !selectedPixel) return false;
      if ((ruleType === 'url_contains' || ruleType === 'url_equals') && !urlValue.trim()) return false;
      if (ruleType === 'event' && !eventName) return false;
      return true;
    }
    if (activeTab === "page") {
      return pageName.trim() && selectedPage;
    }
    if (activeTab === "instagram") {
      return igName.trim() && selectedInstagram;
    }
    if (activeTab === "video") {
      if (!videoName.trim() || !selectedVideoSourceId) return false;
      if (!selectAllVideos && selectedVideos.length === 0) return false;
      return true;
    }
    return false;
  };

  const formatVideoLength = (seconds?: number) => {
    if (!seconds) return '';
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-[850px] max-h-[90vh] overflow-y-auto overflow-x-hidden">
        <DialogHeader>
          <DialogTitle>Criar Público Avançado</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit}>
          <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            <TabsList className="grid grid-cols-4 w-full">
              <TabsTrigger value="website" className="flex items-center gap-1.5">
                <Globe className="h-4 w-4" />
                <span className="hidden sm:inline">Website</span>
              </TabsTrigger>
              <TabsTrigger value="page" className="flex items-center gap-1.5">
                <Facebook className="h-4 w-4" />
                <span className="hidden sm:inline">Página</span>
              </TabsTrigger>
              <TabsTrigger value="instagram" className="flex items-center gap-1.5">
                <Instagram className="h-4 w-4" />
                <span className="hidden sm:inline">Instagram</span>
              </TabsTrigger>
              <TabsTrigger value="video" className="flex items-center gap-1.5">
                <Video className="h-4 w-4" />
                <span className="hidden sm:inline">Vídeo</span>
              </TabsTrigger>
            </TabsList>

            {/* Website Tab */}
            <TabsContent value="website" className="space-y-4 mt-4">
              <div className="space-y-2">
                <Label htmlFor="website-name">Nome do Público *</Label>
                <Input
                  id="website-name"
                  value={websiteName}
                  onChange={(e) => setWebsiteName(e.target.value)}
                  placeholder="Ex: Visitantes Site 30 dias"
                  disabled={loading}
                />
              </div>

              <div className="space-y-2">
                <Label>Pixel do Meta *</Label>
                <Select value={selectedPixel} onValueChange={setSelectedPixel} disabled={loading}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione um Pixel" />
                  </SelectTrigger>
                  <SelectContent>
                    {pixels.length === 0 ? (
                      <SelectItem value="none" disabled>Nenhum Pixel disponível</SelectItem>
                    ) : (
                      pixels.map((pixel) => (
                        <SelectItem key={pixel.id} value={pixel.pixel_id}>
                          {pixel.pixel_name}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Tipo de Regra</Label>
                <Select value={ruleType} onValueChange={(v) => setRuleType(v as unknown)} disabled={loading}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all_visitors">Todos os visitantes</SelectItem>
                    <SelectItem value="url_contains">URL contém</SelectItem>
                    <SelectItem value="url_equals">URL igual a</SelectItem>
                    <SelectItem value="event">Evento específico</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {(ruleType === 'url_contains' || ruleType === 'url_equals') && (
                <div className="space-y-2">
                  <Label htmlFor="url-value">
                    {ruleType === 'url_contains' ? 'URL contém' : 'URL igual a'} *
                  </Label>
                  <Input
                    id="url-value"
                    value={urlValue}
                    onChange={(e) => setUrlValue(e.target.value)}
                    placeholder={ruleType === 'url_contains' ? "Ex: /produtos" : "Ex: https://site.com/checkout"}
                    disabled={loading}
                  />
                </div>
              )}

              {ruleType === 'event' && (
                <div className="space-y-2">
                  <Label>Evento do Pixel *</Label>
                  <Select value={eventName} onValueChange={setEventName} disabled={loading}>
                    <SelectTrigger>
                      <SelectValue placeholder="Selecione um evento" />
                    </SelectTrigger>
                    <SelectContent>
                      {WEBSITE_EVENTS.map((event) => (
                        <SelectItem key={event.value} value={event.value}>
                          {event.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}

              <div className="space-y-3">
                <Label>Período de retenção: {websiteRetention[0]} dias</Label>
                <Slider
                  value={websiteRetention}
                  onValueChange={setWebsiteRetention}
                  min={1}
                  max={180}
                  step={1}
                  disabled={loading}
                />
                <p className="text-xs text-muted-foreground">
                  Pessoas que visitaram nos últimos {websiteRetention[0]} dias
                </p>
              </div>

              <div className="text-sm text-muted-foreground bg-muted p-3 rounded-md">
                <p className="font-medium mb-1">Público de Website</p>
                <p>
                  Captura visitantes do seu site baseado no Meta Pixel instalado.
                  O público será populado automaticamente com dados históricos.
                </p>
              </div>
            </TabsContent>

            {/* Facebook Page Tab */}
            <TabsContent value="page" className="space-y-4 mt-4">
              <div className="space-y-2">
                <Label htmlFor="page-name">Nome do Público *</Label>
                <Input
                  id="page-name"
                  value={pageName}
                  onChange={(e) => setPageName(e.target.value)}
                  placeholder="Ex: Engajados Página Facebook"
                  disabled={loading}
                />
              </div>

              <div className="space-y-2">
                <Label>Página do Facebook *</Label>
                <Select value={selectedPage} onValueChange={setSelectedPage} disabled={loading}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione uma página" />
                  </SelectTrigger>
                  <SelectContent>
                    {pages.length === 0 ? (
                      <SelectItem value="none" disabled>Nenhuma página vinculada</SelectItem>
                    ) : (
                      pages.map((page) => (
                        <SelectItem key={page.id} value={page.page_id}>
                          {page.name}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Tipo de Engajamento</Label>
                <Select value={pageEvent} onValueChange={setPageEvent} disabled={loading}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {PAGE_EVENTS.map((event) => (
                      <SelectItem key={event.value} value={event.value}>
                        {event.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-3">
                <Label>Período de retenção: {pageRetention[0]} dias</Label>
                <Slider
                  value={pageRetention}
                  onValueChange={setPageRetention}
                  min={1}
                  max={365}
                  step={1}
                  disabled={loading}
                />
                <p className="text-xs text-muted-foreground">
                  Pessoas que interagiram nos últimos {pageRetention[0]} dias
                </p>
              </div>

              <div className="text-sm text-muted-foreground bg-muted p-3 rounded-md">
                <p className="font-medium mb-1">Público de Página Facebook</p>
                <p>
                  Captura pessoas que interagiram com sua página do Facebook.
                  Inclui curtidas, comentários, compartilhamentos e mensagens.
                </p>
              </div>
            </TabsContent>

            {/* Instagram Tab */}
            <TabsContent value="instagram" className="space-y-4 mt-4">
              <div className="space-y-2">
                <Label htmlFor="ig-name">Nome do Público *</Label>
                <Input
                  id="ig-name"
                  value={igName}
                  onChange={(e) => setIgName(e.target.value)}
                  placeholder="Ex: Engajados Instagram"
                  disabled={loading}
                />
              </div>

              <div className="space-y-2">
                <Label>Conta do Instagram *</Label>
                <Select value={selectedInstagram} onValueChange={setSelectedInstagram} disabled={loading}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione uma conta" />
                  </SelectTrigger>
                  <SelectContent>
                    {instagramAccounts.length === 0 ? (
                      <SelectItem value="none" disabled>Nenhuma conta vinculada</SelectItem>
                    ) : (
                      instagramAccounts.map((ig) => (
                        <SelectItem key={ig.id} value={ig.instagram_id}>
                          @{ig.username}
                        </SelectItem>
                      ))
                    )}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Tipo de Interação</Label>
                <Select value={igEvent} onValueChange={setIgEvent} disabled={loading}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {INSTAGRAM_EVENTS.map((event) => (
                      <SelectItem key={event.value} value={event.value}>
                        {event.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-3">
                <Label>Período de retenção: {igRetention[0]} dias</Label>
                <Slider
                  value={igRetention}
                  onValueChange={setIgRetention}
                  min={1}
                  max={365}
                  step={1}
                  disabled={loading}
                />
                <p className="text-xs text-muted-foreground">
                  Pessoas que interagiram nos últimos {igRetention[0]} dias
                </p>
              </div>

              <div className="text-sm text-muted-foreground bg-muted p-3 rounded-md">
                <p className="font-medium mb-1">Público de Instagram</p>
                <p>
                  Captura pessoas que visitaram ou interagiram com seu perfil do Instagram Business.
                </p>
              </div>
            </TabsContent>

            {/* Video Tab */}
            <TabsContent value="video" className="space-y-4 mt-4">
              <div className="space-y-2">
                <Label htmlFor="video-name">Nome do Público *</Label>
                <Input
                  id="video-name"
                  value={videoName}
                  onChange={(e) => setVideoName(e.target.value)}
                  placeholder="Ex: Assistiram 75% dos vídeos"
                  disabled={loading}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Origem dos Vídeos</Label>
                  <Select 
                    value={videoSource} 
                    onValueChange={(v) => {
                      setVideoSource(v as 'facebook' | 'instagram');
                      setSelectedVideoSourceId("");
                      setVideos([]);
                      setSelectedVideos([]);
                    }} 
                    disabled={loading}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="facebook">
                        <div className="flex items-center gap-2">
                          <Facebook className="h-4 w-4" />
                          Facebook
                        </div>
                      </SelectItem>
                      <SelectItem value="instagram">
                        <div className="flex items-center gap-2">
                          <Instagram className="h-4 w-4" />
                          Instagram
                        </div>
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label>{videoSource === 'facebook' ? 'Página' : 'Conta'} *</Label>
                  <Select 
                    value={selectedVideoSourceId} 
                    onValueChange={setSelectedVideoSourceId} 
                    disabled={loading}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder={`Selecione ${videoSource === 'facebook' ? 'a página' : 'a conta'}`} />
                    </SelectTrigger>
                    <SelectContent>
                      {videoSource === 'facebook' ? (
                        pages.length === 0 ? (
                          <SelectItem value="none" disabled>Nenhuma página vinculada</SelectItem>
                        ) : (
                          pages.map((page) => (
                            <SelectItem key={page.id} value={page.page_id}>
                              {page.name}
                            </SelectItem>
                          ))
                        )
                      ) : (
                        instagramAccounts.length === 0 ? (
                          <SelectItem value="none" disabled>Nenhuma conta vinculada</SelectItem>
                        ) : (
                          instagramAccounts.map((ig) => (
                            <SelectItem key={ig.id} value={ig.instagram_id}>
                              @{ig.username}
                            </SelectItem>
                          ))
                        )
                      )}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              {selectedVideoSourceId && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <Label>Selecionar Vídeos</Label>
                    <Button 
                      type="button" 
                      variant="ghost" 
                      size="sm" 
                      onClick={fetchVideos}
                      disabled={loadingVideos}
                    >
                      <RefreshCw className={`h-4 w-4 mr-1 ${loadingVideos ? 'animate-spin' : ''}`} />
                      Atualizar
                    </Button>
                  </div>

                  {loadingVideos ? (
                    <div className="flex items-center justify-center py-8">
                      <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
                      <span className="ml-2 text-muted-foreground">Carregando vídeos...</span>
                    </div>
                  ) : videos.length === 0 ? (
                    <div className="text-center py-8 text-muted-foreground border rounded-md">
                      <Video className="h-8 w-8 mx-auto mb-2 opacity-50" />
                      <p>Nenhum vídeo encontrado</p>
                    </div>
                  ) : (
                    <>
                      <div className="flex items-center gap-2 p-2 bg-muted rounded-md">
                        <Checkbox
                          id="select-all"
                          checked={selectAllVideos}
                          onCheckedChange={handleSelectAllVideos}
                        />
                        <label htmlFor="select-all" className="text-sm font-medium cursor-pointer">
                          Todos os vídeos ({videos.length})
                        </label>
                      </div>

                      <ScrollArea className="h-[200px] border rounded-md">
                        <div className="p-2 space-y-2">
                          {videos.map((video) => (
                            <div 
                              key={video.id}
                              className={`flex items-center gap-3 p-2 rounded-md cursor-pointer transition-colors ${
                                selectedVideos.includes(video.id) || selectAllVideos
                                  ? 'bg-primary/10 border border-primary/30' 
                                  : 'hover:bg-muted border border-transparent'
                              }`}
                              onClick={() => toggleVideoSelection(video.id)}
                            >
                              <div className="relative w-16 h-10 bg-muted rounded overflow-hidden flex-shrink-0">
                                {video.thumbnail_url ? (
                                  <img 
                                    src={video.thumbnail_url} 
                                    alt={video.title}
                                    className="w-full h-full object-cover"
                                  />
                                ) : (
                                  <div className="w-full h-full flex items-center justify-center">
                                    <Play className="h-4 w-4 text-muted-foreground" />
                                  </div>
                                )}
                                {(selectedVideos.includes(video.id) || selectAllVideos) && (
                                  <div className="absolute inset-0 bg-primary/50 flex items-center justify-center">
                                    <Check className="h-4 w-4 text-primary-foreground" />
                                  </div>
                                )}
                              </div>
                              <div className="flex-1 min-w-0 overflow-hidden">
                                <p className="text-sm font-medium truncate">{video.title}</p>
                                <div className="flex items-center gap-2 text-xs text-muted-foreground flex-wrap">
                                  {video.length && <span>{formatVideoLength(video.length)}</span>}
                                  {video.views !== undefined && <span>{video.views.toLocaleString()} views</span>}
                                  <span className="truncate">{formatDistanceToNow(new Date(video.created_time), { addSuffix: true, locale: ptBR })}</span>
                                </div>
                              </div>
                            </div>
                          ))}
                        </div>
                      </ScrollArea>

                      {!selectAllVideos && (
                        <p className="text-xs text-muted-foreground">
                          {selectedVideos.length} de {videos.length} vídeos selecionados
                        </p>
                      )}
                    </>
                  )}
                </div>
              )}

              <div className="space-y-2">
                <Label>Percentual Mínimo Assistido</Label>
                <Select 
                  value={videoPercentile.toString()} 
                  onValueChange={(v) => setVideoPercentile(parseInt(v))} 
                  disabled={loading}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {VIDEO_PERCENTILES.map((p) => (
                      <SelectItem key={p.value} value={p.value.toString()}>
                        {p.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-3">
                <Label>Período de retenção: {videoRetention[0]} dias</Label>
                <Slider
                  value={videoRetention}
                  onValueChange={setVideoRetention}
                  min={1}
                  max={365}
                  step={1}
                  disabled={loading}
                />
                <p className="text-xs text-muted-foreground">
                  Pessoas que assistiram nos últimos {videoRetention[0]} dias
                </p>
              </div>

              <div className="text-sm text-muted-foreground bg-muted p-3 rounded-md">
                <p className="font-medium mb-1">Público de Vídeo</p>
                <p>
                  Captura pessoas que assistiram um percentual mínimo dos vídeos selecionados.
                  {selectAllVideos ? ' Inclui todos os vídeos.' : ` ${selectedVideos.length} vídeo(s) selecionado(s).`}
                </p>
              </div>
            </TabsContent>
          </Tabs>

          <DialogFooter className="mt-6">
            <Button
              type="button"
              variant="outline"
              onClick={() => handleOpenChange(false)}
              disabled={loading}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={loading || !isFormValid()}>
              {loading && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Criar Público
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

