interface AdEditContentProps {
  node: TreeNode;
  parentNode?: TreeNode | null;
  clientId: string;
  companyId?: string;
  onSuccess?: () => Promise<void> | void;
}

export function AdEditContent({
  node,
  parentNode,
  clientId,
  companyId,
  onSuccess,
}: AdEditContentProps) {
  const saveProgress = useSaveWithProgress();
  const [hasChanges, setHasChanges] = useState(false);
  const [creativeChanged, setCreativeChanged] = useState(false);

  // Basic fields
  const [editName, setEditName] = useState('');
  const [editStatus, setEditStatus] = useState<'active' | 'paused'>('active');

  // Creative fields
  const [creativeType, setCreativeType] = useState<'IMAGE' | 'VIDEO' | 'CAROUSEL'>('IMAGE');
  const [mediaUrls, setMediaUrls] = useState<string[]>([]);
  const [videoThumbnailUrl, setVideoThumbnailUrl] = useState<string>('');
  const [externalVideoUrl, setExternalVideoUrl] = useState<string>('');
  const [body, setBody] = useState('');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [linkUrl, setLinkUrl] = useState('');
  const [callToAction, setCallToAction] = useState('LEARN_MORE');

  // UTM parameters
  const [utmSource, setUtmSource] = useState('');
  const [utmMedium, setUtmMedium] = useState('');
  const [utmCampaign, setUtmCampaign] = useState('');
  const [utmContent, setUtmContent] = useState('');
  const [utmTerm, setUtmTerm] = useState('');
  const [utmFullString, setUtmFullString] = useState('');
  const [showUtmFields, setShowUtmFields] = useState(false);

  // Pixel tracking
  const [pixelId, setPixelId] = useState('');
  const [parentPixelName, setParentPixelName] = useState<string | null>(null);

  // Original values for comparison
  const [originalValues, setOriginalValues] = useState<unknown>(null);

  // Build full UTM string from individual fields
  const buildUtmString = () => {
    const params: string[] = [];
    if (utmSource) params.push(`utm_source=${utmSource}`);
    if (utmMedium) params.push(`utm_medium=${utmMedium}`);
    if (utmCampaign) params.push(`utm_campaign=${utmCampaign}`);
    if (utmContent) params.push(`utm_content=${utmContent}`);
    if (utmTerm) params.push(`utm_term=${utmTerm}`);
    return params.join('&');
  };

  // Parse full UTM string to individual fields
  const parseUtmString = (fullString: string) => {
    const params = new URLSearchParams(fullString);
    setUtmSource(params.get('utm_source') || '');
    setUtmMedium(params.get('utm_medium') || '');
    setUtmCampaign(params.get('utm_campaign') || '');
    setUtmContent(params.get('utm_content') || '');
    setUtmTerm(params.get('utm_term') || '');
  };

  // Sync individual fields to full string
  useEffect(() => {
    const built = buildUtmString();
    if (built !== utmFullString) {
      setUtmFullString(built);
    }
  }, [utmSource, utmMedium, utmCampaign, utmContent, utmTerm]);

  // Reset form when node changes
  useEffect(() => {
    if (node && node.type === 'ad') {
      const nodeAny = node as unknown;

      setEditName(node.name);
      setEditStatus(node.status === 'active' ? 'active' : 'paused');

      const nodeCreativeType = nodeAny.creativeType?.toUpperCase() || 'IMAGE';
      setCreativeType(nodeCreativeType as 'IMAGE' | 'VIDEO' | 'CAROUSEL');

      const isVideo = nodeCreativeType === 'VIDEO';
      if (isVideo && nodeAny.videoUrl) {
        setMediaUrls([nodeAny.videoUrl]);
        setVideoThumbnailUrl(nodeAny.imageUrl || '');
        if (nodeAny.videoUrl.includes('facebook.com/') || nodeAny.videoUrl.includes('fb.com/')) {
          setExternalVideoUrl(nodeAny.videoUrl);
        } else {
          setExternalVideoUrl('');
        }
      } else if (nodeAny.imageUrl) {
        setMediaUrls([nodeAny.imageUrl]);
        setVideoThumbnailUrl('');
        setExternalVideoUrl('');
      } else if (nodeAny.creativeUrl) {
        setMediaUrls([nodeAny.creativeUrl]);
        setVideoThumbnailUrl('');
        setExternalVideoUrl('');
      } else {
        setMediaUrls([]);
        setVideoThumbnailUrl('');
        setExternalVideoUrl('');
      }

      setBody(nodeAny.creativeBody || '');
      setTitle(nodeAny.creativeTitle || '');
      setDescription(nodeAny.creativeDescription || '');
      setLinkUrl(nodeAny.linkUrl || '');
      setCallToAction(nodeAny.callToAction || 'LEARN_MORE');

      setPixelId(nodeAny.pixelId || '');

      if (nodeAny.linkUrl) {
        try {
          const url = new URL(nodeAny.linkUrl);
          setUtmSource(url.searchParams.get('utm_source') || '');
          setUtmMedium(url.searchParams.get('utm_medium') || '');
          setUtmCampaign(url.searchParams.get('utm_campaign') || '');
          setUtmContent(url.searchParams.get('utm_content') || '');
          setUtmTerm(url.searchParams.get('utm_term') || '');

          if (url.searchParams.has('utm_source') || url.searchParams.has('utm_medium')) {
            setShowUtmFields(true);
          }
        } catch {
          // Invalid URL, ignore
        }
      }

      const origMediaUrls = isVideo && nodeAny.videoUrl 
        ? [nodeAny.videoUrl] 
        : (nodeAny.imageUrl ? [nodeAny.imageUrl] : (nodeAny.creativeUrl ? [nodeAny.creativeUrl] : []));

      setOriginalValues({
        name: node.name,
        status: node.status,
        creativeType: nodeCreativeType,
        mediaUrls: origMediaUrls,
        body: nodeAny.creativeBody || '',
        title: nodeAny.creativeTitle || '',
        description: nodeAny.creativeDescription || '',
        linkUrl: nodeAny.linkUrl || '',
        callToAction: nodeAny.callToAction || 'LEARN_MORE',
      });

      setHasChanges(false);
      setCreativeChanged(false);
    }
  }, [node?.id]);

  // Fetch parent pixel name from meta_pixels table
  useEffect(() => {
    const fetchParentPixelName = async () => {
      if (!parentNode?.pixelId || !clientId) {
        setParentPixelName(null);
        return;
      }

      try {
        const { data, error } = await supabase
          .from('meta_pixels')
          .select('pixel_name')
          .eq('client_id', clientId)
          .eq('pixel_id', parentNode.pixelId)
          .maybeSingle();

        if (!error && data) {
          setParentPixelName(data.pixel_name);
        } else {
          setParentPixelName(null);
        }
      } catch (err) {
        console.error('Error fetching pixel name:', err);
        setParentPixelName(null);
      }
    };

    fetchParentPixelName();
  }, [parentNode?.pixelId, clientId]);

  // Track changes
  useEffect(() => {
    if (!originalValues) return;

    const nameChanged = editName !== originalValues.name;
    const statusChanged = editStatus !== (originalValues.status === 'active' ? 'active' : 'paused');

    const creativeTypeChanged = creativeType !== originalValues.creativeType;
    const mediaChanged = JSON.stringify(mediaUrls) !== JSON.stringify(originalValues.mediaUrls);
    const bodyChanged = body !== originalValues.body;
    const titleChanged = title !== originalValues.title;
    const descriptionChanged = description !== originalValues.description;
    const linkChanged = linkUrl !== originalValues.linkUrl;
    const ctaChanged = callToAction !== originalValues.callToAction;

    const isCreativeChanged = creativeTypeChanged || mediaChanged || bodyChanged || 
                              titleChanged || descriptionChanged || linkChanged || ctaChanged;

    setCreativeChanged(isCreativeChanged);
    setHasChanges(nameChanged || statusChanged || isCreativeChanged);
  }, [editName, editStatus, creativeType, mediaUrls, body, title, description, linkUrl, callToAction, originalValues]);

  const handleSave = useCallback(async () => {
    if (!clientId || !node) return;

    if (!editName.trim()) {
      toast.error('O nome do anúncio não pode estar vazio');
      return;
    }
    if (mediaUrls.length === 0) {
      toast.error('É necessário ter pelo menos uma mídia');
      return;
    }
    if (!body.trim()) {
      toast.error('O texto principal é obrigatório');
      return;
    }
    if (linkUrl && !linkUrl.match(/^https?:\/\//)) {
      toast.error('A URL de destino deve começar com http:// ou https://');
      return;
    }

    const platform = node.platform as 'meta' | 'google';
    const facebookId = (node as unknown).facebookId;

    const metaAction = async () => {
      let finalUrl = linkUrl;
      if (linkUrl) {
        const utmParams: string[] = [];
        if (utmSource) utmParams.push(`utm_source=${encodeURIComponent(utmSource)}`);
        if (utmMedium) utmParams.push(`utm_medium=${encodeURIComponent(utmMedium)}`);
        if (utmCampaign) utmParams.push(`utm_campaign=${encodeURIComponent(utmCampaign)}`);
        if (utmContent) utmParams.push(`utm_content=${encodeURIComponent(utmContent)}`);
        if (utmTerm) utmParams.push(`utm_term=${encodeURIComponent(utmTerm)}`);

        if (utmParams.length > 0) {
          const baseUrl = linkUrl.split('?')[0];
          const existingParams = linkUrl.includes('?') ? linkUrl.split('?')[1] : '';
          const cleanedParams = existingParams
            .split('&')
            .filter(p => !p.startsWith('utm_'))
            .join('&');

          const allParams = cleanedParams 
            ? `${cleanedParams}&${utmParams.join('&')}` 
            : utmParams.join('&');
          finalUrl = `${baseUrl}?${allParams}`;
        }
      }

      if (platform === 'meta' && facebookId) {
        const pixelChanged = pixelId !== (node as unknown).pixelId;

        const { data, error } = await supabase.functions.invoke('update-meta-ad', {
          body: {
            clientId,
            adId: node.id,
            facebookId,
            updates: {
              name: editName !== originalValues?.name ? editName : undefined,
              status: editStatus !== (originalValues?.status === 'active' ? 'active' : 'paused')
                ? (editStatus === 'active' ? 'ACTIVE' : 'PAUSED')
                : undefined,
              creative: creativeChanged ? {
                type: creativeType,
                media_urls: mediaUrls,
                body,
                title,
                description,
                link_url: finalUrl,
                call_to_action: callToAction,
              } : undefined,
              pixel_id: pixelChanged ? pixelId : undefined,
            },
          },
        });

        if (error) throw error;

        if (!data?.success) {
          throw new Error(data?.error || 'Erro ao atualizar anúncio');
        }
      } else {
        const { error: updateError } = await supabase
          .from('ads')
          .update({
            name: editName,
            status: editStatus,
            is_active: editStatus === 'active',
            creative_type: creativeType,
            creative_body: body,
            creative_title: title,
            creative_description: description,
            link_url: finalUrl,
            call_to_action: callToAction,
            image_url: creativeType !== 'VIDEO' ? mediaUrls[0] : null,
            video_url: creativeType === 'VIDEO' ? mediaUrls[0] : null,
            pixel_id: pixelId || null,
            updated_at: new Date().toISOString(),
          })
          .eq('id', node.id);

        if (updateError) throw updateError;
      }
    };

    const success = await saveProgress.execute(metaAction, async () => {
      setHasChanges(false);
      setCreativeChanged(false);
      if (onSuccess) {
        await onSuccess();
      }
    });

    if (success) {
      toast.success('Anúncio atualizado com sucesso!');
    }
  }, [clientId, node, editName, editStatus, creativeType, mediaUrls, body, title, description, linkUrl, callToAction, utmSource, utmMedium, utmCampaign, utmContent, utmTerm, pixelId, originalValues, creativeChanged, onSuccess, saveProgress]);

  if (!node || node.type !== 'ad') return null;

  const isGoogle = node.platform === 'google';
  const formatCurrency = (value: number) => `R$ ${value.toFixed(2)}`;
  const formatNumber = (value: number) => value.toLocaleString();
  const formatPercent = (value: number) => `${value.toFixed(2)}%`;

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="p-6 pb-4">
        <div className="flex items-center gap-3">
          <ImageIcon className="w-6 h-6 text-primary" />
          <div className="flex-1">
            <h2 className="text-xl font-semibold">Anúncio</h2>
            <div className="flex items-center gap-2 mt-1">
              <Badge variant="outline">{node.platform.toUpperCase()}</Badge>
            </div>
          </div>
          {/* Status Toggle */}
          <div className="flex items-center gap-3">
            <span className="text-sm text-muted-foreground">
              {editStatus === 'active' ? 'Ativo' : 'Pausado'}
            </span>
            <Switch
              checked={editStatus === 'active'}
              onCheckedChange={(checked) => setEditStatus(checked ? 'active' : 'paused')}
              className="data-[state=checked]:bg-green-500"
            />
          </div>
        </div>
      </div>

      <Separator />

      <ScrollArea className="flex-1">
        <div className="p-6 space-y-6">
          {/* Alerts */}
          {isGoogle && (
            <Alert>
              <AlertTriangle className="h-4 w-4" />
              <AlertDescription>
                Google Ads: alterações serão salvas apenas localmente.
              </AlertDescription>
            </Alert>
          )}

          {/* Metrics Cards at Top */}
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-8 gap-2">
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <DollarSign className="w-3 h-3" />
                <span className="text-xs">Investido</span>
              </div>
              <p className="text-sm font-bold">{formatCurrency(node.metrics.spend)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Eye className="w-3 h-3" />
                <span className="text-xs">Impressões</span>
              </div>
              <p className="text-sm font-bold">{formatNumber(node.metrics.impressions)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <MousePointerClick className="w-3 h-3" />
                <span className="text-xs">Cliques</span>
              </div>
              <p className="text-sm font-bold">{formatNumber(node.metrics.clicks || 0)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Percent className="w-3 h-3" />
                <span className="text-xs">CTR</span>
              </div>
              <p className="text-sm font-bold">{formatPercent(node.metrics.ctr)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Target className="w-3 h-3" />
                <span className="text-xs">Conversões</span>
              </div>
              <p className="text-sm font-bold">{formatNumber(node.metrics.conversions)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Receipt className="w-3 h-3" />
                <span className="text-xs">CPA</span>
              </div>
              <p className="text-sm font-bold">{formatCurrency(node.metrics.cpa || 0)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Coins className="w-3 h-3" />
                <span className="text-xs">CPC</span>
              </div>
              <p className="text-sm font-bold">{formatCurrency(node.metrics.cpc || 0)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Users className="w-3 h-3" />
                <span className="text-xs">Alcance</span>
              </div>
              <p className="text-sm font-bold">{formatNumber(node.metrics.reach || 0)}</p>
            </div>
          </div>

          {/* Two Column Layout */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Left Column - Configuration & Texts */}
            <div className="space-y-6">
              <div>
                <h4 className="font-medium text-sm mb-4 flex items-center gap-2">
                  <Settings className="w-4 h-4" />
                  Configurações
                </h4>

                {/* Name Field */}
                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label>Nome do Anúncio *</Label>
                    <Input
                      value={editName}
                      onChange={(e) => setEditName(e.target.value)}
                      placeholder="Ex: Anúncio Principal - Produto A"
                    />
                    {editName.trim() === '' && (
                      <p className="text-xs text-destructive">O nome não pode estar vazio</p>
                    )}
                  </div>
                </div>
              </div>

              {/* Texts Section */}
              <div className="border-t pt-4">
                <h4 className="font-medium text-sm mb-4">Textos do Anúncio</h4>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label>Texto Principal *</Label>
                    <Textarea
                      value={body}
                      onChange={(e) => setBody(e.target.value)}
                      placeholder="Texto principal do anúncio que aparece acima da mídia"
                      rows={4}
                    />
                    <p className="text-xs text-muted-foreground">{body.length}/500 caracteres</p>
                  </div>

                  <div className="space-y-2">
                    <Label>Título</Label>
                    <Input
                      value={title}
                      onChange={(e) => setTitle(e.target.value)}
                      placeholder="Título do anúncio (headline)"
                    />
                  </div>

                  <div className="space-y-2">
                    <Label>Descrição</Label>
                    <Textarea
                      value={description}
                      onChange={(e) => setDescription(e.target.value)}
                      placeholder="Descrição complementar do anúncio"
                      rows={3}
                    />
                    <p className="text-xs text-muted-foreground">{description.length}/300 caracteres</p>
                  </div>
                </div>
              </div>

              {/* Destination Section */}
              <div className="border-t pt-4">
                <h4 className="font-medium text-sm mb-4 flex items-center gap-2">
                  <Link2 className="w-4 h-4" />
                  Destino
                </h4>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label>URL de Destino</Label>
                    <Input
                      type="url"
                      value={linkUrl}
                      onChange={(e) => setLinkUrl(e.target.value)}
                      placeholder="https://seusite.com/pagina"
                    />
                    {linkUrl && !linkUrl.match(/^https?:\/\//) && (
                      <p className="text-xs text-destructive">URL deve começar com http:// ou https://</p>
                    )}
                  </div>

                  <div className="space-y-2">
                    <Label>Chamada para Ação (CTA)</Label>
                    <Select value={callToAction} onValueChange={setCallToAction}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {CTA_OPTIONS.map((option) => (
                          <SelectItem key={option.value} value={option.value}>
                            {option.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  {/* Pixel Tracking */}
                  <div className="space-y-3">
                    {parentNode?.pixelId && (
                      <div className="space-y-2">
                        <Label className="text-muted-foreground">Pixel do Conjunto (herdado)</Label>
                        <Input
                          value={parentPixelName 
                            ? `${parentPixelName} (${parentNode.pixelId})` 
                            : parentNode.pixelId}
                          disabled
                          className="bg-muted/50 text-muted-foreground"
                        />
                        <p className="text-xs text-muted-foreground">
                          Configurado no Conjunto de Anúncios
                        </p>
                      </div>
                    )}

                    <PixelSelector
                      clientId={clientId}
                      companyId={companyId || ''}
                      value={pixelId}
                      onChange={setPixelId}
                      label={parentNode?.pixelId ? "Pixel do Anúncio (sobrescreve)" : "Pixel de Conversão"}
                    />
                    {parentNode?.pixelId && pixelId && (
                      <p className="text-xs text-warning">
                        Este pixel sobrescreve o pixel herdado do Conjunto
                      </p>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {/* Right Column - Creative/Media */}
            <div className="space-y-6">
              <div>
                <h4 className="font-medium text-sm mb-4 flex items-center gap-2">
                  <ImageIcon className="w-4 h-4" />
                  Criativo
                </h4>

                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label>Tipo de Criativo</Label>
                    <ToggleGroup
                      type="single"
                      value={creativeType}
                      onValueChange={(value) => value && setCreativeType(value as 'IMAGE' | 'VIDEO' | 'CAROUSEL')}
                      className="justify-start"
                    >
                      <ToggleGroupItem value="IMAGE" aria-label="Imagem" className="gap-2">
                        <Image className="h-4 w-4" />
                        Imagem
                      </ToggleGroupItem>
                      <ToggleGroupItem value="VIDEO" aria-label="Vídeo" className="gap-2">
                        <Film className="h-4 w-4" />
                        Vídeo
                      </ToggleGroupItem>
                      <ToggleGroupItem value="CAROUSEL" aria-label="Carrossel" className="gap-2">
                        <Layers className="h-4 w-4" />
                        Carrossel
                      </ToggleGroupItem>
                    </ToggleGroup>
                  </div>

                  <div className="space-y-2">
                    <Label>Mídia *</Label>
                    <MediaUploader
                      mediaUrls={mediaUrls}
                      onChange={setMediaUrls}
                      type={creativeType}
                      maxFiles={creativeType === 'CAROUSEL' ? 10 : 1}
                      clientId={clientId}
                      companyId={companyId}
                      creativeContext={{ title, body, description }}
                      thumbnailUrl={creativeType === 'VIDEO' ? videoThumbnailUrl : undefined}
                      externalVideoUrl={creativeType === 'VIDEO' ? externalVideoUrl : undefined}
                    />
                  </div>
                </div>
              </div>

              {/* UTM Parameters */}
              <Collapsible open={showUtmFields} onOpenChange={setShowUtmFields}>
                <CollapsibleTrigger asChild>
                  <Button variant="ghost" size="sm" className="gap-2 h-8 text-xs">
                    <ChevronDown className={`h-3 w-3 transition-transform ${showUtmFields ? 'rotate-180' : ''}`} />
                    Parâmetros UTM
                    {utmFullString && <Badge variant="secondary" className="ml-2 text-xs">Configurado</Badge>}
                  </Button>
                </CollapsibleTrigger>
                <CollapsibleContent className="space-y-4 pt-3">
                  <div className="space-y-2">
                    <Label className="text-xs font-medium">String Completa (como no Meta)</Label>
                    <Input
                      value={utmFullString}
                      onChange={(e) => {
                        setUtmFullString(e.target.value);
                        parseUtmString(e.target.value);
                      }}
                      placeholder="utm_source={{site_source_name}}&utm_medium={{ad.name}}&utm_campaign={{campaign.name}}"
                      className="h-9 text-sm font-mono"
                    />
                    <p className="text-xs text-muted-foreground">
                      Cole aqui a string completa de parâmetros ou edite os campos individuais abaixo
                    </p>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1">
                      <Label className="text-xs">utm_source</Label>
                      <Input
                        value={utmSource}
                        onChange={(e) => setUtmSource(e.target.value)}
                        placeholder="facebook"
                        className="h-8 text-sm"
                      />
                    </div>
                    <div className="space-y-1">
                      <Label className="text-xs">utm_medium</Label>
                      <Input
                        value={utmMedium}
                        onChange={(e) => setUtmMedium(e.target.value)}
                        placeholder="cpc"
                        className="h-8 text-sm"
                      />
                    </div>
                    <div className="space-y-1">
                      <Label className="text-xs">utm_campaign</Label>
                      <Input
                        value={utmCampaign}
                        onChange={(e) => setUtmCampaign(e.target.value)}
                        placeholder="{{campaign.name}}"
                        className="h-8 text-sm"
                      />
                    </div>
                    <div className="space-y-1">
                      <Label className="text-xs">utm_content</Label>
                      <Input
                        value={utmContent}
                        onChange={(e) => setUtmContent(e.target.value)}
                        placeholder="{{ad.name}}"
                        className="h-8 text-sm"
                      />
                    </div>
                    <div className="space-y-1 col-span-2">
                      <Label className="text-xs">utm_term</Label>
                      <Input
                        value={utmTerm}
                        onChange={(e) => setUtmTerm(e.target.value)}
                        placeholder="{{adset.name}}"
                        className="h-8 text-sm"
                      />
                    </div>
                  </div>
                </CollapsibleContent>
              </Collapsible>
            </div>
          </div>
        </div>
      </ScrollArea>

      <Separator />

      {/* Footer */}
      <div className="p-4 flex justify-end gap-2">
        <Button 
          onClick={handleSave} 
          disabled={saveProgress.isOpen || !hasChanges || editName.trim() === '' || mediaUrls.length === 0}
        >
          <Save className="w-4 h-4 mr-2" />
          Salvar Alterações
        </Button>
      </div>

      {/* Save Progress Modal */}
      <SaveProgressModal
        isOpen={saveProgress.isOpen}
        steps={saveProgress.steps}
        error={saveProgress.error}
        onClose={saveProgress.close}
        onRetry={handleSave}
      />
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Slider } from '@/components/ui/slider';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { 
  Layers, 
  Save, 
  Settings, 
  DollarSign, 
  Eye, 
  Target, 
  Users, 
  AlertTriangle,
  Percent,
  ImageIcon,
  PlayCircle,
  PauseCircle,
} from 'lucide-react';
import { useInlineEdit } from '@/hooks/useInlineEdit';
import { TreeNode } from '@/hooks/useCampaignTree';
import { AudienceMultiSelect } from '@/components/campaigns/builder/AudienceMultiSelect';
import { InterestSelector, Interest } from '@/components/campaigns/builder/InterestSelector';
import { PixelSelector } from '@/components/campaigns/builder/PixelSelector';
import { ConversionEventSelector } from '@/components/campaigns/builder/ConversionEventSelector';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import { useSaveWithProgress } from '@/hooks/useSaveWithProgress';
import { SaveProgressModal } from './SaveProgressModal';

interface AdSetEditContentProps {
  node: TreeNode;
  clientId: string;
  companyId?: string;
  onSuccess?: () => Promise<void> | void;
}

export function AdSetEditContent({
  node,
  clientId,
  companyId,
  onSuccess,
}: AdSetEditContentProps) {
  const saveProgress = useSaveWithProgress();

  // Basic fields
  const [editName, setEditName] = useState('');
  const [editStatus, setEditStatus] = useState<'active' | 'paused'>('active');
  const [editBudget, setEditBudget] = useState('');

  // Targeting fields
  const [includedAudiences, setIncludedAudiences] = useState<string[]>([]);
  const [excludedAudiences, setExcludedAudiences] = useState<string[]>([]);
  const [interests, setInterests] = useState<Interest[]>([]);
  const [ageMin, setAgeMin] = useState(18);
  const [ageMax, setAgeMax] = useState(65);
  const [genders, setGenders] = useState<number[]>([]);

  // Conversion fields
  const [pixelId, setPixelId] = useState('');
  const [conversionEvent, setConversionEvent] = useState('');

  const [hasChanges, setHasChanges] = useState(false);

  const { loading: inlineLoading, updateStatus, updateBudget, updateName } = useInlineEdit({
    onSuccess: () => {
      onSuccess?.();
    },
  });

  // Parse targeting from node
  const parseTargeting = useCallback((targeting: unknown) => {
    if (!targeting) return null;

    try {
      const data = typeof targeting === 'string' ? JSON.parse(targeting) : targeting;
      return data;
    } catch {
      return null;
    }
  }, []);

  // Reset form when node changes
  useEffect(() => {
    if (node) {
      setEditName(node.name);
      setEditStatus(node.status === 'active' ? 'active' : 'paused');
      setEditBudget(node.budget?.amount?.toString() || '50');

      // Parse and set targeting
      const targeting = parseTargeting(node.targeting);
      if (targeting) {
        setAgeMin(targeting.age_min || 18);
        setAgeMax(targeting.age_max || 65);

        if (targeting.genders && targeting.genders.length > 0) {
          setGenders(targeting.genders);
        } else {
          setGenders([]);
        }

        if (targeting.flexible_spec) {
          const parsedInterests: Interest[] = [];
          targeting.flexible_spec.forEach((spec: unknown) => {
            if (spec.interests) {
              spec.interests.forEach((interest: unknown) => {
                parsedInterests.push({
                  id: interest.id,
                  name: interest.name,
                });
              });
            }
          });
          setInterests(parsedInterests);
        } else {
          setInterests([]);
        }

        if (targeting.custom_audiences) {
          setIncludedAudiences(targeting.custom_audiences.map((a: unknown) => a.id || a));
        } else {
          setIncludedAudiences([]);
        }

        if (targeting.excluded_custom_audiences) {
          setExcludedAudiences(targeting.excluded_custom_audiences.map((a: unknown) => a.id || a));
        } else {
          setExcludedAudiences([]);
        }
      } else {
        setAgeMin(18);
        setAgeMax(65);
        setGenders([]);
        setInterests([]);
        setIncludedAudiences([]);
        setExcludedAudiences([]);
      }

      const nodeAny = node as unknown;
      setPixelId(nodeAny.pixelId || '');
      setConversionEvent(nodeAny.conversionEvent || '');
      setHasChanges(false);
    }
  }, [node?.id, parseTargeting]);

  // Track changes
  useEffect(() => {
    if (!node) return;

    const nameChanged = editName !== node.name;
    const currentNodeStatus = node.status === 'active' ? 'active' : 'paused';
    const statusChanged = editStatus !== currentNodeStatus;
    const budgetChanged = node.budget && editBudget !== node.budget.amount.toString();

    setHasChanges(nameChanged || statusChanged || !!budgetChanged || true);
  }, [editName, editStatus, editBudget, includedAudiences, excludedAudiences, interests, ageMin, ageMax, genders, pixelId, conversionEvent, node]);

  const handleSave = useCallback(async () => {
    if (!clientId || !node) return;

    const platform = node.platform as 'meta' | 'google';
    const facebookId = (node as unknown).facebookId;

    const metaAction = async () => {
      if (platform === 'meta' && facebookId) {
        const { data, error } = await supabase.functions.invoke('update-meta-adset', {
          body: {
            clientId,
            adSetId: node.id,
            facebookId,
            updates: {
              name: editName !== node.name ? editName : undefined,
              status: editStatus !== (node.status === 'active' ? 'active' : 'paused') 
                ? (editStatus === 'active' ? 'ACTIVE' : 'PAUSED') 
                : undefined,
              daily_budget: node.budget && editBudget !== node.budget.amount.toString() 
                ? parseFloat(editBudget) * 100
                : undefined,
              targeting: {
                age_min: ageMin,
                age_max: ageMax,
                genders: genders.length > 0 ? genders : undefined,
                custom_audiences: includedAudiences.length > 0 
                  ? includedAudiences.map(id => ({ id })) 
                  : undefined,
                excluded_custom_audiences: excludedAudiences.length > 0 
                  ? excludedAudiences.map(id => ({ id })) 
                  : undefined,
                flexible_spec: interests.length > 0 
                  ? [{ interests: interests.map(i => ({ id: i.id, name: i.name })) }] 
                  : undefined,
                geo_locations: { countries: ['BR'] },
              },
              pixel_id: pixelId || undefined,
              conversion_event: conversionEvent || undefined,
            },
          },
        });

        if (error) throw error;

        if (!data?.success) {
          throw new Error(data?.error || 'Erro ao atualizar conjunto de anúncios');
        }
      } else {
        if (editName !== node.name) {
          await updateName('adset', node.id, clientId, facebookId, editName, platform);
        }
        if (editStatus !== (node.status === 'active' ? 'active' : 'paused')) {
          await updateStatus('adset', node.id, clientId, facebookId, editStatus, platform);
        }
        if (node.budget && editBudget !== node.budget.amount.toString()) {
          const newBudgetValue = parseFloat(editBudget);
          if (!isNaN(newBudgetValue) && newBudgetValue >= 1) {
            await updateBudget('adset', node.id, clientId, facebookId, newBudgetValue, node.budget.type, platform);
          }
        }
      }
    };

    const success = await saveProgress.execute(metaAction, async () => {
      setHasChanges(false);
      if (onSuccess) {
        await onSuccess();
      }
    });

    if (success) {
      toast.success('Conjunto de anúncios atualizado com sucesso!');
    }
  }, [clientId, node, editName, editStatus, editBudget, ageMin, ageMax, genders, includedAudiences, excludedAudiences, interests, pixelId, conversionEvent, updateName, updateStatus, updateBudget, onSuccess, saveProgress]);

  if (!node || node.type !== 'adset') return null;

  const isGoogle = node.platform === 'google';
  const isLoading = saveProgress.isOpen || inlineLoading;
  const formatCurrency = (value: number) => `R$ ${value.toFixed(2)}`;
  const formatNumber = (value: number) => value.toLocaleString();
  const formatPercent = (value: number) => `${value.toFixed(2)}%`;

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="p-6 pb-4">
        <div className="flex items-center gap-3">
          <Layers className="w-6 h-6 text-primary" />
          <div className="flex-1">
            <h2 className="text-xl font-semibold">Conjunto de Anúncios</h2>
            <div className="flex items-center gap-2 mt-1">
              <Badge variant="outline">{node.platform.toUpperCase()}</Badge>
            </div>
          </div>
          {/* Status Toggle */}
          <div className="flex items-center gap-3">
            <span className="text-sm text-muted-foreground">
              {editStatus === 'active' ? 'Ativo' : 'Pausado'}
            </span>
            <Switch
              checked={editStatus === 'active'}
              onCheckedChange={(checked) => setEditStatus(checked ? 'active' : 'paused')}
              className="data-[state=checked]:bg-green-500"
            />
          </div>
        </div>
      </div>

      <Separator />

      <ScrollArea className="flex-1">
        <div className="p-6 space-y-6">
          {/* Google Alert */}
          {isGoogle && (
            <Alert>
              <AlertTriangle className="h-4 w-4" />
              <AlertDescription>
                Google Ads: alterações serão salvas apenas localmente.
              </AlertDescription>
            </Alert>
          )}

          {/* Metrics Cards at Top */}
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-2">
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <DollarSign className="w-3 h-3" />
                <span className="text-xs">Investido</span>
              </div>
              <p className="text-sm font-bold">{formatCurrency(node.metrics.spend)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Eye className="w-3 h-3" />
                <span className="text-xs">Impressões</span>
              </div>
              <p className="text-sm font-bold">{formatNumber(node.metrics.impressions)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Percent className="w-3 h-3" />
                <span className="text-xs">CTR</span>
              </div>
              <p className="text-sm font-bold">{formatPercent(node.metrics.ctr)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Target className="w-3 h-3" />
                <span className="text-xs">Conversões</span>
              </div>
              <p className="text-sm font-bold">{formatNumber(node.metrics.conversions)}</p>
            </div>
            {/* Ads Summary */}
            {node.children && node.children.length > 0 && (
              <>
                <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
                  <div className="flex items-center gap-1 text-muted-foreground mb-1">
                    <ImageIcon className="w-3 h-3" />
                    <span className="text-xs">Anúncios</span>
                  </div>
                  <p className="text-sm font-bold">{node.children.length}</p>
                </div>
                <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
                  <div className="flex items-center gap-1 text-muted-foreground mb-1">
                    <PlayCircle className="w-3 h-3" />
                    <span className="text-xs">Ativos</span>
                  </div>
                  <p className="text-sm font-bold text-primary">
                    {node.children.filter((c) => c.status === 'active').length}
                  </p>
                </div>
                <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
                  <div className="flex items-center gap-1 text-muted-foreground mb-1">
                    <PauseCircle className="w-3 h-3" />
                    <span className="text-xs">Pausados</span>
                  </div>
                  <p className="text-sm font-bold text-muted-foreground">
                    {node.children.filter((c) => c.status === 'paused').length}
                  </p>
                </div>
              </>
            )}
          </div>

          {/* Two Column Layout */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Left Column - Basic Settings & Demographics */}
            <div className="space-y-6">
              {/* Basic Settings Section */}
              <div className="space-y-4">
                <h4 className="font-medium text-sm flex items-center gap-2 text-muted-foreground uppercase tracking-wider">
                  <Settings className="w-4 h-4" />
                  Configurações Básicas
                </h4>

                {/* Name Field */}
                <div className="space-y-2">
                  <Label>Nome do Conjunto *</Label>
                  <Input
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                    placeholder="Ex: Público Lookalike - 18-35"
                  />
                  {editName.trim() === '' && (
                    <p className="text-xs text-destructive">O nome não pode estar vazio</p>
                  )}
                </div>

                {/* Daily Budget */}
                <div className="space-y-2">
                  <Label>Orçamento Diário (R$)</Label>
                  <Input
                    type="number"
                    min={1}
                    value={editBudget}
                    onChange={(e) => setEditBudget(e.target.value)}
                    placeholder="50"
                  />
                  {parseFloat(editBudget) < 1 && editBudget !== '' && (
                    <p className="text-xs text-destructive">O orçamento mínimo é R$ 1,00</p>
                  )}
                </div>
              </div>

              {/* Demographics Section */}
              <div className="space-y-4 border-t pt-4">
                <h4 className="font-medium text-sm flex items-center gap-2 text-muted-foreground uppercase tracking-wider">
                  <Users className="w-4 h-4" />
                  Demografia
                </h4>

                {/* Age Range */}
                <div className="space-y-3">
                  <Label>Faixa Etária: {ageMin} - {ageMax} anos</Label>
                  <div className="px-2">
                    <Slider
                      min={18}
                      max={65}
                      step={1}
                      value={[ageMin, ageMax]}
                      onValueChange={([min, max]) => {
                        setAgeMin(min);
                        setAgeMax(max);
                      }}
                    />
                  </div>
                </div>

                {/* Gender */}
                <div className="space-y-2">
                  <Label>Gênero</Label>
                  <Select
                    value={genders.length === 0 ? 'all' : genders[0].toString()}
                    onValueChange={(v) => {
                      if (v === 'all') {
                        setGenders([]);
                      } else {
                        setGenders([Number(v)]);
                      }
                    }}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">Todos</SelectItem>
                      <SelectItem value="1">Masculino</SelectItem>
                      <SelectItem value="2">Feminino</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              {/* Conversion Section */}
              <div className="space-y-4 border-t pt-4">
                <h4 className="font-medium text-sm flex items-center gap-2 text-muted-foreground uppercase tracking-wider">
                  <Target className="w-4 h-4" />
                  Conversão (opcional)
                </h4>

                <PixelSelector
                  clientId={clientId}
                  companyId={companyId || ''}
                  value={pixelId}
                  onChange={setPixelId}
                />

                <ConversionEventSelector
                  value={conversionEvent}
                  onChange={setConversionEvent}
                  disabled={!pixelId}
                  campaignObjective="OUTCOME_LEADS"
                />
              </div>
            </div>

            {/* Right Column - Targeting */}
            <div className="space-y-6">
              {/* Targeting Section */}
              <div className="space-y-4">
                <h4 className="font-medium text-sm flex items-center gap-2 text-muted-foreground uppercase tracking-wider">
                  <Users className="w-4 h-4" />
                  Segmentação
                </h4>

                {/* Included Audiences */}
                <AudienceMultiSelect
                  clientId={clientId}
                  selectedIds={includedAudiences}
                  onChange={setIncludedAudiences}
                  label="Públicos de Inclusão"
                  placeholder="Selecionar públicos..."
                />

                {/* Excluded Audiences */}
                <AudienceMultiSelect
                  clientId={clientId}
                  selectedIds={excludedAudiences}
                  onChange={setExcludedAudiences}
                  label="Públicos de Exclusão"
                  placeholder="Excluir públicos..."
                />

                {/* Interests */}
                <InterestSelector
                  clientId={clientId}
                  selectedInterests={interests}
                  onChange={setInterests}
                  label="Interesses"
                  placeholder="Buscar interesses..."
                />
              </div>
            </div>
          </div>
        </div>
      </ScrollArea>

      <Separator />

      {/* Footer */}
      <div className="p-4 flex justify-end gap-2">
        <Button 
          onClick={handleSave} 
          disabled={isLoading || editName.trim() === '' || parseFloat(editBudget) < 1}
        >
          <Save className="w-4 h-4 mr-2" />
          Salvar Alterações
        </Button>
      </div>

      {/* Save Progress Modal */}
      <SaveProgressModal
        isOpen={saveProgress.isOpen}
        steps={saveProgress.steps}
        error={saveProgress.error}
        onClose={saveProgress.close}
        onRetry={handleSave}
      />
    </div>
  );
}

import { useEffect, useState, useCallback, useMemo } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { 
  Target, 
  Save, 
  Settings, 
  DollarSign, 
  Eye, 
  Percent,
  Layers,
  PlayCircle,
  PauseCircle,
  AlertTriangle,
  Info,
} from 'lucide-react';
import { TreeNode } from '@/hooks/useCampaignTree';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import { useSaveWithProgress } from '@/hooks/useSaveWithProgress';
import { SaveProgressModal } from './SaveProgressModal';

interface CampaignEditContentProps {
  node: TreeNode;
  clientId: string;
  companyId?: string;
  onSuccess?: () => Promise<void> | void;
}

const OBJECTIVE_LABELS: Record<string, string> = {
  CONVERSIONS: 'Conversões',
  OUTCOME_SALES: 'Vendas',
  OUTCOME_LEADS: 'Geração de Leads',
  OUTCOME_ENGAGEMENT: 'Engajamento',
  OUTCOME_AWARENESS: 'Reconhecimento',
  OUTCOME_TRAFFIC: 'Tráfego',
  OUTCOME_APP_PROMOTION: 'Promoção de App',
  TRAFFIC: 'Tráfego',
  LEAD_GENERATION: 'Geração de Leads',
  MESSAGES: 'Mensagens',
  ENGAGEMENT: 'Engajamento',
  APP_INSTALLS: 'Instalações de App',
  VIDEO_VIEWS: 'Visualizações de Vídeo',
  REACH: 'Alcance',
  BRAND_AWARENESS: 'Reconhecimento de Marca',
  LINK_CLICKS: 'Cliques no Link',
  POST_ENGAGEMENT: 'Engajamento com Publicação',
  PAGE_LIKES: 'Curtidas na Página',
};

export function CampaignEditContent({
  node,
  clientId,
  companyId,
  onSuccess,
}: CampaignEditContentProps) {
  const saveProgress = useSaveWithProgress();

  // Basic fields
  const [editName, setEditName] = useState('');
  const [editStatus, setEditStatus] = useState<'active' | 'paused'>('active');
  const [budgetType, setBudgetType] = useState<'daily' | 'lifetime'>('daily');
  const [editBudget, setEditBudget] = useState('');

  const [hasChanges, setHasChanges] = useState(false);

  // Reset form when node changes
  useEffect(() => {
    if (node) {
      setEditName(node.name);
      setEditStatus(node.status === 'active' ? 'active' : 'paused');
      setBudgetType(node.budget?.type || 'daily');
      setEditBudget(node.budget?.amount?.toString() || '');
      setHasChanges(false);
    }
  }, [node?.id]);

  // Track changes
  useEffect(() => {
    if (!node) return;

    const nameChanged = editName !== node.name;
    const currentNodeStatus = node.status === 'active' ? 'active' : 'paused';
    const statusChanged = editStatus !== currentNodeStatus;
    const budgetTypeChanged = budgetType !== (node.budget?.type || 'daily');
    const budgetValueChanged = node.budget && editBudget !== node.budget.amount.toString();

    setHasChanges(nameChanged || statusChanged || budgetTypeChanged || !!budgetValueChanged);
  }, [editName, editStatus, budgetType, editBudget, node]);

  const handleSave = useCallback(async () => {
    if (!clientId || !node) return;

    const metaAction = async () => {
      const currentNodeStatus = node.status === 'active' ? 'active' : 'paused';
      const nameChanged = editName !== node.name;
      const statusChanged = editStatus !== currentNodeStatus;
      const budgetChanged = node.budget && (
        editBudget !== node.budget.amount.toString() || 
        budgetType !== node.budget.type
      );

      // Update name
      if (nameChanged) {
        const { data, error } = await supabase.functions.invoke('manage-facebook-campaign', {
          body: {
            campaignId: node.id,
            clientId,
            action: 'rename',
            name: editName,
          },
        });

        if (error) throw error;
        if (!data?.success) throw new Error(data?.error || 'Erro ao renomear campanha');
      }

      // Update status
      if (statusChanged) {
        const { data, error } = await supabase.functions.invoke('manage-facebook-campaign', {
          body: {
            campaignId: node.id,
            clientId,
            action: 'toggle',
            status: editStatus === 'active' ? 'ACTIVE' : 'PAUSED',
          },
        });

        if (error) throw error;
        if (!data?.success) throw new Error(data?.error || 'Erro ao alterar status');
      }

      // Update budget
      if (budgetChanged && editBudget) {
        const { data, error } = await supabase.functions.invoke('manage-facebook-campaign', {
          body: {
            campaignId: node.id,
            clientId,
            action: 'budget',
            budgetType,
            amount: parseFloat(editBudget) * 100, // Meta expects cents
          },
        });

        if (error) throw error;
        if (!data?.success) throw new Error(data?.error || 'Erro ao atualizar orçamento');
      }
    };

    const success = await saveProgress.execute(metaAction, async () => {
      setHasChanges(false);
      if (onSuccess) {
        await onSuccess();
      }
    });

    if (success) {
      toast.success('Campanha atualizada com sucesso!');
    }
  }, [clientId, node, editName, editStatus, budgetType, editBudget, onSuccess, saveProgress]);

  // Calculate ad sets summary
  const adSetsSummary = useMemo(() => {
    if (!node?.children) return { total: 0, active: 0, paused: 0 };

    return {
      total: node.children.length,
      active: node.children.filter(c => c.status === 'active').length,
      paused: node.children.filter(c => c.status !== 'active').length,
    };
  }, [node?.children]);

  if (!node || node.type !== 'campaign') return null;

  const isGoogle = node.platform === 'google';
  const formatCurrency = (value: number) => `R$ ${value.toFixed(2)}`;
  const formatNumber = (value: number) => value.toLocaleString();
  const formatPercent = (value: number) => `${value.toFixed(2)}%`;

  const objectiveLabel = OBJECTIVE_LABELS[(node as unknown).objective || ''] || (node as unknown).objective || 'Não definido';

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="p-6 pb-4">
        <div className="flex items-center gap-3">
          <Target className="w-6 h-6 text-primary" />
          <div className="flex-1">
            <h2 className="text-xl font-semibold">Campanha</h2>
            <div className="flex items-center gap-2 mt-1">
              <Badge variant="outline">{node.platform.toUpperCase()}</Badge>
            </div>
          </div>
          {/* Status Toggle */}
          <div className="flex items-center gap-3">
            <span className="text-sm text-muted-foreground">
              {editStatus === 'active' ? 'Ativo' : 'Pausado'}
            </span>
            <Switch
              checked={editStatus === 'active'}
              onCheckedChange={(checked) => setEditStatus(checked ? 'active' : 'paused')}
              className="data-[state=checked]:bg-green-500"
            />
          </div>
        </div>
      </div>

      <Separator />

      <ScrollArea className="flex-1">
        <div className="p-6 space-y-6">
          {/* Google Alert */}
          {isGoogle && (
            <Alert>
              <AlertTriangle className="h-4 w-4" />
              <AlertDescription>
                Google Ads: alterações serão salvas apenas localmente.
              </AlertDescription>
            </Alert>
          )}

          {/* Metrics Cards at Top */}
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-2">
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <DollarSign className="w-3 h-3" />
                <span className="text-xs">Investido</span>
              </div>
              <p className="text-sm font-bold">{formatCurrency(node.metrics.spend)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Eye className="w-3 h-3" />
                <span className="text-xs">Impressões</span>
              </div>
              <p className="text-sm font-bold">{formatNumber(node.metrics.impressions)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Percent className="w-3 h-3" />
                <span className="text-xs">CTR</span>
              </div>
              <p className="text-sm font-bold">{formatPercent(node.metrics.ctr)}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Target className="w-3 h-3" />
                <span className="text-xs">Conversões</span>
              </div>
              <p className="text-sm font-bold">{formatNumber(node.metrics.conversions)}</p>
            </div>
            {/* Ad Sets Summary */}
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <Layers className="w-3 h-3" />
                <span className="text-xs">Conjuntos</span>
              </div>
              <p className="text-sm font-bold">{adSetsSummary.total}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <PlayCircle className="w-3 h-3" />
                <span className="text-xs">Ativos</span>
              </div>
              <p className="text-sm font-bold text-primary">{adSetsSummary.active}</p>
            </div>
            <div className="p-2 rounded-lg bg-muted/50 flex flex-col items-center">
              <div className="flex items-center gap-1 text-muted-foreground mb-1">
                <PauseCircle className="w-3 h-3" />
                <span className="text-xs">Pausados</span>
              </div>
              <p className="text-sm font-bold text-muted-foreground">{adSetsSummary.paused}</p>
            </div>
          </div>

          {/* Two Column Layout */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Left Column - Configurations */}
            <div className="space-y-6">
              <div className="space-y-4">
                <h4 className="font-medium text-sm flex items-center gap-2 text-muted-foreground uppercase tracking-wider">
                  <Settings className="w-4 h-4" />
                  Configurações
                </h4>

                {/* Name Field */}
                <div className="space-y-2">
                  <Label>Nome da Campanha *</Label>
                  <Input
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                    placeholder="Ex: Campanha de Conversões - Janeiro"
                  />
                  {editName.trim() === '' && (
                    <p className="text-xs text-destructive">O nome não pode estar vazio</p>
                  )}
                </div>

                {/* Objective (Read-only) */}
                <div className="space-y-2">
                  <Label className="flex items-center gap-2">
                    Objetivo
                    <Badge variant="secondary" className="text-xs font-normal">
                      <Info className="w-3 h-3 mr-1" />
                      Somente leitura
                    </Badge>
                  </Label>
                  <Input
                    value={objectiveLabel}
                    disabled
                    className="bg-muted cursor-not-allowed"
                  />
                  <p className="text-xs text-muted-foreground">
                    O objetivo não pode ser alterado após a criação da campanha.
                  </p>
                </div>
              </div>
            </div>

            {/* Right Column - Budget */}
            <div className="space-y-6">
              <div className="space-y-4">
                <h4 className="font-medium text-sm flex items-center gap-2 text-muted-foreground uppercase tracking-wider">
                  <DollarSign className="w-4 h-4" />
                  Orçamento
                </h4>

                {/* Budget Type */}
                <div className="space-y-2">
                  <Label>Tipo de Orçamento</Label>
                  <Select value={budgetType} onValueChange={(v) => setBudgetType(v as 'daily' | 'lifetime')}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="daily">Diário</SelectItem>
                      <SelectItem value="lifetime">Vitalício</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                {/* Budget Value */}
                <div className="space-y-2">
                  <Label>Valor (R$)</Label>
                  <Input
                    type="number"
                    min={1}
                    value={editBudget}
                    onChange={(e) => setEditBudget(e.target.value)}
                    placeholder="50"
                  />
                  {editBudget !== '' && parseFloat(editBudget) < 1 && (
                    <p className="text-xs text-destructive">O orçamento mínimo é R$ 1,00</p>
                  )}
                </div>

                {/* Budget Summary */}
                {node.budget?.spent !== undefined && (
                  <div className="p-4 rounded-lg bg-muted/50 space-y-2">
                    <div className="flex justify-between text-sm">
                      <span className="text-muted-foreground">Gasto até agora:</span>
                      <span className="font-medium">{formatCurrency(node.budget.spent)}</span>
                    </div>
                    {node.budget.amount > 0 && (
                      <div className="flex justify-between text-sm">
                        <span className="text-muted-foreground">Restante:</span>
                        <span className="font-medium">
                          {formatCurrency(Math.max(0, node.budget.amount - node.budget.spent))}
                        </span>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </ScrollArea>

      <Separator />

      {/* Footer */}
      <div className="p-4 flex justify-end gap-2">
        <Button
          onClick={handleSave}
          disabled={saveProgress.isOpen || !hasChanges || editName.trim() === ''}
        >
          <Save className="w-4 h-4 mr-2" />
          Salvar
        </Button>
      </div>

      {/* Save Progress Modal */}
      <SaveProgressModal
        isOpen={saveProgress.isOpen}
        steps={saveProgress.steps}
        error={saveProgress.error}
        onClose={saveProgress.close}
        onRetry={handleSave}
      />
    </div>
  );
}

import { useState, useCallback, useMemo } from "react";
import { TreeNode, ClientTargets } from "@/hooks/useCampaignTree";
import { TreeGridRow } from "./TreeGridRow";
import { BulkActionsBar } from "./BulkActionsBar";
import { useInlineEdit } from "@/hooks/useInlineEdit";
import { Checkbox } from "@/components/ui/checkbox";
import { RefreshCw, ArrowUp, ArrowDown, ArrowUpDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { supabase } from "@/integrations/supabase/client";

type SortColumn = "name" | "status" | "budget" | "ctr" | "cpa" | "cpm" | "cpc" | "conversions" | "spend";
type SortDirection = "asc" | "desc";

interface MultiCampaignTreeGridProps {
  campaigns: TreeNode[];
  targets: ClientTargets;
  clientId: string;
  isLoading: boolean;
  statusFilter: "all" | "active" | "paused" | "finished" | "deleted";
  onSelectNode: (node: TreeNode) => void;
  selectedNodeId: string | null;
  onRefresh: () => void;
}

export function MultiCampaignTreeGrid({
  campaigns,
  targets,
  clientId,
  isLoading,
  statusFilter,
  onSelectNode,
  selectedNodeId,
  onRefresh,
}: MultiCampaignTreeGridProps) {
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set());
  const [selectedNodes, setSelectedNodes] = useState<Set<string>>(new Set());
  const [sortColumn, setSortColumn] = useState<SortColumn | null>(null);
  const [sortDirection, setSortDirection] = useState<SortDirection>("asc");

  const { loading, currentAction, updateStatus, updateBudget, bulkUpdateStatus } = useInlineEdit({
    onSuccess: onRefresh,
  });

  const handleSort = useCallback((column: SortColumn) => {
    if (sortColumn === column) {
      if (sortDirection === "asc") {
        setSortDirection("desc");
      } else {
        setSortColumn(null);
        setSortDirection("asc");
      }
    } else {
      setSortColumn(column);
      setSortDirection("asc");
    }
  }, [sortColumn, sortDirection]);

  // Filter and sort campaigns
  const filteredCampaigns = useMemo(() => {
    const result = statusFilter === "all" ? [...campaigns] : campaigns.filter((campaign) => campaign.status === statusFilter);

    if (sortColumn) {
      result.sort((a, b) => {
        let aValue: number | string;
        let bValue: number | string;

        switch (sortColumn) {
          case "name":
            aValue = a.name.toLowerCase();
            bValue = b.name.toLowerCase();
            break;
          case "status":
            aValue = a.status;
            bValue = b.status;
            break;
          case "budget":
            aValue = a.budget?.amount ?? 0;
            bValue = b.budget?.amount ?? 0;
            break;
          case "ctr":
            aValue = a.metrics.ctr;
            bValue = b.metrics.ctr;
            break;
          case "cpa":
            aValue = a.metrics.cpa;
            bValue = b.metrics.cpa;
            break;
          case "cpm":
            aValue = a.metrics.cpm;
            bValue = b.metrics.cpm;
            break;
          case "cpc":
            aValue = a.metrics.cpc;
            bValue = b.metrics.cpc;
            break;
          case "conversions":
            aValue = a.metrics.conversions;
            bValue = b.metrics.conversions;
            break;
          case "spend":
            aValue = a.metrics.spend;
            bValue = b.metrics.spend;
            break;
          default:
            return 0;
        }

        if (typeof aValue === "string" && typeof bValue === "string") {
          return sortDirection === "asc" 
            ? aValue.localeCompare(bValue) 
            : bValue.localeCompare(aValue);
        }

        return sortDirection === "asc" 
          ? (aValue as number) - (bValue as number) 
          : (bValue as number) - (aValue as number);
      });
    }

    return result;
  }, [campaigns, statusFilter, sortColumn, sortDirection]);

  // Collect all node IDs for "select all" functionality
  const allNodeIds = useMemo(() => {
    const ids: string[] = [];
    const collectIds = (node: TreeNode) => {
      ids.push(node.id);
      node.children?.forEach(collectIds);
    };
    filteredCampaigns.forEach(collectIds);
    return ids;
  }, [filteredCampaigns]);

  // Collect all nodes for bulk operations
  const allNodesMap = useMemo(() => {
    const map = new Map<string, TreeNode>();
    const collectNodes = (node: TreeNode) => {
      map.set(node.id, node);
      node.children?.forEach(collectNodes);
    };
    filteredCampaigns.forEach(collectNodes);
    return map;
  }, [filteredCampaigns]);

  const toggleExpand = useCallback((nodeId: string) => {
    setExpandedNodes((prev) => {
      const next = new Set(prev);
      if (next.has(nodeId)) {
        next.delete(nodeId);
      } else {
        next.add(nodeId);
      }
      return next;
    });
  }, []);

  const toggleSelection = useCallback((nodeId: string) => {
    setSelectedNodes((prev) => {
      const next = new Set(prev);
      if (next.has(nodeId)) {
        next.delete(nodeId);
      } else {
        next.add(nodeId);
      }
      return next;
    });
  }, []);

  const selectAll = useCallback(() => {
    setSelectedNodes(new Set(allNodeIds));
  }, [allNodeIds]);

  const clearSelection = useCallback(() => {
    setSelectedNodes(new Set());
  }, []);

  const handleToggleStatus = useCallback(
    (node: TreeNode, newStatus: boolean) => {
      updateStatus(
        node.type,
        node.id,
        clientId,
        node.facebookId,
        newStatus ? "active" : "paused",
        node.platform
      );
    },
    [updateStatus, clientId]
  );

  const handleUpdateBudget = useCallback(
    (node: TreeNode, newBudget: number) => {
      if (!node.budget) return;
      updateBudget(
        node.type,
        node.id,
        clientId,
        node.facebookId,
        newBudget,
        node.budget.type,
        node.platform
      );
    },
    [updateBudget, clientId]
  );

  const handleBulkPause = useCallback(() => {
    const nodes = Array.from(selectedNodes)
      .map((id) => allNodesMap.get(id))
      .filter((node): node is TreeNode => node !== undefined)
      .map((node) => ({
        type: node.type,
        id: node.id,
        facebookId: node.facebookId,
        platform: node.platform,
      }));

    bulkUpdateStatus(nodes, "paused", clientId);
    clearSelection();
  }, [selectedNodes, allNodesMap, bulkUpdateStatus, clearSelection]);

  const handleBulkActivate = useCallback(() => {
    const nodes = Array.from(selectedNodes)
      .map((id) => allNodesMap.get(id))
      .filter((node): node is TreeNode => node !== undefined)
      .map((node) => ({
        type: node.type,
        id: node.id,
        facebookId: node.facebookId,
        platform: node.platform,
      }));

    bulkUpdateStatus(nodes, "active", clientId);
    clearSelection();
  }, [selectedNodes, allNodesMap, bulkUpdateStatus, clearSelection, clientId]);

  const handleBulkDelete = useCallback(async () => {
    const nodes = Array.from(selectedNodes)
      .map((id) => allNodesMap.get(id))
      .filter((node): node is TreeNode => node !== undefined);

    if (nodes.length === 0) return;

    const confirmMessage = nodes.length === 1
      ? `Tem certeza que deseja excluir "${nodes[0].name}"?`
      : `Tem certeza que deseja excluir ${nodes.length} itens selecionados?`;

    if (!confirm(confirmMessage)) return;

    for (const node of nodes) {
      try {
        await supabase.functions.invoke("delete-tree-entity", {
          body: {
            entityType: node.type === "adset" ? "adset" : node.type === "ad" ? "ad" : "campaign",
            entityId: node.id,
            clientId: clientId,
            facebookId: node.facebookId,
          },
        });
      } catch (error) {
        console.error("Error deleting node:", node.id, error);
      }
    }

    clearSelection();
    onRefresh?.();
  }, [selectedNodes, allNodesMap, clientId, clearSelection, onRefresh]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64 text-muted-foreground border rounded-lg bg-card">
        <div className="text-center">
          <RefreshCw className="w-6 h-6 animate-spin mx-auto mb-2" />
          <p>Carregando campanhas...</p>
        </div>
      </div>
    );
  }

  if (filteredCampaigns.length === 0) {
    return (
      <div className="flex items-center justify-center h-64 text-muted-foreground border rounded-lg bg-card">
        <div className="text-center">
          <p className="mb-2">Nenhuma campanha encontrada</p>
          <p className="text-sm">Clique em "Sincronizar" para buscar campanhas</p>
        </div>
      </div>
    );
  }

  // Check if all are selected
  const allSelected = allNodeIds.length > 0 && selectedNodes.size === allNodeIds.length;
  const someSelected = selectedNodes.size > 0 && selectedNodes.size < allNodeIds.length;

  // Flatten multiple campaign trees into an array of rows
  const flattenTree = (node: TreeNode, depth: number = 0): React.ReactNode[] => {
    const isExpanded = expandedNodes.has(node.id);
    const hasChildren = node.children && node.children.length > 0;
    const isSelected = selectedNodeId === node.id;
    const isChecked = selectedNodes.has(node.id);

    const rows: React.ReactNode[] = [
      <TreeGridRow
        key={node.id}
        node={node}
        depth={depth}
        isExpanded={isExpanded}
        hasChildren={hasChildren}
        isSelected={isSelected}
        isChecked={isChecked}
        targets={targets}
        isStatusLoading={loading && currentAction === `status-${node.id}`}
        isBudgetLoading={loading && currentAction === `budget-${node.id}`}
        clientId={clientId}
        onToggleExpand={() => toggleExpand(node.id)}
        onSelect={() => onSelectNode(node)}
        onToggleCheck={() => toggleSelection(node.id)}
        onToggleStatus={(newStatus) => handleToggleStatus(node, newStatus)}
        onUpdateBudget={(newBudget) => handleUpdateBudget(node, newBudget)}
        onRefresh={onRefresh}
      />,
    ];

    if (isExpanded && hasChildren) {
      node.children!.forEach((child) => {
        rows.push(...flattenTree(child, depth + 1));
      });
    }

    return rows;
  };

  return (
    <div className="space-y-2">
      {/* Bulk Actions Bar */}
      <BulkActionsBar
        selectedCount={selectedNodes.size}
        isLoading={loading && currentAction === "bulk-status"}
        onPause={handleBulkPause}
        onActivate={handleBulkActivate}
        onDelete={handleBulkDelete}
        onClear={clearSelection}
      />

      <div className="border rounded-lg overflow-hidden bg-card">
        <table className="w-full">
          <thead className="bg-card border-b">
            <tr>
              {/* Checkbox column */}
              <th className="px-3 py-3 w-[3%]">
                <Checkbox
                  checked={allSelected}
                  ref={(ref) => {
                    if (ref) {
                      (ref as unknown).indeterminate = someSelected;
                    }
                  }}
                  onCheckedChange={(checked) => {
                    if (checked) {
                      selectAll();
                    } else {
                      clearSelection();
                    }
                  }}
                />
              </th>
              <SortableHeader 
                column="name" 
                label="Nome" 
                width="27%" 
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onSort={handleSort}
              />
              <SortableHeader 
                column="status" 
                label="Status" 
                width="7%" 
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onSort={handleSort}
              />
              <SortableHeader 
                column="budget" 
                label="Orçamento" 
                width="13%" 
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onSort={handleSort}
              />
              <SortableHeader 
                column="conversions" 
                label="Conv." 
                width="7%" 
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onSort={handleSort}
              />
              <SortableHeader 
                column="cpa" 
                label="CPA" 
                width="8%" 
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onSort={handleSort}
              />
              <SortableHeader 
                column="ctr" 
                label="CTR" 
                width="7%" 
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onSort={handleSort}
              />
              <SortableHeader 
                column="cpm" 
                label="CPM" 
                width="7%" 
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onSort={handleSort}
              />
              <SortableHeader 
                column="cpc" 
                label="CPC" 
                width="7%" 
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onSort={handleSort}
              />
              <SortableHeader 
                column="spend" 
                label="Investido" 
                width="12%" 
                sortColumn={sortColumn}
                sortDirection={sortDirection}
                onSort={handleSort}
              />
              <th className="px-3 py-3 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider w-[4%]">

              </th>
            </tr>
          </thead>
          <tbody className="bg-card divide-y divide-border">
            {filteredCampaigns.flatMap((campaign) => flattenTree(campaign, 0))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// Helper component for sortable headers
interface SortableHeaderProps {
  column: SortColumn;
  label: string;
  width: string;
  sortColumn: SortColumn | null;
  sortDirection: SortDirection;
  onSort: (column: SortColumn) => void;
}

function SortableHeader({ column, label, width, sortColumn, sortDirection, onSort }: SortableHeaderProps) {
  const isActive = sortColumn === column;

  return (
    <th 
      className={cn(
        "px-3 py-3 text-left text-xs font-medium uppercase tracking-wider cursor-pointer hover:bg-muted/50 transition-colors select-none",
        isActive ? "text-foreground" : "text-muted-foreground"
      )}
      style={{ width }}
      onClick={() => onSort(column)}
    >
      <div className="flex items-center gap-1">
        <span>{label}</span>
        {isActive ? (
          sortDirection === "asc" ? (
            <ArrowUp className="h-3 w-3" />
          ) : (
            <ArrowDown className="h-3 w-3" />
          )
        ) : (
          <ArrowUpDown className="h-3 w-3 opacity-40" />
        )}
      </div>
    </th>
  );
}

