import { useState, useEffect, useCallback } from 'react';
import {
  Dialog,
  DialogContent,
} from '@/components/ui/dialog';
import { TreeNode } from '@/hooks/useCampaignTree';
import { CampaignTreeNav } from './CampaignTreeNav';
import { CampaignEditContent } from './CampaignEditContent';
import { AdSetEditContent } from './AdSetEditContent';
import { AdEditContent } from './AdEditContent';

interface UnifiedCampaignModalProps {
  isOpen: boolean;
  onClose: () => void;
  campaignTree: TreeNode | null;
  initialSelectedNode: TreeNode | null;
  clientId: string;
  companyId?: string;
  onSuccess?: () => Promise<void> | void;
}

export function UnifiedCampaignModal({
  isOpen,
  onClose,
  campaignTree,
  initialSelectedNode,
  clientId,
  companyId,
  onSuccess,
}: UnifiedCampaignModalProps) {
  const [selectedNode, setSelectedNode] = useState<TreeNode | null>(initialSelectedNode);
  const [parentNode, setParentNode] = useState<TreeNode | null>(null);

  // Update selected node when initial node changes
  useEffect(() => {
    if (isOpen && initialSelectedNode) {
      setSelectedNode(initialSelectedNode);
    }
  }, [isOpen, initialSelectedNode?.id]);

  // Find parent node for ads (to show inherited pixel)
  const findParentNode = useCallback((node: TreeNode, tree: TreeNode | null): TreeNode | null => {
    if (!tree || !node.parentId) return null;

    if (tree.id === node.parentId) return tree;

    if (tree.children) {
      for (const child of tree.children) {
        if (child.id === node.parentId) return child;
        const found = findParentNode(node, child);
        if (found) return found;
      }
    }
    return null;
  }, []);

  // Update parent node when selected node changes
  useEffect(() => {
    if (selectedNode?.type === 'ad' && campaignTree) {
      const parent = findParentNode(selectedNode, campaignTree);
      setParentNode(parent);
    } else {
      setParentNode(null);
    }
  }, [selectedNode, campaignTree, findParentNode]);

  const handleNodeSelect = (node: TreeNode) => {
    setSelectedNode(node);
  };

  const handleSuccess = async () => {
    await onSuccess?.();
  };

  if (!campaignTree) return null;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent 
        className="w-[1800px] max-w-[95vw] h-[85vh] flex flex-col p-0 gap-0 overflow-hidden"
        hideCloseButton={false}
      >
        <div className="flex h-full">
          {/* Left sidebar - Tree navigation */}
          <div className="w-[450px] min-w-[450px] border-r bg-muted/30 flex flex-col">
            <CampaignTreeNav
              tree={campaignTree}
              selectedNodeId={selectedNode?.id || null}
              onSelectNode={handleNodeSelect}
              clientId={clientId}
              onRefresh={handleSuccess}
            />
          </div>

          {/* Right content area */}
          <div className="flex-1 overflow-hidden flex flex-col">
            {selectedNode?.type === 'campaign' && (
              <CampaignEditContent
                node={selectedNode}
                clientId={clientId}
                companyId={companyId}
                onSuccess={handleSuccess}
              />
            )}
            {selectedNode?.type === 'adset' && (
              <AdSetEditContent
                node={selectedNode}
                clientId={clientId}
                companyId={companyId}
                onSuccess={handleSuccess}
              />
            )}
            {selectedNode?.type === 'ad' && (
              <AdEditContent
                node={selectedNode}
                parentNode={parentNode}
                clientId={clientId}
                companyId={companyId}
                onSuccess={handleSuccess}
              />
            )}
            {!selectedNode && (
              <div className="flex items-center justify-center h-full text-muted-foreground">
                Selecione um item na navegação à esquerda
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useMemo, useEffect, useCallback } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Slider } from "@/components/ui/slider";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command";
import { ScrollArea } from "@/components/ui/scroll-area";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Progress } from "@/components/ui/progress";
import { useToast } from "@/hooks/use-toast";
import { useClients } from "@/hooks/useClients";
import { useCompany } from "@/contexts/CompanyContext";
import { useBackgroundImageGeneration } from "@/hooks/useBackgroundImageGeneration";
import { supabase } from "@/integrations/supabase/client";
import { 
  Sparkles, 
  Loader2, 
  Check,
  ChevronsUpDown,
  ChevronDown,
  Target,
  Users,
  DollarSign,
  Zap,
  ShoppingBag,
  RotateCcw,
  Heart,
  TrendingUp,
  Save,
  RefreshCw,
  Settings,
  Send,
  AlertCircle,
  ImageIcon,
  X,
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Alert, AlertDescription } from "@/components/ui/alert";

// Editable sections
import { EditableBudgetSection } from "./editable/EditableBudgetSection";
import { EditableScheduleSection } from "./editable/EditableScheduleSection";
import { EditableBiddingSection } from "./editable/EditableBiddingSection";
import { EditableAdSetsSection } from "./editable/EditableAdSetsSection";
import { 
  EditableStrategy, 
  EditableAdSet, 
  EditableCreative,
  CAMPAIGN_OBJECTIVES,
  createDefaultCreative,
  createDefaultAdSet,
} from "./editable/types";

type FunnelStage = "topo" | "meio" | "fundo" | "retencao";
type CampaignType = "awareness" | "traffic" | "leads" | "conversions" | "remarketing" | "retention";

const FUNNEL_STAGES = [
  { id: "topo" as FunnelStage, label: "Topo", icon: TrendingUp, description: "Awareness" },
  { id: "meio" as FunnelStage, label: "Meio", icon: Users, description: "Consideração" },
  { id: "fundo" as FunnelStage, label: "Fundo", icon: Target, description: "Conversão" },
  { id: "retencao" as FunnelStage, label: "Retenção", icon: Heart, description: "Fidelização" },
];

const CAMPAIGN_TYPES: Record<CampaignType, { title: string; icon: React.ElementType; suitableFor: FunnelStage[] }> = {
  awareness: { title: "Brand Awareness", icon: Zap, suitableFor: ["topo"] },
  traffic: { title: "Tráfego", icon: Target, suitableFor: ["topo", "meio"] },
  leads: { title: "Geração de Leads", icon: Users, suitableFor: ["meio"] },
  conversions: { title: "Conversões", icon: ShoppingBag, suitableFor: ["fundo"] },
  remarketing: { title: "Remarketing", icon: RotateCcw, suitableFor: ["meio", "fundo", "retencao"] },
  retention: { title: "Retenção", icon: Heart, suitableFor: ["retencao"] },
};

interface ExistingCampaign {
  id: string;
  client_id: string;
  title: string;
  funnel_stage: string;
  campaign_type: string;
  configuration: EditableStrategy;
  creatives: EditableCreative[];
  status: string;
  clients?: {
    id: string;
    name: string;
    avatar?: string;
    company: string;
    website_url?: string;
    monthly_budget?: number;
    sector?: string;
  };
}

interface CampaignGeneratorSimplifiedProps {
  onBack: () => void;
  existingCampaign?: ExistingCampaign | null;
}

export function CampaignGeneratorSimplified({ onBack, existingCampaign }: CampaignGeneratorSimplifiedProps) {
  const { toast } = useToast();
  const { clients } = useClients();
  const { activeCompany } = useCompany();
  const { progress: imageProgress, generateImagesInBackground, stopGeneration } = useBackgroundImageGeneration();

  // Determine if we're in edit mode
  const isEditMode = Boolean(existingCampaign);
  const [existingCampaignId] = useState(existingCampaign?.id);

  // Form state - initialize from existing campaign if available
  const [selectedClientId, setSelectedClientId] = useState<string>(existingCampaign?.client_id || "");
  const [funnelStage, setFunnelStage] = useState<FunnelStage | "">(
    (existingCampaign?.funnel_stage as FunnelStage) || ""
  );
  const [campaignType, setCampaignType] = useState<CampaignType | "">(
    (existingCampaign?.campaign_type as CampaignType) || ""
  );
  const [customObjective, setCustomObjective] = useState("");
  const [dailyBudget, setDailyBudget] = useState(existingCampaign?.configuration?.dailyBudget || 100);
  const [duration, setDuration] = useState(existingCampaign?.configuration?.duration || 30);
  const [clientSearchOpen, setClientSearchOpen] = useState(false);
  const [showAdvanced, setShowAdvanced] = useState(false);

  // Generation state - initialize with existing strategy if available
  const [isGenerating, setIsGenerating] = useState(false);
  const [isPublishing, setIsPublishing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editableStrategy, setEditableStrategy] = useState<EditableStrategy | null>(() => {
    if (existingCampaign?.configuration) {
      const config = existingCampaign.configuration;
      return {
        ...config,
        startDate: new Date(config.startDate || Date.now()),
        endDate: config.endDate ? new Date(config.endDate) : null,
        hasEndDate: config.hasEndDate !== false,
        // Ensure arrays exist to prevent "length" errors
        adSets: (config.adSets || []).map((as: unknown) => ({
          ...as,
          creatives: as.creatives || [],
          interests: as.interests || [],
          behaviors: as.behaviors || [],
          includedAudiences: as.includedAudiences || [],
          excludedAudiences: as.excludedAudiences || [],
        })),
        recommendations: config.recommendations || [],
      };
    }
    return null;
  });

  // Callback to update creative with generated image
  const handleCreativeImageUpdate = useCallback((adSetId: string, creativeId: string, imageUrl: string) => {
    setEditableStrategy(prev => {
      if (!prev) return prev;
      return {
        ...prev,
        adSets: prev.adSets.map(as =>
          as.id === adSetId
            ? {
                ...as,
                creatives: as.creatives.map(c =>
                  c.id === creativeId ? { ...c, mediaUrls: [imageUrl] } : c
                ),
              }
            : as
        ),
      };
    });
  }, []);

  // Start background image generation when strategy is set
  useEffect(() => {
    if (editableStrategy && selectedClientId && !isEditMode && !imageProgress.isGenerating) {
      // Small delay to let UI render first
      const timer = setTimeout(() => {
        generateImagesInBackground(editableStrategy, selectedClientId, handleCreativeImageUpdate);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [editableStrategy?.adSets.length, selectedClientId, isEditMode]);

  // Derived state
  const selectedClient = useMemo(() => 
    clients?.find(c => c.id === selectedClientId), 
    [clients, selectedClientId]
  );

  const activeClients = useMemo(() => 
    (clients?.filter(c => !c.is_canceled) || []).sort((a, b) => a.name.localeCompare(b.name)), 
    [clients]
  );

  const availableCampaignTypes = useMemo(() => {
    if (!funnelStage) return [];
    return Object.entries(CAMPAIGN_TYPES)
      .filter(([_, type]) => type.suitableFor.includes(funnelStage as FunnelStage))
      .map(([id, type]) => ({ id: id as CampaignType, ...type }));
  }, [funnelStage]);

  const canGenerate = selectedClientId && funnelStage && campaignType;

  // Reset campaign type when funnel changes
  const handleFunnelChange = (value: string) => {
    setFunnelStage(value as FunnelStage);
    setCampaignType("");
    setEditableStrategy(null);
  };

  const handleStrategyChange = (updates: Partial<EditableStrategy>) => {
    if (editableStrategy) {
      setEditableStrategy({ ...editableStrategy, ...updates });
    }
  };

  const handleGenerate = async () => {
    if (!selectedClient || !funnelStage || !campaignType) return;

    setIsGenerating(true);
    setEditableStrategy(null);

    try {
      const { data, error } = await supabase.functions.invoke('generate-campaign-strategy', {
        body: {
          client: {
            ...selectedClient,
            monthly_budget: dailyBudget * duration,
          },
          funnelStage,
          campaignType,
          step: 'campaign_configuration',
          customObjective,
          budget: {
            daily: dailyBudget,
            duration,
          }
        }
      });

      if (error) throw error;

      if (data?.configuration) {
        const config = data.configuration;
        const startDate = new Date();
        const endDate = new Date();
        endDate.setDate(endDate.getDate() + (config.schedule?.duration || duration));

        // Parse targeting data from AI response
        const aiInterests = config.targeting?.interests || [];
        const aiBehaviors = config.targeting?.behaviors ? 
          (Array.isArray(config.targeting.behaviors) ? config.targeting.behaviors : [config.targeting.behaviors]) : [];

        // Create ad sets with targeting from AI
        const aiAdSets: EditableAdSet[] = (config.adSets || []).map((as: unknown, i: number) => ({
          id: crypto.randomUUID(),
          name: as.name || `Conjunto ${i + 1}`,
          ageMin: as.ageMin || 18,
          ageMax: as.ageMax || 65,
          genders: as.genders || ['all'],
          interests: as.interests || aiInterests,
          behaviors: as.behaviors || aiBehaviors,
          includedAudiences: [],
          excludedAudiences: [],
          creatives: [createDefaultCreative()],
        }));

        // Ensure at least one ad set
        if (aiAdSets.length === 0) {
          aiAdSets.push({
            ...createDefaultAdSet('Conjunto Principal', 0),
            interests: aiInterests,
            behaviors: aiBehaviors,
          });
        }

        // Convert AI response to editable strategy
        const strategy: EditableStrategy = {
          dailyBudget: config.budget?.daily || dailyBudget,
          duration: config.schedule?.duration || duration,
          totalBudget: (config.budget?.daily || dailyBudget) * (config.schedule?.duration || duration),
          startDate,
          endDate,
          hasEndDate: true, // Default to having an end date
          useOptimalHours: true,
          optimalHours: config.schedule?.optimalHours || '9h-21h',
          bidStrategy: 'LOWEST_COST',
          targetCPA: config.bidding?.targetCPA,
          recommendations: config.recommendations || [],
          estimatedReach: config.targeting?.estimatedReach || '50k-100k',
          adSets: aiAdSets,
        };

        // Now generate creative texts using AI
        try {
          const { data: creativesData, error: creativesError } = await supabase.functions.invoke('generate-campaign-creatives', {
            body: {
              client: selectedClient,
              funnelStage,
              campaignType,
              configuration: config,
            }
          });

          if (!creativesError && creativesData?.creatives) {
            // Fill creatives with AI-generated texts
            const aiCreatives = creativesData.creatives;
            strategy.adSets = strategy.adSets.map((adSet, adSetIndex) => {
              const aiCreative = aiCreatives[adSetIndex];
              if (aiCreative) {
                return {
                  ...adSet,
                  creatives: adSet.creatives.map((creative, idx) => ({
                    ...creative,
                    headline: idx === 0 ? aiCreative.headline : (aiCreative.variations?.headline?.[idx - 1] || creative.headline),
                    body: idx === 0 ? aiCreative.primaryText : (aiCreative.variations?.primaryText?.[idx - 1] || creative.body),
                    description: idx === 0 ? aiCreative.description : (aiCreative.variations?.description?.[idx - 1] || creative.description),
                    callToAction: aiCreative.callToAction?.toUpperCase().replace(/\s+/g, '_') || creative.callToAction,
                    linkUrl: selectedClient.website_url || creative.linkUrl,
                  })),
                };
              }
              return adSet;
            });
          }
        } catch (creativesErr) {
          console.warn('Erro ao gerar criativos, continuando com valores padrão:', creativesErr);
        }

        setEditableStrategy(strategy);
        toast({
          title: "Estratégia gerada!",
          description: "Agora você pode editar todos os campos antes de publicar.",
        });
      }
    } catch (error: unknown) {
      console.error('Erro ao gerar estratégia:', error);
      toast({
        title: "Erro ao gerar estratégia",
        description: error.message || "Tente novamente",
        variant: "destructive",
      });
    } finally {
      setIsGenerating(false);
    }
  };

  const validateBeforePublish = (): string[] => {
    const errors: string[] = [];

    if (!selectedClient?.ad_account_id) {
      errors.push("Cliente não possui conta de anúncios Meta vinculada");
    }

    if (!editableStrategy) {
      errors.push("Nenhuma estratégia gerada");
      return errors;
    }

    if (editableStrategy.dailyBudget < 10) {
      errors.push("Orçamento diário mínimo é R$ 10");
    }

    if (editableStrategy.adSets.length === 0) {
      errors.push("Pelo menos 1 conjunto de anúncios é necessário");
    }

    for (const adSet of editableStrategy.adSets) {
      if (adSet.creatives.length === 0) {
        errors.push(`"${adSet.name}" precisa de pelo menos 1 criativo`);
      }

      for (const creative of adSet.creatives) {
        if (creative.mediaUrls.length === 0) {
          errors.push(`Criativo em "${adSet.name}" precisa de imagem/vídeo`);
        }
        if (!creative.body.trim()) {
          errors.push(`Criativo em "${adSet.name}" precisa de texto principal`);
        }
        if (!creative.linkUrl.trim()) {
          errors.push(`Criativo em "${adSet.name}" precisa de link de destino`);
        }
      }
    }

    return errors;
  };

  const handlePublishToMeta = async () => {
    if (!editableStrategy || !selectedClient || !campaignType) return;

    const errors = validateBeforePublish();
    if (errors.length > 0) {
      toast({
        title: "Validação falhou",
        description: errors[0],
        variant: "destructive",
      });
      return;
    }

    setIsPublishing(true);

    try {
      const campaignName = `${selectedClient.name} - ${CAMPAIGN_TYPES[campaignType]?.title || campaignType}`;
      const objective = CAMPAIGN_OBJECTIVES[campaignType] || 'OUTCOME_TRAFFIC';

      // Build payload for create-meta-campaign-full
      const payload = {
        clientId: selectedClientId,
        campaign: {
          name: campaignName,
          objective,
          daily_budget: editableStrategy.dailyBudget,
          status: 'PAUSED' as const, // Start paused for safety
        },
        adSets: editableStrategy.adSets.map(adSet => ({
          name: adSet.name,
          targeting: {
            custom_audiences: adSet.includedAudiences,
            excluded_audiences: adSet.excludedAudiences,
            age_min: adSet.ageMin,
            age_max: adSet.ageMax,
            genders: adSet.genders.includes('all') 
              ? undefined 
              : adSet.genders.map(g => g === 'male' ? 1 : 2),
            interests: adSet.interests,
            behaviors: adSet.behaviors,
          },
          creatives: adSet.creatives.map(creative => ({
            type: creative.type,
            media_urls: creative.mediaUrls,
            body: creative.body,
            title: creative.headline,
            description: creative.description,
            link_url: creative.linkUrl,
            call_to_action: creative.callToAction,
            url_parameters: creative.urlParameters,
          })),
        })),
      };

      const { data, error } = await supabase.functions.invoke('create-meta-campaign-full', {
        body: payload,
      });

      if (error) throw error;
      if (!data?.success) throw new Error(data?.error || 'Erro ao criar campanha');

      toast({
        title: "Campanha publicada!",
        description: `A campanha "${campaignName}" foi criada no Meta Ads com status PAUSADO.`,
      });

      // Save to generated_campaigns
      await supabase.from('generated_campaigns').insert({
        client_id: selectedClientId,
        company_id: activeCompany?.company_id,
        user_id: (await supabase.auth.getUser()).data.user?.id,
        title: campaignName,
        funnel_stage: funnelStage,
        campaign_type: campaignType,
        configuration: editableStrategy as unknown,
        creatives: editableStrategy.adSets.flatMap(as => as.creatives) as unknown,
        status: 'published',
      });

      onBack();
    } catch (error: unknown) {
      console.error('Erro ao publicar:', error);
      toast({
        title: "Erro ao publicar",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setIsPublishing(false);
    }
  };

  const handleSave = async () => {
    if (!editableStrategy || !selectedClient) return;

    setIsSaving(true);
    try {
      const campaignName = `${selectedClient.name} - ${CAMPAIGN_TYPES[campaignType as CampaignType]?.title || campaignType}`;

      if (isEditMode && existingCampaignId) {
        // Update existing campaign
        const { error } = await supabase.from('generated_campaigns')
          .update({
            title: campaignName,
            funnel_stage: funnelStage,
            campaign_type: campaignType,
            configuration: editableStrategy as unknown,
            creatives: editableStrategy.adSets.flatMap(as => as.creatives) as unknown,
          })
          .eq('id', existingCampaignId);

        if (error) throw error;

        toast({
          title: "Campanha atualizada!",
          description: "As alterações foram salvas com sucesso.",
        });
      } else {
        // Create new campaign
        const { error } = await supabase.from('generated_campaigns').insert({
          client_id: selectedClientId,
          company_id: activeCompany?.company_id,
          user_id: (await supabase.auth.getUser()).data.user?.id,
          title: campaignName,
          funnel_stage: funnelStage,
          campaign_type: campaignType,
          configuration: editableStrategy as unknown,
          creatives: editableStrategy.adSets.flatMap(as => as.creatives) as unknown,
          status: 'draft',
        });

        if (error) throw error;

        toast({
          title: "Campanha salva!",
          description: "A campanha foi salva como rascunho.",
        });
      }

      onBack();
    } catch (error: unknown) {
      toast({
        title: "Erro ao salvar",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  const validationErrors = editableStrategy ? validateBeforePublish() : [];

  return (
    <div className="space-y-6">
      {/* Input Card */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-primary" />
            {isEditMode ? 'Editar Campanha' : 'Nova Campanha'}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Client Selector */}
          <div className="space-y-2">
            <Label>Cliente</Label>
            <Popover open={clientSearchOpen} onOpenChange={setClientSearchOpen}>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  role="combobox"
                  aria-expanded={clientSearchOpen}
                  className="w-full justify-between h-11"
                >
                  {selectedClient ? (
                    <div className="flex items-center gap-2">
                      <Avatar className="h-6 w-6">
                        <AvatarImage src={selectedClient.avatar || undefined} />
                        <AvatarFallback className="text-xs">
                          {selectedClient.name.substring(0, 2).toUpperCase()}
                        </AvatarFallback>
                      </Avatar>
                      <span>{selectedClient.name}</span>
                    </div>
                  ) : (
                    <span className="text-muted-foreground">Selecione um cliente...</span>
                  )}
                  <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-full p-0" align="start">
                <Command>
                  <CommandInput placeholder="Buscar cliente..." />
                  <CommandList>
                    <CommandEmpty>Nenhum cliente encontrado.</CommandEmpty>
                    <CommandGroup>
                      <ScrollArea className="h-64">
                        {activeClients.map((client) => (
                          <CommandItem
                            key={client.id}
                            value={client.name}
                            onSelect={() => {
                              setSelectedClientId(client.id);
                              setClientSearchOpen(false);
                              setEditableStrategy(null);
                              if (client.monthly_budget) {
                                setDailyBudget(Math.round(client.monthly_budget / 30));
                              }
                            }}
                          >
                            <div className="flex items-center gap-2 flex-1">
                              <Avatar className="h-6 w-6">
                                <AvatarImage src={client.avatar || undefined} />
                                <AvatarFallback className="text-xs">
                                  {client.name.substring(0, 2).toUpperCase()}
                                </AvatarFallback>
                              </Avatar>
                              <div className="flex flex-col">
                                <span className="text-sm">{client.name}</span>
                                <span className="text-xs text-muted-foreground">{client.sector}</span>
                              </div>
                            </div>
                            {selectedClientId === client.id && (
                              <Check className="h-4 w-4 text-primary" />
                            )}
                          </CommandItem>
                        ))}
                      </ScrollArea>
                    </CommandGroup>
                  </CommandList>
                </Command>
              </PopoverContent>
            </Popover>
          </div>

          {/* Funnel Stage Toggle */}
          <div className="space-y-2">
            <Label>Etapa do Funil</Label>
            <ToggleGroup
              type="single"
              value={funnelStage}
              onValueChange={handleFunnelChange}
              className="justify-start flex-wrap"
            >
              {FUNNEL_STAGES.map((stage) => {
                const Icon = stage.icon;
                return (
                  <ToggleGroupItem
                    key={stage.id}
                    value={stage.id}
                    aria-label={stage.label}
                    className="flex items-center gap-2 data-[state=on]:bg-primary data-[state=on]:text-primary-foreground px-4"
                  >
                    <Icon className="w-4 h-4" />
                    <span className="hidden sm:inline">{stage.label}</span>
                  </ToggleGroupItem>
                );
              })}
            </ToggleGroup>
          </div>

          {/* Campaign Type Select */}
          <div className="space-y-2">
            <Label>Tipo de Campanha</Label>
            <Select
              value={campaignType}
              onValueChange={(value) => {
                setCampaignType(value as CampaignType);
                setEditableStrategy(null);
              }}
              disabled={!funnelStage}
            >
              <SelectTrigger>
                <SelectValue placeholder={funnelStage ? "Selecione o tipo..." : "Selecione a etapa do funil primeiro"} />
              </SelectTrigger>
              <SelectContent>
                {availableCampaignTypes.map((type) => {
                  const Icon = type.icon;
                  return (
                    <SelectItem key={type.id} value={type.id}>
                      <div className="flex items-center gap-2">
                        <Icon className="w-4 h-4" />
                        <span>{type.title}</span>
                      </div>
                    </SelectItem>
                  );
                })}
              </SelectContent>
            </Select>
          </div>

          {/* Advanced Options */}
          <Collapsible open={showAdvanced} onOpenChange={setShowAdvanced}>
            <CollapsibleTrigger asChild>
              <Button variant="ghost" size="sm" className="w-full justify-between">
                <span className="flex items-center gap-2">
                  <Settings className="w-4 h-4" />
                  Configurações Avançadas
                </span>
                <ChevronDown className={`w-4 h-4 transition-transform ${showAdvanced ? 'rotate-180' : ''}`} />
              </Button>
            </CollapsibleTrigger>
            <CollapsibleContent className="space-y-4 pt-4">
              <div className="space-y-2">
                <Label>Objetivo Personalizado (opcional)</Label>
                <Textarea
                  placeholder="Descreva o objetivo específico desta campanha..."
                  value={customObjective}
                  onChange={(e) => setCustomObjective(e.target.value)}
                  className="min-h-[80px]"
                />
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label>Orçamento Diário</Label>
                  <span className="text-sm font-medium">R$ {dailyBudget}</span>
                </div>
                <div className="flex items-center gap-4">
                  <Slider
                    value={[dailyBudget]}
                    onValueChange={([value]) => setDailyBudget(value)}
                    min={10}
                    max={1000}
                    step={10}
                    className="flex-1"
                  />
                  <Input
                    type="number"
                    value={dailyBudget}
                    onChange={(e) => setDailyBudget(Number(e.target.value))}
                    className="w-24"
                    min={10}
                    max={10000}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label>Duração (dias)</Label>
                  <span className="text-sm font-medium">{duration} dias</span>
                </div>
                <Slider
                  value={[duration]}
                  onValueChange={([value]) => setDuration(value)}
                  min={7}
                  max={90}
                  step={1}
                />
              </div>

              <div className="p-3 bg-muted rounded-lg">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-muted-foreground">Orçamento Total Estimado</span>
                  <span className="font-semibold">R$ {(dailyBudget * duration).toLocaleString('pt-BR')}</span>
                </div>
              </div>
            </CollapsibleContent>
          </Collapsible>

          {/* Generate Button */}
          <Button
            onClick={handleGenerate}
            disabled={!canGenerate || isGenerating}
            className="w-full h-12"
            size="lg"
          >
            {isGenerating ? (
              <>
                <Loader2 className="w-5 h-5 mr-2 animate-spin" />
                Gerando Estratégia...
              </>
            ) : (
              <>
                <Sparkles className="w-5 h-5 mr-2" />
                Gerar Estratégia com IA
              </>
            )}
          </Button>
        </CardContent>
      </Card>

      {/* Editable Strategy Sections */}
      {editableStrategy && selectedClient && (
        <>
          {/* Actions Bar */}
          <div className="flex items-center justify-between gap-4 p-4 bg-muted/50 rounded-lg sticky top-0 z-10">
            <div className="flex items-center gap-2">
              <Check className="w-5 h-5 text-green-500" />
              <span className="font-medium">
                {isEditMode ? 'Editando Campanha' : 'Estratégia Gerada'}
              </span>
            </div>
            <div className="flex items-center gap-2">
              {!isEditMode && (
                <Button variant="outline" size="sm" onClick={handleGenerate} disabled={isGenerating}>
                  <RefreshCw className={`w-4 h-4 mr-2 ${isGenerating ? 'animate-spin' : ''}`} />
                  Regenerar
                </Button>
              )}
              <Button variant="outline" size="sm" onClick={handleSave} disabled={isSaving}>
                {isSaving ? (
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                ) : (
                  <Save className="w-4 h-4 mr-2" />
                )}
                {isEditMode ? 'Salvar Alterações' : 'Salvar Rascunho'}
              </Button>
              <Button 
                size="sm" 
                onClick={handlePublishToMeta}
                disabled={isPublishing || validationErrors.length > 0}
              >
                {isPublishing ? (
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                ) : (
                  <Send className="w-4 h-4 mr-2" />
                )}
                Publicar no Meta
              </Button>
            </div>
          </div>

          {/* Validation Errors */}
          {validationErrors.length > 0 && (
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                <strong>Antes de publicar:</strong>
                <ul className="list-disc pl-4 mt-1">
                  {validationErrors.slice(0, 3).map((err, i) => (
                    <li key={i}>{err}</li>
                  ))}
                  {validationErrors.length > 3 && (
                    <li>...e mais {validationErrors.length - 3} erro(s)</li>
                  )}
                </ul>
              </AlertDescription>
            </Alert>
          )}

          {/* Budget & Duration */}
          <EditableBudgetSection
            strategy={editableStrategy}
            onChange={handleStrategyChange}
          />

          {/* Targeting and Audiences are now inside each Ad Set */}

          {/* Ad Sets with Creatives */}
          <EditableAdSetsSection
            strategy={editableStrategy}
            onChange={handleStrategyChange}
            clientId={selectedClientId}
            clientName={selectedClient.name}
            clientAvatar={selectedClient.avatar || undefined}
          />

          {/* Schedule */}
          <EditableScheduleSection
            strategy={editableStrategy}
            onChange={handleStrategyChange}
          />

          {/* Bidding */}
          <EditableBiddingSection
            strategy={editableStrategy}
            onChange={handleStrategyChange}
          />

          {/* Recommendations */}
          {editableStrategy.recommendations.length > 0 && (
            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="text-base flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-primary" />
                  Recomendações da IA
                </CardTitle>
              </CardHeader>
              <CardContent>
                <ul className="space-y-2">
                  {editableStrategy.recommendations.map((rec, i) => (
                    <li key={i} className="flex items-start gap-2 text-sm">
                      <Check className="w-4 h-4 text-green-500 mt-0.5 flex-shrink-0" />
                      <span>{rec}</span>
                    </li>
                  ))}
                </ul>
              </CardContent>
            </Card>
          )}
        </>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Loader2, Image, Video, FileText, RefreshCw } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import type { CampaignData } from "@/pages/GeradorCampanhas";

interface CreativeGeneratorProps {
  campaignData: CampaignData;
  updateCampaignData: (field: keyof CampaignData, value: unknown) => void;
}

interface Creative {
  id: string;
  adSetName: string;
  headline: string;
  primaryText: string;
  description: string;
  callToAction: string;
  imageDescription: string;
  videoSuggestion?: string;
  variations: {
    headline: string[];
    primaryText: string[];
    description: string[];
  };
}

export function CreativeGenerator({ campaignData, updateCampaignData }: CreativeGeneratorProps) {
  const [loading, setLoading] = useState(false);
  const [creatives, setCreatives] = useState<Creative[]>([]);
  const { toast } = useToast();

  const generateCreatives = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke('generate-campaign-creatives', {
        body: {
          client: campaignData.client,
          funnelStage: campaignData.funnelStage,
          campaignType: campaignData.campaignType,
          configuration: campaignData.configuration
        }
      });

      if (error) throw error;

      if (data?.creatives) {
        setCreatives(data.creatives);
        updateCampaignData("creatives", data.creatives);
      }
    } catch (error) {
      console.error('Erro ao gerar criativos:', error);
      toast({
        title: "Erro",
        description: "Não foi possível gerar os criativos",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (campaignData.configuration && creatives.length === 0) {
      generateCreatives();
    }
  }, [campaignData.configuration]);

  if (!campaignData.client || !campaignData.funnelStage || !campaignData.campaignType || !campaignData.configuration) {
    return (
      <div className="text-center py-8 text-muted-foreground">
        Complete as etapas anteriores para continuar.
      </div>
    );
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin mr-3" />
        <div className="text-center">
          <h3 className="font-medium">Gerando Criativos Inteligentes</h3>
          <p className="text-sm text-muted-foreground">
            Criando variações baseadas no tom de voz e histórico de performance...
          </p>
        </div>
      </div>
    );
  }

  if (creatives.length === 0) {
    return (
      <div className="text-center py-8">
        <Button onClick={generateCreatives} className="flex items-center gap-2">
          <FileText className="w-4 h-4" />
          Gerar Criativos
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold mb-2">Criativos Gerados</h3>
          <p className="text-muted-foreground">
            {creatives.length} conjuntos de criativos gerados para <strong>{campaignData.client.name}</strong>
          </p>
        </div>
        <Button 
          onClick={generateCreatives}
          variant="outline"
          size="sm"
          className="flex items-center gap-2"
        >
          <RefreshCw className="w-4 h-4" />
          Regenerar
        </Button>
      </div>

      <div className="space-y-6">
        {creatives.map((creative, index) => (
          <Card key={creative.id} className="p-6">
            <div className="flex items-center justify-between mb-4">
              <h4 className="font-semibold text-lg">Conjunto {index + 1}: {creative.adSetName}</h4>
              <Badge variant="outline">3 variações</Badge>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              {/* Criativo Principal */}
              <div className="lg:col-span-2 space-y-4">
                <div>
                  <h5 className="font-medium mb-2 flex items-center gap-2">
                    <FileText className="w-4 h-4" />
                    Criativo Principal
                  </h5>
                  <div className="space-y-3">
                    <div className="p-3 bg-muted rounded-lg">
                      <div className="text-xs font-medium text-muted-foreground mb-1">TÍTULO</div>
                      <div className="font-semibold">{creative.headline}</div>
                    </div>
                    <div className="p-3 bg-muted rounded-lg">
                      <div className="text-xs font-medium text-muted-foreground mb-1">TEXTO PRINCIPAL</div>
                      <div className="text-sm">{creative.primaryText}</div>
                    </div>
                    <div className="p-3 bg-muted rounded-lg">
                      <div className="text-xs font-medium text-muted-foreground mb-1">DESCRIÇÃO</div>
                      <div className="text-sm text-muted-foreground">{creative.description}</div>
                    </div>
                    <div className="p-3 bg-primary/5 rounded-lg">
                      <div className="text-xs font-medium text-muted-foreground mb-1">CALL TO ACTION</div>
                      <div className="font-medium text-primary">{creative.callToAction}</div>
                    </div>
                  </div>
                </div>

                {/* Sugestões Visuais */}
                <div>
                  <h5 className="font-medium mb-2 flex items-center gap-2">
                    <Image className="w-4 h-4" />
                    Elementos Visuais
                  </h5>
                  <div className="space-y-2">
                    <div className="p-3 bg-muted rounded-lg">
                      <div className="text-xs font-medium text-muted-foreground mb-1">IMAGEM SUGERIDA</div>
                      <div className="text-sm">{creative.imageDescription}</div>
                    </div>
                    {creative.videoSuggestion && (
                      <div className="p-3 bg-muted rounded-lg">
                        <div className="text-xs font-medium text-muted-foreground mb-1 flex items-center gap-1">
                          <Video className="w-3 h-3" />
                          VÍDEO SUGERIDO
                        </div>
                        <div className="text-sm">{creative.videoSuggestion}</div>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {/* Variações para Teste A/B */}
              <div>
                <h5 className="font-medium mb-3">Variações para Teste A/B</h5>

                <div className="space-y-4">
                  <div>
                    <div className="text-xs font-medium text-muted-foreground mb-2">TÍTULOS ALTERNATIVOS</div>
                    <div className="space-y-1">
                      {creative.variations.headline.map((variation, i) => (
                        <div key={i} className="text-xs p-2 bg-muted rounded text-muted-foreground">
                          {variation}
                        </div>
                      ))}
                    </div>
                  </div>

                  <div>
                    <div className="text-xs font-medium text-muted-foreground mb-2">TEXTOS ALTERNATIVOS</div>
                    <div className="space-y-1">
                      {creative.variations.primaryText.map((variation, i) => (
                        <div key={i} className="text-xs p-2 bg-muted rounded text-muted-foreground">
                          {variation}
                        </div>
                      ))}
                    </div>
                  </div>

                  <div>
                    <div className="text-xs font-medium text-muted-foreground mb-2">DESCRIÇÕES ALTERNATIVAS</div>
                    <div className="space-y-1">
                      {creative.variations.description.map((variation, i) => (
                        <div key={i} className="text-xs p-2 bg-muted rounded text-muted-foreground">
                          {variation}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </Card>
        ))}
      </div>

      {creatives.length > 0 && (
        <Card className="p-4 bg-primary/5 border-primary/20">
          <h4 className="font-medium mb-2">Dicas para Otimização</h4>
          <div className="space-y-1 text-sm text-muted-foreground">
            <p>• Teste todas as variações simultaneamente para identificar as melhores performers</p>
            <p>• Monitore CTR, CPM e taxa de conversão nas primeiras 48h</p>
            <p>• Pause criativos com performance abaixo da média após 3 dias</p>
            <p>• Considere criar vídeos baseados nas imagens de melhor performance</p>
          </div>
        </Card>
      )}
    </div>
  );
}

