import { useState, useEffect, useCallback } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Loader2, Check, Instagram, Image, Film, Play } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { cn } from '@/lib/utils';
import { formatDistanceToNow } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface MediaItem {
  id: string;
  media_type: 'IMAGE' | 'VIDEO' | 'CAROUSEL_ALBUM';
  media_url: string;
  thumbnail_url?: string;
  caption?: string;
  timestamp: string;
  permalink?: string;
}

interface InstagramMediaSelectorProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  clientId: string;
  mediaType: 'IMAGE' | 'VIDEO' | 'CAROUSEL';
  maxSelection?: number;
  onSelect: (urls: string[]) => void;
}

export function InstagramMediaSelector({
  open,
  onOpenChange,
  clientId,
  mediaType,
  maxSelection = mediaType === 'CAROUSEL' ? 10 : 1,
  onSelect,
}: InstagramMediaSelectorProps) {
  const [loading, setLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [copying, setCopying] = useState(false);
  const [copyProgress, setCopyProgress] = useState({ current: 0, total: 0 });
  const [media, setMedia] = useState<MediaItem[]>([]);
  const [selectedMedia, setSelectedMedia] = useState<string[]>([]);
  const [instagramAccount, setInstagramAccount] = useState<{id: string, username: string} | null>(null);
  const [nextCursor, setNextCursor] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(false);
  const { toast } = useToast();

  const fetchInstagramMedia = useCallback(async (cursor?: string) => {
    if (!clientId) return;

    const isLoadingMore = !!cursor;
    if (isLoadingMore) {
      setLoadingMore(true);
    } else {
      setLoading(true);
      setMedia([]);
      setSelectedMedia([]);
    }

    try {
      // First get the client's Instagram account (only on initial load)
      let igAccountId = instagramAccount?.id;

      if (!igAccountId) {
        const { data: clientData, error: clientError } = await supabase
          .from('clients')
          .select('instagram_account_id, instagram_accounts:instagram_account_id(instagram_id, username)')
          .eq('id', clientId)
          .single();

        if (clientError) throw clientError;

        if (!clientData?.instagram_account_id) {
          toast({
            title: 'Instagram não configurado',
            description: 'Este cliente não tem uma conta do Instagram vinculada.',
            variant: 'destructive',
          });
          onOpenChange(false);
          return;
        }

        const igAccount = clientData.instagram_accounts as unknown;
        setInstagramAccount({ id: igAccount.instagram_id, username: igAccount.username });
        igAccountId = igAccount.instagram_id;
      }

      // Fetch media from Instagram
      const { data, error } = await supabase.functions.invoke('fetch-instagram-media', {
        body: {
          clientId,
          instagramId: igAccountId,
          mediaType: mediaType === 'VIDEO' ? 'VIDEO' : 'IMAGE',
          limit: 24,
          after: cursor,
        },
      });

      if (error) throw error;
      if (!data.success) throw new Error(data.error);

      if (isLoadingMore) {
        setMedia(prev => [...prev, ...(data.media || [])]);
      } else {
        setMedia(data.media || []);
      }

      setNextCursor(data.nextCursor || null);
      setHasMore(data.hasMore || false);
    } catch (err: unknown) {
      console.error('Error fetching Instagram media:', err);
      toast({
        title: 'Erro ao carregar mídia',
        description: err.message || 'Não foi possível carregar a mídia do Instagram.',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  }, [clientId, mediaType, toast, onOpenChange, instagramAccount]);

  const handleLoadMore = () => {
    if (nextCursor && !loadingMore) {
      fetchInstagramMedia(nextCursor);
    }
  };

  useEffect(() => {
    if (open) {
      setInstagramAccount(null);
      setNextCursor(null);
      setHasMore(false);
      fetchInstagramMedia();
    }
  }, [open]);

  const toggleSelection = (mediaUrl: string) => {
    setSelectedMedia(prev => {
      if (prev.includes(mediaUrl)) {
        return prev.filter(url => url !== mediaUrl);
      }
      if (prev.length >= maxSelection) {
        if (maxSelection === 1) {
          return [mediaUrl];
        }
        toast({
          title: 'Limite atingido',
          description: `Você pode selecionar no máximo ${maxSelection} itens.`,
        });
        return prev;
      }
      return [...prev, mediaUrl];
    });
  };

  // Check if URL is already from our storage (permanent URL)
  const isStorageUrl = (url: string): boolean => {
    return url.includes('supabase.co/storage') || url.includes('.supabase.co');
  };

  // Copy external images to our storage to get permanent URLs
  const copyImagesToStorage = async (imageUrls: string[]): Promise<string[]> => {
    const permanentUrls: string[] = [];

    for (let i = 0; i < imageUrls.length; i++) {
      const url = imageUrls[i];
      setCopyProgress({ current: i + 1, total: imageUrls.length });

      // Skip if already a storage URL
      if (isStorageUrl(url)) {
        permanentUrls.push(url);
        continue;
      }

      try {
        const { data, error } = await supabase.functions.invoke('copy-external-image', {
          body: { imageUrl: url, folder: 'instagram-media' }
        });

        if (error) throw error;

        if (data.success && data.url) {
          permanentUrls.push(data.url);
        } else {
          console.error('Failed to copy image:', data.error);
          // Keep original URL as fallback
          permanentUrls.push(url);
          toast({
            title: "Aviso",
            description: `Não foi possível copiar uma imagem. Usando URL original.`,
            variant: "destructive"
          });
        }
      } catch (err) {
        console.error('Error copying image:', err);
        // Keep original URL as fallback
        permanentUrls.push(url);
      }
    }

    return permanentUrls;
  };

  const handleConfirm = async () => {
    if (selectedMedia.length === 0) return;

    setCopying(true);
    setCopyProgress({ current: 0, total: selectedMedia.length });

    try {
      // Copy all selected media to our storage
      const permanentUrls = await copyImagesToStorage(selectedMedia);

      toast({
        title: "Mídia copiada",
        description: `${permanentUrls.length} item(ns) salvo(s) com sucesso.`,
      });

      onSelect(permanentUrls);
      onOpenChange(false);
    } catch (err) {
      console.error('Error in handleConfirm:', err);
      toast({
        title: "Erro",
        description: "Ocorreu um erro ao copiar a mídia.",
        variant: "destructive"
      });
    } finally {
      setCopying(false);
      setCopyProgress({ current: 0, total: 0 });
    }
  };

  const getMediaTypeLabel = () => {
    switch (mediaType) {
      case 'VIDEO':
        return 'vídeos';
      case 'CAROUSEL':
        return 'imagens';
      default:
        return 'imagens';
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[800px] max-h-[85vh] overflow-hidden flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Instagram className="h-5 w-5" />
            Selecionar do Instagram
            {instagramAccount && (
              <span className="text-sm font-normal text-muted-foreground">
                @{instagramAccount.username}
              </span>
            )}
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 min-h-0">
          {copying ? (
            <div className="flex flex-col items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-primary" />
              <p className="mt-2 text-sm text-muted-foreground">
                Copiando mídia... ({copyProgress.current}/{copyProgress.total})
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                Salvando no servidor para garantir que não expirem
              </p>
            </div>
          ) : loading ? (
            <div className="flex flex-col items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
              <p className="mt-2 text-sm text-muted-foreground">
                Carregando {getMediaTypeLabel()}...
              </p>
            </div>
          ) : media.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-muted-foreground">
              {mediaType === 'VIDEO' ? (
                <Film className="h-12 w-12 mb-2 opacity-50" />
              ) : (
                <Image className="h-12 w-12 mb-2 opacity-50" />
              )}
              <p>Nenhum {mediaType === 'VIDEO' ? 'vídeo' : 'imagem'} encontrado</p>
            </div>
          ) : (
            <ScrollArea className="h-[450px]">
              <div className="p-1">
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
                  {media.map((item) => {
                    const isSelected = selectedMedia.includes(item.media_url);
                    const thumbnailUrl = item.thumbnail_url || item.media_url;

                    return (
                      <div
                        key={item.id}
                        onClick={() => toggleSelection(item.media_url)}
                        className={cn(
                          'relative aspect-square rounded-lg overflow-hidden cursor-pointer group transition-all',
                          'border-2',
                          isSelected 
                            ? 'border-primary ring-2 ring-primary/30' 
                            : 'border-transparent hover:border-muted-foreground/30'
                        )}
                      >
                        <img
                          src={thumbnailUrl}
                          alt={item.caption?.slice(0, 50) || 'Instagram media'}
                          className="w-full h-full object-cover"
                          loading="lazy"
                        />

                        {/* Selection indicator */}
                        {isSelected && (
                          <div className="absolute inset-0 bg-primary/30 flex items-center justify-center">
                            <div className="bg-primary text-primary-foreground rounded-full p-1.5">
                              <Check className="h-4 w-4" />
                            </div>
                          </div>
                        )}

                        {/* Video indicator */}
                        {item.media_type === 'VIDEO' && (
                          <div className="absolute top-2 right-2 bg-black/60 text-white p-1 rounded">
                            <Play className="h-3 w-3" />
                          </div>
                        )}

                        {/* Carousel indicator */}
                        {item.media_type === 'CAROUSEL_ALBUM' && (
                          <div className="absolute top-2 right-2 bg-black/60 text-white px-1.5 py-0.5 rounded text-xs">
                            📷+
                          </div>
                        )}

                        {/* Hover info */}
                        <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/70 to-transparent p-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <p className="text-white text-xs truncate">
                            {item.caption?.slice(0, 40) || 'Sem legenda'}
                            {item.caption && item.caption.length > 40 ? '...' : ''}
                          </p>
                          <p className="text-white/70 text-xs">
                            {formatDistanceToNow(new Date(item.timestamp), { addSuffix: true, locale: ptBR })}
                          </p>
                        </div>
                      </div>
                    );
                  })}
                </div>

                {/* Load More Button */}
                {hasMore && (
                  <div className="flex justify-center mt-4 pb-2">
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      onClick={handleLoadMore}
                      disabled={loadingMore}
                    >
                      {loadingMore ? (
                        <>
                          <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                          Carregando...
                        </>
                      ) : (
                        'Carregar mais'
                      )}
                    </Button>
                  </div>
                )}
              </div>
            </ScrollArea>
          )}
        </div>

        <DialogFooter className="flex-shrink-0 border-t pt-4">
          <div className="flex items-center justify-between w-full">
            <p className="text-sm text-muted-foreground">
              {selectedMedia.length} de {maxSelection} selecionado(s)
            </p>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => onOpenChange(false)} disabled={copying}>
                Cancelar
              </Button>
              <Button 
                onClick={handleConfirm} 
                disabled={selectedMedia.length === 0 || copying}
              >
                {copying ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Copiando...
                  </>
                ) : (
                  `Usar selecionado${selectedMedia.length > 1 ? 's' : ''}`
                )}
              </Button>
            </div>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useCallback } from 'react';
import { Upload, X, Image, Film, Loader2, Sparkles, Pencil, Instagram, Play, ExternalLink } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { cn } from '@/lib/utils';
import { InstagramMediaSelector } from './InstagramMediaSelector';
import { ImageEditorModal } from '@/components/image-editor/ImageEditorModal';
interface MediaUploaderProps {
  mediaUrls: string[];
  onChange: (urls: string[]) => void;
  type: 'IMAGE' | 'VIDEO' | 'CAROUSEL';
  maxFiles?: number;
  clientId?: string;
  companyId?: string;
  creativeContext?: {
    title?: string;
    description?: string;
    body?: string;
  };
  thumbnailUrl?: string; // Optional thumbnail for video fallback
  externalVideoUrl?: string; // Optional external link for non-playable videos
}

export function MediaUploader({
  mediaUrls,
  onChange,
  type,
  maxFiles = type === 'CAROUSEL' ? 10 : 1,
  clientId,
  companyId,
  creativeContext,
  thumbnailUrl,
  externalVideoUrl,
}: MediaUploaderProps) {
  const [uploading, setUploading] = useState(false);
  const [generatingAI, setGeneratingAI] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const [showInstagramSelector, setShowInstagramSelector] = useState(false);
  const [showImageEditor, setShowImageEditor] = useState(false);
  const { toast } = useToast();

  const acceptTypes = type === 'VIDEO' 
    ? 'video/mp4,video/mov,video/avi'
    : 'image/jpeg,image/png,image/webp,image/gif';

  // Check if a video URL is a non-playable Facebook link
  const isFacebookVideoLink = (url: string) => {
    return url && (url.includes('facebook.com/') || url.includes('fb.com/'));
  };

  // Get the external video URL (Facebook page link)
  const getExternalVideoLink = (url: string) => {
    if (isFacebookVideoLink(url)) {
      return url;
    }
    return externalVideoUrl || null;
  };

  const handleGenerateAIImage = useCallback(async () => {
    if (!clientId) {
      toast({
        title: 'Erro',
        description: 'Cliente não identificado',
        variant: 'destructive',
      });
      return;
    }

    setGeneratingAI(true);
    try {
      // Build context-aware prompt from creative data
      let contextPrompt = '';
      if (creativeContext) {
        const parts = [];
        if (creativeContext.title) parts.push(`Título: "${creativeContext.title}"`);
        if (creativeContext.body) parts.push(`Texto: "${creativeContext.body}"`);
        if (creativeContext.description) parts.push(`Descrição: "${creativeContext.description}"`);
        if (parts.length > 0) {
          contextPrompt = `Crie uma imagem para um anúncio com o seguinte conteúdo: ${parts.join('. ')}. A imagem deve complementar e reforçar a mensagem do anúncio.`;
        }
      }

      const { data, error } = await supabase.functions.invoke('generate-ai-campaign-image', {
        body: { 
          clientId,
          prompt: contextPrompt || undefined,
        },
      });

      if (error) throw error;

      if (data?.success && data?.imageUrl) {
        // Replace the first image or add if empty
        if (type === 'CAROUSEL') {
          onChange([...mediaUrls, data.imageUrl]);
        } else {
          onChange([data.imageUrl]);
        }

        toast({
          title: 'Imagem gerada!',
          description: 'A imagem foi criada com base na identidade visual do cliente.',
        });
      } else {
        throw new Error(data?.error || 'Erro ao gerar imagem');
      }
    } catch (err: unknown) {
      console.error('AI generation error:', err);
      toast({
        title: 'Erro na geração',
        description: err.message || 'Não foi possível gerar a imagem',
        variant: 'destructive',
      });
    } finally {
      setGeneratingAI(false);
    }
  }, [clientId, mediaUrls, onChange, toast, type]);

  const handleUpload = useCallback(async (files: FileList) => {
    if (files.length === 0) return;

    const filesToUpload = Array.from(files).slice(0, maxFiles - mediaUrls.length);
    if (filesToUpload.length === 0) {
      toast({
        title: 'Limite atingido',
        description: `Máximo de ${maxFiles} arquivo(s) permitido(s)`,
        variant: 'destructive',
      });
      return;
    }

    setUploading(true);
    const newUrls: string[] = [];

    try {
      for (const file of filesToUpload) {
        const fileExt = file.name.split('.').pop()?.toLowerCase();
        const fileName = `${crypto.randomUUID()}.${fileExt}`;
        const filePath = `campaign-creatives/${fileName}`;

        const { error: uploadError } = await supabase.storage
          .from('scheduled-posts-media')
          .upload(filePath, file, { 
            contentType: file.type,
            upsert: false 
          });

        if (uploadError) throw uploadError;

        const { data: urlData } = supabase.storage
          .from('scheduled-posts-media')
          .getPublicUrl(filePath);

        newUrls.push(urlData.publicUrl);
      }

      onChange([...mediaUrls, ...newUrls]);
      toast({
        title: 'Upload concluído',
        description: `${newUrls.length} arquivo(s) enviado(s)`,
      });
    } catch (err: unknown) {
      console.error('Upload error:', err);
      toast({
        title: 'Erro no upload',
        description: err.message,
        variant: 'destructive',
      });
    } finally {
      setUploading(false);
    }
  }, [mediaUrls, onChange, maxFiles, toast]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    handleUpload(e.dataTransfer.files);
  }, [handleUpload]);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
  }, []);

  const removeMedia = (index: number) => {
    onChange(mediaUrls.filter((_, i) => i !== index));
  };

  const canAddMore = mediaUrls.length < maxFiles;
  const showAIButton = type !== 'VIDEO' && clientId;

  return (
    <div className="space-y-3">
      {/* Preview grid */}
      {mediaUrls.length > 0 && (
        <div className={cn(
          'grid gap-2',
          type === 'CAROUSEL' ? 'grid-cols-5' : 'grid-cols-1'
        )}>
          {mediaUrls.map((url, index) => {
            const isNonPlayableVideo = type === 'VIDEO' && isFacebookVideoLink(url);
            const externalLink = getExternalVideoLink(url);
            const displayThumbnail = isNonPlayableVideo && thumbnailUrl;

            return (
              <div
                key={url}
                className="relative aspect-square rounded-lg overflow-hidden border bg-muted group"
              >
                {type === 'VIDEO' ? (
                  isNonPlayableVideo ? (
                    // Non-playable Facebook video - show thumbnail with play overlay
                    <div className="relative w-full h-full">
                      {displayThumbnail ? (
                        <img
                          src={thumbnailUrl}
                          alt="Video thumbnail"
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center bg-muted">
                          <Film className="w-12 h-12 text-muted-foreground" />
                        </div>
                      )}
                      {/* Play overlay */}
                      <button
                        onClick={() => externalLink && window.open(externalLink, '_blank')}
                        className="absolute inset-0 flex items-center justify-center bg-black/40 hover:bg-black/50 transition-colors cursor-pointer"
                        title="Clique para ver o vídeo no Facebook"
                      >
                        <div className="flex flex-col items-center gap-2">
                          <div className="w-14 h-14 rounded-full bg-white/90 flex items-center justify-center shadow-lg">
                            <Play className="w-7 h-7 text-primary fill-primary ml-1" />
                          </div>
                          <span className="text-white text-xs flex items-center gap-1">
                            <ExternalLink className="w-3 h-3" />
                            Ver no Facebook
                          </span>
                        </div>
                      </button>
                    </div>
                  ) : (
                    // Playable video
                    <video
                      src={url}
                      className="w-full h-full object-cover"
                      muted
                      controls
                    />
                  )
                ) : (
                  <img
                    src={url}
                    alt={`Media ${index + 1}`}
                    className="w-full h-full object-cover"
                  />
                )}
                <button
                  onClick={() => removeMedia(index)}
                  className="absolute top-1 right-1 p-1 rounded-full bg-destructive text-destructive-foreground opacity-0 group-hover:opacity-100 transition-opacity z-10"
                >
                  <X className="h-3 w-3" />
                </button>
                {type === 'CAROUSEL' && (
                  <div className="absolute bottom-1 left-1 px-1.5 py-0.5 rounded text-xs bg-black/60 text-white">
                    {index + 1}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Upload area */}
      {canAddMore && (
        <div
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          className={cn(
            'border-2 border-dashed rounded-lg p-6 text-center transition-colors',
            dragOver ? 'border-primary bg-primary/5' : 'border-muted-foreground/25',
            (uploading || generatingAI) && 'opacity-50 pointer-events-none'
          )}
        >
          {uploading ? (
            <div className="flex flex-col items-center gap-2">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
              <p className="text-sm text-muted-foreground">Enviando...</p>
            </div>
          ) : generatingAI ? (
            <div className="flex flex-col items-center gap-2">
              <Sparkles className="h-8 w-8 animate-pulse text-primary" />
              <p className="text-sm text-muted-foreground">Gerando imagem com IA...</p>
            </div>
          ) : (
            <>
              <div className="flex justify-center mb-2">
                {type === 'VIDEO' ? (
                  <Film className="h-10 w-10 text-muted-foreground" />
                ) : (
                  <Image className="h-10 w-10 text-muted-foreground" />
                )}
              </div>
              <p className="text-sm text-muted-foreground mb-2">
                Arraste {type === 'VIDEO' ? 'vídeos' : 'imagens'} aqui ou
              </p>
              <div className="flex flex-col sm:flex-row items-center justify-center gap-2 flex-wrap">
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    const input = document.createElement('input');
                    input.type = 'file';
                    input.accept = acceptTypes;
                    input.multiple = type === 'CAROUSEL';
                    input.onchange = (e) => {
                      const files = (e.target as HTMLInputElement).files;
                      if (files) handleUpload(files);
                    };
                    input.click();
                  }}
                >
                  <Upload className="h-4 w-4 mr-2" />
                  Selecionar arquivo
                </Button>
                {clientId && (
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => setShowInstagramSelector(true)}
                  >
                    <Instagram className="h-4 w-4 mr-2" />
                    Do Instagram
                  </Button>
                )}
                {showAIButton && (
                  <Button
                    type="button"
                    variant="secondary"
                    size="sm"
                    onClick={handleGenerateAIImage}
                  >
                    <Sparkles className="h-4 w-4 mr-2" />
                    Gerar com IA
                  </Button>
                )}
              </div>
              <p className="text-xs text-muted-foreground mt-2">
                {type === 'CAROUSEL' 
                  ? `${mediaUrls.length}/${maxFiles} arquivos`
                  : type === 'VIDEO'
                  ? 'MP4, MOV ou AVI'
                  : 'JPG, PNG, WebP ou GIF'}
              </p>
            </>
          )}
        </div>
      )}

      {/* Edit image button when image exists */}
      {showAIButton && mediaUrls.length > 0 && type !== 'CAROUSEL' && (
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="w-full"
          onClick={() => setShowImageEditor(true)}
        >
          <Pencil className="h-4 w-4 mr-2" />
          Editar a imagem
        </Button>
      )}

      {/* Image Editor Modal */}
      {showAIButton && mediaUrls.length > 0 && (
        <ImageEditorModal
          open={showImageEditor}
          onOpenChange={setShowImageEditor}
          images={mediaUrls.filter(url => !url.match(/\.(mp4|webm|mov|avi)$/i))}
          onSave={(newUrls) => {
            onChange(newUrls);
            setShowImageEditor(false);
          }}
          clientId={clientId || ''}
          companyId={companyId || ''}
        />
      )}

      {/* Instagram Media Selector Modal */}
      {clientId && (
        <InstagramMediaSelector
          open={showInstagramSelector}
          onOpenChange={setShowInstagramSelector}
          clientId={clientId}
          mediaType={type}
          maxSelection={type === 'CAROUSEL' ? Math.min(10, maxFiles - mediaUrls.length) : 1}
          onSelect={(urls) => {
            if (type === 'CAROUSEL') {
              onChange([...mediaUrls, ...urls]);
            } else {
              onChange(urls);
            }
          }}
        />
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Loader2, Plus, FileText } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

interface CarouselSlide {
  slide_number: number;
  headline: string;
  body_text: string;
  image_url?: string;
}

interface GeneratedCarousel {
  id: string;
  carousel_type: string;
  theme: string;
  slides: CarouselSlide[];
  caption: string;
  hashtags: string;
}

interface ContentPlan {
  id: string;
  name: string;
  created_at: string;
}

interface Props {
  carousel: GeneratedCarousel;
  clientId: string;
  companyId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export function SendCarouselToPlanModal({ 
  carousel, 
  clientId, 
  companyId, 
  open, 
  onOpenChange, 
  onSuccess 
}: Props) {
  const [plans, setPlans] = useState<ContentPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<string>('');
  const [createNew, setCreateNew] = useState(false);
  const [newPlanName, setNewPlanName] = useState('');

  useEffect(() => {
    if (open) {
      fetchPlans();
    }
  }, [open, clientId]);

  const fetchPlans = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('content_plans')
        .select('id, name, created_at')
        .eq('client_id', clientId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setPlans(data || []);

      if (data && data.length > 0) {
        setSelectedPlan(data[0].id);
        setCreateNew(false);
      } else {
        setCreateNew(true);
      }
    } catch (error) {
      console.error('Error fetching plans:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSend = async () => {
    if (createNew && !newPlanName.trim()) {
      toast.error('Digite um nome para o planejamento');
      return;
    }

    setSending(true);
    try {
      let planId = selectedPlan;

      // Get current user
      const { data: userData } = await supabase.auth.getUser();
      if (!userData.user) throw new Error('Usuário não autenticado');

      // Create new plan if needed
      if (createNew) {
        const now = new Date();
        const { data: newPlan, error: createError } = await supabase
          .from('content_plans')
          .insert({
            client_id: clientId,
            company_id: companyId,
            name: newPlanName.trim(),
            status: 'draft',
            user_id: userData.user.id,
            month: now.getMonth() + 1,
            year: now.getFullYear(),
          })
          .select()
          .single();

        if (createError) throw createError;
        planId = newPlan.id;
      }

      // Get current max order
      const { data: existingPosts } = await supabase
        .from('content_plan_posts')
        .select('order_index')
        .eq('content_plan_id', planId)
        .order('order_index', { ascending: false })
        .limit(1);

      const nextOrder = (existingPosts?.[0]?.order_index ?? -1) + 1;

      // Add carousel post
      const fullCaption = carousel.hashtags 
        ? `${carousel.caption}\n\n${carousel.hashtags}` 
        : carousel.caption;

      const { data: createdPost, error: insertError } = await supabase
        .from('content_plan_posts')
        .insert({
          content_plan_id: planId,
          headline: carousel.theme || 'Carrossel',
          caption: fullCaption,
          post_type: 'carrossel',
          status: 'pending',
          order_index: nextOrder,
        })
        .select('id')
        .single();

      if (insertError) throw insertError;

      // Add each slide
      if (createdPost) {
        const slidesData = carousel.slides.map((slide, idx) => ({
          post_id: createdPost.id,
          slide_number: slide.slide_number || idx + 1,
          headline: slide.headline,
          body_text: slide.body_text,
          image_url: slide.image_url,
        }));

        if (slidesData.length > 0) {
          const { error: slidesError } = await supabase
            .from('content_plan_slides')
            .insert(slidesData);

          if (slidesError) {
            console.error('Error inserting slides:', slidesError);
          }
        }
      }
      toast.success(createNew ? 'Planejamento criado e carrossel adicionado!' : 'Carrossel enviado para o planejamento!');
      onSuccess?.();
      onOpenChange(false);
    } catch (error: unknown) {
      console.error('Error sending to plan:', error);
      toast.error('Erro ao enviar: ' + error.message);
    } finally {
      setSending(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            Enviar para Planejamento
          </DialogTitle>
        </DialogHeader>

        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : (
          <div className="space-y-4">
            {plans.length > 0 && (
              <div className="space-y-3">
                <Label>Selecione um planejamento existente</Label>
                <RadioGroup
                  value={createNew ? '' : selectedPlan}
                  onValueChange={(value) => {
                    setSelectedPlan(value);
                    setCreateNew(false);
                  }}
                >
                  {plans.map((plan) => (
                    <div key={plan.id} className="flex items-center space-x-2">
                      <RadioGroupItem value={plan.id} id={plan.id} />
                      <Label htmlFor={plan.id} className="flex-1 cursor-pointer">
                        <span>{plan.name}</span>
                        <span className="text-xs text-muted-foreground ml-2">
                          {format(new Date(plan.created_at), "dd/MM/yyyy", { locale: ptBR })}
                        </span>
                      </Label>
                    </div>
                  ))}
                </RadioGroup>
              </div>
            )}

            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <Button
                  variant={createNew ? "default" : "outline"}
                  size="sm"
                  onClick={() => setCreateNew(true)}
                >
                  <Plus className="h-4 w-4 mr-1" />
                  Criar Novo Planejamento
                </Button>
              </div>

              {createNew && (
                <div className="space-y-2">
                  <Label>Nome do novo planejamento</Label>
                  <Input
                    value={newPlanName}
                    onChange={(e) => setNewPlanName(e.target.value)}
                    placeholder="Ex: Planejamento Janeiro 2025"
                  />
                </div>
              )}
            </div>

            <div className="flex gap-2 pt-4">
              <Button variant="outline" onClick={() => onOpenChange(false)} className="flex-1">
                Cancelar
              </Button>
              <Button onClick={handleSend} disabled={sending} className="flex-1">
                {sending ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : (
                  <FileText className="h-4 w-4 mr-2" />
                )}
                {createNew ? 'Criar e Enviar' : 'Enviar'}
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Loader2, Plus, Presentation } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

interface CarouselSlide {
  slide_number: number;
  headline: string;
  body_text: string;
  image_url?: string;
}

interface GeneratedCarousel {
  id: string;
  carousel_type: string;
  theme: string;
  slides: CarouselSlide[];
  caption: string;
  hashtags: string;
}

interface ContentPresentation {
  id: string;
  name: string;
  created_at: string;
}

interface Props {
  carousel: GeneratedCarousel;
  clientId: string;
  companyId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
}

export function SendCarouselToPresentationModal({ 
  carousel, 
  clientId, 
  companyId, 
  open, 
  onOpenChange, 
  onSuccess 
}: Props) {
  const [presentations, setPresentations] = useState<ContentPresentation[]>([]);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [selectedPresentation, setSelectedPresentation] = useState<string>('');
  const [createNew, setCreateNew] = useState(false);
  const [newPresentationName, setNewPresentationName] = useState('');

  useEffect(() => {
    if (open) {
      fetchPresentations();
    }
  }, [open, clientId]);

  const fetchPresentations = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('content_presentations')
        .select('id, name, created_at')
        .eq('client_id', clientId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setPresentations(data || []);

      if (data && data.length > 0) {
        setSelectedPresentation(data[0].id);
        setCreateNew(false);
      } else {
        setCreateNew(true);
      }
    } catch (error) {
      console.error('Error fetching presentations:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSend = async () => {
    if (createNew && !newPresentationName.trim()) {
      toast.error('Digite um nome para a apresentação');
      return;
    }

    setSending(true);
    try {
      let presentationId = selectedPresentation;

      // Get current user
      const { data: userData } = await supabase.auth.getUser();
      if (!userData.user) throw new Error('Usuário não autenticado');

      // Create new presentation if needed
      if (createNew) {
        const now = new Date();
        const { data: newPresentation, error: createError } = await supabase
          .from('content_presentations')
          .insert({
            client_id: clientId,
            company_id: companyId,
            name: newPresentationName.trim(),
            status: 'draft',
            user_id: userData.user.id,
            month: now.getMonth() + 1,
            year: now.getFullYear(),
          })
          .select()
          .single();

        if (createError) throw createError;
        presentationId = newPresentation.id;
      }

      // Get current max order
      const { data: existingCreatives } = await supabase
        .from('presentation_creatives')
        .select('order_index')
        .eq('presentation_id', presentationId)
        .order('order_index', { ascending: false })
        .limit(1);

      const nextOrder = (existingCreatives?.[0]?.order_index ?? -1) + 1;

      // Add creative to presentation
      const fullCaption = carousel.hashtags 
        ? `${carousel.caption}\n\n${carousel.hashtags}` 
        : carousel.caption;

      const { data: createdCreative, error: insertError } = await supabase
        .from('presentation_creatives')
        .insert({
          presentation_id: presentationId,
          headline: carousel.theme || 'Carrossel',
          caption: fullCaption,
          creative_type: 'carrossel',
          current_status: 'pending',
          order_index: nextOrder,
        })
        .select('id')
        .single();

      if (insertError) throw insertError;

      // Add each slide as media
      if (createdCreative) {
        const mediaData = carousel.slides
          .filter(slide => slide.image_url)
          .map((slide, idx) => ({
            creative_id: createdCreative.id,
            media_type: 'image' as const,
            media_url: slide.image_url!,
            order_index: idx,
          }));

        if (mediaData.length > 0) {
          const { error: mediaError } = await supabase
            .from('creative_media')
            .insert(mediaData);

          if (mediaError) {
            console.error('Error inserting media:', mediaError);
          }
        }
      }

      toast.success(createNew ? 'Apresentação criada e carrossel adicionado!' : 'Carrossel enviado para a apresentação!');
      onSuccess?.();
      onOpenChange(false);
    } catch (error: unknown) {
      console.error('Error sending to presentation:', error);
      toast.error('Erro ao enviar: ' + error.message);
    } finally {
      setSending(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Presentation className="h-5 w-5" />
            Enviar para Apresentação
          </DialogTitle>
        </DialogHeader>

        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : (
          <div className="space-y-4">
            {presentations.length > 0 && (
              <div className="space-y-3">
                <Label>Selecione uma apresentação existente</Label>
                <RadioGroup
                  value={createNew ? '' : selectedPresentation}
                  onValueChange={(value) => {
                    setSelectedPresentation(value);
                    setCreateNew(false);
                  }}
                >
                  {presentations.map((presentation) => (
                    <div key={presentation.id} className="flex items-center space-x-2">
                      <RadioGroupItem value={presentation.id} id={presentation.id} />
                      <Label htmlFor={presentation.id} className="flex-1 cursor-pointer">
                        <span>{presentation.name}</span>
                        <span className="text-xs text-muted-foreground ml-2">
                          {format(new Date(presentation.created_at), "dd/MM/yyyy", { locale: ptBR })}
                        </span>
                      </Label>
                    </div>
                  ))}
                </RadioGroup>
              </div>
            )}

            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <Button
                  variant={createNew ? "default" : "outline"}
                  size="sm"
                  onClick={() => setCreateNew(true)}
                >
                  <Plus className="h-4 w-4 mr-1" />
                  Criar Nova Apresentação
                </Button>
              </div>

              {createNew && (
                <div className="space-y-2">
                  <Label>Nome da nova apresentação</Label>
                  <Input
                    value={newPresentationName}
                    onChange={(e) => setNewPresentationName(e.target.value)}
                    placeholder="Ex: Criativos Janeiro 2025"
                  />
                </div>
              )}
            </div>

            <div className="flex gap-2 pt-4">
              <Button variant="outline" onClick={() => onOpenChange(false)} className="flex-1">
                Cancelar
              </Button>
              <Button onClick={handleSend} disabled={sending} className="flex-1">
                {sending ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : (
                  <Presentation className="h-4 w-4 mr-2" />
                )}
                {createNew ? 'Criar e Enviar' : 'Enviar'}
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useState, useRef, useMemo } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Progress } from "@/components/ui/progress";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { 
  Loader2, CheckCircle, XCircle, AlertCircle, 
  AlertTriangle, Database, Play, BarChart3
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { AutomationHierarchyTree } from "./automation/AutomationHierarchyTree";
import { RuleExecutionProgress } from "./automation/RuleExecutionProgress";
import { 
  CampaignHierarchy, 
  RuleExecution, 
  ProgressUpdate,
  ExecutionPhase 
} from "./automation/types";

interface AutomationProgressModalProps {
  open: boolean;
  executionId: string;
  clientId: string;
  onClose: () => void;
  onComplete?: () => void;
}

export function AutomationProgressModal({
  open,
  executionId,
  clientId,
  onClose,
  onComplete
}: AutomationProgressModalProps) {
  const [updates, setUpdates] = useState<ProgressUpdate[]>([]);
  const [isComplete, setIsComplete] = useState(false);
  const [isTimedOut, setIsTimedOut] = useState(false);
  const [activeTab, setActiveTab] = useState("progress");
  const lastUpdateTimeRef = useRef<number>(Date.now());
  const timeoutCheckRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (!open || !executionId) return;

    // Reset state
    setUpdates([]);
    setIsComplete(false);
    setIsTimedOut(false);
    setActiveTab("progress");
    lastUpdateTimeRef.current = Date.now();

    // Buscar updates existentes
    const fetchExistingUpdates = async () => {
      const { data } = await supabase
        .from('automation_execution_progress')
        .select('*')
        .eq('execution_id', executionId)
        .order('created_at', { ascending: true });

      if (data) {
        setUpdates(data as ProgressUpdate[]);
        lastUpdateTimeRef.current = Date.now();

        // Check if already complete
        const hasCompletion = data.some(u => u.rule_name === 'Conclusão');
        if (hasCompletion) {
          setIsComplete(true);
        }
      }
    };
    fetchExistingUpdates();

    // Subscribe para novos updates
    const subscription = supabase
      .channel(`automation-progress-${executionId}`)
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'automation_execution_progress',
        filter: `execution_id=eq.${executionId}`
      }, payload => {
        const newUpdate = payload.new as ProgressUpdate;
        setUpdates(prev => [...prev, newUpdate]);
        lastUpdateTimeRef.current = Date.now();

        if (newUpdate.rule_name === 'Conclusão') {
          setIsComplete(true);
          onComplete?.();
        }
      })
      .on('postgres_changes', {
        event: 'UPDATE',
        schema: 'public',
        table: 'automation_execution_progress',
        filter: `execution_id=eq.${executionId}`
      }, payload => {
        const updatedRecord = payload.new as ProgressUpdate;
        setUpdates(prev => prev.map(u => 
          u.id === updatedRecord.id ? updatedRecord : u
        ));
        lastUpdateTimeRef.current = Date.now();
      })
      .subscribe();

    // Timeout detection - 5 minutos sem updates (300 segundos)
    // Aumentado porque execuções com muitas campanhas podem demorar
    timeoutCheckRef.current = setInterval(() => {
      const timeSinceLastUpdate = Date.now() - lastUpdateTimeRef.current;
      if (timeSinceLastUpdate > 300000 && !isComplete) {
        setIsTimedOut(true);
      }
    }, 10000);

    return () => {
      subscription.unsubscribe();
      if (timeoutCheckRef.current) {
        clearInterval(timeoutCheckRef.current);
      }
    };
  }, [open, executionId]);

  // Determinar fase atual baseado nos updates
  const currentPhase = useMemo((): ExecutionPhase => {
    if (isComplete) {
      return { phase: 'completed', message: 'Execução concluída', progress: 100 };
    }
    if (isTimedOut) {
      return { phase: 'error', message: 'Timeout na execução', progress: 100 };
    }

    const phaseUpdates = updates.filter(u => 
      u.metadata?.phase || u.rule_name === 'Fase'
    );

    // Verificar se ainda está coletando estrutura
    const hasHierarchy = updates.some(u => u.rule_name === 'Estrutura Completa');
    const hasMetrics = updates.some(u => u.rule_name === 'Métricas Carregadas');

    if (!hasHierarchy) {
      const collectingUpdates = updates.filter(u => 
        u.rule_name === 'Coleta' || u.message?.includes('Buscando') || u.message?.includes('Encontrad')
      );
      return { 
        phase: 'collecting', 
        message: collectingUpdates.length > 0 
          ? collectingUpdates[collectingUpdates.length - 1].message 
          : 'Buscando estrutura no Facebook...', 
        progress: 15 
      };
    }

    if (!hasMetrics) {
      return { phase: 'metrics', message: 'Carregando métricas...', progress: 40 };
    }

    return { phase: 'applying', message: 'Aplicando regras...', progress: 70 };
  }, [updates, isComplete, isTimedOut]);

  // Extrair hierarquia dos updates
  const hierarchy = useMemo((): CampaignHierarchy[] => {
    const hierarchyUpdate = updates.find(u => u.rule_name === 'Estrutura Completa');
    if (hierarchyUpdate?.metadata?.hierarchy) {
      return hierarchyUpdate.metadata.hierarchy;
    }
    return [];
  }, [updates]);

  // Construir progresso das regras baseado nos updates
  const ruleExecutions = useMemo((): RuleExecution[] => {
    const rulesMap = new Map<string, RuleExecution>();

    // Processar updates para construir estrutura de regras
    updates.forEach(update => {
      // Ignorar logs de sistema
      if (['Coleta', 'Consulta', 'Análise', 'Validação', 'Conclusão', 'Fase', 
           'Estrutura Completa', 'Métricas Carregadas', 'Sistema'].includes(update.rule_name)) {
        return;
      }

      const ruleKey = update.rule_name;

      if (!rulesMap.has(ruleKey)) {
        rulesMap.set(ruleKey, {
          ruleId: ruleKey,
          ruleName: update.rule_name,
          entityType: update.entity_type as 'campaign' | 'adset' | 'ad',
          actionType: 'unknown',
          campaignObjectives: [],
          timeWindowDays: 7,
          status: 'running',
          results: []
        });
      }

      const rule = rulesMap.get(ruleKey)!;

      // Mapear status do update para status do resultado
      let resultStatus: 'ignored' | 'skipped' | 'actioned' | 'error' | 'processing' = 'processing';
      if (update.status === 'actioned') resultStatus = 'actioned';
      else if (update.status === 'skipped') {
        resultStatus = update.message?.includes('objetivo') ? 'ignored' : 'skipped';
      }
      else if (update.status === 'error') resultStatus = 'error';

      // Adicionar resultado
      rule.results.push({
        entityId: update.id,
        entityName: update.entity_name,
        entityType: update.entity_type as 'campaign' | 'adset' | 'ad',
        parentCampaignName: update.metadata?.parent_campaign,
        parentAdsetName: update.metadata?.parent_adset,
        status: resultStatus,
        reason: update.message,
        metrics: update.metadata?.metrics
      });
    });

    // Marcar regras como concluídas se não há mais processando
    rulesMap.forEach(rule => {
      const hasProcessing = rule.results.some(r => r.status === 'processing');
      if (!hasProcessing && rule.results.length > 0) {
        rule.status = 'completed';
      }
    });

    return Array.from(rulesMap.values());
  }, [updates]);

  // Calcular estatísticas gerais
  const stats = useMemo(() => {
    const allResults = ruleExecutions.flatMap(r => r.results);
    return {
      total: allResults.length,
      actioned: allResults.filter(r => r.status === 'actioned').length,
      skipped: allResults.filter(r => r.status === 'skipped').length,
      ignored: allResults.filter(r => r.status === 'ignored').length,
      errors: allResults.filter(r => r.status === 'error').length,
    };
  }, [ruleExecutions]);

  const completionUpdate = updates.find(u => u.rule_name === 'Conclusão');
  const currentRuleIndex = ruleExecutions.findIndex(r => r.status === 'running');

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {isComplete ? (
              <CheckCircle className="h-5 w-5 text-green-500" />
            ) : isTimedOut ? (
              <AlertTriangle className="h-5 w-5 text-amber-500" />
            ) : (
              <Loader2 className="h-5 w-5 animate-spin" />
            )}
            {isComplete ? "Execução Concluída" : isTimedOut ? "Execução Finalizada" : "Executando Automações..."}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Progress Bar */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-muted-foreground">{currentPhase.message}</span>
              <span className="font-medium">{Math.round(currentPhase.progress)}%</span>
            </div>
            <Progress value={currentPhase.progress} className="h-2" />
          </div>

          {/* Stats */}
          <div className="grid grid-cols-5 gap-3">
            <div className="text-center p-2 bg-muted rounded-lg">
              <div className="text-xl font-bold">{stats.total}</div>
              <div className="text-xs text-muted-foreground">Total</div>
            </div>
            <div className="text-center p-2 bg-green-50 dark:bg-green-950/30 rounded-lg">
              <div className="text-xl font-bold text-green-600">{stats.actioned}</div>
              <div className="text-xs text-muted-foreground">Ações</div>
            </div>
            <div className="text-center p-2 bg-gray-50 dark:bg-gray-950/30 rounded-lg">
              <div className="text-xl font-bold text-gray-600">{stats.skipped}</div>
              <div className="text-xs text-muted-foreground">Ignorados</div>
            </div>
            <div className="text-center p-2 bg-yellow-50 dark:bg-yellow-950/30 rounded-lg">
              <div className="text-xl font-bold text-yellow-600">{stats.ignored}</div>
              <div className="text-xs text-muted-foreground">Objetivo ≠</div>
            </div>
            <div className="text-center p-2 bg-red-50 dark:bg-red-950/30 rounded-lg">
              <div className="text-xl font-bold text-red-600">{stats.errors}</div>
              <div className="text-xs text-muted-foreground">Erros</div>
            </div>
          </div>

          {/* Tabs */}
          <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="progress" className="flex items-center gap-2">
                <Play className="h-4 w-4" />
                Progresso
              </TabsTrigger>
              <TabsTrigger value="hierarchy" className="flex items-center gap-2">
                <Database className="h-4 w-4" />
                Estrutura
              </TabsTrigger>
              <TabsTrigger value="rules" className="flex items-center gap-2">
                <BarChart3 className="h-4 w-4" />
                Regras
              </TabsTrigger>
            </TabsList>

            <TabsContent value="progress" className="mt-4">
              <ScrollArea className="h-[350px] pr-4">
                {ruleExecutions.length === 0 && !isComplete && !isTimedOut ? (
                  <div className="text-center text-muted-foreground py-8">
                    <Loader2 className="h-8 w-8 animate-spin mx-auto mb-2" />
                    <p>{currentPhase.message}</p>
                  </div>
                ) : (
                  <RuleExecutionProgress 
                    rules={ruleExecutions} 
                    currentRuleIndex={currentRuleIndex >= 0 ? currentRuleIndex : ruleExecutions.length - 1}
                  />
                )}
              </ScrollArea>
            </TabsContent>

            <TabsContent value="hierarchy" className="mt-4">
              <ScrollArea className="h-[350px] pr-4">
                <AutomationHierarchyTree 
                  hierarchy={hierarchy}
                  isLoading={currentPhase.phase === 'collecting'}
                  loadingMessage={currentPhase.message}
                />
              </ScrollArea>
            </TabsContent>

            <TabsContent value="rules" className="mt-4">
              <ScrollArea className="h-[350px] pr-4">
                <div className="space-y-3">
                  {ruleExecutions.map((rule, idx) => (
                    <div key={rule.ruleId} className="p-3 border rounded-lg">
                      <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center gap-2">
                          {rule.status === 'completed' ? (
                            <CheckCircle className="h-4 w-4 text-green-500" />
                          ) : rule.status === 'running' ? (
                            <Loader2 className="h-4 w-4 animate-spin text-blue-500" />
                          ) : (
                            <div className="h-4 w-4 rounded-full border" />
                          )}
                          <span className="font-medium">{rule.ruleName}</span>
                        </div>
                        <Badge variant="outline">{rule.entityType}</Badge>
                      </div>
                      <div className="grid grid-cols-4 gap-2 text-xs">
                        <div className="text-center p-1 bg-green-50 dark:bg-green-950/30 rounded">
                          <span className="font-bold text-green-600">
                            {rule.results.filter(r => r.status === 'actioned').length}
                          </span>
                          <span className="text-muted-foreground ml-1">ações</span>
                        </div>
                        <div className="text-center p-1 bg-gray-50 dark:bg-gray-950/30 rounded">
                          <span className="font-bold text-gray-600">
                            {rule.results.filter(r => r.status === 'skipped').length}
                          </span>
                          <span className="text-muted-foreground ml-1">ignorados</span>
                        </div>
                        <div className="text-center p-1 bg-yellow-50 dark:bg-yellow-950/30 rounded">
                          <span className="font-bold text-yellow-600">
                            {rule.results.filter(r => r.status === 'ignored').length}
                          </span>
                          <span className="text-muted-foreground ml-1">objetivo ≠</span>
                        </div>
                        <div className="text-center p-1 bg-red-50 dark:bg-red-950/30 rounded">
                          <span className="font-bold text-red-600">
                            {rule.results.filter(r => r.status === 'error').length}
                          </span>
                          <span className="text-muted-foreground ml-1">erros</span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </ScrollArea>
            </TabsContent>
          </Tabs>

          {/* Timeout Message */}
          {isTimedOut && !completionUpdate && (
            <div className="p-4 bg-amber-50 dark:bg-amber-950/30 rounded-lg border border-amber-200 dark:border-amber-800">
              <div className="flex items-start gap-3">
                <AlertTriangle className="h-5 w-5 text-amber-500 mt-0.5" />
                <div>
                  <p className="font-medium text-amber-800 dark:text-amber-300">
                    Execução finalizada por timeout
                  </p>
                  <p className="text-sm text-amber-700 dark:text-amber-400 mt-1">
                    A execução demorou mais que o esperado. Todas as ações executadas até este ponto foram salvas.
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Complete Message */}
          {completionUpdate && (
            <div className="text-center p-4 bg-green-50 dark:bg-green-950/30 rounded-lg">
              <CheckCircle className="h-8 w-8 text-green-500 mx-auto mb-2" />
              <p className="font-medium text-green-700 dark:text-green-300">
                {completionUpdate.message}
              </p>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

