    const newSector = await createSector(newSectorName.trim());

    if (newSector) {
      setFormData({ ...formData, sector: newSector.name });
      setNewSectorName("");
      setShowNewSectorInput(false);
      toast({
        title: "Setor criado",
        description: `O setor "${newSector.name}" foi criado com sucesso!`,
      });
    } else {
      toast({
        title: "Erro ao criar setor",
        description: "Já existe um setor com esse nome nesta empresa ou ocorreu um erro.",
        variant: "destructive",
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Handle is_canceled logic: set canceled_at when marking as canceled
      const wasCanceled = client?.is_canceled || false;
      const isCanceled = formData.is_canceled;

      // Handle is_paused logic: set paused_at when marking as paused
      const wasPaused = (client as unknown)?.is_paused || false;
      const isPaused = formData.is_paused;

      const submitData = {
        ...formData,
        team_id: formData.team_id === 'none' ? null : formData.team_id,
        gestor_id: formData.gestor_id === 'none' ? null : formData.gestor_id,
        ai_briefing: localClient?.ai_briefing,
        briefing_generated_at: localClient?.briefing_generated_at,
        is_canceled: isCanceled,
        canceled_at: isCanceled && !wasCanceled 
          ? new Date().toISOString() 
          : isCanceled 
            ? client?.canceled_at 
            : null,
        is_paused: isPaused,
        paused_at: isPaused && !wasPaused 
          ? new Date().toISOString() 
          : isPaused 
            ? (client as unknown)?.paused_at 
            : null,
        pause_reason: isPaused ? formData.pause_reason : null,
      };

      await onSubmit(submitData);

      // Save benchmarks if editing an existing client
      if (client?.id && activeCompany?.company_id) {
        await saveBothBenchmarks(metaBenchmarkFormData, googleBenchmarkFormData);
      }

      if (client?.facebook_ad_accounts?.id) {
        const { error: accountError } = await supabase
          .from('facebook_ad_accounts')
          .update({
            recharge_day: rechargeDayValue === "none" ? null : parseInt(rechargeDayValue)
          })
          .eq('id', client.facebook_ad_accounts.id);

        if (accountError) {
          console.error('Erro ao atualizar dia de recarga:', accountError);
          toast({
            title: "Aviso",
            description: "Cliente salvo, mas houve um erro ao atualizar o dia de recarga.",
            variant: "destructive",
          });
        }
      }

      toast({
        title: "Sucesso",
        description: client ? "Cliente atualizado com sucesso!" : "Cliente criado com sucesso!",
      });
    } catch (error: unknown) {
      toast({
        title: "Erro",
        description: error.message || "Erro ao salvar cliente",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setUploading(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${Date.now()}.${fileExt}`;

      const { error: uploadError } = await supabase.storage
        .from('client-avatars')
        .upload(fileName, file);

      if (uploadError) throw uploadError;

      const { data: { publicUrl } } = supabase.storage
        .from('client-avatars')
        .getPublicUrl(fileName);

      setFormData({ ...formData, avatar: publicUrl });
      toast({
        title: "Sucesso",
        description: "Foto enviada com sucesso!",
      });
    } catch (error) {
      toast({
        title: "Erro",
        description: "Erro ao enviar foto. Tente novamente.",
        variant: "destructive",
      });
    } finally {
      setUploading(false);
    }
  };

