          <DialogFooter className="px-6 py-4 border-t">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              {readOnly ? "Fechar" : "Cancelar"}
            </Button>
            {!readOnly && (
              <Button type="submit" disabled={loading}>
                {loading ? "Salvando..." : client ? "Atualizar" : "Criar"}
              </Button>
            )}
          </DialogFooter>
        </form>

        {/* Reference Selection Dialog */}
        {client && activeCompany && (
          <ReferenceSelectionDialog
            open={referenceDialogOpen}
            onOpenChange={setReferenceDialogOpen}
            clientId={client.id}
            companyId={activeCompany.company_id}
            onSelect={(images) => {
              // Fill in the reference images
              const newFormData = { ...formData };
              if (images[0]) newFormData.ai_reference_image_1 = images[0];
              if (images[1]) newFormData.ai_reference_image_2 = images[1];
              if (images[2]) newFormData.ai_reference_image_3 = images[2];
              setFormData(newFormData);
              toast({
                title: "Imagens importadas",
                description: `${images.length} imagem(ns) de referência adicionada(s).`,
              });
            }}
            maxSelections={3}
          />
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, Settings } from "lucide-react";

interface ConfigureOfflineEventSetDialogProps {
  clientId: string;
}

export const ConfigureOfflineEventSetDialog = ({ clientId }: ConfigureOfflineEventSetDialogProps) => {
  const [open, setOpen] = useState(false);
  const [eventSetId, setEventSetId] = useState('');
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    if (open) {
      loadCurrentEventSetId();
    }
  }, [open, clientId]);

  const loadCurrentEventSetId = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('clients')
        .select('offline_event_set_id')
        .eq('id', clientId)
        .single();

      if (error) throw error;

      setEventSetId(data?.offline_event_set_id || '');
    } catch (err: unknown) {
      console.error('Error loading offline event set ID:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (!eventSetId.trim()) {
      toast({
        title: "Campo obrigatório",
        description: "Por favor, informe o Offline Event Set ID.",
        variant: "destructive",
      });
      return;
    }

    setSaving(true);
    try {
      const { error } = await supabase
        .from('clients')
        .update({ offline_event_set_id: eventSetId.trim() })
        .eq('id', clientId);

      if (error) throw error;

      toast({
        title: "Configuração salva",
        description: "O Offline Event Set ID foi configurado com sucesso.",
      });
      setOpen(false);
    } catch (err: unknown) {
      console.error('Error saving offline event set ID:', err);
      toast({
        title: "Erro ao salvar",
        description: err.message || "Não foi possível salvar a configuração.",
        variant: "destructive",
      });
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm">
          <Settings className="w-4 h-4 mr-2" />
          Configurar Offline Event Set
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>Configurar Offline Event Set ID</DialogTitle>
          <DialogDescription>
            Para enviar conversões offline, você precisa criar um Offline Event Set no Meta Events Manager.
          </DialogDescription>
        </DialogHeader>

        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        ) : (
          <div className="space-y-4">
            <div className="bg-muted p-4 rounded-lg">
              <p className="text-sm font-medium mb-2">📝 Como criar um Offline Event Set:</p>
              <ol className="text-sm space-y-2 list-decimal list-inside text-muted-foreground">
                <li>
                  Acesse o{" "}
                  <a 
                    href="https://business.facebook.com/events_manager2" 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="text-primary underline hover:no-underline"
                  >
                    Meta Events Manager
                  </a>
                </li>
                <li>Clique em "Conectar fontes de dados" → "Offline"</li>
                <li>Crie um novo conjunto de eventos offline</li>
                <li>Vincule sua conta de anúncios ao conjunto criado</li>
                <li>Copie o ID do conjunto (aparece na URL ou nas configurações)</li>
                <li>Cole o ID no campo abaixo</li>
              </ol>
            </div>

            <div className="space-y-2">
              <Label htmlFor="eventSetId">Offline Event Set ID *</Label>
              <Input 
                id="eventSetId"
                value={eventSetId} 
                onChange={(e) => setEventSetId(e.target.value)} 
                placeholder="1234567890123456"
                disabled={saving}
              />
              <p className="text-xs text-muted-foreground">
                O ID é um número longo que identifica seu conjunto de eventos offline.
              </p>
            </div>

            <div className="bg-blue-50 border border-blue-200 p-3 rounded-lg">
              <p className="text-sm text-blue-900">
                💡 <strong>Dica:</strong> Após configurar, você poderá enviar conversões offline e o Meta otimizará suas campanhas com base nos dados reais de conversão.
              </p>
            </div>
          </div>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={() => setOpen(false)} disabled={saving}>
            Cancelar
          </Button>
          <Button onClick={handleSave} disabled={saving || !eventSetId.trim() || loading}>
            {saving ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
            Salvar Configuração
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Loader2, Check, ImageIcon, Instagram, Megaphone, AlertCircle, LayoutGrid, Images } from "lucide-react";
import { cn } from "@/lib/utils";

interface CreativeReference {
  id: string;
  imageUrl: string;
  name?: string;
  caption?: string;
  type: 'ad' | 'instagram';
}

interface CarouselItem {
  id: string;
  imageUrl: string;
  caption: string;
  children: { id: string; imageUrl: string; mediaType: string }[];
  timestamp: string;
}

interface ReferenceSelectionDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  clientId?: string;
  instagramAccountId?: string;
  companyId: string;
  onSelect: (images: string[]) => void;
  maxSelections?: number;
}

export function ReferenceSelectionDialog({
  open,
  onOpenChange,
  clientId,
  instagramAccountId,
  companyId,
  onSelect,
  maxSelections = 3
}: ReferenceSelectionDialogProps) {
  const [loading, setLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState<'ads' | 'instagram' | 'carousels' | null>(null);
  const [copying, setCopying] = useState(false);
  const [copyProgress, setCopyProgress] = useState({ current: 0, total: 0 });
  const [adCreatives, setAdCreatives] = useState<CreativeReference[]>([]);
  const [instagramPosts, setInstagramPosts] = useState<CreativeReference[]>([]);
  const [instagramCarousels, setInstagramCarousels] = useState<CarouselItem[]>([]);
  const [selectedImages, setSelectedImages] = useState<string[]>([]);
  const [selectedCarousel, setSelectedCarousel] = useState<CarouselItem | null>(null);
  const [hasAdAccount, setHasAdAccount] = useState(false);
  const [hasInstagram, setHasInstagram] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<string>("ads");

  // Pagination cursors
  const [nextAdCursor, setNextAdCursor] = useState<string | null>(null);
  const [nextInstagramCursor, setNextInstagramCursor] = useState<string | null>(null);
  const [nextCarouselCursor, setNextCarouselCursor] = useState<string | null>(null);
  const [hasMoreAds, setHasMoreAds] = useState(false);
  const [hasMoreInstagram, setHasMoreInstagram] = useState(false);
  const [hasMoreCarousels, setHasMoreCarousels] = useState(false);

  const { toast } = useToast();

  useEffect(() => {
    if (open && companyId) {
      // Reset state when opening
      setAdCreatives([]);
      setInstagramPosts([]);
      setInstagramCarousels([]);
      setNextAdCursor(null);
      setNextInstagramCursor(null);
      setNextCarouselCursor(null);
      setHasMoreAds(false);
      setHasMoreInstagram(false);
      setHasMoreCarousels(false);
      setSelectedImages([]);
      setSelectedCarousel(null);
      fetchReferences();
    }
  }, [open, clientId, instagramAccountId, companyId]);

  const fetchReferences = async (adCursor?: string, instagramCursor?: string, carouselCursor?: string, append = false) => {
    if (!append) {
      setLoading(true);
    }
    setError(null);

    try {
      const { data, error } = await supabase.functions.invoke('fetch-creative-references', {
        body: { 
          clientId, 
          instagramAccountId, 
          companyId,
          limit: 20,
          adCursor,
          instagramCursor,
          carouselCursor,
          includeCarousels: true
        }
      });

      if (error) throw error;

      if (data.success) {
        if (append) {
          // Append new items to existing ones, avoiding duplicates
          if (adCursor) {
            const existingIds = new Set(adCreatives.map(c => c.id));
            const newAds = (data.adCreatives || []).filter((c: CreativeReference) => !existingIds.has(c.id));
            setAdCreatives(prev => [...prev, ...newAds]);
          }
          if (instagramCursor) {
            const existingIds = new Set(instagramPosts.map(p => p.id));
            const newPosts = (data.instagramPosts || []).filter((p: CreativeReference) => !existingIds.has(p.id));
            setInstagramPosts(prev => [...prev, ...newPosts]);
          }
          if (carouselCursor) {
            const existingIds = new Set(instagramCarousels.map(c => c.id));
            const newCarousels = (data.instagramCarousels || []).filter((c: CarouselItem) => !existingIds.has(c.id));
            setInstagramCarousels(prev => [...prev, ...newCarousels]);
          }
        } else {
          setAdCreatives(data.adCreatives || []);
          setInstagramPosts(data.instagramPosts || []);
          setInstagramCarousels(data.instagramCarousels || []);
        }

        setHasAdAccount(data.hasAdAccount || false);
        setHasInstagram(data.hasInstagram || false);
        setNextAdCursor(data.nextAdCursor || null);
        setNextInstagramCursor(data.nextInstagramCursor || null);
        setNextCarouselCursor(data.nextCarouselCursor || null);
        setHasMoreAds(data.hasMoreAds || false);
        setHasMoreInstagram(data.hasMoreInstagram || false);
        setHasMoreCarousels(data.hasMoreCarousels || false);
      } else {
        setError(data.error || "Erro ao buscar referências");
      }
    } catch (err) {
      console.error("Error fetching references:", err);
      setError("Erro ao buscar imagens de referência");
    } finally {
      setLoading(false);
      setLoadingMore(null);
    }
  };

  const loadMoreAds = async () => {
    if (!nextAdCursor || loadingMore) return;
    setLoadingMore('ads');
    await fetchReferences(nextAdCursor, undefined, undefined, true);
  };

  const loadMoreInstagram = async () => {
    if (!nextInstagramCursor || loadingMore) return;
    setLoadingMore('instagram');
    await fetchReferences(undefined, nextInstagramCursor, undefined, true);
  };

  const loadMoreCarousels = async () => {
    if (!nextCarouselCursor || loadingMore) return;
    setLoadingMore('carousels');
    await fetchReferences(undefined, undefined, nextCarouselCursor, true);
  };

  const toggleSelection = (imageUrl: string) => {
    // If in carousel tab, don't allow individual selection
    if (activeTab === "carousels") return;

    setSelectedImages(prev => {
      if (prev.includes(imageUrl)) {
        return prev.filter(url => url !== imageUrl);
      }
      if (prev.length >= maxSelections) {
        toast({
          title: "Limite atingido",
          description: `Você pode selecionar no máximo ${maxSelections} imagens.`,
          variant: "destructive"
        });
        return prev;
      }
      return [...prev, imageUrl];
    });
  };

  const selectCarousel = (carousel: CarouselItem) => {
    if (selectedCarousel?.id === carousel.id) {
      setSelectedCarousel(null);
    } else {
      setSelectedCarousel(carousel);
      // Clear individual selections when selecting a carousel
      setSelectedImages([]);
    }
  };

  // Check if URL is already from our storage (permanent URL)
  const isStorageUrl = (url: string): boolean => {
    return url.includes('supabase.co/storage') || url.includes('.supabase.co');
  };

  // Copy external images to our storage to get permanent URLs
  const copyImagesToStorage = async (imageUrls: string[]): Promise<string[]> => {
    const permanentUrls: string[] = [];

    for (let i = 0; i < imageUrls.length; i++) {
      const url = imageUrls[i];
      setCopyProgress({ current: i + 1, total: imageUrls.length });

      // Skip if already a storage URL
      if (isStorageUrl(url)) {
        permanentUrls.push(url);
        continue;
      }

      try {
        const { data, error } = await supabase.functions.invoke('copy-external-image', {
          body: { imageUrl: url, folder: 'reference-images' }
        });

        if (error) throw error;

        if (data.success && data.url) {
          permanentUrls.push(data.url);
        } else {
          console.error('Failed to copy image:', data.error);
          // Keep original URL as fallback
          permanentUrls.push(url);
          toast({
            title: "Aviso",
            description: `Não foi possível copiar uma imagem. Usando URL original.`,
            variant: "destructive"
          });
        }
      } catch (err) {
        console.error('Error copying image:', err);
        // Keep original URL as fallback
        permanentUrls.push(url);
      }
    }

    return permanentUrls;
  };

  const handleConfirm = async () => {
    // Determine which images to use
    let imagesToCopy: string[] = [];

    if (selectedCarousel) {
      // If a carousel is selected, use all its children images
      imagesToCopy = selectedCarousel.children.map(child => child.imageUrl);
    } else if (selectedImages.length > 0) {
      imagesToCopy = selectedImages;
    }

    if (imagesToCopy.length === 0) return;

    setCopying(true);
    setCopyProgress({ current: 0, total: imagesToCopy.length });

    try {
      // Copy all selected images to our storage
      const permanentUrls = await copyImagesToStorage(imagesToCopy);

      toast({
        title: selectedCarousel ? "Carrossel importado" : "Imagens copiadas",
        description: selectedCarousel 
          ? `${permanentUrls.length} slides do carrossel importados com sucesso.`
          : `${permanentUrls.length} imagem(ns) salva(s) com sucesso.`,
      });

      onSelect(permanentUrls);
      setSelectedImages([]);
      setSelectedCarousel(null);
      onOpenChange(false);
    } catch (err) {
      console.error('Error in handleConfirm:', err);
      toast({
        title: "Erro",
        description: "Ocorreu um erro ao copiar as imagens.",
        variant: "destructive"
      });
    } finally {
      setCopying(false);
      setCopyProgress({ current: 0, total: 0 });
    }
  };

  const handleCancel = () => {
    setSelectedImages([]);
    setSelectedCarousel(null);
    onOpenChange(false);
  };

  const renderImageGrid = (
    items: CreativeReference[], 
    emptyMessage: string, 
    noAccountMessage: string, 
    hasAccount: boolean,
    hasMore: boolean,
    onLoadMore: () => void,
    isLoadingMore: boolean
  ) => {
    if (!hasAccount) {
      return (
        <div className="flex flex-col items-center justify-center py-12 text-center">
          <AlertCircle className="w-12 h-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground">{noAccountMessage}</p>
        </div>
      );
    }

    if (items.length === 0) {
      return (
        <div className="flex flex-col items-center justify-center py-12 text-center">
          <ImageIcon className="w-12 h-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground">{emptyMessage}</p>
        </div>
      );
    }

    return (
      <div className="space-y-4">
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
          {items.map((item) => {
            const isSelected = selectedImages.includes(item.imageUrl);
            const selectionIndex = selectedImages.indexOf(item.imageUrl);

            return (
              <div
                key={item.id}
                className={cn(
                  "relative cursor-pointer rounded-lg overflow-hidden border-2 transition-all",
                  isSelected 
                    ? "border-primary ring-2 ring-primary/30" 
                    : "border-transparent hover:border-muted-foreground/30"
                )}
                onClick={() => toggleSelection(item.imageUrl)}
              >
                <img
                  src={item.imageUrl}
                  alt={item.name || item.caption || "Referência"}
                  className="w-full h-32 object-cover"
                  loading="lazy"
                />

                {/* Selection indicator */}
                {isSelected && (
                  <div className="absolute top-2 right-2 w-6 h-6 bg-primary rounded-full flex items-center justify-center text-primary-foreground text-sm font-bold">
                    {selectionIndex + 1}
                  </div>
                )}

                {/* Hover overlay */}
                <div className={cn(
                  "absolute inset-0 bg-black/50 flex items-center justify-center transition-opacity",
                  isSelected ? "opacity-30" : "opacity-0 hover:opacity-100"
                )}>
                  <Check className="w-8 h-8 text-white" />
                </div>

                {/* Label */}
                <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 to-transparent p-2">
                  <p className="text-white text-xs truncate">
                    {item.name || item.caption || "Imagem"}
                  </p>
                </div>
              </div>
            );
          })}
        </div>

        {/* Load More Button */}
        {hasMore && (
          <div className="flex justify-center pt-4">
            <Button
              variant="outline"
              onClick={onLoadMore}
              disabled={isLoadingMore}
              className="w-full max-w-xs"
            >
              {isLoadingMore ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Carregando...
                </>
              ) : (
                `Carregar mais (${items.length} carregadas)`
              )}
            </Button>
          </div>
        )}
      </div>
    );
  };

  const renderCarouselGrid = () => {
    if (!hasInstagram) {
      return (
        <div className="flex flex-col items-center justify-center py-12 text-center">
          <AlertCircle className="w-12 h-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground">Conta do Instagram não configurada para este cliente.</p>
        </div>
      );
    }

    if (instagramCarousels.length === 0) {
      return (
        <div className="flex flex-col items-center justify-center py-12 text-center">
          <LayoutGrid className="w-12 h-12 text-muted-foreground mb-4" />
          <p className="text-muted-foreground">Nenhum carrossel encontrado no Instagram.</p>
        </div>
      );
    }

    return (
      <div className="space-y-4">
        <p className="text-sm text-muted-foreground">
          Selecione um carrossel para importar todas as suas imagens como referência.
        </p>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          {instagramCarousels.map((carousel) => {
            const isSelected = selectedCarousel?.id === carousel.id;

            return (
              <div
                key={carousel.id}
                className={cn(
                  "relative cursor-pointer rounded-lg overflow-hidden border-2 transition-all",
                  isSelected 
                    ? "border-primary ring-2 ring-primary/30" 
                    : "border-transparent hover:border-muted-foreground/30"
                )}
                onClick={() => selectCarousel(carousel)}
              >
                {/* Carousel preview with stacked effect */}
                <div className="relative">
                  <img
                    src={carousel.imageUrl}
                    alt={carousel.caption}
                    className="w-full h-40 object-cover"
                    loading="lazy"
                  />

                  {/* Stacked effect indicator */}
                  <div className="absolute top-2 left-2 flex items-center gap-1 bg-black/70 rounded-full px-2 py-1">
                    <Images className="w-3 h-3 text-white" />
                    <span className="text-white text-xs font-medium">{carousel.children.length}</span>
                  </div>

                  {/* Selection indicator */}
                  {isSelected && (
                    <div className="absolute top-2 right-2 w-6 h-6 bg-primary rounded-full flex items-center justify-center">
                      <Check className="w-4 h-4 text-primary-foreground" />
                    </div>
                  )}

                  {/* Hover overlay */}
                  <div className={cn(
                    "absolute inset-0 bg-black/50 flex items-center justify-center transition-opacity",
                    isSelected ? "opacity-30" : "opacity-0 hover:opacity-100"
                  )}>
                    <Check className="w-8 h-8 text-white" />
                  </div>
                </div>

                {/* Caption */}
                <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 to-transparent p-2">
                  <p className="text-white text-xs truncate">
                    {carousel.caption}
                  </p>
                </div>
              </div>
            );
          })}
        </div>

        {/* Selected carousel preview */}
        {selectedCarousel && (
          <div className="border rounded-lg p-4 bg-muted/30">
            <h4 className="text-sm font-medium mb-3">
              Slides do carrossel selecionado ({selectedCarousel.children.length} imagens)
            </h4>
            <div className="flex gap-2 overflow-x-auto pb-2">
              {selectedCarousel.children.map((child, index) => (
                <div key={child.id} className="relative shrink-0">
                  <img
                    src={child.imageUrl}
                    alt={`Slide ${index + 1}`}
                    className="h-20 w-20 object-cover rounded-md"
                  />
                  <div className="absolute top-1 left-1 w-5 h-5 bg-primary rounded-full flex items-center justify-center text-primary-foreground text-xs font-bold">
                    {index + 1}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Load More Button */}
        {hasMoreCarousels && (
          <div className="flex justify-center pt-4">
            <Button
              variant="outline"
              onClick={loadMoreCarousels}
              disabled={loadingMore === 'carousels'}
              className="w-full max-w-xs"
            >
              {loadingMore === 'carousels' ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Carregando...
                </>
              ) : (
                `Carregar mais (${instagramCarousels.length} carregados)`
              )}
            </Button>
          </div>
        )}
      </div>
    );
  };

  const totalAvailable = adCreatives.length + instagramPosts.length + instagramCarousels.length;
  const selectionCount = selectedCarousel 
    ? selectedCarousel.children.length 
    : selectedImages.length;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[800px] max-h-[85vh] overflow-hidden flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <ImageIcon className="w-5 h-5" />
            Selecionar Imagens de Referência
          </DialogTitle>
          <p className="text-sm text-muted-foreground">
            {activeTab === "carousels" 
              ? "Selecione um carrossel para importar todas as suas imagens."
              : `Selecione até ${maxSelections} imagens dos seus anúncios ou posts do Instagram.`
            }
          </p>
        </DialogHeader>

        <div className="flex-1 overflow-hidden">
          {copying ? (
            <div className="flex flex-col items-center justify-center py-16">
              <Loader2 className="w-8 h-8 animate-spin text-primary mb-4" />
              <p className="text-muted-foreground">
                Copiando imagens... ({copyProgress.current}/{copyProgress.total})
              </p>
              <p className="text-xs text-muted-foreground mt-2">
                Salvando no servidor para garantir que não expirem
              </p>
            </div>
          ) : loading ? (
            <div className="flex flex-col items-center justify-center py-16">
              <Loader2 className="w-8 h-8 animate-spin text-primary mb-4" />
              <p className="text-muted-foreground">Carregando imagens...</p>
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <AlertCircle className="w-12 h-12 text-destructive mb-4" />
              <p className="text-destructive font-medium">{error}</p>
              <Button variant="outline" className="mt-4" onClick={() => fetchReferences()}>
                Tentar novamente
              </Button>
            </div>
          ) : totalAvailable === 0 && !hasAdAccount && !hasInstagram ? (
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <AlertCircle className="w-12 h-12 text-muted-foreground mb-4" />
              <p className="text-muted-foreground">
                Este cliente não possui conta de anúncios do Meta ou Instagram configurados.
              </p>
              <p className="text-sm text-muted-foreground mt-2">
                Configure as integrações na aba "Contas & Integrações" para importar imagens.
              </p>
            </div>
          ) : (
            <Tabs 
              value={activeTab} 
              onValueChange={(value) => {
                setActiveTab(value);
                // Clear selections when switching tabs
                if (value === "carousels") {
                  setSelectedImages([]);
                } else {
                  setSelectedCarousel(null);
                }
              }}
              className="h-full flex flex-col"
            >
              <TabsList className="grid w-full grid-cols-3 shrink-0">
                <TabsTrigger value="ads" className="flex items-center gap-2">
                  <Megaphone className="w-4 h-4" />
                  Anúncios ({adCreatives.length}{hasMoreAds ? '+' : ''})
                </TabsTrigger>
                <TabsTrigger value="instagram" className="flex items-center gap-2">
                  <Instagram className="w-4 h-4" />
                  Instagram ({instagramPosts.length}{hasMoreInstagram ? '+' : ''})
                </TabsTrigger>
                <TabsTrigger value="carousels" className="flex items-center gap-2">
                  <LayoutGrid className="w-4 h-4" />
                  Carrosséis ({instagramCarousels.length}{hasMoreCarousels ? '+' : ''})
                </TabsTrigger>
              </TabsList>

              <div className="flex-1 overflow-y-auto mt-4 min-h-0 max-h-[50vh]">
                <TabsContent value="ads" className="mt-0 h-full">
                  {renderImageGrid(
                    adCreatives,
                    "Nenhum criativo de imagem encontrado na conta de anúncios.",
                    "Conta de anúncios do Meta não configurada para este cliente.",
                    hasAdAccount,
                    hasMoreAds,
                    loadMoreAds,
                    loadingMore === 'ads'
                  )}
                </TabsContent>

                <TabsContent value="instagram" className="mt-0 h-full">
                  {renderImageGrid(
                    instagramPosts,
                    "Nenhum post de imagem encontrado no Instagram.",
                    "Conta do Instagram não configurada para este cliente.",
                    hasInstagram,
                    hasMoreInstagram,
                    loadMoreInstagram,
                    loadingMore === 'instagram'
                  )}
                </TabsContent>

                <TabsContent value="carousels" className="mt-0 h-full">
                  {renderCarouselGrid()}
                </TabsContent>
              </div>
            </Tabs>
          )}
        </div>

        <DialogFooter className="flex items-center justify-between border-t pt-4">
          <p className="text-sm text-muted-foreground">
            {selectedCarousel 
              ? `Carrossel com ${selectedCarousel.children.length} imagens selecionado`
              : `${selectedImages.length} de ${maxSelections} selecionadas`
            }
          </p>
          <div className="flex gap-2">
            <Button variant="outline" onClick={handleCancel} disabled={copying}>
              Cancelar
            </Button>
            <Button 
              onClick={handleConfirm} 
              disabled={selectionCount === 0 || copying}
            >
              {copying ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Copiando...
                </>
              ) : selectedCarousel ? (
                `Importar Carrossel (${selectedCarousel.children.length} imagens)`
              ) : (
                `Usar Selecionadas (${selectedImages.length})`
              )}
            </Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import React, { useRef, useState, useCallback } from "react";
import { CommandCenterTask } from "@/hooks/useCommandCenter";
import { cn } from "@/lib/utils";
import { Clock, CheckCircle2, AlertTriangle, GripVertical, Undo2, CalendarArrowDown, ArrowLeftToLine, ArchiveRestore } from "lucide-react";
import { differenceInMinutes } from "date-fns";
import { ContextMenu, ContextMenuContent, ContextMenuItem, ContextMenuTrigger } from "@/components/ui/context-menu";

interface Props {
  task: CommandCenterTask;
  slotWidth: number;
  slotDuration?: number;
  startHour: number;
  selectedDate?: Date;
  onReposition?: (taskId: string, newStartDate: Date) => void;
  onResize?: (taskId: string, newStartDate: Date, newEstimatedMinutes: number) => void;
  onClickTask?: (task: CommandCenterTask) => void;
  onSendToBacklog?: (taskId: string) => void;
  onReturnToBacklogCenter?: (taskId: string) => void;
  onReassign?: (taskId: string, newUserId: string, newMemberName: string, newStartDate: Date) => void;
  onSendToNextDay?: (taskId: string) => void;
}

export function TimelineTaskCard({ task, slotWidth, slotDuration = 20, startHour, selectedDate, onReposition, onResize, onClickTask, onSendToBacklog, onReturnToBacklogCenter, onReassign, onSendToNextDay }: Props) {
  const cardRef = useRef<HTMLDivElement>(null);
  const dragMoved = useRef(false);
  const estimatedMin = task.ai_estimated_minutes || slotDuration;
  const slotsOccupied = Math.max(1, Math.ceil(estimatedMin / slotDuration));
  const baseWidth = slotsOccupied * slotWidth;

  const taskStart = task.start_date ? new Date(task.start_date) : null;
  let leftOffset = 0;
  if (taskStart) {
    const dayStart = new Date(taskStart);
    dayStart.setHours(startHour, 0, 0, 0);
    const minutesFromStart = differenceInMinutes(taskStart, dayStart);
    leftOffset = (minutesFromStart / slotDuration) * slotWidth;
  }

  const isDone = task.status === "done";
  const isOvertime = taskStart && !isDone && differenceInMinutes(new Date(), taskStart) > estimatedMin + 7;

  // Drag-to-move state
  const [dragging, setDragging] = useState(false);
  const [dragLeft, setDragLeft] = useState<number | null>(null);
  const [dragTop, setDragTop] = useState<number | null>(null);
  const [returningToBacklog, setReturningToBacklog] = useState(false);
  const [targetMemberName, setTargetMemberName] = useState<string | null>(null);
  const dragRef = useRef<{ startX: number; startLeft: number; startY: number; origParent: HTMLElement | null } | null>(null);

  // Resize state
  const [resizing, setResizing] = useState<"left" | "right" | null>(null);
  const [resizeLeft, setResizeLeft] = useState<number | null>(null);
  const [resizeWidth, setResizeWidth] = useState<number | null>(null);
  const resizeRef = useRef<{ startX: number; origLeft: number; origWidth: number; edge: "left" | "right" } | null>(null);
  const resizeValuesRef = useRef<{ left: number; width: number }>({ left: 0, width: 0 });

  // --- MOVE ---
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (e.button !== 0) return; // Only left click
    if (!onReposition && !onClickTask) return;
    e.preventDefault();
    e.stopPropagation();
    dragMoved.current = false;

    // Find the parent row element for cross-row detection
    const cardEl = e.currentTarget as HTMLElement;
    const rowEl = cardEl.closest('[data-member-user-id]') as HTMLElement | null;

    dragRef.current = { startX: e.clientX, startLeft: leftOffset, startY: e.clientY, origParent: rowEl };
    setDragging(true);
    setDragLeft(leftOffset);
    setDragTop(null);
    setTargetMemberName(null);

    const onMouseMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      const dx = ev.clientX - dragRef.current.startX;
      const dy = ev.clientY - dragRef.current.startY;
      if (Math.abs(dx) > 4 || Math.abs(dy) > 4) dragMoved.current = true;
      if (!dragMoved.current || isDone) return;
      const newLeft = dragRef.current.startLeft + dx;
      // Detect backlog: check if cursor is over the backlog column
      const card = cardRef.current;
      if (card) card.style.pointerEvents = 'none';
      const elementsAtCursor = document.elementsFromPoint(ev.clientX, ev.clientY);
      if (card) card.style.pointerEvents = '';
      const overBacklog = elementsAtCursor.some(el => el.closest('[data-backlog-column]'));

      if (overBacklog && onSendToBacklog) {
        setReturningToBacklog(true);
        setTargetMemberName(null);
      } else {
        setReturningToBacklog(false);
      }
      const snappedSlot = Math.round(newLeft / slotWidth);
      const snappedLeft = Math.max(-150, snappedSlot * slotWidth);
      setDragLeft(snappedLeft);

      // Detect cross-row via Y offset
      if (Math.abs(dy) > 10) {
        setDragTop(dy);
        // Temporarily hide card so elementsFromPoint can see the row beneath
        const card = cardRef.current;
        if (card) card.style.pointerEvents = 'none';
        const elementsUnder = document.elementsFromPoint(ev.clientX, ev.clientY);
        if (card) card.style.pointerEvents = '';
        const targetRow = elementsUnder.find(el => el.closest('[data-member-user-id]'))?.closest('[data-member-user-id]') as HTMLElement | null;
        if (targetRow && targetRow !== dragRef.current.origParent) {
          setTargetMemberName(targetRow.getAttribute('data-member-name'));
        } else {
          setTargetMemberName(null);
        }
      } else {
        setDragTop(null);
        setTargetMemberName(null);
      }
    };

    const onMouseUp = (ev: MouseEvent) => {
      if (!dragMoved.current) {
        onClickTask?.(task);
      } else if (dragRef.current && !isDone) {
        const dx = ev.clientX - dragRef.current.startX;
        const newLeft = dragRef.current.startLeft + dx;
        // Check if dropped over backlog column
        const card = cardRef.current;
        if (card) card.style.pointerEvents = 'none';
        const dropElements = document.elementsFromPoint(ev.clientX, ev.clientY);
        if (card) card.style.pointerEvents = '';
        const droppedOnBacklog = dropElements.some(el => el.closest('[data-backlog-column]'));

        if (droppedOnBacklog && onSendToBacklog) {
          onSendToBacklog(task.id);
        } else {
          // Check if dropped on a different member row - reuse elementsFromPoint from above
          const targetRow = dropElements.find(el => el.closest('[data-member-user-id]'))?.closest('[data-member-user-id]') as HTMLElement | null;
          const targetUserId = targetRow?.getAttribute('data-member-user-id');
          const targetName = targetRow?.getAttribute('data-member-name');
          const isNewMember = targetUserId && targetUserId !== task.assigned_user_id;

          const snappedSlot = Math.max(0, Math.round(newLeft / slotWidth));
          const newMinutesFromDayStart = snappedSlot * slotDuration;
          const baseDate = selectedDate ? new Date(selectedDate) : (taskStart ? new Date(taskStart) : new Date());
          const newDate = new Date(baseDate);
          newDate.setHours(startHour, 0, 0, 0);
          newDate.setMinutes(newMinutesFromDayStart);

          if (isNewMember && onReassign && targetName) {
            onReassign(task.id, targetUserId, targetName, newDate);
          } else if (onReposition) {
            onReposition(task.id, newDate);
          }
        }
      }
      dragRef.current = null;
      setDragging(false);
      setDragLeft(null);
      setDragTop(null);
      setReturningToBacklog(false);
      setTargetMemberName(null);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
    };

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);
  }, [isDone, onReposition, onReassign, onClickTask, onSendToBacklog, leftOffset, slotWidth, slotDuration, startHour, taskStart, selectedDate, task]);

  // --- RESIZE ---
  const handleResizeMouseDown = useCallback((edge: "left" | "right", e: React.MouseEvent) => {
    if (isDone || !onResize) return;
    e.preventDefault();
    e.stopPropagation();

    resizeRef.current = { startX: e.clientX, origLeft: leftOffset, origWidth: baseWidth, edge };
    setResizing(edge);
    setResizeLeft(leftOffset);
    setResizeWidth(baseWidth);
    resizeValuesRef.current = { left: leftOffset, width: baseWidth };

    const onMouseMove = (ev: MouseEvent) => {
      if (!resizeRef.current) return;
      const dx = ev.clientX - resizeRef.current.startX;

      if (edge === "right") {
        const newWidth = resizeRef.current.origWidth + dx;
        const snappedSlots = Math.max(1, Math.round(newWidth / slotWidth));
        const w = snappedSlots * slotWidth;
        setResizeWidth(w);
        resizeValuesRef.current.width = w;
      } else {
        const newLeft = resizeRef.current.origLeft + dx;
        const snappedSlot = Math.max(0, Math.round(newLeft / slotWidth));
        const snappedLeft = snappedSlot * slotWidth;
        const rightEdge = resizeRef.current.origLeft + resizeRef.current.origWidth;
        const newWidth = rightEdge - snappedLeft;
        if (newWidth >= slotWidth) {
          setResizeLeft(snappedLeft);
          setResizeWidth(newWidth);
          resizeValuesRef.current = { left: snappedLeft, width: newWidth };
        }
      }
    };

    const onMouseUp = () => {
      if (resizeRef.current && onResize) {
        const finalLeft = resizeValuesRef.current.left;
        const finalWidth = resizeValuesRef.current.width;
        const snappedStartSlot = Math.max(0, Math.round(finalLeft / slotWidth));
        const snappedSlots = Math.max(1, Math.round(finalWidth / slotWidth));
        const newMinutesFromDayStart = snappedStartSlot * slotDuration;
        const newEstimated = snappedSlots * slotDuration;

        const baseDate = selectedDate ? new Date(selectedDate) : (taskStart ? new Date(taskStart) : new Date());
        const newDate = new Date(baseDate);
        newDate.setHours(startHour, 0, 0, 0);
        newDate.setMinutes(newMinutesFromDayStart);

        onResize(task.id, newDate, newEstimated);
      }
      resizeRef.current = null;
      setResizing(null);
      setResizeLeft(null);
      setResizeWidth(null);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
    };

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);
  }, [isDone, onResize, leftOffset, baseWidth, slotWidth, slotDuration, startHour, taskStart, selectedDate, task, resizeLeft, resizeWidth]);

  const displayLeft = resizeLeft ?? dragLeft ?? leftOffset;
  const displayWidth = resizeWidth ?? baseWidth;

  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>
        <div
          ref={cardRef}
          onMouseDown={handleMouseDown}
          className={cn(
            "absolute top-1 h-[calc(100%-8px)] rounded-lg px-2 py-1 flex items-center gap-1 text-xs font-medium overflow-hidden group/card",
            returningToBacklog
              ? "bg-destructive/20 border-2 border-dashed border-destructive/50 text-destructive"
              : targetMemberName
              ? "bg-accent/30 border-2 border-dashed border-accent-foreground/50 text-accent-foreground"
              : isDone
              ? "bg-emerald-500/20 border border-emerald-500/40 text-emerald-600 dark:text-emerald-400"
              : isOvertime
              ? "bg-orange-500/20 border border-orange-500/40 text-orange-600 dark:text-orange-400 animate-pulse"
              : "bg-primary/10 border border-primary/30 text-primary",
            (dragging || resizing) ? "opacity-80 shadow-lg z-50" : "",
            dragging ? "cursor-grabbing" : "cursor-grab",
            !(dragging || resizing) && "transition-all duration-300"
          )}
          style={{
            left: `${Math.max(returningToBacklog ? -150 : 0, displayLeft)}px`,
            width: `${displayWidth}px`,
            transform: dragTop !== null ? `translateY(${dragTop}px)` : undefined,
            zIndex: dragTop !== null ? 100 : undefined,
          }}
          title={`${task.title} (${estimatedMin}min)`}
        >
          {/* Left resize handle */}
          {!isDone && onResize && (
            <div
              onMouseDown={(e) => handleResizeMouseDown("left", e)}
              className="absolute left-0 top-0 bottom-0 w-2 cursor-col-resize z-10 flex items-center justify-center opacity-0 group-hover/card:opacity-100 transition-opacity"
            >
              <div className="w-0.5 h-3/5 rounded-full bg-current opacity-40" />
            </div>
          )}

          {returningToBacklog ? (
            <>
              <Undo2 className="w-3 h-3 flex-shrink-0 animate-pulse" />
              <span className="truncate font-semibold">Soltar → Backlog</span>
            </>
          ) : targetMemberName ? (
            <>
              <GripVertical className="w-3 h-3 flex-shrink-0" />
              <span className="truncate font-semibold">→ {targetMemberName}</span>
            </>
          ) : (
            <>
              {!isDone && onReposition && (
                <GripVertical className="w-3 h-3 flex-shrink-0 opacity-40" />
              )}
              {isDone ? (
                <CheckCircle2 className="w-3 h-3 flex-shrink-0" />
              ) : isOvertime ? (
                <AlertTriangle className="w-3 h-3 flex-shrink-0" />
              ) : (
                <Clock className="w-3 h-3 flex-shrink-0" />
              )}
              <span className="truncate">{task.title}</span>
            </>
          )}

          {/* Right resize handle */}
          {!isDone && onResize && (
            <div
              onMouseDown={(e) => handleResizeMouseDown("right", e)}
              className="absolute right-0 top-0 bottom-0 w-2 cursor-col-resize z-10 flex items-center justify-center opacity-0 group-hover/card:opacity-100 transition-opacity"
            >
              <div className="w-0.5 h-3/5 rounded-full bg-current opacity-40" />
            </div>
          )}
        </div>
      </ContextMenuTrigger>
      <ContextMenuContent>
        {onSendToNextDay && (
          <ContextMenuItem onClick={() => onSendToNextDay(task.id)}>
            <CalendarArrowDown className="w-4 h-4 mr-2" />
            Enviar para amanhã
          </ContextMenuItem>
        )}
        {onSendToBacklog && (
          <ContextMenuItem onClick={() => onSendToBacklog(task.id)}>
            <ArrowLeftToLine className="w-4 h-4 mr-2" />
            Devolver ao backlog
          </ContextMenuItem>
        )}
        {onReturnToBacklogCenter && (
          <ContextMenuItem onClick={() => onReturnToBacklogCenter(task.id)}>
            <ArchiveRestore className="w-4 h-4 mr-2" />
            Devolver ao Backlog Center
          </ContextMenuItem>
        )}
      </ContextMenuContent>
    </ContextMenu>
  );
}

import React, { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "@/hooks/use-toast";
import { Loader2, Copy, Save, Plus, RefreshCw, Sparkles } from "lucide-react";
import { ContentType } from "./ContentTypes";
import { GenerationData } from "./ContentModal";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useCompany } from "@/contexts/CompanyContext";

interface ResultStepProps {
  contentType: ContentType;
  data: GenerationData;
  isGenerating: boolean;
  setIsGenerating: (generating: boolean) => void;
  onContentGenerated: (content: string) => void;
}

export function ResultStep({ 
  contentType, 
  data, 
  isGenerating, 
  setIsGenerating, 
  onContentGenerated 
}: ResultStepProps) {
  const [editedContent, setEditedContent] = useState("");
  const { user } = useAuth();
  const { activeCompany } = useCompany();

  useEffect(() => {
    if (!data.generatedContent && data.clientId && data.theme) {
      generateContent();
    }
  }, [data.clientId, data.theme]);

  useEffect(() => {
    if (data.generatedContent) {
      setEditedContent(data.generatedContent);
    }
  }, [data.generatedContent]);

  const generateContent = async () => {
    if (!data.clientId || !data.theme || !activeCompany) {
      return;
    }

    setIsGenerating(true);

    try {
      const { data: result, error } = await supabase.functions.invoke('generate-content-ai', {
        body: {
          contentType: contentType.id,
          clientId: data.clientId,
          theme: data.theme,
          companyId: activeCompany.company_id
        }
      });

      if (error) {
        console.error('Error generating content:', error);
        toast({
          title: "Erro ao gerar conteúdo",
          description: "Tente novamente em alguns segundos.",
          variant: "destructive",
        });
        return;
      }

      if (result?.content) {
        onContentGenerated(result.content);
        toast({
          title: "Conteúdo gerado com sucesso!",
          description: "O conteúdo foi criado usando IA.",
        });
      } else {
        throw new Error("Nenhum conteúdo foi retornado");
      }
    } catch (error) {
      console.error('Error:', error);
      toast({
        title: "Erro ao gerar conteúdo",
        description: "Verifique sua conexão e tente novamente.",
        variant: "destructive",
      });
    } finally {
      setIsGenerating(false);
    }
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(editedContent);
      toast({
        title: "Conteúdo copiado!",
        description: "O conteúdo foi copiado para a área de transferência.",
      });
    } catch (error) {
      toast({
        title: "Erro ao copiar",
        description: "Não foi possível copiar o conteúdo.",
        variant: "destructive",
      });
    }
  };

  const handleSave = async () => {
    if (!user || !activeCompany || !data.clientId) {
      toast({
        title: "Erro ao salvar",
        description: "Dados de usuário não encontrados.",
        variant: "destructive",
      });
      return;
    }

    try {
      const { error } = await supabase
        .from('content_generations')
        .insert({
          user_id: user.id,
          company_id: activeCompany.company_id,
          client_id: data.clientId,
          content_type: contentType.id,
          theme: data.theme,
          generated_content: editedContent,
          status: 'saved'
        });

      if (error) {
        console.error('Error saving content:', error);
        toast({
          title: "Erro ao salvar",
          description: "Não foi possível salvar o conteúdo.",
          variant: "destructive",
        });
        return;
      }

      toast({
        title: "Conteúdo salvo!",
        description: "O conteúdo foi salvo como rascunho.",
      });
    } catch (error) {
      console.error('Error:', error);
      toast({
        title: "Erro ao salvar",
        description: "Verifique sua conexão e tente novamente.",
        variant: "destructive",
      });
    }
  };

  const handleRegenerate = () => {
    onContentGenerated("");
    setEditedContent("");
    generateContent();
  };

  if (isGenerating) {
    return (
      <Card>
        <CardContent className="flex flex-col items-center justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-primary mb-4" />
          <h3 className="text-lg font-semibold mb-2">Gerando conteúdo...</h3>
          <p className="text-muted-foreground text-center">
            Nossa IA está criando conteúdo personalizado baseado no cliente e tema selecionados.
          </p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Generation Summary */}
      <Card className="bg-primary/5 border-primary/20">
        <CardContent className="pt-6">
          <div className="flex items-center gap-2 mb-3">
            <Sparkles className="w-5 h-5 text-primary" />
            <h3 className="font-semibold text-primary">Conteúdo Gerado</h3>
          </div>
          <div className="flex flex-wrap gap-2">
            <Badge variant="secondary">{contentType.title}</Badge>
            <Badge variant="outline">{data.theme}</Badge>
          </div>
        </CardContent>
      </Card>

      {/* Generated Content */}
      <Card>
        <CardHeader className="pb-4">
          <CardTitle className="flex items-center justify-between">
            <span>Resultado</span>
            <Button
              variant="outline"
              size="sm"
              onClick={handleRegenerate}
              disabled={isGenerating}
            >
              <RefreshCw className="w-4 h-4 mr-2" />
              Regenerar
            </Button>
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <Textarea
            value={editedContent}
            onChange={(e) => setEditedContent(e.target.value)}
            placeholder="O conteúdo gerado aparecerá aqui..."
            className="min-h-[300px] resize-none"
          />

          <div className="flex flex-wrap gap-2">
            <Button onClick={handleCopy} variant="outline">
              <Copy className="w-4 h-4 mr-2" />
              Copiar
            </Button>

            <Button onClick={handleSave} variant="outline">
              <Save className="w-4 h-4 mr-2" />
              Salvar como Rascunho
            </Button>

            <Button variant="outline" disabled>
              <Plus className="w-4 h-4 mr-2" />
              Adicionar à Campanha
            </Button>
          </div>

          <p className="text-xs text-muted-foreground">
            Você pode editar o conteúdo acima antes de copiá-lo ou salvá-lo.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Lightbulb, Sparkles } from "lucide-react";
import { ContentType } from "./ContentTypes";
import { useClients } from "@/hooks/useClients";
import { useCampaigns } from "@/hooks/useCampaigns";
import { useCompetitors } from "@/hooks/useCompetitors";

interface ThemeStepProps {
  clientId: string;
  contentType: ContentType;
  selectedTheme: string;
  onThemeSelect: (theme: string) => void;
}

export function ThemeStep({ clientId, contentType, selectedTheme, onThemeSelect }: ThemeStepProps) {
  const [customTheme, setCustomTheme] = useState("");
  const [suggestedThemes, setSuggestedThemes] = useState<string[]>([]);
  const { clients } = useClients();
  const { campaigns } = useCampaigns();
  const { competitors } = useCompetitors();

  const client = clients.find(c => c.id === clientId);

  useEffect(() => {
    if (client) {
      generateSuggestedThemes();
    }
  }, [client, clientId]);

  const generateSuggestedThemes = () => {
    const themes: string[] = [];

    // Base themes from client briefing
    if (client?.objectives) {
      themes.push(`Soluções para ${client.objectives.toLowerCase()}`);
    }

    if (client?.sector) {
      themes.push(`Tendências no setor ${client.sector.toLowerCase()}`);
      themes.push(`Inovação em ${client.sector.toLowerCase()}`);
    }

    if (client?.product_name) {
      themes.push(`Benefícios do ${client.product_name}`);
      themes.push(`Como escolher ${client.product_name}`);
    }

    // Themes from recent campaigns
    const clientCampaigns = campaigns.filter(c => c.client_id === clientId);
    if (clientCampaigns.length > 0) {
      themes.push("Performance de campanhas recentes");
      themes.push("Cases de sucesso");
    }

    // Themes based on competitors
    const clientCompetitors = competitors.filter(c => c.client_id === clientId);
    if (clientCompetitors.length > 0) {
      themes.push("Diferenciais competitivos");
      themes.push("Análise de mercado");
    }

    // Generic themes based on content type
    const genericThemes = getGenericThemesByContentType(contentType.id);
    themes.push(...genericThemes);

    // Remove duplicates and limit to 6
    setSuggestedThemes([...new Set(themes)].slice(0, 6));
  };

  const getGenericThemesByContentType = (contentTypeId: string): string[] => {
    const themeMap: Record<string, string[]> = {
      'roteiro-tiktok': ['Dicas rápidas', 'Trending topics', 'Desafios virais'],
      'roteiro-youtube-shorts': ['Tutorial express', 'Curiosidades', 'Dicas práticas'],
      'titulos-youtube': ['Como fazer', 'Segredos revelados', 'Guia completo'],
      'ideias-instagram': ['Behind the scenes', 'Dicas do dia', 'Transformação'],
      'facebook-ads': ['Oferta especial', 'Benefícios únicos', 'Testemunhos'],
      'email-marketing': ['Novidades exclusivas', 'Oferta limitada', 'Conteúdo premium'],
      'landing-page': ['Solução definitiva', 'Resultado garantido', 'Transformação'],
      'post-comemorativo': ['Dia das Mães', 'Black Friday', 'Natal'],
      'post-autoridade': ['Case de sucesso', 'Premiação recebida', 'Certificação'],
    };

    return themeMap[contentTypeId] || ['Novidades do mercado', 'Dicas especializadas', 'Tendências atuais'];
  };

  const handleThemeSelect = (theme: string) => {
    onThemeSelect(theme);
    setCustomTheme("");
  };

  const handleCustomThemeSubmit = () => {
    if (customTheme.trim()) {
      onThemeSelect(customTheme.trim());
    }
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader className="pb-4">
          <CardTitle className="flex items-center gap-2">
            <Lightbulb className="w-5 h-5 text-primary" />
            Escolha o Tema
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          <p className="text-sm text-muted-foreground">
            Selecione um tema sugerido baseado no perfil do cliente ou digite um tema personalizado.
          </p>

          {/* Suggested Themes */}
          <div className="space-y-3">
            <Label className="text-sm font-medium flex items-center gap-2">
              <Sparkles className="w-4 h-4" />
              Temas Sugeridos
            </Label>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {suggestedThemes.map((theme, index) => (
                <Button
                  key={index}
                  variant={selectedTheme === theme ? "default" : "outline"}
                  className="justify-start h-auto p-3 text-left"
                  onClick={() => handleThemeSelect(theme)}
                >
                  {theme}
                </Button>
              ))}
            </div>
          </div>

          {/* Custom Theme */}
          <div className="space-y-3">
            <Label htmlFor="custom-theme" className="text-sm font-medium">
              Tema Personalizado
            </Label>
            <div className="flex gap-2">
              <Input
                id="custom-theme"
                placeholder="Digite seu tema personalizado..."
                value={customTheme}
                onChange={(e) => setCustomTheme(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleCustomThemeSubmit()}
              />
              <Button 
                onClick={handleCustomThemeSubmit}
                disabled={!customTheme.trim()}
              >
                Usar
              </Button>
            </div>
          </div>

          {/* Selected Theme Display */}
          {selectedTheme && (
            <div className="p-3 bg-primary/5 rounded-lg border border-primary/20">
              <div className="flex items-center gap-2 text-primary font-medium text-sm">
                <Sparkles className="w-4 h-4" />
                Tema Selecionado
              </div>
              <Badge variant="secondary" className="mt-2">
                {selectedTheme}
              </Badge>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Client Context */}
      {client && (
        <Card className="bg-muted/50">
          <CardContent className="pt-6">
            <h4 className="font-medium text-sm mb-2">Contexto do Cliente:</h4>
            <div className="text-xs text-muted-foreground space-y-1">
              <p><strong>Cliente:</strong> {client.name} ({client.company})</p>
              {client.sector && <p><strong>Setor:</strong> {client.sector}</p>}
              {client.target_audience && <p><strong>Público:</strong> {client.target_audience}</p>}
              {client.voice_tone && <p><strong>Tom:</strong> {client.voice_tone}</p>}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { CheckCircle, FileText, Target, Users, MessageSquare, Quote, Sparkles, Loader2 } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useClients } from "@/hooks/useClients";
import { toast } from "@/hooks/use-toast";

interface CreativeContext {
  title: string;
  description: string;
  objective: string;
  targetAudience: string;
  copy: string;
  caption: string;
}

interface CreativeContextValidatorProps {
  context: CreativeContext;
  onContextUpdate: <K extends keyof CreativeContext>(key: K, value: CreativeContext[K]) => void;
  theme: string;
  clientId: string;
  creativeType: string;
}

export function CreativeContextValidator({ 
  context, 
  onContextUpdate, 
  theme, 
  clientId, 
  creativeType 
}: CreativeContextValidatorProps) {
  const [isGenerating, setIsGenerating] = useState(false);
  const [hasAutoGenerated, setHasAutoGenerated] = useState(false);
  const { clients } = useClients();

  const client = clients?.find(c => c.id === clientId);

  const completedFields = Object.values(context).filter(value => value.trim() !== "").length;
  const totalFields = Object.keys(context).length;
  const completionPercentage = Math.round((completedFields / totalFields) * 100);
  const hasEmptyFields = completedFields === 0;

  const generateContextWithAI = async () => {

    if (!theme || !clientId) {
      toast({
        title: "Erro",
        description: `Dados incompletos: tema="${theme}", clientId="${clientId}"`,
        variant: "destructive",
      });
      return;
    }

    if (!client) {
      toast({
        title: "Erro", 
        description: `Cliente não encontrado para ID: ${clientId}`,
        variant: "destructive",
      });
      return;
    }

    setIsGenerating(true);
    try {

      const { data, error } = await supabase.functions.invoke('generate-creative-context', {
        body: {
          theme,
          creativeType,
          clientBriefing: client.ai_briefing || '',
          clientSector: client.sector || '',
          targetAudience: client.notes || '',
          voiceTone: client.voice_tone || ''
        }
      });


      if (error) throw error;

      if (data?.context) {
        // Atualizar todos os campos do contexto
        Object.entries(data.context).forEach(([key, value]) => {
          onContextUpdate(key as keyof CreativeContext, value as string);
        });

        toast({
          title: "Contexto gerado com sucesso!",
          description: "Os campos foram preenchidos automaticamente com base no tema escolhido.",
        });
      }
    } catch (error: unknown) {
      console.error('Error generating context:', error);
      toast({
        title: "Erro ao gerar contexto",
        description: "Não foi possível gerar o contexto automaticamente. Preencha manualmente.",
        variant: "destructive",
      });
    } finally {
      setIsGenerating(false);
    }
  };

  // Auto-gerar contexto quando entrar na tela pela primeira vez
  useEffect(() => {
    if (theme && clientId && client && !isGenerating && !hasAutoGenerated) {
      setHasAutoGenerated(true);
      generateContextWithAI();
    }
  }, [theme, clientId, client, hasAutoGenerated]);

  const fieldConfigs = [
    {
      key: "title" as keyof CreativeContext,
      label: "Título/Headline",
      placeholder: "Ex: Black Friday 2024 - Até 50% OFF",
      icon: FileText,
      description: "Título principal que aparecerá no criativo",
      required: true,
    },
    {
      key: "description" as keyof CreativeContext,
      label: "Descrição da Peça",
      placeholder: "Ex: Criativo promocional para Black Friday destacando descontos em produtos premium",
      icon: FileText,
      description: "Descrição detalhada do que o criativo deve comunicar",
      multiline: true,
      required: true,
    },
    {
      key: "objective" as keyof CreativeContext,
      label: "Objetivo do Criativo",
      placeholder: "Ex: Aumentar vendas durante Black Friday, gerar leads, aumentar awareness",
      icon: Target,
      description: "Qual o objetivo principal desta peça",
      required: true,
    },
    {
      key: "targetAudience" as keyof CreativeContext,
      label: "Público-alvo Específico",
      placeholder: "Ex: Mulheres 25-45 anos, classe B/C, interessadas em moda",
      icon: Users,
      description: "Público específico para este criativo (pode ser diferente do cliente geral)",
      required: false,
    },
    {
      key: "copy" as keyof CreativeContext,
      label: "Copy da Imagem (TEXTO QUE APARECERÁ NA IMAGEM) ⭐",
      placeholder: "Ex: BLACK FRIDAY\\n50% OFF\\nCompre agora!",
      icon: Quote,
      description: "ESTE TEXTO aparecerá EXATAMENTE como escrito na imagem gerada (máximo 3-4 linhas)",
      multiline: true,
      required: true,
    },
    {
      key: "caption" as keyof CreativeContext,
      label: "Legenda Sugerida",
      placeholder: "Ex: 🔥 BLACK FRIDAY chegou! Corre que é só até domingo! #BlackFriday #Promoção",
      icon: MessageSquare,
      description: "Legenda para acompanhar o post nas redes sociais",
      multiline: true,
      required: false,
    },
  ];

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-medium mb-2">Validar Contexto Criativo</h3>
          <p className="text-muted-foreground">
            Revise e aprove o contexto antes de gerar a imagem
          </p>
        </div>

        <div className="flex items-center gap-3">
          <Button 
            onClick={generateContextWithAI}
            disabled={isGenerating}
            variant="outline"
            size="sm"
            className="gap-2"
          >
            {isGenerating ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Sparkles className="w-4 h-4" />
            )}
            {isGenerating ? "Gerando..." : "Gerar com IA"}
          </Button>

          <Badge variant={completionPercentage === 100 ? "default" : "secondary"}>
            {completionPercentage}% completo
          </Badge>
          {completionPercentage === 100 && (
            <CheckCircle className="w-5 h-5 text-green-600" />
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {fieldConfigs.map((field) => {
          const Icon = field.icon;
          const value = context[field.key];
          const isCompleted = value.trim() !== "";

          return (
            <Card 
              key={field.key} 
              className={cn(
                "transition-all duration-200",
                isCompleted ? "border-green-200 bg-green-50/50" : "border-border"
              )}
            >
              <CardHeader className="pb-3">
                <div className="flex items-center gap-2">
                  <Icon className={cn(
                    "w-4 h-4",
                    isCompleted ? "text-green-600" : "text-muted-foreground"
                  )} />
                  <CardTitle className="text-sm font-medium">
                    {field.label}
                    {field.required && <span className="text-red-500 ml-1">*</span>}
                  </CardTitle>
                  {isCompleted && (
                    <CheckCircle className="w-4 h-4 text-green-600 ml-auto" />
                  )}
                </div>
                <p className="text-xs text-muted-foreground">
                  {field.description}
                </p>
              </CardHeader>

              <CardContent className="pt-0">
                <div className="space-y-2">
                  <Label htmlFor={field.key} className="sr-only">
                    {field.label}
                  </Label>

                  {field.multiline ? (
                    <Textarea
                      id={field.key}
                      placeholder={field.placeholder}
                      value={value}
                      onChange={(e) => onContextUpdate(field.key, e.target.value)}
                      rows={field.key === "copy" ? 4 : 3}
                      className={cn(
                        "resize-none",
                        isCompleted && "border-green-300 focus:border-green-400"
                      )}
                    />
                  ) : (
                    <Input
                      id={field.key}
                      placeholder={field.placeholder}
                      value={value}
                      onChange={(e) => onContextUpdate(field.key, e.target.value)}
                      className={cn(
                        isCompleted && "border-green-300 focus:border-green-400"
                      )}
                    />
                  )}

                  {field.key === "copy" && (
                    <div className="space-y-1">
                      <p className="text-xs text-muted-foreground">
                        💡 Use \\n para quebras de linha. Este texto será usado EXATAMENTE como está na imagem.
                      </p>
                      <p className="text-xs text-orange-600 font-medium">
                        ⚠️ IMPORTANTE: Este texto aparecerá na imagem final sem modificações.
                      </p>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {completionPercentage > 60 && (
        <Card className="bg-blue-50 border-blue-200">
          <CardContent className="p-4">
            <div className="flex items-start gap-3">
              <CheckCircle className="w-5 h-5 text-blue-600 mt-0.5 flex-shrink-0" />
              <div className="space-y-1">
                <h5 className="font-medium text-blue-900">Contexto quase pronto!</h5>
                <p className="text-sm text-blue-700">
                  {completionPercentage === 100 
                    ? "Todos os campos estão preenchidos. Você pode prosseguir para a geração da imagem."
                    : `Complete os campos obrigatórios restantes para prosseguir.`
                  }
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {completionPercentage < 50 && (
        <Card className="bg-yellow-50 border-yellow-200">
          <CardContent className="p-4">
            <div className="flex items-start gap-3">
              <Target className="w-5 h-5 text-yellow-600 mt-0.5 flex-shrink-0" />
              <div className="space-y-1">
                <h5 className="font-medium text-yellow-900">Mais informações necessárias</h5>
                <p className="text-sm text-yellow-700">
                  Preencha pelo menos os campos obrigatórios (*) para gerar um criativo de qualidade.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

function cn(...classes: (string | boolean | undefined)[]): string {
  return classes.filter(Boolean).join(' ');
}

import React, { useState, useMemo, useEffect } from "react";
