export function DashboardSidebar() {
  const { open, setOpen } = useSidebar();
  const location = useLocation();
  const currentPath = location.pathname;
  const { hasPermission, permissionsLoading, isOwner } = useEmployeePermissions();
  const { unresolvedCriticalCount } = useSystemAlerts();
  const { token: tvToken, generateToken, generating: generatingToken } = useCompanyTvDashboardToken();
  const { token: socialTvToken, generateToken: generateSocialTvToken, generating: generatingSocialTvToken } = useSocialTvDashboardToken();
  const { token: radarTvToken, generateToken: generateRadarTvToken, generating: generatingRadarTvToken } = useRadarTvDashboardToken();
  const { token: csTvToken, generateToken: generateCsTvToken, generating: generatingCsTvToken } = useCsTvDashboardToken();

  // Track which categories are expanded
  const [expandedCategories, setExpandedCategories] = useState<Record<string, boolean>>(() => {
    const initial: Record<string, boolean> = {};
    menuCategories.forEach(cat => {
      initial[cat.title] = cat.defaultOpen || false;
    });
    return initial;
  });

  const isActive = (path: string) => currentPath === path || currentPath.startsWith(path + '/');

  // Filter categories and items based on permissions and add dynamic badges
  const visibleCategories = useMemo(() => {
    return menuCategories.map(category => {
      const filteredItems = category.items.filter(item => {
        if (isOwner) return true;
        if (permissionsLoading) {
          return item.permission === 'dashboard' || item.permission === 'tarefas';
        }
        return hasPermission(item.permission);
      }).map(item => {
        // Add dynamic badge for Alertas
        if (item.url === '/alertas' && unresolvedCriticalCount > 0) {
          return { ...item, badge: unresolvedCriticalCount };
        }
        return item;
      });

      return { ...category, items: filteredItems };
    }).filter(category => category.items.length > 0);
  }, [permissionsLoading, isOwner, hasPermission, unresolvedCriticalCount]);

  // Auto-expand category containing active route
  React.useEffect(() => {
    visibleCategories.forEach(category => {
      const hasActiveItem = category.items.some(item => isActive(item.url));
      if (hasActiveItem && !expandedCategories[category.title]) {
        setExpandedCategories(prev => ({ ...prev, [category.title]: true }));
      }
    });
  }, [currentPath]);

  const toggleCategory = (categoryTitle: string) => {
    setExpandedCategories(prev => ({
      ...prev,
      [categoryTitle]: !prev[categoryTitle],
    }));
  };

  return (
    <>
      {/* Overlay when sidebar is expanded */}
      {open && (
        <div 
          className="fixed inset-0 bg-black/20 z-40 transition-opacity duration-200"
          onClick={() => setOpen(false)}
        />
      )}

      {/* Google-style Sidebar */}
      <div
        className={cn(
          "fixed left-0 top-0 h-full z-50 transition-all duration-200 ease-in-out bg-card shadow-google-sm flex flex-col",
          open ? "w-[280px]" : "w-[72px]"
        )}
        onMouseEnter={() => setOpen(true)}
        onMouseLeave={() => setOpen(false)}
      >
        {/* Logo area */}
        <div className="h-16 flex items-center px-5 flex-shrink-0">
          <img 
            src="https://i.imgur.com/RMzwUaa.png" 
            alt="Expx Flow" 
            className="w-8 h-8 object-contain flex-shrink-0"
          />
          {open && (
            <span className="ml-4 text-base font-medium text-foreground tracking-tight whitespace-nowrap">
              Expx Flow
            </span>
          )}
        </div>

        {/* Navigation */}
        <nav className="flex-1 px-3 py-2 overflow-y-auto overflow-x-hidden">
          <div className="space-y-1">
            {visibleCategories.map((category) => (
              <Collapsible
                key={category.title}
                open={open ? expandedCategories[category.title] : false}
                onOpenChange={() => open && toggleCategory(category.title)}
              >
                {/* Category Header */}
                <CollapsibleTrigger asChild>
                  <button
                    className={cn(
                      "w-full flex items-center gap-3 py-2.5 rounded-full transition-all duration-150",
                      open ? "px-4 hover:bg-muted/50" : "px-0 justify-center",
                      "text-muted-foreground"
                    )}
                    title={!open ? category.title : undefined}
                  >
                    <category.icon 
                      className="w-5 h-5 flex-shrink-0 text-muted-foreground" 
                      strokeWidth={1.5}
                    />
                    {open && (
                      <>
                        <span className="text-sm font-medium tracking-wide whitespace-nowrap flex-1 text-left text-foreground">
                          {category.title}
                        </span>
                        <ChevronDown 
                          className={cn(
                            "w-4 h-4 transition-transform duration-200 text-muted-foreground",
                            expandedCategories[category.title] && "rotate-180"
                          )}
                        />
                      </>
                    )}
                  </button>
                </CollapsibleTrigger>

                {/* Category Items */}
                <CollapsibleContent className="overflow-hidden data-[state=open]:animate-accordion-down data-[state=closed]:animate-accordion-up">
                  <div className={cn("space-y-0.5", open ? "ml-4 mt-1" : "mt-1")}>
                    {category.items.map((item) => {
                      // Handle external Dashboard TV link (Marketing & Tráfego)
                      if (item.isExternal && item.url === '#tv-dashboard') {
                        const handleTvDashboardClick = async (e: React.MouseEvent) => {
                          e.preventDefault();
                          if (tvToken) {
                            window.open(`/tv/${tvToken}`, '_blank');
                          } else {
                            const newToken = await generateToken();
                            if (newToken) {
                              window.open(`/tv/${newToken}`, '_blank');
                            }
                          }
                        };

                        return (
                          <button
                            key={item.url}
                            onClick={handleTvDashboardClick}
                            disabled={generatingToken}
                            className={cn(
                              "flex items-center py-2 rounded-full transition-all duration-150 w-full",
                              open ? "gap-3 px-4" : "justify-center px-0",
                              "text-muted-foreground hover:bg-muted/50"
                            )}
                            title={!open ? item.title : undefined}
                          >
                            <item.icon 
                              className="w-4 h-4 flex-shrink-0 text-muted-foreground" 
                              strokeWidth={1.5}
                            />
                            {open && (
                              <>
                                <span className="text-sm tracking-wide whitespace-nowrap text-foreground">
                                  {generatingToken ? 'Gerando...' : item.title}
                                </span>
                                <ExternalLink className="w-3 h-3 ml-auto text-muted-foreground" />
                              </>
                            )}
                          </button>
                        );
                      }

                      // Handle external Social TV Dashboard link (Conteúdo & Social)
                      if (item.isExternal && item.url === '#social-tv-dashboard') {
                        const handleSocialTvDashboardClick = async (e: React.MouseEvent) => {
                          e.preventDefault();
                          if (socialTvToken) {
                            window.open(`/social-tv/${socialTvToken}`, '_blank');
                          } else {
                            const newToken = await generateSocialTvToken();
                            if (newToken) {
                              window.open(`/social-tv/${newToken}`, '_blank');
                            }
                          }
                        };

                        return (
                          <button
                            key={item.url}
                            onClick={handleSocialTvDashboardClick}
                            disabled={generatingSocialTvToken}
                            className={cn(
                              "flex items-center py-2 rounded-full transition-all duration-150 w-full",
                              open ? "gap-3 px-4" : "justify-center px-0",
                              "text-muted-foreground hover:bg-muted/50"
                            )}
                            title={!open ? item.title : undefined}
                          >
                            <item.icon 
                              className="w-4 h-4 flex-shrink-0 text-muted-foreground" 
                              strokeWidth={1.5}
                            />
                            {open && (
                              <>
                                <span className="text-sm tracking-wide whitespace-nowrap text-foreground">
                                  {generatingSocialTvToken ? 'Gerando...' : item.title}
                                </span>
                                <ExternalLink className="w-3 h-3 ml-auto text-muted-foreground" />
                              </>
                            )}
                          </button>
                        );
                      }

                      // Handle external Radar TV Dashboard link (Marketing & Tráfego)
                      if (item.isExternal && item.url === '#radar-tv-dashboard') {
                        const handleRadarTvDashboardClick = async (e: React.MouseEvent) => {
                          e.preventDefault();
                          if (radarTvToken) {
                            window.open(`/radar-tv/${radarTvToken}`, '_blank');
                          } else {
                            const newToken = await generateRadarTvToken();
                            if (newToken) {
                              window.open(`/radar-tv/${newToken}`, '_blank');
                            }
                          }
                        };

                        return (
                          <button
                            key={item.url}
                            onClick={handleRadarTvDashboardClick}
                            disabled={generatingRadarTvToken}
                            className={cn(
                              "flex items-center py-2 rounded-full transition-all duration-150 w-full",
                              open ? "gap-3 px-4" : "justify-center px-0",
                              "text-muted-foreground hover:bg-muted/50"
                            )}
                            title={!open ? item.title : undefined}
                          >
                            <item.icon 
                              className="w-4 h-4 flex-shrink-0 text-muted-foreground" 
                              strokeWidth={1.5}
                            />
                            {open && (
                              <>
                                <span className="text-sm tracking-wide whitespace-nowrap text-foreground">
                                  {generatingRadarTvToken ? 'Gerando...' : item.title}
                                </span>
                                <ExternalLink className="w-3 h-3 ml-auto text-muted-foreground" />
                              </>
                            )}
                          </button>
                        );
                      }

                      // Handle external CS TV Dashboard link (Customer Success)
                      if (item.isExternal && item.url === '#cs-tv-dashboard') {
                        const handleCsTvDashboardClick = async (e: React.MouseEvent) => {
                          e.preventDefault();
                          if (csTvToken) {
                            window.open(`/cs-tv/${csTvToken}`, '_blank');
                          } else {
                            const newToken = await generateCsTvToken();
                            if (newToken) {
                              window.open(`/cs-tv/${newToken}`, '_blank');
                            }
                          }
                        };

                        return (
                          <button
                            key={item.url}
                            onClick={handleCsTvDashboardClick}
                            disabled={generatingCsTvToken}
                            className={cn(
                              "flex items-center py-2 rounded-full transition-all duration-150 w-full",
                              open ? "gap-3 px-4" : "justify-center px-0",
                              "text-muted-foreground hover:bg-muted/50"
                            )}
                            title={!open ? item.title : undefined}
                          >
                            <item.icon 
                              className="w-4 h-4 flex-shrink-0 text-muted-foreground" 
                              strokeWidth={1.5}
                            />
                            {open && (
                              <>
                                <span className="text-sm tracking-wide whitespace-nowrap text-foreground">
                                  {generatingCsTvToken ? 'Gerando...' : item.title}
                                </span>
                                <ExternalLink className="w-3 h-3 ml-auto text-muted-foreground" />
                              </>
                            )}
                          </button>
                        );
                      }
                      // Handle items with children (sub-menu)
                      if (item.children && item.children.length > 0) {
                        const subMenuKey = `${category.title}-${item.title}`;
                        const isSubMenuActive = item.children.some(child => 
                          !child.isExternal && isActive(child.url)
                        );
                        return (
                          <Collapsible 
                            key={item.url + '-submenu'} 
                            open={open ? (expandedCategories[subMenuKey] ?? isSubMenuActive) : false}
                            onOpenChange={() => open && toggleCategory(subMenuKey)}
                          >
                            <CollapsibleTrigger asChild>
                              <button
                                className={cn(
                                  "w-full flex items-center py-2 rounded-full transition-all duration-150",
                                  open ? "gap-3 px-4" : "justify-center px-0",
                                  isSubMenuActive
                                    ? "bg-primary/10 text-primary"
                                    : "text-muted-foreground hover:bg-muted/50"
                                )}
                                title={!open ? item.title : undefined}
                              >
                                <item.icon
                                  className={cn(
                                    "w-4 h-4 flex-shrink-0",
                                    isSubMenuActive ? "text-primary" : "text-muted-foreground"
                                  )}
                                  strokeWidth={isSubMenuActive ? 2 : 1.5}
                                />
                                {open && (
                                  <>
                                    <span className={cn(
                                      "text-sm tracking-wide whitespace-nowrap flex-1 text-left",
                                      isSubMenuActive ? "text-primary font-medium" : "text-foreground"
                                    )}>
                                      {item.title}
                                    </span>
                                    <ChevronDown
                                      className={cn(
                                        "w-3 h-3 transition-transform duration-200 text-muted-foreground",
                                        (expandedCategories[subMenuKey] ?? isSubMenuActive) && "rotate-180"
                                      )}
                                    />
                                  </>
                                )}
                              </button>
                            </CollapsibleTrigger>
                            <CollapsibleContent className="overflow-hidden">
                              <div className={cn("space-y-0.5", open ? "ml-4 mt-0.5 border-l border-border pl-2" : "mt-0.5")}>
                                {item.children.map((child) => {
                                  // Re-use the same external link handlers for children
                                  if (child.isExternal && child.url === '#tv-dashboard') {
                                    const handleClick = async (e: React.MouseEvent) => {
                                      e.preventDefault();
                                      if (tvToken) { window.open(`/tv/${tvToken}`, '_blank'); }
                                      else { const t = await generateToken(); if (t) window.open(`/tv/${t}`, '_blank'); }
                                    };
                                    return (
                                      <button key={child.url} onClick={handleClick} disabled={generatingToken}
                                        className={cn("flex items-center py-2 rounded-full transition-all duration-150 w-full", open ? "gap-3 px-4" : "justify-center px-0", "text-muted-foreground hover:bg-muted/50")}
                                        title={!open ? child.title : undefined}>
                                        <child.icon className="w-4 h-4 flex-shrink-0 text-muted-foreground" strokeWidth={1.5} />
                                        {open && (<><span className="text-sm tracking-wide whitespace-nowrap text-foreground">{generatingToken ? 'Gerando...' : child.title}</span><ExternalLink className="w-3 h-3 ml-auto text-muted-foreground" /></>)}
                                      </button>
                                    );
                                  }
                                  if (child.isExternal && child.url === '#radar-tv-dashboard') {
                                    const handleClick = async (e: React.MouseEvent) => {
                                      e.preventDefault();
                                      if (radarTvToken) { window.open(`/radar-tv/${radarTvToken}`, '_blank'); }
                                      else { const t = await generateRadarTvToken(); if (t) window.open(`/radar-tv/${t}`, '_blank'); }
                                    };
                                    return (
                                      <button key={child.url} onClick={handleClick} disabled={generatingRadarTvToken}
                                        className={cn("flex items-center py-2 rounded-full transition-all duration-150 w-full", open ? "gap-3 px-4" : "justify-center px-0", "text-muted-foreground hover:bg-muted/50")}
                                        title={!open ? child.title : undefined}>
                                        <child.icon className="w-4 h-4 flex-shrink-0 text-muted-foreground" strokeWidth={1.5} />
                                        {open && (<><span className="text-sm tracking-wide whitespace-nowrap text-foreground">{generatingRadarTvToken ? 'Gerando...' : child.title}</span><ExternalLink className="w-3 h-3 ml-auto text-muted-foreground" /></>)}
                                      </button>
                                    );
                                  }
                                  return (
                                    <NavLink key={child.url} to={child.url} end
                                      className={({ isActive: active }) => cn(
                                        "flex items-center py-2 rounded-full transition-all duration-150",
                                        open ? "gap-3 px-4" : "justify-center px-0",
                                        active ? "bg-primary/10 text-primary" : "text-muted-foreground hover:bg-muted/50"
                                      )}
                                      title={!open ? child.title : undefined}>
                                      <child.icon className={cn("w-4 h-4 flex-shrink-0", isActive(child.url) ? "text-primary" : "text-muted-foreground")} strokeWidth={isActive(child.url) ? 2 : 1.5} />
                                      {open && (<span className={cn("text-sm tracking-wide whitespace-nowrap", isActive(child.url) ? "text-primary font-medium" : "text-foreground")}>{child.title}</span>)}
                                    </NavLink>
                                  );
                                })}
                              </div>
                            </CollapsibleContent>
                          </Collapsible>
                        );
                      }

                      return (
                        <NavLink 
                          key={item.url}
                          to={item.url} 
                          end={item.url === "/dashboard"}
                          className={({ isActive: active }) =>
                            cn(
                              "flex items-center py-2 rounded-full transition-all duration-150",
                              open ? "gap-3 px-4" : "justify-center px-0",
                              active
                                ? "bg-primary/10 text-primary"
                                : "text-muted-foreground hover:bg-muted/50"
                            )
                          }
                          title={!open ? item.title : undefined}
                        >
                          <item.icon 
                            className={cn(
                              "w-4 h-4 flex-shrink-0 transition-colors duration-150",
                              isActive(item.url) ? "text-primary" : "text-muted-foreground"
                            )} 
                            strokeWidth={isActive(item.url) ? 2 : 1.5}
                          />
                          {open && (
                            <span className={cn(
                              "text-sm tracking-wide whitespace-nowrap",
                              isActive(item.url) ? "text-primary font-medium" : "text-foreground"
                            )}>
                              {item.title}
                            </span>
                          )}
                          {item.badge && item.badge > 0 && open && (
                            <span className="ml-auto bg-destructive text-destructive-foreground text-xs font-medium px-2 py-0.5 rounded-full">
                              {item.badge}
                            </span>
                          )}
                        </NavLink>
                      );
                    })}
                  </div>
                </CollapsibleContent>
              </Collapsible>
            ))}
          </div>
        </nav>
      </div>
    </>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Loader2, UserCircle, Save, ChevronsUpDown, Check, RefreshCw } from "lucide-react";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command";
import { cn } from "@/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import { useDiscordConfig } from "@/hooks/useDiscordConfig";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

interface DiscordMember {
  id: string;
  username: string;
  display_name: string;
  avatar: string | null;
}

export const DiscordEmployeeMapping = () => {
  const { config, listGuildMembers, companyId } = useDiscordConfig();
  const queryClient = useQueryClient();
  const [mappings, setMappings] = useState<Record<string, { discord_user_id: string; discord_username: string }>>({});
  const [saving, setSaving] = useState(false);
  const [members, setMembers] = useState<DiscordMember[]>([]);
  const [loadingMembers, setLoadingMembers] = useState(false);
  const [openPopovers, setOpenPopovers] = useState<Record<string, boolean>>({});

  const { data: employees, isLoading } = useQuery({
    queryKey: ["employees-discord", companyId],
    queryFn: async () => {
      const { data, error } = await (supabase as unknown)
        .from("employees")
        .select("id, name, email, discord_user_id, discord_username")
        .eq("company_id", companyId!)
        .eq("status", "active")
        .order("name");
      if (error) throw error;
      return data;
    },
    enabled: !!companyId,
  });

  useEffect(() => {
    if (employees) {
      const initial: Record<string, unknown> = {};
      employees.forEach((e: unknown) => {
        initial[e.id] = {
          discord_user_id: e.discord_user_id || "",
          discord_username: e.discord_username || "",
        };
      });
      setMappings(initial);
    }
  }, [employees]);

  useEffect(() => {
    if (config?.guild_id && config?.is_connected) {
      fetchMembers();
    }
  }, [config?.guild_id, config?.is_connected]);

  const fetchMembers = async () => {
    if (!config?.guild_id) return;
    setLoadingMembers(true);
    try {
      const m = await listGuildMembers(config.guild_id);
      setMembers(m.sort((a: DiscordMember, b: DiscordMember) => a.display_name.localeCompare(b.display_name)));
    } catch (err: unknown) {
      toast.error("Erro ao carregar membros: " + err.message);
    } finally {
      setLoadingMembers(false);
    }
  };

  const handleSelectMember = (employeeId: string, member: DiscordMember | null) => {
    setMappings((prev) => ({
      ...prev,
      [employeeId]: {
        discord_user_id: member?.id || "",
        discord_username: member?.display_name || "",
      },
    }));
    setOpenPopovers((prev) => ({ ...prev, [employeeId]: false }));
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      for (const emp of employees || []) {
        const mapping = mappings[emp.id];
        if (mapping) {
          await (supabase as unknown)
            .from("employees")
            .update({
              discord_user_id: mapping.discord_user_id || null,
              discord_username: mapping.discord_username || null,
            })
            .eq("id", emp.id);
        }
      }
      queryClient.invalidateQueries({ queryKey: ["employees-discord"] });
      toast.success("Mapeamento de colaboradores atualizado!");
    } catch (err: unknown) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  if (!config?.is_connected) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <UserCircle className="h-5 w-5" /> Colaboradores × Discord
          </CardTitle>
          <CardDescription>Configure a conexão do bot primeiro para mapear colaboradores.</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-lg flex items-center gap-2">
              <UserCircle className="h-5 w-5" /> Colaboradores × Discord
            </CardTitle>
            <CardDescription>
              Associe os colaboradores às suas contas do Discord para receber notificações e menções.
            </CardDescription>
          </div>
          <Button variant="outline" size="sm" onClick={fetchMembers} disabled={loadingMembers}>
            <RefreshCw className={cn("h-4 w-4 mr-1", loadingMembers && "animate-spin")} />
            Atualizar
          </Button>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {isLoading || loadingMembers ? (
          <div className="flex items-center gap-2 text-muted-foreground">
            <Loader2 className="h-4 w-4 animate-spin" /> Carregando...
          </div>
        ) : (
          <>
            {members.length > 0 && (
              <p className="text-xs text-muted-foreground">
                {members.length} membros encontrados no servidor
              </p>
            )}
            <div className="grid gap-3">
              {employees?.map((emp: unknown) => {
                const selectedMember = members.find((m) => m.id === mappings[emp.id]?.discord_user_id);
                return (
                  <div key={emp.id} className="flex items-center gap-3 p-2 rounded-lg border">
                    <Avatar className="h-8 w-8">
                      <AvatarFallback className="text-xs">
                        {emp.name?.substring(0, 2).toUpperCase()}
                      </AvatarFallback>
                    </Avatar>
                    <div className="min-w-[120px]">
                      <p className="text-sm font-medium">{emp.name}</p>
                      <p className="text-xs text-muted-foreground">{emp.email}</p>
                    </div>
                    <Popover
                      open={openPopovers[emp.id] || false}
                      onOpenChange={(open) => setOpenPopovers((prev) => ({ ...prev, [emp.id]: open }))}
                    >
                      <PopoverTrigger asChild>
                        <Button
                          variant="outline"
                          role="combobox"
                          className="flex-1 justify-between"
                        >
                          {selectedMember ? (
                            <span className="flex items-center gap-2">
                              <span className="text-[#5865F2]">@</span>
                              {selectedMember.display_name}
                              <span className="text-xs text-muted-foreground">({selectedMember.username})</span>
                            </span>
                          ) : (
                            <span className="text-muted-foreground">Selecione um membro do Discord...</span>
                          )}
                          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                        </Button>
                      </PopoverTrigger>
                      <PopoverContent className="w-[320px] p-0" align="start">
                        <Command>
                          <CommandInput placeholder="Buscar membro..." />
                          <CommandList>
                            <CommandEmpty>Nenhum membro encontrado.</CommandEmpty>
                            <CommandGroup>
                              <CommandItem
                                onSelect={() => handleSelectMember(emp.id, null)}
                                className="text-muted-foreground"
                              >
                                <Check className={cn("mr-2 h-4 w-4", !mappings[emp.id]?.discord_user_id ? "opacity-100" : "opacity-0")} />
                                Nenhum
                              </CommandItem>
                              {members.map((member) => (
                                <CommandItem
                                  key={member.id}
                                  value={`${member.display_name} ${member.username}`}
                                  onSelect={() => handleSelectMember(emp.id, member)}
                                >
                                  <Check
                                    className={cn(
                                      "mr-2 h-4 w-4",
                                      mappings[emp.id]?.discord_user_id === member.id ? "opacity-100" : "opacity-0"
                                    )}
                                  />
                                  <span className="flex items-center gap-2">
                                    <span className="text-[#5865F2]">@</span>
                                    <span>{member.display_name}</span>
                                    <span className="text-xs text-muted-foreground">({member.username})</span>
                                  </span>
                                </CommandItem>
                              ))}
                            </CommandGroup>
                          </CommandList>
                        </Command>
                      </PopoverContent>
                    </Popover>
                  </div>
                );
              })}
            </div>
            <Button onClick={handleSave} disabled={saving}>
              {saving ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : <Save className="h-4 w-4 mr-2" />}
              Salvar Mapeamento
            </Button>
          </>
        )}
      </CardContent>
    </Card>
  );
};

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Loader2, Hash, Users, Save } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useDiscordConfig } from "@/hooks/useDiscordConfig";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

export const DiscordSquadChannels = () => {
  const { config, listChannels, companyId } = useDiscordConfig();
  const queryClient = useQueryClient();
  const [channels, setChannels] = useState<unknown[]>([]);
  const [loadingChannels, setLoadingChannels] = useState(false);
  const [assignments, setAssignments] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);

  const { data: squads, isLoading: loadingSquads } = useQuery({
    queryKey: ["squads-discord", companyId],
    queryFn: async () => {
      const { data, error } = await (supabase as unknown)
        .from("teams")
        .select("id, name, color, discord_channel_id, discord_channel_name")
        .eq("company_id", companyId!)
        .order("name");
      if (error) throw error;
      return data;
    },
    enabled: !!companyId,
  });

  useEffect(() => {
    if (squads) {
      const initial: Record<string, string> = {};
      squads.forEach((s: unknown) => {
        if (s.discord_channel_id) initial[s.id] = s.discord_channel_id;
      });
      setAssignments(initial);
    }
  }, [squads]);

  useEffect(() => {
    if (config?.guild_id && config?.is_connected) {
      fetchChannels();
    }
  }, [config?.guild_id, config?.is_connected]);

  const fetchChannels = async () => {
    if (!config?.guild_id) return;
    setLoadingChannels(true);
    try {
      const ch = await listChannels(config.guild_id);
      setChannels(ch);
    } catch (err: unknown) {
      toast.error("Erro ao carregar canais: " + err.message);
    } finally {
      setLoadingChannels(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      for (const squad of squads || []) {
        const channelId = assignments[squad.id] || null;
        const channel = channels.find((c) => c.id === channelId);
        await (supabase as unknown)
          .from("teams")
          .update({
            discord_channel_id: channelId,
            discord_channel_name: channel?.name || null,
          })
          .eq("id", squad.id);
      }
      queryClient.invalidateQueries({ queryKey: ["squads-discord"] });
      toast.success("Canais dos squads atualizados!");
    } catch (err: unknown) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  if (!config?.is_connected) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Users className="h-5 w-5" /> Squads × Canais
          </CardTitle>
          <CardDescription>Configure a conexão do bot primeiro para associar squads a canais.</CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg flex items-center gap-2">
          <Users className="h-5 w-5" /> Squads × Canais
        </CardTitle>
        <CardDescription>Associe cada squad a um canal do Discord para receber notificações.</CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {loadingSquads || loadingChannels ? (
          <div className="flex items-center gap-2 text-muted-foreground">
            <Loader2 className="h-4 w-4 animate-spin" /> Carregando...
          </div>
        ) : (
          <>
            {squads?.map((squad: unknown) => (
              <div key={squad.id} className="flex items-center gap-3">
                <div className="flex items-center gap-2 min-w-[140px]">
                  <div className="w-3 h-3 rounded-full" style={{ backgroundColor: squad.color || "#6366f1" }} />
                  <span className="text-sm font-medium">{squad.name}</span>
                </div>
                <Select
                  value={assignments[squad.id] || "none"}
                  onValueChange={(v) =>
                    setAssignments((prev) => ({ ...prev, [squad.id]: v === "none" ? "" : v }))
                  }
                >
                  <SelectTrigger className="flex-1">
                    <SelectValue placeholder="Selecione um canal" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">Nenhum</SelectItem>
                    {channels.map((ch) => (
                      <SelectItem key={ch.id} value={ch.id}>
                        <span className="flex items-center gap-1">
                          <Hash className="h-3 w-3" /> {ch.name}
                        </span>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {squad.discord_channel_name && (
                  <Badge variant="outline" className="text-xs whitespace-nowrap">
                    #{squad.discord_channel_name}
                  </Badge>
                )}
              </div>
            ))}
            <Button onClick={handleSave} disabled={saving} className="mt-2">
              {saving ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : <Save className="h-4 w-4 mr-2" />}
              Salvar Associações
            </Button>
          </>
        )}
      </CardContent>
    </Card>
  );
};

import { useEffect, useState, useMemo } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { CalendarDays, Building2, DollarSign, CheckCircle, AlertTriangle, Facebook, Unlink, RefreshCw, Shield, Instagram, ChevronDown, ChevronRight, Search } from "lucide-react";
import { useFacebookIntegration } from "@/hooks/useFacebookIntegration";
import { useFacebookPages } from "@/hooks/useFacebookPages";
import { useCompany } from "@/contexts/CompanyContext";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";

export const FacebookIntegrationSettings = () => {
  const { activeCompany } = useCompany();
  const { 
    loading, 
    integration, 
    adAccounts, 
    loadIntegration, 
    connectFacebook, 
    disconnectFacebook,
    refreshAdAccounts,
    checkScopes
  } = useFacebookIntegration();

  const { pages, instagramAccounts, refreshPages } = useFacebookPages();

  const [showScopesModal, setShowScopesModal] = useState(false);
  const [scopesData, setScopesData] = useState<unknown>(null);
  const [checkingScopes, setCheckingScopes] = useState(false);
  const [refreshingPages, setRefreshingPages] = useState(false);
  const [adAccountsOpen, setAdAccountsOpen] = useState(false);
  const [pagesOpen, setPagesOpen] = useState(false);
  const [instagramOpen, setInstagramOpen] = useState(false);

  // Search states
  const [adAccountSearch, setAdAccountSearch] = useState("");
  const [pagesSearch, setPagesSearch] = useState("");
  const [instagramSearch, setInstagramSearch] = useState("");

  // Filtered lists
  const filteredAdAccounts = useMemo(() => {
    if (!adAccountSearch.trim()) return adAccounts;
    const search = adAccountSearch.toLowerCase();
    return adAccounts.filter(account => 
      account.account_name?.toLowerCase().includes(search) ||
      account.id?.toLowerCase().includes(search)
    );
  }, [adAccounts, adAccountSearch]);

  const filteredPages = useMemo(() => {
    if (!pagesSearch.trim()) return pages;
    const search = pagesSearch.toLowerCase();
    return pages.filter(page => 
      page.page_name?.toLowerCase().includes(search) ||
      page.page_id?.toLowerCase().includes(search)
    );
  }, [pages, pagesSearch]);

  const filteredInstagramAccounts = useMemo(() => {
    if (!instagramSearch.trim()) return instagramAccounts;
    const search = instagramSearch.toLowerCase();
    return instagramAccounts.filter(account => 
      account.username?.toLowerCase().includes(search) ||
      account.instagram_id?.toLowerCase().includes(search)
    );
  }, [instagramAccounts, instagramSearch]);

  const handleCheckScopes = async () => {
    if (!activeCompany?.company_id) return;

    setCheckingScopes(true);
    const data = await checkScopes(activeCompany.company_id);
    setCheckingScopes(false);

    if (data) {
      setScopesData(data);
      setShowScopesModal(true);
    }
  };

  useEffect(() => {
    if (activeCompany?.company_id) {
      loadIntegration(activeCompany.company_id);
    }
  }, [activeCompany?.company_id]);

  const isConnected = integration && integration.is_active;
  const isExpired = integration && new Date(integration.expires_at) < new Date();

  const handleRefreshPages = async () => {
    if (!integration?.id) return;
    setRefreshingPages(true);
    try {
      await refreshPages(integration.id);
    } finally {
      setRefreshingPages(false);
    }
  };

  // Auto-fetch pages when integration becomes available and pages are empty
  useEffect(() => {
    if (integration?.id && isConnected && pages.length === 0 && !refreshingPages) {
      handleRefreshPages();
    }
  }, [integration?.id, isConnected]);

  if (loading) {
    return (
      <div className="space-y-6">
        <div>
          <h2 className="text-xl font-semibold">Integração Facebook Ads</h2>
          <p className="text-muted-foreground">
            Gerencie sua conexão com o Facebook Ads
          </p>
        </div>
        <Card>
          <CardContent className="p-6">
            <p className="text-muted-foreground">Carregando informações...</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-xl font-semibold">Integração Facebook Ads</h2>
        <p className="text-muted-foreground">
          Gerencie sua conexão com o Facebook Ads e visualize informações das contas
        </p>
      </div>

      {/* Card de Conexão */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Facebook className="h-5 w-5 text-blue-600" />
            Status da Conexão
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="space-y-1">
              <p className="text-sm text-muted-foreground">
                {isConnected 
                  ? "Conectado ao Facebook Ads com sucesso" 
                  : "Conecte sua conta do Facebook Ads para importar campanhas e métricas"
                }
              </p>
              {isConnected && (
                <div className="flex items-center gap-2">
                  <CheckCircle className="h-4 w-4 text-green-600" />
                  <span className="text-sm text-green-600">
                    Conectado - {adAccounts.length} conta(s) de anúncios
                  </span>
                  {isExpired && (
                    <Badge variant="destructive" className="text-xs">
                      Token Expirado
                    </Badge>
                  )}
                </div>
              )}
            </div>

            <div className="flex items-center gap-2">
              {isConnected && (
                <Button
                  variant="outline"
                  onClick={handleCheckScopes}
                  disabled={loading || checkingScopes}
                  className="flex items-center gap-2"
                >
                  <Shield className={`h-4 w-4 ${checkingScopes ? 'animate-pulse' : ''}`} />
                  Verificar Permissões
                </Button>
              )}

              {isConnected ? (
                <Button
                  variant="outline"
                  onClick={disconnectFacebook}
                  disabled={loading}
                  className="flex items-center gap-2"
                >
                  <Unlink className="h-4 w-4" />
                  Desconectar
                </Button>
              ) : (
                <Button
                  onClick={connectFacebook}
                  disabled={loading || !activeCompany}
                  className="flex items-center gap-2"
                >
                  <Facebook className="h-4 w-4" />
                  Conectar ao Facebook Ads
                </Button>
              )}
            </div>
          </div>

          {isExpired && (
            <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-md">
              <p className="text-sm text-yellow-800">
                Seu token do Facebook expirou. Clique em "Conectar ao Facebook Ads" para renovar.
              </p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Informações Detalhadas - só mostra se conectado */}
      {isConnected && (
        <>
          {/* Card de Informações do Token */}
          <Card>
            <CardHeader>
