import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { toast } from "@/hooks/use-toast";

interface StorageImage {
  name: string;
  url: string;
  createdAt: Date;
  size: number;
}

interface RecentCreationsGalleryProps {
  onSelectImage: (imageUrl: string) => void;
}

export function RecentCreationsGallery({ onSelectImage }: RecentCreationsGalleryProps) {
  const { activeCompany } = useCompany();
  const [images, setImages] = useState<StorageImage[]>([]);
  const [loading, setLoading] = useState(true);
  const [deletingImage, setDeletingImage] = useState<string | null>(null);

  const fetchImages = async () => {
    if (!activeCompany?.company_id) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);

      // Buscar imagens do bucket ai-generated-images na pasta standalone da empresa
      const { data: standaloneFiles, error: standaloneError } = await supabase.storage
        .from('ai-generated-images')
        .list(`visual-creatives/standalone/${activeCompany.company_id}`, {
          limit: 50,
          sortBy: { column: 'created_at', order: 'desc' },
        });

      if (standaloneError) {
        console.error('Error fetching standalone images:', standaloneError);
      }

      // Buscar também imagens diretas na pasta visual-creatives/{companyId}
      const { data: directFiles, error: directError } = await supabase.storage
        .from('ai-generated-images')
        .list(`visual-creatives/${activeCompany.company_id}`, {
          limit: 50,
          sortBy: { column: 'created_at', order: 'desc' },
        });

      if (directError) {
        console.error('Error fetching direct images:', directError);
      }

      const allFiles: StorageImage[] = [];

      // Processar arquivos standalone
      if (standaloneFiles) {
        for (const file of standaloneFiles) {
          if (file.name && file.metadata) {
            const { data: urlData } = supabase.storage
              .from('ai-generated-images')
              .getPublicUrl(`visual-creatives/standalone/${activeCompany.company_id}/${file.name}`);

            allFiles.push({
              name: file.name,
              url: urlData.publicUrl,
              createdAt: new Date(file.created_at || Date.now()),
              size: file.metadata?.size || 0,
            });
          }
        }
      }

      // Processar arquivos diretos
      if (directFiles) {
        for (const file of directFiles) {
          if (file.name && file.metadata) {
            const { data: urlData } = supabase.storage
              .from('ai-generated-images')
              .getPublicUrl(`visual-creatives/${activeCompany.company_id}/${file.name}`);

            allFiles.push({
              name: file.name,
              url: urlData.publicUrl,
              createdAt: new Date(file.created_at || Date.now()),
              size: file.metadata?.size || 0,
            });
          }
        }
      }

      // Ordenar por data de criação (mais recente primeiro)
      allFiles.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());

      setImages(allFiles.slice(0, 30)); // Limitar a 30 imagens
    } catch (error) {
      console.error('Error loading recent images:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchImages();
  }, [activeCompany?.company_id]);

  const handleDeleteImage = async (image: StorageImage) => {
    if (!activeCompany?.company_id) return;

    try {
      setDeletingImage(image.name);

      // Tentar deletar de ambas as pastas possíveis
      const paths = [
        `visual-creatives/standalone/${activeCompany.company_id}/${image.name}`,
        `visual-creatives/${activeCompany.company_id}/${image.name}`,
      ];

      for (const path of paths) {
        const { error } = await supabase.storage
          .from('ai-generated-images')
          .remove([path]);

        if (!error) {
          break;
        }
      }

      toast({
        title: "Imagem removida",
        description: "A imagem foi removida com sucesso.",
      });

      // Atualizar lista
      setImages((prev) => prev.filter((img) => img.name !== image.name));
    } catch (error) {
      console.error('Error deleting image:', error);
      toast({
        title: "Erro ao remover",
        description: "Não foi possível remover a imagem.",
        variant: "destructive",
      });
    } finally {
      setDeletingImage(null);
    }
  };

  const formatFileSize = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  if (!activeCompany) {
    return null;
  }

  if (loading) {
    return (
      <div className="mt-8">
        <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
          <ImageIcon className="w-5 h-5" />
          Criações Recentes
        </h2>
        <div className="flex items-center justify-center py-12 text-muted-foreground">
          <Loader2 className="w-6 h-6 animate-spin mr-2" />
          Carregando imagens...
        </div>
      </div>
    );
  }

  if (images.length === 0) {
    return (
      <div className="mt-8">
        <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
          <ImageIcon className="w-5 h-5" />
          Criações Recentes
        </h2>
        <div className="flex flex-col items-center justify-center py-12 text-muted-foreground border-2 border-dashed rounded-xl">
          <ImageIcon className="w-12 h-12 mb-3 opacity-50" />
          <p>Nenhuma criação encontrada</p>
          <p className="text-sm">Suas imagens geradas aparecerão aqui</p>
        </div>
      </div>
    );
  }

  return (
    <div className="mt-8">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-lg font-semibold flex items-center gap-2">
          <ImageIcon className="w-5 h-5" />
          Criações Recentes
        </h2>
        <span className="text-sm text-muted-foreground">
          {images.length} {images.length === 1 ? 'imagem' : 'imagens'}
        </span>
      </div>

      <ScrollArea className="w-full whitespace-nowrap rounded-xl border bg-muted/20 p-4">
        <div className="flex gap-4">
          {images.map((image) => (
            <div
              key={image.name}
              className="group relative flex-shrink-0 w-48 rounded-lg overflow-hidden border bg-background shadow-sm hover:shadow-md transition-shadow"
            >
              {/* Thumbnail */}
              <div
                className="aspect-square w-full bg-muted cursor-pointer overflow-hidden"
                onClick={() => onSelectImage(image.url)}
              >
                <img
                  src={image.url}
                  alt={image.name}
                  className="w-full h-full object-cover transition-transform group-hover:scale-105"
                  loading="lazy"
                />
              </div>

              {/* Overlay com ações */}
              <div className="absolute inset-0 bg-black/0 group-hover:bg-black/40 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100 pointer-events-none group-hover:pointer-events-auto">
                <div className="flex gap-2">
                  <Button
                    size="sm"
                    variant="secondary"
                    onClick={() => onSelectImage(image.url)}
                    className="h-8"
                  >
                    <ExternalLink className="w-4 h-4 mr-1" />
                    Abrir
                  </Button>

                  <AlertDialog>
                    <AlertDialogTrigger asChild>
                      <Button
                        size="sm"
                        variant="destructive"
                        className="h-8 w-8 p-0"
                        disabled={deletingImage === image.name}
                      >
                        {deletingImage === image.name ? (
                          <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                          <Trash2 className="w-4 h-4" />
                        )}
                      </Button>
                    </AlertDialogTrigger>
                    <AlertDialogContent>
                      <AlertDialogHeader>
                        <AlertDialogTitle>Remover imagem?</AlertDialogTitle>
                        <AlertDialogDescription>
                          Esta ação não pode ser desfeita. A imagem será permanentemente removida.
                        </AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel>Cancelar</AlertDialogCancel>
                        <AlertDialogAction
                          onClick={() => handleDeleteImage(image)}
                          className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                          Remover
                        </AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </div>
              </div>

              {/* Info */}
              <div className="p-2 border-t">
                <p className="text-xs text-muted-foreground truncate">
                  {format(image.createdAt, "dd MMM, HH:mm", { locale: ptBR })}
                </p>
                <p className="text-xs text-muted-foreground/70">
                  {formatFileSize(image.size)}
                </p>
              </div>
            </div>
          ))}
        </div>
        <ScrollBar orientation="horizontal" />
      </ScrollArea>
    </div>
  );
}

import { useState, useCallback, useEffect, useRef } from 'react';

export interface CanvasElement {
  id: string;
  type: 'text' | 'shape' | 'image';
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: number;
  content: string;
  styles: {
    fontSize?: number;
    fontWeight?: string;
    fontFamily?: string;
    color?: string;
    backgroundColor?: string;
    borderColor?: string;
    borderWidth?: number;
    borderRadius?: number;
    opacity?: number;
    textAlign?: 'left' | 'center' | 'right';
    shapeType?: 'rectangle' | 'circle' | 'line' | 'arrow';
    // Fade/Gradient properties
    fadeEnabled?: boolean;
    fadeDirection?: 'to-right' | 'to-left' | 'to-bottom' | 'to-top' | 'to-bottom-right' | 'to-bottom-left' | 'to-top-right' | 'to-top-left';
    fadeEndColor?: string; // The color to fade to (usually transparent)
  };
}

export interface AIMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  imageUrl?: string;
  timestamp: Date;
}

export interface ImageEditorState {
  images: string[];
  currentImageIndex: number;
  elements: CanvasElement[][];
  selectedElementId: string | null;
  zoom: number;
  history: CanvasElement[][][];
  historyIndex: number;
  aiChatMessages: AIMessage[];
  isProcessingAI: boolean;
  orientation: string;
}

interface UseImageEditorProps {
  initialImages: string[];
  initialOrientation?: string;
}

export function useImageEditor({ initialImages, initialOrientation = 'post' }: UseImageEditorProps) {
  // Ensure initialImages is always a valid array
  const safeInitialImages = Array.isArray(initialImages) && initialImages.length > 0 
    ? initialImages 
    : [];

  // Use a ref to track the original images that initialized the session
  // This prevents resets when state.images changes due to AI edits
  const sessionInitialImagesRef = useRef<string[]>(safeInitialImages);
  const isInitializedRef = useRef(false);

  const [state, setState] = useState<ImageEditorState>(() => ({
    images: safeInitialImages,
    currentImageIndex: 0,
    elements: safeInitialImages.map(() => []),
    selectedElementId: null,
    zoom: 1,
    history: [safeInitialImages.map(() => [])],
    historyIndex: 0,
    aiChatMessages: [],
    isProcessingAI: false,
    orientation: initialOrientation,
  }));

  // Only reset state when the modal opens with genuinely NEW images
  // Compare against the session's initial images, not current state
  useEffect(() => {
    // Ensure we're working with valid arrays
    const safeImages = Array.isArray(initialImages) ? initialImages : [];

    const initialImagesKey = JSON.stringify(safeImages);
    const sessionKey = JSON.stringify(sessionInitialImagesRef.current);

    // Only reset if:
    // 1. We have images to work with
    // 2. The initialImages are different from what started this session
    // This prevents resets when switching tabs or when state.images changes from AI edits
    if (safeImages.length > 0 && initialImagesKey !== sessionKey) {
      sessionInitialImagesRef.current = safeImages;
      isInitializedRef.current = true;
      setState({
        images: safeImages,
        currentImageIndex: 0,
        elements: safeImages.map(() => []),
        selectedElementId: null,
        zoom: 1,
        history: [safeImages.map(() => [])],
        historyIndex: 0,
        aiChatMessages: [],
        isProcessingAI: false,
        orientation: initialOrientation,
      });
    } else if (!isInitializedRef.current && safeImages.length > 0) {
      // First initialization
      isInitializedRef.current = true;
    }
  }, [initialImages]);

  const getCurrentElements = useCallback(() => {
    return state.elements[state.currentImageIndex] || [];
  }, [state.elements, state.currentImageIndex]);

  const saveToHistory = useCallback((newElements: CanvasElement[][]) => {
    setState(prev => {
      const newHistory = prev.history.slice(0, prev.historyIndex + 1);
      newHistory.push(JSON.parse(JSON.stringify(newElements)));
      return {
        ...prev,
        elements: newElements,
        history: newHistory,
        historyIndex: newHistory.length - 1,
      };
    });
  }, []);

  const addElement = useCallback((type: CanvasElement['type'], config?: Partial<CanvasElement>) => {
    const id = `element-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    const defaultStyles: CanvasElement['styles'] = {
      fontSize: type === 'text' ? 24 : undefined,
      fontWeight: 'normal',
      fontFamily: 'Inter',
      color: '#FFFFFF',
      backgroundColor: type === 'shape' ? '#8B5CF6' : 'transparent',
      borderColor: '#8B5CF6',
      borderWidth: type === 'shape' ? 2 : 0,
      borderRadius: 4,
      opacity: 1,
      textAlign: 'center',
      shapeType: type === 'shape' ? 'rectangle' : undefined,
    };

    const newElement: CanvasElement = {
      id,
      type,
      x: 100,
      y: 100,
      width: type === 'text' ? 200 : type === 'image' ? 150 : 120,
      height: type === 'text' ? 50 : type === 'image' ? 150 : 80,
      rotation: 0,
      content: type === 'text' ? 'Novo texto' : '',
      styles: { ...defaultStyles, ...config?.styles },
      ...config,
    };

    setState(prev => {
      const newElements = [...prev.elements];
      newElements[prev.currentImageIndex] = [...(newElements[prev.currentImageIndex] || []), newElement];
      return {
        ...prev,
        elements: newElements,
        selectedElementId: id,
      };
    });

    saveToHistory(state.elements.map((els, i) => 
      i === state.currentImageIndex ? [...els, newElement] : els
    ));

    return id;
  }, [state.elements, state.currentImageIndex, saveToHistory]);

  const updateElement = useCallback((id: string, updates: Partial<CanvasElement>) => {
    setState(prev => {
      const newElements = prev.elements.map((slideElements, slideIndex) => {
        if (slideIndex !== prev.currentImageIndex) return slideElements;
        return slideElements.map(el => 
          el.id === id ? { ...el, ...updates, styles: { ...el.styles, ...updates.styles } } : el
        );
      });
      return { ...prev, elements: newElements };
    });
  }, []);

  const removeElement = useCallback((id: string) => {
    setState(prev => {
      const newElements = prev.elements.map((slideElements, slideIndex) => {
        if (slideIndex !== prev.currentImageIndex) return slideElements;
        return slideElements.filter(el => el.id !== id);
      });
      saveToHistory(newElements);
      return { 
        ...prev, 
        elements: newElements,
        selectedElementId: prev.selectedElementId === id ? null : prev.selectedElementId,
      };
    });
  }, [saveToHistory]);

  const selectElement = useCallback((id: string | null) => {
    setState(prev => ({ ...prev, selectedElementId: id }));
  }, []);

  const undo = useCallback(() => {
    setState(prev => {
      if (prev.historyIndex <= 0) return prev;
      const newIndex = prev.historyIndex - 1;
      return {
        ...prev,
        elements: JSON.parse(JSON.stringify(prev.history[newIndex])),
        historyIndex: newIndex,
        selectedElementId: null,
      };
    });
  }, []);

  const redo = useCallback(() => {
    setState(prev => {
      if (prev.historyIndex >= prev.history.length - 1) return prev;
      const newIndex = prev.historyIndex + 1;
      return {
        ...prev,
        elements: JSON.parse(JSON.stringify(prev.history[newIndex])),
        historyIndex: newIndex,
        selectedElementId: null,
      };
    });
  }, []);

  const setZoom = useCallback((zoom: number) => {
    setState(prev => ({ ...prev, zoom: Math.max(0.25, Math.min(2, zoom)) }));
  }, []);

  const setCurrentImage = useCallback((index: number) => {
    setState(prev => ({ 
      ...prev, 
      currentImageIndex: Math.max(0, Math.min(prev.images.length - 1, index)),
      selectedElementId: null,
    }));
  }, []);

  const updateImage = useCallback((index: number, newUrl: string) => {
    setState(prev => {
      const newImages = [...prev.images];
      newImages[index] = newUrl;
      return { ...prev, images: newImages };
    });
  }, []);

  const addImage = useCallback((url: string) => {
    setState(prev => {
      const newImages = [...prev.images, url];
      const newElements = [...prev.elements, []];
      return {
        ...prev,
        images: newImages,
        elements: newElements,
        currentImageIndex: newImages.length - 1,
        selectedElementId: null,
      };
    });
  }, []);

  const removeImage = useCallback((index: number) => {
    setState(prev => {
      if (prev.images.length <= 1) return prev;
      const newImages = prev.images.filter((_, i) => i !== index);
      const newElements = prev.elements.filter((_, i) => i !== index);
      const newIndex = Math.min(prev.currentImageIndex, newImages.length - 1);
      return {
        ...prev,
        images: newImages,
        elements: newElements,
        currentImageIndex: newIndex,
        selectedElementId: null,
      };
    });
  }, []);

  const addAIMessage = useCallback((message: Omit<AIMessage, 'id' | 'timestamp'>) => {
    const newMessage: AIMessage = {
      ...message,
      id: `msg-${Date.now()}`,
      timestamp: new Date(),
    };
    setState(prev => ({
      ...prev,
      aiChatMessages: [...prev.aiChatMessages, newMessage],
    }));
    return newMessage.id;
  }, []);

  const setProcessingAI = useCallback((processing: boolean) => {
    setState(prev => ({ ...prev, isProcessingAI: processing }));
  }, []);

  const setOrientation = useCallback((orientation: string) => {
    setState(prev => ({ ...prev, orientation }));
  }, []);

  const canUndo = state.historyIndex > 0;
  const canRedo = state.historyIndex < state.history.length - 1;

  return {
    state,
    getCurrentElements,
    addElement,
    updateElement,
    removeElement,
    selectElement,
    undo,
    redo,
    canUndo,
    canRedo,
    setZoom,
    setCurrentImage,
    updateImage,
    addImage,
    removeImage,
    addAIMessage,
    setProcessingAI,
    setOrientation,
  };
}

