export type TaskDialogMode = 'kanban' | 'roteiro';

interface TaskDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  task?: unknown;
  onSave: (taskData: unknown) => void;
  defaultClientId?: string;
  defaultBoardUserId?: string | null;
