      // Tipo
      if (formData.tipo !== (task.task_type || 'Tarefa')) {
        await logAutomatic(task.id, `Alterou o tipo de ${task.task_type || 'Tarefa'} para ${formData.tipo}`, 'task_type', task.task_type || 'Tarefa', formData.tipo);
