                    <p className="text-sm text-muted-foreground mb-4">
                      Registro de alterações e anotações desta {isRoteiro ? 'atividade' : 'tarefa'}.
                    </p>
                    <TaskHistoryTab taskId={task?.id || null} />
                  </div>
                )}
              </div>
            </ScrollArea>

            {/* Footer */}
            <div className="px-6 py-4 border-t border-border flex justify-end">
              <Button onClick={handleSave} disabled={!formData.title.trim() || !!loading} className="gap-2">
                <Save className="w-4 h-4" />
                {loading ? 'Salvando...' : (task ? 'Atualizar' : 'Criar')} {isRoteiro ? 'Atividade' : 'Tarefa'}
              </Button>
            </div>
          </div>

          {/* Output Panel - shown for non-creative tasks when editing */}
          {!isRoteiro && formData.tipo !== 'Criativo' && task?.id && (
            <>
              {/* Draggable divider */}
              <div
                onMouseDown={handleDividerMouseDown}
                className="w-1 shrink-0 bg-border hover:bg-primary/40 cursor-col-resize transition-colors duration-150 relative group"
                title="Arraste para redimensionar"
              >
                <div className="absolute inset-y-0 -left-1 -right-1 group-hover:bg-primary/10" />
              </div>
              <div className="shrink-0 overflow-hidden" style={{ width: outputWidth }}>
                <TaskOutputPanel taskId={task.id} companyId={companyId} clientId={formData.related_client_id} expanded={outputExpanded} onToggleExpand={() => setOutputExpanded(prev => !prev)} />
              </div>
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>

    {/* Stacked dialog for viewing parent task */}
    {viewingParentTask && (
      <TaskDialog
        open={!!viewingParentTask}
        onOpenChange={(open) => {
          if (!open) setViewingParentTask(null);
        }}
        task={viewingParentTask}
        onSave={async (taskData) => {
          const { id, ...updates } = taskData;
          await supabase.from('tasks').update(updates).eq('id', viewingParentTask.id);
          setViewingParentTask(null);
        }}
      />
    )}

    <ImportChecklistTemplateModal
      open={importChecklistOpen}
      onOpenChange={setImportChecklistOpen}
      onImport={(items) => {
        setFormData(prev => ({
          ...prev,
          checklist: [...prev.checklist, ...items],
        }));
      }}
    />

    {/* Delete Confirmation Dialog */}
    <Dialog open={deleteConfirmOpen} onOpenChange={setDeleteConfirmOpen}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Excluir Tarefa</DialogTitle>
          <DialogDescription>
            Tem certeza que deseja excluir a tarefa <strong>{formData.title}</strong>? Esta ação não pode ser desfeita.
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button variant="outline" onClick={() => setDeleteConfirmOpen(false)}>
            Cancelar
          </Button>
          <Button
            variant="destructive"
            disabled={deleting}
            onClick={async () => {
              if (!task?.id) return;
              setDeleting(true);
              try {
                await supabase.from('tasks').delete().eq('id', task.id);
                setDeleteConfirmOpen(false);
                onOpenChange(false);
              } catch (err) {
                console.error('Error deleting task:', err);
              } finally {
                setDeleting(false);
              }
            }}
          >
            {deleting ? 'Excluindo...' : 'Excluir'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
    </>
  );
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Separator } from "@/components/ui/separator";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Search, X, Crown, Users, Eye, Loader2, Plus, Filter, ShieldCheck } from "lucide-react";
import { useTaskMembers, TaskMemberRole } from "@/hooks/useTaskMembers";
import { useEmployees } from "@/hooks/useEmployees";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";

interface TaskTeamTabProps {
  taskId: string | undefined;
  companyId: string | undefined;
  defaultTeamId?: string;
  fallbackResponsible?: {
    name: string;
    avatar: string;
    employeeId: string;
  };
  autoAssignAuthorizerId?: string | null;
}

const ROLE_CONFIG: Record<TaskMemberRole, { label: string; icon: React.ElementType; color: string; description: string }> = {
  responsible: {
    label: 'Responsável',
    icon: Crown,
    color: 'text-amber-500',
    description: 'Responsável principal pela execução',
  },
  authorizer: {
    label: 'Autorizador',
    icon: ShieldCheck,
    color: 'text-emerald-500',
    description: 'Deve autorizar antes da execução',
  },
  contributor: {
    label: 'Contribuinte',
    icon: Users,
    color: 'text-blue-500',
    description: 'Colabora ativamente na execução',
  },
  observer: {
    label: 'Observador',
    icon: Eye,
    color: 'text-muted-foreground',
    description: 'Acompanha o progresso',
  },
};

function MemberCard({ member, onRemove }: {
  member: { id: string; employee_name?: string; employee_avatar?: string; role: TaskMemberRole };
  onRemove: (id: string) => void;
}) {
  const config = ROLE_CONFIG[member.role];
  const Icon = config.icon;

  return (
    <div className="flex items-center gap-2.5 p-2 rounded-lg border border-border bg-card">
      <Avatar className="h-8 w-8">
        {member.employee_avatar && <AvatarImage src={member.employee_avatar} />}
        <AvatarFallback className="bg-muted text-muted-foreground text-xs">
          {(member.employee_name || '?').charAt(0).toUpperCase()}
        </AvatarFallback>
      </Avatar>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium text-foreground truncate">{member.employee_name}</p>
        <div className="flex items-center gap-1 text-[11px]">
          <Icon className={`w-3 h-3 ${config.color}`} />
          <span className={config.color}>{config.label}</span>
        </div>
      </div>
      <Button
        variant="ghost"
        size="icon"
        className="h-6 w-6 text-destructive hover:text-destructive shrink-0"
        onClick={() => onRemove(member.id)}
        title="Remover membro"
      >
        <X className="w-3 h-3" />
      </Button>
    </div>
  );
}

function RoleDropZone({
  role,
  members,
  onRemove,
  onDrop,
}: {
  role: TaskMemberRole;
  members: Array<{ id: string; employee_name?: string; employee_avatar?: string; role: TaskMemberRole }>;
  onRemove: (id: string) => void;
  onDrop: (employeeId: string, role: TaskMemberRole) => void;
}) {
  const [isDragOver, setIsDragOver] = useState(false);
  const config = ROLE_CONFIG[role];
  const Icon = config.icon;

  return (
    <div
      onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
      onDragLeave={() => setIsDragOver(false)}
      onDrop={(e) => {
        e.preventDefault();
        setIsDragOver(false);
        const eid = e.dataTransfer.getData('employeeId');
        if (eid) onDrop(eid, role);
      }}
      className={`rounded-lg border-2 border-dashed p-2.5 transition-colors ${
        isDragOver ? 'border-primary bg-primary/5' : 'border-border bg-muted/10'
      }`}
    >
      <div className="flex items-center gap-2 mb-1.5">
        <Icon className={`w-3.5 h-3.5 ${config.color}`} />
        <span className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wide">
          {config.label} ({members.length})
        </span>
      </div>
      {members.length > 0 ? (
        <div className="space-y-1.5">
          {members.map(m => (
            <MemberCard key={m.id} member={m} onRemove={onRemove} />
          ))}
        </div>
      ) : (
        <p className="text-[11px] text-muted-foreground text-center py-1.5">
          {isDragOver ? 'Solte aqui' : 'Arraste ou clique para adicionar'}
        </p>
      )}
    </div>
  );
}

function EmployeeChip({
  employee,
  onAdd,
  isAdding,
}: {
  employee: { id: string; name: string; avatar?: string; profile_avatar_url?: string };
  onAdd: (employeeId: string, role: TaskMemberRole) => void;
  isAdding: boolean;
}) {
  const [showRoles, setShowRoles] = useState(false);
  const avatarSrc = employee.avatar || employee.profile_avatar_url || '';

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('employeeId', employee.id);
  };

  return (
    <TooltipProvider delayDuration={200}>
      <div className="relative">
        <Tooltip>
          <TooltipTrigger asChild>
            <div
              draggable
              onDragStart={handleDragStart}
              onClick={() => setShowRoles(!showRoles)}
              className="flex flex-col items-center gap-0.5 cursor-grab active:cursor-grabbing group"
            >
              <div className="relative">
                <Avatar className="h-11 w-11 border-2 border-transparent group-hover:border-primary/40 transition-colors">
                  {avatarSrc && <AvatarImage src={avatarSrc} />}
                  <AvatarFallback className="bg-muted text-muted-foreground text-[11px]">
                    {employee.name.charAt(0).toUpperCase()}
                  </AvatarFallback>
                </Avatar>
                <div className="absolute -bottom-0.5 -right-0.5 h-3.5 w-3.5 rounded-full bg-primary text-primary-foreground flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                  <Plus className="w-2 h-2" />
                </div>
              </div>
              <span className="text-[10px] text-muted-foreground truncate w-full text-center leading-tight">
                {employee.name.split(' ')[0]}
              </span>
            </div>
          </TooltipTrigger>
          <TooltipContent side="top" className="text-xs">{employee.name}</TooltipContent>
        </Tooltip>

        {showRoles && (
          <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-full bg-popover border border-border rounded-lg shadow-lg p-1.5 z-20 min-w-[120px]">
            {(Object.entries(ROLE_CONFIG) as [TaskMemberRole, typeof ROLE_CONFIG.responsible][]).map(([role, cfg]) => {
              const RoleIcon = cfg.icon;
              return (
                <button
                  key={role}
                  onClick={(e) => {
                    e.stopPropagation();
                    onAdd(employee.id, role);
                    setShowRoles(false);
                  }}
                  disabled={isAdding}
                  className={`flex items-center gap-1.5 text-[11px] font-medium px-2 py-1.5 rounded-md hover:bg-muted transition-colors w-full ${cfg.color}`}
                >
                  <RoleIcon className="w-3 h-3" />
                  {cfg.label}
                </button>
              );
            })}
          </div>
        )}
      </div>
    </TooltipProvider>
  );
}

export function TaskTeamTab({ taskId, companyId, fallbackResponsible, defaultTeamId, autoAssignAuthorizerId }: TaskTeamTabProps) {
  const { members, responsible, authorizers, contributors, observers, isLoading, addMember, isAdding, updateRole, removeMember } = useTaskMembers(taskId, companyId);
  const { employees } = useEmployees();
  const [search, setSearch] = useState('');
  const [selectedTeamId, setSelectedTeamId] = useState<string>(defaultTeamId || 'all');
  const lastAutoAssignedRef = useRef<string | null>(null);

  // Auto-assign authorizer when squad changes
  useEffect(() => {
    if (
      autoAssignAuthorizerId &&
      taskId &&
      !isLoading &&
      lastAutoAssignedRef.current !== autoAssignAuthorizerId
    ) {
      const alreadyAuthorizer = authorizers.some(a => a.employee_id === autoAssignAuthorizerId);
      if (!alreadyAuthorizer) {
        addMember({ employeeId: autoAssignAuthorizerId, role: 'authorizer' });
        lastAutoAssignedRef.current = autoAssignAuthorizerId;
      }
    }
  }, [autoAssignAuthorizerId, taskId, isLoading, authorizers]);

  const assignedEmployeeIds = new Set(members.map(m => m.employee_id));

  const teams = useMemo(() => {
    if (!employees) return [];
    const teamMap = new Map<string, { id: string; name: string; color: string }>();
    employees.forEach(e => {
      if (e.team) teamMap.set(e.team.id, e.team);
    });
    return Array.from(teamMap.values()).sort((a, b) => a.name.localeCompare(b.name));
  }, [employees]);

  const availableEmployees = useMemo(() => {
    return (employees || [])
      .filter(e => !assignedEmployeeIds.has(e.id))
      .filter(e => e.name.toLowerCase().includes(search.toLowerCase()))
      .filter(e => selectedTeamId === 'all' || e.team_id === selectedTeamId)
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [employees, assignedEmployeeIds, search, selectedTeamId]);

  const handleAddToRole = (employeeId: string, role: TaskMemberRole) => {
    addMember({ employeeId, role });
  };

  if (!taskId) {
    return (
      <div className="space-y-5">
        <div>
          <h3 className="text-base font-semibold text-foreground mb-1">Equipe</h3>
          <p className="text-sm text-muted-foreground">
            Salve a tarefa primeiro para gerenciar os membros da equipe.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-3 h-full">
      {/* Header */}
      <div>
        <h3 className="text-base font-semibold text-foreground mb-0.5">Equipe</h3>
        <p className="text-[11px] text-muted-foreground">
          Arraste colaboradores para as áreas ou clique para selecionar o papel.
        </p>
      </div>

      {/* Role zones */}
      <div className="space-y-2">
        {/* Responsible */}
        <div
          className="rounded-lg border-2 border-dashed border-amber-500/30 p-2.5 bg-amber-500/5"
          onDragOver={(e) => e.preventDefault()}
          onDrop={(e) => {
            e.preventDefault();
            const eid = e.dataTransfer.getData('employeeId');
            if (eid) handleAddToRole(eid, 'responsible');
          }}
        >
          <div className="flex items-center gap-2 mb-1.5">
            <Crown className="w-3.5 h-3.5 text-amber-500" />
            <span className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wide">
              Responsável
            </span>
          </div>
          {responsible ? (
            <MemberCard member={responsible} onRemove={removeMember} />
          ) : fallbackResponsible?.name ? (
            <div className="flex items-center gap-2.5 p-2 rounded-lg border border-primary/30 bg-card">
              <Avatar className="h-8 w-8">
                {fallbackResponsible.avatar && <AvatarImage src={fallbackResponsible.avatar} />}
                <AvatarFallback className="bg-primary/10 text-primary text-xs">
                  {fallbackResponsible.name.charAt(0).toUpperCase()}
                </AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-foreground truncate">{fallbackResponsible.name}</p>
                <div className="flex items-center gap-1 text-[11px]">
                  <Crown className="w-3 h-3 text-amber-500" />
                  <span className="text-amber-500">Responsável</span>
                  <span className="text-muted-foreground ml-1">(aba Principal)</span>
                </div>
              </div>
            </div>
          ) : (
            <p className="text-[11px] text-muted-foreground text-center py-1.5">
              Arraste um colaborador aqui
            </p>
          )}
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center gap-2 py-3 text-sm text-muted-foreground">
            <Loader2 className="w-4 h-4 animate-spin" /> Carregando...
          </div>
        ) : (
          <>
            <RoleDropZone role="authorizer" members={authorizers} onRemove={removeMember} onDrop={handleAddToRole} />
            <RoleDropZone role="contributor" members={contributors} onRemove={removeMember} onDrop={handleAddToRole} />
            <RoleDropZone role="observer" members={observers} onRemove={removeMember} onDrop={handleAddToRole} />
          </>
        )}
      </div>

      <Separator />

      {/* Available employees */}
      <div className="flex-1 min-h-0">
        {/* Team filter above the list */}
        <div className="flex items-center gap-2 mb-2">
          <Filter className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
          <Select value={selectedTeamId} onValueChange={setSelectedTeamId}>
            <SelectTrigger className="h-7 text-xs flex-1">
              <SelectValue placeholder="Filtrar por equipe" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todas as equipes</SelectItem>
              {teams.map(t => (
                <SelectItem key={t.id} value={t.id}>
                  <div className="flex items-center gap-2">
                    <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: t.color || 'hsl(var(--muted))' }} />
                    {t.name}
                  </div>
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Search */}
        <div className="relative mb-2">
          <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-muted-foreground" />
          <Input
            placeholder="Buscar..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="h-7 pl-7 text-xs"
          />
        </div>

        {/* Compact avatar grid */}
        <div className="grid grid-cols-8 gap-1 max-h-[140px] overflow-y-auto pr-1">
          {availableEmployees.map(emp => (
            <EmployeeChip
              key={emp.id}
              employee={emp}
              onAdd={handleAddToRole}
              isAdding={isAdding}
            />
          ))}
          {availableEmployees.length === 0 && (
            <div className="col-span-8 text-[11px] text-muted-foreground text-center py-3">
              {search ? 'Nenhum encontrado' : 'Todos já adicionados'}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { TrendingUp, RefreshCw, ExternalLink, Flame, ArrowUp } from "lucide-react";
import { useGoogleTrends, TrendingTopic } from "@/hooks/useGoogleTrends";

interface TrendingTopicsCardProps {
  onSelectTopic?: (topic: string) => void;
  className?: string;
}

export function TrendingTopicsCard({ onSelectTopic, className }: TrendingTopicsCardProps) {
  const { getDailyTrends, isLoading, error } = useGoogleTrends();
  const [trends, setTrends] = useState<TrendingTopic[]>([]);
  const [hasLoaded, setHasLoaded] = useState(false);

  const loadTrends = async () => {
    const data = await getDailyTrends("BR");
    setTrends(data);
    setHasLoaded(true);
  };

  useEffect(() => {
    loadTrends();
  }, []);

  const formatTraffic = (traffic: string) => {
    return traffic.replace("+", "").trim();
  };

  if (!hasLoaded && isLoading) {
    return (
      <Card className={className}>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-primary" />
            Tendências do Momento
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          {[1, 2, 3, 4, 5].map((i) => (
            <div key={i} className="flex items-center gap-3">
              <Skeleton className="w-10 h-10 rounded" />
              <div className="flex-1 space-y-1">
                <Skeleton className="h-4 w-3/4" />
                <Skeleton className="h-3 w-1/2" />
              </div>
            </div>
          ))}
        </CardContent>
      </Card>
    );
  }

  if (error && trends.length === 0) {
    return (
      <Card className={className}>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-primary" />
            Tendências do Momento
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-center py-6 text-muted-foreground">
            <p className="text-sm mb-3">Não foi possível carregar as tendências</p>
            <Button variant="outline" size="sm" onClick={loadTrends} disabled={isLoading}>
              <RefreshCw className={`w-4 h-4 mr-2 ${isLoading ? 'animate-spin' : ''}`} />
              Tentar novamente
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={className}>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-primary" />
            Tendências do Momento
          </CardTitle>
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={loadTrends} 
            disabled={isLoading}
            className="h-8 w-8 p-0"
          >
            <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
          </Button>
        </div>
        <p className="text-sm text-muted-foreground">Brasil • Google Trends</p>
      </CardHeader>
      <CardContent className="space-y-2">
        {trends.slice(0, 8).map((trend, index) => (
          <div
            key={trend.title}
            className="group flex items-start gap-3 p-2 rounded-lg hover:bg-muted/50 transition-colors cursor-pointer"
            onClick={() => onSelectTopic?.(trend.title)}
          >
            <div className="flex items-center justify-center w-6 h-6 rounded-full bg-primary/10 text-primary text-xs font-semibold shrink-0">
              {index + 1}
            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className="font-medium text-sm truncate">{trend.title}</span>
                {index < 3 && (
                  <Flame className="w-3.5 h-3.5 text-orange-500 shrink-0" />
                )}
              </div>

              <div className="flex items-center gap-2 mt-1">
                <Badge variant="secondary" className="text-xs px-1.5 py-0">
                  <ArrowUp className="w-3 h-3 mr-0.5" />
                  {formatTraffic(trend.traffic)} buscas
                </Badge>
              </div>

              {trend.relatedQueries.length > 0 && (
                <div className="flex flex-wrap gap-1 mt-1.5">
                  {trend.relatedQueries.slice(0, 3).map((query) => (
                    <span
                      key={query}
                      className="text-xs text-muted-foreground bg-muted px-1.5 py-0.5 rounded"
                    >
                      {query}
                    </span>
                  ))}
                </div>
              )}
            </div>

            {onSelectTopic && (
              <Button
                variant="ghost"
                size="sm"
                className="opacity-0 group-hover:opacity-100 transition-opacity h-7 px-2"
                onClick={(e) => {
                  e.stopPropagation();
                  onSelectTopic(trend.title);
                }}
              >
                Usar
              </Button>
            )}
          </div>
        ))}
      </CardContent>
    </Card>
  );
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  "inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

const Badge = React.forwardRef<HTMLDivElement, BadgeProps>(
