export function WhatsAppAIAssistant({
  isOpen,
  onClose,
  conversationId,
  companyId,
  instanceId,
  customerMessage,
  contactName,
  onUseResponse,
  conversationMessages = [],
  forceRealtimeAnalysis = false,
  isGroupConversation = false,
}: WhatsAppAIAssistantProps) {
  const { 
    messages, 
    isLoading: isLoadingHistory, 
    isLoadingMore,
    hasMore,
    loadMoreMessages,
    addMessage, 
    addAnalysisMessage, 
    clearMessages 
  } = useWhatsAppAIChatMessages(conversationId, companyId);
  const [input, setInput] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [realtimeAnalysisEnabled, setRealtimeAnalysisEnabled] = useState(forceRealtimeAnalysis);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const hasGeneratedSuggestion = useRef(false);
  const lastCustomerMessage = useRef<string | null>(null);
  const lastSavedAnalysisTimestamp = useRef<string | null>(null); // Track saved analysis to prevent duplicates

  // If force is enabled, always keep analysis on
  const isAnalysisActive = forceRealtimeAnalysis || realtimeAnalysisEnabled;

  const { analysis, isNewAnalysis, isAnalyzing, error: analysisError, triggerAnalysis, markAnalysisConsumed } = useWhatsAppRealtimeAnalysis({
    conversationId,
    companyId,
    instanceId,
    messages: conversationMessages,
    enabled: isAnalysisActive,
    isGroupConversation,
  });

  // Save new analysis as a message in the chat (only when it's freshly generated)
  // Use a ref to prevent duplicate saves
  useEffect(() => {
    if (analysis && isNewAnalysis && analysis.timestamp) {
      // Check if we already saved this exact analysis (by timestamp)
      if (lastSavedAnalysisTimestamp.current === analysis.timestamp) {
        return;
      }


      // Mark as saving immediately to prevent race conditions
      lastSavedAnalysisTimestamp.current = analysis.timestamp;

      // Save analysis as a chat message
      const analysisContent: AnalysisMessageContent = {
        temperature: analysis.temperature,
        interpretation: analysis.interpretation,
        suggestion: analysis.suggestion,
        departmentInsight: analysis.departmentInsight,
        alerts: analysis.alerts,
        score: analysis.score,
        issueContext: analysis.issueContext,
        readyMessage: analysis.readyMessage,
      };

      addAnalysisMessage(analysisContent)
        .then(() => {
          markAnalysisConsumed(); // Mark as consumed after saving
        })
        .catch((err) => {
          console.error("Error saving analysis message:", err);
          // Reset on error so we can retry
          lastSavedAnalysisTimestamp.current = null;
        });
    }
  }, [analysis, isNewAnalysis, addAnalysisMessage, markAnalysisConsumed]);

  // Scroll to bottom when messages change
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages]);

  // Auto-focus input when opened
  useEffect(() => {
    if (isOpen && inputRef.current) {
      setTimeout(() => inputRef.current?.focus(), 100);
    }
  }, [isOpen]);

  // Generate initial suggestion when a new customer message is selected
  useEffect(() => {
    if (
      isOpen &&
      customerMessage &&
      customerMessage !== lastCustomerMessage.current &&
      !isLoadingHistory
    ) {
      lastCustomerMessage.current = customerMessage;
      hasGeneratedSuggestion.current = true;
      generateSuggestion(customerMessage);
    }
  }, [isOpen, customerMessage, isLoadingHistory]);

  // Reset refs when closed
  useEffect(() => {
    if (!isOpen) {
      hasGeneratedSuggestion.current = false;
      lastCustomerMessage.current = null;
    }
  }, [isOpen]);
  const generateSuggestion = async (messageToRespond: string) => {
    setIsGenerating(true);

    const systemPrompt = `Você é um assistente de atendimento ao cliente via WhatsApp. 
O cliente "${contactName}" enviou a seguinte mensagem:

"${messageToRespond}"

Sugira uma resposta profissional, cordial e objetiva para essa mensagem.
Mantenha o tom conversacional adequado para WhatsApp (não muito formal, mas profissional).
Não use saudações como "Olá" no início, pois a conversa já está em andamento.
Responda diretamente ao que o cliente perguntou ou comentou.`;

    try {
      const response = await supabase.functions.invoke("whatsapp-ai-assistant", {
        body: {
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: "Gere uma sugestão de resposta para essa mensagem do cliente." }
          ],
        },
      });

      if (response.error) throw response.error;

      const content = response.data?.content || "Não foi possível gerar uma sugestão.";

      // Save both the context message and the assistant response
      await addMessage({
        role: "user",
        content: `[Contexto] Cliente perguntou: "${messageToRespond}"`,
      });
      await addMessage({
        role: "assistant",
        content,
      });
    } catch (error) {
      console.error("Error generating suggestion:", error);
      toast.error("Erro ao gerar sugestão");

      await addMessage({
        role: "assistant",
        content: "Desculpe, não consegui gerar uma sugestão no momento. Por favor, tente novamente.",
      });
    } finally {
      setIsGenerating(false);
    }
  };

  const handleSend = async () => {
    if (!input.trim() || isGenerating) return;

    const userContent = input.trim();
    setInput("");

    // Save user message
    await addMessage({ role: "user", content: userContent });

    setIsGenerating(true);

    try {
      // Build conversation history for context (last 15 messages, INCLUDING analysis summaries)
      const recentMessages = messages
        .slice(-15)
        .map((m) => {
          // For analysis messages, create a summary for context
          if (m.role === "analysis") {
            try {
              const analysisData = JSON.parse(m.content) as AnalysisMessageContent;
              return {
                role: "assistant" as const,
                content: `[Análise da conversa atual]
- Temperatura: ${analysisData.temperature === "positive" ? "Positiva" : analysisData.temperature === "negative" ? "Negativa" : "Neutra"} (Nota: ${analysisData.score}/10)
- Interpretação: ${analysisData.interpretation}
- Sugestão: ${analysisData.suggestion}
- Insight: ${analysisData.departmentInsight?.insight || "N/A"}
- Mensagem pronta sugerida: ${analysisData.readyMessage || "N/A"}`,
              };
            } catch {
              return null;
            }
          }
          return {
            role: m.role as "user" | "assistant",
            content: m.content,
          };
        })
        .filter((m): m is { role: "user" | "assistant"; content: string } => m !== null);

      const systemPrompt = `Você é um assistente de atendimento ao cliente via WhatsApp.
Contexto: Você está ajudando o atendente a formular respostas para o cliente "${contactName}".

IMPORTANTE: Leve em consideração as [Análise da conversa atual] que aparecem no histórico. Elas contêm a análise mais recente do sentimento do cliente, interpretação da situação, sugestões e mensagens prontas. Use esse contexto para responder de forma relevante ao momento atual da conversa.

Mantenha o tom conversacional adequado para WhatsApp.
Siga as instruções do atendente para ajustar a resposta.`;

      const response = await supabase.functions.invoke("whatsapp-ai-assistant", {
        body: {
          messages: [
            { role: "system", content: systemPrompt },
            ...recentMessages,
            { role: "user", content: userContent },
          ],
        },
      });

      if (response.error) throw response.error;

      const content = response.data?.content || "Não foi possível processar sua solicitação.";
      await addMessage({ role: "assistant", content });
    } catch (error) {
      console.error("Error sending message:", error);
      toast.error("Erro ao processar mensagem");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleCopy = async (text: string, id: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedId(id);
      setTimeout(() => setCopiedId(null), 2000);
      toast.success("Copiado!");
    } catch {
      toast.error("Erro ao copiar");
    }
  };

  const handleUseResponse = (text: string) => {
    onUseResponse(text);
  };

  const handleClearHistory = async () => {
    try {
      await clearMessages();
      toast.success("Histórico limpo");
    } catch {
      toast.error("Erro ao limpar histórico");
    }
  };

  const handleToggleRealtimeAnalysis = (checked: boolean) => {
    if (forceRealtimeAnalysis) return; // Cannot toggle when forced
    setRealtimeAnalysisEnabled(checked);
    if (checked) {
      toast.success("Análise em tempo real ativada");
    }
  };

  // Helper to parse analysis content from message
  const parseAnalysisContent = (content: string): AnalysisMessageContent | null => {
    try {
      return JSON.parse(content);
    } catch {
      return null;
    }
  };

  if (!isOpen) return null;

  return (
    <div className="w-full h-full border-l bg-background flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b bg-gradient-to-r from-primary/10 to-primary/5">
        <div className="flex items-center gap-2">
          <div className="h-8 w-8 rounded-full bg-primary/20 flex items-center justify-center">
            <Sparkles className="h-4 w-4 text-primary" />
          </div>
          <div>
            <h3 className="font-medium text-sm">Assistente IA</h3>
            <p className="text-xs text-muted-foreground truncate max-w-[150px]">
              {contactName}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-1">
          {/* Hide clear and close buttons when forced */}
          {!forceRealtimeAnalysis && messages.length > 0 && (
            <Button 
              variant="ghost" 
              size="icon" 
              onClick={handleClearHistory}
              title="Limpar histórico"
            >
              <Trash2 className="h-4 w-4" />
            </Button>
          )}
          {!forceRealtimeAnalysis && (
            <Button variant="ghost" size="icon" onClick={onClose}>
              <X className="h-4 w-4" />
            </Button>
          )}
        </div>
      </div>

      {/* Realtime Analysis Toggle + Fixed Temperature/Alerts */}
      <div className="px-4 py-2 border-b bg-muted/30">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-2">
            <Zap className={cn(
              "h-4 w-4",
              isAnalysisActive ? "text-amber-500" : "text-muted-foreground"
            )} />
            <span className="text-sm font-medium">Análise em Tempo Real</span>
            {forceRealtimeAnalysis && (
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-primary/10 text-primary">
                Sempre ativo
              </span>
            )}
          </div>
          {!forceRealtimeAnalysis && (
            <Switch
              checked={realtimeAnalysisEnabled}
              onCheckedChange={handleToggleRealtimeAnalysis}
            />
          )}
        </div>

        {/* Fixed Temperature + Alerts - only show metrics, not the full analysis */}
        {isAnalysisActive && (
          <WhatsAppRealtimeAnalysisCard
            analysis={analysis}
            isAnalyzing={isAnalyzing}
            error={analysisError}
            onRefresh={triggerAnalysis}
          />
        )}
      </div>

      {/* Messages */}
      <ScrollArea className="flex-1 px-4">
        <div className="py-4 space-y-4">
          {isLoadingHistory ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
            </div>
          ) : messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 text-center">
              <Sparkles className="h-8 w-8 text-muted-foreground/50 mb-2" />
              <p className="text-sm text-muted-foreground">
                Clique no ícone ✨ em uma mensagem do cliente
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                para receber sugestões de resposta
              </p>
            </div>
          ) : (
            <>
              {/* Load More Button */}
              {hasMore && (
                <div className="flex justify-center pb-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={loadMoreMessages}
                    disabled={isLoadingMore}
                    className="text-xs gap-1 text-muted-foreground hover:text-foreground"
                  >
                    {isLoadingMore ? (
                      <Loader2 className="h-3 w-3 animate-spin" />
                    ) : (
                      <ChevronUp className="h-3 w-3" />
                    )}
                    {isLoadingMore ? "Carregando..." : "Ver mensagens anteriores"}
                  </Button>
                </div>
              )}
              {messages.map((message) => {
                // Handle analysis messages
                if (message.role === "analysis") {
                  const analysisData = parseAnalysisContent(message.content);
                  if (analysisData) {
                    return (
                      <AnalysisChatMessage
                        key={message.id}
                        analysisData={analysisData}
                        timestamp={message.created_at}
                        onSendReadyMessage={(msg) => onUseResponse(msg)}
                      />
                    );
                  }
                  return null;
                }

                // Handle regular messages
                return (
                  <div key={message.id} className="space-y-2">
                    <div
                      className={cn(
                        "rounded-lg px-3 py-2",
                        message.role === "user"
                          ? "bg-primary text-primary-foreground ml-8"
                          : "bg-muted mr-4"
                      )}
                    >
                    {message.role === "assistant" ? (
                        <div className="prose prose-xs dark:prose-invert max-w-none text-xs [&>p]:text-xs [&>ul]:text-xs [&>ol]:text-xs [&>li]:text-xs [&>p]:leading-relaxed">
                          <ReactMarkdown>{message.content}</ReactMarkdown>
                        </div>
                      ) : (
                        <p className="text-xs whitespace-pre-wrap leading-relaxed">{message.content}</p>
                      )}
                    </div>

                    {/* Action buttons for assistant messages */}
                    {message.role === "assistant" && !message.content.startsWith("Desculpe") && (
                      <div className="flex items-center gap-2 ml-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-7 text-xs gap-1"
                          onClick={() => handleCopy(message.content, message.id)}
                        >
                          {copiedId === message.id ? (
                            <Check className="h-3 w-3" />
                          ) : (
                            <Copy className="h-3 w-3" />
                          )}
                          Copiar
                        </Button>
                        <Button
                          variant="default"
                          size="sm"
                          className="h-7 text-xs gap-1"
                          onClick={() => handleUseResponse(message.content)}
                        >
                          <MessageSquare className="h-3 w-3" />
                          Usar resposta
                        </Button>
                      </div>
                    )}
                  </div>
                );
              })}
            </>
          )}

          {isGenerating && (
            <div className="flex items-center gap-2 text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" />
              <span className="text-sm">Gerando resposta...</span>
            </div>
          )}

          {isAnalyzing && isAnalysisActive && (
            <div className="flex items-center gap-2 text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" />
              <span className="text-sm">Analisando conversa...</span>
            </div>
          )}

          <div ref={scrollRef} />
        </div>
      </ScrollArea>

      {/* Input */}
      <div className="p-4 border-t">
        <div className="flex gap-2">
          <Input
            ref={inputRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Peça ajustes na resposta..."
            disabled={isGenerating}
            className="text-sm"
          />
          <Button
            onClick={handleSend}
            disabled={!input.trim() || isGenerating}
            size="icon"
          >
            {isGenerating ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Send className="h-4 w-4" />
            )}
          </Button>
        </div>
        <p className="text-xs text-muted-foreground mt-2 text-center">
          Dica: "seja mais formal", "adicione emojis", "resuma"
        </p>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect, useCallback } from "react";
import { Play, Pause, Loader2, FileText } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Slider } from "@/components/ui/slider";
import { cn } from "@/lib/utils";
import { downloadAndCacheMedia, hasCachedMedia } from "@/hooks/useWhatsAppMediaCache";
import { supabase } from "@/integrations/supabase/client";

interface WhatsAppAudioPlayerProps {
  mediaUrl: string | null;
  messageId: string | null; // external_id (UazapiGO)
  supabaseMessageId: string | null; // Supabase message ID for caching
  instanceId: string | null;
  isOutgoing: boolean;
  cachedMediaUrl?: string | null;
  audioTranscription?: string | null;
  transcriptionStatus?: string | null;
}

const PLAYBACK_SPEEDS = [1, 1.5, 2];

export function WhatsAppAudioPlayer({
  mediaUrl,
  messageId,
  supabaseMessageId,
  instanceId,
  isOutgoing,
  cachedMediaUrl,
  audioTranscription,
  transcriptionStatus,
}: WhatsAppAudioPlayerProps) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [playbackSpeed, setPlaybackSpeed] = useState(1);
  const [audioSrc, setAudioSrc] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Transcription state
  const [transcription, setTranscription] = useState<string | null>(audioTranscription || null);
  const [isTranscribing, setIsTranscribing] = useState(transcriptionStatus === "processing");
  const [showTranscription, setShowTranscription] = useState(!!audioTranscription);

  // Update transcription when prop changes
  useEffect(() => {
    if (audioTranscription) {
      setTranscription(audioTranscription);
      setShowTranscription(true);
    }
  }, [audioTranscription]);

  // Check if we have cached media on mount
  useEffect(() => {
    if (hasCachedMedia(cachedMediaUrl)) {
      setAudioSrc(cachedMediaUrl!);
    }
  }, [cachedMediaUrl]);

  // Auto-transcribe all audio messages (incoming AND outgoing)
  useEffect(() => {
    // Transcribe if not already transcribed and has required IDs
    if (
      !audioTranscription &&
      transcriptionStatus !== "processing" &&
      transcriptionStatus !== "completed" &&
      transcriptionStatus !== "error" &&
      supabaseMessageId &&
      instanceId &&
      messageId
    ) {
      triggerTranscription();
    }
  }, [audioTranscription, transcriptionStatus, supabaseMessageId, instanceId, messageId]);

  const triggerTranscription = async () => {
    if (!supabaseMessageId || !instanceId || !messageId) {
      return;
    }

    setIsTranscribing(true);
    setShowTranscription(true);

    try {

      const { data, error } = await supabase.functions.invoke("transcribe-audio", {
        body: {
          messageId: supabaseMessageId,
          instanceId,
          externalMessageId: messageId,
        },
      });

      if (error) {
        console.error("[WhatsAppAudioPlayer] Transcription error:", error);
        setTranscription("Erro na transcrição");
        setIsTranscribing(false);
        return;
      } else if (data?.transcription) {
        setTranscription(data.transcription);
        setIsTranscribing(false);
        return;
      } else if (data?.success === false) {
        if (data?.error_code === "SERVICE_DISABLED") {
          setTranscription(
            `Transcrição indisponível: ative a API "Cloud Speech-to-Text" no Google Cloud e tente novamente.\n${
              data?.activation_url ? `Link: ${data.activation_url}` : ""
            }`
          );
        } else {
          setTranscription(data?.error || "Erro na transcrição");
        }
        setIsTranscribing(false);
        return;
      } else if (data?.status === "processing") {
        // Already processing, poll for result
        pollForTranscription();
        return;
      }

      // Fallback
      setIsTranscribing(false);
    } catch (err) {
      console.error("[WhatsAppAudioPlayer] Transcription failed:", err);
      setTranscription("Erro na transcrição");
      setIsTranscribing(false);
    }
  };

  const pollForTranscription = async () => {
    if (!supabaseMessageId) return;

    // Poll every 2 seconds for up to 60 seconds
    let attempts = 0;
    const maxAttempts = 30;

    const poll = async () => {
      if (attempts >= maxAttempts) {
        setIsTranscribing(false);
        setTranscription("Tempo esgotado");
        return;
      }

      const { data: msg } = await supabase
        .from("whatsapp_messages")
        .select("audio_transcription, transcription_status")
        .eq("id", supabaseMessageId)
        .single();

      if (msg?.audio_transcription) {
        setTranscription(msg.audio_transcription);
        setIsTranscribing(false);
        return;
      }

      if (msg?.transcription_status === "error") {
        setTranscription("Erro na transcrição");
        setIsTranscribing(false);
        return;
      }

      attempts++;
      setTimeout(poll, 2000);
    };

    poll();
  };

  // Fetch audio URL via edge function proxy and cache it
  const loadAudio = useCallback(async () => {
    if (audioSrc) return; // Already loaded

    setIsLoading(true);
    setError(null);

    try {
      // Need instanceId and messageId for UazapiGO download
      if (!instanceId || !messageId) {
        // Try direct URL as fallback
        if (mediaUrl) {
          const testResponse = await fetch(mediaUrl, { method: "HEAD" }).catch(() => null);
          if (testResponse?.ok) {
            setAudioSrc(mediaUrl);
            setIsLoading(false);
            return;
          }
        }
        setError("Áudio não disponível");
        setIsLoading(false);
        return;
      }


      const result = await downloadAndCacheMedia({
        instanceId,
        externalMessageId: messageId,
        supabaseMessageId: supabaseMessageId || "",
        fileName: "audio.mp3",
        shouldCache: !!supabaseMessageId,
      });

      if (!result) {
        throw new Error("Falha ao baixar áudio");
      }

      const { blob, cachedUrl } = result;

      // If we got a cached URL, use it directly. Otherwise create blob URL
      if (cachedUrl) {
        setAudioSrc(cachedUrl);
      } else {
        const objectUrl = URL.createObjectURL(blob);
        setAudioSrc(objectUrl);
      }

    } catch (err: unknown) {
      console.error("[WhatsAppAudioPlayer] Error loading audio:", err);
      setError("Erro ao carregar áudio");
    } finally {
      setIsLoading(false);
    }
  }, [mediaUrl, instanceId, messageId, supabaseMessageId, audioSrc]);

  // Cleanup object URL on unmount (only if it's a blob URL)
  useEffect(() => {
    return () => {
      if (audioSrc && audioSrc.startsWith("blob:")) {
        URL.revokeObjectURL(audioSrc);
      }
    };
  }, [audioSrc]);

  // Update time display
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;

    const handleTimeUpdate = () => setCurrentTime(audio.currentTime);
    const handleLoadedMetadata = () => setDuration(audio.duration);
    const handleEnded = () => setIsPlaying(false);

    audio.addEventListener("timeupdate", handleTimeUpdate);
    audio.addEventListener("loadedmetadata", handleLoadedMetadata);
    audio.addEventListener("ended", handleEnded);

    return () => {
      audio.removeEventListener("timeupdate", handleTimeUpdate);
      audio.removeEventListener("loadedmetadata", handleLoadedMetadata);
      audio.removeEventListener("ended", handleEnded);
    };
  }, [audioSrc]);

  const togglePlay = async () => {
    if (!audioSrc) {
      await loadAudio();
      return;
    }

    const audio = audioRef.current;
    if (!audio) return;

    if (isPlaying) {
      audio.pause();
      setIsPlaying(false);
    } else {
      await audio.play();
      setIsPlaying(true);
    }
  };

  const handleSeek = (value: number[]) => {
    const audio = audioRef.current;
    if (!audio || !duration) return;

    const newTime = (value[0] / 100) * duration;
    audio.currentTime = newTime;
    setCurrentTime(newTime);
  };

  const cyclePlaybackSpeed = () => {
    const currentIndex = PLAYBACK_SPEEDS.indexOf(playbackSpeed);
    const nextIndex = (currentIndex + 1) % PLAYBACK_SPEEDS.length;
    const newSpeed = PLAYBACK_SPEEDS[nextIndex];

    setPlaybackSpeed(newSpeed);
    if (audioRef.current) {
      audioRef.current.playbackRate = newSpeed;
    }
  };

  const formatTime = (seconds: number) => {
    if (!isFinite(seconds) || isNaN(seconds)) return "0:00";
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, "0")}`;
  };

  const progress = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <div className="flex flex-col gap-2 w-full min-w-[240px]">
      {/* Audio Player */}
      <div className={cn(
        "flex items-center gap-3 p-3 rounded-lg w-full",
        isOutgoing ? "bg-primary-foreground/10" : "bg-background/50"
      )}>
        {audioSrc && (
          <audio ref={audioRef} src={audioSrc} preload="metadata" />
        )}

        {/* Play/Pause button */}
        <Button
          size="icon"
          variant="ghost"
          className={cn(
            "h-10 w-10 rounded-full shrink-0",
            isOutgoing 
              ? "bg-primary-foreground/20 hover:bg-primary-foreground/30 text-primary-foreground" 
              : "bg-primary/10 hover:bg-primary/20 text-primary"
          )}
          onClick={togglePlay}
          disabled={isLoading}
        >
          {isLoading ? (
            <Loader2 className="h-5 w-5 animate-spin" />
          ) : isPlaying ? (
            <Pause className="h-5 w-5" />
          ) : (
            <Play className="h-5 w-5 ml-0.5" />
          )}
        </Button>

        {/* Progress and controls */}
        <div className="flex-1 flex flex-col gap-1 min-w-0">
          {/* Slider */}
          <div className="px-1 py-1">
            <Slider
              value={[progress]}
              max={100}
              step={0.1}
              onValueChange={handleSeek}
              disabled={!audioSrc || duration === 0}
              className={cn(
                "cursor-pointer w-full",
                isOutgoing ? "[&_[role=slider]]:bg-primary-foreground" : ""
              )}
            />
          </div>

          {/* Time and speed */}
          <div className="flex items-center justify-between text-xs gap-2">
            <span className={cn(
              "truncate",
              isOutgoing ? "text-primary-foreground/70" : "text-muted-foreground"
            )}>
              {formatTime(currentTime)} / {formatTime(duration)}
            </span>

            <Button
              variant="ghost"
              size="sm"
              className={cn(
                "h-5 px-1.5 text-xs font-medium shrink-0",
                isOutgoing 
                  ? "text-primary-foreground/70 hover:text-primary-foreground hover:bg-primary-foreground/10" 
                  : "text-muted-foreground hover:text-foreground hover:bg-muted"
              )}
              onClick={cyclePlaybackSpeed}
              disabled={!audioSrc}
            >
              {playbackSpeed}x
            </Button>
          </div>
        </div>

        {/* Error state */}
        {error && (
          <span className="text-xs text-destructive shrink-0">{error}</span>
        )}
      </div>

      {/* Transcription Section - For both incoming and outgoing messages */}
      {showTranscription && (
        <div className={cn(
          "flex items-start gap-2 px-3 py-2 rounded-lg text-sm",
          isOutgoing 
            ? "bg-primary-foreground/10 border border-primary-foreground/20" 
            : "bg-muted/50 border border-border/50"
        )}>
          <FileText className={cn(
            "h-4 w-4 shrink-0 mt-0.5",
            isOutgoing ? "text-primary-foreground/70" : "text-muted-foreground"
          )} />
          <div className="flex-1 min-w-0">
            {isTranscribing ? (
              <div className={cn(
                "flex items-center gap-2",
                isOutgoing ? "text-primary-foreground/70" : "text-muted-foreground"
              )}>
                <Loader2 className="h-3 w-3 animate-spin" />
                <span className="text-xs">Transcrevendo áudio...</span>
              </div>
            ) : transcription ? (
              <p className={cn(
                "whitespace-pre-wrap break-words text-xs leading-relaxed",
                isOutgoing ? "text-primary-foreground/90" : "text-foreground/90"
              )}>
                {transcription}
              </p>
            ) : null}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Loader2, ShieldOff, RefreshCw, UserX, Unlock } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

interface BlockedContact {
  jid: string;
  phone: string;
  formatted_phone: string;
}

interface WhatsAppBlockedContactsModalProps {
  isOpen: boolean;
  onClose: () => void;
  companyId: string | undefined;
  instanceId: string | null;
}

export function WhatsAppBlockedContactsModal({
  isOpen,
  onClose,
  companyId,
  instanceId,
}: WhatsAppBlockedContactsModalProps) {
  const [blockedContacts, setBlockedContacts] = useState<BlockedContact[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [unblockingPhone, setUnblockingPhone] = useState<string | null>(null);

  const fetchBlockedContacts = async () => {
    if (!companyId || !instanceId) return;

    setIsLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke("fetch-whatsapp-blocklist", {
        body: {
          company_id: companyId,
          instance_id: instanceId,
        },
      });

      if (error) throw error;

      if (data?.success) {
        setBlockedContacts(data.blockList || []);
      } else {
        throw new Error(data?.error || "Erro ao buscar contatos bloqueados");
      }
    } catch (err: unknown) {
      console.error("[WhatsAppBlockedContactsModal] Error:", err);
      toast.error(err.message || "Erro ao buscar contatos bloqueados");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUnblockContact = async (contact: BlockedContact) => {
    if (!companyId || !instanceId) return;

    setUnblockingPhone(contact.phone);
    try {
      const { data, error } = await supabase.functions.invoke("block-whatsapp-contact", {
        body: {
          company_id: companyId,
          instance_id: instanceId,
          phone: contact.phone,
          block: false,
        },
      });

      if (error) throw error;

      if (data?.success) {
        toast.success("Contato desbloqueado com sucesso");
        // Remove from local list
        setBlockedContacts((prev) => prev.filter((c) => c.phone !== contact.phone));
      } else {
        throw new Error(data?.error || "Erro ao desbloquear contato");
      }
    } catch (err: unknown) {
      console.error("[WhatsAppBlockedContactsModal] Unblock error:", err);
      toast.error(err.message || "Erro ao desbloquear contato");
    } finally {
      setUnblockingPhone(null);
    }
  };

  useEffect(() => {
    if (isOpen && companyId && instanceId) {
      fetchBlockedContacts();
    }
  }, [isOpen, companyId, instanceId]);

  const getInitials = (phone: string): string => {
    const digits = phone.replace(/\D/g, "");
    return digits.slice(-2);
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader className="flex flex-row items-center justify-between">
          <div className="flex items-center gap-2">
            <ShieldOff className="h-5 w-5 text-destructive" />
            <DialogTitle>Contatos Bloqueados</DialogTitle>
          </div>
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={fetchBlockedContacts}
            disabled={isLoading}
          >
            <RefreshCw className={`h-4 w-4 ${isLoading ? "animate-spin" : ""}`} />
          </Button>
        </DialogHeader>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-12 gap-3">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            <p className="text-sm text-muted-foreground">Carregando contatos bloqueados...</p>
          </div>
        ) : blockedContacts.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 gap-3">
            <UserX className="h-12 w-12 text-muted-foreground/30" />
            <p className="text-sm text-muted-foreground">Nenhum contato bloqueado</p>
          </div>
        ) : (
          <ScrollArea className="max-h-[400px]">
            <div className="space-y-2 pr-4">
              {blockedContacts.map((contact) => (
                <div
                  key={contact.jid}
                  className="flex items-center gap-3 p-3 rounded-lg bg-muted/50"
                >
                  <Avatar className="h-10 w-10">
                    <AvatarFallback className="bg-destructive/10 text-destructive text-sm">
                      {getInitials(contact.phone)}
                    </AvatarFallback>
                  </Avatar>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium">{contact.formatted_phone}</p>
                    <p className="text-xs text-muted-foreground truncate">+{contact.phone}</p>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleUnblockContact(contact)}
                    disabled={unblockingPhone === contact.phone}
                    className="text-primary hover:text-primary"
                  >
                    {unblockingPhone === contact.phone ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <>
                        <Unlock className="h-4 w-4 mr-1" />
                        Desbloquear
                      </>
                    )}
                  </Button>
                </div>
              ))}
            </div>
          </ScrollArea>
        )}

        <div className="pt-2 border-t">
          <p className="text-xs text-muted-foreground text-center">
            {blockedContacts.length} contato{blockedContacts.length !== 1 ? "s" : ""} bloqueado{blockedContacts.length !== 1 ? "s" : ""}
          </p>
        </div>
      </DialogContent>
    </Dialog>
  );
}

