interface WhatsAppChatWindowProps {
  conversation: WhatsAppConversation;
  companyId: string | undefined;
  instanceId?: string | null;
  onChatDeleted?: (conversationId: string) => void;
  onChatArchived?: (conversationId: string, archived: boolean) => void;
  onNavigateAway?: () => void; // Called when navigating away (e.g., to client page)
}

export function WhatsAppChatWindow({ conversation, companyId, instanceId, onChatDeleted, onChatArchived, onNavigateAway }: WhatsAppChatWindowProps) {
  const navigate = useNavigate();
  const { messages, isLoading, isFetchingFromApi, isSyncingInBackground, isSendingMedia, sendMessage, sendMedia, fetchMessagesFromApi } = useWhatsAppMessages(
    conversation.id,
    companyId
  );
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isArchiving, setIsArchiving] = useState(false);
  const [deleteFromWhatsApp, setDeleteFromWhatsApp] = useState(true);
  const [deleteLocal, setDeleteLocal] = useState(true);
  const [chatLabelIds, setChatLabelIds] = useState<string[]>(conversation.label_ids || []);
  const [showProfilePic, setShowProfilePic] = useState(false);
  const [isMarkingRead, setIsMarkingRead] = useState(false);
  const [isTogglingRead, setIsTogglingRead] = useState(false);
  const [isMuting, setIsMuting] = useState(false);
  const [isPinning, setIsPinning] = useState(false);
  const [isBlocking, setIsBlocking] = useState(false);
  const [linkedClientId, setLinkedClientId] = useState<string | null>(null);
  const [linkedClientName, setLinkedClientName] = useState<string | null>(null);
  const [linkedClientLogo, setLinkedClientLogo] = useState<string | null>(null);

  // Update linked client state when conversation changes - reset immediately on conversation.id change
  useEffect(() => {
    // Immediately set from conversation data to avoid showing stale state
    setLinkedClientId(conversation.client_id || null);
    setLinkedClientName(conversation.client_name || null);
    setLinkedClientLogo(conversation.client_logo_url || null);
    // Clear reply state when switching conversations
    setReplyToMessage(null);
  }, [conversation.id]); // Only depend on conversation.id to reset on switch

  // Also update when the client data within the same conversation is updated (e.g., after linking)
  useEffect(() => {
    if (conversation.client_id !== linkedClientId) {
      setLinkedClientId(conversation.client_id || null);
      setLinkedClientName(conversation.client_name || null);
      setLinkedClientLogo(conversation.client_logo_url || null);
    }
  }, [conversation.client_id, conversation.client_name, conversation.client_logo_url]);

  // AI Assistant state
  const [aiAssistantOpen, setAiAssistantOpen] = useState(false);
  const [aiSelectedMessage, setAiSelectedMessage] = useState("");
  const [aiSendDialogOpen, setAiSendDialogOpen] = useState(false);
  const [aiSuggestedResponse, setAiSuggestedResponse] = useState("");
  const [isSendingAiResponse, setIsSendingAiResponse] = useState(false);

  // CS Tools modals state
  const [reminderModalOpen, setReminderModalOpen] = useState(false);
  const [taskModalOpen, setTaskModalOpen] = useState(false);
  const [noteModalOpen, setNoteModalOpen] = useState(false);

  // Reply to message state
  const [replyToMessage, setReplyToMessage] = useState<import("@/hooks/useWhatsAppMessages").WhatsAppMessage | null>(null);

  const { labels } = useWhatsAppLabels(companyId, instanceId ?? null);
  const { quickReplies, isLoading: quickRepliesLoading } = useWhatsAppQuickReplies(instanceId ?? null);
  const { sizes, setAiAssistantSize } = useWhatsAppPanelSizes();
  const { config: aiAgentConfig } = useWhatsAppAIAgentConfig(companyId, conversation.instance_id || instanceId);
  const { assignment: currentAssignment } = useConversationAssignment(conversation.id, companyId);
  const queryClient = useQueryClient();

  // Check if realtime analysis is forced globally
  const forceRealtimeAnalysis = aiAgentConfig?.force_realtime_analysis ?? false;
  const ignoreGroupAnalysis = aiAgentConfig?.ignore_group_analysis ?? true;

  // Check if this is a group conversation
  // Groups can be identified by:
  // - @g.us suffix (standard WhatsApp group format)
  // - Hyphen in phone (some group formats)
  // - Phone starting with "120363" (WhatsApp group ID pattern)
  // - Very long phone numbers (20+ digits typically indicate groups)
  const isGroupConversation = 
    conversation.phone?.includes("@g.us") || 
    conversation.phone?.includes("-") ||
    conversation.phone?.startsWith("120363") ||
    (conversation.phone?.length || 0) > 18;

  // Should hide AI for groups if ignore_group_analysis is enabled
  const shouldHideAIForGroup = isGroupConversation && ignoreGroupAnalysis;

  // Debug logging (can be removed later)
  if (isGroupConversation) {
  }

  // If forced, keep AI assistant always open - BUT not for groups when ignore is enabled
  const isAiAssistantVisible = shouldHideAIForGroup ? false : (forceRealtimeAnalysis || aiAssistantOpen);

  // Scroll to bottom when messages change
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages]);

  const displayName = conversation.contact_name || formatPhoneNumber(conversation.phone);

  const handleSend = (message: string, replyToMessageId?: string) => {
    sendMessage({ phone: conversation.phone, message, instanceId: instanceId ?? null, replyToMessageId });
  };

  const handleSendMedia = (media: MediaAttachment, caption: string) => {
    sendMedia({ phone: conversation.phone, media, caption, instanceId: instanceId ?? null });
  };

  const handleDeleteChat = async () => {
    if (!companyId || !instanceId) {
      toast.error("Não foi possível deletar o chat");
      return;
    }

    setIsDeleting(true);

    try {
      const { data, error } = await supabase.functions.invoke("delete-whatsapp-chat", {
        body: {
          company_id: companyId,
          instance_id: instanceId,
          phone: conversation.phone,
          conversation_id: conversation.id,
          delete_chat_whatsapp: deleteFromWhatsApp,
          delete_local: deleteLocal,
          delete_chat_db: false,
          delete_messages_db: false,
        },
      });

      if (error) throw error;

      if (data?.success) {
        toast.success("Chat deletado com sucesso");
        setIsDeleteDialogOpen(false);
        onChatDeleted?.(conversation.id);
      } else {
        throw new Error(data?.error || "Erro ao deletar chat");
      }
    } catch (err: unknown) {
      console.error("[WhatsAppChatWindow] Delete chat error:", err);
      toast.error(err.message || "Erro ao deletar chat");
    } finally {
      setIsDeleting(false);
    }
  };

  const handleMarkAllRead = async () => {
    if (!companyId || !instanceId) {
      toast.error("Não foi possível marcar como lida");
      return;
    }

    setIsMarkingRead(true);

    try {
      const { data, error } = await supabase.functions.invoke("mark-whatsapp-read", {
        body: {
          company_id: companyId,
          instance_id: instanceId,
          conversation_id: conversation.id,
        },
      });

      if (error) throw error;

      if (data?.success) {
        toast.success(`${data.marked || 0} mensagens marcadas como lidas`);
      } else {
        throw new Error(data?.error || "Erro ao marcar mensagens");
      }
    } catch (err: unknown) {
      console.error("[WhatsAppChatWindow] Mark read error:", err);
      toast.error(err.message || "Erro ao marcar como lida");
    } finally {
      setIsMarkingRead(false);
    }
  };

  const handleArchiveChat = async () => {
    if (!companyId || !instanceId) {
      toast.error("Não foi possível arquivar o chat");
      return;
    }

    setIsArchiving(true);
    const newArchiveState = !conversation.is_archived;

    try {
      const { data, error } = await supabase.functions.invoke("archive-whatsapp-chat", {
        body: {
          company_id: companyId,
          instance_id: instanceId,
          phone: conversation.phone,
          conversation_id: conversation.id,
          archive: newArchiveState,
        },
      });

      if (error) throw error;

      if (data?.success) {
        toast.success(newArchiveState ? "Chat arquivado" : "Chat desarquivado");
        onChatArchived?.(conversation.id, newArchiveState);
      } else {
        throw new Error(data?.error || "Erro ao arquivar chat");
      }
    } catch (err: unknown) {
      console.error("[WhatsAppChatWindow] Archive chat error:", err);
      toast.error(err.message || "Erro ao arquivar chat");
    } finally {
      setIsArchiving(false);
    }
  };

  const handleToggleChatRead = async () => {
    if (!companyId || !instanceId) {
      toast.error("Não foi possível alterar status de leitura");
      return;
    }

    setIsTogglingRead(true);
    const newReadState = conversation.unread_count > 0; // If has unread, mark as read; otherwise mark as unread

    try {
      const { data, error } = await supabase.functions.invoke("toggle-whatsapp-chat-read", {
        body: {
          company_id: companyId,
          instance_id: instanceId,
          conversation_id: conversation.id,
          phone: conversation.phone,
          read: newReadState,
        },
      });

      if (error) throw error;

      if (data?.success) {
        toast.success(newReadState ? "Chat marcado como lido" : "Chat marcado como não lido");
      } else {
        throw new Error(data?.error || "Erro ao alterar status");
      }
    } catch (err: unknown) {
      console.error("[WhatsAppChatWindow] Toggle read error:", err);
      toast.error(err.message || "Erro ao alterar status de leitura");
    } finally {
      setIsTogglingRead(false);
    }
  };

  const handleMuteChat = async (muteEndTime: number) => {
    if (!companyId || !instanceId) {
      toast.error("Não foi possível silenciar o chat");
      return;
    }

    setIsMuting(true);

    try {
      const { data, error } = await supabase.functions.invoke("mute-whatsapp-chat", {
        body: {
          company_id: companyId,
          instance_id: instanceId,
          phone: conversation.phone,
          mute_end_time: muteEndTime,
        },
      });

      if (error) throw error;

      if (data?.success) {
        toast.success(data.message);
      } else {
        throw new Error(data?.error || "Erro ao silenciar chat");
      }
    } catch (err: unknown) {
      console.error("[WhatsAppChatWindow] Mute chat error:", err);
      toast.error(err.message || "Erro ao silenciar chat");
    } finally {
      setIsMuting(false);
    }
  };

  const handlePinChat = async () => {
    if (!companyId || !instanceId) {
      toast.error("Não foi possível fixar o chat");
      return;
    }

    setIsPinning(true);
    const newPinStatus = !conversation.is_pinned;

    try {
      const { data, error } = await supabase.functions.invoke("pin-whatsapp-chat", {
        body: {
          company_id: companyId,
          instance_id: instanceId,
          phone: conversation.phone,
          pin: newPinStatus,
        },
      });

      if (error) throw error;

      if (data?.success) {
        toast.success(data.message);
      } else {
        throw new Error(data?.error || "Erro ao fixar chat");
      }
    } catch (err: unknown) {
      console.error("[WhatsAppChatWindow] Pin chat error:", err);
      toast.error(err.message || "Erro ao fixar chat");
    } finally {
      setIsPinning(false);
    }
  };

  const handleBlockContact = async () => {
    if (!companyId || !instanceId) {
      toast.error("Não foi possível bloquear o contato");
      return;
    }

    setIsBlocking(true);

    try {
      const { data, error } = await supabase.functions.invoke("block-whatsapp-contact", {
        body: {
          company_id: companyId,
          instance_id: instanceId,
          phone: conversation.phone,
          block: true,
        },
      });

      if (error) throw error;

      if (data?.success) {
        toast.success(data.message);
      } else {
        throw new Error(data?.error || "Erro ao bloquear contato");
      }
    } catch (err: unknown) {
      console.error("[WhatsAppChatWindow] Block contact error:", err);
      toast.error(err.message || "Erro ao bloquear contato");
    } finally {
      setIsBlocking(false);
    }
  };

  const handleOpenAIAssistant = (messageContent: string) => {
    setAiSelectedMessage(messageContent);
    setAiAssistantOpen(true);
  };

  const handleUseAIResponse = (response: string) => {
    setAiSuggestedResponse(response);
    setAiSendDialogOpen(true);
  };

  const handleSendAIResponse = (message: string) => {
    // Close modal immediately - message will appear via optimistic UI
    setAiSendDialogOpen(false);
    setAiAssistantOpen(false);
    setAiSuggestedResponse("");

    // Fire and forget - sendMessage already handles optimistic UI and error states
    sendMessage({ phone: conversation.phone, message, instanceId: instanceId ?? null });
  };

  const handleNavigateToClient = () => {
    if (linkedClientId) {
      onNavigateAway?.(); // Close the drawer first
      navigate(`/clientes/${linkedClientId}`);
    }
  };

  return (
    <ResizablePanelGroup 
      direction="horizontal" 
      className="h-full"
      onLayout={(panelSizes) => {
        // When AI assistant is open, save the AI panel size (second panel)
        if (aiAssistantOpen && panelSizes[1]) {
          setAiAssistantSize(panelSizes[1]);
        }
      }}
    >
      {/* Main chat area */}
      <ResizablePanel defaultSize={aiAssistantOpen ? (100 - sizes.aiAssistant) : 100} minSize={50}>
        <div className="flex flex-col h-full min-w-0">
      <div className="flex items-center gap-2 md:gap-3 px-2 md:px-4 py-2 md:py-3 border-b bg-muted/30">
        <div className="relative shrink-0">
          <Avatar 
            className={cn(
              "h-8 w-8 md:h-10 md:w-10",
              conversation.profile_pic_url && "cursor-pointer hover:ring-2 hover:ring-primary/50 transition-all"
            )}
            onClick={() => conversation.profile_pic_url && setShowProfilePic(true)}
          >
            {conversation.profile_pic_url && (
              <AvatarImage 
                src={conversation.profile_pic_url} 
                alt={displayName}
                className="object-cover"
              />
            )}
            <AvatarFallback className="bg-primary/10 text-primary text-xs md:text-sm font-medium">
              {getInitials(displayName)}
            </AvatarFallback>
          </Avatar>

          {/* Client logo overlay - clickable to navigate to client */}
          {linkedClientId && (
            <Tooltip>
              <TooltipTrigger asChild>
                <button 
                  onClick={handleNavigateToClient}
                  className="absolute -bottom-1 -right-1 h-4 w-4 md:h-5 md:w-5 rounded-full border-2 border-background bg-background overflow-hidden shadow-sm cursor-pointer hover:ring-2 hover:ring-primary/50 transition-all"
                >
                  {linkedClientLogo ? (
                    <img 
                      src={linkedClientLogo} 
                      alt={linkedClientName || "Cliente"}
                      className="h-full w-full object-cover"
                    />
                  ) : (
                    <div className="h-full w-full bg-primary/10 flex items-center justify-center">
                      <Building2 className="h-2.5 w-2.5 md:h-3 md:w-3 text-primary" />
                    </div>
                  )}
                </button>
              </TooltipTrigger>
              <TooltipContent side="right" className="text-xs">
                <span>Abrir cadastro: {linkedClientName}</span>
              </TooltipContent>
            </Tooltip>
          )}
        </div>
        <div className="flex-1 min-w-0 max-w-[120px] md:max-w-none">
          <div className="flex items-center gap-1 md:gap-2">
            <h3 className="font-medium text-xs md:text-sm truncate">{displayName}</h3>
            {/* Label badges - hide on small screens */}
            <div className="hidden md:flex">
              {chatLabelIds.length > 0 && (
                <WhatsAppLabelList 
                  labels={labels.filter(l => chatLabelIds.includes(l.id))} 
                  maxVisible={2}
                />
              )}
            </div>
          </div>
          <p className="text-[10px] md:text-xs text-muted-foreground flex items-center gap-1">
            <Phone className="h-2.5 w-2.5 md:h-3 md:w-3 shrink-0" />
            <span className="truncate">{formatPhoneNumber(conversation.phone)}</span>
            {/* Background sync indicator - hide on small screens */}
            {isSyncingInBackground && (
              <span className="hidden md:flex ml-2 items-center gap-1 text-primary/70">
                <RefreshCw className="h-3 w-3 animate-spin" />
                <span className="text-[10px]">Sincronizando...</span>
              </span>
            )}
          </p>
        </div>

        {/* Client linker */}
        <WhatsAppClientLinker
          conversationId={conversation.id}
          currentClientId={conversation.client_id}
          companyId={companyId}
          conversationPhone={conversation.phone}
          conversationContactName={conversation.contact_name}
          onClientChange={(clientId, clientName, clientLogoUrl) => {
            setLinkedClientId(clientId);
            setLinkedClientName(clientName);
            setLinkedClientLogo(clientLogoUrl || null);
          }}
        />

        {/* Assignment picker */}
        <WhatsAppAssignmentPicker
          conversationId={conversation.id}
          companyId={companyId}
          currentAssignment={currentAssignment || null}
          onAssignmentChange={() => {
            queryClient.invalidateQueries({ queryKey: ["whatsapp-assignments", companyId] });
            queryClient.invalidateQueries({ queryKey: ["whatsapp-assignment", conversation.id] });
          }}
        />

        {/* Label picker */}
        <WhatsAppLabelPicker
          phone={conversation.phone}
          currentLabelIds={chatLabelIds}
          companyId={companyId}
          instanceId={instanceId ?? null}
          onLabelsChange={setChatLabelIds}
        />

        {/* CS Tools - Lembrete e Tarefa: only shows when a client is linked */}
        {linkedClientId && (
          <>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 md:h-9 md:w-9"
                  onClick={() => setReminderModalOpen(true)}
                >
                  <Clock className="h-3.5 w-3.5 md:h-4 md:w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>Adicionar Lembrete</TooltipContent>
            </Tooltip>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 md:h-9 md:w-9"
                  onClick={() => setTaskModalOpen(true)}
                >
                  <ListTodo className="h-3.5 w-3.5 md:h-4 md:w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>Criar Tarefa</TooltipContent>
            </Tooltip>
          </>
        )}

        {/* Observação - sempre disponível (é por chat, não por cliente) */}
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 md:h-9 md:w-9"
              onClick={() => setNoteModalOpen(true)}
            >
              <StickyNote className="h-3.5 w-3.5 md:h-4 md:w-4" />
            </Button>
          </TooltipTrigger>
          <TooltipContent>Adicionar Observação</TooltipContent>
        </Tooltip>

        {/* Open client button - only shows when a client is linked */}
        {linkedClientId && (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 md:h-9 md:w-9"
                onClick={handleNavigateToClient}
                title="Abrir cadastro do cliente"
              >
                <ExternalLink className="h-3.5 w-3.5 md:h-4 md:w-4" />
              </Button>
            </TooltipTrigger>
            <TooltipContent>Abrir cadastro: {linkedClientName}</TooltipContent>
          </Tooltip>
        )}

        {/* AI Assistant button */}
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant={aiAssistantOpen ? "secondary" : "ghost"}
              size="icon"
              className="h-8 w-8 md:h-9 md:w-9"
              onClick={() => setAiAssistantOpen(!aiAssistantOpen)}
              title="Assistente IA"
            >
              <Sparkles className={cn("h-3.5 w-3.5 md:h-4 md:w-4", aiAssistantOpen && "text-primary")} />
            </Button>
          </TooltipTrigger>
          <TooltipContent>Assistente IA</TooltipContent>
        </Tooltip>

        {/* Refresh messages button */}
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8 md:h-9 md:w-9"
          onClick={() => fetchMessagesFromApi(true)}
          disabled={isFetchingFromApi}
          title="Atualizar mensagens"
        >
          <RefreshCw className={`h-3.5 w-3.5 md:h-4 md:w-4 ${isFetchingFromApi ? 'animate-spin' : ''}`} />
        </Button>

        {/* More options menu */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="icon" className="h-8 w-8 md:h-9 md:w-9">
              <MoreVertical className="h-3.5 w-3.5 md:h-4 md:w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={() => fetchMessagesFromApi(true)}>
              <RefreshCw className="h-4 w-4 mr-2" />
              Atualizar mensagens
            </DropdownMenuItem>
            <DropdownMenuItem 
              onClick={handleMarkAllRead}
              disabled={isMarkingRead}
            >
              {isMarkingRead ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : (
                <CheckCheck className="h-4 w-4 mr-2" />
              )}
              Marcar tudo como lido
            </DropdownMenuItem>
            <DropdownMenuItem 
              onClick={handleToggleChatRead}
              disabled={isTogglingRead}
            >
              {isTogglingRead ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : conversation.unread_count > 0 ? (
                <Circle className="h-4 w-4 mr-2" />
              ) : (
                <CircleDot className="h-4 w-4 mr-2" />
              )}
              {conversation.unread_count > 0 ? "Marcar como lido" : "Marcar como não lido"}
            </DropdownMenuItem>
            <DropdownMenuItem 
              onClick={handleArchiveChat}
              disabled={isArchiving}
            >
              {isArchiving ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : conversation.is_archived ? (
                <ArchiveRestore className="h-4 w-4 mr-2" />
              ) : (
                <Archive className="h-4 w-4 mr-2" />
              )}
              {conversation.is_archived ? "Desarquivar chat" : "Arquivar chat"}
            </DropdownMenuItem>
            <DropdownMenuItem 
              onClick={handlePinChat}
              disabled={isPinning}
            >
              {isPinning ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : conversation.is_pinned ? (
                <PinOff className="h-4 w-4 mr-2" />
              ) : (
                <Pin className="h-4 w-4 mr-2" />
              )}
              {conversation.is_pinned ? "Desafixar chat" : "Fixar no topo"}
            </DropdownMenuItem>
            <DropdownMenuSub>
              <DropdownMenuSubTrigger disabled={isMuting}>
                {isMuting ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : (
                  <BellOff className="h-4 w-4 mr-2" />
                )}
                Silenciar notificações
              </DropdownMenuSubTrigger>
              <DropdownMenuSubContent>
                <DropdownMenuItem onClick={() => handleMuteChat(8)}>
                  Por 8 horas
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleMuteChat(168)}>
                  Por 1 semana
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleMuteChat(-1)}>
                  Permanentemente
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => handleMuteChat(0)}>
                  <Bell className="h-4 w-4 mr-2" />
                  Remover silenciamento
                </DropdownMenuItem>
              </DropdownMenuSubContent>
            </DropdownMenuSub>
            <DropdownMenuSeparator />
            {/* CS Tools Section */}
            <DropdownMenuItem 
              onClick={() => {
                if (!linkedClientId) {
                  toast.error("Vincule este chat a um cliente primeiro");
                  return;
                }
                setReminderModalOpen(true);
              }}
            >
              <Clock className="h-4 w-4 mr-2" />
              Adicionar Lembrete
            </DropdownMenuItem>
            <DropdownMenuItem 
              onClick={() => {
                if (!linkedClientId) {
                  toast.error("Vincule este chat a um cliente primeiro");
                  return;
                }
                setTaskModalOpen(true);
              }}
            >
              <ListTodo className="h-4 w-4 mr-2" />
              Criar Tarefa
            </DropdownMenuItem>
            <DropdownMenuItem 
              onClick={() => setNoteModalOpen(true)}
            >
              <StickyNote className="h-4 w-4 mr-2" />
              Adicionar Observação
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem 
              onClick={handleBlockContact}
              disabled={isBlocking}
              className="text-destructive focus:text-destructive"
            >
              {isBlocking ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : (
                <Ban className="h-4 w-4 mr-2" />
              )}
              Bloquear contato
            </DropdownMenuItem>
            <DropdownMenuItem 
              onClick={() => setIsDeleteDialogOpen(true)}
              className="text-destructive focus:text-destructive"
            >
              <Trash2 className="h-4 w-4 mr-2" />
              Deletar chat
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      {/* Delete chat dialog */}
      <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Deletar chat?</AlertDialogTitle>
            <AlertDialogDescription>
              Escolha como deseja deletar este chat com {displayName}.
            </AlertDialogDescription>
          </AlertDialogHeader>

          <div className="py-4 space-y-4">
            <div className="flex items-center space-x-2">
              <Checkbox 
                id="delete-whatsapp" 
                checked={deleteFromWhatsApp}
                onCheckedChange={(checked) => setDeleteFromWhatsApp(checked === true)}
              />
              <Label htmlFor="delete-whatsapp" className="text-sm">
                Deletar do WhatsApp
                <span className="block text-xs text-muted-foreground">
                  Remove o chat do seu WhatsApp
                </span>
              </Label>
            </div>

            <div className="flex items-center space-x-2">
              <Checkbox 
                id="delete-local" 
                checked={deleteLocal}
                onCheckedChange={(checked) => setDeleteLocal(checked === true)}
              />
              <Label htmlFor="delete-local" className="text-sm">
                Deletar do sistema
                <span className="block text-xs text-muted-foreground">
                  Remove o chat e mensagens deste painel
                </span>
              </Label>
            </div>
          </div>

          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>Cancelar</AlertDialogCancel>
            <AlertDialogAction 
              onClick={handleDeleteChat}
              disabled={isDeleting || (!deleteFromWhatsApp && !deleteLocal)}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isDeleting ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Deletando...
                </>
              ) : (
                "Deletar"
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Profile picture modal */}
      <Dialog open={showProfilePic} onOpenChange={setShowProfilePic}>
        <DialogContent className="max-w-md p-0 overflow-hidden bg-transparent border-none">
          <div className="flex flex-col items-center gap-4 p-4">
            {conversation.profile_pic_url && (
              <img
                src={conversation.profile_pic_url}
                alt={displayName}
                className="w-72 h-72 rounded-full object-cover shadow-2xl"
              />
            )}
            <span className="text-lg font-semibold text-white drop-shadow-lg">
              {displayName}
            </span>
          </div>
        </DialogContent>
      </Dialog>

      {/* Chat notes - fixed at top (specific to this conversation/chat) */}
      <WhatsAppChatNotes 
        conversationId={conversation.id} 
        chatName={displayName}
      />

      {/* Messages */}
      <ScrollArea className="flex-1 px-4">
        {isLoading ? (
          <WhatsAppMessagesLoading />
        ) : messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-8 text-center">
            <p className="text-sm text-muted-foreground">Nenhuma mensagem ainda</p>
            <p className="text-xs text-muted-foreground mt-1">
              Envie uma mensagem para iniciar a conversa
            </p>
            <Button
              variant="outline"
              size="sm"
              onClick={() => fetchMessagesFromApi(true)}
              disabled={isFetchingFromApi}
              className="mt-4"
            >
              <RefreshCw className={`h-4 w-4 mr-2 ${isFetchingFromApi ? 'animate-spin' : ''}`} />
              Buscar mensagens anteriores
            </Button>
          </div>
        ) : (
          <div className="py-4 space-y-2">
            {messages.map((message) => (
              <div key={message.id} id={`message-${message.id}`} className="transition-all duration-300">
                <WhatsAppMessageBubble 
                  message={message} 
                  allMessages={messages}
                  contactName={displayName}
                  instanceId={instanceId ?? null}
                  companyId={companyId}
                  remoteJid={`${conversation.phone}@s.whatsapp.net`}
                  onOpenAIAssistant={handleOpenAIAssistant}
                  onReply={setReplyToMessage}
                />
              </div>
            ))}
            <div ref={scrollRef} />
          </div>
        )}
      </ScrollArea>

      {/* Input */}
      <WhatsAppMessageInput 
        onSend={handleSend} 
        onSendMedia={handleSendMedia}
        isSending={isSendingMedia}
        quickReplies={quickReplies}
        quickRepliesLoading={quickRepliesLoading}
        replyToMessage={replyToMessage}
        replyToContactName={displayName}
        onCancelReply={() => setReplyToMessage(null)}
      />
      </div>
      </ResizablePanel>

      {/* AI Assistant Panel - show when open or forced */}
      {isAiAssistantVisible && (
        <>
          <ResizableHandle withHandle />
          <ResizablePanel defaultSize={sizes.aiAssistant} minSize={20} maxSize={50}>
            <WhatsAppAIAssistant
              isOpen={isAiAssistantVisible}
              onClose={() => setAiAssistantOpen(false)}
              conversationId={conversation.id}
              companyId={companyId}
              instanceId={instanceId}
              customerMessage={aiSelectedMessage}
              contactName={displayName}
              onUseResponse={handleUseAIResponse}
              forceRealtimeAnalysis={forceRealtimeAnalysis}
              isGroupConversation={isGroupConversation}
              conversationMessages={messages.map((m) => ({
                id: m.id,
                content: m.content || "",
                direction: m.direction === "incoming" ? "inbound" : "outbound",
                created_at: m.sent_at,
                message_type: m.message_type,
                audio_transcription: m.audio_transcription,
                transcription_status: m.transcription_status,
              }))}
            />
          </ResizablePanel>
        </>
      )}

      {/* AI Send Dialog */}
      <WhatsAppAISendDialog
        isOpen={aiSendDialogOpen}
        onClose={() => setAiSendDialogOpen(false)}
        initialMessage={aiSuggestedResponse}
        onSend={handleSendAIResponse}
        isSending={isSendingAiResponse}
      />

      {/* CS Tools Modals */}
      {/* Note modal - always available (per conversation) */}
      <WhatsAppChatNoteModal
        open={noteModalOpen}
        onOpenChange={setNoteModalOpen}
        conversationId={conversation.id}
        chatName={displayName}
      />

      {/* Reminder and Task modals - only when client is linked */}
      {linkedClientId && linkedClientName && (
        <>
          <WhatsAppReminderModal
            open={reminderModalOpen}
            onOpenChange={setReminderModalOpen}
            clientId={linkedClientId}
            clientName={linkedClientName}
          />
          <WhatsAppQuickTaskModal
            open={taskModalOpen}
            onOpenChange={setTaskModalOpen}
            clientId={linkedClientId}
            clientName={linkedClientName}
          />
        </>
      )}
    </ResizablePanelGroup>
  );
}

function formatPhoneNumber(phone: string): string {
  const cleaned = phone.replace(/^55/, "");
  if (cleaned.length === 11) {
    return `(${cleaned.slice(0, 2)}) ${cleaned.slice(2, 7)}-${cleaned.slice(7)}`;
  }
  if (cleaned.length === 10) {
    return `(${cleaned.slice(0, 2)}) ${cleaned.slice(2, 6)}-${cleaned.slice(6)}`;
  }
  return phone;
}

function getInitials(name: string): string {
  if (/^\d+$/.test(name.replace(/[\s\-()]/g, ""))) {
    const digits = name.replace(/\D/g, "");
    return digits.slice(-2);
  }
  const parts = name.trim().split(/\s+/);
  if (parts.length >= 2) {
    return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
  }
  return name.slice(0, 2).toUpperCase();
}

import { useState, useEffect, useMemo } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Loader2, User, Eye, Send, Star, Trash2, Search, UserPlus, Headphones } from "lucide-react";
import { WhatsAppInstance, WhatsAppInstanceUser } from "@/hooks/useWhatsAppInstances";
import { supabase } from "@/integrations/supabase/client";
import { useCompany } from "@/contexts/CompanyContext";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

interface WhatsAppInstanceUsersModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  instance: WhatsAppInstance | null;
  fetchInstanceUsers: (instanceId: string) => Promise<WhatsAppInstanceUser[]>;
  onAssignUser: (data: {
    instance_id: string;
    user_id: string;
    can_view: boolean;
    can_send: boolean;
    is_default: boolean;
    is_attendant: boolean;
  }) => void;
  onRemoveUser: (data: { instance_id: string; user_id: string }) => void;
}

interface CompanyUser {
  user_id: string;
  full_name: string;
  role: string;
  avatar_url: string | null;
}

interface AssignedUserWithProfile extends WhatsAppInstanceUser {
  full_name: string;
  role: string;
  avatar_url: string | null;
  is_attendant: boolean;
}

export function WhatsAppInstanceUsersModal({
  open,
  onOpenChange,
  instance,
  fetchInstanceUsers,
  onAssignUser,
  onRemoveUser,
}: WhatsAppInstanceUsersModalProps) {
  const { activeCompany } = useCompany();
  const [isLoading, setIsLoading] = useState(false);
  const [companyUsers, setCompanyUsers] = useState<CompanyUser[]>([]);
  const [assignedUsers, setAssignedUsers] = useState<AssignedUserWithProfile[]>([]);
  const [comboOpen, setComboOpen] = useState(false);

  useEffect(() => {
    if (open && instance && activeCompany) {
      loadData();
    }
  }, [open, instance, activeCompany]);

  const loadData = async () => {
    if (!instance || !activeCompany) return;

    setIsLoading(true);
    try {
      // Fetch employees (mesma fonte da tela de Colaboradores) ordenados por nome
      const { data: employeesData, error: employeesError } = await supabase
        .from("employees")
        .select("id, user_id, name, role, avatar")
        .eq("company_id", activeCompany.company_id)
        .order("name");

      if (employeesError) throw employeesError;

      const users: CompanyUser[] = employeesData?.map(emp => ({
        user_id: emp.user_id,
        full_name: emp.name || "Colaborador",
        role: emp.role || "member",
        avatar_url: emp.avatar || null,
      })) || [];

      setCompanyUsers(users);

      // Fetch assigned users
      const assigned = await fetchInstanceUsers(instance.id);

      // Merge with employee data
      const assignedWithProfiles: AssignedUserWithProfile[] = assigned.map(a => {
        const employee = users.find(u => u.user_id === a.user_id);
        return {
          ...a,
          full_name: employee?.full_name || "Colaborador",
          role: employee?.role || "member",
          avatar_url: employee?.avatar_url || null,
        };
      });

      setAssignedUsers(assignedWithProfiles);
    } catch (error) {
      console.error("Error loading users:", error);
    } finally {
      setIsLoading(false);
    }
  };

  // Users available to add (not yet assigned)
  const availableUsers = useMemo(() => {
    const assignedIds = new Set(assignedUsers.map(u => u.user_id));
    return companyUsers.filter(u => !assignedIds.has(u.user_id));
  }, [companyUsers, assignedUsers]);

  const handleAddUser = (user: CompanyUser) => {
    if (!instance) return;

    onAssignUser({
      instance_id: instance.id,
      user_id: user.user_id,
      can_view: true,
      can_send: true,
      is_default: false,
      is_attendant: false,
    });

    // Add to local state immediately
    setAssignedUsers(prev => [
      ...prev,
      {
        id: crypto.randomUUID(),
        instance_id: instance.id,
        user_id: user.user_id,
        can_view: true,
        can_send: true,
        is_default: false,
        is_attendant: false,
        created_at: new Date().toISOString(),
        full_name: user.full_name,
        role: user.role,
        avatar_url: user.avatar_url,
      },
    ]);

    setComboOpen(false);
  };

  const handleRemoveUser = (userId: string) => {
    if (!instance) return;

    onRemoveUser({ instance_id: instance.id, user_id: userId });
    setAssignedUsers(prev => prev.filter(u => u.user_id !== userId));
  };

  const handleTogglePermission = (userId: string, permission: 'can_view' | 'can_send' | 'is_default' | 'is_attendant', newValue: boolean) => {
    if (!instance) return;

    const user = assignedUsers.find(u => u.user_id === userId);
    if (!user) return;

    onAssignUser({
      instance_id: instance.id,
      user_id: userId,
      can_view: permission === 'can_view' ? newValue : user.can_view ?? true,
      can_send: permission === 'can_send' ? newValue : user.can_send ?? true,
      is_default: permission === 'is_default' ? newValue : user.is_default ?? false,
      is_attendant: permission === 'is_attendant' ? newValue : user.is_attendant ?? false,
    });

    setAssignedUsers(prev =>
      prev.map(u =>
        u.user_id === userId ? { ...u, [permission]: newValue } : u
      )
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>
            Usuários da Instância: {instance?.instance_name}
          </DialogTitle>
        </DialogHeader>

        {isLoading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
          </div>
        ) : (
          <div className="space-y-4">
            {/* Combobox to add users */}
            <Popover open={comboOpen} onOpenChange={setComboOpen}>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  role="combobox"
                  aria-expanded={comboOpen}
                  className="w-full justify-start gap-2"
                >
                  <UserPlus className="h-4 w-4" />
                  <span className="text-muted-foreground">Adicionar colaborador...</span>
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-[400px] p-0" align="start">
                <Command>
                  <CommandInput placeholder="Pesquisar colaborador..." />
                  <CommandList>
                    <CommandEmpty>Nenhum colaborador disponível</CommandEmpty>
                    <CommandGroup>
                      {availableUsers.map(user => (
                        <CommandItem
                          key={user.user_id}
                          value={user.full_name}
                          onSelect={() => handleAddUser(user)}
                          className="cursor-pointer"
                        >
                          {user.avatar_url ? (
                            <img 
                              src={user.avatar_url} 
                              alt={user.full_name}
                              className="h-6 w-6 rounded-full object-cover mr-2"
                            />
                          ) : (
                            <User className="h-4 w-4 mr-2 text-muted-foreground" />
                          )}
                          <span>{user.full_name}</span>
                          <span className="ml-2 text-xs text-muted-foreground capitalize">
                            ({user.role})
                          </span>
                        </CommandItem>
                      ))}
                    </CommandGroup>
                  </CommandList>
                </Command>
              </PopoverContent>
            </Popover>

            {/* Assigned users list */}
            <div className="space-y-1">
              <Label className="text-xs text-muted-foreground uppercase tracking-wider">
                Usuários com acesso ({assignedUsers.length})
              </Label>

              <ScrollArea className="max-h-[300px]">
                {assignedUsers.length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground text-sm">
                    Nenhum usuário atribuído a esta instância
                  </div>
                ) : (
                  <div className="space-y-2">
                    {assignedUsers.map(user => (
                      <div
                        key={user.user_id}
                        className="p-3 rounded-lg border bg-card"
                      >
                        <div className="flex items-center justify-between mb-3">
                          <div className="flex items-center gap-3">
                            {user.avatar_url ? (
                              <img 
                                src={user.avatar_url} 
                                alt={user.full_name}
                                className="h-9 w-9 rounded-full object-cover"
                              />
                            ) : (
                              <div className="h-9 w-9 rounded-full bg-primary/10 flex items-center justify-center">
                                <User className="h-4 w-4 text-primary" />
                              </div>
                            )}
                            <div>
                              <p className="font-medium text-sm">{user.full_name}</p>
                              <p className="text-xs text-muted-foreground capitalize">{user.role}</p>
                            </div>
                          </div>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
                            onClick={() => handleRemoveUser(user.user_id)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>

                        <div className="flex items-center gap-6 pl-10">
                          <div className="flex items-center gap-2">
                            <Switch
                              id={`view-${user.user_id}`}
                              checked={user.can_view ?? true}
                              onCheckedChange={(checked) => handleTogglePermission(user.user_id, 'can_view', checked)}
                            />
                            <Label htmlFor={`view-${user.user_id}`} className="text-xs flex items-center gap-1 cursor-pointer">
                              <Eye className="h-3 w-3" />
                              Ver
                            </Label>
                          </div>

                          <div className="flex items-center gap-2">
                            <Switch
                              id={`send-${user.user_id}`}
                              checked={user.can_send ?? true}
                              onCheckedChange={(checked) => handleTogglePermission(user.user_id, 'can_send', checked)}
                            />
                            <Label htmlFor={`send-${user.user_id}`} className="text-xs flex items-center gap-1 cursor-pointer">
                              <Send className="h-3 w-3" />
                              Enviar
                            </Label>
                          </div>

                          <div className="flex items-center gap-2">
                            <Switch
                              id={`default-${user.user_id}`}
                              checked={user.is_default ?? false}
                              onCheckedChange={(checked) => handleTogglePermission(user.user_id, 'is_default', checked)}
                            />
                            <Label htmlFor={`default-${user.user_id}`} className="text-xs flex items-center gap-1 cursor-pointer">
                              <Star className="h-3 w-3" />
                              Padrão
                            </Label>
                          </div>

                          <div className="flex items-center gap-2">
                            <Switch
                              id={`attendant-${user.user_id}`}
                              checked={user.is_attendant ?? false}
                              onCheckedChange={(checked) => handleTogglePermission(user.user_id, 'is_attendant', checked)}
                            />
                            <Label htmlFor={`attendant-${user.user_id}`} className="text-xs flex items-center gap-1 cursor-pointer">
                              <Headphones className="h-3 w-3" />
                              Atendente
                            </Label>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </ScrollArea>
            </div>
          </div>
        )}

        <div className="border-t pt-4 mt-2">
          <p className="text-xs text-muted-foreground">
            <strong>Ver:</strong> pode visualizar conversas •{" "}
            <strong>Enviar:</strong> pode enviar mensagens •{" "}
            <strong>Padrão:</strong> instância padrão ao abrir o chat •{" "}
            <strong>Atendente:</strong> métricas atribuídas nos relatórios de CS
          </p>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Fechar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useCallback, useEffect } from "react";
import { Video as VideoIcon, Download, Loader2, X, Play } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogClose } from "@/components/ui/dialog";
import { cn } from "@/lib/utils";
import { downloadAndCacheMedia, hasCachedMedia } from "@/hooks/useWhatsAppMediaCache";

interface WhatsAppVideoViewerProps {
  mediaUrl: string | null;
  messageId: string | null; // external_id (UazapiGO)
  supabaseMessageId: string | null; // Supabase message ID for caching
  instanceId: string | null;
  isOutgoing: boolean;
  cachedMediaUrl?: string | null;
}

export function WhatsAppVideoViewer({
  mediaUrl,
  messageId,
  supabaseMessageId,
  instanceId,
  isOutgoing,
  cachedMediaUrl,
}: WhatsAppVideoViewerProps) {
  const [videoLoaded, setVideoLoaded] = useState(false);
  const [videoSrc, setVideoSrc] = useState<string | null>(null);
  const [thumbnailSrc, setThumbnailSrc] = useState<string | null>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Check if we have cached media on mount
  useEffect(() => {
    if (hasCachedMedia(cachedMediaUrl)) {
      setVideoSrc(cachedMediaUrl!);
      setVideoLoaded(true);
      // Generate thumbnail from cached video
      generateThumbnail(cachedMediaUrl!);
    }
  }, [cachedMediaUrl]);

  // Generate a thumbnail from video
  const generateThumbnail = useCallback((videoUrl: string) => {
    const video = document.createElement("video");
    video.crossOrigin = "anonymous";
    video.preload = "metadata";
    video.src = videoUrl;

    video.onloadeddata = () => {
      video.currentTime = 1; // Seek to 1 second for thumbnail
    };

    video.onseeked = () => {
      try {
        const canvas = document.createElement("canvas");
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext("2d");
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const thumbUrl = canvas.toDataURL("image/jpeg", 0.7);
          setThumbnailSrc(thumbUrl);
        }
      } catch (e) {
      }
    };

    video.onerror = () => {
    };
  }, []);

  const handleDownload = useCallback(async () => {
    if (videoSrc) {
      // Video already loaded, just open modal
      setIsModalOpen(true);
      return;
    }

    if (!instanceId || !messageId) {
      // Try direct URL as fallback
      if (mediaUrl) {
        try {
          const testResponse = await fetch(mediaUrl, { method: "HEAD" }).catch(() => null);
          if (testResponse?.ok) {
            setVideoSrc(mediaUrl);
            setVideoLoaded(true);
            generateThumbnail(mediaUrl);
            return;
          }
        } catch {
          // Continue to error
        }
      }
      setError("Vídeo não disponível");
      return;
    }

    setIsDownloading(true);
    setError(null);

    try {

      const result = await downloadAndCacheMedia({
        instanceId,
        externalMessageId: messageId,
        supabaseMessageId: supabaseMessageId || "",
        fileName: "video.mp4",
        shouldCache: !!supabaseMessageId,
      });

      if (!result) {
        throw new Error("Falha ao baixar vídeo");
      }

      const { blob, cachedUrl } = result;
      let url: string;

      // If we got a cached URL, use it directly. Otherwise create blob URL
      if (cachedUrl) {
        url = cachedUrl;
      } else {
        url = URL.createObjectURL(blob);
      }

      setVideoSrc(url);
      setVideoLoaded(true);
      generateThumbnail(url);
    } catch (err: unknown) {
      console.error("[WhatsAppVideoViewer] Error:", err);
      setError(err.message || "Erro ao carregar vídeo");
    } finally {
      setIsDownloading(false);
    }
  }, [videoSrc, instanceId, messageId, supabaseMessageId, mediaUrl, generateThumbnail]);

  const handleSaveVideo = useCallback(() => {
    if (!videoSrc) return;

    const link = document.createElement("a");
    link.href = videoSrc;
    link.download = `whatsapp_video_${Date.now()}.mp4`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [videoSrc]);

  if (error) {
    return (
      <div className="flex items-center gap-2 p-3 rounded-lg bg-muted/50 text-muted-foreground">
        <VideoIcon className="h-5 w-5" />
        <span className="text-sm">{error}</span>
      </div>
    );
  }

  // Show thumbnail if video is loaded
  if (videoLoaded && videoSrc) {
    return (
      <>
        <div 
          className="relative cursor-pointer group rounded-lg overflow-hidden"
          onClick={() => setIsModalOpen(true)}
        >
          {thumbnailSrc ? (
            <img
              src={thumbnailSrc}
              alt="Preview do vídeo"
              className="max-w-full max-h-60 object-cover"
            />
          ) : (
            <div className={cn(
              "w-full h-40 flex items-center justify-center",
              isOutgoing ? "bg-primary-foreground/10" : "bg-muted/50"
            )}>
              <VideoIcon className="h-12 w-12 text-muted-foreground" />
            </div>
          )}

          {/* Play button overlay */}
          <div className="absolute inset-0 bg-black/30 group-hover:bg-black/40 transition-colors flex items-center justify-center">
            <div className="w-14 h-14 rounded-full bg-black/60 flex items-center justify-center group-hover:scale-110 transition-transform">
              <Play className="h-7 w-7 text-white fill-white ml-1" />
            </div>
          </div>
        </div>

        {/* Modal for video player */}
        <Dialog open={isModalOpen} onOpenChange={setIsModalOpen}>
          <DialogContent className="max-w-[90vw] max-h-[90vh] p-0 overflow-hidden bg-black/95 border-none">
            <DialogClose className="absolute top-4 right-4 z-10 rounded-full bg-black/50 p-2 text-white hover:bg-black/70 transition-colors">
              <X className="h-5 w-5" />
            </DialogClose>

            <div className="relative flex items-center justify-center w-full h-full min-h-[50vh]">
              <video
                src={videoSrc}
                controls
                autoPlay
                className="max-w-full max-h-[85vh] object-contain"
                playsInline
              />
            </div>

            <div className="absolute bottom-4 right-4 z-10">
              <Button
                variant="secondary"
                size="sm"
                onClick={handleSaveVideo}
                className="gap-2"
              >
                <Download className="h-4 w-4" />
                Salvar
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      </>
    );
  }

  // Show placeholder with download button
  return (
    <div 
      className={cn(
        "flex flex-col items-center justify-center p-6 rounded-lg cursor-pointer transition-colors",
        isOutgoing 
          ? "bg-primary-foreground/10 hover:bg-primary-foreground/20" 
          : "bg-muted/50 hover:bg-muted"
      )}
      onClick={handleDownload}
    >
      <div className={cn(
        "w-16 h-16 rounded-full flex items-center justify-center mb-3",
        isOutgoing ? "bg-primary-foreground/20" : "bg-muted"
      )}>
        {isDownloading ? (
          <Loader2 className={cn(
            "h-8 w-8 animate-spin",
            isOutgoing ? "text-primary-foreground" : "text-muted-foreground"
          )} />
        ) : (
          <VideoIcon className={cn(
            "h-8 w-8",
            isOutgoing ? "text-primary-foreground" : "text-muted-foreground"
          )} />
        )}
      </div>

      <span className={cn(
        "text-sm font-medium mb-2",
        isOutgoing ? "text-primary-foreground" : "text-foreground"
      )}>
        Vídeo
      </span>

      <Button
        variant={isOutgoing ? "secondary" : "outline"}
        size="sm"
        disabled={isDownloading}
        className="gap-2"
        onClick={(e) => {
          e.stopPropagation();
          handleDownload();
        }}
      >
        {isDownloading ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" />
            Baixando...
          </>
        ) : (
          <>
            <Download className="h-4 w-4" />
            Baixar vídeo
          </>
        )}
      </Button>
    </div>
  );
}

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { 
  CheckCircle, 
  XCircle, 
  MessageSquare, 
  User, 
  Phone, 
  Building2,
  Loader2 
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

interface NotificationMessage {
  id: string;
  client_name: string | null;
  contact_name: string | null;
  recipient_phone: string;
  message_content: string;
  status: string;
  sent_at: string | null;
  error_message: string | null;
}

interface NotificationDetailsModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  executionLogId: string | null;
  triggerName: string;
}

export function NotificationDetailsModal({
  open,
  onOpenChange,
  executionLogId,
  triggerName,
}: NotificationDetailsModalProps) {
  const [messages, setMessages] = useState<NotificationMessage[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedMessage, setSelectedMessage] = useState<NotificationMessage | null>(null);

  useEffect(() => {
    if (open && executionLogId) {
      fetchMessages();
    }
  }, [open, executionLogId]);

  const fetchMessages = async () => {
    if (!executionLogId) return;

    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("whatsapp_notification_log")
        .select("*")
        .eq("execution_log_id", executionLogId)
        .order("sent_at", { ascending: true });

      if (error) throw error;
      setMessages(data || []);
    } catch (error) {
      console.error("Error fetching messages:", error);
    } finally {
      setLoading(false);
    }
  };

  const sentCount = messages.filter(m => m.status === 'sent').length;
  const failedCount = messages.filter(m => m.status !== 'sent').length;

  // Group messages by client
  const messagesByClient = messages.reduce((acc, msg) => {
    const clientName = msg.client_name || 'Sem cliente';
    if (!acc[clientName]) {
      acc[clientName] = [];
    }
    acc[clientName].push(msg);
    return acc;
  }, {} as Record<string, NotificationMessage[]>);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <MessageSquare className="h-5 w-5" />
            Detalhes da Execução: {triggerName}
          </DialogTitle>
        </DialogHeader>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        ) : messages.length === 0 ? (
          <div className="text-center py-12">
            <MessageSquare className="h-12 w-12 mx-auto text-muted-foreground mb-3" />
            <p className="text-muted-foreground">Nenhuma mensagem encontrada para esta execução</p>
            <p className="text-sm text-muted-foreground mt-1">
              As mensagens enviadas após esta atualização aparecerão aqui
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {/* Summary */}
            <div className="flex items-center gap-4 p-3 rounded-lg bg-muted/50">
              <div className="flex items-center gap-2">
                <CheckCircle className="h-4 w-4 text-green-500" />
                <span className="text-sm">
                  <strong className="text-green-500">{sentCount}</strong> enviadas
                </span>
              </div>
              <div className="flex items-center gap-2">
                <XCircle className="h-4 w-4 text-red-500" />
                <span className="text-sm">
                  <strong className="text-red-500">{failedCount}</strong> falhas
                </span>
              </div>
              <div className="flex items-center gap-2">
                <Building2 className="h-4 w-4 text-muted-foreground" />
                <span className="text-sm">
                  <strong>{Object.keys(messagesByClient).length}</strong> clientes
                </span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4 h-[500px]">
              {/* Messages List */}
              <div className="border rounded-lg">
                <div className="p-3 border-b bg-muted/30">
                  <h4 className="font-medium text-sm">Mensagens Enviadas</h4>
                </div>
                <ScrollArea className="h-[450px]">
                  <div className="p-2 space-y-1">
                    {Object.entries(messagesByClient).map(([clientName, clientMessages]) => (
                      <div key={clientName} className="mb-3">
                        <div className="px-2 py-1 text-xs font-medium text-muted-foreground flex items-center gap-1">
                          <Building2 className="h-3 w-3" />
                          {clientName}
                        </div>
                        {clientMessages.map((msg) => (
                          <button
                            key={msg.id}
                            onClick={() => setSelectedMessage(msg)}
                            className={`w-full text-left p-3 rounded-lg transition-colors ${
                              selectedMessage?.id === msg.id
                                ? "bg-primary/10 border border-primary/20"
                                : "hover:bg-muted/50"
                            }`}
                          >
                            <div className="flex items-center justify-between mb-1">
                              <div className="flex items-center gap-2">
                                <User className="h-3 w-3 text-muted-foreground" />
                                <span className="text-sm font-medium">
                                  {msg.contact_name || 'Contato'}
                                </span>
                              </div>
                              <Badge 
                                variant="secondary" 
                                className={msg.status === 'sent' 
                                  ? "bg-green-500/10 text-green-500" 
                                  : "bg-red-500/10 text-red-500"
                                }
                              >
                                {msg.status === 'sent' ? (
                                  <><CheckCircle className="h-3 w-3 mr-1" /> Enviada</>
                                ) : (
                                  <><XCircle className="h-3 w-3 mr-1" /> Falha</>
                                )}
                              </Badge>
                            </div>
                            <div className="flex items-center gap-2 text-xs text-muted-foreground">
                              <Phone className="h-3 w-3" />
                              {msg.recipient_phone}
                            </div>
                            {msg.sent_at && (
                              <div className="text-xs text-muted-foreground mt-1">
                                {format(new Date(msg.sent_at), "dd/MM HH:mm", { locale: ptBR })}
                              </div>
                            )}
                          </button>
                        ))}
                      </div>
                    ))}
                  </div>
                </ScrollArea>
              </div>

              {/* Message Content */}
              <div className="border rounded-lg">
                <div className="p-3 border-b bg-muted/30">
                  <h4 className="font-medium text-sm">Conteúdo da Mensagem</h4>
                </div>
                <ScrollArea className="h-[450px]">
                  {selectedMessage ? (
                    <div className="p-4 space-y-4">
                      <div className="space-y-2">
                        <div className="flex items-center gap-2 text-sm">
                          <User className="h-4 w-4 text-muted-foreground" />
                          <span className="text-muted-foreground">Contato:</span>
                          <span className="font-medium">{selectedMessage.contact_name || '-'}</span>
                        </div>
                        <div className="flex items-center gap-2 text-sm">
                          <Building2 className="h-4 w-4 text-muted-foreground" />
                          <span className="text-muted-foreground">Cliente:</span>
                          <span className="font-medium">{selectedMessage.client_name || '-'}</span>
                        </div>
                        <div className="flex items-center gap-2 text-sm">
                          <Phone className="h-4 w-4 text-muted-foreground" />
                          <span className="text-muted-foreground">Telefone:</span>
                          <span className="font-medium">{selectedMessage.recipient_phone}</span>
                        </div>
                      </div>

                      <Separator />

                      <div>
                        <p className="text-sm text-muted-foreground mb-2">Mensagem:</p>
                        <div className="p-3 rounded-lg bg-muted/30 whitespace-pre-wrap text-sm">
                          {selectedMessage.message_content}
                        </div>
                      </div>

                      {selectedMessage.error_message && (
                        <>
                          <Separator />
                          <div>
                            <p className="text-sm text-red-500 mb-2">Erro:</p>
                            <div className="p-3 rounded-lg bg-red-500/10 text-sm text-red-500">
                              {selectedMessage.error_message}
                            </div>
                          </div>
                        </>
                      )}
                    </div>
                  ) : (
                    <div className="flex items-center justify-center h-full text-muted-foreground text-sm">
                      Selecione uma mensagem para ver o conteúdo
                    </div>
                  )}
                </ScrollArea>
              </div>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

