import { useEffect, useState, useCallback } from "react";
import { useCreateBlockNote } from "@blocknote/react";
import { BlockNoteView } from "@blocknote/mantine";
import "@blocknote/mantine/style.css";
import { Star, StarOff, Share2, MoreHorizontal } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useWorkspaceDocuments } from "@/hooks/useWorkspaceDocuments";
import { WorkspaceShareDialog } from "./WorkspaceShareDialog";
import type { WorkspaceDocument } from "@/types/workspace";

interface WorkspaceEditorProps {
  document: WorkspaceDocument | null;
}

const EMOJI_OPTIONS = ['📄', '📝', '📋', '📌', '💡', '🎯', '🚀', '✨', '📊', '📈', '🔖', '📂'];

export function WorkspaceEditor({ document }: WorkspaceEditorProps) {
  const { updateDocument, toggleFavorite } = useWorkspaceDocuments();
  const [title, setTitle] = useState(document?.title || '');
  const [shareOpen, setShareOpen] = useState(false);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);

  // Create editor with initial content
  const editor = useCreateBlockNote({
    initialContent: document?.content?.length > 0 ? document.content : undefined,
  });

  // Update editor content when document changes
  useEffect(() => {
    if (document && editor) {
      setTitle(document.title);
      if (document.content && document.content.length > 0) {
        editor.replaceBlocks(editor.document, document.content);
      } else {
        editor.replaceBlocks(editor.document, []);
      }
    }
  }, [document?.id]);

  // Debounced save for content changes
  const saveContent = useCallback(async () => {
    if (!document) return;
    const content = editor.document;
    await updateDocument.mutateAsync({ id: document.id, content });
  }, [document, editor, updateDocument]);

  // Save title on blur
  const handleTitleBlur = async () => {
    if (!document || title === document.title) return;
    await updateDocument.mutateAsync({ id: document.id, title: title || 'Sem título' });
  };

  // Handle icon change
  const handleIconChange = async (icon: string) => {
    if (!document) return;
    await updateDocument.mutateAsync({ id: document.id, icon });
    setShowEmojiPicker(false);
  };

  // Handle favorite toggle
  const handleToggleFavorite = () => {
    if (!document) return;
    toggleFavorite.mutate({ id: document.id, isFavorite: !document.is_favorite });
  };

  if (!document) {
    return (
      <div className="h-full flex items-center justify-center bg-background">
        <div className="text-center text-muted-foreground">
          <p className="text-lg">Selecione um documento</p>
          <p className="text-sm mt-1">ou crie um novo para começar</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-background">
      {/* Document Header */}
      <div className="border-b px-6 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3 flex-1">
          {/* Icon with picker */}
          <div className="relative">
            <button
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
              className="text-2xl hover:bg-muted p-1 rounded"
            >
              {document.icon}
            </button>
            {showEmojiPicker && (
              <div className="absolute top-full left-0 mt-1 bg-popover border rounded-md shadow-lg p-2 z-50 grid grid-cols-6 gap-1">
                {EMOJI_OPTIONS.map(emoji => (
                  <button
                    key={emoji}
                    onClick={() => handleIconChange(emoji)}
                    className="text-xl p-1 hover:bg-muted rounded"
                  >
                    {emoji}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Title */}
          <Input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            onBlur={handleTitleBlur}
            placeholder="Sem título"
            className="text-xl font-semibold border-none shadow-none focus-visible:ring-0 px-0 h-auto"
          />
        </div>

        {/* Actions */}
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon"
            onClick={handleToggleFavorite}
            className="h-8 w-8"
          >
            {document.is_favorite ? (
              <Star className="h-4 w-4 text-yellow-500 fill-current" />
            ) : (
              <StarOff className="h-4 w-4" />
            )}
          </Button>

          <Button
            variant="ghost"
            size="icon"
            onClick={() => setShareOpen(true)}
            className="h-8 w-8"
          >
            <Share2 className="h-4 w-4" />
          </Button>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="icon" className="h-8 w-8">
                <MoreHorizontal className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onClick={() => setShareOpen(true)}>
                <Share2 className="h-4 w-4 mr-2" />
                Compartilhar
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* Editor */}
      <div className="flex-1 overflow-auto">
        <div className="w-full h-full py-4 px-6">
          <BlockNoteView 
            editor={editor} 
            onChange={saveContent}
            theme="light"
          />
        </div>
      </div>

      {/* Share Dialog */}
      <WorkspaceShareDialog
        open={shareOpen}
        onOpenChange={setShareOpen}
        resourceType="document"
        resourceId={document.id}
        resourceName={document.title}
      />
    </div>
  );
}

import { useEffect, useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Progress } from "@/components/ui/progress";
import { Loader2, CheckCircle2, AlertCircle } from "lucide-react";
import { cn } from "@/lib/utils";

interface GenerateThumbnailModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  generating: boolean;
  error?: string | null;
}

interface Step {
  id: string;
  label: string;
  status: 'pending' | 'processing' | 'done' | 'error';
}

export function GenerateThumbnailModal({
  open,
  onOpenChange,
  generating,
  error,
}: GenerateThumbnailModalProps) {
  const [steps, setSteps] = useState<Step[]>([
    { id: 'collect', label: 'Coletando informações do roteiro', status: 'pending' },
    { id: 'analyze', label: 'Analisando fotos do modelo', status: 'pending' },
    { id: 'references', label: 'Processando referências visuais', status: 'pending' },
    { id: 'generate', label: 'Gerando imagem com IA', status: 'pending' },
  ]);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    if (!generating) {
      if (error) {
        setSteps(prev => prev.map(s => 
          s.status === 'processing' ? { ...s, status: 'error' } : s
        ));
      }
      return;
    }

    // Simulate progress through steps
    const stepDuration = 2000;
    let currentStep = 0;

    const interval = setInterval(() => {
      if (currentStep < steps.length) {
        setSteps(prev => prev.map((s, i) => {
          if (i < currentStep) return { ...s, status: 'done' };
          if (i === currentStep) return { ...s, status: 'processing' };
          return s;
        }));
        setProgress(((currentStep + 1) / steps.length) * 100);
        currentStep++;
      }
    }, stepDuration);

    return () => clearInterval(interval);
  }, [generating, error]);

  // Reset when modal opens
  useEffect(() => {
    if (open) {
      setSteps([
        { id: 'collect', label: 'Coletando informações do roteiro', status: 'pending' },
        { id: 'analyze', label: 'Analisando fotos do modelo', status: 'pending' },
        { id: 'references', label: 'Processando referências visuais', status: 'pending' },
        { id: 'generate', label: 'Gerando imagem com IA', status: 'pending' },
      ]);
      setProgress(0);
    }
  }, [open]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-center">
            {error ? 'Erro ao gerar thumbnail' : 'Gerando Thumbnail...'}
          </DialogTitle>
        </DialogHeader>

        <div className="py-6 space-y-6">
          {/* Steps */}
          <div className="space-y-3">
            {steps.map((step) => (
              <div
                key={step.id}
                className={cn(
                  "flex items-center gap-3 text-sm",
                  step.status === 'pending' && "text-muted-foreground",
                  step.status === 'processing' && "text-primary font-medium",
                  step.status === 'done' && "text-green-600 dark:text-green-400",
                  step.status === 'error' && "text-destructive"
                )}
              >
                {step.status === 'pending' && (
                  <div className="h-5 w-5 rounded-full border-2 border-muted" />
                )}
                {step.status === 'processing' && (
                  <Loader2 className="h-5 w-5 animate-spin" />
                )}
                {step.status === 'done' && (
                  <CheckCircle2 className="h-5 w-5" />
                )}
                {step.status === 'error' && (
                  <AlertCircle className="h-5 w-5" />
                )}
                <span>{step.label}</span>
              </div>
            ))}
          </div>

          {/* Progress bar */}
          {!error && (
            <div className="space-y-2">
              <Progress value={progress} className="h-2" />
              <p className="text-xs text-center text-muted-foreground">
                {Math.round(progress)}% concluído
              </p>
            </div>
          )}

          {/* Error message */}
          {error && (
            <div className="p-3 bg-destructive/10 border border-destructive/20 rounded-lg">
              <p className="text-sm text-destructive">{error}</p>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useRef } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { YouTubeScript, ScriptMessage } from "@/hooks/useYouTubeScripts";
import { ThumbnailConfig } from "@/hooks/useYouTubeThumbnails";
import {
  ResizablePanelGroup,
  ResizablePanel,
  ResizableHandle,
} from "@/components/ui/resizable";
import {
  ArrowLeft,
  Save,
  Send,
  Loader2,
  Copy,
  Check,
  Image,
  Pencil,
  RefreshCw,
  FileText,
  Sparkles,
} from "lucide-react";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import ReactMarkdown from "react-markdown";
import { GenerateThumbnailModal } from "./GenerateThumbnailModal";
import { ImageEditorModal } from "@/components/image-editor/ImageEditorModal";
import { SlidesSection } from "./SlidesSection";
import { useScriptBuilderPanelSizes } from "@/hooks/useScriptBuilderPanelSizes";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";

interface YouTubeScriptBuilderProps {
  script: YouTubeScript;
  onClose: () => void;
  onUpdate: (updates: Partial<YouTubeScript>) => Promise<void>;
  onSendMessage: (message: string) => Promise<unknown>;
  onGenerateTitles: (style: string) => Promise<unknown>;
  fetchMessages: () => Promise<ScriptMessage[]>;
  onGenerateThumbnail: (
    scriptId: string,
    title: string,
    scriptContent: string,
    suggestedTitles: string[]
  ) => Promise<string | null>;
  generatingThumbnail: boolean;
  thumbnailConfig: ThumbnailConfig | null;
  clientId: string;
  companyId: string;
}

export function YouTubeScriptBuilder({
  script,
  onClose,
  onUpdate,
  onSendMessage,
  onGenerateTitles,
  fetchMessages,
  onGenerateThumbnail,
  generatingThumbnail,
  thumbnailConfig,
  clientId,
  companyId,
}: YouTubeScriptBuilderProps) {
  const [content, setContent] = useState(script.script_content);
  const [title, setTitle] = useState(script.title);
  const [thumbnailUrl, setThumbnailUrl] = useState(script.thumbnail_url || null);
  const [messages, setMessages] = useState<ScriptMessage[]>([]);
  const [chatInput, setChatInput] = useState("");
  const [sending, setSending] = useState(false);
  const [saving, setSaving] = useState(false);
  const [copied, setCopied] = useState(false);
  const [generatingTitles, setGeneratingTitles] = useState(false);
  const [activeTab, setActiveTab] = useState<"edit" | "preview">("edit");
  const [showThumbnailModal, setShowThumbnailModal] = useState(false);
  const [thumbnailError, setThumbnailError] = useState<string | null>(null);
  const [showImageEditor, setShowImageEditor] = useState(false);
  const [imageToEdit, setImageToEdit] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const [videoDescription, setVideoDescription] = useState(script.video_description || "");
  const [generatingDescription, setGeneratingDescription] = useState(false);
  const [descriptionCopied, setDescriptionCopied] = useState(false);
  const [seoTips, setSeoTips] = useState<string[]>([]);
  const { toast } = useToast();

  const {
    sizes,
    isLoaded,
    setHorizontalSizes,
    setLeftColumnSizes,
    setRightColumnSizes,
  } = useScriptBuilderPanelSizes();

  useEffect(() => {
    loadMessages();
  }, [script.id]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const loadMessages = async () => {
    const msgs = await fetchMessages();
    setMessages(msgs);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await onUpdate({
        title,
        script_content: content,
        video_description: videoDescription,
      } as unknown);
    } finally {
      setSaving(false);
    }
  };

  const handleGenerateDescription = async () => {
    setGeneratingDescription(true);
    setSeoTips([]);
    try {
      const { data, error } = await supabase.functions.invoke('generate-youtube-description', {
        body: { scriptId: script.id },
      });

      if (error) throw error;
      if (!data?.success) throw new Error(data?.error || 'Failed to generate description');

      setVideoDescription(data.description);
      setSeoTips(data.seo_tips || []);

      toast({
        title: 'Descrição gerada!',
        description: 'Descrição SEO criada com sucesso.',
      });
    } catch (error: unknown) {
      console.error('Error generating description:', error);
      toast({
        title: 'Erro ao gerar descrição',
        description: error.message,
        variant: 'destructive',
      });
    } finally {
      setGeneratingDescription(false);
    }
  };

  const handleCopyDescription = async () => {
    await navigator.clipboard.writeText(videoDescription);
    setDescriptionCopied(true);
    setTimeout(() => setDescriptionCopied(false), 2000);
  };

  const handleSendMessage = async () => {
    if (!chatInput.trim() || sending) return;

    const userMessage = chatInput;
    setChatInput("");
    setSending(true);

    setMessages((prev) => [
      ...prev,
      {
        id: `temp-${Date.now()}`,
        script_id: script.id,
        role: "user",
        content: userMessage,
        created_at: new Date().toISOString(),
      },
    ]);

    try {
      const result = await onSendMessage(userMessage);
      if (result?.response) {
        setMessages((prev) => [
          ...prev.filter((m) => !m.id.startsWith("temp-")),
          {
            id: `temp-user-${Date.now()}`,
            script_id: script.id,
            role: "user",
            content: userMessage,
            created_at: new Date().toISOString(),
          },
          {
            id: `temp-assistant-${Date.now()}`,
            script_id: script.id,
            role: "assistant",
            content: result.response,
            created_at: new Date().toISOString(),
          },
        ]);
      }
    } finally {
      setSending(false);
    }
  };

  const handleCopy = async () => {
    await navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleGenerateTitles = async (style: string) => {
    setGeneratingTitles(true);
    try {
      await onGenerateTitles(style);
    } finally {
      setGeneratingTitles(false);
    }
  };

  const handleSelectTitle = (newTitle: string) => {
    setTitle(newTitle);
  };

  const handleGenerateThumbnail = async () => {
    setThumbnailError(null);
    setShowThumbnailModal(true);

    try {
      const imageUrl = await onGenerateThumbnail(
        script.id,
        title,
        content,
        script.suggested_titles
      );


      if (imageUrl) {
        setThumbnailUrl(imageUrl);
        setShowThumbnailModal(false);
        setImageToEdit(imageUrl);
        setTimeout(() => {
          setShowImageEditor(true);
        }, 100);
      } else {
        setThumbnailError("Não foi possível gerar a thumbnail");
      }
    } catch (error: unknown) {
      console.error('Thumbnail generation error:', error);
      setThumbnailError(error.message || "Erro desconhecido");
    }
  };

  const handleGenerateThumbnailForSlides = async (): Promise<string | null> => {
    try {
      const imageUrl = await onGenerateThumbnail(
        script.id,
        title,
        content,
        script.suggested_titles
      );

      if (imageUrl) {
        setThumbnailUrl(imageUrl);
        return imageUrl;
      }
      return null;
    } catch (error: unknown) {
      console.error('Thumbnail generation error:', error);
      return null;
    }
  };

  const handleEditThumbnail = () => {
    if (thumbnailUrl) {
      setImageToEdit(thumbnailUrl);
      setShowImageEditor(true);
    }
  };

  const handleImageEditorSave = async (newImages: string[]) => {
    if (newImages.length > 0) {
      const newUrl = newImages[0];
      await onUpdate({ thumbnail_url: newUrl });
      setThumbnailUrl(newUrl);
    }
    setShowImageEditor(false);
    setImageToEdit(null);
  };

  if (!isLoaded) {
    return (
      <div className="min-h-[calc(100vh-8rem)] flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={onClose}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <Input
