import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { supabase } from '@/integrations/supabase/client';

interface CRMUser {
  id: string;
  email: string;
  full_name: string;
  workspace_id: string;
  role: 'admin' | 'collaborator';
}

interface CRMAuthContextType {
  user: CRMUser | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (workspaceToken: string, email: string, password: string) => Promise<{ error?: string }>;
  logout: () => void;
  checkAuth: (workspaceToken: string) => boolean;
}

const CRMAuthContext = createContext<CRMAuthContextType | null>(null);

const CRM_SESSION_KEY = 'crm_session';

export function CRMAuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<CRMUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Verificar se existe sessão salva no localStorage
    const savedSession = localStorage.getItem(CRM_SESSION_KEY);
    if (savedSession) {
      try {
        const session = JSON.parse(savedSession);
        setUser(session.user);
      } catch (error) {
        console.error('Erro ao carregar sessão do CRM:', error);
        localStorage.removeItem(CRM_SESSION_KEY);
      }
    }
    setIsLoading(false);
  }, []);

  const login = async (workspaceToken: string, email: string, password: string) => {
    try {
      const { data, error } = await supabase.functions.invoke('crm-auth', {
        body: {
          workspaceToken,
          email,
          password,
          action: 'login',
        },
      });

      if (error) throw error;

      if (data.error) {
        return { error: data.error };
      }

      if (data.success && data.user) {
        const sessionData = {
          user: data.user,
          session: data.session,
          timestamp: new Date().toISOString(),
        };
        localStorage.setItem(CRM_SESSION_KEY, JSON.stringify(sessionData));
        setUser(data.user);
        return {};
      }

      return { error: 'Falha na autenticação' };
    } catch (error: unknown) {
      console.error('Erro no login CRM:', error);
      return { error: error.message || 'Erro ao fazer login' };
    }
  };

  const logout = () => {
    localStorage.removeItem(CRM_SESSION_KEY);
    setUser(null);
  };

  const checkAuth = (workspaceToken: string): boolean => {
    const savedSession = localStorage.getItem(CRM_SESSION_KEY);
    if (!savedSession) return false;

    try {
      const session = JSON.parse(savedSession);
      // Verificar se a sessão é para o workspace correto
      return session.user.workspace_id === workspaceToken;
    } catch {
      return false;
    }
  };

  return (
    <CRMAuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        isLoading,
        login,
        logout,
        checkAuth,
      }}
    >
      {children}
    </CRMAuthContext.Provider>
  );
}

export function useCRMAuth() {
  const context = useContext(CRMAuthContext);
  if (!context) {
    throw new Error('useCRMAuth must be used within CRMAuthProvider');
  }
  return context;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useCompany } from '@/contexts/CompanyContext';

interface Team {
  id: string;
  name: string;
  color: string | null;
}

interface CSSquadFilterContextType {
  selectedSquadId: string | null; // null = todos
  setSelectedSquadId: (id: string | null) => void;
  squads: Team[];
  isLoading: boolean;
  mySquadId: string | null; // squad do usuário logado
  mySquadName: string | null;
}

const CSSquadFilterContext = createContext<CSSquadFilterContextType | undefined>(undefined);

const STORAGE_KEY = 'cs-squad-filter';
const STORAGE_INITIALIZED_KEY = 'cs-squad-filter-initialized';

export function CSSquadFilterProvider({ children }: { children: ReactNode }) {
  const { activeCompany } = useCompany();

  // Estado inicial do localStorage
  const [selectedSquadId, setSelectedSquadIdState] = useState<string | null>(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem(STORAGE_KEY);
      return stored ? JSON.parse(stored) : null;
    }
    return null;
  });

  const [hasInitialized, setHasInitialized] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem(STORAGE_INITIALIZED_KEY) === 'true';
    }
    return false;
  });

  // Buscar todos os squads da empresa
  const { data: squads = [], isLoading: isLoadingSquads } = useQuery({
    queryKey: ['cs-squads', activeCompany?.company_id],
    queryFn: async () => {
      if (!activeCompany?.company_id) return [];

      const { data, error } = await supabase
        .from('teams')
        .select('id, name, color')
        .eq('company_id', activeCompany.company_id)
        .order('name');

      if (error) throw error;
      return data as Team[];
    },
    enabled: !!activeCompany?.company_id,
  });

  // Buscar squad do usuário logado (via employees e session do supabase)
  const { data: mySquadData } = useQuery({
    queryKey: ['my-squad', activeCompany?.company_id],
    queryFn: async () => {
      if (!activeCompany?.company_id) return null;

      // Obter usuário logado via supabase auth
      const { data: { user } } = await supabase.auth.getUser();
      if (!user?.id) return null;

      const { data: employee } = await supabase
        .from('employees')
        .select('team_id')
        .eq('user_id', user.id)
        .eq('company_id', activeCompany.company_id)
        .maybeSingle();

      if (!employee?.team_id) return null;

      const { data: team } = await supabase
        .from('teams')
        .select('id, name')
        .eq('id', employee.team_id)
        .single();

      return team;
    },
    enabled: !!activeCompany?.company_id,
  });

  // Setar "Meu Squad" como default na primeira visita (se o usuário tiver squad)
  useEffect(() => {
    if (!hasInitialized && mySquadData?.id) {
      setSelectedSquadIdState(mySquadData.id);
      setHasInitialized(true);
      localStorage.setItem(STORAGE_INITIALIZED_KEY, 'true');
    }
  }, [mySquadData, hasInitialized]);

  // Persistir no localStorage
  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(selectedSquadId));
    }
  }, [selectedSquadId]);

  const setSelectedSquadId = (id: string | null) => {
    setSelectedSquadIdState(id);
  };

  return (
    <CSSquadFilterContext.Provider
      value={{
        selectedSquadId,
        setSelectedSquadId,
        squads,
        isLoading: isLoadingSquads,
        mySquadId: mySquadData?.id || null,
        mySquadName: mySquadData?.name || null,
      }}
    >
      {children}
    </CSSquadFilterContext.Provider>
  );
}

export function useCSSquadFilter() {
  const context = useContext(CSSquadFilterContext);
  if (context === undefined) {
    throw new Error('useCSSquadFilter must be used within a CSSquadFilterProvider');
  }
  return context;
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { useCompanies, CompanyMember } from '@/hooks/useCompanies';
import { useAuth } from '@/hooks/useAuth';

interface CompanyContextType {
  activeCompany: CompanyMember | null;
  setActiveCompany: (company: CompanyMember | null) => void;
  companies: CompanyMember[];
  loading: boolean;
  error: string | null;
  createCompany: (companyData: { name: string; slug?: string; logo?: string }) => Promise<unknown>;
  updateCompany: (id: string, updates: unknown) => Promise<unknown>;
  refreshCompanies: () => Promise<void>;
}

const CompanyContext = createContext<CompanyContextType | undefined>(undefined);

export const CompanyProvider = ({ children }: { children: ReactNode }) => {
  const [activeCompany, setActiveCompanyState] = useState<CompanyMember | null>(null);
  const { companies, loading, error, createCompany, updateCompany, fetchUserCompanies } = useCompanies();
  const { user } = useAuth();

  // Set the first company as active by default
  useEffect(() => {
    if (companies.length > 0 && !activeCompany) {
      const savedCompanyId = localStorage.getItem('activeCompanyId');
      if (savedCompanyId) {
        const savedCompany = companies.find(c => c.company_id === savedCompanyId);
        if (savedCompany) {
          setActiveCompanyState(savedCompany);
          return;
        }
      }
      // Default to first company if no saved preference
      setActiveCompanyState(companies[0]);
    }
  }, [companies]); // Fixed: Use companies array as dependency to respect manual selections

  const setActiveCompany = (company: CompanyMember | null) => {
    setActiveCompanyState(company);
    if (company) {
      localStorage.setItem('activeCompanyId', company.company_id);
    } else {
      localStorage.removeItem('activeCompanyId');
    }
  };

  const refreshCompanies = async () => {
    await fetchUserCompanies();
  };

  return (
    <CompanyContext.Provider
      value={{
        activeCompany,
        setActiveCompany,
        companies,
        loading,
        error,
        createCompany,
        updateCompany,
        refreshCompanies,
      }}
    >
      {children}
    </CompanyContext.Provider>
  );
};

export const useCompany = () => {
  const context = useContext(CompanyContext);
  if (context === undefined) {
    throw new Error('useCompany must be used within a CompanyProvider');
  }
  return context;
};

import { createContext, useContext, useState, useCallback, ReactNode } from "react";

interface SyncingItemsContextType {
  syncingItems: Set<string>;
  addSyncingItem: (id: string) => void;
  removeSyncingItem: (id: string) => void;
  isSyncing: (id: string) => boolean;
}

const SyncingItemsContext = createContext<SyncingItemsContextType | undefined>(undefined);

export function SyncingItemsProvider({ children }: { children: ReactNode }) {
  const [syncingItems, setSyncingItems] = useState<Set<string>>(new Set());

  const addSyncingItem = useCallback((id: string) => {
    setSyncingItems((prev) => {
      const next = new Set(prev);
      next.add(id);
      return next;
    });
  }, []);

  const removeSyncingItem = useCallback((id: string) => {
    setSyncingItems((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  }, []);

  const isSyncing = useCallback((id: string) => {
    return syncingItems.has(id);
  }, [syncingItems]);

  return (
    <SyncingItemsContext.Provider value={{ syncingItems, addSyncingItem, removeSyncingItem, isSyncing }}>
      {children}
    </SyncingItemsContext.Provider>
  );
}

export function useSyncingItems() {
  const context = useContext(SyncingItemsContext);
  if (context === undefined) {
    throw new Error("useSyncingItems must be used within a SyncingItemsProvider");
  }
  return context;
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useCompany } from "@/contexts/CompanyContext";
import { useToast } from "@/hooks/use-toast";

interface Conversation {
  id: string;
  client_id: string;
  company_id: string;
  user_id: string;
  title: string;
  created_at: string;
  updated_at: string;
  client_name?: string;
}

interface Message {
  id: string;
  conversation_id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  created_at: string;
}

export function useAIChat() {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [currentConversation, setCurrentConversation] = useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(false);

  const { user } = useAuth();
  const { activeCompany } = useCompany();
  const { toast } = useToast();

  // Fetch conversations
  const fetchConversations = async () => {
    if (!user || !activeCompany) return;

    try {
      const { data, error } = await supabase
        .from('ai_chat_conversations')
        .select(`
          id,
          client_id,
          company_id,
          user_id,
          title,
          created_at,
          updated_at,
          clients(name)
        `)
        .eq('company_id', activeCompany.company_id)
        .order('updated_at', { ascending: false });

      if (error) {
        console.error('Error fetching conversations with clients:', error);
        throw error;
      }

      // Transform data to include client_name
      const conversationsWithClientNames = data?.map((conv: unknown) => ({
        ...conv,
        client_name: conv.clients?.name || 'Cliente não encontrado'
      })) || [];

      setConversations(conversationsWithClientNames);
    } catch (error) {
      console.error('Error fetching conversations:', error);
      toast({
        title: "Erro ao carregar conversas",
        description: "Não foi possível carregar as conversas.",
        variant: "destructive",
      });
    }
  };

  // Fetch messages for a conversation
  const fetchMessages = async (conversationId: string) => {
    try {
      const { data, error } = await supabase
        .from('ai_chat_messages')
        .select('*')
        .eq('conversation_id', conversationId)
        .order('created_at', { ascending: true });

      if (error) throw error;
      setMessages((data || []) as Message[]);
    } catch (error) {
      console.error('Error fetching messages:', error);
      toast({
        title: "Erro ao carregar mensagens",
        description: "Não foi possível carregar as mensagens.",
        variant: "destructive",
      });
    }
  };

  // Create new conversation
  const createConversation = async (clientId: string) => {
    if (!user || !activeCompany) return;

    try {
      const { data, error } = await supabase
        .from('ai_chat_conversations')
        .insert({
          client_id: clientId,
          company_id: activeCompany.company_id,
          user_id: user.id,
          title: 'Nova conversa'
        })
        .select()
        .single();

      if (error) throw error;

      setCurrentConversation(data);
      setMessages([]);
      await fetchConversations();

      toast({
        title: "Nova conversa criada",
        description: "Você pode começar a conversar com a IA agora.",
      });
    } catch (error) {
      console.error('Error creating conversation:', error);
      toast({
        title: "Erro ao criar conversa",
        description: "Não foi possível criar uma nova conversa.",
        variant: "destructive",
      });
    }
  };

  // Send message
  const sendMessage = async (message: string) => {
    if (!currentConversation || !activeCompany) return;

    setLoading(true);
    try {
      // Call the Edge Function
      const { data, error } = await supabase.functions.invoke('ai-chat', {
        body: {
          conversationId: currentConversation.id,
          message,
          clientId: currentConversation.client_id,
          companyId: activeCompany.company_id
        }
      });

      if (error) throw error;

      if (!data.success) {
        throw new Error(data.error || 'Erro desconhecido');
      }

      // Refresh messages
      await fetchMessages(currentConversation.id);
      await fetchConversations(); // Update conversations list to reflect updated_at

    } catch (error) {
      console.error('Error sending message:', error);
      toast({
        title: "Erro ao enviar mensagem",
        description: "Não foi possível enviar a mensagem. Tente novamente.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  // Load conversation
  const loadConversation = async (conversationId: string) => {
    const conversation = conversations.find(c => c.id === conversationId);
    if (conversation) {
      setCurrentConversation(conversation);
      await fetchMessages(conversationId);
      return conversation.client_id; // Return client_id for syncing
    }
    return null;
  };

  // Delete conversation
  const deleteConversation = async (conversationId: string) => {
    try {
      const { error } = await supabase
        .from('ai_chat_conversations')
        .delete()
        .eq('id', conversationId);

      if (error) throw error;

      setConversations(prev => prev.filter(c => c.id !== conversationId));

      if (currentConversation?.id === conversationId) {
        setCurrentConversation(null);
        setMessages([]);
      }

      toast({
        title: "Conversa excluída",
        description: "A conversa foi excluída com sucesso.",
      });
    } catch (error) {
      console.error('Error deleting conversation:', error);
      toast({
        title: "Erro ao excluir conversa",
        description: "Não foi possível excluir a conversa.",
        variant: "destructive",
      });
    }
  };

  // Load conversations on mount
  useEffect(() => {
    fetchConversations();
  }, [user, activeCompany]);

  return {
    conversations,
    currentConversation,
    messages,
    loading,
    createConversation,
    sendMessage,
    loadConversation,
    deleteConversation,
    fetchConversations
  };
}

