import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from './useAuth';
import { useCompany } from '@/contexts/CompanyContext';
import { toast } from 'sonner';

interface KnowledgeDocument {
  id: string;
  agent_id: string;
  file_name: string;
  file_type: string;
  file_size: number;
  storage_path: string;
  content_text: string | null;
  uploaded_by: string;
  created_at: string;
}

export function useAgentKnowledge(agentId?: string) {
  const { user } = useAuth();
  const { activeCompany } = useCompany();
  const [documents, setDocuments] = useState<KnowledgeDocument[]>([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);

  const fetchDocuments = async (id: string) => {
    if (!user || !activeCompany) return;

    try {
      setLoading(true);
      const { data, error } = await supabase
        .from('ia_agent_knowledge_documents')
        .select('*')
        .eq('agent_id', id)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setDocuments(data || []);
    } catch (error) {
      console.error('Error fetching documents:', error);
      toast.error('Erro ao buscar documentos');
    } finally {
      setLoading(false);
    }
  };

  const uploadDocument = async (file: File) => {
    if (!user || !activeCompany || !agentId) return null;

    // Validações
    const maxSize = 20 * 1024 * 1024; // 20MB
    if (file.size > maxSize) {
      toast.error('Arquivo muito grande. Máximo: 20MB');
      return null;
    }

    const allowedTypes = ['text/plain', 'application/pdf'];
    if (!allowedTypes.includes(file.type)) {
      toast.error('Tipo de arquivo não suportado. Use TXT ou PDF');
      return null;
    }

    try {
      setUploading(true);

      // Upload para storage
      const filePath = `${activeCompany.company_id}/${agentId}/${Date.now()}_${file.name}`;
      const { error: uploadError } = await supabase.storage
        .from('agent-knowledge')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      // Extrair conteúdo
      let contentText = '';

      if (file.type === 'text/plain') {
        contentText = await file.text();
      } else if (file.type === 'application/pdf') {
        // Usar parse_document tool para PDFs
        // Por enquanto, apenas salvamos o caminho
        toast.info('PDF carregado. O conteúdo será processado em breve.');
      }

      // Salvar metadata no banco
      const { data, error: dbError } = await supabase
        .from('ia_agent_knowledge_documents')
        .insert({
          agent_id: agentId,
          company_id: activeCompany.company_id,
          file_name: file.name,
          file_type: file.type === 'text/plain' ? 'txt' : 'pdf',
          file_size: file.size,
          storage_path: filePath,
          content_text: contentText || null,
          uploaded_by: user.id
        })
        .select()
        .single();

      if (dbError) throw dbError;

      toast.success('Documento carregado com sucesso');
      await fetchDocuments(agentId);
      return data;
    } catch (error) {
      console.error('Error uploading document:', error);
      toast.error('Erro ao fazer upload do documento');
      return null;
    } finally {
      setUploading(false);
    }
  };

  const deleteDocument = async (documentId: string, storagePath: string) => {
    if (!user || !activeCompany || !agentId) return false;

    try {
      // Deletar do storage
      const { error: storageError } = await supabase.storage
        .from('agent-knowledge')
        .remove([storagePath]);

      if (storageError) throw storageError;

      // Deletar do banco
      const { error: dbError } = await supabase
        .from('ia_agent_knowledge_documents')
        .delete()
        .eq('id', documentId);

      if (dbError) throw dbError;

      toast.success('Documento removido com sucesso');
      await fetchDocuments(agentId);
      return true;
    } catch (error) {
      console.error('Error deleting document:', error);
      toast.error('Erro ao remover documento');
      return false;
    }
  };

  const getDocumentsContent = async (id: string): Promise<string> => {
    try {
      const { data, error } = await supabase
        .from('ia_agent_knowledge_documents')
        .select('content_text, file_name')
        .eq('agent_id', id);

      if (error) throw error;

      return data
        ?.filter(doc => doc.content_text)
        .map(doc => `[Documento: ${doc.file_name}]\n${doc.content_text}`)
        .join('\n\n---\n\n') || '';
    } catch (error) {
      console.error('Error getting documents content:', error);
      return '';
    }
  };

  useEffect(() => {
    if (agentId && user && activeCompany) {
      fetchDocuments(agentId);
    }
  }, [agentId, user?.id, activeCompany?.company_id]);

  return {
    documents,
    loading,
    uploading,
    uploadDocument,
    deleteDocument,
    getDocumentsContent,
    refetch: () => agentId && fetchDocuments(agentId)
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useCompany } from "@/contexts/CompanyContext";
import { useToast } from "@/hooks/use-toast";

export interface AgentSquad {
  id: string;
  name: string;
  description: string | null;
  client_id: string;
  company_id: string;
  user_id: string;
  status: string;
  created_at: string;
  updated_at: string;
  client?: { id: string; name: string; company: string } | null;
  members_count?: number;
}

export interface SquadMember {
  id: string;
  squad_id: string;
  agent_id: string;
  role: "leader" | "manager" | "executor";
  squad_instructions: string | null;
  position_x: number;
  position_y: number;
  created_at: string;
  agent?: {
    id: string;
    agent_name: string;
    description: string | null;
  };
}

export interface SquadFlow {
  id: string;
  squad_id: string;
  source_member_id: string;
  target_member_id: string;
  label: string | null;
  condition: string | null;
}

export function useAgentSquads() {
  const [squads, setSquads] = useState<AgentSquad[]>([]);
  const [loading, setLoading] = useState(false);
  const { user } = useAuth();
  const { activeCompany } = useCompany();
  const { toast } = useToast();

  const fetchSquads = async () => {
    if (!activeCompany?.company_id) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("ia_agent_squads" as unknown)
        .select("*, clients(id, name, company)")
        .eq("company_id", activeCompany.company_id)
        .order("created_at", { ascending: false });

      if (error) throw error;

      // Fetch member counts
      const squadsData = (data || []) as unknown[];
      const squadsWithCounts = await Promise.all(
        squadsData.map(async (squad: unknown) => {
          const { count } = await supabase
            .from("ia_agent_squad_members" as unknown)
            .select("*", { count: "exact", head: true })
            .eq("squad_id", squad.id);
          return {
            ...squad,
            client: squad.clients,
            members_count: count || 0,
          };
        })
      );

      setSquads(squadsWithCounts);
    } catch (err: unknown) {
      toast({ title: "Erro ao carregar squads", description: err.message, variant: "destructive" });
    } finally {
      setLoading(false);
    }
  };

  const createSquad = async (data: { name: string; description?: string; client_id: string }) => {
    if (!activeCompany?.company_id || !user?.id) return null;
    try {
      const { data: squad, error } = await supabase
        .from("ia_agent_squads" as unknown)
        .insert({
          name: data.name,
          description: data.description || null,
          client_id: data.client_id,
          company_id: activeCompany.company_id,
          user_id: user.id,
        } as unknown)
        .select()
        .single();

      if (error) throw error;
      toast({ title: "Squad criada com sucesso!" });
      fetchSquads();
      return squad;
    } catch (err: unknown) {
      toast({ title: "Erro ao criar squad", description: err.message, variant: "destructive" });
      return null;
    }
  };

  const updateSquad = async (id: string, data: { name?: string; description?: string; client_id?: string }) => {
    try {
      const { error } = await supabase
        .from("ia_agent_squads" as unknown)
        .update(data as unknown)
        .eq("id", id);
      if (error) throw error;
      toast({ title: "Squad atualizada!" });
      fetchSquads();
    } catch (err: unknown) {
      toast({ title: "Erro ao atualizar squad", description: err.message, variant: "destructive" });
    }
  };

  const deleteSquad = async (id: string) => {
    try {
      const { error } = await supabase.from("ia_agent_squads" as unknown).delete().eq("id", id);
      if (error) throw error;
      toast({ title: "Squad excluída!" });
      fetchSquads();
    } catch (err: unknown) {
      toast({ title: "Erro ao excluir squad", description: err.message, variant: "destructive" });
    }
  };

  const fetchSquadById = async (id: string) => {
    const { data, error } = await supabase
      .from("ia_agent_squads" as unknown)
      .select("*, clients(id, name, company)")
      .eq("id", id)
      .single();
    if (error) throw error;
    return { ...(data as unknown), client: (data as unknown).clients };
  };

  const fetchSquadMembers = async (squadId: string): Promise<SquadMember[]> => {
    const { data, error } = await supabase
      .from("ia_agent_squad_members" as unknown)
      .select("*, ia_agents(id, agent_name, description)")
      .eq("squad_id", squadId);
    if (error) throw error;
    return ((data || []) as unknown[]).map((m: unknown) => ({ ...m, agent: m.ia_agents }));
  };

  const fetchSquadFlows = async (squadId: string): Promise<SquadFlow[]> => {
    const { data, error } = await supabase
      .from("ia_agent_squad_flows" as unknown)
      .select("*")
      .eq("squad_id", squadId);
    if (error) throw error;
    return (data || []) as unknown[];
  };

  const saveSquadLayout = async (
    squadId: string,
    members: Array<{ id?: string; agent_id: string; role: string; squad_instructions?: string; position_x: number; position_y: number }>,
    flows: Array<{ source_member_id: string; target_member_id: string; label?: string; condition?: string }>
  ) => {
    try {
      // Delete existing flows first (they reference members), then members
      const { error: delFlowsErr } = await supabase.from("ia_agent_squad_flows" as unknown).delete().eq("squad_id", squadId);
      if (delFlowsErr) {
        console.error("Error deleting flows:", delFlowsErr);
        throw delFlowsErr;
      }

      const { error: delMembersErr } = await supabase.from("ia_agent_squad_members" as unknown).delete().eq("squad_id", squadId);
      if (delMembersErr) {
        console.error("Error deleting members:", delMembersErr);
        throw delMembersErr;
      }

      // Insert members
      if (members.length > 0) {
        const { data: insertedMembers, error: membersError } = await supabase
          .from("ia_agent_squad_members" as unknown)
          .insert(
            members.map((m) => ({
              squad_id: squadId,
              agent_id: m.agent_id,
              role: m.role,
              squad_instructions: m.squad_instructions || null,
              position_x: m.position_x,
              position_y: m.position_y,
            })) as unknown
          )
          .select();

        if (membersError) throw membersError;

        // Build id mapping (old temp ids to new DB ids)
        const membersList = insertedMembers as unknown[];

        // Insert flows using the new member IDs
        if (flows.length > 0 && membersList.length > 0) {
          // Map: we need to match source/target by agent_id + position
          const memberMap = new Map<string, string>();
          members.forEach((m, i) => {
            const key = m.id || `${m.agent_id}-${m.position_x}-${m.position_y}`;
            if (membersList[i]) {
              memberMap.set(key, membersList[i].id);
            }
          });

          const flowInserts = flows
            .map((f) => ({
              squad_id: squadId,
              source_member_id: memberMap.get(f.source_member_id) || f.source_member_id,
              target_member_id: memberMap.get(f.target_member_id) || f.target_member_id,
              label: f.label || null,
              condition: f.condition || null,
            }))
            .filter((f) => f.source_member_id && f.target_member_id);

          if (flowInserts.length > 0) {
            const { error: flowsError } = await supabase
              .from("ia_agent_squad_flows" as unknown)
              .insert(flowInserts as unknown);
            if (flowsError) throw flowsError;
          }
        }
      }

      toast({ title: "Squad salva com sucesso!" });
    } catch (err: unknown) {
      toast({ title: "Erro ao salvar squad", description: err.message, variant: "destructive" });
      throw err;
    }
  };

  useEffect(() => {
    if (activeCompany?.company_id) fetchSquads();
  }, [activeCompany?.company_id]);

  return {
    squads,
    loading,
    fetchSquads,
    createSquad,
    updateSquad,
    deleteSquad,
    fetchSquadById,
    fetchSquadMembers,
    fetchSquadFlows,
    saveSquadLayout,
  };
}

import { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { User, Session } from '@supabase/supabase-js';
import { useLocation } from 'react-router-dom';
import { supabase } from '@/integrations/supabase/client';

interface AuthContextType {
  user: User | null;
  session: Session | null;
  signUp: (email: string, password: string, fullName: string) => Promise<{ error: unknown }>;
  signIn: (email: string, password: string) => Promise<{ error: unknown }>;
  signOut: () => Promise<{ error: unknown }>;
  loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const location = useLocation();

  // Public pages should not attempt to recover/refresh auth sessions.
  const isPublicRoute =
    /^\/(dashboard-publico|tv|social-tv|radar-tv|apresentacao|resultados|crm|report-lead-desqualificado)(\/|$)/.test(
      location.pathname
    );

  useEffect(() => {
    let isMounted = true;
    let subscription: { unsubscribe: () => void } | null = null;

    const run = async () => {
      setLoading(true);

      if (isPublicRoute) {
        try {
          await supabase.auth.stopAutoRefresh();
        } catch {
          // ignore
        }

        if (isMounted) {
          setSession(null);
          setUser(null);
          setLoading(false);
        }
        return;
      }

      try {
        await supabase.auth.startAutoRefresh();
      } catch {
        // ignore
      }

      // Set up auth state listener FIRST
      const { data } = supabase.auth.onAuthStateChange((event, session) => {
        if (!isMounted) return;
        setSession(session);
        setUser(session?.user ?? null);
        setLoading(false);
      });
      subscription = data.subscription;

      // THEN check for existing session
      const { data: sessionData } = await supabase.auth.getSession();
      if (!isMounted) return;
      setSession(sessionData.session);
      setUser(sessionData.session?.user ?? null);
      setLoading(false);
    };

    run();

    return () => {
      isMounted = false;
      subscription?.unsubscribe();
    };
  }, [isPublicRoute]);

  const signUp = async (email: string, password: string, fullName: string) => {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          full_name: fullName
        }
      }
    });

    // Se não há erro e não precisa confirmar email, o usuário já está logado
    return { error, data };
  };

  const signIn = async (email: string, password: string) => {
    const { error } = await supabase.auth.signInWithPassword({
      email,
      password
    });
    return { error };
  };

  const signOut = async () => {
    const { error } = await supabase.auth.signOut();
    return { error };
  };

  const value = {
    user,
    session,
    signUp,
    signIn,
    signOut,
    loading
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { useCompany } from "@/contexts/CompanyContext";
import { useToast } from "./use-toast";

export interface AutomationLog {
  id: string;
  rule_id: string;
  company_id: string;
  client_id: string | null;
  campaign_id: string | null;
  action_type: string;
  action_result: 'success' | 'error' | 'skipped';
  error_message: string | null;
  old_name: string | null;
  new_name: string | null;
  old_budget: number | null;
  new_budget: number | null;
  old_status: string | null;
  new_status: string | null;
  rolled_back: boolean;
  rolled_back_at: string | null;
  rolled_back_by: string | null;
  metadata: unknown;
  executed_at: string;
}

export const useAutomationLogs = (clientId?: string | null, limit?: number) => {
  const [logs, setLogs] = useState<unknown[]>([]);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();
  const { activeCompany } = useCompany();
  const { toast } = useToast();

  const fetchLogs = async () => {
    if (!user || !activeCompany?.company_id) return;

    setLoading(true);

    let query = supabase
      .from("campaign_automation_logs")
      .select(`
        *,
        rule:campaign_automation_rules(rule_name),
        client:clients(name),
        campaign:campaigns(name)
      `)
      .eq("company_id", activeCompany.company_id)
      .order("executed_at", { ascending: false });

    if (clientId) {
      query = query.eq("client_id", clientId);
    }

    if (limit) {
      query = query.limit(limit);
    }

    const { data, error } = await query;

    if (error) {
      console.error("Error fetching logs:", error);
      toast({
        title: "Erro",
        description: "Erro ao carregar logs.",
        variant: "destructive",
      });
    } else {
      setLogs(data || []);
    }

    setLoading(false);
  };

  useEffect(() => {
    fetchLogs();
  }, [user?.id, activeCompany?.company_id, clientId, limit]);

  const rollbackAction = async (logId: string) => {
    try {
      const { data, error } = await supabase.functions.invoke(
        'rollback-automation-action',
        {
          body: { log_id: logId },
        }
      );

      if (error) throw error;

      toast({
        title: "Ação revertida",
        description: "A ação foi revertida com sucesso.",
      });

      await fetchLogs();
      return data;
    } catch (error: unknown) {
      toast({
        title: "Erro ao reverter",
        description: error.message,
        variant: "destructive",
      });
      return null;
    }
  };

  const clearLogs = async () => {

    if (!clientId || !activeCompany?.company_id) {
      console.error("Missing clientId or companyId", { clientId, companyId: activeCompany?.company_id });
      toast({
        title: "Erro",
        description: "Cliente ou empresa não identificados.",
        variant: "destructive",
      });
      return false;
    }

    try {

      const { data, error, count } = await supabase
        .from("campaign_automation_logs")
        .delete()
        .eq("client_id", clientId)
        .eq("company_id", activeCompany.company_id)
        .select();


      if (error) {
        console.error("Delete error:", error);
        throw error;
      }

      const deletedCount = data?.length || 0;

      toast({
        title: "Logs limpos",
        description: `${deletedCount} logs de automação foram removidos.`,
      });

      await fetchLogs();
      return true;
    } catch (error: unknown) {
      console.error("Error clearing logs:", error);
      toast({
        title: "Erro ao limpar logs",
        description: error.message || "Erro desconhecido ao limpar logs",
        variant: "destructive",
      });
      return false;
    }
  };

  return {
    logs,
    loading,
    fetchLogs,
    rollbackAction,
    clearLogs,
  };
};

