import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { useCompany } from "@/contexts/CompanyContext";
import { useToast } from "./use-toast";

export interface AutomationRule {
  id: string;
  company_id: string;
  client_id: string | null;
  is_template: boolean;
  template_id: string | null;
  imported_at: string | null;
  rule_name: string;
  rule_description: string | null;
  rule_order: number;
  campaign_objectives: string[] | null;
  entity_type?: string;
  time_window_days: number;
  conditions: {
    logic: "AND" | "OR";
    conditions: Array<{
      field: string;
      operator: "<" | ">" | "=" | "!=" | ">=" | "<=";
      value: number | boolean;
      type: "number" | "boolean";
    }>;
  };
  action_type: string;
  action_config: unknown;
  budget_safety_limits: unknown;
  execution_limits: unknown;
  scope_filters: unknown;
  is_active: boolean;
  last_execution_at: string | null;
  execution_count: number;
  created_at: string;
  updated_at: string;
}

export const useAutomationRules = (clientId?: string | null) => {
  const [rules, setRules] = useState<AutomationRule[]>([]);
  const [templates, setTemplates] = useState<AutomationRule[]>([]);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();
  const { activeCompany } = useCompany();
  const { toast } = useToast();

  const fetchTemplates = async () => {
    if (!user || !activeCompany?.company_id) return;

    const { data, error } = await supabase
      .from("campaign_automation_rules")
      .select("*")
      .eq("company_id", activeCompany.company_id)
      .eq("is_template", true)
      .order("rule_order", { ascending: true });

    if (error) {
      console.error("Error fetching templates:", error);
      return;
    }

    setTemplates((data as unknown) || []);
  };

  const fetchRules = async () => {
    if (!user || !activeCompany?.company_id) return;

    setLoading(true);

    let query = supabase
      .from("campaign_automation_rules")
      .select("*")
      .eq("company_id", activeCompany.company_id)
      .eq("is_template", false);

    if (clientId) {
      query = query.eq("client_id", clientId);
    }

    const { data, error } = await query.order("rule_order", { ascending: true });

    if (error) {
      console.error("Error fetching rules:", error);
      toast({
        title: "Erro",
        description: "Erro ao carregar regras de automação.",
        variant: "destructive",
      });
    } else {
      setRules((data as unknown) || []);
    }

    setLoading(false);
  };

  useEffect(() => {
    fetchTemplates();
    fetchRules();
  }, [user?.id, activeCompany?.company_id, clientId]);

  // Auto-fix entity_type baseado em action_type
  useEffect(() => {
    const autoFixEntityTypes = async () => {
      if (!rules.length || !activeCompany?.company_id) return;

      const rulesToFix = rules.filter(rule => {
        const isAdAction = ['pause_ad', 'activate_ad', 'duplicate_ad'].includes(rule.action_type);
        const isAdsetAction = ['pause_adset', 'activate_adset', 'duplicate_adset'].includes(rule.action_type);
        const isCampaignAction = ['pause_campaign', 'activate_campaign', 'adjust_budget', 'duplicate_campaign'].includes(rule.action_type);

        if (isAdAction && rule.entity_type !== 'ad') return true;
        if (isAdsetAction && rule.entity_type !== 'adset') return true;
        if (isCampaignAction && rule.entity_type !== 'campaign' && rule.entity_type !== null) return true;
        return false;
      });

      for (const rule of rulesToFix) {
        let correctEntityType = 'campaign';
        if (['pause_ad', 'activate_ad', 'duplicate_ad'].includes(rule.action_type)) {
          correctEntityType = 'ad';
        } else if (['pause_adset', 'activate_adset', 'duplicate_adset'].includes(rule.action_type)) {
          correctEntityType = 'adset';
        }


        await supabase
          .from('campaign_automation_rules')
          .update({ entity_type: correctEntityType })
          .eq('id', rule.id);
      }

      if (rulesToFix.length > 0) {
        await fetchRules();
      }
    };

    autoFixEntityTypes();
  }, [rules.length]);

  const createTemplate = async (templateData: Omit<AutomationRule, "id" | "created_at" | "updated_at" | "company_id" | "is_template" | "client_id" | "template_id" | "imported_at" | "execution_count" | "last_execution_at">) => {
    if (!activeCompany?.company_id) return null;

    const { data, error } = await supabase
      .from("campaign_automation_rules")
      .insert({
        ...templateData,
        company_id: activeCompany.company_id,
        is_template: true,
        client_id: null,
        template_id: null,
      })
      .select()
      .single();

    if (error) {
      toast({
        title: "Erro",
        description: "Erro ao criar template.",
        variant: "destructive",
      });
      return null;
    }

    toast({
      title: "Template criado",
      description: "Template de automação criado com sucesso.",
    });

    await fetchTemplates();
    return data;
  };

  const importTemplateToClient = async (templateId: string, targetClientId: string) => {
    if (!activeCompany?.company_id) return null;

    const { data: template, error: fetchError } = await supabase
      .from("campaign_automation_rules")
      .select("*")
      .eq("id", templateId)
      .single();

    if (fetchError || !template) {
      toast({
        title: "Erro",
        description: "Template não encontrado.",
        variant: "destructive",
      });
      return null;
    }

    return template;
  };

  const importConfiguredTemplate = async (
    templateId: string,
    targetClientId: string,
    configuredConditions: unknown
  ) => {
    if (!activeCompany?.company_id) return null;

    const { data: template, error: fetchError } = await supabase
      .from("campaign_automation_rules")
      .select("*")
      .eq("id", templateId)
      .single();

    if (fetchError || !template) {
      toast({
        title: "Erro",
        description: "Template não encontrado.",
        variant: "destructive",
      });
      return null;
    }

    // Validate that all conditions have operator and value
    const allConfigured = configuredConditions.conditions.every(
      (c: unknown) => c.operator !== null && c.value !== null
    );

    if (!allConfigured) {
      toast({
        title: "Erro de validação",
        description: "Todas as condições devem ser configuradas",
        variant: "destructive",
      });
      return null;
    }

    const { data: newRule, error: insertError } = await supabase
      .from("campaign_automation_rules")
      .insert({
        company_id: activeCompany.company_id,
        client_id: targetClientId,
        is_template: false,
        template_id: templateId,
        imported_at: new Date().toISOString(),
        rule_name: template.rule_name,
        rule_description: template.rule_description,
        rule_order: template.rule_order,
        campaign_objectives: template.campaign_objectives,
        time_window_days: template.time_window_days,
        conditions: configuredConditions,
        action_type: template.action_type,
        action_config: template.action_config,
        budget_safety_limits: template.budget_safety_limits,
        execution_limits: template.execution_limits,
        scope_filters: template.scope_filters,
        entity_type: template.entity_type,
        is_active: true,
        execution_count: 0,
      })
      .select()
      .single();

    if (insertError) {
      toast({
        title: "Erro",
        description: "Erro ao importar template.",
        variant: "destructive",
      });
      return null;
    }

    toast({
      title: "Template importado",
      description: `Regra "${template.rule_name}" aplicada ao cliente.`,
    });

    await fetchRules();
    return newRule;
  };

  const updateRule = async (id: string, updates: Partial<AutomationRule>) => {
    const { error } = await supabase
      .from("campaign_automation_rules")
      .update(updates)
      .eq("id", id);

    if (error) {
      toast({
        title: "Erro",
        description: "Erro ao atualizar regra.",
        variant: "destructive",
      });
      return;
    }

    // Verificar se é template e notificar sincronização
    const updatedRule = rules.find(r => r.id === id);
    if (updatedRule?.is_template) {
      // Buscar quantas regras foram sincronizadas
      const { count } = await supabase
        .from('campaign_automation_rules')
        .select('id', { count: 'exact', head: true })
        .eq('template_id', id)
        .eq('is_template', false);

      if (count && count > 0) {
        toast({
          title: "✅ Regra atualizada",
          description: `Template atualizado e sincronizado em ${count} cliente(s)`,
        });
      } else {
        toast({
          title: "✅ Regra atualizada",
          description: "Template atualizado com sucesso.",
        });
      }
    } else {
      toast({
        title: "Regra atualizada",
        description: "Regra atualizada com sucesso.",
      });
    }

    await fetchTemplates();
    await fetchRules();
  };

  const updateRuleConditions = async (ruleId: string, newConditions: unknown, timeWindowDays?: number) => {
    const updateData: unknown = { 
      conditions: newConditions,
      updated_at: new Date().toISOString()
    };

    // Incluir time_window_days se fornecido
    if (timeWindowDays !== undefined && timeWindowDays >= 1 && timeWindowDays <= 90) {
      updateData.time_window_days = timeWindowDays;
    }

    const { error } = await supabase
      .from("campaign_automation_rules")
      .update(updateData)
      .eq("id", ruleId);

    if (error) {
      toast({
        title: "Erro",
        description: "Erro ao atualizar condições.",
        variant: "destructive",
      });
      throw error;
    }

    toast({
      title: "Regra atualizada",
      description: timeWindowDays 
        ? `Condições e janela de tempo (${timeWindowDays} dias) atualizados.`
        : "Os valores foram atualizados com sucesso.",
    });

    await fetchRules();
  };

  const deleteRule = async (id: string) => {
    const { error } = await supabase
      .from("campaign_automation_rules")
      .delete()
      .eq("id", id);

    if (error) {
      toast({
        title: "Erro",
        description: "Erro ao deletar regra.",
        variant: "destructive",
      });
      return;
    }

    toast({
      title: "Regra deletada",
      description: "Regra removida com sucesso.",
    });

    await fetchTemplates();
    await fetchRules();
  };

  const simulateRule = async (ruleId: string) => {
    try {
      const { data, error } = await supabase.functions.invoke(
        'execute-campaign-automations',
        {
          body: {},
          method: 'GET',
          // Pass query params via URL
        }
      );

      if (error) throw error;

      return data;
    } catch (error: unknown) {
      toast({
        title: "Erro na simulação",
        description: error.message,
        variant: "destructive",
      });
      return null;
    }
  };

  return {
    rules,
    templates,
    loading,
    fetchRules,
    fetchTemplates,
    createTemplate,
    importTemplateToClient,
    importConfiguredTemplate,
    updateRule,
    updateRuleConditions,
    deleteRule,
    simulateRule,
  };
};

import { useState, useEffect } from 'react';
