        title: "Erro ao carregar agendamento",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const createOrUpdateSchedule = async (config: {
    is_enabled: boolean;
    executions_per_day: number;
  }) => {
    if (!clientId || !activeCompany) return;

    try {
      setLoading(true);

      const { data, error } = await supabase.functions.invoke(
        'manage-automation-schedule',
        {
          body: {
            client_id: clientId,
            company_id: activeCompany.company_id,
            is_enabled: config.is_enabled,
            executions_per_day: config.executions_per_day,
          }
        }
      );

      if (error) throw error;

      if (!data.success) {
        throw new Error(data.error || 'Erro ao configurar agendamento');
      }

      setSchedule(data.schedule);

      toast({
        title: config.is_enabled ? "Agendamento ativado" : "Agendamento atualizado",
        description: config.is_enabled 
          ? `Automações executarão ${config.executions_per_day}x por dia`
          : "Configurações atualizadas com sucesso",
      });

      return data.schedule;
    } catch (error: unknown) {
      console.error('Error creating/updating schedule:', error);
      toast({
        title: "Erro ao configurar agendamento",
        description: error.message,
        variant: "destructive",
      });
      return null;
    } finally {
      setLoading(false);
    }
  };

  const toggleSchedule = async (enabled: boolean) => {
    // Se não existe schedule, criar um novo com configuração padrão
    const executionsPerDay = schedule?.executions_per_day || 2;

    return createOrUpdateSchedule({
      is_enabled: enabled,
      executions_per_day: executionsPerDay,
    });
  };

  const deleteSchedule = async () => {
    if (!clientId) return;

    try {
      setLoading(true);

      const { data, error } = await supabase.functions.invoke(
        'manage-automation-schedule',
        {
          method: 'DELETE',
          body: { client_id: clientId }
        }
      );

      if (error) throw error;

      if (!data.success) {
        throw new Error(data.error || 'Erro ao deletar agendamento');
      }

      setSchedule(null);

      toast({
        title: "Agendamento removido",
        description: "Automações não serão mais executadas automaticamente",
      });
    } catch (error: unknown) {
      console.error('Error deleting schedule:', error);
      toast({
        title: "Erro ao remover agendamento",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (clientId && activeCompany) {
      fetchSchedule();
    }
  }, [clientId, activeCompany]);

  return {
    schedule,
    loading,
    fetchSchedule,
    createOrUpdateSchedule,
    toggleSchedule,
    deleteSchedule,
  };
};

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useCompany } from "@/contexts/CompanyContext";
import { useToast } from "@/hooks/use-toast";

interface AutomationSettings {
  id: string;
  company_id: string;
  campaign_name_prefix: string;
  created_at: string;
  updated_at: string;
}

export function useAutomationSettings() {
  const { activeCompany } = useCompany();
  const { toast } = useToast();
  const [settings, setSettings] = useState<AutomationSettings | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchSettings = async () => {
    if (!activeCompany?.company_id) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);

      const { data, error } = await supabase
        .from("automation_settings")
        .select("*")
        .eq("company_id", activeCompany.company_id)
        .single();

      if (error) {
        // Se não existe, criar com valores padrão
        if (error.code === 'PGRST116') {
          const { data: newSettings, error: insertError } = await supabase
            .from("automation_settings")
            .insert({
              company_id: activeCompany.company_id,
              campaign_name_prefix: "SHEGrowth"
            })
            .select()
            .single();

          if (insertError) {
            console.error("Error creating default settings:", insertError);
            toast({
              variant: "destructive",
              title: "Erro ao criar configurações",
              description: insertError.message,
            });
            return;
          }

          setSettings(newSettings);
        } else {
          throw error;
        }
      } else {
        setSettings(data);
      }
    } catch (error: unknown) {
      console.error("Error fetching automation settings:", error);
      toast({
        variant: "destructive",
        title: "Erro ao carregar configurações",
        description: error.message,
      });
    } finally {
      setLoading(false);
    }
  };

  const updateSettings = async (updates: Partial<AutomationSettings>) => {
    if (!activeCompany?.company_id || !settings) {
      toast({
        variant: "destructive",
        title: "Erro",
        description: "Nenhuma configuração encontrada para atualizar",
      });
      return;
    }

    // Validar prefixo
    if (updates.campaign_name_prefix !== undefined) {
      const prefix = updates.campaign_name_prefix.trim();
      if (!prefix || prefix.length === 0) {
        toast({
          variant: "destructive",
          title: "Prefixo inválido",
          description: "O prefixo não pode estar vazio",
        });
        return;
      }
      if (prefix.length > 50) {
        toast({
          variant: "destructive",
          title: "Prefixo muito longo",
          description: "O prefixo deve ter no máximo 50 caracteres",
        });
        return;
      }
    }

    try {
      const { data, error } = await supabase
        .from("automation_settings")
        .update(updates)
        .eq("id", settings.id)
        .select()
        .single();

      if (error) throw error;

      setSettings(data);
      toast({
        title: "Configurações atualizadas",
        description: "As configurações foram salvas com sucesso",
      });
    } catch (error: unknown) {
      console.error("Error updating automation settings:", error);
      toast({
        variant: "destructive",
        title: "Erro ao salvar configurações",
        description: error.message,
      });
    }
  };

  useEffect(() => {
    fetchSettings();
  }, [activeCompany?.company_id]);

  return {
    settings,
    loading,
    updateSettings,
    fetchSettings,
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { useCompany } from "@/contexts/CompanyContext";

export interface AutomationRuleTemplate {
  id: string;
  company_id: string;
  name: string;
  description: string | null;
  category: string | null;
  is_active: boolean;
  created_at: string;
  updated_at: string;
  rules?: AutomationTemplateRule[];
}

export interface AutomationTemplateRule {
  id: string;
  template_id: string;
  rule_id: string;
  order_index: number;
  rule?: unknown; // Full rule data when joined
}

export const useAutomationTemplates = () => {
  const [templates, setTemplates] = useState<AutomationRuleTemplate[]>([]);
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();
  const { user } = useAuth();
  const { activeCompany } = useCompany();

  const fetchTemplates = async () => {
    if (!user || !activeCompany) return;

    try {
      setLoading(true);

      // Fetch templates with their associated rules
      const { data: templatesData, error: templatesError } = await supabase
        .from("automation_rule_templates" as unknown)
        .select(`
          *,
          automation_template_rules (
            id,
            rule_id,
            order_index,
            rule:campaign_automation_rules (*)
          )
        `)
        .eq("company_id", activeCompany.company_id)
        .order("created_at", { ascending: false });

      if (templatesError) throw templatesError;

      // Transform the data to match our interface
      const transformedTemplates = templatesData?.map((template: unknown) => ({
        ...template,
        rules: template.automation_template_rules || []
      })) || [];

      setTemplates(transformedTemplates);
    } catch (error: unknown) {
      console.error("Error fetching automation templates:", error);
      toast({
        title: "Erro ao carregar templates",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user && activeCompany) {
      fetchTemplates();
    }
  }, [user, activeCompany]);

  const createTemplate = async (
    name: string,
    description: string | null,
    category: string | null,
    ruleIds: string[]
  ) => {
    if (!activeCompany) {
      throw new Error("Nenhuma empresa selecionada");
    }

    try {
      // Create the template
      const { data: templateData, error: templateError } = await supabase
        .from("automation_rule_templates" as unknown)
        .insert({
          company_id: activeCompany.company_id,
          name,
          description,
          category,
          is_active: true,
        })
        .select()
        .single();

      if (templateError) throw templateError;

      // Create the rule associations
      const ruleAssociations = ruleIds.map((ruleId, index) => ({
        template_id: (templateData as unknown).id,
        rule_id: ruleId,
        order_index: index,
      }));

      const { error: rulesError } = await supabase
        .from("automation_template_rules" as unknown)
        .insert(ruleAssociations);

      if (rulesError) throw rulesError;

      toast({
        title: "Template criado",
        description: "O template foi criado com sucesso.",
      });

      await fetchTemplates();
      return templateData;
    } catch (error: unknown) {
      console.error("Error creating template:", error);
      toast({
        title: "Erro ao criar template",
        description: error.message,
        variant: "destructive",
      });
      throw error;
    }
  };

  const updateTemplate = async (
    templateId: string,
    updates: {
      name?: string;
      description?: string | null;
      category?: string | null;
      is_active?: boolean;
      ruleIds?: string[];
    }
  ) => {
    try {
      // Update template metadata
      const { name, description, category, is_active, ruleIds } = updates;
      const templateUpdates: unknown = {};

      if (name !== undefined) templateUpdates.name = name;
      if (description !== undefined) templateUpdates.description = description;
      if (category !== undefined) templateUpdates.category = category;
      if (is_active !== undefined) templateUpdates.is_active = is_active;

      if (Object.keys(templateUpdates).length > 0) {
        const { error: updateError } = await supabase
          .from("automation_rule_templates" as unknown)
          .update(templateUpdates)
          .eq("id", templateId);

        if (updateError) throw updateError;
      }

      // Update rule associations if provided
      if (ruleIds !== undefined) {
        // Delete existing associations
        const { error: deleteError } = await supabase
          .from("automation_template_rules" as unknown)
          .delete()
          .eq("template_id", templateId);

        if (deleteError) throw deleteError;

        // Create new associations
        const ruleAssociations = ruleIds.map((ruleId, index) => ({
          template_id: templateId,
          rule_id: ruleId,
          order_index: index,
        }));

        const { error: insertError } = await supabase
          .from("automation_template_rules" as unknown)
          .insert(ruleAssociations);

        if (insertError) throw insertError;
      }

      toast({
        title: "Template atualizado",
        description: "As alterações foram salvas com sucesso.",
      });

      await fetchTemplates();
    } catch (error: unknown) {
      console.error("Error updating template:", error);
      toast({
        title: "Erro ao atualizar template",
        description: error.message,
        variant: "destructive",
      });
      throw error;
    }
  };

  const deleteTemplate = async (templateId: string) => {
    try {
      const { error } = await supabase
        .from("automation_rule_templates" as unknown)
        .delete()
        .eq("id", templateId);

      if (error) throw error;

      toast({
        title: "Template deletado",
        description: "O template foi removido com sucesso.",
      });

      await fetchTemplates();
    } catch (error: unknown) {
      console.error("Error deleting template:", error);
      toast({
        title: "Erro ao deletar template",
        description: error.message,
        variant: "destructive",
      });
      throw error;
    }
  };

  const importTemplateToClient = async (templateId: string, clientId: string) => {
    try {
      // Fetch template with all rules
      const { data: templateData, error: templateError } = await supabase
        .from("automation_rule_templates" as unknown)
        .select(`
          *,
          automation_template_rules (
            rule:campaign_automation_rules (*)
          )
        `)
        .eq("id", templateId)
        .single();

      if (templateError) throw templateError;

      // Import each rule to the client
      const ruleImportPromises = (templateData as unknown).automation_template_rules.map(
        async (templateRule: unknown) => {
          const rule = templateRule.rule;

          const { error: importError } = await supabase
            .from("campaign_automation_rules")
            .insert({
              company_id: rule.company_id,
              client_id: clientId,
              rule_name: rule.rule_name,
              rule_description: rule.rule_description,
              entity_type: rule.entity_type,
              action_type: rule.action_type,
              conditions: rule.conditions,
              action_config: rule.action_config,
              time_window_hours: rule.time_window_hours,
              priority: rule.priority,
              is_active: rule.is_active,
              is_template: false,
              template_id: rule.id,
              safety_limits: rule.safety_limits,
              recovery_trigger: rule.recovery_trigger,
              objectives: rule.objectives,
            });

          if (importError) throw importError;
        }
      );

      await Promise.all(ruleImportPromises);

      toast({
        title: "Template importado",
        description: `${(templateData as unknown).automation_template_rules.length} regras foram importadas com sucesso.`,
      });

      return templateData;
    } catch (error: unknown) {
      console.error("Error importing template:", error);
      toast({
        title: "Erro ao importar template",
        description: error.message,
        variant: "destructive",
      });
      throw error;
    }
  };

  return {
    templates,
    loading,
    fetchTemplates,
    createTemplate,
    updateTemplate,
    deleteTemplate,
    importTemplateToClient,
  };
};

import { useState, useCallback, useRef } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { EditableStrategy, EditableCreative } from '@/components/campaign-generator/editable/types';
import { toast } from 'sonner';

interface GenerationProgress {
  total: number;
  completed: number;
  current: string | null;
  isGenerating: boolean;
}

export function useBackgroundImageGeneration() {
  const [progress, setProgress] = useState<GenerationProgress>({
    total: 0,
    completed: 0,
    current: null,
    isGenerating: false,
  });

  const abortRef = useRef(false);

  const generateImagesInBackground = useCallback(async (
    strategy: EditableStrategy,
    clientId: string,
    onCreativeUpdate: (adSetId: string, creativeId: string, imageUrl: string) => void
  ) => {
    // Collect all creatives that need images
    const creativesToGenerate: { 
      adSetId: string; 
      adSetName: string;
      creative: EditableCreative;
      index: number;
    }[] = [];

    strategy.adSets.forEach((adSet) => {
      adSet.creatives.forEach((creative, index) => {
        // Only generate for creatives without images and with text content
        if (creative.mediaUrls.length === 0 && (creative.headline || creative.body)) {
          creativesToGenerate.push({
            adSetId: adSet.id,
            adSetName: adSet.name,
            creative,
            index,
          });
        }
      });
    });

    if (creativesToGenerate.length === 0) {
      return;
    }

    abortRef.current = false;
    setProgress({
      total: creativesToGenerate.length,
      completed: 0,
      current: null,
      isGenerating: true,
    });

    toast.info(`Gerando ${creativesToGenerate.length} imagem(ns) em segundo plano...`, {
      duration: 3000,
    });

    // Generate images one by one
    for (let i = 0; i < creativesToGenerate.length; i++) {
      if (abortRef.current) {
        break;
      }

      const item = creativesToGenerate[i];

      setProgress(prev => ({
        ...prev,
        current: `${item.adSetName} - Criativo ${item.index + 1}`,
      }));

      try {
        const prompt = `Crie uma imagem profissional para anúncio de mídia social. 
          Título: ${item.creative.headline || 'Sem título'}
          Texto: ${item.creative.body || 'Sem texto'}
          Descrição: ${item.creative.description || 'Sem descrição'}
          Estilo: moderno, profissional, adequado para Instagram e Facebook.`;

        const { data, error } = await supabase.functions.invoke('generate-ai-campaign-image', {
          body: { prompt, clientId, placement: 'feed' }
        });

        if (error) {
          console.error('Error generating image:', error);
          continue;
        }

        if (data?.success && data?.imageUrl) {
          onCreativeUpdate(item.adSetId, item.creative.id, data.imageUrl);

          setProgress(prev => ({
            ...prev,
            completed: prev.completed + 1,
          }));
        }
      } catch (error) {
        console.error('Error generating image for creative:', error);
        // Continue with next creative even if one fails
      }
    }

    setProgress(prev => ({
      ...prev,
      current: null,
      isGenerating: false,
    }));

    const finalCompleted = progress.completed + 1;
    if (finalCompleted > 0) {
      toast.success(`${finalCompleted} imagem(ns) gerada(s) com sucesso!`, {
        duration: 3000,
      });
    }
  }, []);

  const stopGeneration = useCallback(() => {
    abortRef.current = true;
    setProgress(prev => ({
      ...prev,
      isGenerating: false,
      current: null,
    }));
  }, []);

  return {
    progress,
    generateImagesInBackground,
    stopGeneration,
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";

export interface Campaign {
  id: string;
  client_id: string;
  name: string;
  platforms: string;
  status: "active" | "paused" | "finished" | "deleted";
  ctr: number;
  cpc: number;
  conversions: number;
  spend: number; // Custo Total da Campanha
  cpa: number; // Custo por Aquisição/Conversão
  period: string;
  is_active: boolean;
  average_ticket?: number; // Ticket médio do produto para cálculo de ROI
  impressions?: number;
  reach?: number;
  frequency?: number;
  quality_ranking?: string;
  engagement_rate_ranking?: string;
  conversion_rate_ranking?: string;
  objective?: string; // Tipo/objetivo da campanha
  created_at?: string;
  updated_at?: string;
  clicks?: number;
  last_synced_at?: string;
  deleted_at?: string;
  client?: {
    name: string;
    avatar: string;
  };
}

export function useCampaigns(clientId?: string) {
  const [campaigns, setCampaigns] = useState<Campaign[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();

  const fetchCampaigns = async () => {
    if (!user) return;

    try {
      setLoading(true);

      // Construir query base
      let query = supabase
        .from("campaigns")
        .select(`
          *,
          client:clients(name, avatar)
        `);

      // Aplicar filtro de cliente se fornecido
      if (clientId) {
        query = query.eq("client_id", clientId);
      }

      const { data, error } = await query.order("created_at", { ascending: false });

      if (error) throw error;
      setCampaigns(data || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao buscar campanhas");
    } finally {
      setLoading(false);
    }
  };

  const createCampaign = async (campaignData: Omit<Campaign, "id" | "client" | "spend" | "cpa">) => {
    if (!user) return null;

    try {
      const { data, error } = await supabase
        .from("campaigns")
        .insert([{
          ...campaignData,
          user_id: user.id,
        }])
        .select()
        .single();

      if (error) throw error;
      await fetchCampaigns(); // Refresh the list
      return data;
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao criar campanha");
      return null;
    }
  };

  const updateCampaign = async (id: string, updates: Partial<Campaign>) => {
    try {
      const { error } = await supabase
        .from("campaigns")
        .update(updates)
        .eq("id", id);

      if (error) throw error;
      await fetchCampaigns(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao atualizar campanha");
    }
  };

  const toggleCampaign = async (id: string, isActive: boolean) => {
    try {
      // First, get the campaign to find the client_id
      const campaign = campaigns.find(c => c.id === id);
      if (!campaign) {
        throw new Error("Campanha não encontrada");
      }

      // Try to update via Facebook API first
      try {
        const { data: result, error: functionError } = await supabase.functions.invoke('manage-facebook-campaign', {
          body: {
            campaignId: id,
            status: isActive ? "active" : "paused",
            clientId: campaign.client_id
          }
        });

        if (functionError) {
          console.warn('Facebook API update failed, falling back to local update:', functionError);
          throw functionError;
        }

        if (result?.error) {
          console.warn('Facebook API returned error, falling back to local update:', result.error);
          throw new Error(result.error);
        }

        // Facebook update successful, refresh campaigns to get latest data
        await fetchCampaigns();
        return;

      } catch (facebookError) {
        console.warn('Facebook API update failed, falling back to local update:', facebookError);

        // Fallback to local update only
        const { error } = await supabase
          .from("campaigns")
          .update({ 
            is_active: isActive,
            status: isActive ? "active" : "paused"
          })
          .eq("id", id);

        if (error) throw error;
        await fetchCampaigns(); // Refresh the list
      }

    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao alterar status da campanha");
    }
  };

  const deleteCampaign = async (id: string) => {
    try {
      const { error } = await supabase
        .from("campaigns")
        .delete()
        .eq("id", id);

      if (error) throw error;
      await fetchCampaigns(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao deletar campanha");
    }
  };

  useEffect(() => {
    fetchCampaigns();
  }, [user, clientId]);

  return {
    campaigns,
    loading,
    error,
    fetchCampaigns,
    createCampaign,
    updateCampaign,
    toggleCampaign,
    deleteCampaign,
  };
}

import { useState, useEffect } from "react";
