export function useClientBenchmarks(clientId?: string, companyId?: string) {
  const [benchmarks, setBenchmarks] = useState<ClientBenchmark[]>([]);
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();

  const fetchBenchmarks = async () => {
    if (!clientId) return;

    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('client_metric_benchmarks')
        .select('*')
        .eq('client_id', clientId);

      if (error) throw error;
      setBenchmarks((data || []) as ClientBenchmark[]);
    } catch (error: unknown) {
      console.error('Error fetching benchmarks:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchBenchmarks();
  }, [clientId]);

  const getBenchmarkByPlatform = (platform: PlatformType): ClientBenchmark | undefined => {
    return benchmarks.find(b => b.platform === platform);
  };

  const formDataToBenchmark = (formData: BenchmarkFormData) => {
    return {
      target_cpa: formData.target_cpa ? parseFloat(formData.target_cpa) : null,
      target_cpl: formData.target_cpl ? parseFloat(formData.target_cpl) : null,
      target_ctr: formData.target_ctr ? parseFloat(formData.target_ctr) : null,
      target_cpc: formData.target_cpc ? parseFloat(formData.target_cpc) : null,
      target_cpm: formData.target_cpm ? parseFloat(formData.target_cpm) : null,
      target_roas: formData.target_roas ? parseFloat(formData.target_roas) : null,
      target_conversion_rate: formData.target_conversion_rate ? parseFloat(formData.target_conversion_rate) : null,
      target_frequency: formData.target_frequency ? parseFloat(formData.target_frequency) : null,
      is_active: formData.is_active,
    };
  };

  const benchmarkToFormData = (benchmark?: ClientBenchmark): BenchmarkFormData => {
    if (!benchmark) return emptyBenchmarkFormData;
    return {
      target_cpa: benchmark.target_cpa?.toString() || "",
      target_cpl: benchmark.target_cpl?.toString() || "",
      target_ctr: benchmark.target_ctr?.toString() || "",
      target_cpc: benchmark.target_cpc?.toString() || "",
      target_cpm: benchmark.target_cpm?.toString() || "",
      target_roas: benchmark.target_roas?.toString() || "",
      target_conversion_rate: benchmark.target_conversion_rate?.toString() || "",
      target_frequency: benchmark.target_frequency?.toString() || "",
      is_active: benchmark.is_active ?? true,
    };
  };

  const saveBenchmark = async (
    platform: PlatformType,
    formData: BenchmarkFormData
  ): Promise<boolean> => {
    if (!clientId || !companyId) {
      toast({
        title: "Erro",
        description: "Cliente ou empresa não identificados.",
        variant: "destructive",
      });
      return false;
    }

    try {
      const existingBenchmark = getBenchmarkByPlatform(platform);
      const benchmarkData = formDataToBenchmark(formData);

      if (existingBenchmark) {
        // Update existing
        const { error } = await supabase
          .from('client_metric_benchmarks')
          .update({
            ...benchmarkData,
            updated_at: new Date().toISOString(),
          })
          .eq('id', existingBenchmark.id);

        if (error) throw error;
      } else {
        // Insert new
        const { error } = await supabase
          .from('client_metric_benchmarks')
          .insert({
            client_id: clientId,
            company_id: companyId,
            platform,
            ...benchmarkData,
          });

        if (error) throw error;
      }

      await fetchBenchmarks();
      return true;
    } catch (error: unknown) {
      console.error('Error saving benchmark:', error);
      toast({
        title: "Erro ao salvar métricas",
        description: error.message || "Tente novamente.",
        variant: "destructive",
      });
      return false;
    }
  };

  const saveBothBenchmarks = async (
    metaFormData: BenchmarkFormData,
    googleFormData: BenchmarkFormData
  ): Promise<boolean> => {
    if (!clientId || !companyId) return false;

    try {
      // Save Meta Ads benchmark
      const metaSuccess = await saveBenchmark('meta_ads', metaFormData);
      if (!metaSuccess) return false;

      // Save Google Ads benchmark
      const googleSuccess = await saveBenchmark('google_ads', googleFormData);
      if (!googleSuccess) return false;

      toast({
        title: "Métricas salvas",
        description: "As métricas ideais foram salvas com sucesso.",
      });

      return true;
    } catch (error: unknown) {
      console.error('Error saving benchmarks:', error);
      return false;
    }
  };

  return {
    benchmarks,
    loading,
    getBenchmarkByPlatform,
    benchmarkToFormData,
    saveBenchmark,
    saveBothBenchmarks,
    refetch: fetchBenchmarks,
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { useCompany } from "@/contexts/CompanyContext";
import { Client, ClientStatus, calculateClientStatus } from "@/hooks/useClients";

export interface ClientCampaign {
  id: string;
  name: string;
  platforms: string;
  status: 'active' | 'paused' | 'finished' | 'deleted';
  is_active: boolean;
  ctr: number;
  cpc: number;
  cpa: number; // Custo por Aquisição/Conversão
  conversions: number;
  spend: number; // Custo Total da Campanha
  impressions?: number;
  reach?: number;
  frequency?: number;
  quality_ranking?: string;
  engagement_rate_ranking?: string;
  conversion_rate_ranking?: string;
  clicks?: number;
  objective?: string; // Objetivo da campanha (LEAD_GENERATION, REACH, etc.)
  facebook_id?: string; // ID da campanha no Facebook/Meta
  daily_budget?: number; // Orçamento diário
  lifetime_budget?: number; // Orçamento vitalício
  created_at: string;
  last_synced_at?: string;
  deleted_at?: string;
}

export interface ClientDetailsData extends Client {
  campaigns: ClientCampaign[];
  statusExplanation?: string;
  facebook_ad_accounts?: {
    id: string;
    account_name: string;
    balance: number;
    currency: string;
    account_status: number;
    disable_reason?: string;
    has_funding_issues: boolean;
    last_balance_check?: string;
    is_prepaid: boolean;
    funding_source_details?: unknown;
    is_restricted?: boolean;
    restriction_reason?: string;
    can_advertise?: boolean;
  };
  facebook_page?: {
    id: string;
    page_id: string;
    page_name: string;
    page_category: string | null;
  };
  instagram_account?: {
    id: string;
    instagram_id: string;
    username: string;
    profile_picture_url: string | null;
    followers_count: number;
  };
  google_ads_account?: {
    id: string;
    google_customer_id: string;
    account_name: string;
    parent_customer_id: string | null;
    status: string;
    is_manager: boolean;
  };
}

export function useClientDetails(clientId: string) {
  const [client, setClient] = useState<ClientDetailsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { activeCompany } = useCompany();

  const fetchClientDetails = async () => {
    if (!user || !activeCompany || !clientId) return;

    try {
      setLoading(true);
      setError(null);

      // Fetch client data with ad account information
      const { data: clientData, error: clientError } = await supabase
        .from("clients")
        .select(`
          *,
          facebook_ad_accounts!ad_account_id (
            id,
            account_name,
            balance,
            currency,
            account_status,
            disable_reason,
            has_funding_issues,
            last_balance_check,
            is_prepaid,
            funding_source_details,
            is_restricted,
            restriction_reason,
            can_advertise
          ),
          facebook_page:facebook_pages!facebook_page_id (
            id,
            page_id,
            page_name,
            page_category
          ),
          instagram_account:instagram_accounts!instagram_account_id (
            id,
            instagram_id,
            username,
            profile_picture_url,
            followers_count
          ),
          google_ads_account:google_ads_accounts!google_account_id (
            id,
            google_customer_id,
            account_name,
            parent_customer_id,
            status,
            is_manager
          )
        `)
        .eq("id", clientId)
        .eq("company_id", activeCompany.company_id)
        .maybeSingle();

      if (clientError) throw clientError;

      if (!clientData) {
        setError("Cliente não encontrado");
        return;
      }

      // Fetch campaigns for this client
      const { data: campaignsData, error: campaignsError } = await supabase
        .from("campaigns")
        .select("*")
        .eq("client_id", clientId)
        .eq("company_id", activeCompany.company_id)
        .order("created_at", { ascending: false });

      if (campaignsError) throw campaignsError;


      // Combine client and campaigns data and calculate status
      const { status, explanation } = await calculateClientStatus(clientId, activeCompany.company_id);
      const clientWithCampaigns: ClientDetailsData = {
        ...clientData,
        campaigns: campaignsData || [],
        status, // This is already ClientStatus from calculateClientStatus
        statusExplanation: explanation
      };


      setClient(clientWithCampaigns);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao buscar detalhes do cliente");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchClientDetails();
  }, [clientId, user?.id, activeCompany?.company_id]);

  // Listen for refresh events
  useEffect(() => {
    const handleRefresh = () => {
      fetchClientDetails();
    };

    window.addEventListener('refreshClientDetails', handleRefresh);
    return () => window.removeEventListener('refreshClientDetails', handleRefresh);
  }, [clientId, user?.id, activeCompany?.company_id]);

  return {
    client,
    loading,
    error,
    refetch: fetchClientDetails
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { useCompany } from "@/contexts/CompanyContext";
import { useToast } from "./use-toast";

export interface RuleCondition {
  field: string;
  operator: "<" | ">" | "=" | "!=" | ">=" | "<=";
  value: number | boolean | string;
  type: "number" | "boolean" | "string";
}

export interface RuleConditions {
  logic: "AND" | "OR";
  conditions: RuleCondition[];
}

export interface ClientStatusRule {
  id: string;
  company_id: string;
  rule_name: string;
  rule_order: number;
  status_output: "excelente" | "atencao" | "emergencial" | "inativo" | "sem_fundos";
  conditions: RuleConditions;
  is_active: boolean;
  is_default: boolean;
  created_at: string;
  updated_at: string;
}

export const useClientStatusRules = () => {
  const [rules, setRules] = useState<ClientStatusRule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { activeCompany } = useCompany();
  const { toast } = useToast();

  const fetchRules = async () => {
    if (!user || !activeCompany?.company_id) return;

    try {
      setLoading(true);
      setError(null);

      const { data, error: fetchError } = await supabase
        .from("client_status_rules")
        .select("*")
        .eq("company_id", activeCompany.company_id)
        .order("rule_order", { ascending: true });

      if (fetchError) throw fetchError;

      setRules((data || []) as unknown as ClientStatusRule[]);
    } catch (err: unknown) {
      console.error("Error fetching rules:", err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRules();
  }, [user?.id, activeCompany?.company_id]);

  const createRule = async (ruleData: Omit<ClientStatusRule, "id" | "created_at" | "updated_at" | "company_id">) => {
    if (!activeCompany?.company_id) return null;

    try {
      const { data, error: createError } = await supabase
        .from("client_status_rules")
        .insert({
          ...ruleData,
          company_id: activeCompany.company_id,
          conditions: ruleData.conditions as unknown,
        })
        .select()
        .single();

      if (createError) throw createError;

      toast({
        title: "Regra criada",
        description: "A regra foi criada com sucesso.",
      });

      await fetchRules();
      return data;
    } catch (err: unknown) {
      console.error("Error creating rule:", err);
      toast({
        title: "Erro ao criar regra",
        description: err.message,
        variant: "destructive",
      });
      return null;
    }
  };

  const updateRule = async (id: string, updates: Partial<ClientStatusRule>) => {
    try {
      const updateData = {
        ...updates,
        conditions: updates.conditions ? (updates.conditions as unknown) : undefined,
      };

      const { error: updateError } = await supabase
        .from("client_status_rules")
        .update(updateData)
        .eq("id", id);

      if (updateError) throw updateError;

      toast({
        title: "Regra atualizada",
        description: "A regra foi atualizada com sucesso.",
      });

      await fetchRules();
    } catch (err: unknown) {
      console.error("Error updating rule:", err);
      toast({
        title: "Erro ao atualizar regra",
        description: err.message,
        variant: "destructive",
      });
    }
  };

  const deleteRule = async (id: string) => {
    try {
      const { error: deleteError } = await supabase
        .from("client_status_rules")
        .delete()
        .eq("id", id);

      if (deleteError) throw deleteError;

      toast({
        title: "Regra excluída",
        description: "A regra foi excluída com sucesso.",
      });

      await fetchRules();
    } catch (err: unknown) {
      console.error("Error deleting rule:", err);
      toast({
        title: "Erro ao excluir regra",
        description: err.message,
        variant: "destructive",
      });
    }
  };

  const reorderRules = async (newOrder: { id: string; rule_order: number }[]) => {
    try {
      // Primeiro, mover todas para valores temporários negativos para evitar conflito de constraint
      for (let i = 0; i < newOrder.length; i++) {
        const { error: tempError } = await supabase
          .from("client_status_rules")
          .update({ rule_order: -(i + 1000) })
          .eq("id", newOrder[i].id);

        if (tempError) throw tempError;
      }

      // Agora aplicar a ordem final
      for (const { id, rule_order } of newOrder) {
        const { error: updateError } = await supabase
          .from("client_status_rules")
          .update({ rule_order })
          .eq("id", id);

        if (updateError) throw updateError;
      }

      toast({
        title: "Ordem atualizada",
        description: "A ordem das regras foi atualizada com sucesso.",
      });

      await fetchRules();
    } catch (err: unknown) {
      console.error("Error reordering rules:", err);
      toast({
        title: "Erro ao reordenar regras",
        description: err.message,
        variant: "destructive",
      });
    }
  };

  const restoreDefaults = async () => {
    if (!activeCompany?.company_id) return;

    try {
      // Delete all non-default rules
      const { error: deleteError } = await supabase
        .from("client_status_rules")
        .delete()
        .eq("company_id", activeCompany.company_id)
        .eq("is_default", false);

