        .from("client_status_rules")
        .insert(defaultRules.map(r => ({ ...r, conditions: r.conditions as unknown })));

      if (insertError) throw insertError;

      toast({
        title: "Regras restauradas",
        description: "As regras padrão foram restauradas com sucesso.",
      });

      await fetchRules();
    } catch (err: unknown) {
      console.error("Error restoring defaults:", err);
      toast({
        title: "Erro ao restaurar padrões",
        description: err.message,
        variant: "destructive",
      });
    }
  };

  return {
    rules,
    loading,
    error,
    fetchRules,
    createRule,
    updateRule,
    deleteRule,
    reorderRules,
    restoreDefaults,
  };
};

import { useState, useCallback } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

export type ValidationStatus = 'ok' | 'error' | 'timeout' | 'redirect' | 'pending' | null;

export interface ClientUrl {
  id: string;
  client_id: string;
  company_id: string;
  url: string;
  domain: string;
  source: 'manual' | 'meta_sync' | 'google_sync';
  label: string | null;
  is_active: boolean;
  first_seen_at: string;
  last_seen_at: string;
  campaign_count: number;
  created_at: string;
  updated_at: string;
  // Validation fields
  last_validated_at: string | null;
  validation_status: ValidationStatus;
  validation_status_code: number | null;
  validation_load_time_ms: number | null;
  validation_error: string | null;
  validation_final_url: string | null;
}

interface UseClientUrlsOptions {
  clientId: string;
  companyId: string;
}

export function useClientUrls({ clientId, companyId }: UseClientUrlsOptions) {
  const queryClient = useQueryClient();
  const queryKey = ['client-urls', clientId];

  // Fetch URLs for client
  const { data: urls = [], isLoading, refetch } = useQuery({
    queryKey,
    queryFn: async () => {
      const { data, error } = await supabase
        .from('client_urls')
        .select('*')
        .eq('client_id', clientId)
        .order('domain', { ascending: true })
        .order('last_seen_at', { ascending: false });

      if (error) throw error;
      return data as ClientUrl[];
    },
    enabled: !!clientId,
  });

  // Add URL mutation
  const addUrlMutation = useMutation({
    mutationFn: async ({ url, label }: { url: string; label?: string }) => {
      // Parse URL to get domain
      const urlObj = new URL(url);
      const domain = urlObj.hostname.replace(/^www\./, '');
      const cleanUrl = url.split('?')[0]; // Remove query params

      const { data, error } = await supabase
        .from('client_urls')
        .insert({
          client_id: clientId,
          company_id: companyId,
          url: cleanUrl,
          domain,
          source: 'manual',
          label: label || null,
          is_active: true,
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success('URL adicionada com sucesso');
    },
    onError: (error: unknown) => {
      if (error.code === '23505') {
        toast.error('Esta URL já está cadastrada para este cliente');
      } else {
        toast.error('Erro ao adicionar URL');
      }
    },
  });

  // Update URL mutation
  const updateUrlMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<ClientUrl> }) => {
      const { data: updated, error } = await supabase
        .from('client_urls')
        .update(data)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return updated;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success('URL atualizada');
    },
    onError: () => {
      toast.error('Erro ao atualizar URL');
    },
  });

  // Delete URL mutation
  const deleteUrlMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase
        .from('client_urls')
        .delete()
        .eq('id', id);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success('URL removida');
    },
    onError: () => {
      toast.error('Erro ao remover URL');
    },
  });

  // Toggle active state
  const toggleActive = useCallback(async (id: string) => {
    const url = urls.find(u => u.id === id);
    if (url) {
      await updateUrlMutation.mutateAsync({ 
        id, 
        data: { is_active: !url.is_active } 
      });
    }
  }, [urls, updateUrlMutation]);

  // Import existing URLs from ads tables
  const importExistingUrls = useCallback(async () => {
    try {
      // Fetch URLs from Meta Ads
      const { data: metaAds, error: metaError } = await supabase
        .from('ads')
        .select('link_url')
        .eq('client_id', clientId)
        .not('link_url', 'is', null)
        .not('link_url', 'eq', '');

      if (metaError) throw metaError;

      // Fetch URLs from Google Ads
      const { data: googleAds, error: googleError } = await supabase
        .from('google_ads')
        .select('final_url')
        .eq('client_id', clientId)
        .not('final_url', 'is', null)
        .not('final_url', 'eq', '');

      if (googleError) throw googleError;

      // Combine and deduplicate URLs
      const urlSet = new Map<string, { url: string; source: string }>();

      metaAds?.forEach(ad => {
        if (ad.link_url) {
          const cleanUrl = ad.link_url.split('?')[0];
          if (!urlSet.has(cleanUrl)) {
            urlSet.set(cleanUrl, { url: cleanUrl, source: 'meta_sync' });
          }
        }
      });

      googleAds?.forEach(ad => {
        if (ad.final_url) {
          const cleanUrl = ad.final_url.split('?')[0];
          if (!urlSet.has(cleanUrl)) {
            urlSet.set(cleanUrl, { url: cleanUrl, source: 'google_sync' });
          }
        }
      });

      let importedCount = 0;
      let skippedCount = 0;

      // Insert each URL using RPC function
      for (const [cleanUrl, { source }] of urlSet) {
        try {
          const urlObj = new URL(cleanUrl);
          const domain = urlObj.hostname.replace(/^www\./, '');

          const { error } = await supabase.rpc('upsert_client_url', {
            p_client_id: clientId,
            p_company_id: companyId,
            p_url: cleanUrl,
            p_domain: domain,
            p_source: source
          });

          if (error) {
            skippedCount++;
          } else {
            importedCount++;
          }
        } catch {
          skippedCount++;
        }
      }

      queryClient.invalidateQueries({ queryKey });

      if (importedCount > 0) {
        toast.success(`${importedCount} URL(s) importada(s) com sucesso`);
      } else if (urlSet.size === 0) {
        toast.info('Nenhuma URL encontrada nos anúncios sincronizados');
      } else {
        toast.info('Todas as URLs já estavam cadastradas');
      }

      return { imported: importedCount, skipped: skippedCount };
    } catch (error) {
      console.error('Error importing URLs:', error);
      toast.error('Erro ao importar URLs');
      throw error;
    }
  }, [clientId, companyId, queryClient, queryKey]);

  // Group URLs by domain
  const urlsByDomain = urls.reduce((acc, url) => {
    if (!acc[url.domain]) {
      acc[url.domain] = [];
    }
    acc[url.domain].push(url);
    return acc;
  }, {} as Record<string, ClientUrl[]>);

  // Validate URLs mutation
  const validateUrlsMutation = useMutation({
    mutationFn: async (urlIds?: string[]) => {
      const payload = urlIds ? { url_ids: urlIds } : { client_id: clientId };

      const { data, error } = await supabase.functions.invoke('validate-client-urls', {
        body: payload
      });

      if (error) throw error;
      return data;
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey });
      const count = data?.results?.length || 0;
      toast.success(`${count} URL(s) validada(s)`);
    },
    onError: (error: unknown) => {
      console.error('Validation error:', error);
      toast.error('Erro ao validar URLs');
    },
  });

  // Validate single URL
  const validateUrl = useCallback(async (urlId: string) => {
    return validateUrlsMutation.mutateAsync([urlId]);
  }, [validateUrlsMutation]);

  // Validate all active URLs
  const validateAllUrls = useCallback(async () => {
    return validateUrlsMutation.mutateAsync(undefined);
  }, [validateUrlsMutation]);

  return {
    urls,
    urlsByDomain,
    loading: isLoading,
    addUrl: (url: string, label?: string) => addUrlMutation.mutateAsync({ url, label }),
    updateUrl: (id: string, data: Partial<ClientUrl>) => updateUrlMutation.mutateAsync({ id, data }),
    deleteUrl: (id: string) => deleteUrlMutation.mutateAsync(id),
    toggleActive,
    importExistingUrls,
    validateUrl,
    validateAllUrls,
    refetch,
    isAdding: addUrlMutation.isPending,
    isUpdating: updateUrlMutation.isPending,
    isDeleting: deleteUrlMutation.isPending,
    isValidating: validateUrlsMutation.isPending,
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { useToast } from "./use-toast";

export interface Company {
  id: string;
  name: string;
  slug?: string;
  logo?: string;
  email?: string;
  phone?: string;
  created_by: string;
  created_at: string;
  updated_at: string;
}

export interface CompanyMember {
  id: string;
  user_id: string;
  company_id: string;
  role: string;
  joined_at: string;
  company?: Company;
}

export const useCompanies = () => {
  const [companies, setCompanies] = useState<CompanyMember[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { toast } = useToast();

  const fetchUserCompanies = async () => {
    if (!user?.id) return;

    try {
      setLoading(true);
      setError(null);

      const { data, error } = await supabase
        .from("company_members")
        .select(`
          *,
          company:companies (*)
        `)
        .eq("user_id", user.id);

      if (error) throw error;

      setCompanies(data || []);
    } catch (error: unknown) {
      console.error("Error fetching companies:", error);
      setError(error.message);
      toast({
        title: "Erro ao carregar empresas",
        description: error.message,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const createCompany = async (companyData: {
    name: string;
    slug?: string;
    logo?: string;
  }) => {
    if (!user?.id) throw new Error("User not authenticated");

    try {
      const { data, error } = await supabase
        .from("companies")
        .insert({
          ...companyData,
          created_by: user.id,
        })
        .select()
        .single();

      if (error) throw error;

      toast({
        title: "Empresa criada!",
        description: `${companyData.name} foi criada com sucesso.`,
      });

      // Refresh the companies list
      await fetchUserCompanies();

      return data;
    } catch (error: unknown) {
      console.error("Error creating company:", error);
      toast({
        title: "Erro ao criar empresa",
        description: error.message,
        variant: "destructive",
      });
      throw error;
    }
  };

  const updateCompany = async (id: string, updates: Partial<Company>) => {
    try {
      const { data, error } = await supabase
        .from("companies")
        .update(updates)
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;

      toast({
        title: "Empresa atualizada!",
        description: "As informações da empresa foram atualizadas.",
      });

      await fetchUserCompanies();
      return data;
    } catch (error: unknown) {
      console.error("Error updating company:", error);
      toast({
        title: "Erro ao atualizar empresa",
        description: error.message,
        variant: "destructive",
      });
      throw error;
    }
  };

  useEffect(() => {
    fetchUserCompanies();
  }, [user?.id]);

  return {
    companies,
    loading,
    error,
    fetchUserCompanies,
    createCompany,
    updateCompany,
  };
};

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useCompany } from "@/contexts/CompanyContext";
import { toast } from "sonner";

/**
 * IMPORTANT:
 * CompanyContext.activeCompany is a CompanyMember.
 * - activeCompany.id is the company_members row id
 * - activeCompany.company_id is the companies.id
 */
export function useCompanyTvDashboardToken() {
  const { activeCompany } = useCompany();

  const companyId = activeCompany?.company_id ?? null;
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    if (companyId) {
      void fetchToken(companyId);
    } else {
      setToken(null);
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [companyId]);

  const fetchToken = async (id: string) => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("companies")
        .select("tv_dashboard_token")
        .eq("id", id)
        .maybeSingle();

      if (error) throw error;
      setToken(data?.tv_dashboard_token ?? null);
    } catch (error) {
      console.error("Error fetching TV dashboard token:", error);
      setToken(null);
    } finally {
      setLoading(false);
    }
  };

  const generateToken = async (): Promise<string | null> => {
    if (!companyId) return null;

    setGenerating(true);
    try {
      const { data: tokenData, error: tokenError } = await supabase.rpc(
        "generate_tv_dashboard_token"
      );
      if (tokenError) throw tokenError;

      const newToken = tokenData as string;

      const { error: setError } = await supabase.rpc("set_tv_dashboard_token", {
        p_company_id: companyId,
        p_token: newToken,
      });
      if (setError) throw setError;

      setToken(newToken);
      toast.success("Token do Dashboard TV gerado com sucesso!");
      return newToken;
    } catch (error) {
      console.error("Error generating TV dashboard token:", error);
      toast.error("Erro ao gerar token do Dashboard TV");
      return null;
    } finally {
      setGenerating(false);
    }
  };

  const regenerateToken = async (): Promise<string | null> => generateToken();

  const getPublicUrl = () => {
    if (!token) return null;
    return `${window.location.origin}/tv/${token}`;
  };

  return {
    token,
    loading,
    generating,
    generateToken,
    regenerateToken,
    getPublicUrl,
    refetch: () => (companyId ? fetchToken(companyId) : Promise.resolve()),
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { useCompany } from '@/contexts/CompanyContext';
import { toast } from 'sonner';

export interface Competitor {
  id: string;
  client_id: string;
  company_id: string;
  user_id: string;
  name: string;
  company_name: string;
  facebook_page_name?: string;
  instagram_handle?: string;
  website_url?: string;
  industry?: string;
  description?: string;
  ad_library_url?: string;
  last_scrape_at?: string;
  created_at: string;
  updated_at: string;
}

export interface CompetitorAd {
  id: string;
  competitor_id: string;
  client_id: string;
  company_id: string;
  user_id: string;
  platform: string;
  ad_title?: string;
  ad_description?: string;
  ad_copy?: string;
  call_to_action?: string;
  image_url?: string;
  video_url?: string;
  landing_page_url?: string;
  ad_type?: string;
  estimated_performance?: string;
  notes?: string;
  date_spotted: string;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

export const useCompetitors = (clientId?: string) => {
  const [competitors, setCompetitors] = useState<Competitor[]>([]);
  const [competitorAds, setCompetitorAds] = useState<CompetitorAd[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { activeCompany } = useCompany();

  const fetchCompetitors = async () => {
    if (!user?.id || !activeCompany?.company_id || !clientId) return;

    try {
      setLoading(true);
      const { data, error } = await supabase
        .from('competitors')
        .select('*')
        .eq('client_id', clientId)
        .eq('company_id', activeCompany.company_id)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setCompetitors(data || []);
    } catch (err) {
      console.error('Error fetching competitors:', err);
      setError(err instanceof Error ? err.message : 'Erro ao carregar concorrentes');
    } finally {
      setLoading(false);
    }
  };

  const fetchCompetitorAds = async () => {
    if (!user?.id || !activeCompany?.company_id || !clientId) return;

    try {
      const { data, error } = await supabase
        .from('competitor_ads')
        .select('*')
        .eq('client_id', clientId)
        .eq('company_id', activeCompany.company_id)
        .eq('is_active', true)
        .order('date_spotted', { ascending: false });

      if (error) throw error;
      setCompetitorAds(data || []);
    } catch (err) {
      console.error('Error fetching competitor ads:', err);
    }
  };

  const createCompetitor = async (competitorData: Partial<Competitor>) => {
    if (!user?.id || !activeCompany?.company_id || !clientId) {
      throw new Error('Dados de autenticação não disponíveis');
    }

    // Ensure required fields are present
    if (!competitorData.name || !competitorData.company_name) {
      throw new Error('Nome e empresa do concorrente são obrigatórios');
    }

    const { data, error } = await supabase
      .from('competitors')
      .insert({
        name: competitorData.name,
        company_name: competitorData.company_name,
        facebook_page_name: competitorData.facebook_page_name,
        instagram_handle: competitorData.instagram_handle,
        website_url: competitorData.website_url,
        industry: competitorData.industry,
        description: competitorData.description,
        client_id: clientId,
        company_id: activeCompany.company_id,
        user_id: user.id,
      })
      .select()
      .single();

    if (error) throw error;

    setCompetitors(prev => [data, ...prev]);
    toast.success('Concorrente adicionado com sucesso!');
    return data;
  };

  const updateCompetitor = async (id: string, updates: Partial<Competitor>) => {
    const { data, error } = await supabase
      .from('competitors')
      .update(updates)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

    setCompetitors(prev => prev.map(comp => comp.id === id ? data : comp));
    toast.success('Concorrente atualizado com sucesso!');
    return data;
  };

  const deleteCompetitor = async (id: string) => {
    const { error } = await supabase
      .from('competitors')
      .delete()
      .eq('id', id);

    if (error) throw error;

    setCompetitors(prev => prev.filter(comp => comp.id !== id));
    toast.success('Concorrente removido com sucesso!');
  };

  const createCompetitorAd = async (adData: Partial<CompetitorAd>) => {
    if (!user?.id || !activeCompany?.company_id || !clientId) {
      throw new Error('Dados de autenticação não disponíveis');
    }

    // Ensure required fields are present
    if (!adData.competitor_id) {
      throw new Error('ID do concorrente é obrigatório');
    }

    const { data, error } = await supabase
      .from('competitor_ads')
      .insert({
        competitor_id: adData.competitor_id,
        platform: adData.platform || 'Facebook Ads',
        ad_title: adData.ad_title,
        ad_description: adData.ad_description,
        ad_copy: adData.ad_copy,
        call_to_action: adData.call_to_action,
        image_url: adData.image_url,
        video_url: adData.video_url,
        landing_page_url: adData.landing_page_url,
        ad_type: adData.ad_type,
        estimated_performance: adData.estimated_performance,
        notes: adData.notes,
        date_spotted: adData.date_spotted || new Date().toISOString().split('T')[0],
        client_id: clientId,
        company_id: activeCompany.company_id,
        user_id: user.id,
      })
      .select()
      .single();

    if (error) throw error;

    setCompetitorAds(prev => [data, ...prev]);
    toast.success('Anúncio do concorrente adicionado com sucesso!');
    return data;
  };

  const saveAdLibraryUrl = async (competitorId: string, url: string) => {
    const { data, error } = await supabase
      .from('competitors')
      .update({ 
        ad_library_url: url,
        last_scrape_at: new Date().toISOString()
      })
      .eq('id', competitorId)
      .select()
      .single();

    if (error) throw error;

    setCompetitors(prev => prev.map(comp => comp.id === competitorId ? data : comp));
    return data;
  };

  const updateCompetitorAd = async (id: string, updates: Partial<CompetitorAd>) => {
    const { data, error } = await supabase
      .from('competitor_ads')
      .update(updates)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

    setCompetitorAds(prev => prev.map(ad => ad.id === id ? data : ad));
    toast.success('Anúncio atualizado com sucesso!');
    return data;
  };

  const deleteCompetitorAd = async (id: string) => {
    const { error } = await supabase
      .from('competitor_ads')
      .delete()
      .eq('id', id);

    if (error) throw error;

    setCompetitorAds(prev => prev.filter(ad => ad.id !== id));
    toast.success('Anúncio removido com sucesso!');
  };

  const generateCompetitiveAnalysis = async (clientData: unknown, clientAds: unknown[]) => {
    try {
      const { data, error } = await supabase.functions.invoke('analyze-competitor-insights', {
        body: {
          clientData,
          clientAds,
          competitorData: competitors,
          competitorAds: competitorAds
        }
      });

      if (error) throw error;
      return data.analysis;
    } catch (err) {
      console.error('Error generating competitive analysis:', err);
      throw err;
    }
  };

  useEffect(() => {
    if (clientId) {
      fetchCompetitors();
      fetchCompetitorAds();
    }
  }, [user?.id, activeCompany?.company_id, clientId]);

  return {
    competitors,
    competitorAds,
    loading,
    error,
    createCompetitor,
    updateCompetitor,
    deleteCompetitor,
    createCompetitorAd,
    updateCompetitorAd,
    deleteCompetitorAd,
    saveAdLibraryUrl,
    generateCompetitiveAnalysis,
    refetch: () => {
      fetchCompetitors();
      fetchCompetitorAds();
    }
  };
};

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { useCompany } from '@/contexts/CompanyContext';
import { useToast } from '@/hooks/use-toast';

export interface ContentGeneration {
  id: string;
  content_type: string;
  theme: string;
  generated_content: string;
  status: string;
  client_id: string;
  user_id: string;
  company_id: string;
  created_at: string;
  updated_at: string;
  clients?: {
    name: string;
    company: string;
  } | null;
}

export function useContentGenerations() {
  const [generations, setGenerations] = useState<ContentGeneration[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { activeCompany } = useCompany();
  const { toast } = useToast();

  const fetchGenerations = async () => {
    if (!user || !activeCompany) return;

    try {
      setLoading(true);
      setError(null);

      const { data, error } = await supabase
        .from('content_generations')
        .select(`
          *,
          clients (
            name,
            company
          )
        `)
        .eq('company_id', activeCompany.company_id)
        .order('created_at', { ascending: false });

      if (error) throw error;

      setGenerations((data as unknown as ContentGeneration[]) || []);
    } catch (err: unknown) {
      setError(err.message);
      toast({
        title: "Erro ao carregar conteúdos",
        description: "Não foi possível carregar os conteúdos gerados.",
        variant: "destructive"
      });
    } finally {
      setLoading(false);
    }
  };

  const deleteGeneration = async (id: string) => {
    try {
      const { error } = await supabase
        .from('content_generations')
        .delete()
        .eq('id', id);

      if (error) throw error;

      setGenerations(prev => prev.filter(gen => gen.id !== id));
      toast({
        title: "Conteúdo deletado",
        description: "O conteúdo foi removido com sucesso."
      });
    } catch (err: unknown) {
      toast({
        title: "Erro ao deletar",
        description: "Não foi possível deletar o conteúdo.",
        variant: "destructive"
      });
    }
  };

  const updateGeneration = async (id: string, updates: Partial<ContentGeneration>) => {
    try {
      const { error } = await supabase
        .from('content_generations')
        .update(updates)
        .eq('id', id);

      if (error) throw error;

      setGenerations(prev =>
        prev.map(gen => gen.id === id ? { ...gen, ...updates } : gen)
      );

      toast({
        title: "Conteúdo atualizado",
        description: "O conteúdo foi atualizado com sucesso."
      });
    } catch (err: unknown) {
      toast({
        title: "Erro ao atualizar",
        description: "Não foi possível atualizar o conteúdo.",
        variant: "destructive"
      });
    }
  };

  useEffect(() => {
    fetchGenerations();
  }, [user, activeCompany]);

  return {
    generations,
    loading,
    error,
    fetchGenerations,
    deleteGeneration,
    updateGeneration
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useCompany } from "@/contexts/CompanyContext";
import { useToast } from "@/hooks/use-toast";
import { contentTypes } from "@/components/content-generator/ContentTypes";

interface ContentPrompt {
