  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { activeCompany } = useCompany();
  const { toast } = useToast();

  const fetchPrompts = async () => {
    if (!activeCompany) return;

    try {
      setLoading(true);
      setError(null);

      const { data, error } = await supabase
        .from('content_prompts')
        .select('*')
        .eq('company_id', activeCompany.company_id)
        .order('content_type');

      if (error) throw error;

      setPrompts(data || []);
    } catch (err) {
      console.error('Error fetching content prompts:', err);
      setError(err instanceof Error ? err.message : 'Erro ao carregar prompts');
    } finally {
      setLoading(false);
    }
  };

  const savePrompt = async (contentType: string, customPrompt: string, defaultPrompt: string) => {
    if (!activeCompany) return;

    try {
      const { data, error } = await supabase
        .from('content_prompts')
        .upsert({
          company_id: activeCompany.company_id,
          content_type: contentType,
          default_prompt: defaultPrompt,
          custom_prompt: customPrompt.trim() || null,
          is_active: true,
        }, {
          onConflict: 'company_id,content_type'
        })
        .select()
        .single();

      if (error) throw error;

      // Update local state
      setPrompts(prev => {
        const existing = prev.find(p => p.content_type === contentType);
        if (existing) {
          return prev.map(p => p.content_type === contentType ? data : p);
        } else {
          return [...prev, data];
        }
      });

      toast({
        title: "Prompt salvo",
        description: "As alterações foram aplicadas com sucesso.",
      });

      return data;
    } catch (err) {
      console.error('Error saving prompt:', err);
      toast({
        title: "Erro ao salvar",
        description: "Não foi possível salvar o prompt. Tente novamente.",
        variant: "destructive",
      });
      throw err;
    }
  };

  const resetPrompt = async (contentType: string) => {
    if (!activeCompany) return;

    try {
      const { error } = await supabase
        .from('content_prompts')
        .delete()
        .eq('company_id', activeCompany.company_id)
        .eq('content_type', contentType);

      if (error) throw error;

      // Update local state
      setPrompts(prev => prev.filter(p => p.content_type !== contentType));

      toast({
        title: "Prompt resetado",
        description: "O prompt foi restaurado para o padrão.",
      });
    } catch (err) {
      console.error('Error resetting prompt:', err);
      toast({
        title: "Erro ao resetar",
        description: "Não foi possível resetar o prompt. Tente novamente.",
        variant: "destructive",
      });
      throw err;
    }
  };

  const getPromptForContentType = (contentType: string) => {
    const customPrompt = prompts.find(p => p.content_type === contentType);
    return customPrompt?.custom_prompt || null;
  };

  const isCustomized = (contentType: string) => {
    const prompt = prompts.find(p => p.content_type === contentType);
    return prompt && prompt.custom_prompt && prompt.custom_prompt.trim().length > 0;
  };

  const getAllPromptsWithStatus = () => {
    return contentTypes.map(contentType => ({
      ...contentType,
      isCustomized: isCustomized(contentType.id),
      customPrompt: getPromptForContentType(contentType.id),
    }));
  };

  useEffect(() => {
    fetchPrompts();
  }, [activeCompany]);

  return {
    prompts,
    loading,
    error,
    savePrompt,
    resetPrompt,
    getPromptForContentType,
    isCustomized,
    getAllPromptsWithStatus,
    refetch: fetchPrompts,
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useCompany } from '@/contexts/CompanyContext';
import { toast } from 'sonner';

export function useCsTvDashboardToken() {
  const { activeCompany } = useCompany();
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    if (activeCompany?.company_id) {
      fetchToken();
    }
  }, [activeCompany?.company_id]);

  const fetchToken = async () => {
    if (!activeCompany?.company_id) return;

    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('companies')
        .select('cs_tv_dashboard_token')
        .eq('id', activeCompany.company_id)
        .single();

      if (error) throw error;
      setToken((data as unknown)?.cs_tv_dashboard_token || null);
    } catch (error) {
      console.error('Error fetching CS TV dashboard token:', error);
    } finally {
      setLoading(false);
    }
  };

  const generateToken = async (): Promise<string | null> => {
    if (!activeCompany?.company_id) return null;

    setGenerating(true);
    try {
      // Generate token using database function
      const { data: tokenData, error: tokenError } = await (supabase
        .rpc as unknown)('generate_cs_tv_dashboard_token');

      if (tokenError) {
        console.error('Error generating token via RPC:', tokenError);
        throw tokenError;
      }

      const newToken = tokenData as string;

      // Use secure RPC to set the token
      const { error: setError } = await (supabase
        .rpc as unknown)('set_cs_tv_dashboard_token', {
          p_company_id: activeCompany.company_id,
          p_token: newToken
        });

      if (setError) {
        console.error('Error setting token via RPC:', setError);
        throw setError;
      }

      setToken(newToken);
      toast.success('Token do CS TV gerado com sucesso!');
      return newToken;
    } catch (error) {
      console.error('Error generating CS TV dashboard token:', error);
      toast.error('Erro ao gerar token do CS TV');
      return null;
    } finally {
      setGenerating(false);
    }
  };

  const regenerateToken = async (): Promise<string | null> => {
    return generateToken();
  };

  const getPublicUrl = () => {
    if (!token) return null;
    return `${window.location.origin}/cs-tv/${token}`;
  };

  return {
    token,
    loading,
    generating,
    generateToken,
    regenerateToken,
    getPublicUrl,
    refetch: fetchToken
  };
}

import { useState, useEffect, useMemo } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from './useAuth';
import { useCompany } from '@/contexts/CompanyContext';

interface DashboardMetrics {
  totalInvestment: number;
  totalLeads: number;
  averageCPA: number;
  averageCTR: number;
  activeClients: number;
  pausedClients: number;
  previousPeriodInvestment: number;
  previousPeriodLeads: number;
  previousPeriodCPA: number;
  previousPeriodCTR: number;
}

interface ClientPerformance {
  id: string;
  name: string;
  company: string;
  totalInvestment: number;
  investment: number;
  totalLeads: number;
  leads_generated: number;
  active_campaigns: number;
  averageCPA: number;
  avg_cpl: number;
  status: string;
}

interface CampaignRanking {
  id: string;
  name: string;
  client_name: string;
  cpa: number;
  conversions: number;
  spend: number;
  ctr: number;
  status: string;
}

interface FunnelMetrics {
  reach: number;
  leads: number;
  clicks: number;
  cpl: number;
  cpa: number;
}


interface TrendData {
  date: string;
  cpl: number;
  leads: number;
  investment: number;
}

export const useDashboardData = () => {
  const [metrics, setMetrics] = useState<DashboardMetrics | null>(null);
  const [clientsPerformance, setClientsPerformance] = useState<ClientPerformance[]>([]);
  const [campaignRankings, setCampaignRankings] = useState<CampaignRanking[]>([]);
  const [funnelMetrics, setFunnelMetrics] = useState<FunnelMetrics | null>(null);

  const [trends, setTrends] = useState<TrendData[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [clientFilter, setClientFilter] = useState<string | null>(null);

  const { user } = useAuth();
  const { activeCompany } = useCompany();

  const fetchDashboardData = async (filterClientId?: string | null) => {
    if (!user || !activeCompany) return;

    try {
      setLoading(true);

      // Buscar dados dos últimos 30 dias
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

      const sixtyDaysAgo = new Date();
      sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);

      // 1. Métricas principais (últimos 30 dias vs período anterior) - Meta Campaigns
      const { data: currentPeriodCampaigns } = await supabase
        .from('campaigns')
        .select(`
          *,
          clients!inner(name, company, status)
        `)
        .eq('company_id', activeCompany.company_id)
        .gte('created_at', thirtyDaysAgo.toISOString());

      const { data: previousPeriodCampaigns } = await supabase
        .from('campaigns')
        .select('*')
        .eq('company_id', activeCompany.company_id)
        .gte('created_at', sixtyDaysAgo.toISOString())
        .lt('created_at', thirtyDaysAgo.toISOString());

      // 1b. Google Campaigns (últimos 30 dias vs período anterior)
      const { data: currentGoogleCampaigns } = await supabase
        .from('google_campaigns')
        .select(`
          *,
          clients!inner(name, company, status)
        `)
        .eq('company_id', activeCompany.company_id)
        .gte('created_at', thirtyDaysAgo.toISOString());

      const { data: previousGoogleCampaigns } = await supabase
        .from('google_campaigns')
        .select('*')
        .eq('company_id', activeCompany.company_id)
        .gte('created_at', sixtyDaysAgo.toISOString())
        .lt('created_at', thirtyDaysAgo.toISOString());

      // 2. Performance por cliente (incluindo Google Campaigns)
      const { data: clientsData } = await supabase
        .from('clients')
        .select(`
          *,
          campaigns(spend, conversions, cpa, status),
          google_campaigns(spend, conversions, cost_per_conversion, status)
        `)
        .eq('company_id', activeCompany.company_id);

      // 3. Ranking de campanhas
      const { data: allCampaigns } = await supabase
        .from('campaigns')
        .select(`
          *,
          clients!inner(name, company)
        `)
        .eq('company_id', activeCompany.company_id)
        .order('cpa', { ascending: true });

      // 4. Dados de tendência (últimos 30 dias)
      const { data: trendsData } = await supabase
        .from('campaigns')
        .select('created_at, spend, conversions, cpa')
        .eq('company_id', activeCompany.company_id)
        .gte('created_at', thirtyDaysAgo.toISOString())
        .order('created_at', { ascending: true });

      // Combinar Meta + Google campaigns
      const allCurrentCampaigns = [
        ...(currentPeriodCampaigns || []),
        ...(currentGoogleCampaigns || [])
      ];
      const allPreviousCampaigns = [
        ...(previousPeriodCampaigns || []),
        ...(previousGoogleCampaigns || [])
      ];

      // Processar métricas principais (Meta + Google combinados)
      const currentMetrics = calculateMetrics(allCurrentCampaigns);
      const previousMetrics = calculateMetrics(allPreviousCampaigns);

      const processedMetrics: DashboardMetrics = {
        ...currentMetrics,
        previousPeriodInvestment: previousMetrics.totalInvestment,
        previousPeriodLeads: previousMetrics.totalLeads,
        previousPeriodCPA: previousMetrics.averageCPA,
        previousPeriodCTR: previousMetrics.averageCTR,
      };

      // Processar performance por cliente
      const processedClients = processClientsPerformance(clientsData || []);

      // Processar ranking de campanhas
      const processedCampaigns = processCampaignRankings(allCampaigns || []);

      // Calcular métricas do funil
      const processedFunnel = calculateFunnelMetrics(currentPeriodCampaigns || []);

      // Remover geração automática de alertas - será feita apenas pelo hook useDashboardAlerts

      // Processar tendências
      const processedTrends = processTrendsData(trendsData || []);

      setMetrics(processedMetrics);
      setClientsPerformance(processedClients);
      setCampaignRankings(processedCampaigns);
      setFunnelMetrics(processedFunnel);
      setTrends(processedTrends);

    } catch (err) {
      console.error('Error fetching dashboard data:', err);
      setError(err instanceof Error ? err.message : 'Erro ao carregar dados do dashboard');
    } finally {
      setLoading(false);
    }
  };

  // Função para calcular métricas de um conjunto de campanhas
  const calculateMetrics = (campaigns: unknown[]) => {
    const totalInvestment = campaigns.reduce((sum, c) => sum + (c.spend || 0), 0);
    const totalLeads = campaigns.reduce((sum, c) => sum + (c.conversions || 0), 0);
    const averageCPA = totalLeads > 0 ? totalInvestment / totalLeads : 0;

    // Calcular CTR usando dados reais
    const totalClicks = campaigns.reduce((sum, c) => sum + (c.clicks || 0), 0);
    const totalImpressions = campaigns.reduce((sum, c) => sum + (c.impressions || 0), 0);
    const averageCTR = totalImpressions > 0 ? (totalClicks / totalImpressions) * 100 : 0;

    // Contar clientes ativos vs pausados
    const clientStatuses = campaigns.reduce((acc, c) => {
      if (c.clients) {
        acc[c.clients.status] = (acc[c.clients.status] || 0) + 1;
      }
      return acc;
    }, {});

    return {
      totalInvestment,
      totalLeads,
      averageCPA,
      averageCTR,
      activeClients: clientStatuses.green || 0,
      pausedClients: (clientStatuses.yellow || 0) + (clientStatuses.red || 0),
    };
  };

  // Função para processar performance dos clientes (Meta + Google combinados)
  const processClientsPerformance = (clients: unknown[]): ClientPerformance[] => {
    return clients.map(client => {
      // Meta campaigns
      const metaInvestment = client.campaigns?.reduce((sum: number, c: unknown) => sum + (c.spend || 0), 0) || 0;
      const metaLeads = client.campaigns?.reduce((sum: number, c: unknown) => sum + (c.conversions || 0), 0) || 0;
      const metaActiveCampaigns = client.campaigns?.filter((c: unknown) => c.status === 'active').length || 0;

      // Google campaigns
      const googleInvestment = client.google_campaigns?.reduce((sum: number, c: unknown) => sum + (c.spend || 0), 0) || 0;
      const googleLeads = client.google_campaigns?.reduce((sum: number, c: unknown) => sum + (c.conversions || 0), 0) || 0;
      const googleActiveCampaigns = client.google_campaigns?.filter((c: unknown) => c.status === 'ENABLED').length || 0;

      // Totais combinados
      const totalInvestment = metaInvestment + googleInvestment;
      const totalLeads = metaLeads + googleLeads;
      const averageCPA = totalLeads > 0 ? totalInvestment / totalLeads : 0;

      return {
        id: client.id,
        name: client.name,
        company: client.company,
        totalInvestment,
        investment: totalInvestment,
        totalLeads,
        leads_generated: totalLeads,
        active_campaigns: metaActiveCampaigns + googleActiveCampaigns,
        averageCPA,
        avg_cpl: averageCPA,
        status: client.status,
      };
    }).sort((a, b) => b.totalInvestment - a.totalInvestment);
  };

  // Função para processar ranking de campanhas
  const processCampaignRankings = (campaigns: unknown[]): CampaignRanking[] => {
    return campaigns
      .filter(c => c.conversions > 0) // Só campanhas com conversões
      .map(campaign => ({
        id: campaign.id,
        name: campaign.name,
        client_name: campaign.clients?.name || 'Cliente não encontrado',
        cpa: campaign.cpa || 0,
        conversions: campaign.conversions || 0,
        spend: campaign.spend || 0,
        ctr: campaign.ctr || 0,
        status: campaign.status || 'unknown',
      }));
  };

  // Função para calcular métricas do funil
  const calculateFunnelMetrics = (campaigns: unknown[]): FunnelMetrics => {
    const totalReach = campaigns.reduce((sum, c) => sum + (c.reach || 0), 0);
    const totalLeads = campaigns.reduce((sum, c) => sum + (c.conversions || 0), 0);
    const totalClicks = campaigns.reduce((sum, c) => sum + (c.clicks || 0), 0);
    const totalSpend = campaigns.reduce((sum, c) => sum + (c.spend || 0), 0);

    return {
      reach: totalReach,
      leads: totalLeads,
      clicks: totalClicks,
      cpl: totalLeads > 0 ? totalSpend / totalLeads : 0,
      cpa: totalLeads > 0 ? totalSpend / totalLeads : 0, // CPA igual ao CPL neste contexto
    };
  };

  // Função para gerar recomendação com ChatGPT
  const generateRecommendation = async (campaignData: unknown, issueType: string) => {
    try {
      const { data, error } = await supabase.functions.invoke('generate-campaign-recommendation', {
        body: {
          campaignData: {
            name: campaignData.name,
            client_name: campaignData.client_name,
            cpa: campaignData.cpa,
            ctr: campaignData.ctr,
            conversions: campaignData.conversions,
            spend: campaignData.spend || 0,
            impressions: campaignData.impressions || 0,
            clicks: campaignData.clicks || 0,
            issue_type: issueType,
          }
        }
      });

      if (error) {
        return getDefaultRecommendation(issueType);
      }

      return data.recommendation || getDefaultRecommendation(issueType);
    } catch (error) {
      return getDefaultRecommendation(issueType);
    }
  };

  // Função para recomendações padrão (fallback)
  const getDefaultRecommendation = (issueType: string) => {
    const defaultRecommendations = {
      'high_cpa': 'Revisar segmentação e otimizar criativos',
      'low_ctr': 'Atualizar criativos e copy dos anúncios',
      'scale_opportunity': 'Aumentar orçamento diário gradualmente',
      'client_analysis': 'Analisar todas as campanhas do cliente'
    };
    return defaultRecommendations[issueType] || 'Analisar métricas e otimizar';
  };


  // Função para processar dados de tendência
  const processTrendsData = (data: unknown[]): TrendData[] => {
    const groupedByDate = data.reduce((acc, item) => {
      const date = new Date(item.created_at).toISOString().split('T')[0];
      if (!acc[date]) {
        acc[date] = { spend: 0, conversions: 0, count: 0 };
      }
      acc[date].spend += item.spend || 0;
      acc[date].conversions += item.conversions || 0;
      acc[date].count += 1;
      return acc;
    }, {});

    return Object.entries(groupedByDate).map(([date, values]: [string, unknown]) => ({
      date,
      cpl: values.conversions > 0 ? values.spend / values.conversions : 0,
      leads: values.conversions,
      investment: values.spend,
    })).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  };

  useEffect(() => {
    fetchDashboardData();
  }, [user?.id, activeCompany?.company_id]);

  return {
    metrics,
    clientsPerformance,
    campaignRankings,
    funnelMetrics,
    trends,
    loading,
    error,
    refetch: (filterClientId?: string | null) => fetchDashboardData(filterClientId),
  };
};

import { useState, useEffect, useRef } from 'react';

interface UseDynamicPaginationProps {
  itemHeight: number; // Altura estimada de cada item em pixels
  headerHeight?: number; // Altura do cabeçalho da tabela
  footerHeight?: number; // Altura do footer/paginação
  minItemsPerPage?: number; // Número mínimo de itens por página
  maxItemsPerPage?: number; // Número máximo de itens por página
}

export const useDynamicPagination = ({
  itemHeight = 80,
  headerHeight = 60,
  footerHeight = 80,
  minItemsPerPage = 5,
  maxItemsPerPage = 50
}: UseDynamicPaginationProps) => {
  const [itemsPerPage, setItemsPerPage] = useState(8);
  const containerRef = useRef<HTMLDivElement>(null);

  const calculateItemsPerPage = () => {
    if (!containerRef.current) return minItemsPerPage;

    const containerHeight = containerRef.current.clientHeight;
    const availableHeight = containerHeight - headerHeight - footerHeight;
    const calculatedItems = Math.floor(availableHeight / itemHeight);

    });

    // Garantir que está dentro dos limites
    return Math.max(minItemsPerPage, Math.min(maxItemsPerPage, calculatedItems));
  };

  useEffect(() => {
    const updateItemsPerPage = () => {
      // Aguardar um frame para garantir que o DOM foi renderizado
      requestAnimationFrame(() => {
        const newItemsPerPage = calculateItemsPerPage();
        setItemsPerPage(newItemsPerPage);
      });
    };

    // Aguardar um pouco antes de calcular inicialmente
    const timer = setTimeout(updateItemsPerPage, 100);

    // Recalcular quando a janela for redimensionada
    const handleResize = () => {
      setTimeout(updateItemsPerPage, 100);
    };

    window.addEventListener('resize', handleResize);

    // Observer para mudanças na altura do container com debounce
    const resizeObserver = new ResizeObserver(() => {
      setTimeout(updateItemsPerPage, 50);
    });

    if (containerRef.current) {
      resizeObserver.observe(containerRef.current);
    }

    return () => {
      clearTimeout(timer);
      window.removeEventListener('resize', handleResize);
      resizeObserver.disconnect();
    };
  }, [itemHeight, headerHeight, footerHeight, minItemsPerPage, maxItemsPerPage]);

  return {
    itemsPerPage,
    containerRef
  };
};

