}

export interface EmployeeWithPermissions {
  id: string;
  name: string;
  email: string;
  role: string;
  permissions: EmployeePermission[];
}

export function useEmployeePermissions() {
  const [employeesWithPermissions, setEmployeesWithPermissions] = useState<EmployeeWithPermissions[]>([]);
  const [currentUserPermissions, setCurrentUserPermissions] = useState<MenuItemType[]>([]);
  const [isOwner, setIsOwner] = useState(false);
  const [loading, setLoading] = useState(true);
  const [permissionsLoading, setPermissionsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { toast } = useToast();
  const { activeCompany } = useCompany();

  // Buscar todas as permissões dos colaboradores (para administradores)
  const fetchAllEmployeePermissions = async () => {
    // Use company_id instead of id
    if (!activeCompany?.company_id) {
      return;
    }

    try {
      setLoading(true);
      setError(null);

      // Buscar colaboradores com suas permissões (LEFT JOIN para incluir colaboradores sem permissões)
      const { data: employees, error: employeesError } = await supabase
        .from('employees')
        .select(`
          id,
          name,
          email,
          role,
          employee_permissions(
            id,
            employee_id,
            menu_item,
            is_enabled
          )
        `)
        .eq('company_id', activeCompany.company_id)
        .eq('status', 'active');

      if (employeesError) {
        console.error('Error fetching employees:', employeesError);
        throw employeesError;
      }

      const employeesWithPerms: EmployeeWithPermissions[] = employees?.map(emp => ({
        id: emp.id,
        name: emp.name,
        email: emp.email,
        role: emp.role,
        permissions: emp.employee_permissions || []
      })) || [];
      setEmployeesWithPermissions(employeesWithPerms);
    } catch (err: unknown) {
      console.error('Erro ao buscar permissões:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // Buscar permissões do usuário atual
  const fetchCurrentUserPermissions = async () => {
    if (!activeCompany?.company_id) {
      setPermissionsLoading(false);
      return;
    }

    try {
      setPermissionsLoading(true);

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        setPermissionsLoading(false);
        return;
      }

      // Verificar se é proprietário da empresa
      const { data: member, error: memberError } = await supabase
        .from('company_members')
        .select('role')
        .eq('user_id', user.id)
        .eq('company_id', activeCompany.company_id)
        .single();

      if (memberError) {
        console.error('Erro ao buscar membro da empresa:', memberError);
      }

      const userIsOwner = member?.role === 'owner';

      setIsOwner(userIsOwner);

      // Se for proprietário, não precisa verificar permissões específicas
      if (userIsOwner) {
        const allPermissions: MenuItemType[] = [
          'dashboard', 'clientes', 'campanhas', 'squad', 'tarefas', 'colaboradores', 'relatorios',
          'gerador-campanhas', 'gerador-conteudo', 'gerador-criativos', 'geradores', 'ia', 'configuracoes',
          'agentes-ia', 'editar-agentes', 'editor-funil', 'whatsapp', 'ver-quadros-outros',
          'radar-saude', 'rotinas', 'lead-intelligence', 'cs-cockpit', 'cs-carteira', 'cs-jornada',
          'cs-acoes', 'cs-clientes', 'cs-tv', 'agendamento', 'automatizadores', 'social-tv',
          'editor-imagens', 'planejador-conteudo', 'repositorio-criativos', 'alertas', 'tarefas-recorrentes',
          'workspace', 'automacoes', 'campanhas-unificadas', 'marketing-tv', 'keyword-planner', 'radar-tv',
          'relatorios-marketing', 'skills-ia', 'editar-skills', 'roteiros', 'command-center', 'reportes'
        ];
        setCurrentUserPermissions(allPermissions);
        setPermissionsLoading(false);
        return;
      }

      // Buscar colaborador atual
      const { data: employee } = await supabase
        .from('employees')
        .select('id')
        .eq('user_id', user.id)
        .eq('company_id', activeCompany.company_id)
        .single();

      if (!employee) {
        setPermissionsLoading(false);
        return;
      }

      // Buscar permissões habilitadas (individuais)
      const { data: permissions } = await supabase
        .from('employee_permissions')
        .select('menu_item')
        .eq('employee_id', employee.id)
        .eq('is_enabled', true);

      const individualMenus = permissions?.map(p => p.menu_item as MenuItemType) || [];

      // Buscar permissões de grupos
      const { data: groupMemberships } = await supabase
        .from('permission_group_members')
        .select('group_id')
        .eq('employee_id', employee.id);

      let groupMenus: MenuItemType[] = [];
      if (groupMemberships && groupMemberships.length > 0) {
        const groupIds = groupMemberships.map(gm => gm.group_id);
        const { data: groupItems } = await supabase
          .from('permission_group_items')
          .select('menu_item')
          .in('group_id', groupIds);

        groupMenus = groupItems?.map(gi => gi.menu_item as MenuItemType) || [];
      }

      // Merge individual + group permissions (union)
      const enabledMenus = [...new Set([...individualMenus, ...groupMenus])];
      setCurrentUserPermissions(enabledMenus);
    } catch (err: unknown) {
      console.error('Erro ao buscar permissões do usuário atual:', err);
    } finally {
      setPermissionsLoading(false);
    }
  };

  // Alternar permissão de um colaborador
  const togglePermission = async (employeeId: string, menuItem: MenuItemType) => {
    try {

      // Primeiro buscar o valor atual
      const { data: currentPerm } = await supabase
        .from('employee_permissions')
        .select('is_enabled')
        .eq('employee_id', employeeId)
        .eq('menu_item', menuItem as unknown)
        .single();


      // Se não existir a permissão, criar primeiro
      if (!currentPerm) {
        const { error: insertError } = await supabase
          .from('employee_permissions')
          .insert({
            employee_id: employeeId,
            company_id: activeCompany?.company_id,
            menu_item: menuItem as unknown,
            is_enabled: true
          } as unknown);

        if (insertError) {
          console.error('Error inserting permission:', insertError);
          throw insertError;
        }


        // Atualizar estado local
        setEmployeesWithPermissions(prev => 
          prev.map(emp => {
            if (emp.id === employeeId) {
              return {
                ...emp,
                permissions: [...emp.permissions, {
                  id: `new-${employeeId}-${menuItem}`,
                  employee_id: employeeId,
                  menu_item: menuItem,
                  is_enabled: true
                }]
              };
            }
            return emp;
          })
        );
      } else {
        // Alternar o valor existente
        const newValue = !currentPerm.is_enabled;

        const { error } = await supabase
          .from('employee_permissions')
          .update({ 
            is_enabled: newValue,
            updated_at: new Date().toISOString()
          })
          .eq('employee_id', employeeId)
          .eq('menu_item', menuItem as unknown);

        if (error) {
          console.error('Error updating permission:', error);
          throw error;
        }


        // Atualizar estado local
        setEmployeesWithPermissions(prev => 
          prev.map(emp => {
            if (emp.id === employeeId) {
              return {
                ...emp,
                permissions: emp.permissions.map(perm => 
                  perm.menu_item === menuItem 
                    ? { ...perm, is_enabled: newValue }
                    : perm
                )
              };
            }
            return emp;
          })
        );
      }

      toast({
        title: "Permissão atualizada",
        description: "A permissão foi alterada com sucesso.",
      });
    } catch (err: unknown) {
      console.error('Erro ao alterar permissão:', err);
      toast({
        title: "Erro",
        description: "Erro ao alterar permissão: " + err.message,
        variant: "destructive",
      });
    }
  };

  // Resetar permissões para o padrão
  const resetToDefaultPermissions = async (employeeId: string) => {
    try {
      // Desabilitar todas as permissões
      await supabase
        .from('employee_permissions')
        .update({ is_enabled: false })
        .eq('employee_id', employeeId);

      // Habilitar apenas dashboard e tarefas
      await supabase
        .from('employee_permissions')
        .update({ is_enabled: true })
        .eq('employee_id', employeeId)
        .in('menu_item', ['dashboard', 'tarefas']);

      await fetchAllEmployeePermissions();

      toast({
        title: "Permissões resetadas",
        description: "As permissões foram resetadas para o padrão.",
      });
    } catch (err: unknown) {
      console.error('Erro ao resetar permissões:', err);
      toast({
        title: "Erro",
        description: "Erro ao resetar permissões: " + err.message,
        variant: "destructive",
      });
    }
  };

  // Verificar se usuário tem permissão para acessar um menu
  const hasPermission = (menuItem: MenuItemType): boolean => {
    // Check if user is owner directly from company context
    const isOwnerFromContext = activeCompany?.role === 'owner';

    // Owners have access to everything - check both sources
    if (isOwner || isOwnerFromContext) {
      return true;
    }

    // During loading, only allow dashboard and tarefas for non-owners
    if (permissionsLoading) {
      return menuItem === 'dashboard' || menuItem === 'tarefas';
    }

    // Dashboard e tarefas são sempre acessíveis para todos os colaboradores
    if (menuItem === 'dashboard' || menuItem === 'tarefas') {
      return true;
    }

    const hasAccess = currentUserPermissions.includes(menuItem);
    return hasAccess;
  };

  useEffect(() => {
    if (activeCompany?.company_id) {
      fetchCurrentUserPermissions();
    }
  }, [activeCompany?.company_id]);

  return {
    employeesWithPermissions,
    currentUserPermissions,
    isOwner,
    loading,
    permissionsLoading,
    error,
    fetchAllEmployeePermissions,
    fetchCurrentUserPermissions,
    togglePermission,
    resetToDefaultPermissions,
    hasPermission,
  };
}

import { useState, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useCompany } from "@/contexts/CompanyContext";
import { supabase } from "@/integrations/supabase/client";
import { useTeams } from "@/hooks/useTeams";

export interface Employee {
  id: string;
  user_id: string;
  company_id: string;
  name: string;
  email: string;
  phone?: string;
  role: string;
  status: string;
  team_id?: string;
  ia_agent_id?: string | null;
  start_date: string;
  skills?: string;
  avatar?: string;
  profile_avatar_url?: string;
  created_at: string;
  updated_at: string;
  team?: {
    id: string;
    name: string;
    color: string;
  };
}

export interface CreateEmployeeData {
  name: string;
  email: string;
  phone?: string;
  role: string;
  status: string;
  team_id?: string;
  start_date: string;
  skills?: string;
  avatar?: string;
}

export const useEmployees = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { activeCompany } = useCompany();

  const fetchEmployees = async () => {
    if (!user || !activeCompany) {
      setEmployees([]);
      return;
    }

    try {
      setLoading(true);
      setError(null);

      // Buscar employees primeiro
      const { data: employeesData, error: employeesError } = await supabase
        .from("employees")
        .select(`
          *,
          team:teams!employees_team_id_fkey (
            id,
            name,
            color
          )
        `)
        .eq("company_id", activeCompany.company_id)
        .order("name");

      if (employeesError) throw employeesError;

      // Se não há employees, retornar array vazio
      if (!employeesData || employeesData.length === 0) {
        setEmployees([]);
        return;
      }

      // Buscar profiles dos user_ids dos employees
      const userIds = employeesData.map(emp => emp.user_id);

      const { data: profilesData, error: profilesError } = await supabase
        .from("profiles")
        .select("user_id, avatar_url")
        .in("user_id", userIds);

      if (profilesError) {
        console.warn("Error fetching profiles:", profilesError);
      }

      // Verificar se todos os user_ids foram encontrados e fazer fallback se necessário
      let allProfiles = profilesData || [];
      const foundUserIds = allProfiles.map(p => p.user_id);
      const missingUserIds = userIds.filter(id => !foundUserIds.includes(id));

      if (missingUserIds.length > 0) {
        // Buscar profiles faltantes individualmente
        const missingProfilesPromises = missingUserIds.map(async (userId) => {
          const { data } = await supabase
            .from("profiles")
            .select("user_id, avatar_url")
            .eq("user_id", userId)
            .maybeSingle();
          return data;
        });

        const missingProfiles = await Promise.all(missingProfilesPromises);
        const validMissingProfiles = missingProfiles.filter(Boolean);
        allProfiles = [...allProfiles, ...validMissingProfiles];
      }

      // Mapear os dados combinando employees com profiles
      const mappedData = employeesData.map((employee: unknown) => {
        const profile = allProfiles.find(p => p.user_id === employee.user_id);
        return {
          ...employee,
          profile_avatar_url: profile?.avatar_url || null
        };
      });

      setEmployees(mappedData);
    } catch (error: unknown) {
      console.error("Error fetching employees:", error);
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  const createEmployee = async (employeeData: CreateEmployeeData) => {
    if (!user || !activeCompany) {
      setError("Usuário não autenticado ou empresa não selecionada");
      return null;
    }

    try {
      setLoading(true);
      setError(null);

      // Verificar se o usuário tem permissões para criar colaboradores
      const { data: userRole, error: roleError } = await supabase
        .from('company_members')
        .select('role')
        .eq('user_id', user.id)
        .eq('company_id', activeCompany.company_id)
        .single();

      if (roleError || !userRole || !['owner', 'admin'].includes(userRole.role)) {
        throw new Error("Você não tem permissão para criar colaboradores. Apenas owners e admins podem realizar esta ação.");
      }

      // 1. Verificar se o colaborador já existe na empresa atual
      const { data: existingEmployeeInCompany, error: companySearchError } = await supabase
        .from('employees')
        .select('id, user_id, email, company_id')
        .eq('email', employeeData.email)
        .eq('company_id', activeCompany.company_id)
        .maybeSingle();

      if (companySearchError) {
        console.error("Erro ao verificar colaborador na empresa:", companySearchError);
        throw new Error(`Erro ao verificar colaborador: ${companySearchError.message}`);
      }

      if (existingEmployeeInCompany) {
        throw new Error("Este email já está cadastrado como colaborador nesta empresa");
      }

      let userId: string;
      let isNewUser = true;
      let shouldSendWelcome = false;

      // 2. Verificar se usuário já existe na plataforma (qualquer empresa)
      const { data: checkResult, error: checkError } = await supabase.functions.invoke('check-user', {
        body: { email: employeeData.email }
      });

      if (checkError) {
        console.warn("Erro ao verificar usuário existente:", checkError);
        // Se falhar verificação, assume que é novo usuário
        isNewUser = true;
      }

      if (checkResult?.exists && !checkError) {
        // CASO B: Usuário já existe - apenas vincular à empresa
        userId = checkResult.user_id;
        isNewUser = false;
        shouldSendWelcome = false;

        // Verificar se já é membro da empresa
        const { data: existingMember } = await supabase
          .from('company_members')
          .select('id')
          .eq('user_id', userId)
          .eq('company_id', activeCompany.company_id)
          .maybeSingle();

        if (!existingMember) {
          // Adicionar como membro da empresa
          const { error: memberError } = await supabase
            .from('company_members')
            .insert([{
              user_id: userId,
              company_id: activeCompany.company_id,
              role: 'member',
              joined_at: new Date().toISOString()
            }]);

          if (memberError) {
            console.warn("Erro ao adicionar como membro da empresa:", memberError);
          }
        }

        // Enviar notificação de nova empresa (não bloquear o processo se falhar)
        try {
          await supabase.functions.invoke('notify-user-new-company', {
            body: {
              email: employeeData.email,
              userName: employeeData.name,
              companyName: activeCompany.company?.name || 'Nova Empresa'
            }
          });
        } catch (notifyError) {
          // Falha silenciosa - nao bloqueia o processo
        }

      } else {
        // CASO A: Usuário não existe - criar novo com magic link
        const { data: createResult, error: createError } = await supabase.functions.invoke('invite-with-magic-link', {
          body: {
            email: employeeData.email,
            name: employeeData.name,
            role: employeeData.role,
            companyId: activeCompany.company_id,
            companyName: activeCompany.company?.name || 'Nossa Empresa',
            redirectTo: `${window.location.origin}/`
          }
        });

        if (createError) {
          throw new Error(`Erro ao criar novo usuário: ${createError.message}`);
        }

        if (!createResult || !createResult.user_id) {
          throw new Error("Erro ao criar usuário: dados não retornados");
        }

        userId = createResult.user_id;
        isNewUser = true;
        shouldSendWelcome = true;
      }

      // 3. Criar registro de colaborador na empresa
      const employeeInsertData = {
        name: employeeData.name,
        email: employeeData.email,
        phone: employeeData.phone || null,
        role: employeeData.role,
        team_id: employeeData.team_id === "sem-squad" || !employeeData.team_id ? null : employeeData.team_id,
        status: employeeData.status,
        start_date: employeeData.start_date,
        skills: employeeData.skills || null,
        avatar: employeeData.avatar || null,
        user_id: userId,
        company_id: activeCompany.company_id,
      };

      const { data: newEmployee, error: employeeError } = await supabase
        .from("employees")
        .insert([employeeInsertData])
        .select(`
          *,
          team:teams!employees_team_id_fkey (
            id,
            name,
            color
          )
        `)
        .single();

      if (employeeError) {
        throw new Error(`Erro ao criar registro de colaborador: ${employeeError.message}`);
      }

      // Atualizar lista de colaboradores
      await fetchEmployees();

      return newEmployee;

    } catch (error: unknown) {
      console.error("Error creating employee:", error);
      setError(error.message);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const updateEmployee = async (id: string, updates: Partial<Employee>) => {
    if (!user || !activeCompany) {
      setError("Usuário não autenticado ou empresa não selecionada");
      return null;
    }

    try {
      setLoading(true);
      setError(null);

      // Verificar se o usuário tem permissões para atualizar colaboradores
      const { data: userRole, error: roleError } = await supabase
        .from('company_members')
        .select('role')
        .eq('user_id', user.id)
        .eq('company_id', activeCompany.company_id)
        .single();

      if (roleError || !userRole || !['owner', 'admin'].includes(userRole.role)) {
        throw new Error("Você não tem permissão para atualizar colaboradores. Apenas owners e admins podem realizar esta ação.");
      }

      const { data, error } = await supabase
        .from("employees")
        .update({
          ...updates,
          team_id: !updates.team_id || updates.team_id === "sem-squad" || updates.team_id === "" ? null : updates.team_id,
          updated_at: new Date().toISOString(),
        })
        .eq("id", id)
        .eq("company_id", activeCompany.company_id) // Garantir que só atualize na empresa atual
        .select(`
          *,
          team:teams!employees_team_id_fkey (
            id,
            name,
            color
          )
        `)
        .single();

      if (error) throw error;

      // Atualizar lista de colaboradores
      await fetchEmployees();

      return data;
    } catch (error: unknown) {
      console.error("Error updating employee:", error);
      setError(error.message);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const deleteEmployee = async (id: string) => {
    if (!user || !activeCompany) {
      setError("Usuário não autenticado ou empresa não selecionada");
      return;
    }

    try {
      setLoading(true);
      setError(null);

      // Verificar se o usuário tem permissões para deletar colaboradores
      const { data: userRole, error: roleError } = await supabase
        .from('company_members')
        .select('role')
        .eq('user_id', user.id)
        .eq('company_id', activeCompany.company_id)
        .single();

      if (roleError || !userRole || !['owner', 'admin'].includes(userRole.role)) {
        throw new Error("Você não tem permissão para excluir colaboradores. Apenas owners e admins podem realizar esta ação.");
      }

      const { error } = await supabase
        .from("employees")
        .delete()
        .eq("id", id)
        .eq("company_id", activeCompany.company_id); // Garantir que só delete na empresa atual

      if (error) throw error;

      // Atualizar lista de colaboradores
      await fetchEmployees();
    } catch (error: unknown) {
      console.error("Error deleting employee:", error);
      setError(error.message);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user && activeCompany) {
      fetchEmployees();
    }
  }, [user, activeCompany]);

  return {
    employees,
    loading,
    error,
    fetchEmployees,
    createEmployee,
    updateEmployee,
    deleteEmployee,
  };
};

import { useState } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { SyncOptions } from '@/components/facebook/SyncPeriodDialog';

export const useFacebookCampaignSync = () => {
  const [syncing, setSyncing] = useState(false);
  const [progress, setProgress] = useState({ current: 0, total: 0, clientName: '' });
  const [currentJobId, setCurrentJobId] = useState<string | null>(null);
  const { toast } = useToast();

  const syncCampaigns = async (
    clientId: string, 
    period: string = '30', 
    options?: { 
      campaigns?: boolean; 
      adsets?: boolean; 
      ads?: boolean;
      campaignFacebookId?: string; // Optional: sync only specific campaign
      startDate?: string; // Optional: custom period start (YYYY-MM-DD)
      endDate?: string; // Optional: custom period end (YYYY-MM-DD)
    }, 
    silent: boolean = false, 
    includeInactive: boolean = false
  ): Promise<string | null> => {
    if (!clientId) return null;

    try {
      const { data, error } = await supabase.functions.invoke('sync-facebook-campaigns', {
        body: { 
          clientId, 
          period, 
          syncCampaigns: options?.campaigns !== false,
          syncAdSets: options?.adsets !== false, 
          syncAds: options?.ads !== false,
          includeInactive,
          campaignFacebookId: options?.campaignFacebookId || null,
          startDate: options?.startDate || null,
          endDate: options?.endDate || null
        }
      });

      if (error) {
        console.error('Sync error:', error);
        throw new Error(error.message || 'Erro ao iniciar sincronização');
      }

      if (!data.success) {
        throw new Error(data.error || 'Erro ao iniciar sincronização');
      }

      const jobId = data.job_id;
      setCurrentJobId(jobId);

      if (!silent) {
        toast({
          title: "Sincronização iniciada",
          description: "Processando dados em background...",
        });
      }

      return jobId;
    } catch (error: unknown) {
      console.error('Error syncing campaigns:', error);
      toast({
        title: "Erro ao iniciar sincronização",
        description: error.message || "Não foi possível iniciar a sincronização.",
        variant: "destructive",
      });
      return null;
    }
  };

  const validateCompanyUrls = async (companyId: string) => {
    try {
      const { data, error } = await supabase.functions.invoke('validate-client-urls', {
        body: { company_id: companyId }
      });

      if (error) {
        console.error('[validateCompanyUrls] URL validation failed:', error.message);
      } else {
      }
    } catch (urlError: unknown) {
      console.error('[validateCompanyUrls] URL validation error:', urlError.message);
    }
  };

  const syncAllClients = async (options: SyncOptions, companyId?: string) => {
    setSyncing(true);
    setProgress({ current: 0, total: 0, clientName: '' });

    try {
      // Get all clients with ad accounts
      let query = supabase
        .from('clients')
        .select('id, name, ad_account_id, status, company_id')
        .not('ad_account_id', 'is', null)
        .eq('is_canceled', false);

      // Exclude inactive clients if not requested to include them
      if (!options.includeInactive) {
        // Exclude clients that are red status WITH inactive_reason (considered inactive)
        query = query.or(`status.neq.red,inactive_reason.is.null,inactive_reason.eq.`);
      }

      const { data: clients, error } = await query;

      if (error) throw error;

      const totalClients = clients?.length || 0;
      setProgress({ current: 0, total: totalClients, clientName: '' });

      // Get company_id from first client if not provided
      const targetCompanyId = companyId || (clients && clients.length > 0 ? clients[0].company_id : null);

      let successCount = 0;
      for (let i = 0; i < (clients?.length || 0); i++) {
        const client = clients![i];
        setProgress({ current: i + 1, total: totalClients, clientName: client.name });

        const result = await syncCampaigns(client.id, options.period, {
          campaigns: options.campaigns,
          adsets: options.adsets,
          ads: options.ads
        }, true, options.includeInactive); // silent mode for bulk sync, pass includeInactive
        if (result) successCount++;
      }

      // ========== VALIDAR URLs APÓS SINCRONIZAÇÃO ==========
      if (targetCompanyId) {
        await validateCompanyUrls(targetCompanyId);
      }
      // ========== FIM DA VALIDAÇÃO DE URLs ==========

      const periodLabel = options.period === 'lifetime' ? 'máximo' : `${options.period} dias`;
      const syncTypes = [];
      if (options.campaigns) syncTypes.push('campanhas');
      if (options.adsets) syncTypes.push('conjuntos de anúncios');
      if (options.ads) syncTypes.push('criativos');
      const syncType = syncTypes.join(', ') || 'campanhas';

      toast({
        title: "Sincronização concluída",
        description: `${successCount} de ${clients?.length || 0} clientes sincronizados (${syncType}, ${periodLabel}).`,
      });

    } catch (error: unknown) {
      console.error('Error syncing all clients:', error);
      toast({
        title: "Erro na sincronização",
        description: error.message || "Erro ao sincronizar todos os clientes.",
        variant: "destructive",
      });
    } finally {
      setSyncing(false);
      setProgress({ current: 0, total: 0, clientName: '' });
    }
  };

  const handleJobComplete = (jobId: string, success: boolean, errorMessage?: string) => {
    if (success) {
      toast({
        title: "✅ Sincronização concluída",
        description: "Dados atualizados com sucesso!",
      });
      window.dispatchEvent(new CustomEvent('clientsUpdated'));
    } else {
      toast({
        title: "❌ Erro na sincronização",
        description: errorMessage || "Ocorreu um erro durante a sincronização.",
        variant: "destructive",
      });
    }

    setSyncing(false);
    if (currentJobId === jobId) {
      setCurrentJobId(null);
    }
  };

  const syncAllClientsWrapper = async (options: SyncOptions, companyId?: string): Promise<string | null> => {
    await syncAllClients(options, companyId);
    return null; // TODO: Implement job tracking for bulk sync
  };

  return {
    syncing,
    progress,
    currentJobId,
    syncCampaigns,
    syncAllClients: syncAllClientsWrapper,
    handleJobComplete,
    clearJobId: () => setCurrentJobId(null)
  };
};

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useCompany } from "@/contexts/CompanyContext";

interface FacebookAdAccount {
  id: string;
  account_name: string;
  currency: string;
  is_active: boolean;
}

interface FacebookIntegration {
  id: string;
  company_id: string;
  access_token: string;
  expires_at: string;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

export const useFacebookIntegration = () => {
  const [loading, setLoading] = useState(false);
  const [integration, setIntegration] = useState<FacebookIntegration | null>(
    null,
  );
  const [adAccounts, setAdAccounts] = useState<FacebookAdAccount[]>([]);
  const { toast } = useToast();
  const { activeCompany } = useCompany();

  const getAuthUrl = () => {
    if (!activeCompany) {
      toast({
        title: "Erro",
        description: "Selecione uma empresa primeiro",
        variant: "destructive",
      });
      return null;
    }

    const facebookAppId = "1118192076871259"; // Your Facebook App ID

    // Determine redirect URI based on current domain
    const origin = window.location.origin;
    let redirectUri = "";

    if (
      origin.includes("expxflow.com.br") ||
      origin.includes("controledetrafego.com.br")
    ) {
      redirectUri = `${origin}/auth/callback`;
    } else {
      redirectUri = "https://expxflow.com.br/auth/callback";
    }

    const params = new URLSearchParams({
      client_id: facebookAppId,
      redirect_uri: redirectUri,
      scope:
        "email,public_profile,ads_read,ads_management,business_management,pages_show_list,pages_read_engagement,pages_manage_posts,instagram_basic,instagram_manage_insights,instagram_content_publish",
      response_type: "code",
      state: activeCompany.company_id, // Pass company ID as state
    });

    return `https://www.facebook.com/v20.0/dialog/oauth?${params.toString()}`;
  };

  const connectFacebook = () => {
    const authUrl = getAuthUrl();
    if (authUrl) {
      window.location.href = authUrl;
    }
  };

  const handleCallback = async (code: string, companyId: string) => {
    setLoading(true);
    try {

      const { data, error } = await supabase.functions.invoke(
        "facebook-oauth?action=exchange",
        {
          body: {
            code,
            companyId,
          },
        },
      );

      if (error) {
        console.error("Edge function error:", error);
        throw new Error(error.message || "Erro na função de OAuth");
      }

      if (!data.success) {
        throw new Error(data.error || "Erro ao processar OAuth");
      }


      setIntegration(data.integration);
      setAdAccounts(data.adAccounts || []);

      toast({
        title: "Facebook conectado com sucesso!",
        description: `${(data.adAccounts || []).length} conta(s) de anúncios importadas.`,
      });

      return true;
    } catch (error: unknown) {
      console.error("Error handling Facebook callback:", error);
      toast({
        title: "Erro ao conectar Facebook",
        description:
          error instanceof Error ? error.message : "Ocorreu um erro inesperado",
        variant: "destructive",
      });
      return false;
    } finally {
      setLoading(false);
    }
  };

  const loadIntegration = async (companyId: string) => {
    setLoading(true);
    try {
      const { data: integrations, error } = await supabase
        .from("facebook_integrations")
        .select(
          `
          *,
          facebook_ad_accounts(*)
        `,
        )
        .eq("company_id", companyId)
        .eq("is_active", true)
        .maybeSingle();

      if (error && error.code !== "PGRST116") {
        throw error;
      }

      if (integrations) {
        setIntegration(integrations);
        setAdAccounts(integrations.facebook_ad_accounts || []);
      } else {
        setIntegration(null);
        setAdAccounts([]);
      }
    } catch (error: unknown) {
      console.error("Error loading integration:", error);
      toast({
        title: "Erro ao carregar integração",
        description:
          error instanceof Error ? error.message : "Ocorreu um erro inesperado",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const disconnectFacebook = async () => {
    if (!integration) return;

    setLoading(true);
    try {
      const { error } = await supabase
        .from("facebook_integrations")
        .update({ is_active: false })
        .eq("id", integration.id);

      if (error) throw error;

      setIntegration(null);
      setAdAccounts([]);

      toast({
        title: "Facebook desconectado",
        description: "A integração foi removida com sucesso.",
      });
    } catch (error: unknown) {
      console.error("Error disconnecting Facebook:", error);
      toast({
        title: "Erro ao desconectar",
        description:
          error instanceof Error ? error.message : "Ocorreu um erro inesperado",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const refreshAdAccounts = async () => {
    if (!integration || !activeCompany) return;

    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke(
        "facebook-oauth?action=refresh-accounts",
        {
          body: {
            integrationId: integration.id,
            companyId: activeCompany.company_id,
          },
        },
      );

      if (error) {
        console.error("Edge function error:", error);
        throw new Error(error.message || "Erro na função de atualização");
      }

      if (!data.success) {
        throw new Error(data.error || "Erro ao atualizar contas");
      }


      setAdAccounts(data.adAccounts || []);

      toast({
        title: "Contas atualizadas!",
        description: `${(data.adAccounts || []).length} conta(s) de anúncios atualizadas.`,
      });

      return true;
    } catch (error: unknown) {
      console.error("Error refreshing ad accounts:", error);
      toast({
        title: "Erro ao atualizar contas",
        description:
          error instanceof Error ? error.message : "Ocorreu um erro inesperado",
        variant: "destructive",
      });
      return false;
    } finally {
      setLoading(false);
    }
  };

  const checkScopes = async (companyId: string) => {
    try {
      setLoading(true);

      const { data, error } = await supabase.functions.invoke(
        "check-facebook-scopes",
        {
          body: { companyId },
        },
      );

      if (error) {
        console.error("Error checking scopes:", error);
        toast({
          variant: "destructive",
          title: "Erro ao verificar permissões",
          description:
            error.message ||
            "Não foi possível verificar as permissões do Facebook.",
        });
        return null;
      }

      if (!data.success) {
        toast({
          variant: "destructive",
          title: "Erro ao verificar permissões",
          description:
            data.error ||
            "Não foi possível verificar as permissões do Facebook.",
        });
        return null;
      }

      return data;
    } catch (error) {
      console.error("Error checking scopes:", error);
      toast({
        variant: "destructive",
        title: "Erro ao verificar permissões",
        description: "Não foi possível verificar as permissões do Facebook.",
      });
      return null;
    } finally {
      setLoading(false);
    }
  };

  // Auto-load integration when active company changes
  useEffect(() => {
    if (activeCompany?.company_id) {
      loadIntegration(activeCompany.company_id);
    } else {
      setIntegration(null);
      setAdAccounts([]);
    }
  }, [activeCompany?.company_id]);

  return {
    loading,
    integration,
    adAccounts,
    connectFacebook,
    handleCallback,
    loadIntegration,
    disconnectFacebook,
    refreshAdAccounts,
    checkScopes,
  };
};

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { useCompany } from '@/contexts/CompanyContext';

export interface FacebookPage {
  id: string;
  integration_id: string;
  company_id: string;
  page_id: string;
  page_name: string;
  page_access_token: string;
  page_category: string | null;
  instagram_business_account_id: string | null;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

export interface InstagramAccount {
  id: string;
  facebook_page_id: string | null;
  company_id: string;
  instagram_id: string;
  username: string;
  profile_picture_url: string | null;
  followers_count: number;
  is_active: boolean;
  created_at: string;
  updated_at: string;
  source?: 'page' | 'business_manager';
  business_id?: string | null;
  facebook_page?: FacebookPage | null;
}

export const useFacebookPages = () => {
  const [pages, setPages] = useState<FacebookPage[]>([]);
  const [instagramAccounts, setInstagramAccounts] = useState<InstagramAccount[]>([]);
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();
  const { activeCompany } = useCompany();

  const fetchPages = async () => {
    if (!activeCompany?.company_id) return;

    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('facebook_pages')
        .select('*')
        .eq('company_id', activeCompany.company_id)
        .eq('is_active', true);

      if (error) throw error;
      setPages((data || []) as FacebookPage[]);
    } catch (error: unknown) {
      console.error('Error fetching Facebook pages:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchInstagramAccounts = async () => {
    if (!activeCompany?.company_id) return;

    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('instagram_accounts')
        .select(`
          *,
          facebook_page:facebook_pages(*)
        `)
        .eq('company_id', activeCompany.company_id)
        .eq('is_active', true);

      if (error) throw error;
      setInstagramAccounts((data || []) as InstagramAccount[]);
    } catch (error: unknown) {
      console.error('Error fetching Instagram accounts:', error);
    } finally {
      setLoading(false);
    }
  };

  const refreshPages = async (integrationId: string) => {
    if (!activeCompany?.company_id) return false;

    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke('fetch-facebook-pages', {
        body: { 
          integrationId,
          companyId: activeCompany.company_id
        }
      });

      if (error) throw error;

      if (!data.success) {
        throw new Error(data.error || 'Failed to fetch pages');
      }

      toast({
        title: 'Páginas atualizadas!',
        description: `${data.pages?.length || 0} páginas e ${data.instagramAccounts?.length || 0} contas Instagram encontradas.`,
      });

      await fetchPages();
      await fetchInstagramAccounts();
      return true;
    } catch (error: unknown) {
      console.error('Error refreshing pages:', error);
      toast({
        title: 'Erro ao atualizar páginas',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (activeCompany?.company_id) {
      fetchPages();
      fetchInstagramAccounts();
    }
  }, [activeCompany?.company_id]);

  return {
    pages,
    instagramAccounts,
    loading,
    fetchPages,
    fetchInstagramAccounts,
    refreshPages,
  };
};

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { useCompany } from '@/contexts/CompanyContext';

export interface SyncOptions {
  period: string;
  campaigns: boolean;
  adsets: boolean;
  ads: boolean;
  includeInactive: boolean;
}

export interface SyncSchedule {
  id: string;
  company_id: string;
  is_enabled: boolean;
  sync_options: SyncOptions;
  scheduled_times: string[];
  executions_per_day: number;
  last_execution_at: string | null;
  next_execution_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface ExecutionLog {
  id: string;
  company_id: string;
  schedule_id: string | null;
  status: 'running' | 'completed' | 'failed' | 'partial';
  clients_processed: number;
  clients_total: number;
  sync_options: SyncOptions;
  started_at: string;
  completed_at: string | null;
  error_message: string | null;
  execution_details: unknown;
}

export const useFacebookSyncSchedule = () => {
  const [schedule, setSchedule] = useState<SyncSchedule | null>(null);
  const [executionLogs, setExecutionLogs] = useState<ExecutionLog[]>([]);
  const [loading, setLoading] = useState(false);
  const [logsLoading, setLogsLoading] = useState(false);
  const { toast } = useToast();
  const { activeCompany } = useCompany();

  const fetchSchedule = async () => {
    if (!activeCompany?.company_id) return;

    try {
      setLoading(true);
      const { data, error } = await supabase.functions.invoke('manage-facebook-sync-schedule', {
        body: {
          action: 'get',
          company_id: activeCompany.company_id,
        },
      });

      if (error) throw error;
      setSchedule(data.schedule);
    } catch (error: unknown) {
      console.error('Error fetching schedule:', error);
      toast({
        title: 'Erro ao carregar configuração',
        description: error.message,
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchExecutionLogs = async () => {
    if (!activeCompany?.company_id) return;

    try {
      setLogsLoading(true);
      const { data, error } = await supabase
        .from('facebook_sync_execution_logs')
        .select('*')
        .eq('company_id', activeCompany.company_id)
        .order('started_at', { ascending: false })
        .limit(10);

      if (error) throw error;

      // Cast com validação de tipo
      const logs = (data || []).map(log => ({
        ...log,
        status: log.status as 'running' | 'completed' | 'failed' | 'partial',
        sync_options: log.sync_options as unknown as SyncOptions,
      }));

      setExecutionLogs(logs);
    } catch (error: unknown) {
      console.error('Error fetching execution logs:', error);
    } finally {
      setLogsLoading(false);
    }
  };

  const saveSchedule = async (
    isEnabled: boolean,
    syncOptions: SyncOptions,
    executionsPerDay: number
  ) => {
    if (!activeCompany?.company_id) return;

    try {
      setLoading(true);
      const { data, error } = await supabase.functions.invoke('manage-facebook-sync-schedule', {
        body: {
          action: 'upsert',
          company_id: activeCompany.company_id,
          is_enabled: isEnabled,
          sync_options: syncOptions,
          executions_per_day: executionsPerDay,
        },
      });

      if (error) throw error;

      setSchedule(data.schedule);
      toast({
        title: 'Configuração salva',
        description: 'As configurações de sincronização foram atualizadas com sucesso.',
      });

      return data.schedule;
    } catch (error: unknown) {
      console.error('Error saving schedule:', error);
      toast({
        title: 'Erro ao salvar configuração',
        description: error.message,
        variant: 'destructive',
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const toggleSchedule = async (enabled: boolean) => {
    if (!activeCompany?.company_id) return;

    try {
      setLoading(true);
      const { data, error } = await supabase.functions.invoke('manage-facebook-sync-schedule', {
        body: {
          action: 'patch',
          company_id: activeCompany.company_id,
          is_enabled: enabled,
        },
      });

      if (error) throw error;

      setSchedule(data.schedule);
      toast({
        title: enabled ? 'Sincronização ativada' : 'Sincronização desativada',
        description: enabled 
          ? 'A sincronização automática foi ativada.' 
          : 'A sincronização automática foi desativada.',
      });

      return data.schedule;
    } catch (error: unknown) {
      console.error('Error toggling schedule:', error);
      toast({
        title: 'Erro ao alterar status',
        description: error.message,
        variant: 'destructive',
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const deleteSchedule = async () => {
    if (!activeCompany?.company_id) return;

    try {
      setLoading(true);
      const { error } = await supabase.functions.invoke('manage-facebook-sync-schedule', {
        body: {
          action: 'delete',
          company_id: activeCompany.company_id,
        },
      });

      if (error) throw error;

      setSchedule(null);
      toast({
        title: 'Configuração removida',
        description: 'A configuração de sincronização foi removida.',
      });
    } catch (error: unknown) {
      console.error('Error deleting schedule:', error);
      toast({
        title: 'Erro ao remover configuração',
        description: error.message,
        variant: 'destructive',
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (activeCompany?.company_id) {
      fetchSchedule();
      fetchExecutionLogs();
    }
  }, [activeCompany?.company_id]);

  return {
    schedule,
    executionLogs,
    loading,
    logsLoading,
    fetchSchedule,
    fetchExecutionLogs,
    saveSchedule,
    toggleSchedule,
    deleteSchedule,
  };
};

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { useCompany } from '@/contexts/CompanyContext';
import { toast } from '@/hooks/use-toast';

export interface GeneratedCampaign {
  id: string;
  user_id: string;
  company_id: string;
  client_id: string;
  title: string;
  funnel_stage: string;
  campaign_type: string;
  configuration: unknown;
  creatives: unknown;
  status: string;
  created_at: string;
  updated_at: string;
  clients?: {
    name: string;
    company: string;
    email?: string;
    sector?: string;
    avatar?: string;
  };
}

export interface CampaignData {
  client: unknown;
  funnelStage: string;
  campaignType: string;
  configuration: unknown;
  creatives: unknown;
}

export const useGeneratedCampaigns = () => {
  const [campaigns, setCampaigns] = useState<GeneratedCampaign[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { activeCompany } = useCompany();

  const fetchCampaigns = async () => {
    if (!user || !activeCompany) return;

    setLoading(true);
    setError(null);

    try {
      // Primeiro buscar as campanhas geradas
      const { data: campaigns, error: campaignsError } = await supabase
        .from('generated_campaigns')
        .select('*')
        .eq('company_id', activeCompany.company_id)
        .order('created_at', { ascending: false });

      if (campaignsError) {
        console.error('Error fetching campaigns:', campaignsError);
        setError('Erro ao carregar campanhas');
        return;
      }

      // Buscar dados dos clientes separadamente
      if (campaigns && campaigns.length > 0) {
        const clientIds = [...new Set(campaigns.map(c => c.client_id))];
        const { data: clients, error: clientsError } = await supabase
          .from('clients')
          .select('id, name, company, email')
          .in('id', clientIds);

        if (clientsError) {
          console.error('Error fetching clients:', clientsError);
        }

        // Combinar os dados
        const campaignsWithClients = campaigns.map(campaign => ({
          ...campaign,
          clients: clients?.find(client => client.id === campaign.client_id) || null
        }));

        setCampaigns(campaignsWithClients);
      } else {
        setCampaigns([]);
      }
    } catch (err) {
      console.error('Error:', err);
      setError('Erro ao carregar campanhas');
    } finally {
      setLoading(false);
    }
  };

  const createCampaign = async (campaignData: CampaignData) => {
    if (!user || !activeCompany) {
      throw new Error('Usuário ou empresa não encontrados');
    }

    try {
      const title = `${campaignData.client.name} - ${campaignData.campaignType} - ${campaignData.funnelStage}`;

      const { data, error } = await supabase
        .from('generated_campaigns')
        .insert({
          user_id: user.id,
          company_id: activeCompany.company_id,
          client_id: campaignData.client.id,
          title,
          funnel_stage: campaignData.funnelStage,
          campaign_type: campaignData.campaignType,
          configuration: campaignData.configuration || {},
          creatives: campaignData.creatives || {},
          status: 'completed'
        })
        .select()
        .single();

      if (error) throw error;

      toast({
        title: "Campanha salva com sucesso!",
        description: "A estratégia foi salva e pode ser acessada a qualquer momento.",
      });

      await fetchCampaigns();
      return data;
    } catch (err) {
      console.error('Error creating campaign:', err);
      const message = err instanceof Error ? err.message : 'Erro ao salvar campanha';
      toast({
        title: "Erro ao salvar campanha",
        description: message,
        variant: "destructive",
      });
      throw err;
    }
  };

  const getCampaign = async (id: string): Promise<GeneratedCampaign | null> => {
    if (!user || !activeCompany) return null;

    try {
      // Buscar a campanha
      const { data: campaign, error: campaignError } = await supabase
        .from('generated_campaigns')
        .select('*')
        .eq('id', id)
        .eq('company_id', activeCompany.company_id)
        .single();

      if (campaignError) throw campaignError;

      // Buscar dados do cliente separadamente
      const { data: client, error: clientError } = await supabase
        .from('clients')
        .select('name, company, email, sector, avatar')
        .eq('id', campaign.client_id)
        .single();

      if (clientError) {
        console.error('Error fetching client:', clientError);
      }

      return {
        ...campaign,
        clients: client || null
      };
    } catch (err) {
      console.error('Error fetching campaign:', err);
      return null;
    }
  };

  const updateCampaign = async (id: string, updates: Partial<GeneratedCampaign>) => {
    if (!user || !activeCompany) {
      throw new Error('Usuário ou empresa não encontrados');
    }

    try {
      const { data, error } = await supabase
        .from('generated_campaigns')
        .update(updates)
        .eq('id', id)
        .eq('company_id', activeCompany.company_id)
        .select()
        .single();

      if (error) throw error;

      await fetchCampaigns();
      return data;
    } catch (err) {
      console.error('Error updating campaign:', err);
      throw err;
    }
  };

  useEffect(() => {
    fetchCampaigns();
  }, [user, activeCompany]);

  return {
    campaigns,
    loading,
    error,
    fetchCampaigns,
    createCampaign,
    getCampaign,
    updateCampaign,
  };
};

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import type { Json } from "@/integrations/supabase/types";

interface SyncOptions {
  clientId: string;
  companyId: string;
  period?: string;
  syncCampaigns?: boolean;
  syncAdGroups?: boolean;
  syncAds?: boolean;
  includeInactive?: boolean;
  silent?: boolean;
}

interface ClientSyncResult {
  client_id: string;
  client_name: string;
  status: 'success' | 'error';
  error_code?: string;
  error_message?: string;
  action_required?: 'internal' | 'client' | 'none';
  campaigns_synced?: number;
  ad_groups_synced?: number;
  ads_synced?: number;
}

// Classificador de erros do Google Ads
function classifyGoogleAdsError(errorMessage: string): {
  code: string;
  userFriendlyMessage: string;
  actionRequired: 'internal' | 'client' | 'none';
} {
  if (errorMessage.includes('USER_PERMISSION_DENIED')) {
    return {
      code: 'USER_PERMISSION_DENIED',
      userFriendlyMessage: 'Conta MCC não tem permissão para acessar este cliente. O cliente precisa conceder acesso à conta MCC no Google Ads.',
      actionRequired: 'client',
    };
  }
  if (errorMessage.includes('CUSTOMER_NOT_ENABLED')) {
    return {
      code: 'CUSTOMER_NOT_ENABLED',
      userFriendlyMessage: 'Conta do Google Ads está desativada ou pausada. O cliente precisa reativar a conta.',
      actionRequired: 'client',
    };
  }
  if (errorMessage.includes('OAUTH_TOKEN_REVOKED') || errorMessage.includes('invalid_grant')) {
    return {
      code: 'OAUTH_TOKEN_REVOKED',
      userFriendlyMessage: 'Token de acesso revogado. Reconecte o Google Ads nas configurações.',
      actionRequired: 'internal',
    };
  }
  if (errorMessage.includes('Token refresh failed')) {
    return {
      code: 'TOKEN_REFRESH_FAILED',
      userFriendlyMessage: 'Falha ao renovar credenciais. Reconecte o Google Ads.',
      actionRequired: 'internal',
    };
  }
  if (errorMessage.includes('Client does not have a Google Ads account configured')) {
    return {
      code: 'NO_GOOGLE_ACCOUNT',
      userFriendlyMessage: 'Cliente não tem conta Google Ads configurada.',
      actionRequired: 'internal',
    };
  }
  if (errorMessage.includes('Google Ads integration is not active')) {
    return {
      code: 'INTEGRATION_INACTIVE',
      userFriendlyMessage: 'Integração do Google Ads não está ativa.',
      actionRequired: 'internal',
    };
  }
  if (errorMessage.includes('Google Ads account not found')) {
    return {
      code: 'ACCOUNT_NOT_FOUND',
      userFriendlyMessage: 'Conta do Google Ads não encontrada.',
      actionRequired: 'internal',
    };
  }
  return {
    code: 'UNKNOWN',
    userFriendlyMessage: errorMessage,
    actionRequired: 'internal',
  };
}

export function useGoogleAdsCampaignSync() {
  const [syncing, setSyncing] = useState(false);
  const [progress, setProgress] = useState<{
    current: number;
    total: number;
    clientName?: string;
  }>({ current: 0, total: 0 });

  const syncCampaigns = async (options: SyncOptions): Promise<{
    success: boolean;
    synced?: { campaigns: number; adGroups: number; ads: number };
    error?: string;
    errorCode?: string;
    actionRequired?: 'internal' | 'client' | 'none';
  }> => {
    const {
      clientId,
      companyId,
      period = 'last_30_days',
      syncCampaigns = true,
      syncAdGroups = false,
      syncAds = false,
      includeInactive = false,
      silent = false,
    } = options;

    try {
      setSyncing(true);

      if (!silent) {
        toast.loading("Sincronizando campanhas do Google Ads...", { id: "google-sync" });
      }

      const response = await supabase.functions.invoke('sync-google-ads-campaigns', {
        body: {
          clientId,
          companyId,
          period,
          syncCampaigns,
          syncAdGroups,
          syncAds,
          includeInactive,
          silent,
        },
      });

      const data = response.data;
      const error = response.error;

      // Extract detailed error message from response
      if (error) {
        let errorMessage = error.message || 'Unknown error';
        // Try to get detailed error from context body
        const contextBody = (error as unknown).context?.body;
        if (typeof contextBody === 'string' && contextBody.startsWith('{')) {
          try {
            const parsed = JSON.parse(contextBody);
            errorMessage = parsed.error || errorMessage;
          } catch (e) {
            // Keep original
          }
        }
        throw new Error(errorMessage);
      }

      if (data?.error) {
        throw new Error(data.error);
      }

      if (!silent) {
        toast.success(
          `Sincronizado: ${data.synced.campaigns} campanhas, ${data.synced.adGroups} grupos de anúncios, ${data.synced.ads} anúncios`,
          { id: "google-sync" }
        );
      }

      // Dispatch event for other components to refresh
      window.dispatchEvent(new CustomEvent('clientsUpdated'));

      return {
        success: true,
        synced: data.synced,
      };
    } catch (error: unknown) {
      console.error("Error syncing Google Ads campaigns:", error);

      const classification = classifyGoogleAdsError(error.message || '');

      if (!silent) {
        toast.error(`Erro ao sincronizar: ${classification.userFriendlyMessage}`, { id: "google-sync" });
      }

      return {
        success: false,
        error: classification.userFriendlyMessage,
        errorCode: classification.code,
        actionRequired: classification.actionRequired,
      };
    } finally {
      setSyncing(false);
    }
  };

  const validateCompanyUrls = async (companyId: string) => {
    try {
      const { data, error } = await supabase.functions.invoke('validate-client-urls', {
        body: { company_id: companyId }
      });

      if (error) {
        console.error('[validateCompanyUrls] URL validation failed:', error.message);
      } else {
      }
    } catch (urlError: unknown) {
      console.error('[validateCompanyUrls] URL validation error:', urlError.message);
    }
  };

  const syncAllClients = async (
    companyId: string,
    options: {
      period?: string;
      syncCampaigns?: boolean;
      syncAdGroups?: boolean;
      syncAds?: boolean;
      includeInactive?: boolean;
      excludeInactiveClients?: boolean;
    } = {}
  ) => {
    const startedAt = new Date().toISOString();
    const clientResults: ClientSyncResult[] = [];

    try {
      setSyncing(true);
      setProgress({ current: 0, total: 0 });


      // Get all clients with Google Ads accounts
      let query = supabase
        .from('clients')
        .select('id, name, google_account_id')
        .eq('company_id', companyId)
        .not('google_account_id', 'is', null);

      if (options.excludeInactiveClients) {
        // Use 'red' which is the database enum value for inactive clients
        query = query.neq('status', 'red');
      }

      const { data: clients, error } = await query;


      if (error) throw error;

      if (!clients || clients.length === 0) {
        console.warn('[syncAllClients] No clients found with Google Ads configured for company:', companyId);
        toast.info("Nenhum cliente com Google Ads configurado");
        return;
      }

      setProgress({ current: 0, total: clients.length });
      let successCount = 0;
      let errorCount = 0;

      for (let i = 0; i < clients.length; i++) {
        const client = clients[i];
        setProgress({
          current: i + 1,
          total: clients.length,
          clientName: client.name,
        });

        const result = await syncCampaigns({
          clientId: client.id,
          companyId,
          ...options,
          silent: true,
        });

        if (result.success) {
          successCount++;
          clientResults.push({
            client_id: client.id,
            client_name: client.name,
            status: 'success',
            campaigns_synced: result.synced?.campaigns || 0,
            ad_groups_synced: result.synced?.adGroups || 0,
            ads_synced: result.synced?.ads || 0,
          });
        } else {
          console.error(`Failed to sync client ${client.name}:`, result.error);
          errorCount++;
          clientResults.push({
            client_id: client.id,
            client_name: client.name,
            status: 'error',
            error_code: result.errorCode,
            error_message: result.error,
            action_required: result.actionRequired,
          });
        }
      }

      // Determinar status geral
      let overallStatus: 'completed' | 'partial' | 'failed' = 'completed';
      if (errorCount > 0 && successCount > 0) {
        overallStatus = 'partial';
      } else if (errorCount > 0 && successCount === 0) {
        overallStatus = 'failed';
      }

      // Registrar no histórico de execuções
      const completedAt = new Date().toISOString();
      const { error: logError } = await supabase
        .from('google_ads_sync_execution_logs')
        .insert([{
          company_id: companyId,
          schedule_id: null, // null = sincronização manual
          status: overallStatus,
          clients_processed: successCount,
          clients_total: clients.length,
          sync_options: {
            period: options.period || 'last_30_days',
            campaigns: options.syncCampaigns ?? true,
            adGroups: options.syncAdGroups ?? false,
            ads: options.syncAds ?? false,
            includeInactive: options.includeInactive ?? false,
          } as Json,
          execution_details: {
            trigger: 'manual',
            clients: clientResults.map(c => ({ ...c })),
          } as Json,
          error_message: errorCount > 0 ? `${errorCount} cliente(s) com erro` : null,
          started_at: startedAt,
          completed_at: completedAt,
        }]);

      if (logError) {
        console.error('[syncAllClients] Error creating execution log:', logError);
      } else {
      }

      // ========== VALIDAR URLs APÓS SINCRONIZAÇÃO ==========
      await validateCompanyUrls(companyId);
      // ========== FIM DA VALIDAÇÃO DE URLs ==========

      toast.success(
        `Sincronização concluída! ${successCount} clientes sincronizados${errorCount > 0 ? `, ${errorCount} com erro` : ''}`
      );
    } catch (error: unknown) {
      console.error("Error syncing all clients:", error);

      // Registrar falha no histórico
      await supabase
        .from('google_ads_sync_execution_logs')
        .insert([{
          company_id: companyId,
          schedule_id: null,
          status: 'failed',
          clients_processed: 0,
          clients_total: 0,
          sync_options: {
            period: options.period || 'last_30_days',
            campaigns: options.syncCampaigns ?? true,
            adGroups: options.syncAdGroups ?? false,
            ads: options.syncAds ?? false,
            includeInactive: options.includeInactive ?? false,
          } as Json,
          execution_details: {
            trigger: 'manual',
            clients: clientResults.map(c => ({ ...c })),
          } as Json,
          error_message: error.message,
          started_at: startedAt,
          completed_at: new Date().toISOString(),
        }]);

      toast.error(`Erro ao sincronizar clientes: ${error.message}`);
    } finally {
      setSyncing(false);
      setProgress({ current: 0, total: 0 });
    }
  };

  return {
    syncing,
    progress,
    syncCampaigns,
    syncAllClients,
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { useCompany } from '@/contexts/CompanyContext';

export interface GoogleSyncOptions {
  period: string;
  campaigns: boolean;
  adGroups: boolean;
  ads: boolean;
  includeInactive: boolean;
}

export interface GoogleSyncSchedule {
  id: string;
  company_id: string;
  is_enabled: boolean;
  sync_options: GoogleSyncOptions;
  scheduled_times: string[];
  executions_per_day: number;
  last_execution_at: string | null;
  next_execution_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface GoogleExecutionLog {
  id: string;
  company_id: string;
  schedule_id: string | null;
  status: 'running' | 'completed' | 'failed' | 'partial';
  clients_processed: number;
  clients_total: number;
  sync_options: GoogleSyncOptions;
  started_at: string;
  completed_at: string | null;
  error_message: string | null;
  execution_details: unknown;
}

export const useGoogleAdsSyncSchedule = () => {
  const [schedule, setSchedule] = useState<GoogleSyncSchedule | null>(null);
  const [executionLogs, setExecutionLogs] = useState<GoogleExecutionLog[]>([]);
  const [loading, setLoading] = useState(false);
  const [logsLoading, setLogsLoading] = useState(false);
  const { toast } = useToast();
  const { activeCompany } = useCompany();

  const fetchSchedule = async () => {
    const companyId = activeCompany?.company_id;
    if (!companyId) {
      return;
    }

    try {
      setLoading(true);

      const { data, error } = await supabase.functions.invoke('manage-google-ads-sync-schedule', {
        body: JSON.stringify({
          action: 'get',
          company_id: companyId,
        }),
      });

      if (error) throw error;

      // Handle case where data might be a string (double-parsed)
      const parsedData = typeof data === 'string' ? JSON.parse(data) : data;
      setSchedule(parsedData?.schedule || null);
    } catch (error: unknown) {
      console.error('Error fetching schedule:', error);
      toast({
        title: 'Erro ao carregar configuração',
        description: error.message,
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchExecutionLogs = async () => {
    if (!activeCompany?.company_id) return;

    try {
      setLogsLoading(true);
      const { data, error } = await supabase
        .from('google_ads_sync_execution_logs')
        .select('*')
        .eq('company_id', activeCompany.company_id)
        .order('started_at', { ascending: false })
        .limit(10);

      if (error) throw error;

      // Cast with type validation
      const logs = (data || []).map(log => ({
        ...log,
        status: log.status as 'running' | 'completed' | 'failed' | 'partial',
        sync_options: log.sync_options as unknown as GoogleSyncOptions,
      }));

      setExecutionLogs(logs);
    } catch (error: unknown) {
      console.error('Error fetching execution logs:', error);
    } finally {
      setLogsLoading(false);
    }
  };

  const saveSchedule = async (
    isEnabled: boolean,
    syncOptions: GoogleSyncOptions,
    executionsPerDay: number
  ) => {
    const companyId = activeCompany?.company_id;
    if (!companyId) return;

    try {
      setLoading(true);
      const { data, error } = await supabase.functions.invoke('manage-google-ads-sync-schedule', {
        body: JSON.stringify({
          action: 'upsert',
          company_id: companyId,
          is_enabled: isEnabled,
          sync_options: syncOptions,
          executions_per_day: executionsPerDay,
        }),
      });

      if (error) throw error;

      const parsedData = typeof data === 'string' ? JSON.parse(data) : data;
      setSchedule(parsedData?.schedule || null);
      toast({
        title: 'Configuração salva',
        description: 'As configurações de sincronização do Google Ads foram atualizadas.',
      });

      return parsedData?.schedule;
    } catch (error: unknown) {
      console.error('Error saving schedule:', error);
      toast({
        title: 'Erro ao salvar configuração',
        description: error.message,
        variant: 'destructive',
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const toggleSchedule = async (enabled: boolean) => {
    const companyId = activeCompany?.company_id;
    if (!companyId) return;

    try {
      setLoading(true);
      const { data, error } = await supabase.functions.invoke('manage-google-ads-sync-schedule', {
        body: JSON.stringify({
          action: 'patch',
          company_id: companyId,
          is_enabled: enabled,
        }),
      });

      if (error) throw error;

      const parsedData = typeof data === 'string' ? JSON.parse(data) : data;
      setSchedule(parsedData?.schedule || null);
      toast({
        title: enabled ? 'Sincronização ativada' : 'Sincronização desativada',
        description: enabled 
          ? 'A sincronização automática do Google Ads foi ativada.' 
          : 'A sincronização automática do Google Ads foi desativada.',
      });

      return parsedData?.schedule;
    } catch (error: unknown) {
      console.error('Error toggling schedule:', error);
      toast({
        title: 'Erro ao alterar status',
        description: error.message,
        variant: 'destructive',
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const deleteSchedule = async () => {
    const companyId = activeCompany?.company_id;
    if (!companyId) return;

    try {
      setLoading(true);
      const { error } = await supabase.functions.invoke('manage-google-ads-sync-schedule', {
        body: JSON.stringify({
          action: 'delete',
          company_id: companyId,
        }),
      });

      if (error) throw error;

      setSchedule(null);
      toast({
        title: 'Configuração removida',
        description: 'A configuração de sincronização foi removida.',
      });
    } catch (error: unknown) {
      console.error('Error deleting schedule:', error);
      toast({
        title: 'Erro ao remover configuração',
        description: error.message,
        variant: 'destructive',
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (activeCompany?.company_id) {
      fetchSchedule();
      fetchExecutionLogs();
    }
  }, [activeCompany?.company_id]);

  return {
    schedule,
    executionLogs,
    loading,
    logsLoading,
    fetchSchedule,
    fetchExecutionLogs,
    saveSchedule,
    toggleSchedule,
    deleteSchedule,
  };
};

import { useState, useEffect, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useCompany } from "@/contexts/CompanyContext";
import { useToast } from "@/hooks/use-toast";

interface Agent {
  id: string;
  agent_name: string;
  description: string | null;
  prompt_base: string;
  additional_instructions: string | null;
  model: string;
  client_id: string | null;
  created_at: string;
  updated_at: string;
  client?: {
    id: string;
    name: string;
    company: string;
  } | null;
}

interface Conversation {
  id: string;
  agent_id: string;
  title: string;
  created_at: string;
  updated_at: string;
}

interface Message {
  id: string;
  conversation_id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  created_at: string;
}

export function useIAAgents() {
  const [agents, setAgents] = useState<Agent[]>([]);
  const [currentAgent, setCurrentAgent] = useState<Agent | null>(null);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [currentConversation, setCurrentConversation] = useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(false);
  const isFetchingRef = useRef(false);
  const lastCompanyIdRef = useRef<string | null>(null);

  const { user } = useAuth();
  const { activeCompany } = useCompany();
  const { toast } = useToast();

  // Buscar todos os agentes
  const fetchAgents = async () => {
    if (!activeCompany || isFetchingRef.current) return;

    isFetchingRef.current = true;
    try {
      const { data, error } = await supabase
        .from('ia_agents')
        .select(`
          *,
          client:clients(id, name, company)
        `)
        .eq('company_id', activeCompany.company_id)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setAgents(data || []);
    } catch (error) {
      console.error('Error fetching agents:', error);
      toast({
        title: "Erro ao carregar agentes",
        description: "Não foi possível carregar os agentes.",
        variant: "destructive",
      });
    } finally {
      isFetchingRef.current = false;
    }
  };

  // Criar novo agente
  const createAgent = async (agentData: {
    agent_name: string;
    description?: string;
    prompt_base: string;
    additional_instructions?: string;
    model?: string;
    client_id?: string | null;
  }) => {
    if (!user || !activeCompany) return null;

    // Validação do prompt
    if (agentData.prompt_base.length < 50) {
      toast({
        title: "Prompt muito curto",
        description: "O prompt deve ter no mínimo 50 caracteres.",
        variant: "destructive",
      });
      return null;
    }

    try {
      const { data, error } = await supabase
        .from('ia_agents')
        .insert({
          ...agentData,
          company_id: activeCompany.company_id,
          user_id: user.id,
          model: agentData.model || 'google/gemini-2.5-flash'
        })
        .select()
        .single();

      if (error) throw error;

      // Adiciona o novo agente ao início da lista imediatamente
      setAgents(prev => [data, ...prev]);

      toast({
        title: "Agente criado",
        description: "Agente criado com sucesso!",
      });

      return data;
    } catch (error) {
      console.error('Error creating agent:', error);
      toast({
        title: "Erro ao criar agente",
        description: "Não foi possível criar o agente.",
        variant: "destructive",
      });
      return null;
    }
  };

  // Atualizar agente
  const updateAgent = async (agentId: string, updates: Partial<Agent>) => {
    try {
      const { error } = await supabase
        .from('ia_agents')
        .update(updates)
        .eq('id', agentId);

      if (error) throw error;

      await fetchAgents();
      if (currentAgent?.id === agentId) {
        setCurrentAgent({ ...currentAgent, ...updates });
      }

      toast({
        title: "Agente atualizado",
        description: "Agente atualizado com sucesso!",
      });
    } catch (error) {
      console.error('Error updating agent:', error);
      toast({
        title: "Erro ao atualizar agente",
        description: "Não foi possível atualizar o agente.",
        variant: "destructive",
      });
    }
  };

  // Duplicar agente
  const duplicateAgent = async (agentId: string) => {
    const agent = agents.find(a => a.id === agentId);
    if (!agent) return;

    await createAgent({
      agent_name: `${agent.agent_name} (Cópia)`,
      description: agent.description || undefined,
      prompt_base: agent.prompt_base,
      additional_instructions: agent.additional_instructions || undefined,
      model: agent.model
    });
  };

  // Excluir agente
  const deleteAgent = async (agentId: string) => {
    try {
      const { error } = await supabase
        .from('ia_agents')
        .delete()
        .eq('id', agentId);

      if (error) throw error;

      setAgents(prev => prev.filter(a => a.id !== agentId));

      if (currentAgent?.id === agentId) {
        setCurrentAgent(null);
        setCurrentConversation(null);
        setMessages([]);
      }

      toast({
        title: "Agente excluído",
        description: "Agente excluído com sucesso!",
      });
    } catch (error) {
      console.error('Error deleting agent:', error);
      toast({
        title: "Erro ao excluir agente",
        description: "Não foi possível excluir o agente.",
        variant: "destructive",
      });
    }
  };

  // Buscar conversas de um agente
  const fetchConversations = async (agentId: string) => {
    if (!user) return;

    try {
      const { data, error } = await supabase
        .from('ia_agent_conversations')
        .select('*')
        .eq('agent_id', agentId)
        .eq('user_id', user.id)
        .order('updated_at', { ascending: false });

      if (error) throw error;
      setConversations(data || []);
    } catch (error) {
      console.error('Error fetching conversations:', error);
    }
  };

  // Criar nova conversa
  const createConversation = async (agentId: string) => {
    if (!user || !activeCompany) return;

    try {
      const { data, error } = await supabase
        .from('ia_agent_conversations')
        .insert({
          agent_id: agentId,
          company_id: activeCompany.company_id,
          user_id: user.id,
          title: 'Nova conversa'
        })
        .select()
        .single();

      if (error) throw error;

      setCurrentConversation(data);
      setMessages([]);
      await fetchConversations(agentId);
    } catch (error) {
      console.error('Error creating conversation:', error);
      toast({
        title: "Erro ao criar conversa",
        description: "Não foi possível criar uma nova conversa.",
        variant: "destructive",
      });
    }
  };

  // Buscar mensagens
  const fetchMessages = async (conversationId: string) => {
    try {
      const { data, error } = await supabase
        .from('ia_agent_messages')
        .select('*')
        .eq('conversation_id', conversationId)
        .order('created_at', { ascending: true });

      if (error) throw error;
      setMessages((data || []) as Message[]);
    } catch (error) {
      console.error('Error fetching messages:', error);
    }
  };

  // Enviar mensagem
  const sendMessage = async (message: string) => {
    if (!currentConversation || !currentAgent) return;

    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke('ia-agent-chat', {
        body: {
          conversationId: currentConversation.id,
          message,
          agentId: currentAgent.id
        }
      });

      if (error) throw error;

      if (!data.success) {
        throw new Error(data.error || 'Erro desconhecido');
      }

      await fetchMessages(currentConversation.id);
      await fetchConversations(currentAgent.id);

    } catch (error) {
      console.error('Error sending message:', error);
      toast({
        title: "Erro ao enviar mensagem",
        description: "Não foi possível enviar a mensagem.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  // Carregar agente
  const loadAgent = async (agentId: string) => {
    // Primeiro tenta encontrar no array já carregado
    let agent = agents.find(a => a.id === agentId);

    // Se não encontrar, busca direto do banco
    if (!agent) {
      try {
        const { data, error } = await supabase
          .from('ia_agents')
          .select('*')
          .eq('id', agentId)
          .single();

        if (error) throw error;
        agent = data;

        // Atualiza a lista local também
        setAgents(prev => {
          const exists = prev.find(a => a.id === agentId);
          if (exists) return prev;
          return [data, ...prev];
        });
      } catch (error) {
        console.error('Error loading agent:', error);
        toast({
          title: "Erro ao carregar agente",
          description: "Não foi possível carregar o agente.",
          variant: "destructive",
        });
        return;
      }
    }

    setCurrentAgent(agent);
    await fetchConversations(agentId);
  };

  // Carregar conversa
  const loadConversation = async (conversationId: string) => {
    const conversation = conversations.find(c => c.id === conversationId);
    if (conversation) {
      setCurrentConversation(conversation);
      await fetchMessages(conversationId);
    }
  };

  // Renomear conversa
  const renameConversation = async (conversationId: string, newTitle: string) => {
    try {
      const { error } = await supabase
        .from('ia_agent_conversations')
        .update({ title: newTitle })
        .eq('id', conversationId);

      if (error) throw error;

      // Atualiza o estado local
      setConversations(prev => 
        prev.map(c => c.id === conversationId ? { ...c, title: newTitle } : c)
      );

      // Atualiza a conversa atual se for a mesma
      if (currentConversation?.id === conversationId) {
        setCurrentConversation(prev => prev ? { ...prev, title: newTitle } : null);
      }

      toast({
        title: "Conversa renomeada",
        description: "O título da conversa foi atualizado.",
      });
    } catch (error) {
      console.error('Error renaming conversation:', error);
      toast({
        title: "Erro ao renomear conversa",
        description: "Não foi possível renomear a conversa.",
        variant: "destructive",
      });
    }
  };

  // Excluir conversa
  const deleteConversation = async (conversationId: string) => {
    try {
      const { error } = await supabase
        .from('ia_agent_conversations')
        .delete()
        .eq('id', conversationId);

      if (error) throw error;

      setConversations(prev => prev.filter(c => c.id !== conversationId));

      if (currentConversation?.id === conversationId) {
        setCurrentConversation(null);
        setMessages([]);
      }

      toast({
        title: "Conversa excluída",
        description: "Conversa excluída com sucesso!",
      });
    } catch (error) {
      console.error('Error deleting conversation:', error);
      toast({
        title: "Erro ao excluir conversa",
        description: "Não foi possível excluir a conversa.",
        variant: "destructive",
      });
    }
  };

  useEffect(() => {
    const currentCompanyId = activeCompany?.company_id;

    // Só busca se o company_id realmente mudou
    if (currentCompanyId && currentCompanyId !== lastCompanyIdRef.current) {
      lastCompanyIdRef.current = currentCompanyId;
      fetchAgents();
    }
  }, [activeCompany?.company_id]);

  return {
    agents,
    currentAgent,
    conversations,
    currentConversation,
    messages,
    loading,
    createAgent,
    updateAgent,
    duplicateAgent,
    deleteAgent,
    loadAgent,
    createConversation,
    loadConversation,
    renameConversation,
    deleteConversation,
    sendMessage
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useCompany } from '@/contexts/CompanyContext';
import { toast } from '@/hooks/use-toast';

interface IdeogramPrompt {
  id?: string;
  company_id: string;
  content_type: string;
  default_prompt: string;
  custom_prompt?: string;
  is_active: boolean;
  created_at?: string;
  updated_at?: string;
}

const DEFAULT_IDEOGRAM_PROMPT = `PROFESSIONAL PHOTOGRAPHY: Create a real marketing campaign photograph - NOT an illustration or cartoon

TEXT: "{textToUse}"
MANDATORY: Use EXACTLY this text in Portuguese Brazil - no changes, additions or modifications

VISUAL CONTEXT:
- Client: {clientName} ({sectorContext} sector)
- Target audience: {audienceContext}
- Campaign theme: {theme}
- Creative type: {creativeType}
{clientBriefing}

PHOTOGRAPHY SPECIFICATIONS:
- MUST be ultra-realistic photography style - like shot with professional DSLR camera
- Professional studio lighting or natural lighting setup
- High-resolution commercial photography quality
- Corporate, professional design with clean, modern layout
- Clean, modern **typography** with excellent readability
- Colors and visual style aligned with the branding of the {sectorContext} sector
- Visual appeal for {audienceContext}
- Background: Clean, professional, and contextually appropriate

STRICT TEXT RULES:
- TEXT MUST BE EXACTLY: "{textToUse}"
- NO extra words, slogans, or additional text
- NO English words
- NO spelling errors or invented words
- NO distortions or variations in the text
- NO decorative or artistic fonts — only professional fonts

CRITICAL REQUIREMENTS:
- NEVER use illustration, cartoon, drawing, sketch, anime, manga, comic, flat design, vector art, digital art, painting, artistic rendering, 3D render, clipart, icon, logo, symbol, or graphic design
- MUST look like an actual photograph taken by a professional photographer
- MUST appear as a real marketing campaign photo that could be used by a major brand
- Use realistic lighting, shadows, depth of field, and photographic composition
- Focus on creating a highly professional and realistic advertisement photograph`;

export function useIdeogramPrompt() {
  const { activeCompany } = useCompany();
  const [prompt, setPrompt] = useState<IdeogramPrompt | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchPrompt = async () => {
    if (!activeCompany?.id) return;

    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase
        .from('content_prompts')
        .select('*')
        .eq('company_id', activeCompany.id)
        .eq('content_type', 'ideogram_creative')
        .maybeSingle();

      if (error) {
        throw error;
      }

      setPrompt(data);
    } catch (err) {
      console.error('Error fetching ideogram prompt:', err);
      setError(err instanceof Error ? err.message : 'Erro ao buscar prompt');
    } finally {
      setLoading(false);
    }
  };

  const savePrompt = async (customPrompt: string) => {
    if (!activeCompany?.id) return;

    // Validação mínima
    if (customPrompt.trim().length < 100) {
      toast({
        title: "Erro de validação",
        description: "O prompt deve ter pelo menos 100 caracteres.",
        variant: "destructive",
      });
      return;
    }

    // Validar se contém variáveis essenciais
    if (!customPrompt.includes('{textToUse}')) {
      toast({
        title: "Erro de validação",
        description: "O prompt deve conter a variável {textToUse}.",
        variant: "destructive",
      });
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const { data, error } = await supabase
        .from('content_prompts')
        .upsert({
          company_id: activeCompany.id,
          content_type: 'ideogram_creative',
          default_prompt: DEFAULT_IDEOGRAM_PROMPT,
          custom_prompt: customPrompt,
          is_active: true,
        })
        .select()
        .single();

      if (error) {
        throw error;
      }

      setPrompt(data);
      toast({
        title: "Sucesso",
        description: "Prompt personalizado salvo com sucesso!",
      });
    } catch (err) {
      console.error('Error saving ideogram prompt:', err);
      setError(err instanceof Error ? err.message : 'Erro ao salvar prompt');
      toast({
        title: "Erro",
        description: "Erro ao salvar prompt personalizado.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const resetPrompt = async () => {
    if (!activeCompany?.id || !prompt?.id) return;

    setLoading(true);
    setError(null);

    try {
      const { error } = await supabase
        .from('content_prompts')
        .delete()
        .eq('id', prompt.id);

      if (error) {
        throw error;
      }

      setPrompt(null);
      toast({
        title: "Sucesso",
        description: "Prompt resetado para o padrão com sucesso!",
      });
    } catch (err) {
      console.error('Error resetting ideogram prompt:', err);
      setError(err instanceof Error ? err.message : 'Erro ao resetar prompt');
      toast({
        title: "Erro",
        description: "Erro ao resetar prompt para o padrão.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const getFinalPrompt = () => {
    return prompt?.custom_prompt && prompt.custom_prompt.trim() 
      ? prompt.custom_prompt 
      : DEFAULT_IDEOGRAM_PROMPT;
  };

  const isCustomized = () => {
    return prompt?.custom_prompt && prompt.custom_prompt.trim().length > 0;
  };

  useEffect(() => {
    fetchPrompt();
  }, [activeCompany?.id]);

  return {
    prompt,
    loading,
    error,
    savePrompt,
    resetPrompt,
    getFinalPrompt,
    isCustomized,
    refetch: fetchPrompt,
    defaultPrompt: DEFAULT_IDEOGRAM_PROMPT,
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useCompany } from "@/contexts/CompanyContext";
import { useAuth } from "@/hooks/useAuth";

export const useLeadDisqualificationNotifications = () => {
  const [unviewedCount, setUnviewedCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();
  const { activeCompany } = useCompany();
  const { user } = useAuth();

  const fetchUnviewedCount = async () => {
    if (!activeCompany?.company_id) return;

    try {
      const { data, error } = await supabase
        .from('lead_disqualification_reports')
        .select('id')
        .eq('company_id', activeCompany.company_id)
        .is('viewed_at', null);

      if (error) throw error;

      const count = data?.length || 0;
      setUnviewedCount(count);
    } catch (err) {
      console.error('Error fetching unviewed count:', err);
    }
  };

  const markAllAsViewed = async () => {
    if (!activeCompany?.company_id || !user?.id) {
      return;
    }

    try {
      setLoading(true);

      // Primeiro buscar quantos reports precisam ser marcados
      const { data: unviewedReports, error: fetchError } = await supabase
        .from('lead_disqualification_reports')
        .select('id, reporter_name, created_at')
        .eq('company_id', activeCompany.company_id)
        .is('viewed_at', null);


      if (fetchError) {
        console.error('markAllAsViewed: Erro ao buscar reports:', fetchError);
        throw fetchError;
      }

      if (!unviewedReports || unviewedReports.length === 0) {
        setUnviewedCount(0);
        return;
      }


      const { data: updateResult, error: updateError } = await supabase
        .from('lead_disqualification_reports')
        .update({
          viewed_at: new Date().toISOString(),
          viewed_by: user.id
        })
        .eq('company_id', activeCompany.company_id)
        .is('viewed_at', null)
        .select('id');


      if (updateError) {
        console.error('markAllAsViewed: Erro ao atualizar records:', updateError);
        throw updateError;
      }

      // Atualizar imediatamente o contador local
      setUnviewedCount(0);

    } catch (err) {
      console.error('markAllAsViewed: Erro completo:', err);
      toast({
        title: "Erro",
        description: "Não foi possível marcar os reports como visualizados",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUnviewedCount();

    // Escutar evento customizado para forçar refresh
    const handleRefresh = () => {
      fetchUnviewedCount();
    };

    window.addEventListener('refreshNotificationCount', handleRefresh);

    // Setup realtime subscription
    if (activeCompany?.company_id) {
      const channel = supabase
        .channel('lead-disqualification-notifications')
        .on(
          'postgres_changes',
          {
            event: 'INSERT',
            schema: 'public',
            table: 'lead_disqualification_reports',
            filter: `company_id=eq.${activeCompany.company_id}`
          },
          () => {
            fetchUnviewedCount();
            toast({
              title: "Novo lead desqualificado",
              description: "Um novo report de lead desqualificado foi recebido",
            });
          }
        )
        .on(
          'postgres_changes',
          {
            event: 'UPDATE',
            schema: 'public',
            table: 'lead_disqualification_reports',
            filter: `company_id=eq.${activeCompany.company_id}`
          },
          (payload) => {
            // Só atualizar se não estamos na tela de admin (para evitar loops)
            if (window.location.pathname !== '/leads-desqualificados') {
              fetchUnviewedCount();
            }
          }
        )
        .subscribe();

      return () => {
        window.removeEventListener('refreshNotificationCount', handleRefresh);
        supabase.removeChannel(channel);
      };
    }

    return () => {
      window.removeEventListener('refreshNotificationCount', handleRefresh);
    };
  }, [activeCompany?.company_id]);

  return {
    unviewedCount,
    loading,
    markAllAsViewed,
    fetchUnviewedCount
  };
};

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useCompany } from "@/contexts/CompanyContext";

export interface LeadDisqualificationReport {
  id: string;
  client_id: string;
  company_id: string;
  token_id: string;
  reporter_name: string;
  lead_received_date: string;
  disqualification_reason: 'fora_perfil' | 'informacoes_incorretas' | 'contato_errado' | 'ligacao_sem_resposta' | 'outro';
  additional_notes?: string;
  evidence_file_url?: string;
  conversation_link?: string;
  created_at: string;
  updated_at: string;
  viewed_at?: string;
  viewed_by?: string;
}

interface ReportsFilters {
  clientId?: string;
  reason?: string;
  startDate?: string;
  endDate?: string;
  viewedStatus?: string;
}

export const useLeadDisqualificationReports = (filters?: ReportsFilters) => {
  const [reports, setReports] = useState<LeadDisqualificationReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { toast } = useToast();
  const { activeCompany } = useCompany();

  const fetchReports = async () => {
    if (!activeCompany?.company_id) return;

    try {
      setLoading(true);
      setError(null);

      let query = supabase
        .from('lead_disqualification_reports')
        .select('*')
        .eq('company_id', activeCompany.company_id);

      if (filters?.clientId && filters.clientId !== 'all') {
        query = query.eq('client_id', filters.clientId);
      }

      if (filters?.reason && filters.reason !== 'all') {
        query = query.eq('disqualification_reason', filters.reason);
      }

      if (filters?.startDate) {
        query = query.gte('created_at', filters.startDate);
      }

      if (filters?.endDate) {
        query = query.lte('created_at', filters.endDate);
      }

      if (filters?.viewedStatus && filters.viewedStatus !== 'all') {
        if (filters.viewedStatus === 'viewed') {
          query = query.not('viewed_at', 'is', null);
        } else if (filters.viewedStatus === 'unviewed') {
          query = query.is('viewed_at', null);
        }
      }

      const { data, error } = await query.order('created_at', { ascending: false });

      if (error) throw error;

      setReports((data || []) as LeadDisqualificationReport[]);
    } catch (err) {
      console.error('Error fetching lead disqualification reports:', err);
      setError(err instanceof Error ? err.message : 'Erro ao carregar reports');
      toast({
        title: "Erro",
        description: "Não foi possível carregar os reports de desqualificação",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const getReasonLabel = (reason: string) => {
    const labels = {
      'fora_perfil': 'Fora do perfil',
      'informacoes_incorretas': 'Informações incorretas',
      'contato_errado': 'Contato errado',
      'ligacao_sem_resposta': 'Ligação sem resposta',
      'outro': 'Outro'
    };
    return labels[reason as keyof typeof labels] || reason;
  };

  const exportReports = async (format: 'csv' | 'pdf') => {
    try {
      // Implementar exportação aqui
      toast({
        title: "Sucesso",
        description: `Exportação ${format.toUpperCase()} iniciada`,
      });
    } catch (err) {
      console.error('Error exporting reports:', err);
      toast({
        title: "Erro",
        description: "Não foi possível exportar os reports",
        variant: "destructive",
      });
    }
  };

  useEffect(() => {
    fetchReports();
  }, [activeCompany?.company_id, filters?.clientId, filters?.reason, filters?.startDate, filters?.endDate, filters?.viewedStatus]);

  return {
    reports,
    loading,
    error,
    fetchReports,
    getReasonLabel,
    exportReports
  };
};

