import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useCompany } from '@/contexts/CompanyContext';

interface LeadQualityData {
  totalLeads: number;
  disqualifiedLeads: number;
  mqlPercentage: number;
  periodStart?: string;
  periodEnd?: string;
}

export function useLeadQuality() {
  const [data, setData] = useState<LeadQualityData>({
    totalLeads: 0,
    disqualifiedLeads: 0,
    mqlPercentage: 0
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { activeCompany } = useCompany();

  const fetchLeadQualityData = async () => {
    if (!activeCompany?.company_id) return;

    setLoading(true);
    setError(null);

    try {

      // Primeiro, buscar dados sem filtro de período para debug
      const { data: allCampaigns, error: allCampaignsError } = await supabase
        .from('campaigns')
        .select('conversions, updated_at')
        .eq('company_id', activeCompany.company_id);

      if (allCampaignsError) throw allCampaignsError;

      const { data: allReports, error: allReportsError } = await supabase
        .from('lead_disqualification_reports')
        .select('id, lead_received_date')
        .eq('company_id', activeCompany.company_id);

      if (allReportsError) throw allReportsError;


      const totalLeadsAll = allCampaigns?.reduce((sum, campaign) => sum + (campaign.conversions || 0), 0) || 0;

      // Buscar dados de sincronização mais recente para determinar o período
      const { data: clients, error: clientsError } = await supabase
        .from('clients')
        .select('last_sync_at, last_sync_period')
        .eq('company_id', activeCompany.company_id)
        .not('last_sync_at', 'is', null)
        .order('last_sync_at', { ascending: false })
        .limit(1);

      if (clientsError) throw clientsError;

      let periodStart: string | undefined;
      let periodEnd: string | undefined;
      let totalLeads = totalLeadsAll;
      let disqualifiedLeads = allReports?.length || 0;

      // Se houver sincronização recente, aplicar filtro de período
      if (clients && clients.length > 0) {
        const lastSync = clients[0];
        const syncDate = new Date(lastSync.last_sync_at);


        // Calcular período baseado na última sincronização
        switch (lastSync.last_sync_period) {
          case '7_days':
            periodStart = new Date(syncDate.getTime() - (7 * 24 * 60 * 60 * 1000)).toISOString().split('T')[0];
            break;
          case '30_days':
            periodStart = new Date(syncDate.getTime() - (30 * 24 * 60 * 60 * 1000)).toISOString().split('T')[0];
            break;
          case '90_days':
            periodStart = new Date(syncDate.getTime() - (90 * 24 * 60 * 60 * 1000)).toISOString().split('T')[0];
            break;
          case 'custom':
            periodStart = new Date(syncDate.getTime() - (30 * 24 * 60 * 60 * 1000)).toISOString().split('T')[0];
            break;
          default:
            periodStart = new Date(syncDate.getTime() - (30 * 24 * 60 * 60 * 1000)).toISOString().split('T')[0];
        }
        periodEnd = syncDate.toISOString().split('T')[0];


        // Aplicar filtro de período nas campanhas
        const filteredCampaigns = allCampaigns?.filter(campaign => {
          const campaignDate = campaign.updated_at.split('T')[0];
          return campaignDate >= periodStart! && campaignDate <= periodEnd!;
        }) || [];

        totalLeads = filteredCampaigns.reduce((sum, campaign) => sum + (campaign.conversions || 0), 0);

        // Aplicar filtro de período nos relatórios
        const filteredReports = allReports?.filter(report => {
          const reportDate = report.lead_received_date;
          return reportDate >= periodStart! && reportDate <= periodEnd!;
        }) || [];

        disqualifiedLeads = filteredReports.length;

      } else {
        // Fallback: usar últimos 30 dias se não houver sincronização
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        periodStart = thirtyDaysAgo.toISOString().split('T')[0];
        periodEnd = new Date().toISOString().split('T')[0];
      }


      const qualifiedLeads = Math.max(0, totalLeads - disqualifiedLeads);
      const mqlPercentage = totalLeads > 0 ? (qualifiedLeads / totalLeads) * 100 : 0;


      setData({
        totalLeads,
        disqualifiedLeads,
        mqlPercentage,
        periodStart,
        periodEnd
      });

    } catch (err) {
      console.error('Error fetching lead quality data:', err);
      setError(err instanceof Error ? err.message : 'Erro ao carregar dados de qualidade de leads');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLeadQualityData();
  }, [activeCompany?.company_id]);

  return {
    data,
    loading,
    error,
    refetch: fetchLeadQualityData
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { useCompany } from '@/contexts/CompanyContext';
import { toast } from 'sonner';

export interface MarketResearchInsight {
  id: string;
  client_id: string;
  company_id: string;
  topic: string;
  pain_point: string | null;
  opportunity: string | null;
  sentiment: string | null;
  relevance_score: number | null;
  source_url: string | null;
  source_type: string;
  raw_content: string | null;
  extracted_quotes: string[] | null;
  used_in_ads: number;
  last_used_at: string | null;
  created_at: string;
  updated_at: string;
}

export const useMarketResearchInsights = (clientId?: string) => {
  const [insights, setInsights] = useState<MarketResearchInsight[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { activeCompany } = useCompany();

  const fetchInsights = async () => {
    if (!user?.id || !activeCompany?.company_id || !clientId) return;

    try {
      setLoading(true);
      const { data, error } = await supabase
        .from('market_research_insights')
        .select('*')
        .eq('client_id', clientId)
        .eq('company_id', activeCompany.company_id)
        .order('relevance_score', { ascending: false, nullsFirst: false });

      if (error) throw error;

      setInsights(data?.map(item => ({
        ...item,
        extracted_quotes: item.extracted_quotes as string[] | null
      })) || []);
    } catch (err) {
      console.error('Error fetching insights:', err);
      setError(err instanceof Error ? err.message : 'Erro ao carregar insights');
    } finally {
      setLoading(false);
    }
  };

  const createInsight = async (insightData: Partial<MarketResearchInsight>) => {
    if (!user?.id || !activeCompany?.company_id || !clientId) {
      throw new Error('Dados de autenticação não disponíveis');
    }

    if (!insightData.topic) {
      throw new Error('O tópico é obrigatório');
    }

    const { data, error } = await supabase
      .from('market_research_insights')
      .insert({
        topic: insightData.topic,
        pain_point: insightData.pain_point,
        opportunity: insightData.opportunity,
        sentiment: insightData.sentiment || 'neutral',
        relevance_score: insightData.relevance_score || 50,
        source_url: insightData.source_url,
        source_type: insightData.source_type || 'manual',
        raw_content: insightData.raw_content,
        extracted_quotes: insightData.extracted_quotes,
        client_id: clientId,
        company_id: activeCompany.company_id,
      })
      .select()
      .single();

    if (error) throw error;

    setInsights(prev => [{ ...data, extracted_quotes: data.extracted_quotes as string[] | null }, ...prev]);
    toast.success('Tema de pesquisa adicionado com sucesso!');
    return data;
  };

  const updateInsight = async (id: string, updates: Partial<MarketResearchInsight>) => {
    const { data, error } = await supabase
      .from('market_research_insights')
      .update(updates)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

    setInsights(prev => prev.map(insight => 
      insight.id === id ? { ...data, extracted_quotes: data.extracted_quotes as string[] | null } : insight
    ));
    toast.success('Tema atualizado com sucesso!');
    return data;
  };

  const deleteInsight = async (id: string) => {
    const { error } = await supabase
      .from('market_research_insights')
      .delete()
      .eq('id', id);

    if (error) throw error;

    setInsights(prev => prev.filter(insight => insight.id !== id));
    toast.success('Tema removido com sucesso!');
  };

  useEffect(() => {
    if (clientId) {
      fetchInsights();
    }
  }, [user?.id, activeCompany?.company_id, clientId]);

  return {
    insights,
    loading,
    error,
    createInsight,
    updateInsight,
    deleteInsight,
    refetch: fetchInsights
  };
};

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { useToast } from "@/hooks/use-toast";

export interface PeriodComparison {
  id: string;
  client_id: string;
  company_id: string;
  user_id: string;
  comparison_name: string;
  period_1_start: string;
  period_1_end: string;
  period_1_label: string;
  period_2_start: string;
  period_2_end: string;
  period_2_label: string;
  status: 'pending' | 'syncing' | 'completed' | 'error';
  sync_progress: number;
  error_message?: string;
  created_at: string;
  updated_at: string;
}

export interface PeriodComparisonCampaign {
  id: string;
  comparison_id: string;
  period_number: number;
  facebook_campaign_id: string;
  campaign_name: string;
  status: string;
  objective?: string;
  spend: number;
  impressions: number;
  clicks: number;
  conversions: number;
  reach: number;
  frequency: number;
  ctr: number;
  cpc: number;
  cpa: number;
  quality_ranking?: string;
