export interface ComparisonMetrics {
  period1: {
    spend: number;
    conversions: number;
    ctr: number;
    cpc: number;
    cpa: number;
    impressions: number;
    clicks: number;
    reach: number;
    campaigns_count: number;
  };
  period2: {
    spend: number;
    conversions: number;
    ctr: number;
    cpc: number;
    cpa: number;
    impressions: number;
    clicks: number;
    reach: number;
