export function usePeriodComparisons(clientId?: string) {
  const [comparisons, setComparisons] = useState<PeriodComparison[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { toast } = useToast();

  const fetchComparisons = async () => {
    if (!user || !clientId) return;

    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("period_comparisons")
        .select("*")
        .eq("client_id", clientId)
        .order("created_at", { ascending: false });

      if (error) throw error;
      setComparisons((data || []) as PeriodComparison[]);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao buscar comparações");
    } finally {
      setLoading(false);
    }
  };

  const createComparison = async (data: {
    comparisonName: string;
    period1Start: string;
    period1End: string;
    period1Label: string;
    period2Start: string;
    period2End: string;
    period2Label: string;
    companyId: string;
  }) => {
    if (!user || !clientId) return null;

    try {
      const { data: comparison, error } = await supabase
        .from("period_comparisons")
        .insert([{
          client_id: clientId,
          company_id: data.companyId,
          user_id: user.id,
          comparison_name: data.comparisonName,
          period_1_start: data.period1Start,
          period_1_end: data.period1End,
          period_1_label: data.period1Label,
          period_2_start: data.period2Start,
          period_2_end: data.period2End,
          period_2_label: data.period2Label,
        }])
        .select()
        .single();

      if (error) throw error;

      await fetchComparisons();
      return comparison;
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao criar comparação");
      return null;
    }
  };

  const syncComparison = async (comparisonId: string) => {
    try {
      toast({
        title: "Sincronização iniciada",
        description: "Buscando dados dos períodos selecionados...",
      });

      const { data, error } = await supabase.functions.invoke('sync-period-comparison', {
        body: { comparisonId }
      });

      if (error) {
        console.error('Supabase function error:', error);
        throw error;
      }

      if (data?.error) {
        console.error('Function returned error:', data.error);
        throw new Error(data.error);
      }

      // Start polling for updates
      let attempts = 0;
      const maxAttempts = 150; // 5 minutes with 2-second intervals

      const pollInterval = setInterval(async () => {
        attempts++;

        try {
          const { data: comparisonData } = await supabase
            .from('period_comparisons')
            .select('status, sync_progress, error_message')
            .eq('id', comparisonId)
            .single();

          if (comparisonData?.status === 'completed') {
            clearInterval(pollInterval);
            toast({
              title: "Sincronização concluída",
              description: "Os dados foram sincronizados com sucesso!",
            });
            await fetchComparisons();
          } else if (comparisonData?.status === 'error') {
            clearInterval(pollInterval);
            toast({
              title: "Erro na sincronização",
              description: comparisonData.error_message || "Erro desconhecido",
              variant: "destructive",
            });
            await fetchComparisons();
          } else if (attempts >= maxAttempts) {
            clearInterval(pollInterval);
            toast({
              title: "Tempo limite excedido",
              description: "A sincronização está demorando mais que o esperado. Verifique o status mais tarde.",
              variant: "destructive",
            });
            await fetchComparisons();
          }
        } catch (pollError) {
          console.error('Error polling comparison status:', pollError);
          if (attempts >= 5) {
            clearInterval(pollInterval);
            toast({
              title: "Erro no monitoramento",
              description: "Não foi possível verificar o status da sincronização.",
              variant: "destructive",
            });
          }
        }
      }, 2000);

    } catch (err) {
      console.error('Error in syncComparison:', err);
      setError(err instanceof Error ? err.message : "Erro ao sincronizar comparação");
      toast({
        title: "Erro na sincronização",
        description: err instanceof Error ? err.message : "Erro desconhecido",
        variant: "destructive",
      });
    }
  };

  const getComparisonCampaigns = async (comparisonId: string): Promise<PeriodComparisonCampaign[]> => {
    try {
      const { data, error } = await supabase
        .from("period_comparison_campaigns")
        .select("*")
        .eq("comparison_id", comparisonId)
        .order("campaign_name", { ascending: true });

      if (error) throw error;
      return data || [];
    } catch (err) {
      console.error("Error fetching comparison campaigns:", err);
      return [];
    }
  };

  const getComparisonMetrics = async (comparisonId: string): Promise<ComparisonMetrics | null> => {
    try {
      const campaigns = await getComparisonCampaigns(comparisonId);

      const period1Campaigns = campaigns.filter(c => c.period_number === 1);
      const period2Campaigns = campaigns.filter(c => c.period_number === 2);

      const calculateTotals = (campaigns: PeriodComparisonCampaign[]) => ({
        spend: campaigns.reduce((sum, c) => sum + c.spend, 0),
        conversions: campaigns.reduce((sum, c) => sum + c.conversions, 0),
        impressions: campaigns.reduce((sum, c) => sum + c.impressions, 0),
        clicks: campaigns.reduce((sum, c) => sum + c.clicks, 0),
        reach: campaigns.reduce((sum, c) => sum + c.reach, 0),
        ctr: campaigns.length > 0 ? campaigns.reduce((sum, c) => sum + c.ctr, 0) / campaigns.length : 0,
        cpc: campaigns.length > 0 ? campaigns.reduce((sum, c) => sum + c.cpc, 0) / campaigns.length : 0,
        cpa: campaigns.length > 0 ? campaigns.reduce((sum, c) => sum + c.cpa, 0) / campaigns.length : 0,
        campaigns_count: campaigns.length,
      });

      const period1 = calculateTotals(period1Campaigns);
      const period2 = calculateTotals(period2Campaigns);

      const calculateChange = (current: number, previous: number) => ({
        absolute: current - previous,
        percentage: previous > 0 ? ((current - previous) / previous) * 100 : 0
      });

      const spendChange = calculateChange(period2.spend, period1.spend);
      const conversionsChange = calculateChange(period2.conversions, period1.conversions);
      const ctrChange = calculateChange(period2.ctr, period1.ctr);
      const cpcChange = calculateChange(period2.cpc, period1.cpc);
      const cpaChange = calculateChange(period2.cpa, period1.cpa);
      const impressionsChange = calculateChange(period2.impressions, period1.impressions);
      const clicksChange = calculateChange(period2.clicks, period1.clicks);
      const reachChange = calculateChange(period2.reach, period1.reach);

      return {
        period1,
        period2,
        changes: {
          spend_change: spendChange.absolute,
          spend_change_pct: spendChange.percentage,
          conversions_change: conversionsChange.absolute,
          conversions_change_pct: conversionsChange.percentage,
          ctr_change: ctrChange.absolute,
          ctr_change_pct: ctrChange.percentage,
          cpc_change: cpcChange.absolute,
          cpc_change_pct: cpcChange.percentage,
          cpa_change: cpaChange.absolute,
          cpa_change_pct: cpaChange.percentage,
          impressions_change: impressionsChange.absolute,
          impressions_change_pct: impressionsChange.percentage,
          clicks_change: clicksChange.absolute,
          clicks_change_pct: clicksChange.percentage,
          reach_change: reachChange.absolute,
          reach_change_pct: reachChange.percentage,
        }
      };
    } catch (err) {
      console.error("Error calculating comparison metrics:", err);
      return null;
    }
  };

  const deleteComparison = async (comparisonId: string) => {
    try {
      const { error } = await supabase
        .from("period_comparisons")
        .delete()
        .eq("id", comparisonId);

      if (error) throw error;

      await fetchComparisons();
      toast({
        title: "Comparação removida",
        description: "A comparação foi removida com sucesso.",
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao remover comparação");
      toast({
        title: "Erro ao remover",
        description: err instanceof Error ? err.message : "Erro desconhecido",
        variant: "destructive",
      });
    }
  };

  useEffect(() => {
    if (clientId) {
      fetchComparisons();
    }
  }, [user, clientId]);

  return {
    comparisons,
    loading,
    error,
    fetchComparisons,
    createComparison,
    syncComparison,
    getComparisonCampaigns,
    getComparisonMetrics,
    deleteComparison,
  };
}

import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useCompany } from "@/contexts/CompanyContext";
import { MenuItemType } from "@/hooks/useEmployeePermissions";

export interface PermissionGroup {
  id: string;
  name: string;
  description: string | null;
  company_id: string;
  created_at: string;
  updated_at: string;
  items: MenuItemType[];
  members: { id: string; employee_id: string }[];
}

export function usePermissionGroups() {
  const [groups, setGroups] = useState<PermissionGroup[]>([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();
  const { activeCompany } = useCompany();

  const fetchGroups = useCallback(async () => {
    if (!activeCompany?.company_id) return;
    try {
      setLoading(true);
      const { data: groupsData, error: groupsError } = await supabase
        .from('permission_groups')
        .select('*')
        .eq('company_id', activeCompany.company_id)
        .order('name');

      if (groupsError) throw groupsError;

      const groupIds = groupsData?.map(g => g.id) || [];
      if (groupIds.length === 0) {
        setGroups([]);
        return;
      }

      const [{ data: items }, { data: members }] = await Promise.all([
        supabase.from('permission_group_items').select('*').in('group_id', groupIds),
        supabase.from('permission_group_members').select('*').in('group_id', groupIds),
      ]);

      const result: PermissionGroup[] = (groupsData || []).map(g => ({
        ...g,
        items: (items || []).filter(i => i.group_id === g.id).map(i => i.menu_item as MenuItemType),
        members: (members || []).filter(m => m.group_id === g.id).map(m => ({ id: m.id, employee_id: m.employee_id })),
      }));

      setGroups(result);
    } catch (err: unknown) {
      console.error('Error fetching permission groups:', err);
      toast({ title: "Erro", description: "Erro ao carregar grupos de permissão", variant: "destructive" });
    } finally {
      setLoading(false);
    }
  }, [activeCompany?.company_id]);

  const createGroup = async (name: string, description: string) => {
    if (!activeCompany?.company_id) return;
    try {
      const { data, error } = await supabase
        .from('permission_groups')
        .insert({ name, description: description || null, company_id: activeCompany.company_id })
        .select()
        .single();

      if (error) throw error;
      toast({ title: "Grupo criado", description: `Grupo "${name}" criado com sucesso.` });
      await fetchGroups();
      return data;
    } catch (err: unknown) {
      toast({ title: "Erro", description: err.message, variant: "destructive" });
    }
  };

  const updateGroup = async (groupId: string, name: string, description: string) => {
    try {
      const { error } = await supabase
        .from('permission_groups')
        .update({ name, description: description || null })
        .eq('id', groupId);

      if (error) throw error;
      toast({ title: "Grupo atualizado" });
      await fetchGroups();
    } catch (err: unknown) {
      toast({ title: "Erro", description: err.message, variant: "destructive" });
    }
  };

  const deleteGroup = async (groupId: string) => {
    try {
      const { error } = await supabase
        .from('permission_groups')
        .delete()
        .eq('id', groupId);

      if (error) throw error;
      toast({ title: "Grupo excluído" });
      await fetchGroups();
    } catch (err: unknown) {
      toast({ title: "Erro", description: err.message, variant: "destructive" });
    }
  };

  const toggleGroupItem = async (groupId: string, menuItem: MenuItemType) => {
    const group = groups.find(g => g.id === groupId);
    if (!group) return;

    try {
      if (group.items.includes(menuItem)) {
        const { error } = await supabase
          .from('permission_group_items')
          .delete()
          .eq('group_id', groupId)
          .eq('menu_item', menuItem as unknown);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('permission_group_items')
          .insert({ group_id: groupId, menu_item: menuItem as unknown });
        if (error) throw error;
      }

      // Update local state optimistically
      setGroups(prev => prev.map(g => {
        if (g.id !== groupId) return g;
        const items = g.items.includes(menuItem)
          ? g.items.filter(i => i !== menuItem)
          : [...g.items, menuItem];
        return { ...g, items };
      }));
    } catch (err: unknown) {
      toast({ title: "Erro", description: err.message, variant: "destructive" });
    }
  };
  const setAllGroupItems = async (groupId: string, allMenuItems: MenuItemType[], enable: boolean) => {
    try {
      if (enable) {
        // Insert all items that don't exist yet
        const group = groups.find(g => g.id === groupId);
        const existingItems = group?.items || [];
        const newItems = allMenuItems.filter(item => !existingItems.includes(item));
        if (newItems.length > 0) {
          const { error } = await supabase
            .from('permission_group_items')
            .insert(newItems.map(item => ({ group_id: groupId, menu_item: item as unknown })));
          if (error) throw error;
        }
      } else {
        // Delete all items
        const { error } = await supabase
          .from('permission_group_items')
          .delete()
          .eq('group_id', groupId);
        if (error) throw error;
      }

      setGroups(prev => prev.map(g => {
        if (g.id !== groupId) return g;
        return { ...g, items: enable ? [...allMenuItems] : [] };
      }));

      toast({ title: enable ? "Todas permissões ativadas" : "Todas permissões desativadas" });
    } catch (err: unknown) {
      toast({ title: "Erro", description: err.message, variant: "destructive" });
    }
  };

  const addMember = async (groupId: string, employeeId: string) => {
    try {
      const { error } = await supabase
        .from('permission_group_members')
        .insert({ group_id: groupId, employee_id: employeeId });

      if (error) {
        if (error.code === '23505') {
          toast({ title: "Aviso", description: "Colaborador já está neste grupo." });
          return;
        }
        throw error;
      }
      toast({ title: "Membro adicionado" });
      await fetchGroups();
    } catch (err: unknown) {
      toast({ title: "Erro", description: err.message, variant: "destructive" });
    }
  };

  const removeMember = async (groupId: string, employeeId: string) => {
    try {
      const { error } = await supabase
        .from('permission_group_members')
        .delete()
        .eq('group_id', groupId)
        .eq('employee_id', employeeId);

      if (error) throw error;
      toast({ title: "Membro removido" });
      await fetchGroups();
    } catch (err: unknown) {
      toast({ title: "Erro", description: err.message, variant: "destructive" });
    }
  };

  useEffect(() => {
    if (activeCompany?.company_id) {
      fetchGroups();
    }
  }, [activeCompany?.company_id, fetchGroups]);

  return {
    groups,
    loading,
    fetchGroups,
    createGroup,
    updateGroup,
    deleteGroup,
    toggleGroupItem,
    setAllGroupItems,
    addMember,
    removeMember,
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useCompany } from '@/contexts/CompanyContext';
import { toast } from 'sonner';

export function useRadarTvDashboardToken() {
  const { activeCompany } = useCompany();
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    if (activeCompany?.company_id) {
      fetchToken();
    }
  }, [activeCompany?.company_id]);

  const fetchToken = async () => {
    if (!activeCompany?.company_id) return;

    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('companies')
        .select('radar_tv_dashboard_token')
        .eq('id', activeCompany.company_id)
        .single();

      if (error) throw error;
      setToken((data as unknown)?.radar_tv_dashboard_token || null);
    } catch (error) {
      console.error('Error fetching Radar TV dashboard token:', error);
    } finally {
      setLoading(false);
    }
  };

  const generateToken = async (): Promise<string | null> => {
    if (!activeCompany?.company_id) return null;

    setGenerating(true);
  try {
      // Generate token using database function
      const { data: tokenData, error: tokenError } = await (supabase
        .rpc as unknown)('generate_radar_tv_dashboard_token');

      if (tokenError) {
        console.error('Error generating token via RPC:', tokenError);
        throw tokenError;
      }

      const newToken = tokenData as string;

      // Use secure RPC to set the token
      const { error: setError } = await (supabase
        .rpc as unknown)('set_radar_tv_dashboard_token', {
          p_company_id: activeCompany.company_id,
          p_token: newToken
        });

      if (setError) {
        console.error('Error setting token via RPC:', setError);
        throw setError;
      }

      setToken(newToken);
      toast.success('Token do Radar TV gerado com sucesso!');
      return newToken;
    } catch (error) {
      console.error('Error generating Radar TV dashboard token:', error);
      toast.error('Erro ao gerar token do Radar TV');
      return null;
    } finally {
      setGenerating(false);
    }
  };

  const regenerateToken = async (): Promise<string | null> => {
    return generateToken();
  };

  const getPublicUrl = () => {
    if (!token) return null;
    return `${window.location.origin}/radar-tv/${token}`;
  };

  return {
    token,
    loading,
    generating,
    generateToken,
    regenerateToken,
    getPublicUrl,
    refetch: fetchToken
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { useCompany } from '@/contexts/CompanyContext';

export interface ScheduledPost {
  id: string;
  company_id: string;
  client_id: string | null;
  created_by: string;
  content_type: 'image' | 'video' | 'carousel' | 'reel';
  caption: string | null;
  media_urls: string[];
  thumbnail_url: string | null;
  platforms: string[];
  facebook_page_id: string | null;
  instagram_account_id: string | null;
  scheduled_at: string;
  timezone: string;
  status: 'draft' | 'scheduled' | 'publishing' | 'published' | 'failed' | 'cancelled';
  facebook_post_id: string | null;
  instagram_media_id: string | null;
  published_at: string | null;
  error_message: string | null;
  retry_count: number;
  visual_creative_id: string | null;
  collaborators: string[];
  metadata: Record<string, unknown>;
  created_at: string;
  updated_at: string;
  // Joined data
  facebook_page?: {
    id: string;
    page_name: string;
    page_id: string;
  } | null;
  instagram_account?: {
    id: string;
    username: string;
    profile_picture_url: string | null;
  } | null;
  client?: {
    id: string;
    name: string;
    company: string;
  } | null;
}

export interface CreateScheduledPostInput {
  client_id?: string | null;
  content_type: 'image' | 'video' | 'carousel' | 'reel';
  caption?: string;
  media_urls: string[];
  thumbnail_url?: string;
  platforms: string[];
  facebook_page_id?: string | null;
  instagram_account_id?: string | null;
  scheduled_at: string;
  timezone?: string;
  status?: 'draft' | 'scheduled';
  visual_creative_id?: string | null;
  collaborators?: string[];
  metadata?: Record<string, unknown>;
}

export const useScheduledPosts = () => {
  const [posts, setPosts] = useState<ScheduledPost[]>([]);
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();
  const { activeCompany } = useCompany();

  const fetchPosts = async (filters?: { status?: string; startDate?: string; endDate?: string }) => {
    if (!activeCompany?.company_id) return;

    setLoading(true);
    try {
      let query = supabase
        .from('scheduled_posts')
        .select(`
          *,
          facebook_page:facebook_pages(id, page_name, page_id),
          instagram_account:instagram_accounts(id, username, profile_picture_url),
          client:clients(id, name, company)
        `)
        .eq('company_id', activeCompany.company_id)
        .order('scheduled_at', { ascending: true });

      if (filters?.status) {
        query = query.eq('status', filters.status);
      }

      if (filters?.startDate) {
        query = query.gte('scheduled_at', filters.startDate);
      }

      if (filters?.endDate) {
        query = query.lte('scheduled_at', filters.endDate);
      }

      const { data, error } = await query;

      if (error) throw error;
      setPosts((data || []) as ScheduledPost[]);
    } catch (error: unknown) {
      console.error('Error fetching scheduled posts:', error);
      toast({
        title: 'Erro ao carregar posts',
        description: error.message,
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const createPost = async (input: CreateScheduledPostInput): Promise<ScheduledPost | null> => {
    if (!activeCompany?.company_id) return null;

    setLoading(true);
    try {
      const { data: user } = await supabase.auth.getUser();
      if (!user.user) throw new Error('User not authenticated');

      const { data, error } = await supabase
        .from('scheduled_posts')
        .insert({
          company_id: activeCompany.company_id,
          created_by: user.user.id,
          client_id: input.client_id || null,
          content_type: input.content_type,
          caption: input.caption || null,
          media_urls: input.media_urls,
          thumbnail_url: input.thumbnail_url || null,
          platforms: input.platforms,
          facebook_page_id: input.facebook_page_id || null,
          instagram_account_id: input.instagram_account_id || null,
          scheduled_at: input.scheduled_at,
          timezone: input.timezone || 'America/Sao_Paulo',
          status: input.status || 'scheduled',
          visual_creative_id: input.visual_creative_id || null,
          collaborators: input.collaborators || [],
          metadata: input.metadata || {},
        })
        .select()
        .single();

      if (error) throw error;

      toast({
        title: 'Post agendado!',
        description: `O post será publicado em ${new Date(input.scheduled_at).toLocaleString('pt-BR')}`,
      });

      await fetchPosts();
      return data as ScheduledPost;
    } catch (error: unknown) {
      console.error('Error creating scheduled post:', error);
      toast({
        title: 'Erro ao agendar post',
        description: error.message,
        variant: 'destructive',
      });
      return null;
    } finally {
      setLoading(false);
    }
  };

  const updatePost = async (id: string, updates: Partial<CreateScheduledPostInput>): Promise<boolean> => {
    setLoading(true);
    try {
      const { error } = await supabase
        .from('scheduled_posts')
        .update(updates)
        .eq('id', id);

      if (error) throw error;

      toast({
        title: 'Post atualizado!',
        description: 'As alterações foram salvas.',
      });

      await fetchPosts();
      return true;
    } catch (error: unknown) {
      console.error('Error updating scheduled post:', error);
      toast({
        title: 'Erro ao atualizar post',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    } finally {
      setLoading(false);
    }
  };

  const deletePost = async (id: string): Promise<boolean> => {
    setLoading(true);
    try {
      // First, fetch the post to check if there's a linked creative
      const { data: postData } = await supabase
        .from('scheduled_posts')
        .select('visual_creative_id, metadata')
        .eq('id', id)
        .single();

      // Delete the post
      const { error } = await supabase
        .from('scheduled_posts')
        .delete()
        .eq('id', id);

      if (error) throw error;

      // If there was a linked creative, update it back to approved status
      const creativeId = postData?.visual_creative_id || 
                         (postData?.metadata as Record<string, unknown>)?.from_presentation_creative;

      if (creativeId) {
        await supabase
          .from('presentation_creatives')
          .update({
            scheduled_post_id: null,
            current_status: 'approved',
          })
          .eq('id', creativeId);
      }

      toast({
        title: 'Post excluído',
        description: 'O agendamento foi removido.',
      });

      await fetchPosts();
      return true;
    } catch (error: unknown) {
      console.error('Error deleting scheduled post:', error);
      toast({
        title: 'Erro ao excluir post',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    } finally {
      setLoading(false);
    }
  };

  const cancelPost = async (id: string): Promise<boolean> => {
    return updatePost(id, { status: 'cancelled' } as unknown);
  };

  const reschedulePost = async (id: string, newScheduledAt: string): Promise<boolean> => {
    setLoading(true);
    try {
      const { error } = await supabase
        .from('scheduled_posts')
        .update({ 
          scheduled_at: newScheduledAt,
          status: 'scheduled',
          error_message: null,
        })
        .eq('id', id);

      if (error) throw error;

      toast({
        title: 'Post reagendado!',
        description: `Nova data: ${new Date(newScheduledAt).toLocaleString('pt-BR')}`,
      });

      await fetchPosts();
      return true;
    } catch (error: unknown) {
      console.error('Error rescheduling post:', error);
      toast({
        title: 'Erro ao reagendar',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    } finally {
      setLoading(false);
    }
  };

  const publishNow = async (id: string): Promise<boolean> => {
    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke('publish-scheduled-post', {
        body: { postId: id }
      });

      if (error) throw error;

      if (data.success) {
        toast({
          title: 'Post publicado!',
          description: 'O post foi publicado com sucesso.',
        });
      } else {
        toast({
          title: 'Erro na publicação',
          description: data.error || 'Ocorreu um erro ao publicar',
          variant: 'destructive',
        });
      }

      await fetchPosts();
      return data.success;
    } catch (error: unknown) {
      console.error('Error publishing post:', error);
      toast({
        title: 'Erro ao publicar',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (activeCompany?.company_id) {
      fetchPosts();
    }
  }, [activeCompany?.company_id]);

  return {
    posts,
    loading,
    fetchPosts,
    createPost,
    updatePost,
    deletePost,
    cancelPost,
    reschedulePost,
    publishNow,
  };
};

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useCompany } from "@/contexts/CompanyContext";
import { toast } from "sonner";

/**
 * IMPORTANT:
 * CompanyContext.activeCompany is a CompanyMember.
 * - activeCompany.id is the company_members row id
 * - activeCompany.company_id is the companies.id
 */
export function useSocialTvDashboardToken() {
  const { activeCompany } = useCompany();

  const companyId = activeCompany?.company_id ?? null;
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    if (companyId) {
      void fetchToken(companyId);
    } else {
      setToken(null);
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [companyId]);

  const fetchToken = async (id: string) => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("companies")
        .select("social_tv_dashboard_token")
        .eq("id", id)
        .maybeSingle();

      if (error) throw error;
      setToken(data?.social_tv_dashboard_token ?? null);
    } catch (error) {
      console.error("Error fetching Social TV dashboard token:", error);
      setToken(null);
    } finally {
      setLoading(false);
    }
  };

  const generateToken = async (): Promise<string | null> => {
    if (!companyId) return null;

    setGenerating(true);
    try {
      const { data: tokenData, error: tokenError } = await supabase.rpc(
        "generate_social_tv_dashboard_token"
      );
      if (tokenError) throw tokenError;

      const newToken = tokenData as string;

      const { error: setError } = await supabase.rpc(
        "set_social_tv_dashboard_token",
        {
          p_company_id: companyId,
          p_token: newToken,
        }
      );
      if (setError) throw setError;

      setToken(newToken);
      toast.success("Token do Dashboard TV Social gerado com sucesso!");
      return newToken;
    } catch (error) {
      console.error("Error generating Social TV dashboard token:", error);
      toast.error("Erro ao gerar token do Dashboard TV Social");
      return null;
    } finally {
      setGenerating(false);
    }
  };

  const regenerateToken = async (): Promise<string | null> => generateToken();

  const getPublicUrl = () => {
    if (!token) return null;
    return `${window.location.origin}/social-tv/${token}`;
  };

  return {
    token,
    loading,
    generating,
    generateToken,
    regenerateToken,
    getPublicUrl,
    refetch: () => (companyId ? fetchToken(companyId) : Promise.resolve()),
  };
}

import { useMemo } from "react";
import { useTeams, Team, TeamMember } from "@/hooks/useTeams";
import { useTasks, Task } from "@/hooks/useTasks";
import { useClients } from "@/hooks/useClients";
import { useEmployees, Employee } from "@/hooks/useEmployees";
import { differenceInDays, parseISO, isAfter, subDays } from "date-fns";

export interface MemberPerformance {
  id: string;
  name: string;
  avatar: string | null;
  role: string;
  squadName: string;
  squadColor: string;
  totalTasks: number;
  completedTasks: number;
  inProgressTasks: number;
  overdueTasks: number;
  completionRate: number;
  avgCompletionDays: number;
  tasksLast7Days: number;
  tasksLast30Days: number;
}

export interface SquadPerformance {
  id: string;
  name: string;
  color: string;
  icon: string;
  iconColor: string;
  iconBg: string;
  leaderName: string | null;
  membersCount: number;
  clientsCount: number;
  totalTasks: number;
  completedTasks: number;
  inProgressTasks: number;
  todoTasks: number;
  overdueTasks: number;
  completionRate: number;
  avgCompletionDays: number;
  tasksLast7Days: number;
  tasksLast30Days: number;
  productivityScore: number;
  members: MemberPerformance[];
}

export interface DashboardKPIs {
  totalSquads: number;
  totalMembers: number;
  totalTasks: number;
  completedTasks: number;
  inProgressTasks: number;
  overdueTasks: number;
  globalCompletionRate: number;
  avgCompletionDays: number;
  tasksLast7Days: number;
  tasksLast30Days: number;
  topSquad: string | null;
  bottomSquad: string | null;
}

export function useSquadDashboard() {
  const { teams, loading: teamsLoading } = useTeams();
  const { tasks, loading: tasksLoading } = useTasks();
  const { clients } = useClients();
  const { employees, loading: employeesLoading } = useEmployees();

  const loading = teamsLoading || tasksLoading || employeesLoading;

  const now = new Date();
  const sevenDaysAgo = subDays(now, 7);
  const thirtyDaysAgo = subDays(now, 30);

  const squadsPerformance = useMemo<SquadPerformance[]>(() => {
    if (!teams.length) return [];

    return teams.map((team) => {
      const teamTasks = tasks.filter((t) => t.team_id === team.id);
      const teamClients = clients.filter((c) => c.team_id === team.id);
      const teamMembers = team.members || [];

      const completed = teamTasks.filter((t) => t.status === "done");
      const inProgress = teamTasks.filter((t) => t.status === "progress");
      const todo = teamTasks.filter((t) => t.status === "todo");
      const overdue = teamTasks.filter(
        (t) => t.status !== "done" && t.deadline && isAfter(now, parseISO(t.deadline))
      );

      const completionDays = completed
        .filter((t) => t.created_at && (t as unknown).completed_at)
        .map((t) => differenceInDays(parseISO((t as unknown).completed_at), parseISO(t.created_at!)))
        .filter((d) => d >= 0);

      const avgDays = completionDays.length > 0
        ? Math.round(completionDays.reduce((a, b) => a + b, 0) / completionDays.length)
        : 0;

      const last7 = teamTasks.filter(
        (t) => t.status === "done" && (t as unknown).completed_at && isAfter(parseISO((t as unknown).completed_at), sevenDaysAgo)
      ).length;

      const last30 = teamTasks.filter(
        (t) => t.status === "done" && (t as unknown).completed_at && isAfter(parseISO((t as unknown).completed_at), thirtyDaysAgo)
      ).length;

      const completionRate = teamTasks.length > 0
        ? Math.round((completed.length / teamTasks.length) * 100)
        : 0;

      // Productivity score = weighted combination
      const productivityScore = Math.min(100, Math.round(
        (completionRate * 0.4) +
        (Math.min(last7 * 5, 30)) +
        (overdue.length === 0 ? 20 : Math.max(0, 20 - overdue.length * 4)) +
        (avgDays <= 3 ? 10 : avgDays <= 7 ? 5 : 0)
      ));

      // Per-member performance
      const memberPerformances: MemberPerformance[] = teamMembers.map((member) => {
        const memberEmployee = employees.find((e) => e.id === member.id);
        const userId = member.user_id || memberEmployee?.user_id;
        const memberTasks = tasks.filter(
          (t) => t.team_id === team.id && (t.assigned_user_id === userId || t.user_id === userId)
        );
        const mCompleted = memberTasks.filter((t) => t.status === "done");
        const mInProgress = memberTasks.filter((t) => t.status === "progress");
        const mOverdue = memberTasks.filter(
          (t) => t.status !== "done" && t.deadline && isAfter(now, parseISO(t.deadline))
        );

        const mCompletionDays = mCompleted
          .filter((t) => t.created_at && (t as unknown).completed_at)
          .map((t) => differenceInDays(parseISO((t as unknown).completed_at), parseISO(t.created_at!)))
          .filter((d) => d >= 0);

        const mLast7 = mCompleted.filter(
          (t) => (t as unknown).completed_at && isAfter(parseISO((t as unknown).completed_at), sevenDaysAgo)
        ).length;

        const mLast30 = mCompleted.filter(
          (t) => (t as unknown).completed_at && isAfter(parseISO((t as unknown).completed_at), thirtyDaysAgo)
        ).length;

        return {
          id: member.id,
          name: member.name,
          avatar: member.avatar,
          role: member.role,
          squadName: team.name,
          squadColor: team.color,
          totalTasks: memberTasks.length,
          completedTasks: mCompleted.length,
          inProgressTasks: mInProgress.length,
          overdueTasks: mOverdue.length,
          completionRate: memberTasks.length > 0
            ? Math.round((mCompleted.length / memberTasks.length) * 100)
            : 0,
          avgCompletionDays: mCompletionDays.length > 0
            ? Math.round(mCompletionDays.reduce((a, b) => a + b, 0) / mCompletionDays.length)
            : 0,
          tasksLast7Days: mLast7,
          tasksLast30Days: mLast30,
        };
      });

      return {
        id: team.id,
        name: team.name,
        color: team.color,
        icon: team.icon,
        iconColor: team.icon_color,
        iconBg: team.icon_bg,
        leaderName: team.leader?.name || null,
        membersCount: teamMembers.length,
        clientsCount: teamClients.length,
        totalTasks: teamTasks.length,
        completedTasks: completed.length,
        inProgressTasks: inProgress.length,
        todoTasks: todo.length,
        overdueTasks: overdue.length,
        completionRate,
        avgCompletionDays: avgDays,
        tasksLast7Days: last7,
        tasksLast30Days: last30,
        productivityScore,
        members: memberPerformances,
      };
    }).sort((a, b) => b.productivityScore - a.productivityScore);
  }, [teams, tasks, clients, employees, now]);

  const kpis = useMemo<DashboardKPIs>(() => {
    const totalTasks = tasks.length;
    const completedTasks = tasks.filter((t) => t.status === "done").length;
    const inProgressTasks = tasks.filter((t) => t.status === "progress").length;
    const overdueTasks = tasks.filter(
      (t) => t.status !== "done" && t.deadline && isAfter(now, parseISO(t.deadline))
    ).length;

    const completionDays = tasks
      .filter((t) => t.status === "done" && t.created_at && (t as unknown).completed_at)
      .map((t) => differenceInDays(parseISO((t as unknown).completed_at), parseISO(t.created_at!)))
      .filter((d) => d >= 0);

    const last7 = tasks.filter(
      (t) => t.status === "done" && (t as unknown).completed_at && isAfter(parseISO((t as unknown).completed_at), sevenDaysAgo)
    ).length;

    const last30 = tasks.filter(
      (t) => t.status === "done" && (t as unknown).completed_at && isAfter(parseISO((t as unknown).completed_at), thirtyDaysAgo)
    ).length;

    const sorted = [...squadsPerformance].sort((a, b) => b.productivityScore - a.productivityScore);

    return {
      totalSquads: teams.length,
      totalMembers: employees.length,
      totalTasks,
      completedTasks,
      inProgressTasks,
      overdueTasks,
      globalCompletionRate: totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0,
      avgCompletionDays: completionDays.length > 0
        ? Math.round(completionDays.reduce((a, b) => a + b, 0) / completionDays.length)
        : 0,
      tasksLast7Days: last7,
      tasksLast30Days: last30,
      topSquad: sorted[0]?.name || null,
      bottomSquad: sorted.length > 1 ? sorted[sorted.length - 1]?.name || null : null,
    };
  }, [tasks, teams, employees, squadsPerformance, now]);

  // Ranking of all members across squads
  const membersRanking = useMemo<MemberPerformance[]>(() => {
    return squadsPerformance
      .flatMap((s) => s.members)
      .sort((a, b) => b.completedTasks - a.completedTasks);
  }, [squadsPerformance]);

  return {
    loading,
    kpis,
    squadsPerformance,
    membersRanking,
  };
}

import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";
import { useCompany } from "@/contexts/CompanyContext";

export interface TeamMember {
  id: string;
  name: string;
  email: string;
  role: string;
  avatar: string | null;
  user_id: string;
  work_schedule_id?: string | null;
}

export interface Team {
  id: string;
  name: string;
  description: string;
  icon: string;
  icon_color: string;
  icon_bg: string;
  color: string;
  progress: number;
  active_tasks: number;
  leader_id?: string | null;
  whatsapp_responsible_id?: string | null;
  authorizer_id?: string | null;
  members?: TeamMember[];
  leader?: TeamMember | null;
  whatsapp_responsible?: TeamMember | null;
  authorizer?: TeamMember | null;
}

export function useTeams() {
  const [teams, setTeams] = useState<Team[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();
  const { activeCompany } = useCompany();

  const fetchTeams = async () => {
    if (!user || !activeCompany) return;

    try {
      setLoading(true);

      // Fetch teams
      const { data: teamsData, error: teamsError } = await supabase
        .from("teams")
        .select("*")
        .eq("company_id", activeCompany.company_id)
        .order("created_at", { ascending: false });

      if (teamsError) throw teamsError;
      if (!teamsData || teamsData.length === 0) {
        setTeams([]);
        return;
      }

      // Fetch all employees for this company to get members
      const { data: employees, error: employeesError } = await supabase
        .from("employees")
        .select("id, user_id, name, email, role, avatar, team_id, work_schedule_id")
        .eq("company_id", activeCompany.company_id)
        .eq("status", "active");

      if (employeesError) throw employeesError;

      // Map teams with their members
      const teamsWithMembers = teamsData.map((team) => {
        const teamMembers = (employees || [])
          .filter((emp) => emp.team_id === team.id)
          .map((emp) => ({
            id: emp.id,
            user_id: emp.user_id,
            name: emp.name,
            email: emp.email,
            role: emp.role,
            avatar: emp.avatar,
            work_schedule_id: (emp as unknown).work_schedule_id || null,
          }));

        const leader = teamMembers.find((m) => m.id === team.leader_id) || null;
        const whatsappResponsible = teamMembers.find((m) => m.id === team.whatsapp_responsible_id) || null;
        const authorizer = teamMembers.find((m) => m.id === team.authorizer_id) || null;

        return {
          ...team,
          members: teamMembers,
          leader,
          whatsapp_responsible: whatsappResponsible,
          authorizer,
        };
      });

      setTeams(teamsWithMembers);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao buscar equipes");
    } finally {
      setLoading(false);
    }
  };

  const createTeam = async (teamData: Omit<Team, "id" | "progress" | "active_tasks" | "members">) => {
    if (!user || !activeCompany) {
      setError("Usuário não autenticado ou empresa não selecionada");
      return null;
    }

    try {
      setError(null);
      const { data, error } = await supabase
        .from("teams")
        .insert([{
          ...teamData,
          user_id: user.id,
          company_id: activeCompany.company_id,
        }])
        .select()
        .single();

      if (error) throw error;
      await fetchTeams(); // Refresh the list
      return data;
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao criar equipe");
      return null;
    }
  };

  const updateTeam = async (id: string, updates: Partial<Team>) => {
    try {
      const { error } = await supabase
        .from("teams")
        .update(updates)
        .eq("id", id);

      if (error) throw error;
      await fetchTeams(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao atualizar equipe");
    }
  };

  const deleteTeam = async (id: string) => {
    try {
      const { error } = await supabase
        .from("teams")
        .delete()
        .eq("id", id);

      if (error) throw error;
      await fetchTeams(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao deletar equipe");
    }
  };

  const addTeamMember = async (teamId: string, memberData: Omit<TeamMember, "id">) => {
    try {
      const { error } = await supabase
        .from("team_members")
        .insert([{
          ...memberData,
          team_id: teamId,
        }]);

      if (error) throw error;
      await fetchTeams(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao adicionar membro");
    }
  };

  const removeTeamMember = async (memberId: string) => {
    try {
      const { error } = await supabase
        .from("team_members")
        .delete()
        .eq("id", memberId);

      if (error) throw error;
      await fetchTeams(); // Refresh the list
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao remover membro");
    }
  };

  useEffect(() => {
    fetchTeams();
  }, [user, activeCompany]);

  return {
    teams,
    loading,
    error,
    fetchTeams,
    createTeam,
    updateTeam,
    deleteTeam,
    addTeamMember,
    removeTeamMember,
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useCompany } from '@/contexts/CompanyContext';
import { toast } from 'sonner';

export function useTvDashboardToken() {
  const { activeCompany } = useCompany();
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    if (activeCompany?.id) {
      fetchToken();
    }
  }, [activeCompany?.id]);

  const fetchToken = async () => {
    if (!activeCompany?.id) return;

    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('companies')
        .select('tv_dashboard_token')
        .eq('id', activeCompany.id)
        .single();

      if (error) throw error;
      setToken(data?.tv_dashboard_token || null);
    } catch (error) {
      console.error('Error fetching TV dashboard token:', error);
    } finally {
      setLoading(false);
    }
  };

  const generateToken = async (): Promise<string | null> => {
    if (!activeCompany?.id) return null;

    setGenerating(true);
    try {
      // Generate token using database function
      const { data: tokenData, error: tokenError } = await supabase
        .rpc('generate_tv_dashboard_token');

      if (tokenError) {
        console.error('Error generating token via RPC:', tokenError);
        throw tokenError;
      }

      const newToken = tokenData as string;

      // Use secure RPC to set the token (avoids RLS issues)
      const { error: setError } = await supabase
        .rpc('set_tv_dashboard_token', {
          p_company_id: activeCompany.id,
          p_token: newToken
        });

      if (setError) {
        console.error('Error setting token via RPC:', setError);
        throw setError;
      }

      setToken(newToken);
      toast.success('Token do Dashboard TV gerado com sucesso!');
      return newToken;
    } catch (error) {
      console.error('Error generating TV dashboard token:', error);
      toast.error('Erro ao gerar token do Dashboard TV');
      return null;
    } finally {
      setGenerating(false);
    }
  };

  const regenerateToken = async (): Promise<string | null> => {
    return generateToken();
  };

  const getPublicUrl = () => {
    if (!token) return null;
    return `${window.location.origin}/tv/${token}`;
  };

  return {
    token,
    loading,
    generating,
    generateToken,
    regenerateToken,
    getPublicUrl,
    refetch: fetchToken
  };
}

import { useState, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";

interface UserProfile {
  id: string;
  user_id: string;
  full_name: string | null;
  company: string | null;
  phone: string | null;
  avatar_url: string | null;
  created_at: string;
  updated_at: string;
}

export const useUserProfile = () => {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user } = useAuth();

  const fetchProfile = async () => {
    if (!user?.id) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('user_id', user.id)
        .single();

      if (error && error.code !== 'PGRST116') {
        throw error;
      }

      setProfile(data);
    } catch (error: unknown) {
      console.error('Error fetching user profile:', error);
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  const updateProfile = async (updates: Partial<UserProfile>) => {
    if (!user?.id) return;

    try {
      const { data, error } = await supabase
        .from('profiles')
        .upsert({
          user_id: user.id,
          ...updates,
          updated_at: new Date().toISOString(),
        }, {
          onConflict: 'user_id'
        })
        .select()
        .single();

      if (error) throw error;

      setProfile(data);
      return data;
    } catch (error: unknown) {
      console.error('Error updating profile:', error);
      throw error;
    }
  };

  useEffect(() => {
    fetchProfile();
  }, [user?.id]);

  return {
    profile,
    loading,
    error,
    fetchProfile,
    updateProfile,
  };
};

