const nodeTypes: NodeTypes = {
  squadAgent: SquadAgentNode,
};

// Custom labeled edge
function LabeledEdge({ id, sourceX, sourceY, targetX, targetY, sourcePosition, targetPosition, data, markerEnd }: EdgeProps) {
  const [edgePath, labelX, labelY] = getBezierPath({ sourceX, sourceY, sourcePosition, targetX, targetY, targetPosition });

  return (
    <>
      <BaseEdge path={edgePath} markerEnd={markerEnd} id={id} />
      {(data as unknown)?.label && (
        <EdgeLabelRenderer>
          <div
            style={{ position: "absolute", transform: `translate(-50%, -50%) translate(${labelX}px,${labelY}px)`, pointerEvents: "all" }}
            className="bg-card border rounded px-2 py-0.5 text-xs text-muted-foreground shadow-sm"
          >
            {(data as unknown).label}
          </div>
        </EdgeLabelRenderer>
      )}
    </>
  );
}

const edgeTypes = { labeled: LabeledEdge };

function SquadEditorContent() {
  const navigate = useNavigate();
  const { squadId } = useParams();
  const { toast } = useToast();
  const { fetchSquadById, fetchSquadMembers, fetchSquadFlows, saveSquadLayout, updateSquad } = useAgentSquads();
  const { clients = [] } = useClients();
  const { screenToFlowPosition } = useReactFlow();

  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const [editingNode, setEditingNode] = useState<Node | null>(null);
  const [squadName, setSquadName] = useState("Squad");
  const [squadClientId, setSquadClientId] = useState<string | undefined>();
  const [squadDescription, setSquadDescription] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Edit squad dialog state
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [editForm, setEditForm] = useState({ name: "", description: "", client_id: "" });
  const [clientPopoverOpen, setClientPopoverOpen] = useState(false);

  const nodesRef = useRef<Node[]>([]);

  const sortedClients = Array.isArray(clients)
    ? [...clients].sort((a, b) => a.name.localeCompare(b.name))
    : [];

  useEffect(() => {
    nodesRef.current = nodes;
  }, [nodes]);

  const handleOpenEditPanel = useCallback((nodeId: string) => {
    const node = nodesRef.current.find((n) => n.id === nodeId);
    if (node) setEditingNode(node);
  }, []);

  // Load squad data
  useEffect(() => {
    if (!squadId) return;
    const load = async () => {
      setIsLoading(true);
      try {
        const squad = await fetchSquadById(squadId);
        setSquadName(squad.name);
        setSquadClientId(squad.client_id);
        setSquadDescription(squad.description || "");

        const members = await fetchSquadMembers(squadId);
        const flows = await fetchSquadFlows(squadId);

        const loadedNodes: Node[] = members.map((m) => ({
          id: m.id,
          type: "squadAgent",
          position: { x: m.position_x, y: m.position_y },
          data: {
            label: m.agent?.agent_name || "Agente",
            description: m.agent?.description || "",
            role: m.role,
            agent_id: m.agent_id,
            squad_instructions: m.squad_instructions || "",
            onEdit: handleOpenEditPanel,
          } as SquadAgentNodeData,
        }));

        const loadedEdges: Edge[] = flows.map((f) => ({
          id: f.id,
          source: f.source_member_id,
          target: f.target_member_id,
          type: "labeled",
          data: { label: f.label || "" },
          animated: true,
          markerEnd: { type: "arrowclosed" as unknown },
        }));

        setNodes(loadedNodes);
        setEdges(loadedEdges);
      } catch (err) {
        toast({ title: "Erro ao carregar squad", variant: "destructive" });
      } finally {
        setIsLoading(false);
      }
    };
    load();
  }, [squadId, handleOpenEditPanel]);

  const onConnect = useCallback(
    (params: Connection) => {
      const newEdge = {
        ...params,
        type: "labeled",
        data: { label: "" },
        animated: true,
        markerEnd: { type: "arrowclosed" as unknown },
      };
      setEdges((eds) => addEdge(newEdge, eds));
    },
    [setEdges]
  );

  const onDragOver = useCallback((event: React.DragEvent) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
  }, []);

  const onDrop = useCallback(
    (event: React.DragEvent) => {
      event.preventDefault();
      const agentData = event.dataTransfer.getData("application/squad-agent");
      if (!agentData) return;

      const agent = JSON.parse(agentData);
      const position = screenToFlowPosition({ x: event.clientX, y: event.clientY });

      const newNode: Node = {
        id: `agent-${agent.id}-${Date.now()}`,
        type: "squadAgent",
        position,
        data: {
          label: agent.agent_name,
          description: agent.description || "",
          role: "executor",
          agent_id: agent.id,
          squad_instructions: "",
          onEdit: handleOpenEditPanel,
        } as SquadAgentNodeData,
      };

      setNodes((nds) => nds.concat(newNode));
    },
    [handleOpenEditPanel, setNodes, screenToFlowPosition]
  );

  const onDragStart = (event: React.DragEvent, agent: unknown) => {
    event.dataTransfer.setData("application/squad-agent", JSON.stringify(agent));
    event.dataTransfer.effectAllowed = "move";
  };

  const handleSaveNode = (id: string, updates: Partial<SquadAgentNodeData>) => {
    setNodes((nds) =>
      nds.map((node) =>
        node.id === id ? { ...node, data: { ...(node.data as SquadAgentNodeData), ...updates } } : node
      )
    );
  };

  const handleDeleteNode = (id: string) => {
    setNodes((nds) => nds.filter((n) => n.id !== id));
    setEdges((eds) => eds.filter((e) => e.source !== id && e.target !== id));
  };

  const handleSave = async () => {
    if (!squadId) return;
    setIsSaving(true);
    try {
      const members = nodes.map((n) => {
        const d = n.data as SquadAgentNodeData;
        return {
          id: n.id,
          agent_id: d.agent_id,
          role: d.role,
          squad_instructions: d.squad_instructions,
          position_x: n.position.x,
          position_y: n.position.y,
        };
      });

      const flows = edges.map((e) => ({
        source_member_id: e.source,
        target_member_id: e.target,
        label: (e.data as unknown)?.label || "",
      }));

      await saveSquadLayout(squadId, members, flows);
    } finally {
      setIsSaving(false);
    }
  };

  // Edit squad dialog handlers
  const handleOpenEditDialog = () => {
    setEditForm({
      name: squadName,
      description: squadDescription,
      client_id: squadClientId || "",
    });
    setEditDialogOpen(true);
  };

  const handleSaveSquadEdit = async () => {
    if (!squadId || !editForm.name || !editForm.client_id) return;
    await updateSquad(squadId, {
      name: editForm.name,
      description: editForm.description,
      client_id: editForm.client_id,
    });
    setSquadName(editForm.name);
    setSquadDescription(editForm.description);
    // If client changed, update the library filter
    if (editForm.client_id !== squadClientId) {
      setSquadClientId(editForm.client_id);
    }
    setEditDialogOpen(false);
  };

  const selectedEditClientName = sortedClients.find(c => c.id === editForm.client_id)?.name;

  // Find leader agent for test chat
  const leaderNode = nodes.find((n) => (n.data as SquadAgentNodeData).role === "leader");
  const leaderAgentId = leaderNode ? (leaderNode.data as SquadAgentNodeData).agent_id : undefined;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col bg-background">
      {/* Header */}
      <div className="border-b bg-card px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={() => navigate("/ia/squads")}>
            <ArrowLeft className="h-5 w-5" />
          </Button>
          <div>
            <h1 className="text-lg font-semibold">{squadName}</h1>
            <p className="text-sm text-muted-foreground">Editor Visual da Squad</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={handleOpenEditDialog}>
            <Settings className="h-4 w-4 mr-2" />
            Editar Squad
          </Button>
          <Button onClick={handleSave} disabled={isSaving}>
            {isSaving ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : <Save className="h-4 w-4 mr-2" />}
            Salvar
          </Button>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex overflow-hidden">
        <SquadAgentLibrary clientId={squadClientId} onDragStart={onDragStart} />

        <div className="flex-1 bg-muted/20 relative">
          <ReactFlow
            nodes={nodes}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={onConnect}
            onDrop={onDrop}
            onDragOver={onDragOver}
            deleteKeyCode={["Backspace", "Delete"]}
            onNodesDelete={(deletedNodes) => {
              const deletedIds = new Set(deletedNodes.map((n) => n.id));
              setEdges((eds) => eds.filter((e) => !deletedIds.has(e.source) && !deletedIds.has(e.target)));
            }}
            nodeTypes={nodeTypes}
            edgeTypes={edgeTypes}
            defaultEdgeOptions={{ type: "labeled", animated: true, markerEnd: { type: "arrowclosed" as unknown } }}
            fitView
            minZoom={0.2}
            maxZoom={2}
          >
            <Background />
            <Controls />
            <MiniMap pannable zoomable />
            <Panel position="top-center" className="bg-card/80 backdrop-blur-sm px-3 py-1 rounded-md text-sm text-muted-foreground">
              Arraste agentes da biblioteca e conecte-os para definir o fluxo
            </Panel>
          </ReactFlow>
        </div>

        <SquadTestChat
          squadId={squadId || ""}
          squadName={squadName}
          agentId={leaderAgentId}
        />
      </div>

      <SquadNodeEditPanel
        node={editingNode}
        isOpen={!!editingNode}
        onClose={() => setEditingNode(null)}
        onSave={handleSaveNode}
        onDelete={handleDeleteNode}
        onRefreshNode={(nodeId, updates) => {
          setNodes((nds) =>
            nds.map((n) =>
              n.id === nodeId ? { ...n, data: { ...(n.data as SquadAgentNodeData), ...updates } } : n
            )
          );
        }}
      />

      {/* Edit Squad Dialog */}
      <Dialog open={editDialogOpen} onOpenChange={setEditDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Editar Squad</DialogTitle>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Nome da Squad</Label>
              <Input
                value={editForm.name}
                onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
                placeholder="Nome da squad"
              />
            </div>
            <div>
              <Label>Descrição</Label>
              <Textarea
                value={editForm.description}
                onChange={(e) => setEditForm({ ...editForm, description: e.target.value })}
                placeholder="Descreva o objetivo da squad..."
              />
            </div>
            <div>
              <Label>Cliente</Label>
              <Popover open={clientPopoverOpen} onOpenChange={setClientPopoverOpen}>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    role="combobox"
                    aria-expanded={clientPopoverOpen}
                    className="w-full justify-between font-normal"
                  >
                    {selectedEditClientName || "Selecione um cliente"}
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-[--radix-popover-trigger-width] p-0">
                  <Command>
                    <CommandInput placeholder="Buscar cliente..." />
                    <CommandList>
                      <CommandEmpty>Nenhum cliente encontrado.</CommandEmpty>
                      <CommandGroup>
                        {sortedClients.map((c) => (
                          <CommandItem
                            key={c.id}
                            value={c.name}
                            onSelect={() => {
                              setEditForm({ ...editForm, client_id: c.id });
                              setClientPopoverOpen(false);
                            }}
                          >
                            <Check
                              className={cn(
                                "mr-2 h-4 w-4",
                                editForm.client_id === c.id ? "opacity-100" : "opacity-0"
                              )}
                            />
                            {c.name}
                          </CommandItem>
                        ))}
                      </CommandGroup>
                    </CommandList>
                  </Command>
                </PopoverContent>
              </Popover>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setEditDialogOpen(false)}>
              Cancelar
            </Button>
            <Button onClick={handleSaveSquadEdit} disabled={!editForm.name || !editForm.client_id}>
              Salvar Alterações
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

export default function AgentSquadEditor() {
  return (
    <ReactFlowProvider>
      <SquadEditorContent />
    </ReactFlowProvider>
  );
}

import { DashboardLayout } from '@/components/dashboard/DashboardLayout';
import { ChannelSidebar } from '@/components/comm-hub/ChannelSidebar';
import { ChatFlow } from '@/components/comm-hub/ChatFlow';
import { MyDayPanel } from '@/components/comm-hub/MyDayPanel';
import { useInternalChat } from '@/hooks/useInternalChat';
import { useChannelUnread } from '@/hooks/useChannelUnread';
import { TaskDialog } from '@/components/tasks/TaskDialog';
import { useEffect, useState } from 'react';
import { toast } from 'sonner';
import { supabase } from '@/integrations/supabase/client';
import { ResizablePanelGroup, ResizablePanel, ResizableHandle } from '@/components/ui/resizable';

export default function CommunicationDashboard() {
  const {
    channels,
    channelsLoading,
    activeChannel,
    activeChannelId,
    setActiveChannelId,
    messages,
    messagesLoading,
    sendMessage,
    sendingMessage,
    getOrCreateDMChannel,
  } = useInternalChat();

  const { unreadCounts, mentionCounts, markAsRead } = useChannelUnread();
  const [focusMode, setFocusMode] = useState(false);
  const [taskDialogOpen, setTaskDialogOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState<unknown>(null);

  // Handle DM navigation from notification click
  useEffect(() => {
    const storedChannel = sessionStorage.getItem('dm-navigate-channel');
    if (storedChannel && channels.length > 0) {
      sessionStorage.removeItem('dm-navigate-channel');
      setActiveChannelId(storedChannel);
    }
  }, [channels]);

  // Listen for dm-switch-channel event (when already on dashboard)
  useEffect(() => {
    const handler = (e: Event) => {
      const channelId = (e as CustomEvent).detail;
      if (channelId) setActiveChannelId(channelId);
    };
    window.addEventListener('dm-switch-channel', handler);
    return () => window.removeEventListener('dm-switch-channel', handler);
  }, [setActiveChannelId]);

  // Mark channel as read when switching
  useEffect(() => {
    if (activeChannelId) {
      markAsRead(activeChannelId);
    }
  }, [activeChannelId]);

  const handleOpenDM = async (userId: string, userName: string) => {
    const channelId = await getOrCreateDMChannel(userId, userName);
    if (channelId) {
      setActiveChannelId(channelId);
    } else {
      toast.error('Não foi possível abrir a conversa');
    }
  };

  const handleOpenTask = async (taskId: string) => {
    const { data } = await supabase
      .from('tasks')
      .select('*')
      .eq('id', taskId)
      .maybeSingle();
    if (data) {
      setSelectedTask(data);
      setTaskDialogOpen(true);
    }
  };

  return (
    <DashboardLayout>
      <div className="h-[calc(100vh-4rem)] -m-8 rounded-none overflow-hidden relative">
        <ResizablePanelGroup direction="horizontal" className="h-full">
          <ResizablePanel defaultSize={20} minSize={15} maxSize={35}>
            <ChannelSidebar
              channels={channels}
              activeChannelId={activeChannelId}
              onSelectChannel={setActiveChannelId}
              loading={channelsLoading}
              unreadCounts={unreadCounts}
              mentionCounts={mentionCounts}
            />
          </ResizablePanel>
          <ResizableHandle withHandle />
          <ResizablePanel defaultSize={60} minSize={30}>
            <ChatFlow
              channel={activeChannel}
              messages={messages}
              loading={messagesLoading}
              onSendMessage={(content, threadParentId) => sendMessage(content, threadParentId)}
              sendingMessage={sendingMessage}
              focusMode={focusMode}
              onToggleFocusMode={() => setFocusMode(prev => !prev)}
            />
          </ResizablePanel>
          <ResizableHandle withHandle />
          <ResizablePanel defaultSize={20} minSize={15} maxSize={35}>
            <MyDayPanel onOpenDM={handleOpenDM} onOpenTask={handleOpenTask} />
          </ResizablePanel>
        </ResizablePanelGroup>
      </div>

      {taskDialogOpen && (
        <TaskDialog
          open={taskDialogOpen}
          onOpenChange={(open) => {
            setTaskDialogOpen(open);
            if (!open) setSelectedTask(null);
          }}
          task={selectedTask}
          onSave={() => {
            setTaskDialogOpen(false);
            setSelectedTask(null);
          }}
        />
      )}
    </DashboardLayout>
  );
}

import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { DashboardLayout } from "@/components/dashboard/DashboardLayout";
import { CampaignsList } from "@/components/campaign-generator/CampaignsList";
import { CampaignGeneratorSimplified } from "@/components/campaign-generator/CampaignGeneratorSimplified";
import { Button } from "@/components/ui/button";
import { ArrowLeft, Home } from "lucide-react";
import { useGeneratedCampaigns } from "@/hooks/useGeneratedCampaigns";
import type { Client } from "@/hooks/useClients";

export type FunnelStage = "topo" | "meio" | "fundo" | "retencao";
export type CampaignType = "awareness" | "traffic" | "leads" | "conversions" | "remarketing" | "retention";

export interface CampaignData {
  client: Client | null;
  funnelStage: FunnelStage | null;
  campaignType: CampaignType | null;
  configuration: unknown;
  creatives: unknown[];
}

const GeradorCampanhas = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const { getCampaign } = useGeneratedCampaigns();

  const [mode, setMode] = useState<'list' | 'generator' | 'edit'>('list');
  const [existingCampaign, setExistingCampaign] = useState<unknown>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (id) {
      loadCampaignForEdit(id);
    } else {
      setMode('list');
      setExistingCampaign(null);
    }
  }, [id]);

  const loadCampaignForEdit = async (campaignId: string) => {
    try {
      setLoading(true);
      const campaign = await getCampaign(campaignId);
      if (campaign) {
        setExistingCampaign(campaign);
        setMode('edit');
      } else {
        navigate('/geradores/campanhas');
      }
    } catch (error) {
      console.error('Error loading campaign:', error);
      navigate('/geradores/campanhas');
    } finally {
      setLoading(false);
    }
  };

  const handleNewCampaign = () => {
    setMode('generator');
    setExistingCampaign(null);
    navigate('/geradores/campanhas');
  };

  const handleViewCampaign = (campaignId: string) => {
    navigate(`/geradores/campanhas/${campaignId}`);
  };

  const handleBackToList = () => {
    setMode('list');
    setExistingCampaign(null);
    navigate('/geradores/campanhas');
  };

  if (loading) {
    return (
      <DashboardLayout>
        <div className="flex items-center justify-center min-h-[400px]">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
        </div>
      </DashboardLayout>
    );
  }

  if (mode === 'list') {
    return (
      <DashboardLayout>
        <CampaignsList
          onNewCampaign={handleNewCampaign}
          onViewCampaign={handleViewCampaign}
        />
      </DashboardLayout>
    );
  }

  // Both 'generator' (new) and 'edit' (existing) modes use CampaignGeneratorSimplified
  return (
    <DashboardLayout>
      <div className="space-y-6">
        <div className="flex items-center gap-2">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate('/geradores')}
            className="flex items-center gap-2"
