import { useEffect, useState, useRef } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useGoogleAdsIntegration } from "@/hooks/useGoogleAdsIntegration";
import { useCompany } from "@/contexts/CompanyContext";
import { Loader2, CheckCircle2, XCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";

export default function GoogleAdsCallback() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { activeCompany } = useCompany();
  const { handleCallback, refreshAdAccounts } = useGoogleAdsIntegration();
  const [status, setStatus] = useState<'loading' | 'success' | 'error'>('loading');
  const [error, setError] = useState<string | null>(null);

  // Ref para garantir que o processamento só aconteça uma vez
  const hasProcessedRef = useRef(false);

  useEffect(() => {
    // Só processar se activeCompany estiver disponível
    if (!activeCompany) {
      return;
    }

    // Marcar IMEDIATAMENTE para prevenir race conditions
    if (hasProcessedRef.current) {
      return;
    }
    hasProcessedRef.current = true;

    const processCallback = async () => {
      const code = searchParams.get('code');
      const errorParam = searchParams.get('error');


      if (errorParam) {
        setStatus('error');
        setError('Autorização negada pelo usuário');
        return;
      }

      if (!code) {
        setStatus('error');
        setError('Código de autorização não encontrado');
        return;
      }

      try {
        await handleCallback(code, activeCompany.company_id);
        await refreshAdAccounts();
        setStatus('success');
        setTimeout(() => {
          navigate('/configuracoes/integracao-google');
        }, 2000);
      } catch (error: unknown) {
        console.error('Callback processing error:', error);
        setStatus('error');
        setError(error.message || 'Erro ao processar callback');
        hasProcessedRef.current = false; // Permitir retry em caso de erro
      }
    };

    processCallback();
  }, [activeCompany, searchParams, handleCallback, navigate]); // Executar quando activeCompany carregar

  return (
    <div className="flex min-h-screen items-center justify-center bg-background p-4">
      <Card className="w-full max-w-md">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            {status === 'loading' && <Loader2 className="h-6 w-6 animate-spin" />}
            {status === 'success' && <CheckCircle2 className="h-6 w-6 text-green-500" />}
            {status === 'error' && <XCircle className="h-6 w-6 text-destructive" />}
            {status === 'loading' && 'Conectando ao Google Ads...'}
            {status === 'success' && 'Conectado com sucesso!'}
            {status === 'error' && 'Erro na conexão'}
          </CardTitle>
          <CardDescription>
            {status === 'loading' && 'Processando autorização...'}
            {status === 'success' && 'Redirecionando para as configurações...'}
            {status === 'error' && error}
          </CardDescription>
        </CardHeader>
        {status === 'error' && (
          <CardContent>
            <Button onClick={() => navigate('/configuracoes/integracao-google')} className="w-full">
              Voltar para Configurações
            </Button>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  ReactFlow,
  MiniMap,
  Controls,
  Background,
  useNodesState,
  useEdgesState,
  addEdge,
  type Connection,
  type Node,
  type Edge,
  BackgroundVariant,
  useReactFlow,
  ReactFlowProvider,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { ArrowLeft, Save, Check, Loader2, LayoutGrid } from 'lucide-react';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useMindMaps } from '@/hooks/useMindMaps';
import MindMapNodeComponent from '@/components/mind-map/MindMapNode';
import { MindMapToolbar } from '@/components/mind-map/MindMapToolbar';
import { useDebounce } from '@/hooks/useDebounce';

const nodeTypes = { mindMapNode: MindMapNodeComponent };

function MindMapEditorInner() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { mindMaps, updateMindMap } = useMindMaps();
  const { fitView } = useReactFlow();

  const mindMap = mindMaps.find(m => m.id === id);
  const [title, setTitle] = useState('');
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'unsaved'>('saved');
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const initialized = useRef(false);

  // Helper: compute node metadata (childCount, hasLeft/RightChildren, collapsed visibility)
  const updateNodeMetadata = useCallback((currentNodes: Node[], currentEdges: Edge[]) => {
    // Build parent->children map with direction info
    const childrenMap: Record<string, string[]> = {};
    const edgeDirectionMap: Record<string, 'left' | 'right'> = {}; // edge.id -> direction

    currentEdges.forEach(e => {
      if (!childrenMap[e.source]) childrenMap[e.source] = [];
      childrenMap[e.source].push(e.target);
      edgeDirectionMap[e.id] = (e.data as unknown)?.direction || 'right';
    });

    // For each edge, determine direction from edge data
    const nodeChildDirections: Record<string, Set<string>> = {};
    currentEdges.forEach(e => {
      if (!nodeChildDirections[e.source]) nodeChildDirections[e.source] = new Set();
      const dir = (e.data as unknown)?.direction || 'right';
      nodeChildDirections[e.source].add(dir);
    });

    return currentNodes.map(n => {
      const children = childrenMap[n.id] || [];
      const directions = nodeChildDirections[n.id] || new Set();
      return {
        ...n,
        data: {
          ...n.data,
          childCount: children.length,
          hasLeftChildren: directions.has('left'),
          hasRightChildren: directions.has('right') || (children.length > 0 && !directions.has('left')),
        },
      };
    });
  }, []);

  // Load data once
  useEffect(() => {
    if (mindMap && !initialized.current) {
      setTitle(mindMap.title);
      const loadedEdges = mindMap.edges || [];
      const loadedNodes = (mindMap.nodes || []).map((n: Node) => ({
        ...n,
        data: {
          ...n.data,
          onAddChild: handleAddChildRef.current,
          onLabelChange: handleLabelChangeRef.current,
          onToggleCollapse: handleToggleCollapseRef.current,
        },
      }));
      setEdges(loadedEdges);
      setNodes(updateNodeMetadata(loadedNodes, loadedEdges));
      initialized.current = true;
      setTimeout(() => fitView({ padding: 0.3 }), 100);
    }
  }, [mindMap]);

  // Refs for stable callbacks passed to node data
  const handleAddChildRef = useRef<(parentId: string, direction?: 'left' | 'right') => void>(() => {});
  const handleLabelChangeRef = useRef<(nodeId: string, label: string) => void>(() => {});
  const handleToggleCollapseRef = useRef<(nodeId: string) => void>(() => {});

  // Sync callbacks into nodes
  useEffect(() => {
    setNodes(nds => nds.map(n => ({
      ...n,
      data: {
        ...n.data,
        onAddChild: handleAddChildRef.current,
        onLabelChange: handleLabelChangeRef.current,
        onToggleCollapse: handleToggleCollapseRef.current,
      },
    })));
  }, []);

  // Auto-save with debounce
  const debouncedNodes = useDebounce(nodes, 2000);
  const debouncedEdges = useDebounce(edges, 2000);
  const debouncedTitle = useDebounce(title, 2000);

  useEffect(() => {
    if (!id || !initialized.current) return;
    setSaveStatus('saving');
    updateMindMap.mutate(
      { id, title: debouncedTitle, nodes: debouncedNodes, edges: debouncedEdges },
      { onSuccess: () => setSaveStatus('saved'), onError: () => setSaveStatus('unsaved') }
    );
  }, [debouncedNodes, debouncedEdges, debouncedTitle]);

  // Toggle collapse
  const handleToggleCollapse = useCallback((nodeId: string) => {
    setNodes(nds => nds.map(n =>
      n.id === nodeId
        ? { ...n, data: { ...n.data, collapsed: !(n.data as unknown).collapsed } }
        : n
    ));
    setSaveStatus('unsaved');
    setTimeout(() => autoLayoutRef.current(), 50);
  }, []);
  handleToggleCollapseRef.current = handleToggleCollapse;

  // Add child with direction support
  const handleAddChild = useCallback((parentId: string, direction: 'left' | 'right' = 'right') => {
    const newId = `node-${Date.now()}`;
    setEdges(currentEdges => {
      setNodes(nds => {
        const parent = nds.find(n => n.id === parentId);
        if (!parent) return nds;
        const parentLevel = (parent.data as unknown).level || 0;

        const xOffset = direction === 'left' ? -250 : 250;

        const newNode: Node = {
          id: newId,
          type: 'mindMapNode',
          position: {
            x: parent.position.x + xOffset,
            y: parent.position.y,
          },
          data: {
            label: 'Nova ideia',
            level: parentLevel + 1,
            direction,
            onAddChild: handleAddChildRef.current,
            onLabelChange: handleLabelChangeRef.current,
            onToggleCollapse: handleToggleCollapseRef.current,
          },
        };
        return [...nds, newNode];
      });

      return [
        ...currentEdges,
        {
          id: `edge-${parentId}-${newId}`,
          source: parentId,
          target: newId,
          type: 'default',
          sourceHandle: direction === 'left' ? 'left-source' : undefined,
          targetHandle: direction === 'left' ? 'right-target' : undefined,
          style: { stroke: 'hsl(var(--muted-foreground))', strokeWidth: 2 },
          data: { direction },
        },
      ];
    });
    setSaveStatus('unsaved');
    setTimeout(() => autoLayoutRef.current(), 50);
  }, []);
  handleAddChildRef.current = handleAddChild;

  const handleLabelChange = useCallback((nodeId: string, label: string) => {
    setNodes(nds => nds.map(n => n.id === nodeId ? { ...n, data: { ...n.data, label } } : n));
    setSaveStatus('unsaved');
  }, []);
  handleLabelChangeRef.current = handleLabelChange;

  const handleAddSibling = useCallback(() => {
    if (!selectedNodeId) return;
    const parentEdge = edges.find(e => e.target === selectedNodeId);
    if (parentEdge) {
      const dir = (parentEdge.data as unknown)?.direction || 'right';
      handleAddChild(parentEdge.source, dir);
    }
  }, [selectedNodeId, edges, handleAddChild]);

  const handleDelete = useCallback(() => {
    if (!selectedNodeId || selectedNodeId === 'root') return;
    // Recursively find all descendants
    const toDelete = new Set<string>();
    const findDescendants = (nodeId: string) => {
      toDelete.add(nodeId);
      edges.filter(e => e.source === nodeId).forEach(e => findDescendants(e.target));
    };
    findDescendants(selectedNodeId);

    setNodes(nds => nds.filter(n => !toDelete.has(n.id)));
    setEdges(eds => eds.filter(e => !toDelete.has(e.source) && !toDelete.has(e.target)));
    setSelectedNodeId(null);
    setSaveStatus('unsaved');
    setTimeout(() => autoLayoutRef.current(), 50);
  }, [selectedNodeId, edges]);

  const handleEditLabel = useCallback(() => {}, []);

  // Auto-layout: bidirectional tree algorithm
  const autoLayoutRef = useRef<() => void>(() => {});
  const handleAutoLayout = useCallback(() => {
    setNodes(currentNodes => {
      let currentEdges: Edge[] = [];
      setEdges(eds => { currentEdges = eds; return eds; });

      // Build adjacency with direction
      const rightChildrenMap: Record<string, string[]> = {};
      const leftChildrenMap: Record<string, string[]> = {};
      currentEdges.forEach(e => {
        const dir = (e.data as unknown)?.direction || 'right';
        if (dir === 'left') {
          if (!leftChildrenMap[e.source]) leftChildrenMap[e.source] = [];
          leftChildrenMap[e.source].push(e.target);
        } else {
          if (!rightChildrenMap[e.source]) rightChildrenMap[e.source] = [];
          rightChildrenMap[e.source].push(e.target);
        }
      });

      // Find root(s)
      const targetIds = new Set(currentEdges.map(e => e.target));
      const roots = currentNodes.filter(n => !targetIds.has(n.id));
      if (roots.length === 0) return currentNodes;

      // Check collapsed state
      const collapsedSet = new Set(
        currentNodes.filter(n => (n.data as unknown).collapsed).map(n => n.id)
      );

      const H_GAP = 50; // horizontal gap between a node's right edge and its child's left edge
      const V_GAP = 16; // vertical gap between sibling nodes
      const positions: Record<string, { x: number; y: number }> = {};
      const nodeMap = new Map(currentNodes.map(n => [n.id, n]));

      const getNodeHeight = (nodeId: string): number => {
        const n = nodeMap.get(nodeId);
        return n?.measured?.height ?? n?.height ?? 40;
      };
      const getNodeWidth = (nodeId: string): number => {
        const n = nodeMap.get(nodeId);
        return n?.measured?.width ?? n?.width ?? 120;
      };

      // Calculate the total vertical space a subtree needs
      // This is the sum of all leaf-level heights + gaps, NOT influenced by parent height
      const subtreeHeightCache: Record<string, number> = {};
      const calcSubtreeSpan = (nodeId: string, childrenMap: Record<string, string[]>): number => {
        const key = `${nodeId}-${childrenMap === rightChildrenMap ? 'r' : 'l'}`;
        if (subtreeHeightCache[key] !== undefined) return subtreeHeightCache[key];

        if (collapsedSet.has(nodeId)) {
          subtreeHeightCache[key] = getNodeHeight(nodeId);
          return subtreeHeightCache[key];
        }

        const children = childrenMap[nodeId];
        if (!children || children.length === 0) {
          subtreeHeightCache[key] = getNodeHeight(nodeId);
          return subtreeHeightCache[key];
        }

        // Total span = sum of all children subtree spans + gaps between them
        let total = 0;
        children.forEach((cId, i) => {
          if (i > 0) total += V_GAP;
          total += calcSubtreeSpan(cId, childrenMap);
        });

        // The parent itself needs at least its own height
        subtreeHeightCache[key] = Math.max(getNodeHeight(nodeId), total);
        return subtreeHeightCache[key];
      };

      // Layout a branch: place children, then center parent on them
      const layoutBranch = (
        nodeId: string,
        xStart: number, // the X position for this node
        yCenterHint: number, // the center Y where this subtree should be placed
        childrenMap: Record<string, string[]>,
        dirMul: number // 1 for right, -1 for left
      ) => {
        const myHeight = getNodeHeight(nodeId);
        const myWidth = getNodeWidth(nodeId);
        const children = collapsedSet.has(nodeId) ? undefined : childrenMap[nodeId];

        if (!children || children.length === 0) {
          // Leaf: center on the hint
          if (!positions[nodeId]) {
            positions[nodeId] = { x: xStart, y: yCenterHint - myHeight / 2 };
          }
          return;
        }

        // Calculate children positions
        const totalChildSpan = calcSubtreeSpan(nodeId, childrenMap);
        const childrenSpan = children.reduce((sum, cId, i) => {
          return sum + calcSubtreeSpan(cId, childrenMap) + (i > 0 ? V_GAP : 0);
        }, 0);

        // Children X: after this node's right edge + gap
        const childX = dirMul > 0
          ? xStart + myWidth + H_GAP
          : xStart - H_GAP; // for left, children are placed to the left

        // Children Y: centered around the hint
        let childYTop = yCenterHint - childrenSpan / 2;

        children.forEach(childId => {
          const childSpan = calcSubtreeSpan(childId, childrenMap);
          const childCenter = childYTop + childSpan / 2;

          // For left direction, position child so its right edge aligns
          const childWidth = getNodeWidth(childId);
          const childXPos = dirMul > 0 ? childX : childX - childWidth;

          positions[childId] = {
            x: childXPos,
            y: childCenter - getNodeHeight(childId) / 2,
          };
          layoutBranch(childId, childXPos, childCenter, childrenMap, dirMul);
          childYTop += childSpan + V_GAP;
        });

        // Center parent vertically among its children
        if (!positions[nodeId]) {
          const firstChildPos = positions[children[0]];
          const lastChildPos = positions[children[children.length - 1]];
          const lastChildH = getNodeHeight(children[children.length - 1]);
          const centerY = (firstChildPos.y + lastChildPos.y + lastChildH) / 2 - myHeight / 2;
          positions[nodeId] = { x: xStart, y: centerY };
        }
      };

      let globalY = 0;
      roots.forEach(root => {
        const hasRight = !collapsedSet.has(root.id) && (rightChildrenMap[root.id]?.length || 0) > 0;
        const hasLeft = !collapsedSet.has(root.id) && (leftChildrenMap[root.id]?.length || 0) > 0;

        const rightSpan = hasRight ? calcSubtreeSpan(root.id, rightChildrenMap) : getNodeHeight(root.id);
        const leftSpan = hasLeft ? calcSubtreeSpan(root.id, leftChildrenMap) : getNodeHeight(root.id);
        const maxSpan = Math.max(rightSpan, leftSpan);
        const centerY = globalY + maxSpan / 2;

        // Position root
        const rootWidth = getNodeWidth(root.id);
        positions[root.id] = { x: -rootWidth / 2, y: centerY - getNodeHeight(root.id) / 2 };

        if (hasRight) {
          layoutBranch(root.id, -rootWidth / 2, centerY, rightChildrenMap, 1);
        }
        if (hasLeft) {
          layoutBranch(root.id, -rootWidth / 2, centerY, leftChildrenMap, -1);
        }

        globalY += maxSpan + V_GAP * 3;
      });

      setSaveStatus('unsaved');

      // Update metadata and positions
      const updatedNodes = currentNodes.map(n => ({
        ...n,
        position: positions[n.id] || n.position,
        // Hide collapsed children
        hidden: isHiddenByCollapse(n.id, currentEdges, collapsedSet),
      }));

      return updateNodeMetadata(updatedNodes, currentEdges);
    });

    // Also hide collapsed edges
    setEdges(eds => {
      let currentNodes: Node[] = [];
      setNodes(nds => { currentNodes = nds; return nds; });
      const hiddenNodeIds = new Set(currentNodes.filter(n => n.hidden).map(n => n.id));
      return eds.map(e => ({
        ...e,
        hidden: hiddenNodeIds.has(e.target),
      }));
    });
  }, [updateNodeMetadata]);

  autoLayoutRef.current = handleAutoLayout;

  const onConnect = useCallback((connection: Connection) => {
    setEdges(eds => addEdge({
      ...connection,
      type: 'default',
      style: { stroke: 'hsl(var(--muted-foreground))', strokeWidth: 2 },
    }, eds));
    setSaveStatus('unsaved');
  }, []);

  const onSelectionChange = useCallback(({ nodes: selectedNodes }: { nodes: Node[] }) => {
    setSelectedNodeId(selectedNodes.length === 1 ? selectedNodes[0].id : null);
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (e.key === 'Tab' && selectedNodeId) {
        e.preventDefault();
        handleAddChild(selectedNodeId, 'right');
      }
      if (e.key === 'Enter' && selectedNodeId) {
        e.preventDefault();
        handleAddSibling();
      }
      if ((e.key === 'Delete' || e.key === 'Backspace') && selectedNodeId) {
        e.preventDefault();
        handleDelete();
      }
      if (e.key === 's' && (e.ctrlKey || e.metaKey) && id) {
        e.preventDefault();
        setSaveStatus('saving');
        updateMindMap.mutate(
          { id, title, nodes, edges },
          { onSuccess: () => setSaveStatus('saved') }
        );
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [selectedNodeId, handleAddChild, handleAddSibling, handleDelete, id, title, nodes, edges]);

  if (!mindMap && mindMaps.length > 0) {
    return (
      <div className="h-screen flex items-center justify-center text-muted-foreground">
        Mapa mental não encontrado.
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col bg-background">
      {/* Header */}
      <div className="h-14 border-b border-border flex items-center justify-between px-4 bg-card shrink-0 z-10">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={() => navigate('/mapas-mentais')}>
            <ArrowLeft className="w-4 h-4" />
          </Button>
          <Input
            value={title}
            onChange={e => { setTitle(e.target.value); setSaveStatus('unsaved'); }}
            className="border-none bg-transparent text-lg font-semibold h-9 w-64 focus-visible:ring-0 px-1"
          />
        </div>
        <div className="flex items-center gap-3">
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button variant="outline" size="sm" onClick={handleAutoLayout} className="gap-1.5">
                  <LayoutGrid className="w-3.5 h-3.5" />
                  Reorganizar
                </Button>
              </TooltipTrigger>
              <TooltipContent>Organizar nós automaticamente em árvore</TooltipContent>
            </Tooltip>
          </TooltipProvider>
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            {saveStatus === 'saving' && <><Loader2 className="w-3.5 h-3.5 animate-spin" /> Salvando...</>}
            {saveStatus === 'saved' && <><Check className="w-3.5 h-3.5 text-green-500" /> Salvo</>}
            {saveStatus === 'unsaved' && <><Save className="w-3.5 h-3.5" /> Não salvo</>}
          </div>
        </div>
      </div>

      {/* Canvas */}
      <div className="flex-1 relative">
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          onSelectionChange={onSelectionChange}
          nodeTypes={nodeTypes}
          fitView
          defaultEdgeOptions={{
            type: 'default',
            style: { stroke: 'hsl(var(--muted-foreground))', strokeWidth: 2 },
          }}
          proOptions={{ hideAttribution: true }}
        >
          <Background variant={BackgroundVariant.Dots} gap={20} size={1} color="hsl(var(--muted-foreground) / 0.15)" />
          <Controls className="!bg-card !border-border !shadow-sm [&>button]:!bg-card [&>button]:!border-border [&>button]:!text-foreground" />
          <MiniMap
            nodeColor={() => 'hsl(var(--primary))'}
            maskColor="hsl(var(--background) / 0.8)"
            className="!bg-card !border-border"
          />
        </ReactFlow>

        <MindMapToolbar
          hasSelection={!!selectedNodeId}
          onAddChild={() => selectedNodeId && handleAddChild(selectedNodeId, 'right')}
          onAddSibling={handleAddSibling}
          onEditLabel={handleEditLabel}
          onDelete={handleDelete}
        />
      </div>
    </div>
  );
}

// Helper: check if a node should be hidden because an ancestor is collapsed
function isHiddenByCollapse(nodeId: string, edges: Edge[], collapsedSet: Set<string>): boolean {
  // Find parent
  const parentEdge = edges.find(e => e.target === nodeId);
  if (!parentEdge) return false; // root is never hidden
  if (collapsedSet.has(parentEdge.source)) return true;
  return isHiddenByCollapse(parentEdge.source, edges, collapsedSet);
}

export default function MapaMentalEditor() {
  return (
    <ReactFlowProvider>
      <MindMapEditorInner />
    </ReactFlowProvider>
  );
}

import { useState, useEffect } from "react";
import { useSearchParams } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Check,
  X,
  Loader2,
  Image as ImageIcon,
  Calendar,
  AlertCircle,
  CheckCircle2,
  XCircle,
  ChevronLeft,
  ChevronRight,
  Play,
  Film,
  FileText,
} from "lucide-react";
import { toast } from "sonner";

interface Slide {
  id: string;
  post_id: string;
  order_index: number;
  headline: string | null;
  content: string | null;
  image_url: string | null;
}

interface ReelsScene {
  index: number;
  status: string;
  videoUrl?: string;
  error?: string;
}

interface ReelsProgress {
  totalScenes?: number;
  scenes?: ReelsScene[];
}

interface Post {
  id: string;
  order_index: number;
  headline: string | null;
  subheadline: string | null;
  caption: string | null;
  objective: string | null;
  post_type: string | null;
  image_url: string | null;
  review_status: string | null;
  review_feedback: string | null;
  reviewed_at: string | null;
  slides?: Slide[];
  reels_video_url?: string | null;
  reels_generation_status?: string | null;
  reels_generation_progress?: ReelsProgress | null;
  reels_uploaded_video_url?: string | null;
  script?: string | null;
}

interface Plan {
  id: string;
  name: string;
  status: string;
  month: number;
  year: number;
  clients: {
    id: string;
    name: string;
    company: string;
    avatar: string | null;
  } | null;
}

const monthNames = [
  "Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho",
  "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"
];

export default function PublicContentReview() {
  const [searchParams] = useSearchParams();
  const token = searchParams.get("token");

  const [plan, setPlan] = useState<Plan | null>(null);
  const [posts, setPosts] = useState<Post[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [rejectingPostId, setRejectingPostId] = useState<string | null>(null);
  const [rejectFeedback, setRejectFeedback] = useState("");
  const [updatingPostId, setUpdatingPostId] = useState<string | null>(null);
  const [carouselIndexes, setCarouselIndexes] = useState<Record<string, number>>({});
  const [reelsVideoIndexes, setReelsVideoIndexes] = useState<Record<string, number>>({});
  const [viewingScriptPost, setViewingScriptPost] = useState<Post | null>(null);
  const getCarouselIndex = (postId: string) => carouselIndexes[postId] || 0;

  const setCarouselIndex = (postId: string, index: number) => {
    setCarouselIndexes(prev => ({ ...prev, [postId]: index }));
  };

  const getReelsVideoIndex = (postId: string) => reelsVideoIndexes[postId] || 0;

  const setReelsVideoIndex = (postId: string, index: number) => {
    setReelsVideoIndexes(prev => ({ ...prev, [postId]: index }));
  };

  useEffect(() => {
    if (token) {
      fetchPlanData();
    } else {
      setError("Link inválido");
      setIsLoading(false);
    }
  }, [token]);

  const fetchPlanData = async () => {
    try {
      setIsLoading(true);
      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/public-content-review?token=${token}`
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Erro ao carregar dados");
      }

      setPlan(data.plan);
      setPosts(data.posts);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erro ao carregar dados");
    } finally {
      setIsLoading(false);
    }
  };

  const handleApprove = async (postId: string) => {
    setUpdatingPostId(postId);
    try {
      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/public-content-review`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            postId,
            reviewStatus: "approved",
            planToken: token,
          }),
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Erro ao aprovar");
      }

      setPosts((prev) =>
        prev.map((p) =>
          p.id === postId
            ? { ...p, review_status: "approved", review_feedback: null, reviewed_at: new Date().toISOString() }
            : p
        )
      );
      toast.success("Post aprovado!");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Erro ao aprovar");
    } finally {
      setUpdatingPostId(null);
    }
  };

  const handleReject = async () => {
    if (!rejectingPostId || !rejectFeedback.trim()) {
      toast.error("Informe o que precisa ser alterado");
      return;
    }

    setUpdatingPostId(rejectingPostId);
    try {
      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/public-content-review`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            postId: rejectingPostId,
            reviewStatus: "rejected",
            reviewFeedback: rejectFeedback,
            planToken: token,
          }),
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Erro ao rejeitar");
      }

      setPosts((prev) =>
        prev.map((p) =>
          p.id === rejectingPostId
            ? { ...p, review_status: "rejected", review_feedback: rejectFeedback, reviewed_at: new Date().toISOString() }
            : p
        )
      );
      setRejectingPostId(null);
      setRejectFeedback("");
      toast.success("Feedback enviado!");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Erro ao rejeitar");
    } finally {
      setUpdatingPostId(null);
    }
  };

  const getReviewStatusBadge = (status: string | null) => {
    switch (status) {
      case "approved":
        return (
          <Badge className="bg-green-500/10 text-green-600 border-green-500/20">
            <CheckCircle2 className="w-3 h-3 mr-1" />
            Aprovado
          </Badge>
        );
      case "rejected":
        return (
          <Badge className="bg-red-500/10 text-red-600 border-red-500/20">
            <XCircle className="w-3 h-3 mr-1" />
            Reprovado
          </Badge>
        );
      default:
        return (
          <Badge variant="secondary">
            <AlertCircle className="w-3 h-3 mr-1" />
            Pendente
          </Badge>
        );
    }
  };

  const approvedCount = posts.filter((p) => p.review_status === "approved").length;
  const rejectedCount = posts.filter((p) => p.review_status === "rejected").length;
  const pendingCount = posts.filter((p) => !p.review_status || p.review_status === "pending").length;

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <Card className="max-w-md w-full mx-4">
          <CardContent className="pt-6 text-center">
            <XCircle className="w-12 h-12 text-destructive mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">Erro</h2>
            <p className="text-muted-foreground">{error}</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!plan) return null;

  return (
    <div className="min-h-screen bg-background">
      {/* Header */}
      <header className="border-b bg-card sticky top-0 z-10">
        <div className="container max-w-6xl mx-auto px-4 py-4">
          <div className="flex items-center gap-4">
            {plan.clients?.avatar && (
              <Avatar className="h-12 w-12">
                <AvatarImage src={plan.clients.avatar} />
                <AvatarFallback>{plan.clients.name?.charAt(0)}</AvatarFallback>
              </Avatar>
            )}
            <div className="flex-1">
              <h1 className="text-xl font-bold">{plan.name}</h1>
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <span>{plan.clients?.name}</span>
                <span>•</span>
                <Calendar className="w-4 h-4" />
                <span>{monthNames[plan.month - 1]} {plan.year}</span>
              </div>
            </div>
          </div>

          {/* Progress summary */}
          <div className="flex gap-4 mt-4">
            <div className="flex items-center gap-2 text-sm">
              <div className="w-3 h-3 rounded-full bg-green-500" />
              <span>{approvedCount} aprovados</span>
            </div>
            <div className="flex items-center gap-2 text-sm">
              <div className="w-3 h-3 rounded-full bg-red-500" />
              <span>{rejectedCount} reprovados</span>
            </div>
            <div className="flex items-center gap-2 text-sm">
              <div className="w-3 h-3 rounded-full bg-muted-foreground" />
              <span>{pendingCount} pendentes</span>
            </div>
          </div>
        </div>
      </header>

      {/* Posts grid */}
      <main className="container max-w-6xl mx-auto px-4 py-8">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {posts.map((post, index) => (
            <Card
              key={post.id}
              className={`overflow-hidden transition-all ${
                post.review_status === "approved"
                  ? "ring-2 ring-green-500/30"
                  : post.review_status === "rejected"
                  ? "ring-2 ring-red-500/30"
                  : ""
              }`}
            >
              {/* Image / Carousel / Reels Video */}
              <div className="aspect-[3/4] bg-muted relative">
                {/* Reels Video Player */}
                {post.post_type === 'reels' ? (
                  (() => {
                    // Priority: uploaded video > generated scenes
                    if (post.reels_uploaded_video_url) {
                      return (
                        <>
                          <video
                            src={post.reels_uploaded_video_url}
                            controls
                            className="w-full h-full object-cover"
                            poster={post.image_url || undefined}
                          />
                          {/* Play icon overlay */}
                          <div className="absolute top-12 left-2 bg-primary/80 backdrop-blur-sm rounded-full px-2 py-0.5 text-xs font-medium text-primary-foreground flex items-center gap-1">
                            <Play className="w-3 h-3" />
                            Reels
                          </div>
                          {/* Script button for reels */}
                          {post.script && (
                            <button
                              onClick={() => setViewingScriptPost(post)}
                              className="absolute top-12 right-2 bg-background/80 backdrop-blur-sm hover:bg-background rounded-full px-2 py-0.5 text-xs font-medium flex items-center gap-1 transition-colors"
                            >
                              <FileText className="w-3 h-3" />
                              Roteiro
                            </button>
                          )}
                        </>
                      );
                    }

                    const progress = post.reels_generation_progress as ReelsProgress | null;
                    const completedScenes = progress?.scenes?.filter(s => s.status === 'completed' && s.videoUrl) || [];
                    const currentIndex = getReelsVideoIndex(post.id);
                    const currentScene = completedScenes[currentIndex];

                    if (completedScenes.length === 0) {
                      // No videos generated yet
                      return (
                        <div className="w-full h-full flex flex-col items-center justify-center gap-3">
                          <Film className="w-16 h-16 text-muted-foreground/30" />
                          <span className="text-sm text-muted-foreground">Vídeo em processamento</span>
                        </div>
                      );
                    }

                    return (
                      <>
                        {/* Video player */}
                        <video
                          key={currentScene?.videoUrl}
                          src={currentScene?.videoUrl}
                          controls
                          className="w-full h-full object-cover"
                          poster={post.image_url || undefined}
                        />

                        {/* Navigation for multiple videos */}
                        {completedScenes.length > 1 && (
                          <>
                            <button
                              onClick={() => setReelsVideoIndex(post.id, Math.max(0, currentIndex - 1))}
                              disabled={currentIndex === 0}
                              className="absolute left-2 top-1/2 -translate-y-1/2 bg-background/80 backdrop-blur-sm rounded-full w-8 h-8 flex items-center justify-center disabled:opacity-30 hover:bg-background transition-colors z-10"
                            >
                              <ChevronLeft className="w-5 h-5" />
                            </button>
                            <button
                              onClick={() => setReelsVideoIndex(post.id, Math.min(completedScenes.length - 1, currentIndex + 1))}
                              disabled={currentIndex === completedScenes.length - 1}
                              className="absolute right-2 top-1/2 -translate-y-1/2 bg-background/80 backdrop-blur-sm rounded-full w-8 h-8 flex items-center justify-center disabled:opacity-30 hover:bg-background transition-colors z-10"
                            >
                              <ChevronRight className="w-5 h-5" />
                            </button>

                            {/* Video indicators */}
                            <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
                              {completedScenes.map((_, idx) => (
                                <button
                                  key={idx}
                                  onClick={() => setReelsVideoIndex(post.id, idx)}
                                  className={`w-2 h-2 rounded-full transition-colors ${
                                    idx === currentIndex
                                      ? 'bg-white'
                                      : 'bg-white/50 hover:bg-white/75'
                                  }`}
                                />
                              ))}
                            </div>

                            {/* Video counter */}
                            <div className="absolute bottom-3 right-2 bg-background/80 backdrop-blur-sm rounded-full px-2 py-0.5 text-xs font-medium z-10">
                              {currentIndex + 1}/{completedScenes.length}
                            </div>
                          </>
                        )}

                        {/* Play icon overlay */}
                        <div className="absolute top-12 left-2 bg-primary/80 backdrop-blur-sm rounded-full px-2 py-0.5 text-xs font-medium text-primary-foreground flex items-center gap-1">
                          <Play className="w-3 h-3" />
                          Reels
                        </div>

                        {/* Script button for reels */}
                        {post.script && (
                          <button
                            onClick={() => setViewingScriptPost(post)}
                            className="absolute top-12 right-2 bg-background/80 backdrop-blur-sm hover:bg-background rounded-full px-2 py-0.5 text-xs font-medium flex items-center gap-1 transition-colors"
                          >
                            <FileText className="w-3 h-3" />
                            Roteiro
                          </button>
                        )}
                      </>
                    );
                  })()
                ) : post.post_type === 'carrossel' && post.slides && post.slides.length > 0 ? (
                  <>
                    {/* Carousel image */}
                    {post.slides[getCarouselIndex(post.id)]?.image_url ? (
                      <img
                        src={post.slides[getCarouselIndex(post.id)].image_url!}
                        alt={post.slides[getCarouselIndex(post.id)]?.headline || `Slide ${getCarouselIndex(post.id) + 1}`}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <ImageIcon className="w-16 h-16 text-muted-foreground/30" />
                      </div>
                    )}

                    {/* Carousel navigation */}
                    {post.slides.length > 1 && (
                      <>
                        <button
                          onClick={() => setCarouselIndex(post.id, Math.max(0, getCarouselIndex(post.id) - 1))}
                          disabled={getCarouselIndex(post.id) === 0}
                          className="absolute left-2 top-1/2 -translate-y-1/2 bg-background/80 backdrop-blur-sm rounded-full w-8 h-8 flex items-center justify-center disabled:opacity-30 hover:bg-background transition-colors"
                        >
                          <ChevronLeft className="w-5 h-5" />
                        </button>
                        <button
                          onClick={() => setCarouselIndex(post.id, Math.min(post.slides!.length - 1, getCarouselIndex(post.id) + 1))}
                          disabled={getCarouselIndex(post.id) === post.slides.length - 1}
                          className="absolute right-2 top-1/2 -translate-y-1/2 bg-background/80 backdrop-blur-sm rounded-full w-8 h-8 flex items-center justify-center disabled:opacity-30 hover:bg-background transition-colors"
                        >
                          <ChevronRight className="w-5 h-5" />
                        </button>

                        {/* Carousel indicators */}
                        <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-1.5">
                          {post.slides.map((_, idx) => (
                            <button
                              key={idx}
                              onClick={() => setCarouselIndex(post.id, idx)}
                              className={`w-2 h-2 rounded-full transition-colors ${
                                idx === getCarouselIndex(post.id)
                                  ? 'bg-white'
                                  : 'bg-white/50 hover:bg-white/75'
                              }`}
                            />
                          ))}
                        </div>
                      </>
                    )}

                    {/* Slide counter */}
                    <div className="absolute bottom-3 right-2 bg-background/80 backdrop-blur-sm rounded-full px-2 py-0.5 text-xs font-medium">
                      {getCarouselIndex(post.id) + 1}/{post.slides.length}
                    </div>
                  </>
                ) : (
                  <>
                    {post.image_url ? (
                      <img
                        src={post.image_url}
                        alt={post.headline || `Post ${index + 1}`}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center">
                        <ImageIcon className="w-16 h-16 text-muted-foreground/30" />
                      </div>
                    )}
                  </>
                )}

                {/* Post number */}
                <div className="absolute top-2 left-2 bg-background/80 backdrop-blur-sm rounded-full w-8 h-8 flex items-center justify-center text-sm font-medium">
                  {index + 1}
                </div>

                {/* Status badge */}
                <div className="absolute top-2 right-2">
                  {getReviewStatusBadge(post.review_status)}
                </div>
              </div>

              <CardContent className="p-4 space-y-3">
                {/* Headlines */}
                {post.headline && (
                  <h3 className="font-semibold text-sm">{post.headline}</h3>
                )}
                {post.subheadline && (
                  <p className="text-sm text-muted-foreground">{post.subheadline}</p>
                )}

                {/* Caption */}
                {post.caption && (
                  <div className="text-xs text-muted-foreground border-t pt-3">
                    <p className="whitespace-pre-wrap">{post.caption}</p>
                  </div>
                )}

                {/* Rejection feedback */}
                {post.review_status === "rejected" && post.review_feedback && (
                  <div className="bg-red-500/10 border border-red-500/20 rounded-md p-3">
                    <p className="text-xs font-medium text-red-600 mb-1">Feedback:</p>
                    <p className="text-xs text-red-600/80">{post.review_feedback}</p>
                  </div>
                )}

                {/* Action buttons */}
                <div className="flex gap-2 pt-2">
                  <Button
                    variant={post.review_status === "approved" ? "default" : "outline"}
                    size="sm"
                    className="flex-1 gap-1"
                    onClick={() => handleApprove(post.id)}
                    disabled={updatingPostId === post.id}
                  >
                    {updatingPostId === post.id ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <Check className="w-4 h-4" />
                    )}
                    Aprovar
                  </Button>
                  <Button
                    variant={post.review_status === "rejected" ? "destructive" : "outline"}
                    size="sm"
                    className="flex-1 gap-1"
                    onClick={() => {
                      setRejectingPostId(post.id);
                      setRejectFeedback(post.review_feedback || "");
                    }}
                    disabled={updatingPostId === post.id}
                  >
                    <X className="w-4 h-4" />
                    Reprovar
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>

        {posts.length === 0 && (
          <div className="text-center py-16">
            <ImageIcon className="w-16 h-16 text-muted-foreground/30 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-muted-foreground">
              Nenhum post neste planejamento
            </h3>
          </div>
        )}
      </main>

      {/* Reject dialog */}
      <Dialog open={!!rejectingPostId} onOpenChange={() => setRejectingPostId(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Reprovar Post</DialogTitle>
            <DialogDescription>
              Informe o que precisa ser alterado neste post para que seja aprovado.
            </DialogDescription>
          </DialogHeader>

          <Textarea
            placeholder="Descreva as alterações necessárias..."
            value={rejectFeedback}
            onChange={(e) => setRejectFeedback(e.target.value)}
            rows={4}
          />

          <DialogFooter>
            <Button variant="outline" onClick={() => setRejectingPostId(null)}>
              Cancelar
            </Button>
            <Button
              variant="destructive"
              onClick={handleReject}
              disabled={!rejectFeedback.trim() || updatingPostId === rejectingPostId}
            >
              {updatingPostId === rejectingPostId ? (
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
              ) : null}
              Enviar Feedback
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Script Modal */}
      <Dialog open={!!viewingScriptPost} onOpenChange={() => setViewingScriptPost(null)}>
        <DialogContent className="max-w-2xl max-h-[80vh]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <FileText className="w-5 h-5" />
              Roteiro do Reels
            </DialogTitle>
            {viewingScriptPost?.headline && (
              <DialogDescription>
                {viewingScriptPost.headline}
              </DialogDescription>
            )}
          </DialogHeader>
          <ScrollArea className="max-h-[60vh]">
            <div className="whitespace-pre-wrap text-sm leading-relaxed p-1">
              {viewingScriptPost?.script}
            </div>
          </ScrollArea>
          <DialogFooter>
            <Button variant="outline" onClick={() => setViewingScriptPost(null)}>
              Fechar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useParams, Navigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { CalendarIcon, Upload, Send, CheckCircle, AlertCircle } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";

interface ClientInfo {
  id: string;
  name: string;
  email: string;
  company_name?: string;
}

interface TokenInfo {
  id: string;
  client_id: string;
  company_id: string;
}

export default function ReportLeadDesqualificado() {
  const { token } = useParams<{ token: string }>();
  const { toast } = useToast();

  const [clientInfo, setClientInfo] = useState<ClientInfo | null>(null);
  const [tokenInfo, setTokenInfo] = useState<TokenInfo | null>(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form data
  const [reporterName, setReporterName] = useState("");
  const [leadDate, setLeadDate] = useState<Date>();
  const [reason, setReason] = useState("");
  const [notes, setNotes] = useState("");
  const [conversationLink, setConversationLink] = useState("");
  const [evidenceFile, setEvidenceFile] = useState<File | null>(null);

  const reasonOptions = [
    { value: "fora_perfil", label: "Fora do perfil" },
    { value: "informacoes_incorretas", label: "Informações incorretas" },
    { value: "contato_errado", label: "Contato errado" },
    { value: "ligacao_sem_resposta", label: "Ligação sem resposta" },
    { value: "outro", label: "Outro" }
  ];

  useEffect(() => {
    if (token) {
      validateTokenAndLoadClient();
    }
  }, [token]);

  const validateTokenAndLoadClient = async () => {
    try {
      setLoading(true);
      setError(null);

      const { data, error } = await supabase
        .from('lead_disqualification_tokens')
        .select(`
          id,
          client_id,
          company_id
        `)
        .eq('token', token)
        .single();

      if (error || !data) {
        setError('Token inválido ou expirado');
        return;
      }

      // Buscar dados do cliente separadamente
      const { data: clientData, error: clientError } = await supabase
        .from('clients')
        .select(`
          id,
          name,
          email,
          company_id
        `)
        .eq('id', data.client_id)
        .single();

      if (clientError || !clientData) {
        setError('Cliente não encontrado');
        return;
      }

      setTokenInfo({
        id: data.id,
        client_id: data.client_id,
        company_id: data.company_id
      });

      setClientInfo({
        id: clientData.id,
        name: clientData.name,
        email: clientData.email,
        company_name: undefined // Por enquanto sem nome da empresa
      });

    } catch (err) {
      console.error('Error validating token:', err);
      setError('Erro ao validar token');
    } finally {
      setLoading(false);
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      // Validar tipo e tamanho do arquivo
      const maxSize = 10 * 1024 * 1024; // 10MB
      const allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'application/pdf'];

      if (file.size > maxSize) {
        toast({
          title: "Arquivo muito grande",
          description: "O arquivo deve ter no máximo 10MB",
          variant: "destructive",
        });
        return;
      }

      if (!allowedTypes.includes(file.type)) {
        toast({
          title: "Tipo de arquivo não suportado",
          description: "Apenas imagens (JPEG, PNG, GIF) e PDFs são permitidos",
          variant: "destructive",
        });
        return;
      }

      setEvidenceFile(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!reporterName || !leadDate || !reason) {
      toast({
        title: "Campos obrigatórios",
        description: "Preencha todos os campos obrigatórios",
        variant: "destructive",
      });
      return;
    }

    setSubmitting(true);

    try {
      let evidenceFileUrl = null;

      // Upload do arquivo de evidência primeiro, se fornecido
      if (evidenceFile && clientInfo) {
        // Função para sanitizar o nome do arquivo
        const sanitizeFileName = (name: string): string => {
          return name
            .normalize('NFD') // Decompor acentos
            .replace(/[\u0300-\u036f]/g, '') // Remover acentos
            .replace(/[^a-zA-Z0-9.-]/g, '_') // Substituir caracteres especiais por underscore
            .replace(/_{2,}/g, '_') // Substituir múltiplos underscores por um só
            .replace(/^_|_$/g, ''); // Remover underscores do início e fim
        };

        // Gerar nome de arquivo com fallback caso o nome original seja undefined
        const originalName = evidenceFile.name || 'arquivo_sem_nome';
        const sanitizedName = sanitizeFileName(originalName);
        const fileExtension = sanitizedName.split('.').pop() || 'bin';
        const timestamp = Date.now();
        const fileName = `${clientInfo.id}/${timestamp}-${sanitizedName}`;


        const { data: uploadData, error: uploadError } = await supabase.storage
          .from('lead-evidence')
          .upload(fileName, evidenceFile, {
            cacheControl: '3600',
            upsert: false
          });

        if (uploadError) {
          console.error('Upload error:', uploadError);
          toast({
            title: "Erro no upload da evidência",
            description: "Não foi possível fazer upload do arquivo, mas o report será enviado sem evidência.",
            variant: "destructive",
          });
        } else {
          evidenceFileUrl = fileName;
        }
      }

      // Enviar o report com a URL do arquivo (se houver)
      const { data, error } = await supabase.functions.invoke('process-lead-disqualification-report', {
        body: {
          token,
          reporter_name: reporterName,
          lead_received_date: format(leadDate, 'yyyy-MM-dd'),
          disqualification_reason: reason,
          additional_notes: notes,
          conversation_link: conversationLink || null,
          evidence_file_url: evidenceFileUrl
        }
      });

      if (error) throw error;

      setSubmitted(true);
      toast({
        title: "Report enviado!",
        description: "Obrigado pelo feedback. O report foi enviado com sucesso.",
      });

    } catch (err) {
      console.error('Error submitting report:', err);
      toast({
        title: "Erro ao enviar report",
        description: "Tente novamente mais tarde",
        variant: "destructive",
      });
    } finally {
      setSubmitting(false);
    }
  };

  if (!token) {
    return <Navigate to="/" replace />;
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="animate-spin h-8 w-8 border-4 border-primary border-t-transparent rounded-full" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center p-4">
        <Card className="max-w-md w-full">
          <CardHeader className="text-center">
            <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
            <CardTitle>Erro</CardTitle>
            <CardDescription>{error}</CardDescription>
          </CardHeader>
        </Card>
      </div>
    );
  }

  if (submitted) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center p-4">
        <Card className="max-w-md w-full">
          <CardHeader className="text-center">
            <CheckCircle className="h-12 w-12 text-green-600 mx-auto mb-4" />
            <CardTitle>Report Enviado!</CardTitle>
            <CardDescription>
              Obrigado pelo feedback. Seu report foi enviado com sucesso e nossa equipe irá analisá-lo.
            </CardDescription>
          </CardHeader>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <div className="container max-w-2xl mx-auto py-8 px-4">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold mb-2">Report de Lead Desqualificado</h1>
          <p className="text-muted-foreground">
            Use este formulário para reportar leads que não atendem aos critérios esperados
          </p>
        </div>

        {/* Client Info */}
        {clientInfo && (
          <Card className="mb-6">
            <CardContent className="pt-6">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="font-medium">{clientInfo.name}</h3>
                  <p className="text-sm text-muted-foreground">{clientInfo.email}</p>
                  {clientInfo.company_name && (
                    <Badge variant="secondary" className="mt-1">
                      {clientInfo.company_name}
                    </Badge>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Form */}
        <Card>
          <CardHeader>
            <CardTitle>Informações do Lead</CardTitle>
            <CardDescription>
              Preencha as informações sobre o lead que deseja reportar
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Reporter Name */}
              <div className="space-y-2">
                <Label htmlFor="reporter-name">
                  Nome de quem está reportando *
                </Label>
                <Input
                  id="reporter-name"
                  value={reporterName}
                  onChange={(e) => setReporterName(e.target.value)}
                  placeholder="Seu nome completo"
                  required
                />
              </div>

              {/* Lead Date */}
              <div className="space-y-2">
                <Label>Data em que o lead foi recebido *</Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      className={cn(
                        "w-full justify-start text-left font-normal",
                        !leadDate && "text-muted-foreground"
                      )}
                    >
                      <CalendarIcon className="mr-2 h-4 w-4" />
                      {leadDate ? format(leadDate, "PPP", { locale: ptBR }) : "Selecione uma data"}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={leadDate}
                      onSelect={setLeadDate}
                      initialFocus
                      className="p-3 pointer-events-auto"
                    />
                  </PopoverContent>
                </Popover>
              </div>

              {/* Reason */}
              <div className="space-y-2">
                <Label>Motivo da desqualificação *</Label>
                <Select value={reason} onValueChange={setReason}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione o motivo" />
                  </SelectTrigger>
                  <SelectContent>
                    {reasonOptions.map((option) => (
                      <SelectItem key={option.value} value={option.value}>
                        {option.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {/* Additional Notes */}
              <div className="space-y-2">
                <Label htmlFor="notes">Observações adicionais</Label>
                <Textarea
                  id="notes"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="Descreva detalhes adicionais sobre a desqualificação..."
                  rows={4}
                />
              </div>

              {/* Conversation Link */}
              <div className="space-y-2">
                <Label htmlFor="conversation-link">Link da conversa (opcional)</Label>
                <Input
                  id="conversation-link"
                  type="url"
                  value={conversationLink}
                  onChange={(e) => setConversationLink(e.target.value)}
                  placeholder="https://..."
                />
              </div>

              {/* Evidence Upload */}
              <div className="space-y-2">
                <Label htmlFor="evidence">Upload de evidência (opcional)</Label>
                <div className="border-2 border-dashed border-muted-foreground/25 rounded-lg p-6">
                  <div className="text-center">
                    <Upload className="h-8 w-8 mx-auto mb-4 text-muted-foreground" />
                    <div className="space-y-2">
                      <Label
                        htmlFor="evidence"
                        className="cursor-pointer text-sm font-medium text-primary hover:underline"
                      >
                        Clique para fazer upload
                      </Label>
                      <Input
                        id="evidence"
                        type="file"
                        onChange={handleFileChange}
                        accept="image/*,.pdf"
                        className="hidden"
                      />
                      <p className="text-xs text-muted-foreground">
                        Imagens ou PDF, máximo 10MB
                      </p>
                    </div>
                  </div>
                  {evidenceFile && (
                    <Alert className="mt-4">
                      <AlertDescription>
                        Arquivo selecionado: {evidenceFile.name}
                      </AlertDescription>
                    </Alert>
                  )}
                </div>
              </div>

              {/* Submit Button */}
              <Button
                type="submit"
                className="w-full"
                disabled={submitting}
              >
                {submitting ? (
                  <>
                    <div className="animate-spin h-4 w-4 mr-2 border-2 border-current border-t-transparent rounded-full" />
                    Enviando...
                  </>
                ) : (
                  <>
                    <Send className="h-4 w-4 mr-2" />
                    Enviar Report
                  </>
                )}
              </Button>
            </form>
          </CardContent>
        </Card>

        {/* Footer */}
        <div className="text-center mt-8 text-sm text-muted-foreground">
          <p>Este report será enviado diretamente para nossa equipe de análise.</p>
        </div>
      </div>
    </div>
  );
}

import React, { useCallback, useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { DragDropContext, DropResult } from "react-beautiful-dnd";
import { supabase } from "@/integrations/supabase/client";
import { DashboardLayout } from "@/components/dashboard/DashboardLayout";
import { CommandCenterHeader } from "@/components/command-center/CommandCenterHeader";
import { SquadSelector } from "@/components/command-center/SquadSelector";
import { BacklogColumn } from "@/components/command-center/BacklogColumn";
import { WorkloadTimeline } from "@/components/command-center/WorkloadTimeline";
import { TaskDialog } from "@/components/tasks/TaskDialog";
import { useCommandCenter, SquadMember, CommandCenterTask } from "@/hooks/useCommandCenter";
import { useWorkSchedules } from "@/hooks/useWorkSchedules";
import { useBacklogCommandCenter } from "@/hooks/useBacklogCommandCenter";
import { useCompany } from "@/contexts/CompanyContext";
import { BacklogHeader } from "@/components/backlog-center/BacklogHeader";
import { BacklogClientSidebar } from "@/components/backlog-center/BacklogClientSidebar";
import { BacklogBucket } from "@/components/backlog-center/BacklogBucket";
import { BacklogFooterBar } from "@/components/backlog-center/BacklogFooterBar";
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/components/ui/resizable";
import { Radar, Loader2, Inbox } from "lucide-react";
import { ErrorBoundary } from "@/components/ui/error-boundary";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

const START_HOUR = 0;
const TOTAL_MINUTES = 1440; // 24 hours

export default function SquadCommandCenter() {
  const {
    teams,
    teamsLoading,
    selectedTeamId,
    setSelectedTeamId,
    selectedTeam,
    backlogTasks,
    timelineTasks,
    setTimelineTasks,
    loading,
    assignTask,
    unassignTask,
    returnToBacklogCenter,
    getAgingHours,
    getTodayMetrics,
    fetchTasks,
    viewDate,
    setViewDate,
  } = useCommandCenter();

  const navigate = useNavigate();
  const { schedules: workSchedules } = useWorkSchedules();
  const { toast } = useToast();
  const [editingTask, setEditingTask] = useState<CommandCenterTask | null>(null);
  const [taskDialogOpen, setTaskDialogOpen] = useState(false);
  const [activeView, setActiveView] = useState<'timeline' | 'backlog'>('timeline');
  const [overflowDialog, setOverflowDialog] = React.useState<{
    taskId: string;
    memberId: string;
    memberName: string;
    startDate: Date;
  } | null>(null);
  const [draggingTask, setDraggingTask] = useState<CommandCenterTask | null>(null);
  const dropSlotRef = useRef<number | null>(null);
  const timelineContainerRef = useRef<HTMLDivElement | null>(null);
  const lastMousePosRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const dragMouseListenerRef = useRef<((e: MouseEvent) => void) | null>(null);

  // Backlog center hooks
  const { activeCompany } = useCompany();
  const backlogCenter = useBacklogCommandCenter();
  const [releasing, setReleasing] = useState(false);

  // Sync squad filter: command center → backlog
  useEffect(() => {
    if (selectedTeamId && selectedTeamId !== backlogCenter.selectedSquadId) {
      backlogCenter.setSelectedSquadId(selectedTeamId);
    }
  }, [selectedTeamId]);

  // Unified squad change handler
  const handleSquadChange = useCallback((id: string) => {
    setSelectedTeamId(id);
    backlogCenter.setSelectedSquadId(id);
  }, [setSelectedTeamId, backlogCenter]);

  const handleRelease = async () => {
    if (backlogCenter.selectedTaskIds.size === 0) return;
    setReleasing(true);
    try {
      await backlogCenter.releaseToLeaders(Array.from(backlogCenter.selectedTaskIds));
    } finally {
      setReleasing(false);
    }
  };

  const handleDeleteSelected = async () => {
    const ids = Array.from(backlogCenter.selectedTaskIds);
    const { error } = await supabase.from('tasks').delete().in('id', ids);
    if (error) {
      toast({ title: "Erro ao excluir tarefas", variant: "destructive" });
    } else {
      toast({ title: `${ids.length} tarefa${ids.length > 1 ? 's' : ''} excluída${ids.length > 1 ? 's' : ''}` });
      backlogCenter.clearSelection();
      window.location.reload();
    }
  };

  const members: SquadMember[] = (selectedTeam?.members || []).map(m => ({
    ...m,
    discord_user_id: null,
  }));

  const findNextFreeSlot = useCallback((userId: string): Date => {
    const memberTasks = timelineTasks.filter(t => t.assigned_user_id === userId);
    const today = new Date();
    today.setHours(START_HOUR, 0, 0, 0);

    if (memberTasks.length === 0) return today;

    // Find latest task end
    let latestEnd = today.getTime();
    memberTasks.forEach(task => {
      if (!task.start_date) return;
      const start = new Date(task.start_date).getTime();
      const duration = (task.ai_estimated_minutes || 20) * 60000;
      const end = start + duration;
      if (end > latestEnd) latestEnd = end;
    });

    return new Date(latestEnd);
  }, [timelineTasks]);

  const handleDragStart = useCallback((start: unknown) => {
    const task = backlogTasks.find(t => t.id === start.draggableId);
    setDraggingTask(task || null);
    dropSlotRef.current = null;

    // Track mouse position directly in the parent to avoid React re-render timing issues
    const onMove = (e: MouseEvent) => {
      lastMousePosRef.current = { x: e.clientX, y: e.clientY };
    };
    window.addEventListener('mousemove', onMove);
    dragMouseListenerRef.current = onMove;
  }, [backlogTasks]);

  const handleDragEnd = useCallback(async (result: DropResult) => {
    // Clean up mouse tracking listener
    if (dragMouseListenerRef.current) {
      window.removeEventListener('mousemove', dragMouseListenerRef.current);
      dragMouseListenerRef.current = null;
    }

    setDraggingTask(null);
    dropSlotRef.current = null;
    const { source, destination, draggableId } = result;
    if (!destination) return;
    if (source.droppableId === destination.droppableId) return;

    // Only handle drops from backlog to timeline
    if (!source.droppableId.startsWith("backlog")) return;
    if (!destination.droppableId.startsWith("timeline-")) return;

    const memberId = destination.droppableId.replace("timeline-", "");
    const member = members.find(m => m.id === memberId);
    if (!member) return;

    const task = backlogTasks.find(t => t.id === draggableId);
    if (!task) return;

    // Compute drop slot from tracked mouse position + DOM attributes (avoids React timing issues and localStorage/DB mismatch)
    let startDate: Date | null = null;
    const container = document.querySelector('[data-timeline-scroll]') as HTMLElement | null;
    if (container) {
      const rect = container.getBoundingClientRect();
      const scrollLeft = container.scrollLeft;
      const currentSlotWidth = Number(container.getAttribute('data-slot-width')) || 56;
      const currentSlotDuration = Number(container.getAttribute('data-slot-duration')) || 20;
      const currentStartHour = Number(container.getAttribute('data-start-hour')) || 0;
      const mouseX = lastMousePosRef.current.x - rect.left + scrollLeft - 192; // 192 = w-48 member column

      if (mouseX >= 0) {
        const slot = Math.max(0, Math.floor(mouseX / currentSlotWidth));
        const minutesFromDayStart = currentStartHour * 60 + slot * currentSlotDuration;
        startDate = new Date(viewDate);
        startDate.setHours(0, 0, 0, 0);
        startDate.setMinutes(minutesFromDayStart);
      }
    }

    // Fallback to next free slot if we couldn't determine position
    if (!startDate) {
      startDate = findNextFreeSlot(member.user_id);
    }

    try {
      await assignTask(draggableId, member.user_id, member.name, startDate);

    } catch {
      toast({ title: "Erro ao atribuir", variant: "destructive" });
    }
  }, [backlogTasks, members, findNextFreeSlot, assignTask, toast, viewDate]);

  const handleOverflowConfirm = async () => {
    if (!overflowDialog) return;
    try {
      const task = backlogTasks.find(t => t.id === overflowDialog.taskId);
      const member = members.find(m => m.id === overflowDialog.memberId);
      await assignTask(overflowDialog.taskId, member?.user_id || overflowDialog.memberId, overflowDialog.memberName, overflowDialog.startDate);


    } catch {
      toast({ title: "Erro ao atribuir", variant: "destructive" });
    }
    setOverflowDialog(null);
  };

  const handleRepositionTask = useCallback(async (taskId: string, newStartDate: Date) => {
    try {
      const task = timelineTasks.find(t => t.id === taskId);
      const estimatedMinutes = task?.ai_estimated_minutes || 20;
      const newDeadline = new Date(newStartDate.getTime() + estimatedMinutes * 60000);

      // Optimistic update
      setTimelineTasks(prev => prev.map(t => t.id === taskId ? {
        ...t,
        start_date: newStartDate.toISOString(),
        deadline: newDeadline.toISOString().split('T')[0],
      } : t));

      const { error } = await supabase
        .from("tasks")
        .update({
          start_date: newStartDate.toISOString(),
          deadline: newDeadline.toISOString().split('T')[0],
          due_date: newDeadline.toISOString(),
        })
        .eq("id", taskId);
      if (error) {
        // Rollback
        if (task) setTimelineTasks(prev => prev.map(t => t.id === taskId ? task : t));
        throw error;
      }

    } catch {
      toast({ title: "Erro ao mover tarefa", variant: "destructive" });
    }
  }, [toast, timelineTasks, setTimelineTasks]);

  const handleResizeTask = useCallback(async (taskId: string, newStartDate: Date, newEstimatedMinutes: number) => {
    try {
      const task = timelineTasks.find(t => t.id === taskId);
      const newDeadline = new Date(newStartDate.getTime() + newEstimatedMinutes * 60000);

      // Optimistic update
      setTimelineTasks(prev => prev.map(t => t.id === taskId ? {
        ...t,
        start_date: newStartDate.toISOString(),
        deadline: newDeadline.toISOString().split('T')[0],
        ai_estimated_minutes: newEstimatedMinutes,
      } : t));

      const { error } = await supabase
        .from("tasks")
        .update({
          start_date: newStartDate.toISOString(),
          deadline: newDeadline.toISOString().split('T')[0],
          due_date: newDeadline.toISOString(),
          ai_estimated_minutes: newEstimatedMinutes,
        })
        .eq("id", taskId);
      if (error) {
        if (task) setTimelineTasks(prev => prev.map(t => t.id === taskId ? task : t));
        throw error;
      }

    } catch {
      toast({ title: "Erro ao redimensionar", variant: "destructive" });
    }
  }, [toast, timelineTasks, setTimelineTasks]);

  const handleSendToBacklog = useCallback(async (taskId: string) => {
    const task = timelineTasks.find(t => t.id === taskId);
    try {
      await unassignTask(taskId);

    } catch {
      toast({ title: "Erro ao devolver ao backlog", variant: "destructive" });
    }
  }, [unassignTask, toast, timelineTasks]);

  const handleReturnToBacklogCenter = useCallback(async (taskId: string) => {
    try {
      await returnToBacklogCenter(taskId);
      toast({ title: "Tarefa devolvida ao Backlog Center" });
    } catch {
      toast({ title: "Erro ao devolver ao Backlog Center", variant: "destructive" });
    }
  }, [returnToBacklogCenter, toast]);

  const handleSendToNextDay = useCallback(async (taskId: string) => {
    const task = timelineTasks.find(t => t.id === taskId);
    if (!task || !task.start_date) return;
    try {
      const currentStart = new Date(task.start_date);
      const nextDay = new Date(currentStart);
      nextDay.setDate(nextDay.getDate() + 1);
      // Skip weekends
      while (nextDay.getDay() === 0 || nextDay.getDay() === 6) {
        nextDay.setDate(nextDay.getDate() + 1);
      }
      // Keep same time of day
      const estimatedMinutes = task.ai_estimated_minutes || 20;
      const newDeadline = new Date(nextDay.getTime() + estimatedMinutes * 60000);

      // Optimistic update - remove from current view
      setTimelineTasks(prev => prev.filter(t => t.id !== taskId));

      const { error } = await supabase
        .from("tasks")
        .update({
          start_date: nextDay.toISOString(),
          deadline: newDeadline.toISOString().split('T')[0],
          due_date: newDeadline.toISOString(),
        })
        .eq("id", taskId);
      if (error) {
        if (task) setTimelineTasks(prev => [...prev, task]);
        throw error;
      }
    } catch {
      toast({ title: "Erro ao mover tarefa", variant: "destructive" });
    }
  }, [timelineTasks, setTimelineTasks, toast]);

  const handleReassignTask = useCallback(async (taskId: string, newUserId: string, newMemberName: string, newStartDate: Date) => {
    const task = timelineTasks.find(t => t.id === taskId);
    try {
      const estimatedMinutes = task?.ai_estimated_minutes || 20;
      const deadlineDate = new Date(newStartDate.getTime() + estimatedMinutes * 60000);

      // Optimistic update
      setTimelineTasks(prev => prev.map(t => t.id === taskId ? {
        ...t,
        assigned_user_id: newUserId,
        responsible_name: newMemberName,
        start_date: newStartDate.toISOString(),
        deadline: deadlineDate.toISOString().split('T')[0],
      } : t));

      const { error } = await supabase
        .from("tasks")
        .update({
          assigned_user_id: newUserId,
          responsible_name: newMemberName,
          start_date: newStartDate.toISOString(),
          deadline: deadlineDate.toISOString().split('T')[0],
          due_date: deadlineDate.toISOString(),
        })
        .eq("id", taskId);
      if (error) {
        if (task) setTimelineTasks(prev => prev.map(t => t.id === taskId ? task : t));
        throw error;
      }

    } catch {
      toast({ title: "Erro ao reatribuir tarefa", variant: "destructive" });
    }
  }, [toast, timelineTasks, setTimelineTasks]);

  const metrics = getTodayMetrics();

  // Calculate time-based availability
  const timeAvailability = React.useMemo(() => {
    const toMin = (t: string) => {
      const [h, m] = (t || "00:00").substring(0, 5).split(":").map(Number);
      return h * 60 + m;
    };

    let totalCapacityMin = 0;
    let totalAllocatedMin = 0;

    members.forEach(member => {
      const schedule = workSchedules.find(ws => ws.id === member.work_schedule_id);
      let memberCapacity = 0;
      if (schedule) {
        const workMin = toMin(schedule.work_end) - toMin(schedule.work_start);
        const lunchMin = toMin(schedule.lunch_end) - toMin(schedule.lunch_start);
        memberCapacity = Math.max(0, workMin - lunchMin);
      } else {
        memberCapacity = 480; // default 8h
      }
      totalCapacityMin += memberCapacity;

      const memberTasks = timelineTasks.filter(t => t.assigned_user_id === member.user_id);
      const allocated = memberTasks.reduce((sum, t) => sum + (t.ai_estimated_minutes || 20), 0);
      totalAllocatedMin += allocated;
    });

    const freeMin = Math.max(0, totalCapacityMin - totalAllocatedMin);
    const freePercent = totalCapacityMin > 0 ? Math.round((freeMin / totalCapacityMin) * 100) : 0;
    const freeHours = Math.floor(freeMin / 60);
    const freeMinRemainder = freeMin % 60;
    const totalHours = Math.floor(totalCapacityMin / 60);

    return { totalCapacityMin, totalAllocatedMin, freeMin, freePercent, freeHours, freeMinRemainder, totalHours };
  }, [members, timelineTasks, workSchedules]);

  return (
    <DashboardLayout>
      <div className="flex flex-col h-[calc(100vh-130px)] overflow-hidden">
        {/* Top bar */}
        <div className="flex items-center justify-between flex-shrink-0 pb-4">
          <div className="flex items-center gap-3">
            {activeView === 'backlog' ? <Inbox className="w-6 h-6 text-primary" /> : <Radar className="w-6 h-6 text-primary" />}
            <h1 className="text-xl font-bold text-foreground tracking-tight">{activeView === 'backlog' ? 'Backlog' : 'Command Center'}</h1>
          </div>
          <div className="flex items-center gap-3">
            <Button
              variant="outline"
              size="sm"
              onClick={() => navigate('/backlog-command-center')}
              className="gap-2"
            >
              <Inbox className="w-4 h-4" />
              Backlog Center
            </Button>
            <Button
              variant={activeView === 'backlog' ? 'default' : 'outline'}
              size="sm"
              onClick={() => {
                const newView = activeView === 'backlog' ? 'timeline' : 'backlog';
                setActiveView(newView);
                if (newView === 'timeline') fetchTasks();
              }}
              className="gap-2"
            >
              <Inbox className="w-4 h-4" />
              {activeView === 'backlog' ? 'Voltar à Timeline' : 'Backlog'}
            </Button>
            <SquadSelector
              teams={teams}
              selectedTeamId={selectedTeamId}
              onSelect={handleSquadChange}
              loading={teamsLoading}
            />
          </div>
        </div>

        {loading || teamsLoading ? (
          <div className="flex items-center justify-center py-32">
            <Loader2 className="w-8 h-8 text-primary animate-spin" />
          </div>
        ) : activeView === 'backlog' ? (
          <>
            <div className="flex-shrink-0">
              <BacklogHeader
                totalStats={backlogCenter.totalStats}
                squads={backlogCenter.squads}
                selectedSquadId={selectedTeamId}
                onSquadChange={handleSquadChange}
              />
            </div>
            <ResizablePanelGroup direction="horizontal" autoSaveId="backlog-panels" className="flex flex-1 min-h-0">
              <ResizablePanel defaultSize={25} minSize={15} maxSize={40}>
                <BacklogClientSidebar
                  clients={backlogCenter.backlogClients}
                  selectedClientId={backlogCenter.selectedClientId}
                  onSelectClient={backlogCenter.setSelectedClientId}
                  totalStats={backlogCenter.totalStats}
                />
              </ResizablePanel>
              <ResizableHandle withHandle />
              <ResizablePanel defaultSize={75}>
                <BacklogBucket
                  tasks={backlogCenter.filteredTasks}
                  loading={backlogCenter.tasksLoading}
                  selectedTaskIds={backlogCenter.selectedTaskIds}
                  onToggleTask={backlogCenter.toggleTaskSelection}
                  getReadiness={backlogCenter.getReadiness}
                  getAgingHours={backlogCenter.getAgingHours}
                  clients={backlogCenter.clients}
                  taskToClients={backlogCenter.taskToClients}
                  companyId={activeCompany?.company_id}
                  selectedSquadId={backlogCenter.selectedSquadId}
                  subtasksByParent={backlogCenter.subtasksByParent}
                  selectionBar={
                    <BacklogFooterBar
                      selectionStats={backlogCenter.selectionStats}
                      onRelease={handleRelease}
                      onClear={backlogCenter.clearSelection}
                      onSelectAll={backlogCenter.selectAll}
                      onDeleteSelected={handleDeleteSelected}
                      releasing={releasing}
                    />
                  }
                />
              </ResizablePanel>
            </ResizablePanelGroup>
          </>
        ) : (
          <ErrorBoundary fallbackMessage="Erro no Command Center. Tente novamente.">
          <DragDropContext onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
            {/* Header metrics */}
            <div className="my-4 flex-shrink-0">
              <CommandCenterHeader metrics={metrics} teamName={selectedTeam?.name || "—"} timeAvailability={timeAvailability} />
            </div>

            {/* Main layout: Backlog + Timeline */}
            <ResizablePanelGroup direction="horizontal" autoSaveId="command-center-panels" className="flex gap-0 flex-1 min-h-0">
              <ResizablePanel defaultSize={20} minSize={12} maxSize={35}>
                <div className="bg-card border border-border overflow-hidden flex flex-col h-full">
                  <BacklogColumn
                    tasks={backlogTasks}
                    getAgingHours={getAgingHours}
                    teamColor={selectedTeam?.color}
                    onClickTask={(task) => { setEditingTask(task); setTaskDialogOpen(true); }}
                  />
                </div>
              </ResizablePanel>
              <ResizableHandle withHandle />
              <ResizablePanel defaultSize={80}>
                <div className="flex-1 min-w-0 overflow-auto flex flex-col h-full">
                  <WorkloadTimeline
                    members={members}
                    tasks={timelineTasks}
                    startHour={START_HOUR}
                    workSchedules={workSchedules}
                    onRepositionTask={handleRepositionTask}
                    onResizeTask={handleResizeTask}
                    onClickTask={(task) => { setEditingTask(task); setTaskDialogOpen(true); }}
                    onSendToBacklog={handleSendToBacklog}
                    onReturnToBacklogCenter={handleReturnToBacklogCenter}
                    onSendToNextDay={handleSendToNextDay}
                    onReassignTask={handleReassignTask}
                    draggingTask={draggingTask}
                    dropSlotRef={dropSlotRef}
                    selectedDate={viewDate}
                    onDateChange={setViewDate}
                  />
                </div>
              </ResizablePanel>
            </ResizablePanelGroup>
          </DragDropContext>
          </ErrorBoundary>
        )}

        {/* Overflow dialog */}
        <AlertDialog open={!!overflowDialog} onOpenChange={() => setOverflowDialog(null)}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Cuidado: Overflow de horário</AlertDialogTitle>
              <AlertDialogDescription>
                Esta tarefa empurrará o cronograma para além das 6h do dia de {overflowDialog?.memberName}. Deseja confirmar?
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>
                Cancelar
              </AlertDialogCancel>
              <AlertDialogAction onClick={handleOverflowConfirm}>
                Confirmar
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>

      <TaskDialog
        open={taskDialogOpen}
        onOpenChange={(open) => {
          if (!open) {
            setTaskDialogOpen(false);
            // Delay clearing task to avoid rendering dialog content with null task
            setTimeout(() => setEditingTask(null), 100);
          }
        }}
        task={editingTask}
        onSave={async (taskData) => {
          if (!editingTask) return;
          const taskId = editingTask.id;
          // Close dialog first, then update data
          setTaskDialogOpen(false);
          setTimeout(() => setEditingTask(null), 100);
          try {
            await supabase.from("tasks").update(taskData).eq("id", taskId);
            await fetchTasks();
            toast({ title: "Tarefa atualizada" });
          } catch {
            toast({ title: "Erro ao atualizar", variant: "destructive" });
          }
        }}
      />
    </DashboardLayout>
  );
}

