        )}
        {isOverdue && (
          <div className="flex items-center gap-1 rounded bg-red-900/40 border border-red-500/30 px-1.5 py-0.5 shrink-0">
            <AlertTriangle className="w-2.5 h-2.5 text-red-400 shrink-0" />
            <span className="text-[10px] text-red-300">Vencido</span>
          </div>
        )}
      </div>
    </div>
  );
}

// ---- Rank icon ----
function RankIcon({ pos }: { pos: number }) {
  if (pos === 0) return <Trophy className="w-5 h-5 text-yellow-400" />;
  if (pos === 1) return <Medal className="w-5 h-5 text-gray-300" />;
  if (pos === 2) return <Award className="w-5 h-5 text-amber-600" />;
  return <span className="w-5 h-5 flex items-center justify-center text-xs font-bold text-gray-500">#{pos + 1}</span>;
}

// ---- Ranking row ----
function RankingRow({ collab, pos, metric }: {
  collab: CollaboratorRanking; pos: number;
  metric: 'score' | 'regularity' | 'efficiency';
}) {
  const val = collab[metric];
  const color = val >= 70 ? 'bg-emerald-500' : val >= 40 ? 'bg-yellow-500' : 'bg-red-500';

  return (
    <div className="flex items-center gap-3 py-2.5 border-b border-white/5 last:border-0">
      <RankIcon pos={pos} />
      {collab.user_avatar ? (
        <img src={collab.user_avatar} alt={collab.user_name}
          className="w-8 h-8 rounded-full object-cover shrink-0" />
      ) : (
        <div className="w-8 h-8 rounded-full bg-gray-700 flex items-center justify-center shrink-0">
          <span className="text-xs font-bold text-gray-300">{collab.user_name.charAt(0)}</span>
        </div>
      )}
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold text-white truncate">{collab.user_name}</p>
        <div className="flex gap-3 text-xs text-gray-500 mt-0.5">
          <span>R: {collab.regularity}%</span>
          <span>Q: {collab.quality}%</span>
          <span>E: {collab.efficiency}%</span>
        </div>
      </div>
      <div className="text-right shrink-0">
        <span className="text-lg font-black text-white tabular-nums">{val}%</span>
        <div className="w-20 h-1.5 rounded-full bg-white/10 mt-1 overflow-hidden">
          <div className={`h-full rounded-full ${color} transition-all duration-700`} style={{ width: `${val}%` }} />
        </div>
      </div>
    </div>
  );
}

// ---- Main Dashboard ----
export default function TaskTvDashboard() {
  const [refreshInterval, setRefreshInterval] = useState(() => {
    const saved = localStorage.getItem('task-tv-refresh-interval');
    return saved ? parseInt(saved) : 30_000;
  });
  const [zoom, setZoom] = useState(() => {
    const saved = localStorage.getItem('task-tv-zoom');
    return saved ? parseInt(saved) : 100;
  });
  const [rotation, setRotation] = useState(() => {
    const saved = localStorage.getItem('task-tv-rotation');
    return saved ? parseInt(saved) : 0;
  });

  const handleZoomChange = (v: number) => { setZoom(v); localStorage.setItem('task-tv-zoom', v.toString()); };
  const handleRotationChange = (v: number) => { setRotation(v); localStorage.setItem('task-tv-rotation', v.toString()); };
  const handleRefreshIntervalChange = (v: number) => { setRefreshInterval(v); localStorage.setItem('task-tv-refresh-interval', v.toString()); };

  const { data, isLoading, isFetching, refetch } = useTaskTvDashboard(refreshInterval);
  const { activeCompany } = useCompany();

  const [listModal, setListModal] = useState<ModalKind>(null);
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);

  // --- Alert states ---
  const [celebrationTask, setCelebrationTask] = useState<TaskItem | null>(null);
  const [criticalAlert, setCriticalAlert] = useState<TaskItem | null>(null);
  const prevCompletedIdsRef = useRef<Set<string>>(new Set());
  const prevOverdueIdsRef = useRef<Set<string>>(new Set());
  // Track whether first load has happened (to avoid alerts on initial render)
  const completedInitializedRef = useRef(false);
  const overdueInitializedRef = useRef(false);

  // Detect new high-priority completions
  useEffect(() => {
    if (!data) return;
    const currentIds = new Set(data.completedTodayList.map(t => t.id));

    if (!completedInitializedRef.current) {
      // First load — just seed the ref, no alert
      prevCompletedIdsRef.current = currentIds;
      completedInitializedRef.current = true;
      return;
    }

    const newHighPriority = data.completedTodayList.filter(
      t => !prevCompletedIdsRef.current.has(t.id) && ['high', 'alta'].includes(t.priority?.toLowerCase() ?? '')
    );
    if (newHighPriority.length > 0) {
      setCelebrationTask(newHighPriority[0]);
    }
    prevCompletedIdsRef.current = currentIds;
  }, [data?.completedTodayList]);

  // Detect new high-priority overdues
  useEffect(() => {
    if (!data) return;
    const currentIds = new Set(data.overdueTasksList.map(t => t.id));

    if (!overdueInitializedRef.current) {
      // First load — just seed the ref, no alert
      prevOverdueIdsRef.current = currentIds;
      overdueInitializedRef.current = true;
      return;
    }

    const newOverdue = data.overdueTasksList.filter(
      t => !prevOverdueIdsRef.current.has(t.id) && ['high', 'alta'].includes(t.priority?.toLowerCase() ?? '')
    );
    if (newOverdue.length > 0 && !criticalAlert) {
      setCriticalAlert(newOverdue[0]);
    }
    prevOverdueIdsRef.current = currentIds;
  }, [data?.overdueTasksList, criticalAlert]);

  function openTask(id: string) {
    setListModal(null);
    setEditingTaskId(id);
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <RefreshCw className="w-12 h-12 animate-spin text-emerald-400" />
          <p className="text-gray-400 text-lg">Carregando dashboard...</p>
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center">
        <p className="text-gray-400">Erro ao carregar dados.</p>
      </div>
    );
  }

  const topPerformers = [...data.rankings].sort((a, b) => b.score      - a.score     ).slice(0, 5);
  const topRegularity = [...data.rankings].sort((a, b) => b.regularity - a.regularity).slice(0, 5);
  const topEfficiency = [...data.rankings].sort((a, b) => b.efficiency - a.efficiency).slice(0, 5);

  const listTasks: TaskItem[] =
    listModal === 'open'      ? data.openTasksList :
    listModal === 'overdue'   ? data.overdueTasksList :
    listModal === 'completed' ? data.completedTodayList :
    listModal === 'review'    ? data.reviewTasksList : [];

  const allTasksForEdit = [
    ...data.openTasksList, ...data.overdueTasksList,
    ...data.completedTodayList, ...data.reviewTasksList,
  ];
  const editingTask = editingTaskId ? allTasksForEdit.find(t => t.id === editingTaskId) : null;

  const isRotated = rotation === 90 || rotation === 270;

  return (
    <div
      className="min-h-screen bg-gray-950 overflow-hidden"
      style={{
        transform: `rotate(${rotation}deg)`,
        transformOrigin: rotation === 90 ? 'top left' : rotation === 270 ? 'bottom right' : 'center',
        width: isRotated ? '100vh' : '100%',
        height: isRotated ? '100vw' : '100%',
        position: isRotated ? 'absolute' : 'relative',
        top: rotation === 90 ? 0 : rotation === 270 ? 'auto' : undefined,
        left: rotation === 90 ? '100vw' : undefined,
        bottom: rotation === 270 ? '100vh' : undefined,
        right: rotation === 270 ? 0 : undefined,
      }}
    >
      {/* Celebration Overlay */}
      {celebrationTask && (
        <CelebrationOverlay task={celebrationTask} onDismiss={() => setCelebrationTask(null)} />
      )}

      {/* Critical Alert Banner */}
      {criticalAlert && (
        <CriticalAlertBanner task={criticalAlert} onDismiss={() => setCriticalAlert(null)} />
      )}

      <TooltipProvider>
        <div
          className="text-white p-6 flex flex-col gap-5 origin-top-left"
          style={{
            transform: `scale(${zoom / 100})`,
            width: `${10000 / zoom}%`,
            fontFamily: 'system-ui, sans-serif',
          }}
        >
          {/* ---- HEADER ---- */}
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-black tracking-tight text-white">
                {activeCompany?.company?.name || 'Dashboard de Tarefas'}
              </h1>
              <p className="text-xs text-gray-500 mt-0.5 uppercase tracking-widest">Painel de Operações em Tempo Real</p>
            </div>
            <div className="flex items-center gap-6">
              <div className="flex items-center gap-2 text-xs">
                {isFetching
                  ? <><RefreshCw className="w-3.5 h-3.5 animate-spin text-emerald-400" /><span className="text-emerald-400">Atualizando...</span></>
                  : <><Wifi className="w-3.5 h-3.5 text-emerald-400" /><span className="text-gray-400">Ao vivo</span></>
                }
              </div>
              <LiveClock />
            </div>
          </div>

          {/* ---- KPI ROW — 6 cards ---- */}
          <div className="grid grid-cols-6 gap-4">
            <KpiCard label="Em Aberto" value={data.openTasks} icon={Clock} color="text-gray-300"
              sublabel="Clique para ver a lista" onClick={() => setListModal('open')} />
            <KpiCard label="Em Atraso" value={data.overdueTasks} icon={AlertTriangle} color="text-red-400"
              sublabel="Clique para ver a lista" onClick={() => setListModal('overdue')} />
            <KpiCard label="Concluídas Hoje" value={data.completedToday} icon={CheckCircle2} color="text-emerald-400"
              sublabel={`Clique para ver — ${format(new Date(), 'dd/MM')}`} onClick={() => setListModal('completed')} />
            <KpiCard label="Em Revisão" value={data.reviewTasks} icon={ClipboardCheck} color="text-yellow-400"
              sublabel="Aguardando aprovação" onClick={() => setListModal('review')} />
            <KpiCard label="Executando Agora" value={data.executingNow} icon={Zap} color="text-emerald-400"
              sublabel="Sessões ativas" />
            <KpiCard
              label="Horas Rastreadas (7d)"
              value={`${data.hoursTrackedLast7Days}h`}
              icon={Timer}
              color="text-gray-300"
              sublabel={`Média ${data.avgHoursPerCollaborator}h/colaborador`}
            />
          </div>

          {/* ---- INDICATORS ---- */}
          <div className="grid grid-cols-3 gap-4">
            <IndicatorBar label="Regularidade" value={data.regularity} color="text-gray-300"
              description="Mede tarefas abertas em relação às que estão dentro do prazo." />
            <IndicatorBar label="Qualidade" value={data.quality} color="text-emerald-400"
              description="Índice de eficiência das tarefas concluídas sem retrabalho." />
            <IndicatorBar label="Eficiência" value={data.efficiency} color="text-yellow-400"
              description="Combina regularidade e qualidade para medir eficiência geral." />
          </div>

          {/* ---- TREND CHARTS (diário + horário lado a lado) ---- */}
          {data.completionTrend.length > 0 && (
            <div className="grid grid-cols-2 gap-4">
              <CompletionTrendChart data={data.completionTrend} />
              <HourlyTrendChart data={data.hourlyTrend} />
            </div>
          )}

          {/* ---- EXECUTANDO AGORA — linha completa, só aparece se houver sessões ---- */}
          {data.activeSessions.length > 0 && (
            <div className="flex flex-col gap-3 rounded-xl border border-emerald-500/25 bg-emerald-500/5 p-4">
              <div className="flex items-center gap-2">
                <div className="w-2.5 h-2.5 rounded-full bg-emerald-400 animate-pulse" />
                <h2 className="text-sm font-bold uppercase tracking-wider text-emerald-300">
                  Executando Agora — {data.executingNow} sessão{data.executingNow !== 1 ? 'ões' : ''} ativa{data.executingNow !== 1 ? 's' : ''}
                </h2>
              </div>
              <div className="grid gap-3" style={{ gridTemplateColumns: `repeat(${Math.min(data.activeSessions.length, 4)}, minmax(0, 1fr))` }}>
                {data.activeSessions.map(s => (
                  <SessionCard key={s.session_id} session={s} onOpenTask={openTask} />
                ))}
              </div>
            </div>
          )}

          {/* ---- SQUADS + RANKINGS ---- */}
          <div className="grid grid-cols-12 gap-4">
            {/* Squad Ranking */}
            {data.squadRankings.length > 0 && (
              <div className="col-span-3 rounded-xl border border-white/10 bg-white/5 p-4 flex flex-col gap-1">
                <div className="flex items-center gap-2 mb-2">
                  <Users className="w-4 h-4 text-gray-400" />
                  <h3 className="text-xs font-bold uppercase tracking-wider text-gray-300">Performance por Squad</h3>
                </div>
                <div className="flex flex-col">
                  {data.squadRankings.slice(0, 6).map((sq, i) => (
                    <SquadRankCard key={sq.team_id} squad={sq} pos={i} />
                  ))}
                </div>
              </div>
            )}

            {/* Rankings */}
            <div className={cn(
              'grid grid-cols-3 gap-4',
              data.squadRankings.length > 0 ? 'col-span-9' : 'col-span-12'
            )}>
              {/* Top Performers */}
              <div className="rounded-xl border border-white/10 bg-white/5 p-4 flex flex-col gap-2">
                <div className="flex items-center gap-2 mb-1">
                  <Trophy className="w-4 h-4 text-yellow-400" />
                  <h3 className="text-xs font-bold uppercase tracking-wider text-gray-300">Top Performers</h3>
                </div>
                <p className="text-xs text-gray-500 mb-2">Score combinado da última semana</p>
                {topPerformers.length === 0
                  ? <p className="text-xs text-gray-600 text-center py-4">Sem dados suficientes</p>
                  : topPerformers.map((c, i) => <RankingRow key={c.user_id} collab={c} pos={i} metric="score" />)
                }
              </div>

              {/* Top Regularidade */}
              <div className="rounded-xl border border-white/10 bg-white/5 p-4 flex flex-col gap-2">
                <div className="flex items-center gap-2 mb-1">
                  <Star className="w-4 h-4 text-blue-400" />
                  <h3 className="text-xs font-bold uppercase tracking-wider text-gray-300">Top Regularidade</h3>
                </div>
                <p className="text-xs text-gray-500 mb-2">Tarefas entregues dentro do prazo</p>
                {topRegularity.length === 0
                  ? <p className="text-xs text-gray-600 text-center py-4">Sem dados suficientes</p>
                  : topRegularity.map((c, i) => <RankingRow key={c.user_id} collab={c} pos={i} metric="regularity" />)
                }
              </div>

              {/* Top Eficiência */}
              <div className="rounded-xl border border-white/10 bg-white/5 p-4 flex flex-col gap-2">
                <div className="flex items-center gap-2 mb-1">
                  <TrendingUp className="w-4 h-4 text-emerald-400" />
                  <h3 className="text-xs font-bold uppercase tracking-wider text-gray-300">Top Eficiência</h3>
                </div>
                <p className="text-xs text-gray-500 mb-2">Conclusão vs. em andamento</p>
                {topEfficiency.length === 0
                  ? <p className="text-xs text-gray-600 text-center py-4">Sem dados suficientes</p>
                  : topEfficiency.map((c, i) => <RankingRow key={c.user_id} collab={c} pos={i} metric="efficiency" />)
                }
              </div>
            </div>
          </div>

          {/* ---- FOOTER ---- */}
          <div className="flex items-center justify-between text-xs text-gray-600 border-t border-white/5 pt-3">
            <span>Atualização automática a cada {refreshInterval / 1000}s · Clique nos cards para ver detalhes</span>
            <button
              onClick={() => refetch()}
              className="flex items-center gap-1.5 text-gray-500 hover:text-gray-300 transition-colors"
            >
              <RefreshCw className="w-3 h-3" />
              Atualizar agora
            </button>
            <span>Última sync: {data.lastSync ? format(data.lastSync, 'HH:mm:ss') : '—'}</span>
          </div>

          {/* ---- MODALS ---- */}
          {listModal && (
            <TaskListModal
              kind={listModal}
              tasks={listTasks}
              onClose={() => setListModal(null)}
              onOpenTask={openTask}
            />
          )}

          {editingTaskId && (
            <Suspense fallback={null}>
              <TaskDialog
                open={!!editingTaskId}
                onOpenChange={open => { if (!open) setEditingTaskId(null); }}
                task={editingTask ? {
                  id: editingTask.id,
                  title: editingTask.title,
                  status: editingTask.status as unknown,
                  priority: editingTask.priority as unknown,
                  deadline: editingTask.deadline,
                  due_date: editingTask.due_date,
                  responsible_name: editingTask.responsible_name,
                  responsible_avatar: editingTask.responsible_avatar,
                  assigned_user_id: editingTask.assigned_user_id,
                  user_id: editingTask.user_id,
                } as unknown : undefined}
                onSave={() => { setEditingTaskId(null); refetch(); }}
                onDelete={() => { setEditingTaskId(null); refetch(); }}
              />
            </Suspense>
          )}
        </div>
      </TooltipProvider>

      {/* ---- SETTINGS CONTROLS ---- */}
      <RadarTVControls
        refreshInterval={refreshInterval}
        onRefreshIntervalChange={handleRefreshIntervalChange}
        onRefreshNow={() => refetch()}
        isRefreshing={isFetching}
        zoom={zoom}
        onZoomChange={handleZoomChange}
        rotation={rotation}
        onRotationChange={handleRotationChange}
      />
    </div>
  );
}

import { useState, useMemo, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useYouTubeChannels } from "@/hooks/useYouTubeChannels";
import { useYouTubeAnalytics } from "@/hooks/useYouTubeAnalytics";
import { useYouTubeSuggestions } from "@/hooks/useYouTubeSuggestions";
import { useYouTubeScripts } from "@/hooks/useYouTubeScripts";
import { useYouTubeThumbnails } from "@/hooks/useYouTubeThumbnails";
import { useYouTubeCategories } from "@/hooks/useYouTubeCategories";
import { YouTubeChannelManager } from "@/components/youtube-content-lab/YouTubeChannelManager";
import { YouTubeVideoAnalytics } from "@/components/youtube-content-lab/YouTubeVideoAnalytics";
import { YouTubeSuggestionsList } from "@/components/youtube-content-lab/YouTubeSuggestionsList";
import { YouTubeScriptsList } from "@/components/youtube-content-lab/YouTubeScriptsList";
import { YouTubeScriptBuilder } from "@/components/youtube-content-lab/YouTubeScriptBuilder";
import { YouTubeThumbnailConfig } from "@/components/youtube-content-lab/YouTubeThumbnailConfig";
import { YouTubeCategorySidebar } from "@/components/youtube-content-lab/YouTubeCategorySidebar";
import { YouTubeRefreshModal, ChannelRefreshStatus } from "@/components/youtube-content-lab/YouTubeRefreshModal";
import { YouTubeRefreshConfigModal } from "@/components/youtube-content-lab/YouTubeRefreshConfigModal";
import { Youtube, BarChart3, Lightbulb, FileText, Loader2, Image, ArrowLeft } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useQuery } from "@tanstack/react-query";

export default function YouTubeContentLabPage() {
  const { labId } = useParams<{ labId: string }>();
  const navigate = useNavigate();

  // Fetch lab details
  const { data: lab, isLoading: labLoading } = useQuery({
    queryKey: ['youtube-lab', labId],
    queryFn: async () => {
      if (!labId) return null;
      const { data, error } = await supabase
        .from('youtube_content_labs')
        .select('*, clients(name)')
        .eq('id', labId)
        .single();
      if (error) throw error;
      return data as unknown;
    },
    enabled: !!labId,
  });

  // Use the lab's client_id (if any) as a proxy for the existing hooks
  // The hooks still query by client_id + company_id, but we use the lab's context
  const clientId = lab?.client_id || labId || "";
  const companyId = lab?.company_id || "";

  const [activeTab, setActiveTab] = useState("channels");
  const [selectedScriptId, setSelectedScriptId] = useState<string | null>(null);
  const [selectedCategoryId, setSelectedCategoryId] = useState<string | null>(null);
  const [refreshConfigOpen, setRefreshConfigOpen] = useState(false);
  const [refreshModalOpen, setRefreshModalOpen] = useState(false);
  const [refreshStatuses, setRefreshStatuses] = useState<ChannelRefreshStatus[]>([]);
  const [refreshFinished, setRefreshFinished] = useState(false);

  // For now hooks still use clientId - they'll work for client-linked labs
  // For standalone labs, we pass labId as clientId (queries will return empty, which is correct for new labs)
  const channelsHook = useYouTubeChannels(clientId, companyId);
  const analyticsHook = useYouTubeAnalytics(clientId, companyId);
  const suggestionsHook = useYouTubeSuggestions(clientId, companyId);
  const scriptsHook = useYouTubeScripts(clientId, companyId);
  const thumbnailsHook = useYouTubeThumbnails(clientId, companyId);
  const categoriesHook = useYouTubeCategories(clientId, companyId);

  const categoryChannelIds = categoriesHook.getChannelIdsForCategory(selectedCategoryId);

  useEffect(() => {
    if (categoryChannelIds) {
      analyticsHook.setSelectedChannelIds(categoryChannelIds);
    } else {
      analyticsHook.setSelectedChannelIds([]);
    }
  }, [categoryChannelIds]);

  const filteredChannels = useMemo(() => {
    if (!categoryChannelIds) return channelsHook.channels;
    return channelsHook.channels.filter(ch => categoryChannelIds.includes(ch.id));
  }, [channelsHook.channels, categoryChannelIds]);

  const filteredSuggestions = useMemo(() => {
    if (!categoryChannelIds) return suggestionsHook.suggestions;
    return suggestionsHook.suggestions.filter((s: unknown) =>
      s.category_id === selectedCategoryId || !s.category_id
    );
  }, [suggestionsHook.suggestions, selectedCategoryId, categoryChannelIds]);

  const filteredScripts = useMemo(() => {
    if (!categoryChannelIds) return scriptsHook.scripts;
    return scriptsHook.scripts.filter((s: unknown) =>
      s.category_id === selectedCategoryId || !s.category_id
    );
  }, [scriptsHook.scripts, selectedCategoryId, categoryChannelIds]);

  if (labLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!lab) {
    return (
      <div className="text-center py-16 space-y-4">
        <h3 className="text-lg font-medium">Lab não encontrado</h3>
        <Button variant="outline" onClick={() => navigate('/youtube-content-lab')}>
          Voltar
        </Button>
      </div>
    );
  }

  const handleCreateScript = async (suggestionId: string, title: string) => {
    const script = await scriptsHook.generateScript(title, { suggestionId });
    if (script) {
      setSelectedScriptId(script.id);
      setActiveTab("scripts");
    }
  };

  const handleOpenScript = (scriptId: string) => {
    setSelectedScriptId(scriptId);
  };

  const handleCloseBuilder = () => {
    setSelectedScriptId(null);
  };

  if (selectedScriptId) {
    const script = scriptsHook.scripts.find(s => s.id === selectedScriptId);
    if (script) {
      return (
        <YouTubeScriptBuilder
          script={script}
          onClose={handleCloseBuilder}
          onUpdate={(updates) => scriptsHook.updateScript(selectedScriptId, updates)}
          onSendMessage={(message) => scriptsHook.sendChatMessage(selectedScriptId, message)}
          onGenerateTitles={(style) => scriptsHook.generateTitles(selectedScriptId, style)}
          fetchMessages={() => scriptsHook.fetchScriptMessages(selectedScriptId)}
          onGenerateThumbnail={thumbnailsHook.generateThumbnail}
          generatingThumbnail={thumbnailsHook.generating}
          thumbnailConfig={thumbnailsHook.config}
          clientId={clientId}
          companyId={companyId}
        />
      );
    }
  }

  const labName = lab.clients?.name || lab.name;

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3">
        <Button
          variant="ghost"
          size="icon"
          onClick={() => navigate('/youtube-content-lab')}
        >
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="p-2 bg-red-100 dark:bg-red-900/30 rounded-lg">
          <Youtube className="h-6 w-6 text-red-600 dark:text-red-400" />
        </div>
        <div>
          <h1 className="text-2xl font-bold">{labName}</h1>
          <p className="text-muted-foreground">
            {lab.client_id ? "Lab vinculado ao cliente" : "Lab standalone"} • Analise canais, identifique tendências e crie roteiros
          </p>
        </div>
      </div>

      <div className="flex border rounded-lg overflow-hidden min-h-[600px]">
        <YouTubeCategorySidebar
          categories={categoriesHook.categories}
          channels={channelsHook.channels}
          selectedCategoryId={selectedCategoryId}
          onSelectCategory={setSelectedCategoryId}
          onCreateCategory={categoriesHook.createCategory}
          onUpdateCategory={categoriesHook.updateCategory}
          onDeleteCategory={categoriesHook.deleteCategory}
          onLinkChannel={categoriesHook.linkChannel}
          onUnlinkChannel={categoriesHook.unlinkChannel}
        />

        <div className="flex-1 p-6">
          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="grid w-full grid-cols-5">
              <TabsTrigger value="channels" className="flex items-center gap-2">
                <Youtube className="h-4 w-4" />
                Canais
              </TabsTrigger>
              <TabsTrigger value="analytics" className="flex items-center gap-2">
                <BarChart3 className="h-4 w-4" />
                Análise
              </TabsTrigger>
              <TabsTrigger value="suggestions" className="flex items-center gap-2">
                <Lightbulb className="h-4 w-4" />
                Sugestões
              </TabsTrigger>
              <TabsTrigger value="scripts" className="flex items-center gap-2">
                <FileText className="h-4 w-4" />
                Roteiros
              </TabsTrigger>
              <TabsTrigger value="thumbnails" className="flex items-center gap-2">
                <Image className="h-4 w-4" />
                Thumbnails
              </TabsTrigger>
            </TabsList>

            <TabsContent value="channels" className="mt-6">
              <YouTubeChannelManager
                channels={filteredChannels}
                loading={channelsHook.loading}
                analyzing={channelsHook.analyzing}
                onAddChannel={channelsHook.addChannel}
                onRefreshChannel={channelsHook.refreshChannel}
                onRemoveChannel={channelsHook.removeChannel}
                categories={categoriesHook.categories}
                onLinkChannel={categoriesHook.linkChannel}
                onUnlinkChannel={categoriesHook.unlinkChannel}
              />
            </TabsContent>

            <TabsContent value="analytics" className="mt-6">
              <YouTubeVideoAnalytics
                videos={analyticsHook.videos}
                allVideos={analyticsHook.allVideos}
                loading={analyticsHook.loading}
                period={analyticsHook.period}
                onPeriodChange={analyticsHook.setPeriod}
                customDateRange={analyticsHook.customDateRange}
                onCustomDateChange={analyticsHook.setCustomDateRange}
                selectedChannelIds={categoryChannelIds || analyticsHook.selectedChannelIds}
                onChannelSelect={analyticsHook.setSelectedChannelIds}
                searchQuery={analyticsHook.searchQuery}
                onSearchChange={analyticsHook.setSearchQuery}
                sortBy={analyticsHook.sortBy}
                onSortChange={analyticsHook.setSortBy}
                metrics={analyticsHook.metrics}
                topByViews={analyticsHook.topByViews}
                topByEngagement={analyticsHook.topByEngagement}
                channels={filteredChannels}
                onCreateScript={(topic) => {
                  scriptsHook.generateScript(topic, { sourceVideoTitle: topic });
                  setActiveTab("scripts");
                }}
                onRefreshAnalysis={async () => {
                  setRefreshConfigOpen(true);
                }}
                refreshing={channelsHook.analyzing}
              />
            </TabsContent>

            <TabsContent value="suggestions" className="mt-6">
              <YouTubeSuggestionsList
                suggestions={filteredSuggestions}
                loading={suggestionsHook.loading}
                generating={suggestionsHook.generating}
                onGenerateSuggestions={suggestionsHook.generateSuggestions}
                onCreateScript={handleCreateScript}
                onDismiss={(id) => suggestionsHook.updateSuggestionStatus(id, 'dismissed')}
                hasChannels={filteredChannels.length > 0}
              />
            </TabsContent>

            <TabsContent value="scripts" className="mt-6">
              <YouTubeScriptsList
                scripts={filteredScripts}
                loading={scriptsHook.loading}
                generating={scriptsHook.generating}
                onOpenScript={handleOpenScript}
                onDeleteScript={scriptsHook.deleteScript}
                onCreateNew={() => {
                  scriptsHook.generateScript("Novo roteiro");
                }}
                onUpdateStatus={(scriptId, status) => scriptsHook.updateScript(scriptId, { status })}
              />
            </TabsContent>

            <TabsContent value="thumbnails" className="mt-6">
              <YouTubeThumbnailConfig
                clientId={clientId}
                companyId={companyId}
              />
            </TabsContent>
          </Tabs>
        </div>
      </div>
      <YouTubeRefreshConfigModal
        open={refreshConfigOpen}
        onOpenChange={setRefreshConfigOpen}
        channels={filteredChannels}
        onConfirm={async (selectedIds, periodDays) => {
          const channelsToRefresh = filteredChannels.filter((ch) => selectedIds.includes(ch.id));
          const statuses: ChannelRefreshStatus[] = channelsToRefresh.map((ch) => ({
            channelId: ch.id,
            channelName: ch.channel_name,
            status: "pending" as const,
          }));
          setRefreshStatuses(statuses);
          setRefreshFinished(false);
          setRefreshModalOpen(true);

          for (let i = 0; i < channelsToRefresh.length; i++) {
            const channel = channelsToRefresh[i];
            setRefreshStatuses((prev) =>
              prev.map((s, idx) =>
                idx === i ? { ...s, status: "loading" as const } : s
              )
            );

            try {
              const data = await channelsHook.refreshChannel(channel.id, periodDays);
              setRefreshStatuses((prev) =>
                prev.map((s, idx) =>
                  idx === i
                    ? { ...s, status: "success" as const, videoCount: data?.analyzedCount ?? 0 }
                    : s
                )
              );
            } catch {
              setRefreshStatuses((prev) =>
                prev.map((s, idx) =>
                  idx === i ? { ...s, status: "error" as const } : s
                )
              );
            }
          }

          await analyticsHook.refetch();
          setRefreshFinished(true);
        }}
      />
      <YouTubeRefreshModal
        open={refreshModalOpen}
        onOpenChange={setRefreshModalOpen}
        channels={refreshStatuses}
        finished={refreshFinished}
      />
    </div>
  );
}

import { useState, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useCampaignTree, TreeNode } from "@/hooks/useCampaignTree";
import { useClientContext } from "./ClienteContext";
import { TreeGridTable } from "@/components/campaign-editor/TreeGridTable";
import { UnifiedCampaignModal } from "@/components/campaign-editor/UnifiedCampaignModal";
import { KPISummaryBar } from "@/components/campaign-editor/KPISummaryBar";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import { ArrowLeft, RefreshCw, CalendarIcon } from "lucide-react";
import { useQueryClient } from "@tanstack/react-query";
import { useFacebookCampaignSync } from "@/hooks/useFacebookCampaignSync";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { DateRange } from "react-day-picker";

export default function CampaignEditorPage() {
  const { campaignId } = useParams<{ campaignId: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { client } = useClientContext();
  const { toast } = useToast();
  const { syncCampaigns, syncing } = useFacebookCampaignSync();

  const { treeData, isLoading, targets, campaign, platform } = useCampaignTree({
    campaignId,
    clientId: client?.id,
    companyId: (client as unknown)?.company_id,
  });

  const [selectedNode, setSelectedNode] = useState<TreeNode | null>(null);
  const [unifiedModalOpen, setUnifiedModalOpen] = useState(false);
  const [syncPeriod, setSyncPeriod] = useState<string>(() => {
    return localStorage.getItem('campaignEditorSyncPeriod') || '30';
  });
  const [isSyncing, setIsSyncing] = useState(false);
  const [customDateRange, setCustomDateRange] = useState<DateRange | undefined>(undefined);
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);

  const handleSelectNode = useCallback((node: TreeNode) => {
    setSelectedNode(node);
    setUnifiedModalOpen(true);
  }, []);

  const handlePeriodChange = (value: string) => {
    setSyncPeriod(value);
    localStorage.setItem('campaignEditorSyncPeriod', value);
    // Clear custom date range when selecting a preset
    if (value !== 'custom') {
      setCustomDateRange(undefined);
    }
  };

  const handleCustomDateSelect = (range: DateRange | undefined) => {
    setCustomDateRange(range);
    if (range?.from && range?.to) {
      setSyncPeriod('custom');
      localStorage.setItem('campaignEditorSyncPeriod', 'custom');
      setIsCalendarOpen(false);
    }
  };

  const invalidateQueries = useCallback(() => {
    queryClient.invalidateQueries({ queryKey: ["campaign-tree-meta-campaign", campaignId] });
    queryClient.invalidateQueries({ queryKey: ["campaign-tree-google-campaign", campaignId] });
    queryClient.invalidateQueries({ queryKey: ["campaign-tree-meta-adsets", campaignId] });
    queryClient.invalidateQueries({ queryKey: ["campaign-tree-meta-ads", campaignId] });
    queryClient.invalidateQueries({ queryKey: ["campaign-tree-google-adgroups", campaignId] });
    queryClient.invalidateQueries({ queryKey: ["campaign-tree-google-ads", campaignId] });
  }, [queryClient, campaignId]);

  const handleSyncFromMeta = useCallback(async () => {
    if (!client?.id || platform !== "meta") {
      toast({
        title: "Erro",
        description: platform !== "meta" ? "Sincronização disponível apenas para campanhas Meta" : "Cliente não encontrado",
        variant: "destructive",
      });
      return;
    }

    // Get the facebook_id from the campaign
    const campaignFacebookId = (campaign as unknown)?.facebook_id;
    if (!campaignFacebookId) {
      toast({
        title: "Erro",
        description: "ID do Facebook não encontrado para esta campanha.",
        variant: "destructive",
      });
      return;
    }

    // Build period label
    let periodLabel = syncPeriod === 'lifetime' ? 'máximo' : `${syncPeriod} dias`;
    let startDate: string | undefined;
    let endDate: string | undefined;

    if (syncPeriod === 'custom' && customDateRange?.from && customDateRange?.to) {
      startDate = format(customDateRange.from, 'yyyy-MM-dd');
      endDate = format(customDateRange.to, 'yyyy-MM-dd');
      periodLabel = `${format(customDateRange.from, 'dd/MM')} a ${format(customDateRange.to, 'dd/MM')}`;
    }

    toast({
      title: "Sincronizando do Meta",
      description: `Buscando dados da campanha (${periodLabel})...`,
    });

    try {
      // Sync only this specific campaign, its adsets and ads
      const jobId = await syncCampaigns(
        client.id,
        syncPeriod === 'custom' ? '30' : syncPeriod, // Use 30 as fallback for custom
        { 
          campaigns: true, 
          adsets: true, 
          ads: true,
          campaignFacebookId, // Only sync this specific campaign
          startDate,
          endDate
        },
        true, // silent
        false // includeInactive
      );

      if (jobId) {
        let pollCount = 0;
        const maxPolls = 60;

        const checkJob = async () => {
          pollCount++;

          if (pollCount >= maxPolls) {
            toast({
              title: "⚠️ Sincronização demorada",
              description: "Atualize a página para verificar os dados.",
              variant: "destructive",
            });
            setIsSyncing(false);
            invalidateQueries();
            return;
          }

          try {
            const { data: job, error: jobError } = await supabase
              .from('sync_jobs')
              .select('status, error_message')
              .eq('id', jobId)
              .single();

            if (jobError) {
              console.error('Error checking sync job:', jobError);
              setIsSyncing(false);
              invalidateQueries();
              return;
            }

            const status = job?.status?.toLowerCase();

            if (status === 'completed' || status === 'success') {
              toast({
                title: "✅ Sincronização concluída",
                description: `Campanha atualizada (${periodLabel}).`,
              });
              invalidateQueries();
              setIsSyncing(false);
            } else if (status === 'error' || status === 'failed') {
              toast({
                title: "❌ Erro na sincronização",
                description: job?.error_message || "Ocorreu um erro ao sincronizar.",
                variant: "destructive",
              });
              setIsSyncing(false);
            } else if (status === 'processing' || status === 'pending') {
              setTimeout(checkJob, 2000);
            } else {
              if (pollCount < 5) {
                setTimeout(checkJob, 2000);
              } else {
                setIsSyncing(false);
                invalidateQueries();
              }
            }
          } catch (pollError) {
            console.error('Poll error:', pollError);
            setIsSyncing(false);
            invalidateQueries();
          }
        };

        setTimeout(checkJob, 1500);
      } else {
        setIsSyncing(false);
      }
    } catch (error: unknown) {
      console.error('Sync error:', error);
      toast({
        title: "Erro na sincronização",
        description: error.message || "Não foi possível sincronizar os dados.",
        variant: "destructive",
      });
      setIsSyncing(false);
    }
  }, [client?.id, platform, syncPeriod, customDateRange, (campaign as unknown)?.facebook_id, syncCampaigns, invalidateQueries, toast]);

  // Get period display text
  const getPeriodDisplayText = () => {
    if (syncPeriod === 'custom' && customDateRange?.from && customDateRange?.to) {
      return `${format(customDateRange.from, 'dd/MM')} - ${format(customDateRange.to, 'dd/MM')}`;
    }
    const labels: Record<string, string> = {
      '1': 'Hoje',
      '3': '3 dias',
      '5': '5 dias',
      '7': '7 dias',
      '14': '14 dias',
      '30': '30 dias',
      '60': '60 dias',
      '90': '90 dias',
      'lifetime': 'Máximo'
    };
    return labels[syncPeriod] || '30 dias';
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <RefreshCw className="w-6 h-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="sm" onClick={() => navigate(-1)}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Voltar
          </Button>
          <div>
            <h1 className="text-2xl font-bold truncate max-w-lg">
              {campaign?.name || "Campanha"}
            </h1>
            <p className="text-sm text-muted-foreground">
              Plataforma: {platform === "meta" ? "Meta Ads" : "Google Ads"} •{" "}
              {treeData?.children?.length || 0} conjuntos de anúncios
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {/* Period selector */}
          <Select value={syncPeriod === 'custom' ? 'custom' : syncPeriod} onValueChange={handlePeriodChange}>
            <SelectTrigger className="w-[130px] h-9">
              <SelectValue placeholder="Período">
                {getPeriodDisplayText()}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="1">Hoje</SelectItem>
              <SelectItem value="3">3 dias</SelectItem>
              <SelectItem value="5">5 dias</SelectItem>
              <SelectItem value="7">7 dias</SelectItem>
              <SelectItem value="14">14 dias</SelectItem>
              <SelectItem value="30">30 dias</SelectItem>
              <SelectItem value="60">60 dias</SelectItem>
              <SelectItem value="90">90 dias</SelectItem>
              <SelectItem value="lifetime">Máximo</SelectItem>
              <SelectItem value="custom">Personalizado</SelectItem>
            </SelectContent>
          </Select>

          {/* Custom date picker */}
          {syncPeriod === 'custom' && (
            <Popover open={isCalendarOpen} onOpenChange={setIsCalendarOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="h-9 gap-2">
                  <CalendarIcon className="h-4 w-4" />
                  {customDateRange?.from && customDateRange?.to ? (
                    <span className="text-xs">
                      {format(customDateRange.from, 'dd/MM')} - {format(customDateRange.to, 'dd/MM')}
                    </span>
                  ) : (
                    <span className="text-xs">Selecionar</span>
                  )}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0" align="end">
                <Calendar
                  mode="range"
                  selected={customDateRange}
                  onSelect={handleCustomDateSelect}
                  numberOfMonths={2}
                  locale={ptBR}
                  disabled={(date) => date > new Date()}
                />
              </PopoverContent>
            </Popover>
          )}

          {/* Sync button */}
          <Button
            variant="outline"
            size="sm"
            onClick={handleSyncFromMeta}
            disabled={isSyncing || syncing || platform !== "meta" || (syncPeriod === 'custom' && (!customDateRange?.from || !customDateRange?.to))}
          >
            <RefreshCw className={`w-4 h-4 mr-2 ${isSyncing || syncing ? 'animate-spin' : ''}`} />
            {isSyncing || syncing ? 'Sincronizando...' : 'Atualizar'}
          </Button>
        </div>
      </div>

      {/* KPI Summary */}
      <KPISummaryBar campaign={treeData} targets={targets} />

      {/* Tree Grid */}
      <TreeGridTable
        campaign={treeData}
        targets={targets}
        clientId={client?.id || ""}
        onSelectNode={handleSelectNode}
        selectedNodeId={selectedNode?.id || null}
        onRefresh={invalidateQueries}
      />

      {/* Unified Campaign Modal */}
      <UnifiedCampaignModal
        isOpen={unifiedModalOpen}
        onClose={() => setUnifiedModalOpen(false)}
        campaignTree={treeData}
        initialSelectedNode={selectedNode}
        clientId={client?.id || ''}
        companyId={(client as unknown)?.company_id}
        onSuccess={invalidateQueries}
      />
    </div>
  );
}

import { useEffect, useState } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { AlertTriangle, TrendingUp, Lightbulb, Loader2 } from "lucide-react";
import { useClientContext } from "./ClienteContext";
import { useDashboardAlerts } from "@/hooks/useDashboardAlerts";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { useCampaigns } from "@/hooks/useCampaigns";
import { TaskSuggestionsModal } from "@/components/clients/TaskSuggestionsModal";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";

export function ClienteAlertas() {
  const { client } = useClientContext();
  const { alerts, loading, generateAlerts } = useDashboardAlerts();
  const { convertAlertToTask, isCreating } = useTaskAutomation();
  const { campaigns } = useCampaigns();
  const { toast } = useToast();
  const [showSuggestionsModal, setShowSuggestionsModal] = useState(false);
  const [generatingSuggestions, setGeneratingSuggestions] = useState(false);
  const [clientSuggestions, setClientSuggestions] = useState<unknown>(null);

  // Buscar alertas ao montar
  useEffect(() => {
    if (client?.id) {
      generateAlerts(client.id);
    }
  }, [client?.id]);

  // Filtrar alertas apenas deste cliente
  const clientAlerts = alerts.filter(alert => alert.client_id === client?.id);

  // Contadores
  const criticalCount = clientAlerts.filter(a => a.type === 'danger').length;
  const opportunityCount = clientAlerts.filter(a => a.type === 'opportunity').length;

  const handleCreateTask = (alert: unknown) => {
    convertAlertToTask(alert);
  };

  const handleGenerateSuggestions = async () => {
    if (!client?.id) return;

    setGeneratingSuggestions(true);
    try {
      // Buscar campanhas do cliente
      const clientCampaigns = campaigns.filter(c => c.client_id === client.id);

      const { data, error } = await supabase.functions.invoke('generate-client-suggestions', {
        body: {
          clientData: {
            id: client.id,
            name: client.name,
            company: client.company,
            status: client.status,
          },
          campaigns: clientCampaigns.map(c => ({
            id: c.id,
            name: c.name,
            status: c.status,
            spend: c.spend,
            cpa: c.cpa,
            ctr: c.ctr,
            conversions: c.conversions,
            impressions: c.impressions,
            clicks: c.clicks,
          })),
        },
      });

      if (error) throw error;

      // Preparar dados para o modal
      const modalData = {
        id: client.id,
        name: client.name,
        issues: data.suggestions.map((s: unknown) => s.description).slice(0, 5),
        problematic_campaigns: clientCampaigns
          .filter(c => c.status === 'active' && (c.cpa > 50 || c.ctr < 1))
          .map(c => c.name)
          .slice(0, 3),
        ai_recommendations: data.suggestions.map((s: unknown) => s.action).slice(0, 5),
      };

      setClientSuggestions(modalData);
      setShowSuggestionsModal(true);

      toast({
        title: "Sugestões geradas!",
        description: `${data.suggestions.length} sugestões de otimização criadas com IA.`,
      });
    } catch (error) {
      console.error('Erro ao gerar sugestões:', error);
      toast({
        title: "Erro ao gerar sugestões",
        description: "Não foi possível gerar sugestões. Tente novamente.",
        variant: "destructive",
      });
    } finally {
      setGeneratingSuggestions(false);
    }
  };

  const getBadgeVariant = (type: string) => {
    return type === 'danger' ? 'destructive' : 'default';
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Alertas & Sugestões</h2>
          <p className="text-muted-foreground">
            Alertas das campanhas e sugestões de otimização para {client?.name}
          </p>
        </div>
        <Button
          onClick={handleGenerateSuggestions}
          disabled={generatingSuggestions}
          className="gap-2"
        >
          {generatingSuggestions ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Gerando...
            </>
          ) : (
            <>
              <Lightbulb className="w-4 h-4" />
              Gerar Sugestões Inteligentes
            </>
          )}
        </Button>
      </div>

      {/* Resumo */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-destructive/10 rounded-lg flex items-center justify-center">
                <AlertTriangle className="w-5 h-5 text-destructive" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Críticos</p>
                <p className="text-2xl font-bold">{criticalCount}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">
                <TrendingUp className="w-5 h-5 text-green-600" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Oportunidades</p>
                <p className="text-2xl font-bold">{opportunityCount}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-primary/10 rounded-lg flex items-center justify-center">
                <Lightbulb className="w-5 h-5 text-primary" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">Total</p>
                <p className="text-2xl font-bold">{clientAlerts.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Lista de Alertas */}
      {clientAlerts.length === 0 ? (
        <Card>
          <CardContent className="py-12">
            <div className="text-center">
              <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-green-100 flex items-center justify-center">
                <TrendingUp className="w-8 h-8 text-green-600" />
              </div>
              <h3 className="text-lg font-semibold mb-2">Tudo certo por aqui! 🎉</h3>
              <p className="text-muted-foreground max-w-md mx-auto">
                Não há alertas críticos para este cliente no momento. Continue monitorando as campanhas regularmente.
              </p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {clientAlerts.map((alert) => (
            <Card key={alert.id} className={alert.type === 'danger' ? 'border-l-4 border-l-destructive' : 'border-l-4 border-l-green-500'}>
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div className="flex items-start gap-3 flex-1">
                    <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${
                      alert.type === 'danger' ? 'bg-destructive/10' : 'bg-green-100'
                    }`}>
                      {alert.type === 'danger' ? (
                        <AlertTriangle className="w-5 h-5 text-destructive" />
                      ) : (
                        <TrendingUp className="w-5 h-5 text-green-600" />
                      )}
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <CardTitle className="text-lg">{alert.title}</CardTitle>
                        <Badge variant={getBadgeVariant(alert.type)}>
                          {alert.type === 'danger' ? 'Crítico' : 'Oportunidade'}
                        </Badge>
                      </div>
                      <p className="text-sm text-muted-foreground mb-2">{alert.description}</p>
                      <div className="flex items-center gap-4 text-sm">
                        <span className="font-medium">Campanha:</span>
                        <span className="text-muted-foreground">{alert.campaign}</span>
                      </div>
                      <div className="flex items-center gap-4 text-sm mt-1">
                        <span className="font-medium">{alert.metric}:</span>
                        <span className="text-muted-foreground">{alert.value}</span>
                      </div>
                    </div>
                  </div>
                  <Button
                    onClick={() => handleCreateTask(alert)}
                    disabled={isCreating}
                    size="sm"
                  >
                    {isCreating ? 'Criando...' : 'Criar Tarefa'}
                  </Button>
                </div>
              </CardHeader>
              <CardContent>
                <div className="bg-muted/50 p-4 rounded-lg">
                  <p className="text-sm font-medium mb-2">💡 Recomendação:</p>
                  <p className="text-sm text-muted-foreground">{alert.recommendation}</p>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Modal de Sugestões */}
      {clientSuggestions && (
        <TaskSuggestionsModal
          isOpen={showSuggestionsModal}
          onClose={() => setShowSuggestionsModal(false)}
          client={clientSuggestions}
        />
      )}
    </div>
  );
}

import { createContext, useContext, ReactNode } from "react";
import { ClientDetailsData } from "@/hooks/useClientDetails";

interface ClientContextValue {
  client: ClientDetailsData;
  selectedCampaignId: string | null;
  setSelectedCampaignId: (id: string | null) => void;
  selectedAdSetId: string | null;
  setSelectedAdSetId: (id: string | null) => void;
  refetchClient: () => void;
  refetchAdSets?: () => void;
  refetchAds?: () => void;
}

const ClientContext = createContext<ClientContextValue | null>(null);

export function useClientContext() {
  const context = useContext(ClientContext);
  if (!context) {
    throw new Error("useClientContext must be used within ClientContext Provider");
  }
  return context;
}

interface ClientContextProviderProps {
  children: ReactNode;
  value: ClientContextValue;
}

export function ClientContextProvider({ children, value }: ClientContextProviderProps) {
  return <ClientContext.Provider value={value}>{children}</ClientContext.Provider>;
}

import { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Loader2,
  Search,
  Link,
  Download,
  TrendingUp,
  ArrowUpDown,
  X,
  Plus,
  Sparkles,
  Wand2,
  AlertCircle,
} from "lucide-react";
import { useKeywordPlanner, KeywordIdea } from "@/hooks/useKeywordPlanner";
import { useCompany } from "@/contexts/CompanyContext";
import { useClientContext } from "./ClienteContext";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

type SortField = "keyword" | "avgMonthlySearches" | "competition" | "cpcLow" | "cpcHigh";
type SortDirection = "asc" | "desc";

export function ClienteKeywordPlanner() {
  const { activeCompany } = useCompany();
  const { client } = useClientContext();
  const [inputMode, setInputMode] = useState<"keywords" | "url" | "briefing">("briefing");
  const [keywordInput, setKeywordInput] = useState("");
  const [urlInput, setUrlInput] = useState("");
  const [seedKeywords, setSeedKeywords] = useState<string[]>([]);
  const [sortField, setSortField] = useState<SortField>("avgMonthlySearches");
  const [sortDirection, setSortDirection] = useState<SortDirection>("desc");
  const [competitionFilter, setCompetitionFilter] = useState<string>("all");

  // Usar o customer ID da conta Google Ads vinculada ao cliente
  const googleCustomerId = client?.google_ads_account?.google_customer_id;

  const {
    loading,
    keywords,
    generateKeywordIdeas,
    formatCurrency,
    formatNumber,
    getCompetitionLabel,
    getCompetitionColor,
    clearKeywords,
  } = useKeywordPlanner({
    companyId: activeCompany?.company_id || "",
    customerId: googleCustomerId,
  });

  // Extract keywords from client briefing
  const extractKeywordsFromBriefing = (): string[] => {
    if (!client) return [];

    const keywords: string[] = [];

    // Add product/service name
    if (client.product_name) {
      keywords.push(client.product_name);
    }

    // Add company name
    if (client.company) {
      keywords.push(client.company);
    }

    // Add sector
    if (client.sector) {
      keywords.push(client.sector);
    }

    // Extract keywords from briefing
    if (client.ai_briefing) {
      // Extract key phrases from briefing (simplified extraction)
      const briefingText = client.ai_briefing.toLowerCase();

      // Common patterns to extract
      const patterns = [
        /produto[s]?:\s*([^.;]+)/gi,
        /serviço[s]?:\s*([^.;]+)/gi,
        /oferece[m]?\s+([^.;]+)/gi,
        /especializado[s]?\s+em\s+([^.;]+)/gi,
        /foco\s+em\s+([^.;]+)/gi,
      ];

      patterns.forEach(pattern => {
        const matches = briefingText.matchAll(pattern);
        for (const match of matches) {
          if (match[1]) {
            const extracted = match[1].trim().split(/[,;]/).map(s => s.trim()).filter(s => s.length > 2 && s.length < 50);
            keywords.push(...extracted);
          }
        }
      });
    }

    // Add target audience keywords
    if (client.target_audience) {
      keywords.push(client.target_audience);
    }

    // Add objectives
    if (client.objectives) {
      keywords.push(client.objectives);
    }

    // Filter and deduplicate
    const uniqueKeywords = [...new Set(keywords)]
      .filter(k => k && k.length > 2 && k.length < 50)
      .slice(0, 10);

    return uniqueKeywords;
  };

  // Pre-populate URL from client website
  useEffect(() => {
    if (client?.website_url && !urlInput) {
      setUrlInput(client.website_url);
    }
  }, [client?.website_url]);

  const handleAddKeyword = () => {
    const keyword = keywordInput.trim();
    if (keyword && !seedKeywords.includes(keyword)) {
      setSeedKeywords([...seedKeywords, keyword]);
      setKeywordInput("");
    }
  };

  const handleRemoveKeyword = (keyword: string) => {
    setSeedKeywords(seedKeywords.filter((k) => k !== keyword));
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault();
      handleAddKeyword();
    }
  };

  const handleSearch = async () => {
    if (inputMode === "keywords" && seedKeywords.length > 0) {
      await generateKeywordIdeas(seedKeywords);
    } else if (inputMode === "url" && urlInput.trim()) {
      await generateKeywordIdeas([], urlInput.trim());
    } else if (inputMode === "briefing") {
      const briefingKeywords = extractKeywordsFromBriefing();
      if (briefingKeywords.length > 0) {
        await generateKeywordIdeas(briefingKeywords);
      }
    }
  };

  const handleSearchFromBriefing = async () => {
    const briefingKeywords = extractKeywordsFromBriefing();
    if (briefingKeywords.length > 0) {
      await generateKeywordIdeas(briefingKeywords);
    }
  };

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortDirection("desc");
    }
  };

  const filteredAndSortedKeywords = keywords
    .filter((kw) => {
      if (competitionFilter === "all") return true;
      return kw.competition === competitionFilter;
    })
    .sort((a, b) => {
      let comparison = 0;
      switch (sortField) {
        case "keyword":
          comparison = a.keyword.localeCompare(b.keyword);
          break;
        case "avgMonthlySearches":
          comparison = a.avgMonthlySearches - b.avgMonthlySearches;
          break;
        case "competition": {
          const order = { LOW: 1, MEDIUM: 2, HIGH: 3, UNSPECIFIED: 0 };
          comparison = (order[a.competition] || 0) - (order[b.competition] || 0);
          break;
        }
        case "cpcLow":
          comparison = a.lowTopOfPageBidMicros - b.lowTopOfPageBidMicros;
          break;
        case "cpcHigh":
          comparison = a.highTopOfPageBidMicros - b.highTopOfPageBidMicros;
          break;
      }
      return sortDirection === "asc" ? comparison : -comparison;
    });

  const handleExportCSV = () => {
    if (filteredAndSortedKeywords.length === 0) return;

    const headers = ["Palavra-chave", "Vol. Mensal", "Competição", "CPC Baixo", "CPC Alto"];
    const rows = filteredAndSortedKeywords.map((kw) => [
      kw.keyword,
      kw.avgMonthlySearches,
      getCompetitionLabel(kw.competition),
      formatCurrency(kw.lowTopOfPageBidMicros),
      formatCurrency(kw.highTopOfPageBidMicros),
    ]);

    const csvContent = [headers, ...rows].map((row) => row.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `keyword-planner-${client?.name || 'cliente'}-${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  };

  const SortableHeader = ({ field, children }: { field: SortField; children: React.ReactNode }) => (
    <TableHead
      className="cursor-pointer hover:bg-muted/50 transition-colors"
      onClick={() => handleSort(field)}
    >
      <div className="flex items-center gap-1">
        {children}
        <ArrowUpDown className="h-3 w-3 text-muted-foreground" />
      </div>
    </TableHead>
  );

  const briefingKeywords = extractKeywordsFromBriefing();
  const hasBriefing = briefingKeywords.length > 0;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-foreground">Planejador de Palavras-chave</h1>
        <p className="text-muted-foreground">
          Descubra palavras-chave relevantes para {client?.name || "este cliente"}
        </p>
        {client?.google_ads_account && (
          <p className="text-xs text-muted-foreground mt-1">
            Conta Google Ads: {client.google_ads_account.account_name} ({client.google_ads_account.google_customer_id})
          </p>
        )}
      </div>

      {/* Aviso se não houver conta Google Ads vinculada */}
      {!client?.google_ads_account && (
        <Alert variant="destructive">
          <AlertCircle className="h-4 w-4" />
          <AlertTitle>Conta Google Ads não vinculada</AlertTitle>
          <AlertDescription>
            Este cliente não possui uma conta Google Ads vinculada. Vincule uma conta nas configurações do cliente para usar o Planejador de Palavras-chave.
          </AlertDescription>
        </Alert>
      )}

      {/* Quick Suggestions from Briefing */}
      {hasBriefing && keywords.length === 0 && (
        <Card className="border-primary/20 bg-primary/5">
          <CardContent className="pt-6">
            <div className="flex items-start gap-4">
              <div className="p-3 rounded-full bg-primary/10">
                <Wand2 className="h-6 w-6 text-primary" />
              </div>
              <div className="flex-1 space-y-3">
                <div>
                  <h3 className="font-semibold text-foreground">Sugestões Automáticas</h3>
                  <p className="text-sm text-muted-foreground">
                    Baseado no briefing e dados do cliente, identificamos estas palavras-chave iniciais:
                  </p>
                </div>
                <div className="flex flex-wrap gap-2">
                  {briefingKeywords.map((kw, i) => (
                    <Badge key={i} variant="secondary">
                      {kw}
                    </Badge>
                  ))}
                </div>
                <Button onClick={handleSearchFromBriefing} disabled={loading || !googleCustomerId} className="gap-2">
                  {loading ? (
                    <>
                      <Loader2 className="h-4 w-4 animate-spin" />
                      Buscando...
                    </>
                  ) : (
                    <>
                      <Sparkles className="h-4 w-4" />
                      Gerar Ideias de Palavras-chave
                    </>
                  )}
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {!hasBriefing && keywords.length === 0 && (
        <Alert>
          <AlertCircle className="h-4 w-4" />
          <AlertTitle>Briefing não encontrado</AlertTitle>
          <AlertDescription>
            Este cliente não possui briefing configurado. Adicione palavras-chave manualmente ou uma URL para gerar ideias.
          </AlertDescription>
        </Alert>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-primary" />
            Pesquisar Palavras-chave
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <Tabs value={inputMode} onValueChange={(v) => setInputMode(v as "keywords" | "url" | "briefing")}>
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="briefing" className="gap-2">
                <Wand2 className="h-4 w-4" />
                Do Briefing
              </TabsTrigger>
              <TabsTrigger value="keywords" className="gap-2">
                <Search className="h-4 w-4" />
                Por Palavras-chave
              </TabsTrigger>
              <TabsTrigger value="url" className="gap-2">
                <Link className="h-4 w-4" />
                Por URL
              </TabsTrigger>
            </TabsList>

            <TabsContent value="briefing" className="space-y-3 mt-4">
              {hasBriefing ? (
                <div className="space-y-3">
                  <p className="text-sm text-muted-foreground">
                    Palavras-chave extraídas do briefing do cliente:
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {briefingKeywords.map((kw, i) => (
                      <Badge key={i} variant="outline">
                        {kw}
                      </Badge>
                    ))}
                  </div>
                </div>
              ) : (
                <p className="text-sm text-muted-foreground">
                  Nenhum briefing disponível. Configure o briefing do cliente para usar esta opção.
                </p>
              )}
            </TabsContent>

            <TabsContent value="keywords" className="space-y-3 mt-4">
              <div className="flex gap-2">
                <Input
                  placeholder="Digite uma palavra-chave e pressione Enter"
                  value={keywordInput}
                  onChange={(e) => setKeywordInput(e.target.value)}
                  onKeyPress={handleKeyPress}
                  disabled={loading}
                />
                <Button onClick={handleAddKeyword} disabled={!keywordInput.trim() || loading} size="icon">
                  <Plus className="h-4 w-4" />
                </Button>
              </div>

              {seedKeywords.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {seedKeywords.map((keyword) => (
                    <Badge key={keyword} variant="secondary" className="gap-1 pr-1">
                      {keyword}
                      <button
                        onClick={() => handleRemoveKeyword(keyword)}
                        className="ml-1 hover:bg-muted rounded-full p-0.5"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  ))}
                </div>
              )}
            </TabsContent>

            <TabsContent value="url" className="mt-4">
              <Input
                placeholder="https://exemplo.com.br/pagina"
                value={urlInput}
                onChange={(e) => setUrlInput(e.target.value)}
                disabled={loading}
              />
              <p className="text-xs text-muted-foreground mt-2">
                O Google irá extrair palavras-chave relevantes desta página
              </p>
            </TabsContent>
          </Tabs>

          <Button
            onClick={handleSearch}
            disabled={
              loading ||
              !googleCustomerId ||
              (inputMode === "keywords" && seedKeywords.length === 0) ||
              (inputMode === "url" && !urlInput.trim()) ||
              (inputMode === "briefing" && !hasBriefing)
            }
            className="w-full gap-2"
          >
            {loading ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" />
                Buscando ideias...
              </>
            ) : (
              <>
                <TrendingUp className="h-4 w-4" />
                Gerar Ideias de Palavras-chave
              </>
            )}
          </Button>

          {keywords.length > 0 && (
            <div className="space-y-4 pt-4 border-t">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <p className="text-sm text-muted-foreground">
                    {filteredAndSortedKeywords.length} de {keywords.length} palavras-chave
                  </p>
                  <Select value={competitionFilter} onValueChange={setCompetitionFilter}>
                    <SelectTrigger className="w-[140px] h-8">
                      <SelectValue placeholder="Competição" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">Todas</SelectItem>
                      <SelectItem value="LOW">Baixa</SelectItem>
                      <SelectItem value="MEDIUM">Média</SelectItem>
                      <SelectItem value="HIGH">Alta</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="flex gap-2">
                  <Button variant="outline" size="sm" onClick={handleExportCSV} className="gap-2">
                    <Download className="h-4 w-4" />
                    Exportar CSV
                  </Button>
                  <Button variant="ghost" size="sm" onClick={clearKeywords}>
                    Limpar
                  </Button>
                </div>
              </div>

              <div className="border rounded-lg overflow-hidden">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <SortableHeader field="keyword">Palavra-chave</SortableHeader>
                      <SortableHeader field="avgMonthlySearches">Vol. Mensal</SortableHeader>
                      <SortableHeader field="competition">Competição</SortableHeader>
                      <SortableHeader field="cpcLow">CPC Mín.</SortableHeader>
                      <SortableHeader field="cpcHigh">CPC Máx.</SortableHeader>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filteredAndSortedKeywords.slice(0, 50).map((kw, index) => (
                      <TableRow key={`${kw.keyword}-${index}`}>
                        <TableCell className="font-medium">{kw.keyword}</TableCell>
                        <TableCell>{formatNumber(kw.avgMonthlySearches)}</TableCell>
                        <TableCell>
                          <Badge
                            variant="outline"
                            className={getCompetitionColor(kw.competition)}
                          >
                            {getCompetitionLabel(kw.competition)}
                          </Badge>
                        </TableCell>
                        <TableCell>{formatCurrency(kw.lowTopOfPageBidMicros)}</TableCell>
                        <TableCell>{formatCurrency(kw.highTopOfPageBidMicros)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>

              {filteredAndSortedKeywords.length > 50 && (
                <p className="text-xs text-muted-foreground text-center">
                  Exibindo 50 de {filteredAndSortedKeywords.length} resultados. Exporte para ver todos.
                </p>
              )}
            </div>
          )}

          {!loading && keywords.length === 0 && !hasBriefing && (
            <div className="text-center py-8 text-muted-foreground">
              <TrendingUp className="h-12 w-12 mx-auto mb-3 opacity-50" />
              <p>Digite palavras-chave ou uma URL para descobrir ideias</p>
              <p className="text-sm mt-1">
                Use o Planejador para encontrar termos relevantes para suas campanhas
              </p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useParams } from "react-router-dom";
import { useEffect, useState } from "react";
import { useMetaAudiences, MetaAudience } from "@/hooks/useMetaAudiences";
import { AudiencesList } from "@/components/audiences/AudiencesList";
import { CreateAudienceModal } from "@/components/audiences/CreateAudienceModal";
import { CreateAdvancedAudienceModal, PixelOption, PageOption, InstagramOption } from "@/components/audiences/CreateAdvancedAudienceModal";
import { UploadLeadsModal } from "@/components/audiences/UploadLeadsModal";
import { AudienceDetailsModal } from "@/components/audiences/AudienceDetailsModal";
import { CreateLookalikeModal } from "@/components/audiences/CreateLookalikeModal";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Plus, RefreshCw, Users, AlertCircle, ExternalLink, Sparkles } from "lucide-react";
import { Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";

export function ClientePublicos() {
  const { id } = useParams<{ id: string }>();
  const {
    loading,
    audiences,
    fetchAudiences,
    createAudience,
    deleteAudience,
    getAudienceDetails,
    addUsersToAudience,
    createLookalikeAudience,
    createWebsiteAudience,
    createEngagementAudience,
    error,
  } = useMetaAudiences(id || null);

  const [createModalOpen, setCreateModalOpen] = useState(false);
  const [advancedModalOpen, setAdvancedModalOpen] = useState(false);
  const [uploadModalOpen, setUploadModalOpen] = useState(false);
  const [detailsModalOpen, setDetailsModalOpen] = useState(false);
  const [lookalikeModalOpen, setLookalikeModalOpen] = useState(false);
  const [selectedAudience, setSelectedAudience] = useState<MetaAudience | null>(null);

  // Data for advanced modal
  const [pixels, setPixels] = useState<PixelOption[]>([]);
  const [pages, setPages] = useState<PageOption[]>([]);
  const [instagramAccounts, setInstagramAccounts] = useState<InstagramOption[]>([]);

  useEffect(() => {
    if (id) {
      fetchAudiences(true);
      fetchAdvancedData();
    }
  }, [id]);

  const fetchAdvancedData = async () => {
    if (!id) return;

    // Fetch pixels, pages, and Instagram accounts for this client
    const [pixelsRes, clientRes] = await Promise.all([
      supabase.from('meta_pixels').select('id, pixel_id, pixel_name').eq('client_id', id),
      supabase.from('clients').select(`
        facebook_page_id,
        instagram_account_id,
        facebook_pages!clients_facebook_page_id_fkey(id, page_id, page_name),
        instagram_accounts!clients_instagram_account_id_fkey(id, instagram_id, username)
      `).eq('id', id).single(),
    ]);

    if (pixelsRes.data) {
      setPixels(pixelsRes.data);
    }

    if (clientRes.data) {
      if (clientRes.data.facebook_pages) {
        const page = clientRes.data.facebook_pages as unknown;
        setPages([{ id: page.id, page_id: page.page_id, name: page.page_name }]);
      }
      if (clientRes.data.instagram_accounts) {
        setInstagramAccounts([clientRes.data.instagram_accounts as InstagramOption]);
      }
    }
  };

  const handleCreateAudience = async (name: string, description?: string) => {
    const result = await createAudience(name, description);
    if (result) {
      setCreateModalOpen(false);
    }
  };

  const handleCreateWebsiteAudience = async (params: Parameters<typeof createWebsiteAudience>[0]) => {
    const result = await createWebsiteAudience(params);
    if (result) {
      setAdvancedModalOpen(false);
    }
  };

  const handleCreateEngagementAudience = async (params: Parameters<typeof createEngagementAudience>[0]) => {
    const result = await createEngagementAudience(params);
