import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useClientDetails } from "@/hooks/useClientDetails";
import { useCompany } from "@/contexts/CompanyContext";
import { useYouTubeContentLabs } from "@/hooks/useYouTubeContentLabs";
import { Loader2 } from "lucide-react";

export default function ClienteYouTubeContentLab() {
  const { id: clientId } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { client, loading: clientLoading } = useClientDetails(clientId || "");
  const { activeCompany } = useCompany();
  const companyId = activeCompany?.company_id || client?.company_id || "";
  const { getOrCreateClientLab, loading: labsLoading } = useYouTubeContentLabs(companyId);
  const [redirecting, setRedirecting] = useState(false);

  useEffect(() => {
    if (!clientId || !client || !companyId || labsLoading || redirecting) return;

    const redirect = async () => {
      setRedirecting(true);
      const labId = await getOrCreateClientLab(clientId, client.name);
      if (labId) {
        navigate(`/youtube-content-lab/${labId}`, { replace: true });
      }
    };

    redirect();
  }, [clientId, client, companyId, labsLoading]);

  return (
    <div className="flex items-center justify-center h-64">
      <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { useCompany } from "@/contexts/CompanyContext";
import { useClients } from "@/hooks/useClients";
import { supabase } from "@/integrations/supabase/client";
import { Plus, Loader2, Factory, Zap, Settings2 } from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { ClientSearchCombobox } from "@/components/generators/ClientSearchCombobox";
import { ClienteConfiguracaoFabrica } from "@/components/generators/ClienteConfiguracaoFabrica";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";

interface ScheduleWithClient {
  id: string;
  client_id: string;
  is_active: boolean;
  ads_per_day: number;
  autopilot_enabled: boolean;
  generation_time: string;
  client_name?: string;
  client_company?: string;
  client_avatar?: string | null;
  client_sector?: string | null;
  ads_generated?: number;
}

export default function ConfiguracaoFabrica() {
  const { activeCompany } = useCompany();
  const { clients } = useClients();
  const [schedules, setSchedules] = useState<ScheduleWithClient[]>([]);
  const [loading, setLoading] = useState(true);
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [selectedClientId, setSelectedClientId] = useState<string>("");
  const [configClientId, setConfigClientId] = useState<string | null>(null);
  const debounceTimers = useRef<Record<string, NodeJS.Timeout>>({});

  const loadSchedules = async () => {
    if (!activeCompany?.company_id) return;

    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('ad_generation_schedules')
        .select('id, client_id, is_active, ads_per_day, autopilot_enabled, generation_time')
        .eq('company_id', activeCompany.company_id);

      if (error) throw error;

      const clientIds = (data || []).map(s => s.client_id);
      const { data: adsData } = await supabase
        .from('ad_generation_queue')
        .select('client_id')
        .in('client_id', clientIds);

      const adsCountByClient: Record<string, number> = {};
      (adsData || []).forEach(ad => {
        adsCountByClient[ad.client_id] = (adsCountByClient[ad.client_id] || 0) + 1;
      });

      const schedulesWithClients = (data || []).map(schedule => {
        const client = clients.find(c => c.id === schedule.client_id);
        return {
          ...schedule,
          client_name: client?.name || 'Cliente não encontrado',
          client_company: client?.company || '',
          client_avatar: client?.avatar,
          client_sector: client?.sector,
          ads_generated: adsCountByClient[schedule.client_id] || 0,
        };
      });

      setSchedules(schedulesWithClients);
    } catch (error) {
      console.error('Error loading schedules:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (activeCompany?.company_id && clients.length > 0) {
      loadSchedules();
    }
  }, [activeCompany?.company_id, clients]);

  const clientsWithSchedule = schedules.map(s => s.client_id);
  const availableClients = clients.filter(c => !clientsWithSchedule.includes(c.id));

  const handleCreateFactory = () => {
    if (selectedClientId) {
      setConfigClientId(selectedClientId);
      setCreateDialogOpen(false);
      setSelectedClientId("");
    }
  };

  const handleConfigSaved = () => {
    loadSchedules();
    setConfigClientId(null);
  };

  const getInitials = (name: string) => {
    return name
      .split(" ")
      .map((n) => n[0])
      .join("")
      .toUpperCase()
      .slice(0, 2);
  };

  const updateScheduleField = async (scheduleId: string, field: string, value: unknown) => {
    // Clear existing timer for this field
    const timerKey = `${scheduleId}-${field}`;
    if (debounceTimers.current[timerKey]) {
      clearTimeout(debounceTimers.current[timerKey]);
    }

    // Update local state immediately
    setSchedules(prev => prev.map(s => 
      s.id === scheduleId ? { ...s, [field]: value } : s
    ));

    // Debounce the API call
    debounceTimers.current[timerKey] = setTimeout(async () => {
      try {
        const { error } = await supabase
          .from('ad_generation_schedules')
          .update({ [field]: value })
          .eq('id', scheduleId);

        if (error) throw error;
        toast.success("Configuração salva");
      } catch (error) {
        console.error('Error updating schedule:', error);
        toast.error("Erro ao salvar");
        loadSchedules(); // Reload to revert
      }
    }, 800);
  };

  if (configClientId) {
    const client = clients.find(c => c.id === configClientId);
    return (
      <div className="space-y-6">
        <div className="flex items-center gap-4">
          <Button 
            variant="ghost" 
            onClick={() => setConfigClientId(null)}
            className="gap-2"
          >
            Voltar para Lista
          </Button>
          <div>
            <h1 className="text-headline-small font-medium text-foreground">Configurar Fábrica</h1>
            <p className="text-body-medium text-muted-foreground">{client?.name}</p>
          </div>
        </div>
        <ClienteConfiguracaoFabrica 
          clientId={configClientId} 
          onSave={handleConfigSaved}
        />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-headline-small font-medium text-foreground">Configuração da Fábrica</h1>
          <p className="text-body-medium text-muted-foreground">Gerencie as fábricas de anúncios por cliente</p>
        </div>
        <Button 
          onClick={() => setCreateDialogOpen(true)} 
          disabled={availableClients.length === 0}
          className="gap-2"
        >
          <Plus className="h-4 w-4" />
          Nova Fábrica
        </Button>
      </div>

      {loading ? (
        <div className="flex items-center justify-center h-64">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
      ) : schedules.length === 0 ? (
        <Card className="border-dashed">
          <div className="flex flex-col items-center justify-center py-16">
            <div className="h-16 w-16 rounded-full bg-primary/10 flex items-center justify-center mb-4">
              <Factory className="h-8 w-8 text-primary" />
            </div>
            <h3 className="text-title-large font-medium text-foreground mb-2">Nenhuma fábrica configurada</h3>
            <p className="text-body-medium text-muted-foreground mb-6 text-center max-w-md">
              Crie uma fábrica de anúncios para começar a gerar anúncios automaticamente para seus clientes
            </p>
            <Button onClick={() => setCreateDialogOpen(true)} className="gap-2">
              <Plus className="h-4 w-4" />
              Criar primeira fábrica
            </Button>
          </div>
        </Card>
      ) : (
        <Card>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-[280px]">Cliente</TableHead>
                <TableHead className="text-center">Status</TableHead>
                <TableHead className="text-center">Horário</TableHead>
                <TableHead className="text-center">Anúncios/dia</TableHead>
                <TableHead className="text-center">Gerados</TableHead>
                <TableHead className="text-center">Autopilot</TableHead>
                <TableHead className="w-[60px]"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {schedules.map((schedule) => (
                <TableRow key={schedule.id}>
                  <TableCell>
                    <div className="flex items-center gap-3">
                      <Avatar className="h-9 w-9">
                        <AvatarImage src={schedule.client_avatar || ""} alt={schedule.client_name} />
                        <AvatarFallback className="bg-primary/10 text-primary text-body-small">
                          {getInitials(schedule.client_name || '')}
                        </AvatarFallback>
                      </Avatar>
                      <div className="min-w-0">
                        <p className="text-body-medium font-medium text-foreground truncate">
                          {schedule.client_name}
                        </p>
                        {schedule.client_sector && (
                          <p className="text-body-small text-muted-foreground truncate">
                            {schedule.client_sector}
                          </p>
                        )}
                      </div>
                    </div>
                  </TableCell>

                  <TableCell className="text-center">
                    <Switch
                      checked={schedule.is_active}
                      onCheckedChange={(checked) => updateScheduleField(schedule.id, 'is_active', checked)}
                    />
                  </TableCell>

                  <TableCell className="text-center">
                    <Input
                      type="time"
                      value={schedule.generation_time}
                      onChange={(e) => updateScheduleField(schedule.id, 'generation_time', e.target.value)}
                      className="w-28 mx-auto text-center"
                    />
                  </TableCell>

                  <TableCell className="text-center">
                    <Input
                      type="number"
                      min={1}
                      max={5}
                      value={schedule.ads_per_day}
                      onChange={(e) => updateScheduleField(schedule.id, 'ads_per_day', parseInt(e.target.value) || 1)}
                      className="w-20 mx-auto text-center"
                    />
                  </TableCell>

                  <TableCell className="text-center">
                    <span className="text-body-medium font-medium">{schedule.ads_generated}</span>
                  </TableCell>

                  <TableCell className="text-center">
                    {schedule.autopilot_enabled && (
                      <Zap className="h-4 w-4 text-warning mx-auto" />
                    )}
                  </TableCell>

                  <TableCell>
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => setConfigClientId(schedule.client_id)}
                      className="h-8 w-8"
                      title="Configurações avançadas"
                    >
                      <Settings2 className="h-4 w-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </Card>
      )}

      <Dialog open={createDialogOpen} onOpenChange={setCreateDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="text-title-large">Nova Fábrica de Anúncios</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-4">
            <div>
              <label className="text-label-large font-medium mb-2 block">Selecione o cliente</label>
              <ClientSearchCombobox
                clients={availableClients}
                value={selectedClientId}
                onValueChange={setSelectedClientId}
                showCompany
                placeholder="Buscar cliente..."
              />
            </div>
            {availableClients.length === 0 && (
              <p className="text-body-small text-muted-foreground">
                Todos os clientes já possuem fábricas configuradas.
              </p>
            )}
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setCreateDialogOpen(false)}>
                Cancelar
              </Button>
              <Button onClick={handleCreateFactory} disabled={!selectedClientId}>
                Criar Fábrica
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { useDashboardAlerts } from "@/hooks/useDashboardAlerts";
import { useClients } from "@/hooks/useClients";
import { useCampaigns } from "@/hooks/useCampaigns";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { AlertTriangle, TrendingDown, Clock, DollarSign, Target, Eye, Users } from "lucide-react";

interface CriticalAlert {
  id: string;
  title: string;
  description: string;
  type: 'critical' | 'warning' | 'info';
  severity: 'alta' | 'media' | 'baixa';
  client_id?: string;
  client_name?: string;
  campaign_id?: string;
  campaign_name?: string;
  impact: string;
  recommended_action: string;
  created_at: string;
  metrics?: {
    current_value: number;
    target_value: number;
    unit: string;
  };
}

const RelatorioAlertasCriticos = () => {
  const { alerts } = useDashboardAlerts();
  const { clients } = useClients();
  const { campaigns } = useCampaigns();
  const { convertAlertToTask } = useTaskAutomation();
  const [criticalAlerts, setCriticalAlerts] = useState<CriticalAlert[]>([]);
  const [filteredData, setFilteredData] = useState<CriticalAlert[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});

  useEffect(() => {
    if (clients && campaigns) {
      generateCriticalAlerts();
    }
  }, [clients, campaigns, alerts]);

  useEffect(() => {
    setFilteredData(criticalAlerts);
  }, [criticalAlerts]);

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = [...criticalAlerts];

    // Filtro por tipo de alerta
    if (newFilters['tipo-alerta'] && newFilters['tipo-alerta'] !== 'todos') {
      filtered = filtered.filter(alert => alert.type === newFilters['tipo-alerta']);
    }

    // Filtro por severidade
    if (newFilters.severidade && newFilters.severidade !== 'todas') {
      filtered = filtered.filter(alert => alert.severity === newFilters.severidade);
    }

    // Filtro por cliente
    if (newFilters.cliente && newFilters.cliente !== 'todos') {
      filtered = filtered.filter(alert => alert.client_id === newFilters.cliente);
    }

    // Filtro por impacto
    if (newFilters.impacto && newFilters.impacto !== 'todos') {
      const impactType = newFilters.impacto;
      filtered = filtered.filter(alert => {
        switch (impactType) {
          case 'financeiro':
            return alert.impact.includes('orçamento') || alert.impact.includes('custo');
          case 'performance':
            return alert.impact.includes('CTR') || alert.impact.includes('conversão');
          case 'estrategico':
            return alert.impact.includes('campanha') || alert.impact.includes('cliente');
          default:
            return true;
        }
      });
    }

    setFilteredData(filtered);
  };

  const generateCriticalAlerts = () => {
    const generated: CriticalAlert[] = [];

    // 1. Clientes sem campanhas ativas
    clients?.forEach(client => {
      const activeCampaigns = campaigns?.filter(c => 
        c.client_id === client.id && c.status === 'active' && c.is_active
      ) || [];

      if (activeCampaigns.length === 0) {
        generated.push({
          id: `no_campaigns_${client.id}`,
          title: `Cliente sem campanhas ativas`,
          description: `${client.name} não possui campanhas ativas rodando`,
          type: 'critical',
          severity: 'alta',
          client_id: client.id,
          client_name: client.name,
          impact: 'Perda de faturamento e desconexão com cliente',
          recommended_action: 'Ativar campanhas imediatamente ou agendar reunião',
          created_at: new Date().toISOString()
        });
      }
    });

    // 2. Campanhas com CPA crítico
    campaigns?.forEach(campaign => {
      const client = clients?.find(c => c.id === campaign.client_id);
      if (campaign.cpa > 200 && campaign.conversions > 0) {
        generated.push({
          id: `high_cpa_${campaign.id}`,
          title: `CPA crítico detectado`,
          description: `${campaign.name} com CPA de R$ ${campaign.cpa.toFixed(0)}`,
          type: 'critical',
          severity: 'alta',
          client_id: campaign.client_id,
          client_name: client?.name || 'Cliente não identificado',
          campaign_id: campaign.id,
          campaign_name: campaign.name,
          impact: 'Alto desperdício de orçamento',
          recommended_action: 'Revisar segmentação e otimizar criativos',
          created_at: new Date().toISOString(),
          metrics: {
            current_value: campaign.cpa,
            target_value: 150,
            unit: 'R$'
          }
        });
      }
    });

    // 3. Campanhas com CTR muito baixo
    campaigns?.forEach(campaign => {
      const client = clients?.find(c => c.id === campaign.client_id);
      if (campaign.ctr < 0.5 && campaign.spend > 1000) {
        generated.push({
          id: `low_ctr_${campaign.id}`,
          title: `CTR extremamente baixo`,
          description: `${campaign.name} com CTR de ${campaign.ctr.toFixed(2)}%`,
          type: 'warning',
          severity: 'media',
          client_id: campaign.client_id,
          client_name: client?.name || 'Cliente não identificado',
          campaign_id: campaign.id,
          campaign_name: campaign.name,
          impact: 'Baixo engajamento e desperdício de impressões',
          recommended_action: 'Testar novos criativos e refinar audiência',
          created_at: new Date().toISOString(),
          metrics: {
            current_value: campaign.ctr,
            target_value: 1.0,
            unit: '%'
          }
        });
      }
    });

    // 4. Campanhas sem conversões há muito tempo
    campaigns?.forEach(campaign => {
      const client = clients?.find(c => c.id === campaign.client_id);
      if (campaign.conversions === 0 && campaign.spend > 500) {
        generated.push({
          id: `no_conversions_${campaign.id}`,
          title: `Campanha sem conversões`,
          description: `${campaign.name} gastou R$ ${campaign.spend.toFixed(0)} sem conversões`,
          type: 'critical',
          severity: 'alta',
          client_id: campaign.client_id,
          client_name: client?.name || 'Cliente não identificado',
          campaign_id: campaign.id,
          campaign_name: campaign.name,
          impact: 'Desperdício total de orçamento',
          recommended_action: 'Pausar campanha e revisar estratégia completamente',
          created_at: new Date().toISOString()
        });
      }
    });

    // Ordenar por severidade e tipo
    setCriticalAlerts(generated.sort((a, b) => {
      if (a.type === 'critical' && b.type !== 'critical') return -1;
      if (b.type === 'critical' && a.type !== 'critical') return 1;
      if (a.severity === 'alta' && b.severity !== 'alta') return -1;
      if (b.severity === 'alta' && a.severity !== 'alta') return 1;
      return 0;
    }));
  };

  const handleCreateTask = (alert: CriticalAlert) => {
    const alertData = {
      type: alert.type === 'critical' ? 'danger' : 'warning',
      description: `${alert.title}: ${alert.description} - ${alert.recommended_action}`,
      campaign_id: alert.campaign_id,
      client_id: alert.client_id,
      id: alert.id
    };

    convertAlertToTask(alertData);
  };

  const getStatusColor = (type: string) => {
    switch (type) {
      case 'critical': return 'bg-destructive text-destructive-foreground';
      case 'warning': return 'bg-warning text-warning-foreground';
      default: return 'bg-secondary text-secondary-foreground';
    }
  };

  const getSeverityBadge = (severity: string) => {
    switch (severity) {
      case 'alta': return 'bg-destructive text-destructive-foreground';
      case 'media': return 'bg-warning text-warning-foreground';
      default: return 'bg-secondary text-secondary-foreground';
    }
  };

  const getAlertIcon = (type: string) => {
    switch (type) {
      case 'critical': return AlertTriangle;
      case 'warning': return TrendingDown;
      default: return Clock;
    }
  };

  // Usar dados filtrados para métricas quando há filtros ativos
  const dataToUse = Object.keys(activeFilters).length > 0 ? filteredData : criticalAlerts;

  const criticalCount = dataToUse.filter(alert => alert.type === 'critical').length;
  const warningCount = dataToUse.filter(alert => alert.type === 'warning').length;
  const highSeverityCount = dataToUse.filter(alert => alert.severity === 'alta').length;
  const uniqueClientsAffected = new Set(dataToUse.map(alert => alert.client_id)).size;

  // Preparar dados únicos para filtros
  const uniqueClients = Array.from(new Set(criticalAlerts
    .filter(alert => alert.client_name)
    .map(alert => ({ id: alert.client_id!, name: alert.client_name! }))))
    .sort((a, b) => a.name.localeCompare(b.name))
    .map(client => ({ value: client.id, label: client.name }));

  const primaryFilters: FilterConfig[] = [
    {
      id: 'tipo-alerta',
      label: 'Tipo de Alerta',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os tipos' },
        { value: 'critical', label: 'Crítico' },
        { value: 'warning', label: 'Alerta' },
        { value: 'info', label: 'Informativo' }
      ],
      placeholder: 'Todos os tipos'
    },
    {
      id: 'severidade',
      label: 'Severidade',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as severidades' },
        { value: 'alta', label: 'Alta' },
        { value: 'media', label: 'Média' },
        { value: 'baixa', label: 'Baixa' }
      ],
      placeholder: 'Todas as severidades'
    },
    {
      id: 'cliente',
      label: 'Cliente',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os clientes' },
        ...uniqueClients
      ],
      placeholder: 'Todos os clientes'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'impacto',
      label: 'Tipo de Impacto',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os impactos' },
        { value: 'financeiro', label: 'Financeiro' },
        { value: 'performance', label: 'Performance' },
        { value: 'estrategico', label: 'Estratégico' }
      ],
      placeholder: 'Todos os impactos'
    }
  ];

  return (
    <ReportLayout
      title="Relatório de Alertas Críticos"
      description="Situações críticas que requerem ação imediata"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Configure os parâmetros para análise de alertas críticos"
    >
      <div className="space-y-6">
        {/* Resumo */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <MetricCard
            title="Alertas Críticos"
            value={criticalCount}
            trend={criticalCount > 0 ? "down" : "neutral"}
            subtitle="Requerem ação imediata"
          />
          <MetricCard
            title="Alertas de Atenção"
            value={warningCount}
            trend={warningCount > 0 ? "down" : "neutral"}
            subtitle="Monitoramento necessário"
          />
          <MetricCard
            title="Severidade Alta"
            value={highSeverityCount}
            trend={highSeverityCount > 0 ? "down" : "neutral"}
            subtitle="Máxima prioridade"
          />
          <MetricCard
            title="Clientes Afetados"
            value={uniqueClientsAffected}
            subtitle="Total de clientes"
          />
        </div>

        {/* Lista de Alertas */}
        <div className="grid gap-4">
          {filteredData.length === 0 ? (
            <Card>
              <CardContent className="p-6 text-center">
                <Users className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
                <h3 className="text-lg font-semibold mb-2">Nenhum alerta encontrado</h3>
                <p className="text-muted-foreground">
                  {Object.keys(activeFilters).length > 0 
                    ? 'Nenhum alerta corresponde aos filtros selecionados.'
                    : 'Não há alertas críticos no momento.'
                  }
                </p>
              </CardContent>
            </Card>
          ) : (
            filteredData.map((alert) => {
              const AlertIcon = getAlertIcon(alert.type);

              return (
                <Card key={alert.id} className={`border-l-4 ${alert.type === 'critical' ? 'border-l-destructive' : 'border-l-warning'}`}>
                  <CardHeader className="pb-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <AlertIcon className={`w-5 h-5 ${alert.type === 'critical' ? 'text-destructive' : 'text-warning'}`} />
                        <div>
                          <CardTitle className="text-lg">{alert.title}</CardTitle>
                          <p className="text-sm text-muted-foreground">
                            {alert.client_name} {alert.campaign_name && `• ${alert.campaign_name}`}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Badge className={getStatusColor(alert.type)}>
                          {alert.type === 'critical' ? 'CRÍTICO' : 'ALERTA'}
                        </Badge>
                        <Badge className={getSeverityBadge(alert.severity)}>
                          {alert.severity.toUpperCase()}
                        </Badge>
                        <div className="flex gap-2">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleCreateTask(alert)}
                          >
                            <Target className="w-4 h-4 mr-2" />
                            Criar Tarefa
                          </Button>
                        </div>
                      </div>
                    </div>
                  </CardHeader>

                  <CardContent className="space-y-4">
                    {/* Descrição do Problema */}
                    <div>
                      <h4 className={`font-semibold mb-2 ${alert.type === 'critical' ? 'text-destructive' : 'text-warning'}`}>
                        Problema Identificado:
                      </h4>
                      <p className="text-sm text-muted-foreground bg-muted/50 p-3 rounded-lg">
                        {alert.description}
                      </p>
                    </div>

                    {/* Impacto */}
                    <div>
                      <h4 className="font-semibold mb-2">Impacto:</h4>
                      <p className="text-sm text-muted-foreground">
                        {alert.impact}
                      </p>
                    </div>

                    {/* Ação Recomendada */}
                    <div>
                      <h4 className="font-semibold mb-2 text-primary">Ação Recomendada:</h4>
                      <p className="text-sm text-muted-foreground bg-primary/5 p-3 rounded-lg">
                        {alert.recommended_action}
                      </p>
                    </div>

                    {/* Métricas (se disponíveis) */}
                    {alert.metrics && (
                      <div className="grid grid-cols-3 gap-4 pt-4 border-t">
                        <div className="text-center">
                          <div className={`text-2xl font-bold ${alert.type === 'critical' ? 'text-destructive' : 'text-warning'}`}>
                            {alert.metrics.current_value.toFixed(alert.metrics.unit === '%' ? 2 : 0)}{alert.metrics.unit}
                          </div>
                          <div className="text-xs text-muted-foreground">Valor Atual</div>
                        </div>
                        <div className="text-center">
                          <div className="text-2xl font-bold text-success">
                            {alert.metrics.target_value.toFixed(alert.metrics.unit === '%' ? 2 : 0)}{alert.metrics.unit}
                          </div>
                          <div className="text-xs text-muted-foreground">Meta</div>
                        </div>
                        <div className="text-center">
                          <div className={`text-2xl font-bold ${alert.type === 'critical' ? 'text-destructive' : 'text-warning'}`}>
                            {((alert.metrics.current_value / alert.metrics.target_value - 1) * 100).toFixed(1)}%
                          </div>
                          <div className="text-xs text-muted-foreground">Desvio da Meta</div>
                        </div>
                      </div>
                    )}
                  </CardContent>
                </Card>
              );
            })
          )}
        </div>
      </div>
    </ReportLayout>
  );
};

