  const analyzeCampaigns = () => {
    // Filtrar apenas campanhas ativas
    const activeCampaigns = campaigns.filter(campaign => campaign.status === 'active');

    const analysis: CampaignAnalysis[] = activeCampaigns.map(campaign => {
      // Identificar problemas
      const issues: string[] = [];
      if (campaign.ctr < 1.5) issues.push(`CTR baixo: ${campaign.ctr.toFixed(2)}%`);
      if (campaign.cpa > 100) issues.push(`CPA alto: R$ ${campaign.cpa.toFixed(2)}`);
      if (campaign.conversions === 0) issues.push('Nenhuma conversão registrada');
      if (campaign.status === 'paused') issues.push('Campanha pausada');
      if (campaign.spend > 5000 && campaign.conversions < 10) issues.push('Alto investimento com poucas conversões');

      // Calcular eficiência
      const efficiency = campaign.ctr > 0 && campaign.cpa > 0 
        ? Math.round((campaign.ctr / campaign.cpa) * 1000) 
        : 0;

      // Determinar status
      const analysisStatus: CampaignAnalysis['analysisStatus'] = 
        (campaign.ctr < 1 || campaign.cpa > 150 || campaign.conversions === 0) ? 'critical' :
        (campaign.ctr < 1.5 || campaign.cpa > 100 || issues.length >= 2) ? 'needs_attention' :
        (campaign.ctr > 2 && campaign.cpa < 50) ? 'excellent' : 'good';

      // Gerar recomendações
      const recommendations: string[] = [];
      if (campaign.ctr < 1.5) recommendations.push('Otimizar criativos para aumentar CTR');
      if (campaign.cpa > 100) recommendations.push('Revisar audiência e estratégia de lances');
      if (campaign.conversions === 0) recommendations.push('Verificar tracking e pixel de conversão');
      if (campaign.status === 'paused') recommendations.push('Analisar motivo da pausa e reativar se possível');
      if (efficiency < 20) recommendations.push('Revisar estratégia geral da campanha');

      return {
        id: campaign.id,
        name: campaign.name,
        platforms: campaign.platforms,
        status: campaign.status,
        spend: campaign.spend,
        conversions: campaign.conversions,
        ctr: campaign.ctr,
        cpa: campaign.cpa,
        client_name: 'Cliente',
        analysisStatus,
        issues,
        recommendations,
        efficiency
      };
    });

    setCampaignsAnalysis(analysis);
  };

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = campaignsAnalysis;

    // Filtro por status de análise
    if (newFilters['status-analise'] && newFilters['status-analise'] !== 'todos') {
      filtered = filtered.filter(campaign => campaign.analysisStatus === newFilters['status-analise']);
    }

    // Filtro por cliente
    if (newFilters['cliente'] && newFilters['cliente'] !== 'todos') {
      filtered = filtered.filter(campaign => campaign.client_name?.includes(newFilters['cliente']));
    }

    // Filtro por status da campanha
    if (newFilters['status-campanha'] && newFilters['status-campanha'] !== 'todos') {
      filtered = filtered.filter(campaign => campaign.status === newFilters['status-campanha']);
    }

    // Filtro por tipo de problema
    if (newFilters['tipo-problema'] && newFilters['tipo-problema'] !== 'todos') {
      const problemMap: Record<string, string> = {
        'ctr_baixo': 'CTR baixo',
        'cpa_alto': 'CPA alto',
        'sem_conversoes': 'Nenhuma conversão',
        'pausada': 'pausada'
      };
      const problemText = problemMap[newFilters['tipo-problema']];
      if (problemText) {
        filtered = filtered.filter(campaign => campaign.issues.some(issue => issue.includes(problemText)));
      }
    }

    // Filtro por investimento mínimo
    if (newFilters['investimento-minimo'] && newFilters['investimento-minimo'] !== 'todos') {
      const minInvestment = parseInt(newFilters['investimento-minimo']);
      filtered = filtered.filter(campaign => campaign.spend >= minInvestment);
    }

    setFilteredData(filtered);
  };

  const handleCreateTask = async (campaign: CampaignAnalysis) => {
    const taskTitle = `Otimizar campanha: ${campaign.name}`;
    const taskDescription = `Problemas: ${campaign.issues.join(', ')}. Recomendações: ${campaign.recommendations.join(', ')}`;

    await convertAlertToTask({
      title: taskTitle,
      description: taskDescription,
      priority: campaign.analysisStatus === 'critical' ? 'high' : 'medium',
      type: 'optimization'
    });
  };

  const getStatusColor = (status: CampaignAnalysis['analysisStatus']) => {
    switch (status) {
      case 'excellent': return 'text-green-600';
      case 'good': return 'text-blue-600';
      case 'needs_attention': return 'text-yellow-600';
      case 'critical': return 'text-red-600';
      default: return 'text-gray-600';
    }
  };

  const getStatusBadge = (status: CampaignAnalysis['analysisStatus']) => {
    const variants = {
      excellent: 'default',
      good: 'secondary',
      needs_attention: 'outline',
      critical: 'destructive'
    } as const;

    const labels = {
      excellent: 'Excelente',
      good: 'Bom',
      needs_attention: 'Precisa de Atenção',
      critical: 'Crítico'
    };

    return (
      <Badge variant={variants[status]}>
        {labels[status]}
      </Badge>
    );
  };

  const getStatusIcon = (status: CampaignAnalysis['analysisStatus']) => {
    switch (status) {
      case 'excellent': return <CheckCircle className="w-4 h-4 text-green-600" />;
      case 'good': return <Target className="w-4 h-4 text-blue-600" />;
      case 'needs_attention': return <AlertCircle className="w-4 h-4 text-yellow-600" />;
      case 'critical': return <AlertTriangle className="w-4 h-4 text-red-600" />;
      default: return <Play className="w-4 h-4 text-gray-600" />;
    }
  };

  const getCampaignStatusIcon = (status: string) => {
    switch (status) {
      case 'active': return <Play className="w-4 h-4 text-green-600" />;
      case 'paused': return <Pause className="w-4 h-4 text-yellow-600" />;
      default: return <AlertCircle className="w-4 h-4 text-gray-600" />;
    }
  };

  const getCampaignStatusBadge = (status: string) => {
    const variants = {
      active: 'default',
      paused: 'outline',
      finished: 'secondary'
    } as const;

    const labels = {
      active: 'Ativa',
      paused: 'Pausada',
      finished: 'Finalizada'
    };

    return (
      <Badge variant={variants[status as keyof typeof variants] || 'secondary'}>
        {labels[status as keyof typeof labels] || status}
      </Badge>
    );
  };

  useEffect(() => {
    if (campaigns.length > 0) {
      analyzeCampaigns();
    }
  }, [campaigns]);

  useEffect(() => {
    setFilteredData(campaignsAnalysis);
  }, [campaignsAnalysis]);

  // Métricas de resumo baseadas nos dados filtrados
  const filteredMetrics = {
    totalCampaigns: filteredData.length,
    criticalCampaigns: filteredData.filter(c => c.analysisStatus === 'critical').length,
    totalSpend: filteredData.reduce((acc, c) => acc + c.spend, 0),
    avgCPA: filteredData.length > 0 
      ? filteredData.reduce((acc, c) => acc + c.cpa, 0) / filteredData.length
      : 0
  };

  return (
    <ReportLayout
      title="Relatório de Campanhas"
      description="Análise detalhada de performance e otimização de campanhas publicitárias"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Use os filtros para analisar campanhas específicas e identificar oportunidades de otimização"
    >
      {/* Métricas de resumo */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <MetricCard
          title="Total de Campanhas"
          value={filteredMetrics.totalCampaigns}
          subtitle="Campanhas analisadas"
        />
        <MetricCard
          title="Campanhas Críticas"
          value={filteredMetrics.criticalCampaigns}
          trend={filteredMetrics.criticalCampaigns > 0 ? "down" : "up"}
          subtitle="Precisam de atenção imediata"
        />
        <MetricCard
          title="Investimento Total"
          value={`R$ ${filteredMetrics.totalSpend.toLocaleString()}`}
          subtitle="Investimento analisado"
        />
        <MetricCard
          title="CPA Médio"
          value={`R$ ${filteredMetrics.avgCPA.toFixed(2)}`}
          trend={filteredMetrics.avgCPA <= 80 ? "up" : "down"}
          subtitle="Custo por aquisição"
        />
      </div>

      {/* Lista de campanhas analisadas */}
      <div className="grid gap-4">
        {filteredData.length > 0 ? (
          filteredData.map((campaign) => {
            const statusColor = campaign.analysisStatus === 'critical' ? 'border-l-destructive' :
                               campaign.analysisStatus === 'needs_attention' ? 'border-l-yellow-500' :
                               campaign.analysisStatus === 'good' ? 'border-l-blue-500' : 'border-l-green-500';

            return (
              <Card key={campaign.id} className={`border-l-4 ${statusColor}`}>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div className="space-y-2">
                      <div className="flex items-center gap-3">
                        {getStatusIcon(campaign.analysisStatus)}
                        <div>
                          <CardTitle className="text-lg">{campaign.name}</CardTitle>
                          <p className="text-sm text-muted-foreground">
                            {campaign.platforms} • {campaign.client_name || 'Cliente não especificado'}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        {getStatusBadge(campaign.analysisStatus)}
                        {getCampaignStatusBadge(campaign.status)}
                        <Badge variant="outline">
                          Score: {campaign.efficiency}/100
                        </Badge>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      {(campaign.analysisStatus === 'critical' || campaign.analysisStatus === 'needs_attention') && (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleCreateTask(campaign)}
                        >
                          <Target className="w-4 h-4 mr-2" />
                          Criar Tarefa
                        </Button>
                      )}
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  {/* Problemas Identificados */}
                  {campaign.issues.length > 0 && (
                    <div>
                      <h4 className="font-semibold mb-2 text-destructive">Problemas Identificados:</h4>
                      <ul className="space-y-1">
                        {campaign.issues.map((issue, index) => (
                          <li key={index} className="flex items-center gap-2 text-sm">
                            <AlertTriangle className="w-4 h-4 text-destructive" />
                            {issue}
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {/* Recomendação */}
                  {campaign.recommendations.length > 0 && (
                    <div>
                      <h4 className="font-semibold mb-2 text-primary">Recomendação:</h4>
                      <p className="text-sm bg-primary/10 p-3 rounded-lg">
                        {campaign.recommendations[0]}
                      </p>
                    </div>
                  )}

                  {/* Métricas Detalhadas */}
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 pt-4 border-t">
                    <div className="text-center">
                      <div className="text-2xl font-bold text-foreground">
                        R$ {campaign.spend.toLocaleString()}
                      </div>
                      <div className="text-xs text-muted-foreground">
                        Investimento Total
                      </div>
                    </div>
                    <div className="text-center">
                      <div className="text-2xl font-bold">
                        {campaign.conversions}
                      </div>
                      <div className="text-xs text-muted-foreground">
                        Conversões
                      </div>
                    </div>
                    <div className="text-center">
                      <div className={`text-2xl font-bold ${campaign.ctr >= 1.5 ? 'text-green-600' : 'text-destructive'}`}>
                        {campaign.ctr.toFixed(2)}%
                      </div>
                      <div className="text-xs text-muted-foreground">
                        CTR (Meta: &gt;1.5%)
                      </div>
                    </div>
                    <div className="text-center">
                      <div className={`text-2xl font-bold ${campaign.cpa <= 100 ? 'text-green-600' : 'text-destructive'}`}>
                        R$ {campaign.cpa.toFixed(0)}
                      </div>
                      <div className="text-xs text-muted-foreground">
                        CPA (Meta: &lt;R$ 100)
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })
        ) : (
          <Card>
            <CardContent className="text-center py-8">
              <Play className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
              <h3 className="text-lg font-medium text-foreground mb-2">
                Nenhuma campanha encontrada
              </h3>
              <p className="text-muted-foreground">
                Ajuste os filtros para ver mais resultados ou verifique se há campanhas cadastradas.
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </ReportLayout>
  );
};

export default RelatorioCampanhas;

import { useState, useEffect } from "react";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { AlertTriangle, Target, TrendingDown, DollarSign, BarChart3, Eye } from "lucide-react";
import { useCampaigns } from "@/hooks/useCampaigns";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { useClients } from "@/hooks/useClients";
import { CampaignMetricsModal } from "@/components/campaigns/CampaignMetricsModal";

interface InefficientCampaign {
  id: string;
  name: string;
  client_name: string;
  investment: number;
  conversions: number;
  cpa_current: number;
  cpa_target: number;
  roas_current: number;
  roas_minimum: number;
  efficiency_score: number;
  efficiency_rank: number;
  days_running: number;
  recommendation: string;
  issues: string[];
}

export default function RelatorioCampanhasIneficientes() {
  const { campaigns, loading } = useCampaigns();
  const { clients } = useClients();
  const { convertAlertToTask } = useTaskAutomation();
  const [inefficientCampaigns, setInefficientCampaigns] = useState<InefficientCampaign[]>([]);
  const [filteredData, setFilteredData] = useState<InefficientCampaign[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});
  const [selectedCampaign, setSelectedCampaign] = useState<unknown>(null);
  const [campaignMetricsModalOpen, setCampaignMetricsModalOpen] = useState(false);

  useEffect(() => {
    if (!loading && campaigns) {
      analyzeInefficientCampaigns();
    }
  }, [campaigns, loading]);

  useEffect(() => {
    setFilteredData(inefficientCampaigns);
  }, [inefficientCampaigns]);

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = [...inefficientCampaigns];

    // Filtro por cliente
    if (newFilters.cliente && newFilters.cliente !== 'todos') {
      filtered = filtered.filter(item => item.client_name === newFilters.cliente);
    }

    // Filtro por nível de ineficiência
    if (newFilters['nivel-ineficiencia'] && newFilters['nivel-ineficiencia'] !== 'todos') {
      switch (newFilters['nivel-ineficiencia']) {
        case 'critica':
          filtered = filtered.filter(item => item.efficiency_score < 30);
          break;
        case 'baixa':
          filtered = filtered.filter(item => item.efficiency_score >= 30 && item.efficiency_score < 60);
          break;
        case 'moderada':
          filtered = filtered.filter(item => item.efficiency_score >= 60);
          break;
      }
    }

    // Filtro por plataforma
    if (newFilters.plataforma && newFilters.plataforma !== 'todas') {
      // Como não temos plataforma no modelo, vamos simular baseado em dados disponíveis
      // Em um cenário real, seria filtrado por campaign.platform
      // Manter todos por enquanto - filtro de plataforma não implementado
    }

    // Filtro por CPA mínimo
    if (newFilters['cpa-minimo'] && newFilters['cpa-minimo'] !== 'sem-limite') {
      const minCPA = parseFloat(newFilters['cpa-minimo']);
      filtered = filtered.filter(item => item.cpa_current >= minCPA);
    }

    // Filtro por tipo de problema
    if (newFilters['tipo-problema'] && newFilters['tipo-problema'] !== 'todos') {
      const problemType = newFilters['tipo-problema'];
      filtered = filtered.filter(item => {
        switch (problemType) {
          case 'sem-conversao':
            return item.conversions === 0;
          case 'cpa-alto':
            return item.cpa_current > item.cpa_target;
          case 'roas-baixo':
            return item.roas_current < item.roas_minimum;
          case 'investimento-alto':
            return item.investment > 5000 && item.conversions < 5;
          default:
            return true;
        }
      });
    }

    // Filtro por período
    if (newFilters.periodo && newFilters.periodo !== 'todos') {
      const days = parseInt(newFilters.periodo);
      if (!isNaN(days)) {
        filtered = filtered.filter(item => item.days_running >= days);
      }
    }

    setFilteredData(filtered);
  };

  const analyzeInefficientCampaigns = () => {
    const inefficient: InefficientCampaign[] = [];

    // Filtrar apenas campanhas ativas
    const activeCampaigns = campaigns?.filter(campaign => 
      campaign.status === 'active' && campaign.is_active === true
    ) || [];

    activeCampaigns.forEach(campaign => {
      // Targets definidos (podem ser configuráveis por cliente)
      const cpaTarget = 150; // R$ 150 por conversão
      const roasMinimum = 3.0; // ROAS mínimo de 3:1

      const investment = campaign.spend || 0;
      const conversions = campaign.conversions || 0;
      const cpaCurrent = conversions > 0 ? investment / conversions : 0;

      // Simular valor das conversões (revenue)
      const avgOrderValue = 450; // Valor médio do pedido
      const revenue = conversions * avgOrderValue;
      const roasCurrent = investment > 0 ? revenue / investment : 0;

      // Calcular dias em execução (simulado)
      const daysRunning = Math.floor(Math.random() * 60) + 1;

      // Identificar problemas
      const issues: string[] = [];
      let efficiencyScore = 100;

      if (cpaCurrent > cpaTarget && conversions > 0) {
        issues.push(`CPA acima da meta (R$ ${cpaCurrent.toFixed(0)} vs R$ ${cpaTarget})`);
        efficiencyScore -= 30;
      }

      if (roasCurrent < roasMinimum && conversions > 0) {
        issues.push(`ROAS abaixo do mínimo (${roasCurrent.toFixed(1)}:1 vs ${roasMinimum}:1)`);
        efficiencyScore -= 30;
      }

      if (conversions === 0 && daysRunning > 7) {
        issues.push('Nenhuma conversão gerada');
        efficiencyScore -= 40;
      }

      if (investment > 5000 && conversions < 5) {
        issues.push('Alto investimento com poucas conversões');
        efficiencyScore -= 20;
      }

      // Só incluir campanhas com problemas
      if (issues.length === 0) return;

      // Gerar recomendação
      let recommendation = '';
      if (conversions === 0) {
        recommendation = 'Revisar completamente a estratégia de segmentação e criativos';
      } else if (cpaCurrent > cpaTarget * 1.5) {
        recommendation = 'Otimizar lances e melhorar qualidade dos leads';
      } else if (roasCurrent < roasMinimum * 0.5) {
        recommendation = 'Revisar landing page e processo de conversão';
      } else {
        recommendation = 'Ajustar segmentação e testar novos criativos';
      }

      inefficient.push({
        id: campaign.id,
        name: campaign.name,
        client_name: campaign.client?.name || 'Cliente não identificado',
        investment,
        conversions,
        cpa_current: cpaCurrent,
        cpa_target: cpaTarget,
        roas_current: roasCurrent,
        roas_minimum: roasMinimum,
        efficiency_score: Math.max(0, efficiencyScore),
        efficiency_rank: 0, // será definido após ordenação
        days_running: daysRunning,
        recommendation,
        issues
      });
    });

    // Ordenar por efficiency score (pior primeiro) e definir ranks
    const sorted = inefficient
      .sort((a, b) => a.efficiency_score - b.efficiency_score)
      .map((campaign, index) => ({
        ...campaign,
        efficiency_rank: index + 1
      }));

    setInefficientCampaigns(sorted);
  };

  const handleCreateTask = (campaign: InefficientCampaign) => {
    const alertData = {
      type: 'warning',
      description: `Campanha ineficiente: ${campaign.issues.join(', ')}`,
      campaign_id: campaign.id,
      client_id: undefined, // Será extraído do campaign_id no backend
      id: `inefficient_campaign_${campaign.id}`
    };

    convertAlertToTask(alertData);
  };

  const handleViewCampaignMetrics = (campaign: InefficientCampaign) => {
    // Encontrar a campanha original nos dados
    const originalCampaign = campaigns?.find(c => c.id === campaign.id);
    if (originalCampaign) {
      setSelectedCampaign({
        ...originalCampaign,
        created_at: originalCampaign.created_at || new Date().toISOString()
      });
      setCampaignMetricsModalOpen(true);
    }
  };

  const getEfficiencyColor = (score: number) => {
    if (score < 30) return 'text-destructive';
    if (score < 60) return 'text-warning';
    return 'text-success';
  };

  const getEfficiencyBadge = (score: number) => {
    if (score < 30) return { variant: 'destructive' as const, label: 'CRÍTICA' };
    if (score < 60) return { variant: 'secondary' as const, label: 'BAIXA' };
    return { variant: 'outline' as const, label: 'MODERADA' };
  };

  if (loading) {
    return (
      <ReportLayout
        title="Relatório de Campanhas Ineficientes"
        description="Campanhas que estão consumindo verba sem gerar resultados proporcionais"
      >
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="h-32 bg-muted animate-pulse rounded-lg" />
            ))}
          </div>
        </div>
      </ReportLayout>
    );
  }

  // Usar dados filtrados para métricas quando há filtros ativos
  const dataToUse = Object.keys(activeFilters).length > 0 ? filteredData : inefficientCampaigns;

  const totalWastedBudget = dataToUse.reduce((sum, c) => sum + c.investment, 0);
  const avgEfficiencyScore = dataToUse.length > 0 
    ? dataToUse.reduce((sum, c) => sum + c.efficiency_score, 0) / dataToUse.length 
    : 0;
  const criticalCampaigns = dataToUse.filter(c => c.efficiency_score < 30).length;
  const top5Worst = dataToUse.slice(0, 5);

  // Preparar dados únicos para filtros
  const uniqueClients = Array.from(new Set(inefficientCampaigns.map(c => c.client_name)))
    .sort()
    .map(name => ({ value: name, label: name }));

  const primaryFilters: FilterConfig[] = [
    {
      id: 'cliente',
      label: 'Cliente',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os clientes' },
        ...uniqueClients
      ],
      placeholder: 'Todos os clientes'
    },
    {
      id: 'nivel-ineficiencia',
      label: 'Nível de Ineficiência',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os níveis' },
        { value: 'critica', label: 'Crítica (< 30)' },
        { value: 'baixa', label: 'Baixa (30-60)' },
        { value: 'moderada', label: 'Moderada (> 60)' }
      ],
      placeholder: 'Todos os níveis'
    },
    {
      id: 'plataforma',
      label: 'Plataforma',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as plataformas' },
        { value: 'facebook', label: 'Facebook' },
        { value: 'google', label: 'Google Ads' },
        { value: 'instagram', label: 'Instagram' }
      ],
      placeholder: 'Todas as plataformas'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'cpa-minimo',
      label: 'CPA Mínimo',
      type: 'select',
      options: [
        { value: 'sem-limite', label: 'Sem limite' },
        { value: '100', label: 'R$ 100+' },
        { value: '200', label: 'R$ 200+' },
        { value: '300', label: 'R$ 300+' },
        { value: '500', label: 'R$ 500+' }
      ],
      placeholder: 'Sem limite'
    },
    {
      id: 'tipo-problema',
      label: 'Tipo de Problema',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os tipos' },
        { value: 'sem-conversao', label: 'Sem conversões' },
        { value: 'cpa-alto', label: 'CPA alto' },
        { value: 'roas-baixo', label: 'ROAS baixo' },
        { value: 'investimento-alto', label: 'Alto investimento' }
      ],
      placeholder: 'Todos os tipos'
    },
    {
      id: 'periodo',
      label: 'Período Mínimo (dias)',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os períodos' },
        { value: '7', label: '7+ dias' },
        { value: '15', label: '15+ dias' },
        { value: '30', label: '30+ dias' },
        { value: '60', label: '60+ dias' }
      ],
      placeholder: 'Todos os períodos'
    }
  ];

  return (
    <ReportLayout
      title="Relatório de Campanhas Ineficientes"
      description="Campanhas que estão consumindo verba sem gerar resultados proporcionais"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Configure os parâmetros para análise de campanhas ineficientes"
    >
      <div className="space-y-6">
        {/* Resumo */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <MetricCard
            title="Campanhas Críticas"
            value={criticalCampaigns}
            trend={criticalCampaigns > 0 ? "down" : "neutral"}
            subtitle="Score < 30"
          />
          <MetricCard
            title="Verba Desperdiçada"
            value={`R$ ${totalWastedBudget.toLocaleString()}`}
            trend="down"
            subtitle="Total investido"
          />
          <MetricCard
            title="Score Médio"
            value={`${avgEfficiencyScore.toFixed(0)}/100`}
            trend={avgEfficiencyScore < 50 ? "down" : avgEfficiencyScore > 70 ? "up" : "neutral"}
            subtitle="Eficiência geral"
          />
          <MetricCard
            title="Total Ineficientes"
            value={dataToUse.length}
            subtitle="Campanhas identificadas"
          />
        </div>

        {/* Lista Detalhada de Campanhas */}
        <div className="grid gap-4">
          {filteredData.length === 0 ? (
            <Card>
              <CardContent className="p-6 text-center">
                <BarChart3 className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
                <h3 className="text-lg font-semibold mb-2">Nenhuma campanha ineficiente detectada</h3>
                <p className="text-muted-foreground">
                  {Object.keys(activeFilters).length > 0 
                    ? 'Nenhuma campanha corresponde aos filtros selecionados.'
                    : 'Todas as campanhas estão com performance dentro dos parâmetros esperados.'
                  }
                </p>
              </CardContent>
            </Card>
          ) : (
            filteredData.map((campaign) => {
              const efficiencyBadge = getEfficiencyBadge(campaign.efficiency_score);

              return (
                <Card key={campaign.id} className="border-l-4 border-l-destructive">
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <div className="space-y-2">
                        <div className="flex items-center gap-3">
                          <AlertTriangle className="w-5 h-5 text-destructive" />
                          <div>
                            <CardTitle className="text-lg">{campaign.name}</CardTitle>
                            <p className="text-sm text-muted-foreground">
                              {campaign.client_name} • {campaign.days_running} dias ativa
                            </p>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <Badge variant={efficiencyBadge.variant}>
                            EFICIÊNCIA {efficiencyBadge.label}
                          </Badge>
                          <Badge variant="outline">
                            #{campaign.efficiency_rank} pior campanha
                          </Badge>
                          <Badge variant="outline">
                            Score: {campaign.efficiency_score}/100
                          </Badge>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleCreateTask(campaign)}
                        >
                          <Target className="w-4 h-4 mr-2" />
                          Criar Tarefa
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleViewCampaignMetrics(campaign)}
                        >
                          <Eye className="w-4 h-4 mr-2" />
                          Ver Detalhes
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    {/* Problemas Identificados */}
                    <div>
                      <h4 className="font-semibold mb-2 text-destructive">Problemas Identificados:</h4>
                      <ul className="space-y-1">
                        {campaign.issues.map((issue, index) => (
                          <li key={index} className="flex items-center gap-2 text-sm">
                            <TrendingDown className="w-4 h-4 text-destructive" />
                            {issue}
                          </li>
                        ))}
                      </ul>
                    </div>

                    {/* Recomendação */}
                    <div>
                      <h4 className="font-semibold mb-2 text-primary">Recomendação:</h4>
                      <p className="text-sm bg-primary/10 p-3 rounded-lg">
                        {campaign.recommendation}
                      </p>
                    </div>

                    {/* Métricas Detalhadas */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 pt-4 border-t">
                      <div className="text-center">
                        <div className="text-2xl font-bold text-destructive">
                          R$ {campaign.investment.toLocaleString()}
                        </div>
                        <div className="text-xs text-muted-foreground">
                          Investimento Total
                        </div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold">
                          {campaign.conversions}
                        </div>
                        <div className="text-xs text-muted-foreground">
                          Conversões
                        </div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-destructive">
                          R$ {campaign.cpa_current > 0 ? campaign.cpa_current.toFixed(0) : '0'}
                        </div>
                        <div className="text-xs text-muted-foreground">
                          CPA (Meta: R$ {campaign.cpa_target})
                        </div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-destructive">
                          {campaign.roas_current.toFixed(1)}:1
                        </div>
                        <div className="text-xs text-muted-foreground">
                          ROAS (Min: {campaign.roas_minimum}:1)
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              );
            })
          )}
        </div>
      </div>

      {/* Campaign Metrics Modal */}
      <CampaignMetricsModal
        campaign={selectedCampaign}
        isOpen={campaignMetricsModalOpen}
        onClose={() => setCampaignMetricsModalOpen(false)}
      />
    </ReportLayout>
  );
}

import { useState, useEffect } from "react";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { AlertTriangle, TrendingDown, Target, Users } from "lucide-react";
import { useClients } from "@/hooks/useClients";
import { useCampaigns } from "@/hooks/useCampaigns";
import { TaskSuggestionsModal } from "@/components/clients/TaskSuggestionsModal";

interface CriticalClient {
  id: string;
  name: string;
  status: 'critical' | 'warning';
  issues: string[];
  cpl_current: number;
  cpl_target: number;
  cpa_current: number;
  cpa_target: number;
  ctr: number;
  frequency: number;
  cpc_current: number;
  problematic_campaigns: string[];
  ai_recommendations: string[];
}

export default function RelatorioClientesZonaCritica() {
  const { clients, loading: clientsLoading } = useClients();
  const { campaigns, loading: campaignsLoading } = useCampaigns();
  const [criticalClients, setCriticalClients] = useState<CriticalClient[]>([]);
  const [filteredData, setFilteredData] = useState<CriticalClient[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});
  const [selectedClient, setSelectedClient] = useState<CriticalClient | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    if (!clientsLoading && !campaignsLoading && clients && campaigns) {
      analyzeCriticalClients();
    }
  }, [clients, campaigns, clientsLoading, campaignsLoading]);

  useEffect(() => {
    setFilteredData(criticalClients);
  }, [criticalClients]);

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = [...criticalClients];

    // Filtro por status
    if (newFilters.status && newFilters.status !== 'todos') {
      filtered = filtered.filter(client => client.status === newFilters.status);
    }

    // Filtro por tipo de problema
    if (newFilters['tipo-problema'] && newFilters['tipo-problema'] !== 'todos') {
      const problemType = newFilters['tipo-problema'];
      filtered = filtered.filter(client => {
        switch (problemType) {
          case 'sem-campanhas':
            return client.issues.some(issue => issue.includes('Sem campanhas ativas'));
          case 'cpa-alto':
            return client.issues.some(issue => issue.includes('CPA'));
          case 'ctr-baixo':
            return client.issues.some(issue => issue.includes('CTR'));
          case 'frequencia-alta':
            return client.issues.some(issue => issue.includes('Frequência'));
          case 'sem-leads':
            return client.issues.some(issue => issue.includes('sem nenhum lead'));
          default:
            return true;
        }
      });
    }

    // Filtro por nível de criticidade (número de problemas)
    if (newFilters['nivel-criticidade'] && newFilters['nivel-criticidade'] !== 'todos') {
      const level = newFilters['nivel-criticidade'];
      filtered = filtered.filter(client => {
        switch (level) {
          case 'muito-critico':
            return client.issues.length >= 4;
          case 'critico':
            return client.issues.length === 3;
          case 'moderado':
            return client.issues.length <= 2;
          default:
            return true;
        }
      });
    }

    // Filtro por valor de CPA
    if (newFilters['cpa-limite'] && newFilters['cpa-limite'] !== 'sem-limite') {
      const cpaLimit = parseFloat(newFilters['cpa-limite']);
      filtered = filtered.filter(client => client.cpa_current >= cpaLimit);
    }

    setFilteredData(filtered);
  };

  const analyzeCriticalClients = () => {
    const critical: CriticalClient[] = [];

    clients?.forEach(client => {
      // IMPORTANTE: Filtrar apenas campanhas ATIVAS para cálculo das métricas
      const clientCampaigns = campaigns?.filter(c => c.client_id === client.id && c.status === 'active') || [];
      const issues: string[] = [];
      const problematicCampaigns: string[] = [];

      // PRIORIDADE MÁXIMA: Clientes sem campanhas ativas
      if (clientCampaigns.length === 0) {
        critical.push({
          id: client.id,
          name: client.name,
          status: 'critical',
          issues: ['Sem campanhas ativas'],
          cpl_current: 0,
          cpl_target: 50,
          cpa_current: 0,
          cpa_target: 150,
          ctr: 0,
          frequency: 0,
          cpc_current: 0,
          problematic_campaigns: [],
          ai_recommendations: [
            'URGENTE: Ativar campanhas imediatamente',
            'Revisar estratégia de marketing do cliente',
            'Agendar reunião para reativação'
          ]
        });
        return; // Pular análise de métricas para clientes sem campanhas
      }

      // ===== CÁLCULO DAS MÉTRICAS APENAS COM CAMPANHAS ATIVAS =====
      const totalSpend = clientCampaigns.reduce((sum, c) => sum + (c.spend || 0), 0);
      const totalConversions = clientCampaigns.reduce((sum, c) => sum + (c.conversions || 0), 0);
      const totalClicks = clientCampaigns.reduce((sum, c) => sum + (c.clicks || 0), 0);
      const totalImpressions = clientCampaigns.reduce((sum, c) => sum + (c.impressions || 0), 0);
      const totalReach = clientCampaigns.reduce((sum, c) => sum + (c.reach || 0), 0);

      // Calcular métricas agregadas do cliente (APENAS campanhas ativas)
      const avgCPA = totalConversions > 0 ? totalSpend / totalConversions : 0;
      const avgCPL = totalClicks > 0 ? totalSpend / totalClicks : 0; // CPL = Custo por Lead/Click
      const avgCTR = totalImpressions > 0 ? (totalClicks / totalImpressions) * 100 : 0; // CTR em %
      const avgFrequency = totalReach > 0 ? totalImpressions / totalReach : 0; // Frequência = Impressões / Alcance
      const avgCPC = totalClicks > 0 ? totalSpend / totalClicks : 0; // CPC = Custo por Clique (mesmo que CPL)

      // Definir targets baseados em benchmarks da indústria
      const cplTarget = 50; // R$ 50 por lead (benchmark padrão)
      const cpaTarget = 150; // R$ 150 por conversão (benchmark padrão)
      const ctrTarget = 1; // 1% CTR mínimo (benchmark padrão)
      const frequencyMax = 5; // Frequência máxima 5 (benchmark padrão)
      const maxSpendWithoutLeads = 150; // R$ 150 máximo sem leads

      // ===== VERIFICAÇÕES DE PROBLEMAS =====

      // 1. Verificar se tem campanhas ativas mas NENHUMA gerou leads
      const hasActiveCampaignsWithoutLeads = clientCampaigns.length > 0 && totalConversions === 0;
      if (hasActiveCampaignsWithoutLeads) {
        issues.push(`Campanhas ativas sem nenhum lead gerado (${clientCampaigns.length} campanhas) - Gasto total: R$ ${totalSpend.toFixed(0)}`);
      }

      // 2. Verificar campanhas que gastaram mais de R$ 150 sem leads
      const campaignsWithHighSpendNoLeads = clientCampaigns.filter(campaign => 
        campaign.spend > maxSpendWithoutLeads && (campaign.conversions || 0) === 0
      );
      if (campaignsWithHighSpendNoLeads.length > 0) {
        const totalWastedSpend = campaignsWithHighSpendNoLeads.reduce((sum, c) => sum + (c.spend || 0), 0);
        issues.push(`${campaignsWithHighSpendNoLeads.length} campanha(s) gastaram R$ ${totalWastedSpend.toFixed(0)} sem leads`);
      }

      // 3. Verificar CPL acima da meta (apenas se houver conversões)
      if (totalConversions > 0 && avgCPL > cplTarget) {
        issues.push(`CPL acima da meta (R$ ${avgCPL.toFixed(2)} vs R$ ${cplTarget})`);
      }

      // 4. Verificar CPA acima da meta (apenas se houver conversões)
      if (totalConversions > 0 && avgCPA > cpaTarget) {
        issues.push(`CPA acima da meta (R$ ${avgCPA.toFixed(2)} vs R$ ${cpaTarget})`);
      }

      // 5. Verificar CTR abaixo do mínimo
      if (avgCTR < ctrTarget) {
        issues.push(`CTR abaixo do mínimo (${avgCTR.toFixed(2)}% vs ${ctrTarget}%)`);
      }

      // 6. Verificar frequência muito alta
      if (avgFrequency > frequencyMax) {
        issues.push(`Frequência muito alta (${avgFrequency.toFixed(1)} vs ${frequencyMax})`);
      }

      // Identificar campanhas problemáticas e com CPA crítico
      const criticalCPAThreshold = cpaTarget; // CPA crítico: acima da meta (R$ 150)
      let hasCriticalCPACampaigns = false;

      clientCampaigns.forEach(campaign => {
        const campaignCPA = campaign.conversions > 0 ? campaign.spend / campaign.conversions : 0;
        const campaignCTR = campaign.impressions > 0 ? (campaign.clicks / campaign.impressions) * 100 : 0;

        // Verificar se campanha tem CPA crítico
        if (campaignCPA > criticalCPAThreshold) {
          hasCriticalCPACampaigns = true;
        }

        if (campaignCPA > cpaTarget || campaignCTR < ctrTarget) {
          problematicCampaigns.push(campaign.name);
        }
      });

      // Adicionar alerta específico para CPA crítico
      if (hasCriticalCPACampaigns) {
        issues.push(`Campanhas com CPA crítico (acima de R$ ${criticalCPAThreshold})`);
      }

      if (issues.length > 0) {
        const status = issues.length >= 3 ? 'critical' : 'warning';

        critical.push({
          id: client.id,
          name: client.name,
          status,
          issues,
          cpl_current: avgCPL,
          cpl_target: cplTarget,
          cpa_current: avgCPA,
          cpa_target: cpaTarget,
          ctr: avgCTR,
          frequency: avgFrequency,
          cpc_current: avgCPC,
          problematic_campaigns: problematicCampaigns,
          ai_recommendations: generateRecommendations(issues, avgCPA, avgCTR, avgFrequency)
        });
      }
    });

    // Ordenar com clientes sem campanhas no topo
    setCriticalClients(critical.sort((a, b) => {
      // Prioridade 1: Clientes sem campanhas ativas (issues contém 'Sem campanhas ativas')
      const aHasNoCampaigns = a.issues.includes('Sem campanhas ativas');
      const bHasNoCampaigns = b.issues.includes('Sem campanhas ativas');

      if (aHasNoCampaigns && !bHasNoCampaigns) return -1;
      if (!aHasNoCampaigns && bHasNoCampaigns) return 1;

      // Prioridade 2: Status crítico
      if (a.status === 'critical' && b.status !== 'critical') return -1;
      if (b.status === 'critical' && a.status !== 'critical') return 1;

      // Prioridade 3: Número de problemas
      return b.issues.length - a.issues.length;
    }));
  };

  const generateRecommendations = (issues: string[], cpa: number, ctr: number, frequency: number): string[] => {
    const recommendations: string[] = [];

    if (issues.some(i => i.includes('CPA'))) {
      recommendations.push('Revisar segmentação de audiência para reduzir CPA');
      recommendations.push('Testar novos criativos com maior apelo');
    }

    if (issues.some(i => i.includes('CTR'))) {
      recommendations.push('Atualizar criativos para melhorar engajamento');
      recommendations.push('Refinar targeting para audiência mais qualificada');
    }

    if (issues.some(i => i.includes('Frequência'))) {
      recommendations.push('Expandir audiência para reduzir frequência');
      recommendations.push('Implementar rotação de criativos');
    }

    if (issues.some(i => i.includes('CPL'))) {
      recommendations.push('Otimizar landing pages para melhor conversão');
      recommendations.push('Revisar estratégia de lances');
    }

    return recommendations;
  };

  const handleCreateTask = (client: CriticalClient) => {
    setSelectedClient(client);
    setIsModalOpen(true);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'critical': return 'bg-destructive text-destructive-foreground';
      case 'warning': return 'bg-warning text-warning-foreground';
      default: return 'bg-muted text-muted-foreground';
    }
  };

  const getStatusIcon = (status: string) => {
    return status === 'critical' ? AlertTriangle : TrendingDown;
  };

  if (clientsLoading || campaignsLoading) {
    return (
      <ReportLayout
        title="Relatório de Clientes em Zona Crítica"
        description="Identificação de clientes com campanhas problemáticas"
      >
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="h-32 bg-muted animate-pulse rounded-lg" />
            ))}
          </div>
        </div>
      </ReportLayout>
    );
  }

  // Usar dados filtrados para métricas quando há filtros ativos
  const dataToUse = Object.keys(activeFilters).length > 0 ? filteredData : criticalClients;

  const criticalCount = dataToUse.filter(c => c.status === 'critical').length;
  const warningCount = dataToUse.filter(c => c.status === 'warning').length;
  const totalIssues = dataToUse.reduce((sum, c) => sum + c.issues.length, 0);

  // Configurar filtros
  const primaryFilters: FilterConfig[] = [
    {
      id: 'status',
      label: 'Status',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os status' },
        { value: 'critical', label: 'Crítico' },
        { value: 'warning', label: 'Alerta' }
      ],
      placeholder: 'Todos os status'
    },
    {
      id: 'tipo-problema',
      label: 'Tipo de Problema',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os tipos' },
        { value: 'sem-campanhas', label: 'Sem campanhas ativas' },
        { value: 'cpa-alto', label: 'CPA alto' },
        { value: 'ctr-baixo', label: 'CTR baixo' },
        { value: 'frequencia-alta', label: 'Frequência alta' },
        { value: 'sem-leads', label: 'Sem leads' }
      ],
      placeholder: 'Todos os tipos'
    },
    {
      id: 'nivel-criticidade',
      label: 'Nível de Criticidade',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os níveis' },
        { value: 'muito-critico', label: 'Muito crítico (4+ problemas)' },
        { value: 'critico', label: 'Crítico (3 problemas)' },
        { value: 'moderado', label: 'Moderado (1-2 problemas)' }
      ],
      placeholder: 'Todos os níveis'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'cpa-limite',
      label: 'CPA Mínimo',
      type: 'select',
      options: [
        { value: 'sem-limite', label: 'Sem limite' },
        { value: '100', label: 'R$ 100+' },
        { value: '150', label: 'R$ 150+' },
        { value: '200', label: 'R$ 200+' },
        { value: '300', label: 'R$ 300+' }
      ],
      placeholder: 'Sem limite'
    }
  ];

  return (
    <ReportLayout
      title="Relatório de Clientes em Zona Crítica"
      description="Identificação de clientes com campanhas problemáticas"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Configure os parâmetros para análise de clientes em zona crítica"
    >
      <div className="space-y-6">
        {/* Resumo */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <MetricCard
            title="Clientes Críticos"
            value={criticalCount}
            trend={criticalCount > 0 ? "down" : "neutral"}
            subtitle="Status vermelho"
          />
          <MetricCard
            title="Clientes em Alerta"
            value={warningCount}
            trend={warningCount > 0 ? "down" : "neutral"}
            subtitle="Status amarelo"
          />
          <MetricCard
            title="Total de Problemas"
            value={totalIssues}
            subtitle="Identificados"
          />
          <MetricCard
            title="Taxa de Criticidade"
            value={`${((criticalCount + warningCount) / (clients?.length || 1) * 100).toFixed(1)}%`}
            trend={(criticalCount + warningCount) > 0 ? "down" : "up"}
            subtitle="Do total de clientes"
          />
        </div>

        {/* Lista de Clientes Críticos */}
        <div className="grid gap-4">
          {filteredData.length === 0 ? (
            <Card>
              <CardContent className="p-6 text-center">
                <Users className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
                <h3 className="text-lg font-semibold mb-2">Nenhum cliente encontrado</h3>
                <p className="text-muted-foreground">
                  {Object.keys(activeFilters).length > 0 
                    ? 'Nenhum cliente corresponde aos filtros selecionados.'
                    : 'Todos os clientes estão com performance dentro dos parâmetros esperados.'
                  }
                </p>
              </CardContent>
            </Card>
          ) : (
            filteredData.map((client) => {
              const StatusIcon = getStatusIcon(client.status);

              return (
                <Card key={client.id} className={`border-l-4 ${client.status === 'critical' ? 'border-l-destructive' : 'border-l-warning'}`}>
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <StatusIcon className={`w-5 h-5 ${client.status === 'critical' ? 'text-destructive' : 'text-warning'}`} />
                        <div>
                          <CardTitle className="text-lg">{client.name}</CardTitle>
                          <Badge className={getStatusColor(client.status)}>
                            {client.status === 'critical' ? 'CRÍTICO' : 'ALERTA'}
                          </Badge>
                        </div>
                      </div>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleCreateTask(client)}
                      >
                        <Target className="w-4 h-4 mr-2" />
                        Criar Tarefa
                      </Button>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-4">
                     {/* Problemas Identificados */}
                     <div>
                       <h4 className={`font-semibold mb-2 ${client.status === 'critical' ? 'text-destructive' : 'text-warning'}`}>Problemas Identificados:</h4>
                       <ul className="space-y-1">
                         {client.issues.map((issue, index) => (
                           <li key={index} className="flex items-center gap-2 text-sm">
                             <AlertTriangle className={`w-4 h-4 ${client.status === 'critical' ? 'text-destructive' : 'text-warning'}`} />
                             {issue}
                           </li>
                         ))}
                       </ul>
                     </div>

                     {/* Campanhas Problemáticas */}
                     {client.problematic_campaigns.length > 0 && (
                       <div>
                         <h4 className="font-semibold mb-2">Campanhas Responsáveis:</h4>
                         <div className="flex flex-wrap gap-2">
                           {client.problematic_campaigns.map((campaign, index) => (
                             <Badge key={index} variant="secondary">
                               {campaign}
                             </Badge>
                           ))}
                         </div>
                       </div>
                     )}

                     {/* Recomendações da IA */}
                     <div>
                       <h4 className="font-semibold mb-2 text-primary">Recomendações da IA:</h4>
                       <ul className="space-y-1">
                         {client.ai_recommendations.map((recommendation, index) => (
                           <li key={index} className="flex items-start gap-2 text-sm">
                             <div className="w-2 h-2 bg-primary rounded-full mt-2 flex-shrink-0" />
                             {recommendation}
                           </li>
                         ))}
                       </ul>
                     </div>

                     {/* Métricas Detalhadas */}
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-4 pt-4 border-t">
                       <div className="text-center">
                         <div className={`text-2xl font-bold ${client.status === 'critical' ? 'text-destructive' : 'text-warning'}`}>
                           R$ {client.cpl_current.toFixed(0)}
                         </div>
                         <div className="text-xs text-muted-foreground">
                           CPL (Meta: R$ {client.cpl_target})
                         </div>
                       </div>
                       <div className="text-center">
                         <div className={`text-2xl font-bold ${client.status === 'critical' ? 'text-destructive' : 'text-warning'}`}>
                           {client.ctr.toFixed(2)}%
                         </div>
                         <div className="text-xs text-muted-foreground">
                           CTR (Min: 1%)
                         </div>
                       </div>
                       <div className="text-center">
                         <div className={`text-2xl font-bold ${client.status === 'critical' ? 'text-destructive' : 'text-warning'}`}>
                           {client.frequency.toFixed(1)}x
                         </div>
                         <div className="text-xs text-muted-foreground">
                           Frequência (Max: 5x)
                         </div>
                       </div>
                        <div className="text-center">
                          <div className={`text-2xl font-bold ${client.status === 'critical' ? 'text-destructive' : 'text-warning'}`}>
                            R$ {client.cpc_current.toFixed(2)}
                          </div>
                          <div className="text-xs text-muted-foreground">
                            CPC Médio
                          </div>
                        </div>
                     </div>
                  </CardContent>
                </Card>
              );
            })
          )}
        </div>
      </div>

      {/* Modal de Sugestões */}
      {selectedClient && (
        <TaskSuggestionsModal
          isOpen={isModalOpen}
          onClose={() => {
            setIsModalOpen(false);
            setSelectedClient(null);
          }}
          client={selectedClient}
        />
      )}
    </ReportLayout>
  );
}

import { useState, useEffect } from "react";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { AlertTriangle, Target, TrendingDown, Image, Eye } from "lucide-react";
import { useAds } from "@/hooks/useAds";
import { useCampaigns } from "@/hooks/useCampaigns";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { AdCreativeMetricsModal } from "@/components/ads/AdCreativeMetricsModal";

interface LowPerformingCreative {
  id: string;
  name: string;
  campaign_id: string;
  campaign_name: string;
  campaign_status: 'active' | 'paused' | 'finished' | 'deleted';
  campaign_is_active: boolean;
  client_id: string;
  client_name: string;
  ctr: number;
  cpc: number;
  cpl: number;
  conversions: number;
  spend: number;
  days_active: number;
  status: 'critical' | 'warning' | 'underperforming';
  recommendation: 'pause' | 'adjust' | 'replace';
  recommendation_reason: string;
  performance_score: number;
  // Benchmarks ideais
  ideal_ctr: number;
  ideal_cpc: number;
  ideal_cpl: number;
}

export default function RelatorioCriativosBaixoDesempenho() {
  const { ads, loading: adsLoading } = useAds();
  const { campaigns, loading: campaignsLoading } = useCampaigns();
  const { convertAlertToTask } = useTaskAutomation();
  const [lowPerformingCreatives, setLowPerformingCreatives] = useState<LowPerformingCreative[]>([]);
  const [filteredData, setFilteredData] = useState<LowPerformingCreative[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});
  const [selectedAd, setSelectedAd] = useState<unknown>(null);
  const [adCreativeMetricsModalOpen, setAdCreativeMetricsModalOpen] = useState(false);

  useEffect(() => {
    if (!adsLoading && !campaignsLoading && ads && campaigns) {
      analyzeLowPerformingCreatives();
    }
  }, [ads, campaigns, adsLoading, campaignsLoading]);

  useEffect(() => {
    setFilteredData(lowPerformingCreatives);
  }, [lowPerformingCreatives]);

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = [...lowPerformingCreatives];

    // Filtro por cliente
    if (newFilters.cliente && newFilters.cliente !== 'todos') {
      filtered = filtered.filter(item => item.client_name === newFilters.cliente);
    }

    // Filtro por tipo de criativo
    if (newFilters['tipo-criativo'] && newFilters['tipo-criativo'] !== 'todos') {
      // Como não temos tipo no modelo, vamos simular baseado em dados disponíveis
      // Manter todos por enquanto - filtro de tipo de criativo não implementado
    }

    // Filtro por performance mínima (score)
    if (newFilters['performance-minima'] && newFilters['performance-minima'] !== 'sem-limite') {
      const minScore = parseInt(newFilters['performance-minima']);
      filtered = filtered.filter(item => item.performance_score <= minScore);
    }

    // Filtro por período
    if (newFilters.periodo && newFilters.periodo !== 'todos') {
      const days = parseInt(newFilters.periodo);
      if (!isNaN(days)) {
        filtered = filtered.filter(item => item.days_active >= days);
      }
    }

    // Filtro por status
    if (newFilters.status && newFilters.status !== 'todos') {
      filtered = filtered.filter(item => item.status === newFilters.status);
    }

    // Filtro por recomendação
    if (newFilters.recomendacao && newFilters.recomendacao !== 'todas') {
      filtered = filtered.filter(item => item.recommendation === newFilters.recomendacao);
    }

    // Filtro por status da campanha
    if (newFilters['status-campanha'] && newFilters['status-campanha'] !== 'todos') {
      filtered = filtered.filter(item => item.campaign_status === newFilters['status-campanha']);
    }

    setFilteredData(filtered);
  };

  const handleCreateTask = (creative: LowPerformingCreative) => {
    const alertData = {
      type: 'warning',
      description: `Criativo com baixo desempenho: Score ${creative.performance_score}/100 - ${creative.recommendation_reason}`,
      campaign_id: creative.campaign_id,
      client_id: creative.client_id,
      id: `low_performing_creative_${creative.id}`
    };

    convertAlertToTask(alertData);
  };

  const handleViewAdCreativeMetrics = (creative: LowPerformingCreative) => {
    // Encontrar o anúncio original nos dados
    const originalAd = ads?.find(ad => ad.id === creative.id);
    if (originalAd) {
      setSelectedAd(originalAd);
      setAdCreativeMetricsModalOpen(true);
    }
  };

  const analyzeLowPerformingCreatives = () => {
    const lowPerforming: LowPerformingCreative[] = [];

    // Filtrar campanhas ativas apenas (padrão)
    const activeCampaigns = campaigns?.filter(c => 
      c.status === 'active' && c.is_active === true
    ) || [];

    // Calcular benchmarks globais apenas de campanhas ativas
    const activeAds = ads?.filter(ad => 
      activeCampaigns.some(c => c.id === ad.campaign_id)
    ) || [];

    const totalImpressions = activeAds.reduce((sum, ad) => sum + (ad.impressions || 0), 0);
    const totalClicks = activeAds.reduce((sum, ad) => sum + (ad.clicks || 0), 0);
    const totalSpend = activeAds.reduce((sum, ad) => sum + (ad.spend || 0), 0);
    const totalConversions = activeAds.reduce((sum, ad) => sum + (ad.conversions || 0), 0);

    const avgCTR = totalImpressions > 0 ? (totalClicks / totalImpressions) * 100 : 0;
    const avgCPC = totalClicks > 0 ? totalSpend / totalClicks : 0;
    const avgCPL = totalConversions > 0 ? totalSpend / totalConversions : 0;

    // Definir thresholds (50% abaixo da média)
    const ctrThreshold = avgCTR * 0.5;
    const cpcThreshold = avgCPC * 1.5; // 50% acima da média
    const cplThreshold = avgCPL * 1.5; // 50% acima da média

    // Analisar apenas anúncios de campanhas ativas
    activeAds.forEach(ad => {
      const campaign = activeCampaigns.find(c => c.id === ad.campaign_id);
      if (!campaign) return;

      const adCTR = ad.impressions > 0 ? (ad.clicks / ad.impressions) * 100 : 0;
      const adCPC = ad.clicks > 0 ? ad.spend / ad.clicks : 0;
      const adCPL = ad.conversions > 0 ? ad.spend / ad.conversions : 0;

      // Calcular dias ativos (simulado)
      const daysActive = Math.floor(Math.random() * 30) + 1;

      // Avaliar performance
      let issues = 0;
      let status: 'critical' | 'warning' | 'underperforming' = 'underperforming';
      let recommendation: 'pause' | 'adjust' | 'replace' = 'adjust';
      let recommendationReason = '';

      // Verificar problemas
      const problems: string[] = [];

      if (adCTR < ctrThreshold) {
        issues++;
        problems.push('CTR baixo');
      }

      if (adCPC > cpcThreshold) {
        issues++;
        problems.push('CPC alto');
      }

      if (adCPL > cplThreshold && ad.conversions > 0) {
        issues++;
        problems.push('CPL alto');
      }

      if (ad.conversions === 0 && daysActive > 7) {
        issues++;
        problems.push('Sem conversões');
      }

      // Só incluir se tiver problemas
      if (issues === 0) return;

      // Definir status baseado na severidade
      if (issues >= 3 || (ad.conversions === 0 && daysActive > 14)) {
        status = 'critical';
        recommendation = 'pause';
        recommendationReason = 'Performance muito baixa, pausar imediatamente';
      } else if (issues >= 2 || daysActive > 21) {
        status = 'warning';
        recommendation = 'replace';
        recommendationReason = 'Substituir por novos criativos';
      } else {
        recommendation = 'adjust';
        recommendationReason = 'Ajustar segmentação ou lances';
      }

      // Calcular score de performance (0-100)
      let performanceScore = 100;
      if (adCTR < ctrThreshold) performanceScore -= 25;
      if (adCPC > cpcThreshold) performanceScore -= 25;
      if (adCPL > cplThreshold) performanceScore -= 25;
      if (ad.conversions === 0 && daysActive > 7) performanceScore -= 25;

      lowPerforming.push({
        id: ad.id,
        name: ad.name,
        campaign_id: campaign.id,
        campaign_name: campaign.name,
        campaign_status: campaign.status,
        campaign_is_active: campaign.is_active,
        client_id: campaign.client_id,
        client_name: campaign.client?.name || 'Cliente não identificado',
        ctr: adCTR,
        cpc: adCPC,
        cpl: adCPL,
        conversions: ad.conversions,
        spend: ad.spend,
        days_active: daysActive,
        status,
        recommendation,
        recommendation_reason: recommendationReason,
        performance_score: Math.max(0, performanceScore),
        // Benchmarks ideais calculados
        ideal_ctr: avgCTR,
        ideal_cpc: avgCPC,
        ideal_cpl: avgCPL
      });
    });

    // Ordenar por performance score (pior primeiro)
    setLowPerformingCreatives(
      lowPerforming.sort((a, b) => a.performance_score - b.performance_score)
    );
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'critical': return 'bg-destructive text-destructive-foreground';
      case 'warning': return 'bg-warning text-warning-foreground';
      default: return 'bg-secondary text-secondary-foreground';
    }
  };

  const getRecommendationColor = (recommendation: string) => {
    switch (recommendation) {
      case 'pause': return 'text-destructive';
      case 'replace': return 'text-warning';
      default: return 'text-primary';
    }
  };


  if (adsLoading || campaignsLoading) {
    return (
      <ReportLayout
        title="Relatório de Criativos de Baixo Desempenho"
        description="Identificação de anúncios que estão queimando verba sem retorno"
      >
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="h-32 bg-muted animate-pulse rounded-lg" />
            ))}
          </div>
        </div>
      </ReportLayout>
    );
  }

  // Usar dados filtrados para métricas quando há filtros ativos
  const dataToUse = Object.keys(activeFilters).length > 0 ? filteredData : lowPerformingCreatives;

  const criticalCount = dataToUse.filter(c => c.status === 'critical').length;
  const warningCount = dataToUse.filter(c => c.status === 'warning').length;
  const totalWaste = dataToUse.reduce((sum, c) => sum + c.spend, 0);
  const avgPerformanceScore = dataToUse.length > 0 
    ? dataToUse.reduce((sum, c) => sum + c.performance_score, 0) / dataToUse.length 
    : 0;

  // Preparar dados únicos para filtros
  const uniqueClients = Array.from(new Set(lowPerformingCreatives.map(c => c.client_name)))
    .sort()
    .map(name => ({ value: name, label: name }));

  const primaryFilters: FilterConfig[] = [
    {
      id: 'cliente',
      label: 'Cliente',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os clientes' },
        ...uniqueClients
      ],
      placeholder: 'Todos os clientes'
    },
    {
      id: 'tipo-criativo',
      label: 'Tipo de Criativo',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os tipos' },
        { value: 'imagem', label: 'Imagem' },
        { value: 'video', label: 'Vídeo' },
        { value: 'carousel', label: 'Carrossel' }
      ],
      placeholder: 'Todos os tipos'
    },
    {
      id: 'performance-minima',
      label: 'Performance Máxima',
      type: 'select',
      options: [
        { value: 'sem-limite', label: 'Sem limite' },
        { value: '20', label: 'Score ≤ 20' },
        { value: '40', label: 'Score ≤ 40' },
        { value: '60', label: 'Score ≤ 60' },
        { value: '80', label: 'Score ≤ 80' }
      ],
      placeholder: 'Sem limite'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'periodo',
      label: 'Período Mínimo (dias)',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os períodos' },
        { value: '7', label: '7+ dias' },
        { value: '15', label: '15+ dias' },
        { value: '30', label: '30+ dias' }
      ],
      placeholder: 'Todos os períodos'
    },
    {
      id: 'status',
      label: 'Status',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os status' },
        { value: 'critical', label: 'Crítico' },
        { value: 'warning', label: 'Alerta' },
        { value: 'underperforming', label: 'Baixa Performance' }
      ],
      placeholder: 'Todos os status'
    },
    {
      id: 'recomendacao',
      label: 'Recomendação',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as recomendações' },
        { value: 'pause', label: 'Pausar' },
        { value: 'replace', label: 'Substituir' },
        { value: 'adjust', label: 'Ajustar' }
      ],
      placeholder: 'Todas as recomendações'
    },
    {
      id: 'status-campanha',
      label: 'Status da Campanha',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os status' },
        { value: 'active', label: 'Ativas' },
        { value: 'paused', label: 'Pausadas' },
        { value: 'finished', label: 'Finalizadas' }
      ],
      placeholder: 'Todos os status'
    }
  ];

  return (
    <ReportLayout
      title="Relatório de Criativos de Baixo Desempenho"
      description="Identificação de anúncios que estão queimando verba sem retorno"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Configure os parâmetros para análise de criativos de baixo desempenho"
    >
      <div className="space-y-6">
        {/* Resumo */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <MetricCard
            title="Criativos Críticos"
            value={criticalCount}
            trend={criticalCount > 0 ? "down" : "neutral"}
            subtitle="Para pausar imediatamente"
          />
          <MetricCard
            title="Criativos em Alerta"
            value={warningCount}
            trend={warningCount > 0 ? "down" : "neutral"}
            subtitle="Para substituir"
          />
          <MetricCard
            title="Verba Desperdiçada"
            value={`R$ ${totalWaste.toLocaleString()}`}
            trend="down"
            subtitle="Total gasto sem retorno"
          />
          <MetricCard
            title="Score Médio"
            value={`${avgPerformanceScore.toFixed(0)}/100`}
            trend={avgPerformanceScore < 50 ? "down" : avgPerformanceScore > 70 ? "up" : "neutral"}
            subtitle="Performance geral"
          />
        </div>

        {/* Lista de Criativos */}
        <div className="grid gap-4">
          {filteredData.length === 0 ? (
            <Card>
              <CardContent className="p-6 text-center">
                <Image className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
                <h3 className="text-lg font-semibold mb-2">Nenhum criativo com baixo desempenho</h3>
                <p className="text-muted-foreground">
                  Todos os criativos estão com performance dentro dos parâmetros esperados.
                </p>
              </CardContent>
            </Card>
          ) : (
            filteredData.map((creative) => {
              return (
                <Card key={creative.id} className="border-l-4 border-l-destructive">
                  <CardHeader className="pb-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <AlertTriangle className="w-5 h-5 text-destructive" />
                        <div>
                          <CardTitle className="text-lg">{creative.name}</CardTitle>
                          <p className="text-sm text-muted-foreground">
                            {creative.campaign_name} • {creative.client_name}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Badge className={getStatusColor(creative.status)}>
                          {creative.status === 'critical' ? 'EFICIÊNCIA BAIXA' : 
                           creative.status === 'warning' ? 'ALERTA' : 'BAIXA PERFORMANCE'}
                        </Badge>
                        <div className="flex gap-2">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleCreateTask(creative)}
                          >
                            Criar Tarefa
                          </Button>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleViewAdCreativeMetrics(creative)}
                          >
                            <Eye className="w-4 h-4 mr-2" />
                            Ver Detalhes
                          </Button>
                        </div>
                      </div>
                    </div>
                  </CardHeader>

                  <CardContent className="space-y-4">
                    {/* Problemas Identificados */}
                    <div>
                      <h4 className="font-semibold mb-2 text-destructive">Problemas Identificados:</h4>
                      <div className="space-y-1">
                        {creative.ctr < creative.ideal_ctr && (
                          <div className="flex items-center gap-2 text-sm text-muted-foreground">
                            <AlertTriangle className="w-4 h-4 text-destructive" />
                            <span>CTR abaixo da meta ({creative.ctr.toFixed(2)}% vs {creative.ideal_ctr.toFixed(2)}%)</span>
                          </div>
                        )}
                        {creative.cpc > creative.ideal_cpc && (
                          <div className="flex items-center gap-2 text-sm text-muted-foreground">
                            <AlertTriangle className="w-4 h-4 text-destructive" />
                            <span>CPC acima da meta (R$ {creative.cpc.toFixed(2)} vs R$ {creative.ideal_cpc.toFixed(2)})</span>
                          </div>
                        )}
                        {creative.conversions === 0 && (
                          <div className="flex items-center gap-2 text-sm text-muted-foreground">
                            <AlertTriangle className="w-4 h-4 text-destructive" />
                            <span>Nenhuma conversão gerada</span>
                          </div>
                        )}
                      </div>
                    </div>

                    {/* Recomendação */}
                    <div>
                      <h4 className="font-semibold mb-2 text-primary">Recomendação:</h4>
                      <p className="text-sm text-muted-foreground bg-muted/50 p-3 rounded-lg">
                        {creative.recommendation_reason}
                      </p>
                    </div>

                    {/* Status da Campanha e badges */}
                    <div className="flex items-center gap-2 flex-wrap">
                      <Badge 
                        variant={creative.campaign_status === 'active' ? 'default' : 'secondary'}
                        className={creative.campaign_status === 'active' ? 'bg-success text-success-foreground' : ''}
                      >
                        Campanha: {creative.campaign_status === 'active' ? 'Ativa' : 
                                  creative.campaign_status === 'paused' ? 'Pausada' : 'Finalizada'}
                      </Badge>
                      <Badge variant="outline">
                        Score: {creative.performance_score}/100
                      </Badge>
                      <Badge variant="outline">
                        {creative.days_active} dias ativo{creative.days_active !== 1 ? 's' : ''}
                      </Badge>
                    </div>

                    {/* Métricas Principais - Layout horizontal similar à imagem */}
                    <div className="grid grid-cols-5 gap-4 pt-4 border-t">
                      <div className="text-center">
                        <div className="text-2xl font-bold text-destructive">
                          R$ {creative.spend.toLocaleString()}
                        </div>
                        <div className="text-xs text-muted-foreground">Investimento Total</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold">
                          {creative.conversions}
                        </div>
                        <div className="text-xs text-muted-foreground">Conversões</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-destructive">
                          {creative.cpl > 0 ? `R$ ${creative.cpl.toFixed(0)}` : 'N/A'}
                        </div>
                        <div className="text-xs text-muted-foreground">
                          CPA (Meta: {creative.ideal_cpl > 0 ? `R$ ${creative.ideal_cpl.toFixed(0)}` : 'N/A'})
                        </div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-destructive">
                          {creative.ctr.toFixed(2)}%
                        </div>
                        <div className="text-xs text-muted-foreground">
                          CTR (Mín: {creative.ideal_ctr.toFixed(2)}%)
                        </div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-destructive">
                          R$ {creative.cpc.toFixed(2)}
                        </div>
                        <div className="text-xs text-muted-foreground">
                          CPC (Mín: R$ {creative.ideal_cpc.toFixed(2)})
                        </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              );
            })
          )}
        </div>
      </div>

      {/* Ad Creative Metrics Modal */}
      <AdCreativeMetricsModal
        ad={selectedAd}
        isOpen={adCreativeMetricsModalOpen}
        onClose={() => setAdCreativeMetricsModalOpen(false)}
      />
    </ReportLayout>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useDashboardData } from "@/hooks/useDashboardData";
import { useClients } from "@/hooks/useClients";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { TrendingUp, Target, DollarSign, AlertTriangle, Plus, Award } from "lucide-react";

interface ExecutiveSummary {
  id: string;
  category: string;
  title: string;
  description: string;
  kpi: string;
  value: number | string;
  target: number | string;
  status: 'excellent' | 'good' | 'needs_attention' | 'critical';
  trend: 'up' | 'down' | 'neutral';
  insights: string[];
  recommendations: string[];
  impact: 'Alto' | 'Médio' | 'Baixo';
}

const RelatorioExecutivo = () => {
  const { metrics, clientsPerformance, campaignRankings, loading } = useDashboardData();
  const { clients } = useClients();
  const { convertAlertToTask } = useTaskAutomation();

  const [executiveSummary, setExecutiveSummary] = useState<ExecutiveSummary[]>([]);
  const [filteredData, setFilteredData] = useState<ExecutiveSummary[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});

  const primaryFilters: FilterConfig[] = [
    {
      id: 'categoria',
      label: 'Categoria',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as categorias' },
        { value: 'financeiro', label: 'Financeiro' },
        { value: 'performance', label: 'Performance' },
        { value: 'crescimento', label: 'Crescimento' },
        { value: 'operacional', label: 'Operacional' }
      ],
      placeholder: 'Todas as categorias'
    },
    {
      id: 'status-kpi',
      label: 'Status do KPI',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os status' },
        { value: 'critical', label: 'Crítico' },
        { value: 'needs_attention', label: 'Atenção Necessária' },
        { value: 'good', label: 'No Alvo' },
        { value: 'excellent', label: 'Superando Metas' }
      ],
      placeholder: 'Todos os status'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'impacto',
      label: 'Impacto no Negócio',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os impactos' },
        { value: 'Alto', label: 'Alto' },
        { value: 'Médio', label: 'Médio' },
        { value: 'Baixo', label: 'Baixo' }
      ],
      placeholder: 'Todos os impactos'
    }
  ];

  const generateExecutiveSummary = () => {
    if (!metrics || !clientsPerformance || !campaignRankings) return;

    const roi = (metrics.totalInvestment || 0) > 0 ? 
      (((metrics.totalLeads || 0) * 150 - (metrics.totalInvestment || 0)) / (metrics.totalInvestment || 1) * 100) : 0;

    const avgCPA = (metrics.totalInvestment || 0) / (metrics.totalLeads || 1);
    const activeClients = clients.filter(c => clientsPerformance.some(cp => cp.name === c.name)).length;

    const summary: ExecutiveSummary[] = [
      {
        id: 'roi',
        category: 'financeiro',
        title: 'Retorno sobre Investimento',
        description: 'ROI geral das campanhas de marketing',
        kpi: 'ROI',
        value: `${roi.toFixed(1)}%`,
        target: '200%',
        status: roi > 200 ? 'excellent' : roi > 150 ? 'good' : roi > 100 ? 'needs_attention' : 'critical',
        trend: roi > 150 ? 'up' : 'down',
        insights: [
          `ROI atual de ${roi.toFixed(1)}% vs target de 200%`,
          `Investimento total: R$ ${(metrics.totalInvestment || 0).toLocaleString()}`
        ],
        recommendations: roi < 150 ? ['Revisar campanhas com baixo ROI', 'Otimizar targeting'] : ['Manter estratégia atual'],
        impact: 'Alto'
      },
      {
        id: 'cpa',
        category: 'performance',
        title: 'Custo por Aquisição',
        description: 'Eficiência na geração de leads',
        kpi: 'CPA Médio',
        value: `R$ ${avgCPA.toFixed(2)}`,
        target: 'R$ 80,00',
        status: avgCPA < 60 ? 'excellent' : avgCPA < 80 ? 'good' : avgCPA < 120 ? 'needs_attention' : 'critical',
        trend: avgCPA < 80 ? 'up' : 'down',
        insights: [
          `CPA atual: R$ ${avgCPA.toFixed(2)} vs target R$ 80`,
          `Total de leads: ${metrics.totalLeads || 0}`
        ],
        recommendations: avgCPA > 80 ? ['Otimizar audiências', 'Melhorar criativos'] : ['Escalar campanhas eficientes'],
        impact: 'Alto'
      },
      {
        id: 'crescimento',
        category: 'crescimento',
        title: 'Crescimento da Base de Clientes',
        description: 'Expansão do portfólio de clientes',
        kpi: 'Clientes Ativos',
        value: activeClients,
        target: activeClients + 5,
        status: activeClients > 20 ? 'excellent' : activeClients > 15 ? 'good' : 'needs_attention',
        trend: 'neutral',
        insights: [
          `${activeClients} clientes ativos no período`,
          `Meta de crescimento: +5 clientes/mês`
        ],
        recommendations: ['Programa de indicações', 'Prospecção ativa', 'Melhoria do atendimento'],
        impact: 'Médio'
      },
      {
        id: 'campanhas-ativas',
        category: 'operacional',
        title: 'Campanhas em Execução',
        description: 'Volume operacional de campanhas',
        kpi: 'Campanhas Ativas',
        value: campaignRankings.filter(c => c.status === 'active').length,
        target: '50+',
        status: campaignRankings.length > 50 ? 'excellent' : campaignRankings.length > 30 ? 'good' : 'needs_attention',
        trend: 'up',
        insights: [
          `${campaignRankings.length} campanhas no total`,
          `${campaignRankings.filter(c => c.status === 'active').length} campanhas ativas`
        ],
        recommendations: ['Otimizar campanhas existentes', 'Expandir para novos canais'],
        impact: 'Médio'
      }
    ];

    setExecutiveSummary(summary);
  };

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = executiveSummary;

    if (newFilters['categoria'] && newFilters['categoria'] !== 'todas') {
      filtered = filtered.filter(item => item.category === newFilters['categoria']);
    }

    if (newFilters['status-kpi'] && newFilters['status-kpi'] !== 'todos') {
      filtered = filtered.filter(item => item.status === newFilters['status-kpi']);
    }

    if (newFilters['impacto'] && newFilters['impacto'] !== 'todos') {
      filtered = filtered.filter(item => item.impact === newFilters['impacto']);
    }

    setFilteredData(filtered);
  };

  const handleCreateTask = async (item: ExecutiveSummary) => {
    await convertAlertToTask({
      title: `Ação executiva: ${item.title}`,
      description: `KPI: ${item.kpi} (${item.value}). Recomendações: ${item.recommendations.join(', ')}`,
      priority: item.status === 'critical' ? 'high' : 'medium',
      type: 'strategic'
    });
  };

  const getStatusBadge = (status: ExecutiveSummary['status']) => {
    const variants = { excellent: 'default', good: 'secondary', needs_attention: 'outline', critical: 'destructive' } as const;
    const labels = { excellent: 'Superando', good: 'No Alvo', needs_attention: 'Atenção', critical: 'Crítico' };
    return <Badge variant={variants[status]}>{labels[status]}</Badge>;
  };

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case 'financeiro': return <DollarSign className="w-4 h-4" />;
      case 'performance': return <TrendingUp className="w-4 h-4" />;
      case 'crescimento': return <Target className="w-4 h-4" />;
      case 'operacional': return <Award className="w-4 h-4" />;
      default: return <AlertTriangle className="w-4 h-4" />;
    }
  };

  useEffect(() => {
    if (metrics && clientsPerformance && campaignRankings) {
      generateExecutiveSummary();
    }
  }, [metrics, clientsPerformance, campaignRankings]);

  useEffect(() => {
    setFilteredData(executiveSummary);
  }, [executiveSummary]);

  if (loading || !metrics) {
    return (
      <ReportLayout title="Relatório Executivo" description="Carregando dados...">
        <div className="flex items-center justify-center h-64">
          <p className="text-muted-foreground">Carregando dados...</p>
        </div>
      </ReportLayout>
    );
  }

  const filteredMetrics = {
    totalKPIs: filteredData.length,
    criticalKPIs: filteredData.filter(k => k.status === 'critical').length,
    excellentKPIs: filteredData.filter(k => k.status === 'excellent').length,
    avgImpact: filteredData.filter(k => k.impact === 'Alto').length
  };

  return (
    <ReportLayout
      title="Relatório Executivo"
      description="Dashboard estratégico com KPIs e insights de negócio"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
    >
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <MetricCard
          title="KPIs Monitorados"
          value={filteredMetrics.totalKPIs}
          subtitle="Indicadores executivos"
        />
        <MetricCard
          title="KPIs Críticos"
          value={filteredMetrics.criticalKPIs}
          trend={filteredMetrics.criticalKPIs > 0 ? "down" : "up"}
          subtitle="Requerem ação imediata"
        />
        <MetricCard
          title="Superando Metas"
          value={filteredMetrics.excellentKPIs}
          trend="up"
          subtitle="Performance excelente"
        />
        <MetricCard
          title="Alto Impacto"
          value={filteredMetrics.avgImpact}
          subtitle="KPIs críticos para negócio"
        />
      </div>

      <div className="space-y-4">
        {filteredData.map((item) => (
          <Card key={item.id} className="hover:shadow-md transition-shadow">
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    {getCategoryIcon(item.category)}
                    <CardTitle className="text-lg">{item.title}</CardTitle>
                    <Badge variant="outline" className="capitalize">{item.category}</Badge>
                  </div>
                  <CardDescription>{item.description}</CardDescription>
                </div>
                {getStatusBadge(item.status)}
              </div>
            </CardHeader>

            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-muted/50 rounded-lg">
                <div className="text-center">
                  <div className="text-2xl font-bold text-foreground">{item.value}</div>
                  <div className="text-xs text-muted-foreground">Atual</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-muted-foreground">{item.target}</div>
                  <div className="text-xs text-muted-foreground">Meta</div>
                </div>
                <div className="text-center">
                  <div className={`text-lg font-bold ${item.trend === 'up' ? 'text-green-600' : 'text-red-600'}`}>
                    {item.trend === 'up' ? '↑' : '↓'}
                  </div>
                  <div className="text-xs text-muted-foreground">Tendência</div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold text-foreground">{item.impact}</div>
                  <div className="text-xs text-muted-foreground">Impacto</div>
                </div>
              </div>

              {item.insights.length > 0 && (
                <div>
                  <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                    <Target className="w-4 h-4" />
                    Insights Executivos
                  </h4>
                  <ul className="space-y-1">
                    {item.insights.map((insight, index) => (
                      <li key={index} className="text-sm text-muted-foreground flex items-center gap-2">
                        <div className="w-1 h-1 rounded-full bg-primary" />
                        {insight}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {item.recommendations.length > 0 && (
                <div>
                  <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                    <TrendingUp className="w-4 h-4" />
                    Ações Recomendadas
                  </h4>
                  <ul className="space-y-1">
                    {item.recommendations.map((rec, index) => (
                      <li key={index} className="text-sm text-muted-foreground flex items-center gap-2">
                        <div className="w-1 h-1 rounded-full bg-orange-500" />
                        {rec}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {(item.status === 'critical' || item.status === 'needs_attention') && (
                <div className="flex justify-end pt-2">
                  <Button 
                    variant="outline" 
                    size="sm"
                    onClick={() => handleCreateTask(item)}
                    className="flex items-center gap-2"
                  >
                    <Plus className="w-4 h-4" />
                    Criar Plano de Ação
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>
    </ReportLayout>
  );
};

export default RelatorioExecutivo;

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useDashboardData } from "@/hooks/useDashboardData";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { Users, MousePointer, Target, Repeat, AlertTriangle, Plus, TrendingDown } from "lucide-react";

interface FunnelStageAnalysis {
  id: string;
  stage: string;
  stageName: string;
  volume: number;
  conversionRate: number;
  cost: number;
  cpl: number;
  efficiency: string;
  analysisStatus: 'excellent' | 'good' | 'needs_attention' | 'critical';
  issues: string[];
  recommendations: string[];
  dropoffRate: number;
}

const RelatorioFunil = () => {
  const { funnelMetrics, campaignRankings } = useDashboardData();
  const { convertAlertToTask } = useTaskAutomation();

  const [funnelAnalysis, setFunnelAnalysis] = useState<FunnelStageAnalysis[]>([]);
  const [filteredData, setFilteredData] = useState<FunnelStageAnalysis[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});

  const primaryFilters: FilterConfig[] = [
    {
      id: 'status-eficiencia',
      label: 'Status de Eficiência',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os status' },
        { value: 'critical', label: 'Crítico' },
        { value: 'needs_attention', label: 'Precisa Atenção' },
        { value: 'good', label: 'Bom' },
        { value: 'excellent', label: 'Excelente' }
      ],
      placeholder: 'Todos os status'
    },
    {
      id: 'etapa-funil',
      label: 'Etapa do Funil',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as etapas' },
        { value: 'topo', label: 'Topo (Awareness)' },
        { value: 'meio', label: 'Meio (Consideration)' },
        { value: 'fundo', label: 'Fundo (Conversion)' },
        { value: 'retencao', label: 'Retenção' }
      ],
      placeholder: 'Todas as etapas'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'conversao-minima',
      label: 'Conversão Mínima',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as conversões' },
        { value: '5', label: '5%+' },
        { value: '10', label: '10%+' },
        { value: '15', label: '15%+' }
      ],
      placeholder: 'Todas as conversões'
    }
  ];

  const analyzeFunnel = () => {
    if (!funnelMetrics) return;

    const stages = [
      {
        id: 'topo',
        stage: 'topo',
        stageName: 'Topo (Awareness)',
        volume: funnelMetrics.reach || 0,
        cost: (funnelMetrics.reach || 0) * 0.01,
        icon: Users
      },
      {
        id: 'meio',
        stage: 'meio',
        stageName: 'Meio (Consideration)',
        volume: funnelMetrics.clicks || 0,
        cost: (funnelMetrics.clicks || 0) * 0.5,
        icon: MousePointer
      },
      {
        id: 'fundo',
        stage: 'fundo',
        stageName: 'Fundo (Conversion)',
        volume: funnelMetrics.leads || 0,
        cost: (funnelMetrics.leads || 0) * (funnelMetrics.cpl || 0),
        icon: Target
      },
      {
        id: 'retencao',
        stage: 'retencao',
        stageName: 'Retenção',
        volume: Math.floor((funnelMetrics.leads || 0) * 0.7),
        cost: Math.floor((funnelMetrics.leads || 0) * 0.7) * 50,
        icon: Repeat
      }
    ];

    const analysis: FunnelStageAnalysis[] = stages.map((stage, index) => {
      const prevStage = index > 0 ? stages[index - 1] : null;
      const conversionRate = prevStage ? (stage.volume / prevStage.volume * 100) : 100;
      const dropoffRate = 100 - conversionRate;
      const cpl = stage.volume > 0 ? stage.cost / stage.volume : 0;

      // Identificar problemas
      const issues: string[] = [];
      if (conversionRate < 5 && index > 0) issues.push(`Taxa de conversão baixa: ${conversionRate.toFixed(1)}%`);
      if (dropoffRate > 80 && index > 0) issues.push(`Alto índice de abandono: ${dropoffRate.toFixed(1)}%`);
      if (cpl > 100 && index === 2) issues.push(`CPL alto: R$ ${cpl.toFixed(2)}`);

      // Determinar status
      const analysisStatus: FunnelStageAnalysis['analysisStatus'] = 
        conversionRate < 3 && index > 0 ? 'critical' :
        conversionRate < 8 && index > 0 ? 'needs_attention' :
        conversionRate > 15 ? 'excellent' : 'good';

      // Gerar recomendações
      const recommendations: string[] = [];
      if (conversionRate < 5 && index === 1) recommendations.push('Melhorar criativos para aumentar CTR');
      if (conversionRate < 5 && index === 2) recommendations.push('Otimizar landing pages e formulários');
      if (dropoffRate > 70) recommendations.push('Revisar jornada do usuário nesta etapa');
      if (cpl > 80) recommendations.push('Melhorar segmentação de audiência');

      const efficiency = conversionRate > 15 ? 'Excelente' : 
                        conversionRate > 10 ? 'Boa' : 
                        conversionRate > 5 ? 'Regular' : 'Crítica';

      return {
        id: stage.id,
        stage: stage.stage,
        stageName: stage.stageName,
        volume: stage.volume,
        conversionRate: Math.round(conversionRate * 100) / 100,
        cost: stage.cost,
        cpl: Math.round(cpl * 100) / 100,
        efficiency,
        analysisStatus,
        issues,
        recommendations,
        dropoffRate: Math.round(dropoffRate * 100) / 100
      };
    });

    setFunnelAnalysis(analysis);
  };

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = funnelAnalysis;

    if (newFilters['status-eficiencia'] && newFilters['status-eficiencia'] !== 'todos') {
      filtered = filtered.filter(stage => stage.analysisStatus === newFilters['status-eficiencia']);
    }

    if (newFilters['etapa-funil'] && newFilters['etapa-funil'] !== 'todas') {
      filtered = filtered.filter(stage => stage.stage === newFilters['etapa-funil']);
    }

    if (newFilters['conversao-minima'] && newFilters['conversao-minima'] !== 'todas') {
      const minConversion = parseInt(newFilters['conversao-minima']);
      filtered = filtered.filter(stage => stage.conversionRate >= minConversion);
    }

    setFilteredData(filtered);
  };

  const handleCreateTask = async (stage: FunnelStageAnalysis) => {
    await convertAlertToTask({
      title: `Otimizar ${stage.stageName}`,
      description: `Problemas: ${stage.issues.join(', ')}. Recomendações: ${stage.recommendations.join(', ')}`,
      priority: stage.analysisStatus === 'critical' ? 'high' : 'medium',
      type: 'optimization'
    });
  };

  const getStatusBadge = (status: FunnelStageAnalysis['analysisStatus']) => {
    const variants = { excellent: 'default', good: 'secondary', needs_attention: 'outline', critical: 'destructive' } as const;
    const labels = { excellent: 'Excelente', good: 'Bom', needs_attention: 'Precisa Atenção', critical: 'Crítico' };
    return <Badge variant={variants[status]}>{labels[status]}</Badge>;
  };

  useEffect(() => {
    if (funnelMetrics) {
      analyzeFunnel();
    }
  }, [funnelMetrics]);

  useEffect(() => {
    setFilteredData(funnelAnalysis);
  }, [funnelAnalysis]);

  if (!funnelMetrics) {
    return (
      <ReportLayout title="Relatório de Funil Completo" description="Carregando análise do funil...">
        <div className="flex items-center justify-center h-64">
          <p className="text-muted-foreground">Carregando dados...</p>
        </div>
      </ReportLayout>
    );
  }

  const filteredMetrics = {
    totalStages: filteredData.length,
    criticalStages: filteredData.filter(s => s.analysisStatus === 'critical').length,
    avgConversion: filteredData.length > 0 ? filteredData.reduce((acc, s) => acc + s.conversionRate, 0) / filteredData.length : 0,
    totalCost: filteredData.reduce((acc, s) => acc + s.cost, 0)
  };

  return (
    <ReportLayout
      title="Relatório de Funil Completo"
      description="Análise detalhada de conversão e otimização do funil"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
    >
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <MetricCard
          title="Etapas Analisadas"
          value={filteredMetrics.totalStages}
          subtitle="Total do funil"
        />
        <MetricCard
          title="Etapas Críticas"
          value={filteredMetrics.criticalStages}
          trend={filteredMetrics.criticalStages > 0 ? "down" : "up"}
          subtitle="Precisam otimização"
        />
        <MetricCard
          title="Conversão Média"
          value={`${filteredMetrics.avgConversion.toFixed(1)}%`}
          trend={filteredMetrics.avgConversion >= 10 ? "up" : "down"}
          subtitle="Entre etapas"
        />
        <MetricCard
          title="Custo Total"
          value={`R$ ${filteredMetrics.totalCost.toLocaleString()}`}
          subtitle="Investimento no funil"
        />
      </div>

      <div className="space-y-4">
        {filteredData.map((stage) => (
          <Card key={stage.id} className="hover:shadow-md transition-shadow">
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <div className="flex-1">
                  <CardTitle className="text-lg">{stage.stageName}</CardTitle>
                  <CardDescription>
                    {stage.volume.toLocaleString()} usuários • {stage.conversionRate}% conversão
                  </CardDescription>
                </div>
                {getStatusBadge(stage.analysisStatus)}
              </div>
            </CardHeader>

            <CardContent className="space-y-4">
              {stage.issues.length > 0 && (
                <div>
                  <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                    <AlertTriangle className="w-4 h-4" />
                    Problemas Identificados
                  </h4>
                  <ul className="space-y-1">
                    {stage.issues.map((issue, index) => (
                      <li key={index} className="text-sm text-destructive flex items-center gap-2">
                        <div className="w-1 h-1 rounded-full bg-destructive" />
                        {issue}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {stage.recommendations.length > 0 && (
                <div>
                  <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                    <Target className="w-4 h-4" />
                    Recomendações
                  </h4>
                  <ul className="space-y-1">
                    {stage.recommendations.map((rec, index) => (
                      <li key={index} className="text-sm text-muted-foreground flex items-center gap-2">
                        <div className="w-1 h-1 rounded-full bg-primary" />
                        {rec}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                <div className="text-center">
                  <div className="text-lg font-bold text-foreground">{stage.volume.toLocaleString()}</div>
                  <div className="text-xs text-muted-foreground">Volume</div>
                </div>
                <div className="text-center">
                  <div className={`text-lg font-bold ${stage.conversionRate >= 10 ? 'text-green-600' : 'text-red-600'}`}>
                    {stage.conversionRate}%
                  </div>
                  <div className="text-xs text-muted-foreground">Conversão</div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold text-foreground">R$ {stage.cost.toLocaleString()}</div>
                  <div className="text-xs text-muted-foreground">Custo</div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold text-foreground">R$ {stage.cpl.toFixed(2)}</div>
                  <div className="text-xs text-muted-foreground">CPL</div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-bold text-foreground">{stage.efficiency}</div>
                  <div className="text-xs text-muted-foreground">Eficiência</div>
                </div>
              </div>

              {(stage.analysisStatus === 'critical' || stage.analysisStatus === 'needs_attention') && (
                <div className="flex justify-end pt-2">
                  <Button 
                    variant="outline" 
                    size="sm"
                    onClick={() => handleCreateTask(stage)}
                    className="flex items-center gap-2"
                  >
                    <Plus className="w-4 h-4" />
                    Otimizar Etapa
                  </Button>
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>
    </ReportLayout>
  );
};

export default RelatorioFunil;

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useDashboardData } from "@/hooks/useDashboardData";
import { useClients } from "@/hooks/useClients";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { 
  TrendingUp, 
  TrendingDown, 
  Target, 
  AlertTriangle,
  Plus,
  DollarSign,
  Lightbulb
} from "lucide-react";

interface OpportunityAnalysis {
  id: string;
  title: string;
  description: string;
  clientId?: string;
  clientName?: string;
  type: 'optimization' | 'creative' | 'budget' | 'audience' | 'strategy';
  priority: 'high' | 'medium' | 'low';
  impact: 'Alto' | 'Médio' | 'Baixo';
  effort: 'Alto' | 'Médio' | 'Baixo';
  estimatedSaving: number;
  timeframe: string;
  healthScore: number; // nota de saúde de 0 a 100
  analysisStatus: 'excellent' | 'good' | 'needs_attention' | 'critical';
  issues: string[];
  recommendations: string[];
  implementationSteps: string[];
}

const RelatorioOportunidades = () => {
  const { metrics, clientsPerformance, campaignRankings, funnelMetrics } = useDashboardData();
  const { clients } = useClients();
  const { convertAlertToTask } = useTaskAutomation();

  const [opportunitiesAnalysis, setOpportunitiesAnalysis] = useState<OpportunityAnalysis[]>([]);
  const [filteredData, setFilteredData] = useState<OpportunityAnalysis[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});

  const primaryFilters: FilterConfig[] = [
    {
      id: 'cliente',
      label: 'Cliente',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os clientes' },
        ...clients.map(client => ({
          value: client.id,
          label: client.name
        }))
      ],
      placeholder: 'Todos os clientes'
    },
    {
      id: 'tipo-oportunidade',
      label: 'Tipo de Oportunidade',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as oportunidades' },
        { value: 'optimization', label: 'Otimização' },
        { value: 'creative', label: 'Criativos' },
        { value: 'budget', label: 'Orçamento' },
        { value: 'audience', label: 'Audiência' },
        { value: 'strategy', label: 'Estratégia' }
      ],
      placeholder: 'Todas as oportunidades'
    },
    {
      id: 'prioridade',
      label: 'Prioridade',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as prioridades' },
        { value: 'high', label: 'Alta' },
        { value: 'medium', label: 'Média' },
        { value: 'low', label: 'Baixa' }
      ],
      placeholder: 'Todas as prioridades'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'economia-minima',
      label: 'Economia Mínima',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as economias' },
        { value: '5000', label: 'R$ 5.000+' },
        { value: '10000', label: 'R$ 10.000+' },
        { value: '20000', label: 'R$ 20.000+' }
      ],
      placeholder: 'Todas as economias'
    },
    {
      id: 'prazo',
      label: 'Prazo de Implementação',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os prazos' },
        { value: 'imediato', label: 'Imediato (1-7 dias)' },
        { value: 'curto', label: 'Curto (1-4 semanas)' },
        { value: 'medio', label: 'Médio (1-3 meses)' }
      ],
      placeholder: 'Todos os prazos'
    }
  ];

  const calculateHealthScore = (priority: string, impact: string, effort: string, estimatedSaving: number): number => {
    let score = 50; // Base score

    // Pontuação baseada na prioridade (30 pontos máximo)
    if (priority === 'high') {
      score += 30;
    } else if (priority === 'medium') {
      score += 15;
    } else {
      score += 5;
    }

    // Pontuação baseada no impacto (25 pontos máximo)
    if (impact === 'Alto') {
      score += 25;
    } else if (impact === 'Médio') {
      score += 15;
    } else {
      score += 5;
    }

    // Pontuação baseada no esforço (15 pontos máximo - menor esforço = maior pontuação)
    if (effort === 'Baixo') {
      score += 15;
    } else if (effort === 'Médio') {
      score += 10;
    } else {
      score += 3;
    }

    // Pontuação baseada na economia estimada (20 pontos máximo)
    if (estimatedSaving >= 20000) {
      score += 20;
    } else if (estimatedSaving >= 10000) {
      score += 15;
    } else if (estimatedSaving >= 5000) {
      score += 10;
    } else {
      score += 5;
    }

    return Math.max(0, Math.min(100, Math.round(score)));
  };

  const analyzeOpportunities = () => {
    if (!metrics || !clientsPerformance || !campaignRankings || !funnelMetrics) {
      return;
    }

    const opportunities: OpportunityAnalysis[] = [];

    // Oportunidades de otimização de campanhas
    campaignRankings.forEach((campaign, index) => {
      // Tentar associar campanha ao cliente pelo nome ou ID
      const associatedClient = clientsPerformance.find(client => 
        campaign.name.toLowerCase().includes(client.name.toLowerCase()) ||
        client.name.toLowerCase().includes(campaign.name.toLowerCase())
      );

      if (campaign.ctr < 1.5) {
        const priority = campaign.ctr < 1 ? 'high' : 'medium';
        const impact = campaign.spend > 10000 ? 'Alto' : 'Médio';
        const effort = 'Médio';
        const estimatedSaving = campaign.spend * 0.25;

        opportunities.push({
          id: `ctr-${index}`,
          title: `Otimizar CTR da campanha ${campaign.name}`,
          description: `CTR atual de ${campaign.ctr}% está abaixo da média de mercado (2%)`,
          clientId: associatedClient?.id,
          clientName: associatedClient?.name || 'Cliente não identificado',
          type: 'creative',
          priority,
          impact,
          effort,
          estimatedSaving,
          timeframe: '2-4 semanas',
          healthScore: calculateHealthScore(priority, impact, effort, estimatedSaving),
          analysisStatus: campaign.ctr < 1 ? 'critical' : 'needs_attention',
          issues: [`CTR baixo: ${campaign.ctr}%`, 'Criativos podem estar saturados'],
          recommendations: ['Testar novos criativos', 'A/B test de headlines', 'Revisar copy'],
          implementationSteps: ['Criar 3-5 variações de criativos', 'Configurar testes A/B', 'Monitorar performance por 2 semanas']
        });
      }

      if (campaign.cpa > 100) {
        const priority = campaign.cpa > 150 ? 'high' : 'medium';
        const impact = 'Alto';
        const effort = 'Médio';
        const estimatedSaving = (campaign.cpa - 80) * campaign.conversions;

        opportunities.push({
          id: `cpa-${index}`,
          title: `Reduzir CPA da campanha ${campaign.name}`,
          description: `CPA de R$ ${campaign.cpa} está acima do target de R$ 80`,
          clientId: associatedClient?.id,
          clientName: associatedClient?.name || 'Cliente não identificado',
          type: 'optimization',
          priority,
          impact,
          effort,
          estimatedSaving,
          timeframe: '1-3 semanas',
          healthScore: calculateHealthScore(priority, impact, effort, estimatedSaving),
          analysisStatus: campaign.cpa > 150 ? 'critical' : 'needs_attention',
          issues: [`CPA alto: R$ ${campaign.cpa}`, 'Audiência pode estar mal segmentada'],
          recommendations: ['Refinar audiência', 'Otimizar lances', 'Melhorar landing page'],
          implementationSteps: ['Analisar audiência atual', 'Criar lookalikes', 'Otimizar páginas de destino']
        });
      }
    });

    // Oportunidades de redistribuição de budget
    if (funnelMetrics.cpl && funnelMetrics.cpl > 80) {
      const priority = 'high';
      const impact = 'Alto';
      const effort = 'Baixo';
      const estimatedSaving = (metrics?.totalInvestment || 0) * 0.15;

      opportunities.push({
        id: 'budget-redistribution',
        title: 'Redistribuir orçamento entre campanhas',
        description: `CPL médio de R$ ${funnelMetrics.cpl} indica oportunidade de realocação`,
        clientName: 'Estratégia Geral',
        type: 'budget',
        priority,
        impact,
        effort,
        estimatedSaving,
        timeframe: '1 semana',
        healthScore: calculateHealthScore(priority, impact, effort, estimatedSaving),
        analysisStatus: 'needs_attention',
        issues: ['Orçamento mal distribuído', 'Campanhas com baixo ROI recebendo muito budget'],
        recommendations: ['Mover budget para campanhas top performers', 'Pausar campanhas ineficientes'],
        implementationSteps: ['Identificar top 20% campanhas', 'Realocar 30% do budget', 'Monitorar resultados']
      });
    }

    // Oportunidades de audiência
    clientsPerformance.forEach((client, index) => {
      if (client.investment > 15000) {
        const efficiency = (client.investment / 60) / client.investment * 1000;
        if (efficiency < 15) {
          const priority = 'medium';
          const impact = 'Alto';
          const effort = 'Médio';
          const estimatedSaving = client.investment * 0.20;

          opportunities.push({
            id: `audience-${index}`,
            title: `Expandir audiências para ${client.name}`,
            description: `Alto investimento (R$ ${client.investment.toLocaleString()}) com baixa eficiência`,
            clientId: client.id,
            clientName: client.name,
            type: 'audience',
            priority,
            impact,
            effort,
            estimatedSaving,
            timeframe: '3-6 semanas',
            healthScore: calculateHealthScore(priority, impact, effort, estimatedSaving),
            analysisStatus: 'needs_attention',
            issues: ['Audiência limitada', 'Possível saturação'],
            recommendations: ['Criar lookalikes', 'Testar interesses similares', 'Expandir geo-targeting'],
            implementationSteps: ['Mapear audiências atuais', 'Criar 5 novas audiências', 'Implementar testes graduais']
          });
        }
      }
    });

    setOpportunitiesAnalysis(opportunities.slice(0, 12));
  };

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = opportunitiesAnalysis;

    if (newFilters['cliente'] && newFilters['cliente'] !== 'todos') {
      filtered = filtered.filter(opp => opp.clientId === newFilters['cliente']);
    }

    if (newFilters['tipo-oportunidade'] && newFilters['tipo-oportunidade'] !== 'todas') {
      filtered = filtered.filter(opp => opp.type === newFilters['tipo-oportunidade']);
    }

    if (newFilters['prioridade'] && newFilters['prioridade'] !== 'todas') {
      filtered = filtered.filter(opp => opp.priority === newFilters['prioridade']);
    }

    if (newFilters['economia-minima'] && newFilters['economia-minima'] !== 'todas') {
      const minSaving = parseInt(newFilters['economia-minima']);
      filtered = filtered.filter(opp => opp.estimatedSaving >= minSaving);
    }

    setFilteredData(filtered);
  };

  const handleCreateTask = async (opportunity: OpportunityAnalysis) => {
    await convertAlertToTask({
      title: opportunity.title,
      description: `${opportunity.description}. Economia estimada: R$ ${opportunity.estimatedSaving.toLocaleString()}. Passos: ${opportunity.implementationSteps.join(', ')}`,
      priority: opportunity.priority,
      type: 'optimization'
    });
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'optimization': return <TrendingUp className="w-4 h-4" />;
      case 'creative': return <Lightbulb className="w-4 h-4" />;
      case 'budget': return <DollarSign className="w-4 h-4" />;
      case 'audience': return <Target className="w-4 h-4" />;
      default: return <AlertTriangle className="w-4 h-4" />;
    }
  };

  const getPriorityBadge = (priority: string) => {
    const variants = { high: 'destructive', medium: 'outline', low: 'secondary' } as const;
    const labels = { high: 'Alta', medium: 'Média', low: 'Baixa' };
    return <Badge variant={variants[priority as keyof typeof variants] || 'outline'}>{labels[priority as keyof typeof labels] || priority}</Badge>;
  };

  const getStatusBadge = (status: OpportunityAnalysis['analysisStatus']) => {
    const variants = { excellent: 'default', good: 'secondary', needs_attention: 'outline', critical: 'destructive' } as const;
    const labels = { excellent: 'Excelente', good: 'Bom', needs_attention: 'Precisa de Atenção', critical: 'Crítico' };
    return <Badge variant={variants[status]}>{labels[status]}</Badge>;
  };

  useEffect(() => {
    analyzeOpportunities();
  }, [metrics, clientsPerformance, campaignRankings, funnelMetrics]);

  useEffect(() => {
    setFilteredData(opportunitiesAnalysis);
  }, [opportunitiesAnalysis]);

  const filteredMetrics = {
    totalOpportunities: filteredData.length,
    highPriorityOpps: filteredData.filter(o => o.priority === 'high').length,
    totalPotentialSaving: filteredData.reduce((acc, o) => acc + o.estimatedSaving, 0),
    quickWins: filteredData.filter(o => o.effort === 'Baixo' && o.impact === 'Alto').length
  };

  return (
    <ReportLayout
      title="Relatório de Oportunidades"
      description="Identificação de melhorias e otimizações com potencial de economia"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Use os filtros para priorizar oportunidades por tipo, impacto e economia potencial"
    >
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <MetricCard
          title="Oportunidades Identificadas"
          value={filteredMetrics.totalOpportunities}
          subtitle="Melhorias potenciais"
        />
        <MetricCard
          title="Prioridade Alta"
          value={filteredMetrics.highPriorityOpps}
          trend={filteredMetrics.highPriorityOpps > 0 ? "up" : "neutral"}
          subtitle="Ação imediata"
        />
        <MetricCard
          title="Economia Potencial"
          value={`R$ ${filteredMetrics.totalPotentialSaving.toLocaleString()}`}
          trend="up"
          subtitle="Por mês"
        />
        <MetricCard
          title="Quick Wins"
          value={filteredMetrics.quickWins}
          trend="up"
          subtitle="Alto impacto, baixo esforço"
        />
      </div>

      <div className="grid gap-4">
        {filteredData.length > 0 ? (
          filteredData
            .sort((a, b) => {
              // Ordenar primeiro por nota de saúde (maior para menor)
              const healthDiff = b.healthScore - a.healthScore;

              // Se nota igual, ordenar por economia estimada (maior para menor)
              if (healthDiff === 0) {
                return b.estimatedSaving - a.estimatedSaving;
              }

              return healthDiff;
            })
            .map((opportunity, index) => {
            const statusColor = opportunity.priority === 'high' ? 'border-l-destructive' :
                               opportunity.priority === 'medium' ? 'border-l-yellow-500' : 'border-l-green-500';

            return (
            <Card key={opportunity.id} className={`border-l-4 ${statusColor}`}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div className="space-y-2">
                    <div className="flex items-center gap-3">
                      <div className="flex items-center justify-center w-8 h-8 bg-muted rounded-full text-sm font-bold">
                        #{index + 1}
                      </div>
                      {getTypeIcon(opportunity.type)}
                      <div>
                        <CardTitle className="text-lg">{opportunity.title}</CardTitle>
                        <p className="text-sm text-muted-foreground">
                          {opportunity.clientName} • {opportunity.timeframe}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {getPriorityBadge(opportunity.priority)}
                      <Badge variant="outline">
                        {opportunity.impact} impacto
                      </Badge>
                      <Badge variant="outline">
                        {opportunity.effort} esforço
                      </Badge>
                      <Badge variant="outline">
                        Score: {opportunity.healthScore}/100
                      </Badge>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <div className="text-right mr-4">
                      <div className="text-lg font-bold text-green-600">
                        R$ {opportunity.estimatedSaving.toLocaleString()}
                      </div>
                      <div className="text-xs text-muted-foreground">economia/mês</div>
                    </div>
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => handleCreateTask(opportunity)}
                      className="flex items-center gap-2"
                    >
                      <Plus className="w-4 h-4" />
                      Implementar
                    </Button>
                  </div>
                </div>
              </CardHeader>

              <CardContent className="space-y-4">
                {opportunity.issues.length > 0 && (
                  <div>
                    <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                      <AlertTriangle className="w-4 h-4" />
                      Problemas Identificados
                    </h4>
                    <ul className="space-y-1">
                      {opportunity.issues.map((issue, index) => (
                        <li key={index} className="text-sm text-destructive flex items-center gap-2">
                          <div className="w-1 h-1 rounded-full bg-destructive" />
                          {issue}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                <div>
                  <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                    <Target className="w-4 h-4" />
                    Plano de Implementação
                  </h4>
                  <ul className="space-y-1">
                    {opportunity.implementationSteps.map((step, index) => (
                      <li key={index} className="text-sm text-muted-foreground flex items-center gap-2">
                        <div className="w-4 h-4 rounded-full bg-primary/10 flex items-center justify-center text-xs font-medium text-primary">
                          {index + 1}
                        </div>
                        {step}
                      </li>
                    ))}
                  </ul>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div className="text-center">
                    <div className="text-lg font-bold text-foreground">{opportunity.impact}</div>
                    <div className="text-xs text-muted-foreground">Impacto</div>
                  </div>
                  <div className="text-center">
                    <div className="text-lg font-bold text-foreground">{opportunity.effort}</div>
                    <div className="text-xs text-muted-foreground">Esforço</div>
                  </div>
                  <div className="text-center">
                    <div className="text-lg font-bold text-foreground">{opportunity.timeframe}</div>
                    <div className="text-xs text-muted-foreground">Prazo</div>
                  </div>
                  <div className="text-center">
                    <div className="text-lg font-bold text-foreground capitalize">{opportunity.type}</div>
                    <div className="text-xs text-muted-foreground">Tipo</div>
                  </div>
                </div>

              </CardContent>
            </Card>
            );
          })
        ) : (
          <Card>
            <CardContent className="text-center py-8">
              <Lightbulb className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
              <h3 className="text-lg font-medium text-foreground mb-2">
                Nenhuma oportunidade encontrada
              </h3>
              <p className="text-muted-foreground">
                Ajuste os filtros para ver mais oportunidades ou verifique se há dados suficientes para análise.
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </ReportLayout>
  );
};

export default RelatorioOportunidades;

import { useState, useEffect } from "react";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
