  client_name: string;
  total_budget: number;
  current_distribution: {
    topo: number;
    meio: number;
    fundo: number;
    retencao: number;
  };
  recommended_distribution: {
    topo: number;
    meio: number;
    fundo: number;
    retencao: number;
  };
