  meio: 'Meio do Funil', 
  fundo: 'Fundo do Funil',
  retencao: 'Retenção'
};

export default function RelatorioOrcamentoMalDistribuido() {
  const { clients, loading: clientsLoading } = useClients();
  const { campaigns, loading: campaignsLoading } = useCampaigns();
  const [budgetAnalysis, setBudgetAnalysis] = useState<BudgetDistribution[]>([]);
  const [filteredData, setFilteredData] = useState<BudgetDistribution[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});

  useEffect(() => {
    if (!clientsLoading && !campaignsLoading && clients && campaigns) {
      analyzeBudgetDistribution();
    }
  }, [clients, campaigns, clientsLoading, campaignsLoading]);

  useEffect(() => {
    setFilteredData(budgetAnalysis);
  }, [budgetAnalysis]);

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = [...budgetAnalysis];

    // Filtro por cliente
    if (newFilters.cliente && newFilters.cliente !== 'todos') {
      filtered = filtered.filter(item => item.client_id === newFilters.cliente);
    }

    // Filtro por severidade
    if (newFilters.severidade && newFilters.severidade !== 'todos') {
      switch (newFilters.severidade) {
        case 'critico':
          filtered = filtered.filter(item => item.severity_score > 60);
          break;
        case 'moderado':
          filtered = filtered.filter(item => item.severity_score >= 30 && item.severity_score <= 60);
          break;
        case 'leve':
          filtered = filtered.filter(item => item.severity_score < 30);
          break;
      }
    }

    // Filtro por orçamento mínimo
    if (newFilters['orcamento-minimo'] && newFilters['orcamento-minimo'] !== 'sem-limite') {
      const minBudget = parseFloat(newFilters['orcamento-minimo']);
      filtered = filtered.filter(item => item.total_budget >= minBudget);
    }

    // Filtro por tipo de desequilíbrio
    if (newFilters['tipo-desequilibrio'] && newFilters['tipo-desequilibrio'] !== 'todos') {
      const type = newFilters['tipo-desequilibrio'];
      filtered = filtered.filter(item => 
        item.imbalances.some(imbalance => 
          type === 'excesso' ? imbalance.status === 'excess' : imbalance.status === 'deficit'
        )
      );
    }

    // Filtro por etapa do funil
    if (newFilters['etapa-funil'] && newFilters['etapa-funil'] !== 'todas') {
      const stage = newFilters['etapa-funil'];
      filtered = filtered.filter(item => 
        item.imbalances.some(imbalance => {
          const stageNames = {
            'topo': 'Topo do Funil',
            'meio': 'Meio do Funil',
            'fundo': 'Fundo do Funil',
            'retencao': 'Retenção'
          };
          return imbalance.stage === stageNames[stage as keyof typeof stageNames] && 
                 imbalance.status !== 'balanced';
        })
      );
    }

    setFilteredData(filtered);
  };

  const analyzeBudgetDistribution = () => {
    const analysis: BudgetDistribution[] = [];

    // Distribuição recomendada padrão
    const recommendedDistribution = {
      topo: 30,    // 30%
      meio: 30,    // 30%
      fundo: 30,   // 30%
      retencao: 10 // 10%
    };

    clients?.forEach(client => {
      const clientCampaigns = campaigns?.filter(c => c.client_id === client.id) || [];

      if (clientCampaigns.length === 0) return;

      const totalBudget = clientCampaigns.reduce((sum, c) => sum + (c.spend || 0), 0);

      if (totalBudget === 0) return;

      // Simular distribuição atual baseada no tipo de campanha
      // Na prática, isso viria de dados reais de categorização das campanhas
      const currentDistribution = simulateCurrentDistribution(clientCampaigns);

      // Calcular percentuais atuais
      const currentPercents = {
        topo: (currentDistribution.topo / totalBudget) * 100,
        meio: (currentDistribution.meio / totalBudget) * 100,
        fundo: (currentDistribution.fundo / totalBudget) * 100,
        retencao: (currentDistribution.retencao / totalBudget) * 100
      };

      // Identificar desequilíbrios
      const imbalances = Object.keys(recommendedDistribution).map(stage => {
        const stageKey = stage as keyof typeof recommendedDistribution;
        const currentPercent = currentPercents[stageKey];
        const recommendedPercent = recommendedDistribution[stageKey];
        const difference = currentPercent - recommendedPercent;

        let status: 'excess' | 'deficit' | 'balanced' = 'balanced';
        if (Math.abs(difference) > 10) { // Tolerância de 10%
          status = difference > 0 ? 'excess' : 'deficit';
        }

        return {
          stage: STAGE_NAMES[stageKey],
          current_percent: currentPercent,
          recommended_percent: recommendedPercent,
          difference,
          status
        };
      });

      // Calcular score de severidade (0-100, onde 100 é muito desbalanceado)
      const severityScore = imbalances.reduce((score, imbalance) => {
        return score + Math.abs(imbalance.difference);
      }, 0);

      // Gerar sugestões de reequilíbrio
      const suggestions = generateRebalanceSuggestions(imbalances, totalBudget);

      // Só incluir clientes com desequilíbrios significativos
      if (severityScore > 20) { // Threshold de 20 pontos
        analysis.push({
          client_id: client.id,
          client_name: client.name,
          total_budget: totalBudget,
          current_distribution: currentDistribution,
          recommended_distribution: {
            topo: (recommendedDistribution.topo / 100) * totalBudget,
            meio: (recommendedDistribution.meio / 100) * totalBudget,
            fundo: (recommendedDistribution.fundo / 100) * totalBudget,
            retencao: (recommendedDistribution.retencao / 100) * totalBudget
          },
          imbalances,
          severity_score: severityScore,
          rebalance_suggestions: suggestions
        });
      }
    });

    // Ordenar por severity score (pior primeiro)
    setBudgetAnalysis(analysis.sort((a, b) => b.severity_score - a.severity_score));
  };

  const simulateCurrentDistribution = (campaigns: unknown[]) => {
    // Simular distribuição baseada em características das campanhas
    const totalSpend = campaigns.reduce((sum, c) => sum + (c.spend || 0), 0);

    // Distribuição simulada (na prática viria de categorização real)
    return {
      topo: totalSpend * (0.2 + Math.random() * 0.4), // 20-60%
      meio: totalSpend * (0.1 + Math.random() * 0.3), // 10-40%
      fundo: totalSpend * (0.1 + Math.random() * 0.4), // 10-50%
      retencao: totalSpend * (0.05 + Math.random() * 0.2) // 5-25%
    };
  };

  const generateRebalanceSuggestions = (imbalances: unknown[], totalBudget: number): string[] => {
    const suggestions: string[] = [];

    const excesses = imbalances.filter(i => i.status === 'excess');
    const deficits = imbalances.filter(i => i.status === 'deficit');

    excesses.forEach(excess => {
      const amount = (Math.abs(excess.difference) / 100) * totalBudget;
      suggestions.push(
        `Reduzir orçamento em ${excess.stage} em R$ ${amount.toLocaleString()} (${Math.abs(excess.difference).toFixed(1)}%)`
      );
    });

    deficits.forEach(deficit => {
      const amount = (Math.abs(deficit.difference) / 100) * totalBudget;
      suggestions.push(
        `Aumentar orçamento em ${deficit.stage} em R$ ${amount.toLocaleString()} (${Math.abs(deficit.difference).toFixed(1)}%)`
      );
    });

    if (suggestions.length === 0) {
      suggestions.push('Distribuição está dentro dos parâmetros recomendados');
    }

    return suggestions;
  };

  const getSeverityColor = (score: number) => {
    if (score > 60) return 'text-destructive';
    if (score > 30) return 'text-warning';
    return 'text-success';
  };

  const getSeverityBadge = (score: number) => {
    if (score > 60) return { variant: 'destructive' as const, label: 'CRÍTICO' };
    if (score > 30) return { variant: 'secondary' as const, label: 'MODERADO' };
    return { variant: 'outline' as const, label: 'LEVE' };
  };

  if (clientsLoading || campaignsLoading) {
    return (
      <ReportLayout
        title="Relatório de Orçamento Mal Distribuído"
        description="Detecção de clientes que não seguem a estratégia recomendada de alocação"
      >
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="h-32 bg-muted animate-pulse rounded-lg" />
            ))}
          </div>
        </div>
      </ReportLayout>
    );
  }

  // Usar dados filtrados para métricas quando há filtros ativos
  const dataToUse = Object.keys(activeFilters).length > 0 ? filteredData : budgetAnalysis;

  const totalMisallocatedBudget = dataToUse.reduce((sum, a) => sum + a.total_budget, 0);
  const avgSeverityScore = dataToUse.length > 0 
    ? dataToUse.reduce((sum, a) => sum + a.severity_score, 0) / dataToUse.length 
    : 0;
  const criticalClients = dataToUse.filter(a => a.severity_score > 60).length;

  const availableClients = budgetAnalysis.map(analysis => ({
    value: analysis.client_id,
    label: analysis.client_name
  }));

  const primaryFilters: FilterConfig[] = [
    {
      id: 'cliente',
      label: 'Cliente',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os clientes' },
        ...availableClients
      ],
      placeholder: 'Todos os clientes'
    },
    {
      id: 'severidade',
      label: 'Nível de Severidade',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os níveis' },
        { value: 'critico', label: 'Crítico (> 60%)' },
        { value: 'moderado', label: 'Moderado (30-60%)' },
        { value: 'leve', label: 'Leve (< 30%)' }
      ],
      placeholder: 'Todos os níveis'
    },
    {
      id: 'orcamento-minimo',
      label: 'Orçamento Mínimo',
      type: 'select',
      options: [
        { value: 'sem-limite', label: 'Sem limite' },
        { value: '1000', label: 'R$ 1.000+' },
        { value: '5000', label: 'R$ 5.000+' },
        { value: '10000', label: 'R$ 10.000+' },
        { value: '50000', label: 'R$ 50.000+' }
      ],
      placeholder: 'Sem limite'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'tipo-desequilibrio',
      label: 'Tipo de Desequilíbrio',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os tipos' },
        { value: 'excesso', label: 'Excesso de verba' },
        { value: 'deficit', label: 'Déficit de verba' }
      ],
      placeholder: 'Todos os tipos'
    },
    {
      id: 'etapa-funil',
      label: 'Etapa do Funil',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as etapas' },
        { value: 'topo', label: 'Topo do Funil' },
        { value: 'meio', label: 'Meio do Funil' },
        { value: 'fundo', label: 'Fundo do Funil' },
        { value: 'retencao', label: 'Retenção' }
      ],
      placeholder: 'Todas as etapas'
    }
  ];

  return (
    <ReportLayout
      title="Relatório de Orçamento Mal Distribuído"
      description="Detecção de clientes que não seguem a estratégia recomendada de alocação"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Configure os parâmetros para análise de distribuição de orçamento"
    >
      <div className="space-y-6">
        {/* Resumo */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <MetricCard
            title="Clientes Críticos"
            value={criticalClients}
            trend={criticalClients > 0 ? "down" : "neutral"}
            subtitle="Desequilíbrio > 60%"
          />
          <MetricCard
            title="Orçamento Afetado"
            value={`R$ ${totalMisallocatedBudget.toLocaleString()}`}
            trend="down"
            subtitle="Total mal distribuído"
          />
          <MetricCard
            title="Score Médio"
            value={`${avgSeverityScore.toFixed(0)}/100`}
            trend={avgSeverityScore > 50 ? "down" : avgSeverityScore < 30 ? "up" : "neutral"}
            subtitle="Desequilíbrio médio"
          />
          <MetricCard
            title="Clientes Afetados"
            value={dataToUse.length}
            subtitle="Com desequilíbrios"
          />
        </div>

        {/* Distribuição Recomendada */}
        <Card>
          <CardHeader>
            <CardTitle>Distribuição Recomendada vs Atual</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Distribuição Recomendada */}
              <div>
                <h4 className="font-semibold mb-4 text-center">Distribuição Recomendada</h4>
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span>Topo do Funil</span>
                    <div className="flex items-center gap-2">
                      <Progress value={30} className="w-24" />
                      <span className="text-sm font-medium">30%</span>
                    </div>
                  </div>
                  <div className="flex items-center justify-between">
                    <span>Meio do Funil</span>
                    <div className="flex items-center gap-2">
                      <Progress value={30} className="w-24" />
                      <span className="text-sm font-medium">30%</span>
                    </div>
                  </div>
                  <div className="flex items-center justify-between">
                    <span>Fundo do Funil</span>
                    <div className="flex items-center gap-2">
                      <Progress value={30} className="w-24" />
                      <span className="text-sm font-medium">30%</span>
                    </div>
                  </div>
                  <div className="flex items-center justify-between">
                    <span>Retenção</span>
                    <div className="flex items-center gap-2">
                      <Progress value={10} className="w-24" />
                      <span className="text-sm font-medium">10%</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* Gráfico de Pizza */}
              <div>
                <h4 className="font-semibold mb-4 text-center">Visualização</h4>
                <ResponsiveContainer width="100%" height={200}>
                  <PieChart>
                    <Pie
                      data={[
                        { name: 'Topo', value: 30 },
                        { name: 'Meio', value: 30 },
                        { name: 'Fundo', value: 30 },
                        { name: 'Retenção', value: 10 }
                      ]}
                      cx="50%"
                      cy="50%"
                      outerRadius={80}
                      dataKey="value"
                      label={({ name, value }) => `${name}: ${value}%`}
                    >
                      {COLORS.map((color, index) => (
                        <Cell key={`cell-${index}`} fill={color} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Lista Detalhada */}
        <div className="grid gap-4">
          {filteredData.length === 0 ? (
            <Card>
              <CardContent className="p-6 text-center">
                <DollarSign className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
                <h3 className="text-lg font-semibold mb-2">Nenhum desequilíbrio significativo detectado</h3>
                <p className="text-muted-foreground">
                  Todos os clientes estão com distribuição de orçamento dentro dos parâmetros recomendados.
                </p>
              </CardContent>
            </Card>
          ) : (
            filteredData.map((analysis) => {
              const severityBadge = getSeverityBadge(analysis.severity_score);

              // Preparar dados para o gráfico de barras
              const chartData = Object.keys(analysis.current_distribution).map(stage => {
                const stageKey = stage as keyof typeof analysis.current_distribution;
                const current = (analysis.current_distribution[stageKey] / analysis.total_budget) * 100;
                const recommended = stage === 'topo' ? 30 : stage === 'meio' ? 30 : stage === 'fundo' ? 30 : 10;

                return {
                  stage: STAGE_NAMES[stageKey],
                  atual: current,
                  recomendado: recommended
                };
              });

              return (
                <Card key={analysis.client_id} className="border-l-4 border-l-warning">
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <div className="space-y-2">
                        <div className="flex items-center gap-3">
                          <AlertTriangle className="w-5 h-5 text-warning" />
                          <div>
                            <CardTitle className="text-lg">{analysis.client_name}</CardTitle>
                            <p className="text-sm text-muted-foreground">
                              Orçamento Total: R$ {analysis.total_budget.toLocaleString()}
                            </p>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <Badge variant={severityBadge.variant}>
                            DESEQUILÍBRIO {severityBadge.label}
                          </Badge>
                          <Badge variant="outline">
                            Score: {analysis.severity_score.toFixed(0)}/100
                          </Badge>
                        </div>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-6">
                    {/* Gráfico de Comparação */}
                    <div>
                      <h4 className="font-semibold mb-4">Distribuição Atual vs Recomendada</h4>
                      <ResponsiveContainer width="100%" height={300}>
                        <BarChart data={chartData}>
                          <CartesianGrid strokeDasharray="3 3" />
                          <XAxis dataKey="stage" />
                          <YAxis />
                          <Tooltip formatter={(value: unknown) => [`${value.toFixed(1)}%`, '']} />
                          <Bar dataKey="atual" fill="#ff7c7c" name="Atual" />
                          <Bar dataKey="recomendado" fill="#82ca9d" name="Recomendado" />
                        </BarChart>
                      </ResponsiveContainer>
                    </div>

                    {/* Desequilíbrios Detalhados */}
                    <div>
                      <h4 className="font-semibold mb-3">Desequilíbrios Identificados:</h4>
                      <div className="space-y-2">
                        {analysis.imbalances
                          .filter(imbalance => imbalance.status !== 'balanced')
                          .map((imbalance, index) => (
                            <div key={index} className="flex items-center justify-between p-3 bg-muted/50 rounded-lg">
                              <div className="flex items-center gap-2">
                                {imbalance.status === 'excess' ? (
                                  <TrendingUp className="w-4 h-4 text-destructive" />
                                ) : (
                                  <TrendingDown className="w-4 h-4 text-warning" />
                                )}
                                <span>{imbalance.stage}</span>
                              </div>
                              <div className="text-right">
                                <div className="font-semibold">
                                  {imbalance.current_percent.toFixed(1)}% 
                                  <span className="text-muted-foreground mx-1">vs</span>
                                  {imbalance.recommended_percent}%
                                </div>
                                <div className={`text-sm ${imbalance.status === 'excess' ? 'text-destructive' : 'text-warning'}`}>
                                  {imbalance.status === 'excess' ? '+' : ''}{imbalance.difference.toFixed(1)}%
                                </div>
                              </div>
                            </div>
                          ))}
                      </div>
                    </div>

                    {/* Sugestões de Reequilíbrio */}
                    <div>
                      <h4 className="font-semibold mb-3 text-primary">Sugestões de Reequilíbrio:</h4>
                      <ul className="space-y-2">
                        {analysis.rebalance_suggestions.map((suggestion, index) => (
                          <li key={index} className="flex items-start gap-2 text-sm">
                            <Target className="w-4 h-4 text-primary mt-0.5 flex-shrink-0" />
                            {suggestion}
                          </li>
                        ))}
                      </ul>
                    </div>
                  </CardContent>
                </Card>
              );
            })
          )}
        </div>
      </div>
    </ReportLayout>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useDashboardData } from "@/hooks/useDashboardData";
import { useClients } from "@/hooks/useClients";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { 
  TrendingUp, 
  TrendingDown, 
  Target, 
  AlertTriangle,
  Plus,
  CheckCircle,
  User
} from "lucide-react";

interface ClientAnalysis {
  id: string;
  name: string;
  investment: number;
  leads: number;
  cpa: number;
  leadsPerThousand: number; // leads por R$ 1000 investidos
  healthScore: number; // nota de saúde de 0 a 100
  analysisStatus: 'excellent' | 'good' | 'needs_attention' | 'critical';
  issues: string[];
  recommendations: string[];
}

const RelatorioPerformanceCliente = () => {
  const { clientsPerformance } = useDashboardData();
  const { clients } = useClients();
  const { convertAlertToTask } = useTaskAutomation();

  const [clientsAnalysis, setClientsAnalysis] = useState<ClientAnalysis[]>([]);
  const [filteredData, setFilteredData] = useState<ClientAnalysis[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});

  const primaryFilters: FilterConfig[] = [
    {
      id: 'status-analise',
      label: 'Status de Performance',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os status' },
        { value: 'critical', label: 'Crítico' },
        { value: 'needs_attention', label: 'Precisa de Atenção' },
        { value: 'good', label: 'Bom' },
        { value: 'excellent', label: 'Excelente' }
      ],
      placeholder: 'Todos os status'
    },
    {
      id: 'faturamento-minimo',
      label: 'Faturamento Mínimo',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os faturamentos' },
        { value: '5000', label: 'R$ 5.000+' },
        { value: '10000', label: 'R$ 10.000+' },
        { value: '25000', label: 'R$ 25.000+' }
      ],
      placeholder: 'Todos os faturamentos'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'tipo-problema',
      label: 'Tipo de Problema',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os problemas' },
        { value: 'cpa_alto', label: 'CPA Alto' },
        { value: 'poucos_leads', label: 'Poucos Leads' },
        { value: 'sem_leads', label: 'Sem Leads' }
      ],
      placeholder: 'Todos os problemas'
    }
  ];

  const analyzeClients = () => {
    // Incluir TODOS os clientes (com e sem investimento)
    const allClients = clientsPerformance;

    const analysis: ClientAnalysis[] = allClients.map(client => {
      // Usar dados REAIS ao invés de simulados
      const realLeads = client.totalLeads || client.leads_generated || 0;
      const realInvestment = client.totalInvestment || client.investment || 0;
      const realCPA = client.averageCPA || client.avg_cpl || (realInvestment > 0 && realLeads > 0 ? realInvestment / realLeads : 0);

      // Calcular leads por R$ 1000 investidos
      const leadsPerThousand = realInvestment > 0 ? (realLeads / realInvestment * 1000) : 0;

      // Calcular nota de saúde de 0 a 100
      const calculateHealthScore = () => {
        let score = 50; // Base score

        // Pontuação baseada no CPA (40 pontos máximo)
        if (realCPA === 0 && realLeads === 0) {
          score -= 40; // Sem leads nem CPA = muito ruim
        } else if (realCPA <= 60) {
          score += 40; // CPA excelente
        } else if (realCPA <= 90) {
          score += 25; // CPA bom
        } else if (realCPA <= 120) {
          score += 10; // CPA aceitável
        } else if (realCPA <= 150) {
          score -= 10; // CPA alto
        } else {
          score -= 30; // CPA muito alto
        }

        // Pontuação baseada em leads por R$1000 (30 pontos máximo)
        if (leadsPerThousand >= 15) {
          score += 30; // Excelente volume
        } else if (leadsPerThousand >= 10) {
          score += 20; // Bom volume
        } else if (leadsPerThousand >= 6) {
          score += 10; // Volume razoável
        } else if (leadsPerThousand >= 3) {
          score -= 5; // Volume baixo
        } else {
          score -= 20; // Volume muito baixo
        }

        // Pontuação baseada no volume absoluto de leads (20 pontos máximo)
        if (realLeads >= 50) {
          score += 20;
        } else if (realLeads >= 20) {
          score += 15;
        } else if (realLeads >= 10) {
          score += 10;
        } else if (realLeads >= 5) {
          score += 5;
        } else if (realLeads === 0) {
          score -= 20;
        }

        return Math.max(0, Math.min(100, Math.round(score)));
      };

      const healthScore = calculateHealthScore();

      // Identificar problemas baseados em leads e CPA
      const issues: string[] = [];

      // Clientes sem investimento (inativos)
      if (realInvestment === 0) {
        issues.push('Cliente inativo - sem campanhas em execução');
        issues.push('Nenhum investimento registrado no período');
      } else {
        // Clientes com investimento ativo
        if (leadsPerThousand < 8) issues.push('Poucos leads por investimento (meta: 8+ leads/R$1000)');
        if (realCPA > 120) issues.push(`CPA muito alto: R$ ${realCPA.toFixed(2)} (meta: <R$120)`);
        if (realLeads < 5 && realInvestment > 3000) issues.push('Volume de leads insuficiente para o investimento');
        if (realLeads === 0 && realInvestment > 0) issues.push('Nenhum lead gerado com investimento ativo');
      }

      // Determinar status baseado em leads e CPA
      const analysisStatus: ClientAnalysis['analysisStatus'] = 
        realInvestment === 0 ? 'critical' : // Clientes inativos são sempre críticos
        realLeads === 0 || realCPA > 150 ? 'critical' :
        realCPA > 120 || leadsPerThousand < 5 ? 'needs_attention' :
        realCPA <= 80 && leadsPerThousand >= 12 ? 'excellent' : 'good';

      // Gerar recomendações focadas em leads e CPA
      const recommendations: string[] = [];

      if (realInvestment === 0) {
        recommendations.push('URGENTE: Reativar cliente - criar estratégia de campanhas');
        recommendations.push('Agendar reunião para entender necessidades atuais');
        recommendations.push('Desenvolver proposta comercial personalizada');
      } else {
        if (realCPA > 120) recommendations.push('Otimizar campanhas para reduzir CPA: revisar segmentação e criativos');
        if (leadsPerThousand < 8) recommendations.push('Melhorar eficiência: aumentar volume de leads por real investido');
        if (realLeads === 0) recommendations.push('URGENTE: Investigar campanhas - sem conversões detectadas');
        if (realLeads < 10 && realInvestment > 5000) recommendations.push('Escalar investimento ou revisar funil de conversão');
      }

      return {
        id: client.id || client.name,
        name: client.name,
        investment: realInvestment,
        leads: realLeads,
        cpa: realCPA,
        leadsPerThousand: Math.round(leadsPerThousand * 10) / 10,
        healthScore,
        analysisStatus,
        issues,
        recommendations
      };
    });

    setClientsAnalysis(analysis);
  };

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = clientsAnalysis;

    if (newFilters['status-analise'] && newFilters['status-analise'] !== 'todos') {
      filtered = filtered.filter(client => client.analysisStatus === newFilters['status-analise']);
    }

    if (newFilters['faturamento-minimo'] && newFilters['faturamento-minimo'] !== 'todos') {
      const minRevenue = parseInt(newFilters['faturamento-minimo']);
      filtered = filtered.filter(client => client.investment >= minRevenue);
    }

    setFilteredData(filtered);
  };

  const handleCreateTask = async (client: ClientAnalysis) => {
    await convertAlertToTask({
      title: `Otimizar performance do cliente ${client.name}`,
      description: `Problemas: ${client.issues.join(', ')}. Recomendações: ${client.recommendations.join(', ')}`,
      priority: client.analysisStatus === 'critical' ? 'high' : 'medium',
      type: 'optimization'
    });
  };

  const getStatusBadge = (status: ClientAnalysis['analysisStatus']) => {
    const variants = { excellent: 'default', good: 'secondary', needs_attention: 'outline', critical: 'destructive' } as const;
    const labels = { excellent: 'Excelente', good: 'Bom', needs_attention: 'Precisa de Atenção', critical: 'Crítico' };
    return <Badge variant={variants[status]}>{labels[status]}</Badge>;
  };

  const getStatusIcon = (status: ClientAnalysis['analysisStatus']) => {
    switch (status) {
      case 'excellent': return <CheckCircle className="w-5 h-5 text-green-600" />;
      case 'good': return <TrendingUp className="w-5 h-5 text-blue-600" />;
      case 'needs_attention': return <AlertTriangle className="w-5 h-5 text-yellow-600" />;
      case 'critical': return <TrendingDown className="w-5 h-5 text-red-600" />;
      default: return <User className="w-5 h-5 text-gray-600" />;
    }
  };

  useEffect(() => {
    if (clientsPerformance.length > 0) {
      analyzeClients();
    }
  }, [clientsPerformance]);

  useEffect(() => {
    setFilteredData(clientsAnalysis);
  }, [clientsAnalysis]);

  const filteredMetrics = {
    totalClients: filteredData.length,
    criticalClients: filteredData.filter(c => c.analysisStatus === 'critical').length,
    totalInvestment: filteredData.reduce((acc, c) => acc + c.investment, 0),
    avgCPA: filteredData.length > 0 ? filteredData.reduce((acc, c) => acc + c.cpa, 0) / filteredData.length : 0
  };

  return (
    <ReportLayout
      title="Relatório de Performance por Cliente"
      description="Análise detalhada de leads e CPA por cliente"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
    >
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <MetricCard title="Total de Clientes" value={filteredMetrics.totalClients} />
        <MetricCard title="Clientes Críticos" value={filteredMetrics.criticalClients} trend={filteredMetrics.criticalClients > 0 ? "down" : "up"} />
        <MetricCard title="Investimento Total" value={`R$ ${filteredMetrics.totalInvestment.toLocaleString()}`} />
        <MetricCard title="CPA Médio" value={`R$ ${filteredMetrics.avgCPA.toFixed(0)}`} trend={filteredMetrics.avgCPA <= 120 ? "up" : "down"} />
      </div>

      <div className="grid gap-4">
        {filteredData
          .sort((a, b) => {
            // Ordenar primeiro por status (melhor para pior)
            const statusOrder = { excellent: 4, good: 3, needs_attention: 2, critical: 1 };
            const statusDiff = statusOrder[b.analysisStatus] - statusOrder[a.analysisStatus];

            // Se status igual, ordenar por leads per thousand (maior para menor)
            if (statusDiff === 0) {
              return b.leadsPerThousand - a.leadsPerThousand;
            }

            return statusDiff;
          })
          .map((client, index) => {
          const statusColor = client.analysisStatus === 'critical' ? 'border-l-destructive' :
                             client.analysisStatus === 'needs_attention' ? 'border-l-yellow-500' :
                             client.analysisStatus === 'good' ? 'border-l-blue-500' : 'border-l-green-500';

          return (
            <Card key={client.id} className={`border-l-4 ${statusColor}`}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div className="space-y-2">
                     <div className="flex items-center gap-3">
                       <div className="flex items-center gap-2">
                         <div className="flex items-center justify-center w-8 h-8 bg-muted rounded-full text-sm font-bold">
                           #{index + 1}
                         </div>
                         {getStatusIcon(client.analysisStatus)}
                       </div>
                        <div>
                           <CardTitle className="text-lg">{client.name}</CardTitle>
                           <p className="text-sm text-muted-foreground">
                             {client.investment > 0 ? 
                               `Cliente ativo • CPA: R$ ${client.cpa.toFixed(0)}` : 
                               'Cliente inativo • Sem campanhas'
                             }
                           </p>
                        </div>
                     </div>
                    <div className="flex items-center gap-2">
                      {getStatusBadge(client.analysisStatus)}
                       <Badge variant="outline">
                         {client.leadsPerThousand} leads/R$1000
                       </Badge>
                      <Badge variant="outline">
                        {client.leads} leads gerados
                      </Badge>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    {(client.analysisStatus === 'critical' || client.analysisStatus === 'needs_attention') && (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleCreateTask(client)}
                      >
                        <Target className="w-4 h-4 mr-2" />
                        Criar Tarefa
                      </Button>
                    )}
                  </div>
                </div>
              </CardHeader>
              <CardContent className="space-y-4">
                {/* Problemas Identificados */}
                {client.issues.length > 0 && (
                  <div>
                    <h4 className="font-semibold mb-2 text-destructive">Problemas Identificados:</h4>
                    <ul className="space-y-1">
                      {client.issues.map((issue, index) => (
                        <li key={index} className="flex items-center gap-2 text-sm">
                          <TrendingDown className="w-4 h-4 text-destructive" />
                          {issue}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Recomendação */}
                {client.recommendations.length > 0 && (
                  <div>
                    <h4 className="font-semibold mb-2 text-primary">Recomendação:</h4>
                    <p className="text-sm bg-primary/10 p-3 rounded-lg">
                      {client.recommendations[0]}
                    </p>
                  </div>
                )}

                 {/* Métricas Detalhadas */}
                 <div className="grid grid-cols-1 md:grid-cols-4 gap-4 pt-4 border-t">
                   <div className="text-center">
                     <div className={`text-2xl font-bold ${
                       client.healthScore >= 80 ? 'text-green-600' :
                       client.healthScore >= 60 ? 'text-blue-600' :
                       client.healthScore >= 40 ? 'text-yellow-600' : 'text-destructive'
                     }`}>
                       {client.healthScore}/100
                     </div>
                     <div className="text-xs text-muted-foreground">
                       Nota de Saúde
                     </div>
                   </div>
                   <div className="text-center">
                     <div className="text-2xl font-bold text-foreground">
                       R$ {client.investment.toLocaleString()}
                     </div>
                     <div className="text-xs text-muted-foreground">
                       Investimento Total
                     </div>
                   </div>
                   <div className="text-center">
                     <div className="text-2xl font-bold">
                       {client.leads}
                     </div>
                     <div className="text-xs text-muted-foreground">
                       Leads Gerados
                     </div>
                   </div>
                   <div className="text-center">
                     <div className={`text-2xl font-bold ${client.cpa <= 120 ? 'text-green-600' : 'text-destructive'}`}>
                       R$ {client.cpa.toFixed(0)}
                     </div>
                     <div className="text-xs text-muted-foreground">
                       CPA (Meta: &lt;R$ 120)
                     </div>
                   </div>
                 </div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </ReportLayout>
  );
};

