import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useTeams } from "@/hooks/useTeams";
import { useTasks } from "@/hooks/useTasks";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { 
  Users, 
  Target, 
  TrendingUp, 
  TrendingDown, 
  AlertTriangle, 
  CheckCircle, 
  Clock,
  Plus
} from "lucide-react";

interface SquadAnalysis {
  id: string;
  name: string;
  description: string;
  icon: string;
  icon_bg: string;
  icon_color: string;
  totalTasks: number;
  completedTasks: number;
  inProgressTasks: number;
  pendingTasks: number;
  productivity: number;
  avgProgress: number;
  status: 'excellent' | 'good' | 'needs_attention' | 'critical';
  issues: string[];
  recommendations: string[];
  workloadLevel: 'low' | 'normal' | 'high' | 'overloaded';
}

const RelatorioProdutividadeSquads = () => {
  const { teams } = useTeams();
  const { tasks } = useTasks();
  const { convertAlertToTask } = useTaskAutomation();

  const [squadsAnalysis, setSquadsAnalysis] = useState<SquadAnalysis[]>([]);
  const [filteredData, setFilteredData] = useState<SquadAnalysis[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});

  const primaryFilters: FilterConfig[] = [
    {
      id: 'status-performance',
      label: 'Status de Performance',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os status' },
        { value: 'critical', label: 'Crítico' },
        { value: 'needs_attention', label: 'Precisa de Atenção' },
        { value: 'good', label: 'Bom' },
        { value: 'excellent', label: 'Excelente' }
      ],
      placeholder: 'Todos os status'
    },
    {
      id: 'carga-trabalho',
      label: 'Carga de Trabalho',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as cargas' },
        { value: 'overloaded', label: 'Sobrecarregado' },
        { value: 'high', label: 'Alta' },
        { value: 'normal', label: 'Normal' },
        { value: 'low', label: 'Baixa' }
      ],
      placeholder: 'Todas as cargas'
    },
    {
      id: 'tipo-problema',
      label: 'Tipo de Problema',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os problemas' },
        { value: 'baixa_produtividade', label: 'Baixa Produtividade' },
        { value: 'sobrecarga', label: 'Sobrecarga' },
        { value: 'sem_tarefas', label: 'Sem Tarefas Ativas' },
        { value: 'atraso_entregas', label: 'Atraso nas Entregas' }
      ],
      placeholder: 'Todos os problemas'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'produtividade-minima',
      label: 'Produtividade Mínima',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as produtividades' },
        { value: '90', label: '90%+' },
        { value: '75', label: '75%+' },
        { value: '50', label: '50%+' },
        { value: '25', label: '25%+' }
      ],
      placeholder: 'Todas as produtividades'
    }
  ];

  const analyzeSquads = () => {
    const analysis: SquadAnalysis[] = teams.map(team => {
      const teamTasks = tasks.filter(task => task.team_id === team.id);
      const completedTasks = teamTasks.filter(task => task.status === 'done');
      const inProgressTasks = teamTasks.filter(task => task.status === 'progress');
      const pendingTasks = teamTasks.filter(task => task.status === 'todo');

      const productivity = teamTasks.length > 0 
        ? (completedTasks.length / teamTasks.length * 100)
        : 0;

      const avgProgress = teamTasks.length > 0 
        ? teamTasks.reduce((acc, task) => acc + task.progress, 0) / teamTasks.length 
        : 0;

      // Determinar nível de carga de trabalho
      const workloadLevel: SquadAnalysis['workloadLevel'] = 
        teamTasks.length > 15 ? 'overloaded' :
        teamTasks.length > 10 ? 'high' :
        teamTasks.length > 5 ? 'normal' : 'low';

      // Identificar problemas
      const issues: string[] = [];
      if (productivity < 50) issues.push('Produtividade baixa');
      if (teamTasks.length > 15) issues.push('Sobrecarga de trabalho');
      if (teamTasks.length === 0) issues.push('Sem tarefas ativas');
      if (inProgressTasks.length > completedTasks.length * 2) issues.push('Muitas tarefas em andamento');
      if (avgProgress < 30 && inProgressTasks.length > 0) issues.push('Progresso lento das tarefas');

      // Determinar status
      const status: SquadAnalysis['status'] = 
        productivity >= 90 && workloadLevel !== 'overloaded' ? 'excellent' :
        productivity >= 70 && issues.length <= 1 ? 'good' :
        productivity >= 50 || issues.length <= 2 ? 'needs_attention' : 'critical';

      // Gerar recomendações
      const recommendations: string[] = [];
      if (productivity < 50) recommendations.push('Revisar distribuição de tarefas e capacitação da equipe');
      if (workloadLevel === 'overloaded') recommendations.push('Redistribuir carga de trabalho ou contratar mais pessoas');
      if (teamTasks.length === 0) recommendations.push('Alocar novas tarefas para manter a equipe ativa');
      if (inProgressTasks.length > 5) recommendations.push('Focar na conclusão de tarefas em andamento');
      if (avgProgress < 30) recommendations.push('Implementar acompanhamento diário do progresso');

      return {
        id: team.id,
        name: team.name,
        description: team.description,
        icon: team.icon,
        icon_bg: team.icon_bg,
        icon_color: team.icon_color,
        totalTasks: teamTasks.length,
        completedTasks: completedTasks.length,
        inProgressTasks: inProgressTasks.length,
        pendingTasks: pendingTasks.length,
        productivity: Math.round(productivity),
        avgProgress: Math.round(avgProgress),
        status,
        issues,
        recommendations,
        workloadLevel
      };
    });

    setSquadsAnalysis(analysis);
  };

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = squadsAnalysis;

    // Filtro por status de performance
    if (newFilters['status-performance'] && newFilters['status-performance'] !== 'todos') {
      filtered = filtered.filter(squad => squad.status === newFilters['status-performance']);
    }

    // Filtro por carga de trabalho
    if (newFilters['carga-trabalho'] && newFilters['carga-trabalho'] !== 'todas') {
      filtered = filtered.filter(squad => squad.workloadLevel === newFilters['carga-trabalho']);
    }

    // Filtro por tipo de problema
    if (newFilters['tipo-problema'] && newFilters['tipo-problema'] !== 'todos') {
      const problemMap: Record<string, string> = {
        'baixa_produtividade': 'Produtividade baixa',
        'sobrecarga': 'Sobrecarga de trabalho',
        'sem_tarefas': 'Sem tarefas ativas',
        'atraso_entregas': 'Progresso lento das tarefas'
      };
      const problemText = problemMap[newFilters['tipo-problema']];
      if (problemText) {
        filtered = filtered.filter(squad => squad.issues.some(issue => issue.includes(problemText)));
      }
    }

    // Filtro por produtividade mínima
    if (newFilters['produtividade-minima'] && newFilters['produtividade-minima'] !== 'todas') {
      const minProductivity = parseInt(newFilters['produtividade-minima']);
      filtered = filtered.filter(squad => squad.productivity >= minProductivity);
    }

    setFilteredData(filtered);
  };

  const handleCreateTask = async (squad: SquadAnalysis) => {
    const taskTitle = `Melhorar produtividade do squad ${squad.name}`;
    const taskDescription = `Problemas identificados: ${squad.issues.join(', ')}. Recomendações: ${squad.recommendations.join(', ')}`;

    await convertAlertToTask({
      title: taskTitle,
      description: taskDescription,
      priority: squad.status === 'critical' ? 'high' : 'medium',
      type: 'optimization'
    });
  };

  const getStatusColor = (status: SquadAnalysis['status']) => {
    switch (status) {
      case 'excellent': return 'text-green-600';
      case 'good': return 'text-blue-600';
      case 'needs_attention': return 'text-yellow-600';
      case 'critical': return 'text-red-600';
      default: return 'text-gray-600';
    }
  };

  const getStatusBadge = (status: SquadAnalysis['status']) => {
    const variants = {
      excellent: 'default',
      good: 'secondary',
      needs_attention: 'outline',
      critical: 'destructive'
    } as const;

    const labels = {
      excellent: 'Excelente',
      good: 'Bom',
      needs_attention: 'Precisa de Atenção',
      critical: 'Crítico'
    };

    return (
      <Badge variant={variants[status]}>
        {labels[status]}
      </Badge>
    );
  };

  const getStatusIcon = (status: SquadAnalysis['status']) => {
    switch (status) {
      case 'excellent': return <CheckCircle className="w-4 h-4 text-green-600" />;
      case 'good': return <Target className="w-4 h-4 text-blue-600" />;
      case 'needs_attention': return <Clock className="w-4 h-4 text-yellow-600" />;
      case 'critical': return <AlertTriangle className="w-4 h-4 text-red-600" />;
      default: return <Users className="w-4 h-4 text-gray-600" />;
    }
  };

  useEffect(() => {
    if (teams.length > 0 && tasks.length > 0) {
      analyzeSquads();
    }
  }, [teams, tasks]);

  useEffect(() => {
    setFilteredData(squadsAnalysis);
  }, [squadsAnalysis]);

  // Métricas de resumo baseadas nos dados filtrados
  const filteredMetrics = {
    totalSquads: filteredData.length,
    criticalSquads: filteredData.filter(s => s.status === 'critical').length,
    avgProductivity: filteredData.length > 0 
      ? Math.round(filteredData.reduce((acc, s) => acc + s.productivity, 0) / filteredData.length)
      : 0,
    activeSquads: filteredData.filter(s => s.totalTasks > 0).length
  };


  return (
    <ReportLayout
      title="Relatório de Produtividade de Squads"
      description="Análise detalhada de performance e produtividade por equipe"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Use os filtros para analisar squads específicos e identificar oportunidades de melhoria"
    >
      {/* Métricas de resumo */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <MetricCard
          title="Total de Squads"
          value={filteredMetrics.totalSquads}
          subtitle="Equipes analisadas"
        />
        <MetricCard
          title="Squads Críticos"
          value={filteredMetrics.criticalSquads}
          trend={filteredMetrics.criticalSquads > 0 ? "down" : "up"}
          subtitle="Precisam de atenção imediata"
        />
        <MetricCard
          title="Produtividade Média"
          value={`${filteredMetrics.avgProductivity}%`}
          trend={filteredMetrics.avgProductivity >= 75 ? "up" : "down"}
          subtitle="Taxa de conclusão de tarefas"
        />
        <MetricCard
          title="Squads Ativos"
          value={filteredMetrics.activeSquads}
          subtitle="Com tarefas em andamento"
        />
      </div>

      {/* Lista de squads analisados */}
      <div className="space-y-4">
        {filteredData.length > 0 ? (
          filteredData.map((squad) => (
            <Card key={squad.id} className="hover:shadow-md transition-shadow">
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div 
                      className="w-12 h-12 rounded-lg flex items-center justify-center text-lg"
                      style={{ backgroundColor: squad.icon_bg, color: squad.icon_color }}
                    >
                      {squad.icon}
                    </div>
                    <div>
                      <CardTitle className="text-lg">{squad.name}</CardTitle>
                      <CardDescription>{squad.description}</CardDescription>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {getStatusIcon(squad.status)}
                    {getStatusBadge(squad.status)}
                  </div>
                </div>
              </CardHeader>

              <CardContent className="space-y-4">
                {/* Problemas identificados */}
                {squad.issues.length > 0 && (
                  <div>
                    <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                      <AlertTriangle className="w-4 h-4" />
                      Problemas Identificados
                    </h4>
                    <ul className="space-y-1">
                      {squad.issues.map((issue, index) => (
                        <li key={index} className="text-sm text-destructive flex items-center gap-2">
                          <div className="w-1 h-1 rounded-full bg-destructive" />
                          {issue}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Recomendações */}
                {squad.recommendations.length > 0 && (
                  <div>
                    <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                      <Target className="w-4 h-4" />
                      Recomendações
                    </h4>
                    <ul className="space-y-1">
                      {squad.recommendations.map((rec, index) => (
                        <li key={index} className="text-sm text-muted-foreground flex items-center gap-2">
                          <div className="w-1 h-1 rounded-full bg-primary" />
                          {rec}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Métricas */}
                <div>
                  <h4 className="font-medium text-sm text-muted-foreground mb-3 flex items-center gap-2">
                    <TrendingUp className="w-4 h-4" />
                    Métricas de Performance
                  </h4>
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    <div className="text-center">
                      <div className="text-lg font-bold text-foreground">{squad.totalTasks}</div>
                      <div className="text-xs text-muted-foreground">Total Tarefas</div>
                    </div>
                    <div className="text-center">
                      <div className="text-lg font-bold text-green-600">{squad.completedTasks}</div>
                      <div className="text-xs text-muted-foreground">Concluídas</div>
                    </div>
                    <div className="text-center">
                      <div className="text-lg font-bold text-blue-600">{squad.inProgressTasks}</div>
                      <div className="text-xs text-muted-foreground">Em Andamento</div>
                    </div>
                    <div className="text-center">
                      <div className={`text-lg font-bold ${getStatusColor(squad.status)}`}>
                        {squad.productivity}%
                      </div>
                      <div className="text-xs text-muted-foreground">Produtividade</div>
                    </div>
                    <div className="text-center">
                      <div className="text-lg font-bold text-foreground">{squad.avgProgress}%</div>
                      <div className="text-xs text-muted-foreground">Progresso Médio</div>
                    </div>
                  </div>
                </div>

                {/* Botão de ação para squads problemáticos */}
                {(squad.status === 'critical' || squad.status === 'needs_attention') && (
                  <div className="flex justify-end pt-2">
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => handleCreateTask(squad)}
                      className="flex items-center gap-2"
                    >
                      <Plus className="w-4 h-4" />
                      Criar Tarefa
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>
          ))
        ) : (
          <Card>
            <CardContent className="text-center py-8">
              <Users className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
              <h3 className="text-lg font-medium text-foreground mb-2">
                Nenhum squad encontrado
              </h3>
              <p className="text-muted-foreground">
                Ajuste os filtros para ver mais resultados ou verifique se há squads cadastrados.
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </ReportLayout>
  );
};

export default RelatorioProdutividadeSquads;

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { useEmployees } from "@/hooks/useEmployees";
import { useTasks } from "@/hooks/useTasks";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { User, TrendingUp, TrendingDown, Clock, Award, AlertTriangle, Target, Users } from "lucide-react";

interface EmployeePerformance {
  id: string;
  name: string;
  email: string;
  role: string;
  status: string;
  avatar?: string;
  start_date: string;
  team_id?: string;
  skills?: string;
  // Métricas de performance
  totalTasks: number;
  completedTasks: number;
  inProgressTasks: number;
  pendingTasks: number;
  overdueTasks: number;
  productivity: number;
  avgProgress: number;
  monthsWorked: number;
  // Análise de problemas
  issues: string[];
  status_type: 'excellent' | 'good' | 'needs_attention' | 'critical';
  recommended_actions: string[];
  workload_level: 'low' | 'normal' | 'high' | 'overloaded';
}

const RelatorioRHColaboradores = () => {
  const { employees } = useEmployees();
  const { tasks } = useTasks();
  const { convertAlertToTask } = useTaskAutomation();
  const [employeePerformances, setEmployeePerformances] = useState<EmployeePerformance[]>([]);
  const [filteredData, setFilteredData] = useState<EmployeePerformance[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});

  useEffect(() => {
    if (employees && tasks) {
      analyzeEmployeePerformance();
    }
  }, [employees, tasks]);

  useEffect(() => {
    setFilteredData(employeePerformances);
  }, [employeePerformances]);

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = [...employeePerformances];

    // Filtro por status
    if (newFilters.status && newFilters.status !== 'todos') {
      filtered = filtered.filter(emp => emp.status_type === newFilters.status);
    }

    // Filtro por função
    if (newFilters.funcao && newFilters.funcao !== 'todas') {
      filtered = filtered.filter(emp => emp.role === newFilters.funcao);
    }

    // Filtro por nível de carga de trabalho
    if (newFilters['carga-trabalho'] && newFilters['carga-trabalho'] !== 'todos') {
      filtered = filtered.filter(emp => emp.workload_level === newFilters['carga-trabalho']);
    }

    // Filtro por produtividade mínima
    if (newFilters['produtividade-minima'] && newFilters['produtividade-minima'] !== 'sem-limite') {
      const minProductivity = parseFloat(newFilters['produtividade-minima']);
      filtered = filtered.filter(emp => emp.productivity >= minProductivity);
    }

    // Filtro por tipo de problema
    if (newFilters['tipo-problema'] && newFilters['tipo-problema'] !== 'todos') {
      const problemType = newFilters['tipo-problema'];
      filtered = filtered.filter(emp => {
        switch (problemType) {
          case 'baixa-produtividade':
            return emp.issues.some(issue => issue.includes('produtividade'));
          case 'sobrecarga':
            return emp.issues.some(issue => issue.includes('sobrecarga'));
          case 'sem-tarefas':
            return emp.issues.some(issue => issue.includes('sem tarefas'));
          case 'tarefas-atrasadas':
            return emp.issues.some(issue => issue.includes('atrasadas'));
          default:
            return true;
        }
      });
    }

    setFilteredData(filtered);
  };

  const analyzeEmployeePerformance = () => {
    const performances: EmployeePerformance[] = [];

    employees?.forEach(employee => {
      const employeeTasks = tasks?.filter(task => 
        task.responsible_name === employee.name
      ) || [];

      const completedTasks = employeeTasks.filter(task => task.status === 'done');
      const inProgressTasks = employeeTasks.filter(task => task.status === 'progress');
      const pendingTasks = employeeTasks.filter(task => task.status === 'todo');

      // Calcular tarefas atrasadas (simulado)
      const today = new Date();
      const overdueTasks = employeeTasks.filter(task => 
        task.deadline && new Date(task.deadline) < today && task.status !== 'done'
      );

      const productivity = employeeTasks.length > 0 
        ? (completedTasks.length / employeeTasks.length) * 100
        : 0;

      const avgProgress = employeeTasks.length > 0 
        ? employeeTasks.reduce((acc, task) => acc + task.progress, 0) / employeeTasks.length 
        : 0;

      // Calcular tempo na empresa
      const startDate = new Date(employee.start_date);
      const monthsWorked = Math.floor((today.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24 * 30));

      // Analisar problemas
      const issues: string[] = [];
      let status_type: 'excellent' | 'good' | 'needs_attention' | 'critical' = 'good';
      const recommended_actions: string[] = [];

      // 1. Verificar produtividade baixa
      if (productivity < 50) {
        issues.push(`Produtividade baixa (${productivity.toFixed(1)}%)`);
        status_type = 'critical';
        recommended_actions.push('Revisar carga de trabalho e oferecer suporte');
      } else if (productivity < 70) {
        issues.push(`Produtividade abaixo do esperado (${productivity.toFixed(1)}%)`);
        status_type = status_type === 'good' ? 'needs_attention' : status_type;
        recommended_actions.push('Identificar obstáculos e oferecer treinamento');
      }

      // 2. Verificar sobrecarga de trabalho
      const workload_level: 'low' | 'normal' | 'high' | 'overloaded' = 
        employeeTasks.length > 15 ? 'overloaded' :
        employeeTasks.length > 10 ? 'high' :
        employeeTasks.length > 5 ? 'normal' : 'low';

      if (workload_level === 'overloaded') {
        issues.push(`Sobrecarga de trabalho (${employeeTasks.length} tarefas)`);
        status_type = status_type === 'good' ? 'needs_attention' : status_type;
        recommended_actions.push('Redistribuir tarefas ou contratar mais pessoal');
      }

      // 3. Verificar funcionário sem tarefas
      if (employeeTasks.length === 0) {
        issues.push('Colaborador sem tarefas atribuídas');
        status_type = 'needs_attention';
        recommended_actions.push('Atribuir tarefas apropriadas ao cargo');
      }

      // 4. Verificar tarefas atrasadas
      if (overdueTasks.length > 0) {
        issues.push(`${overdueTasks.length} tarefa(s) atrasada(s)`);
        status_type = status_type === 'good' ? 'needs_attention' : status_type;
        recommended_actions.push('Revisar prazos e prioridades');
      }

      // 5. Definir excelência
      if (productivity >= 90 && employeeTasks.length > 3 && overdueTasks.length === 0) {
        status_type = 'excellent';
        recommended_actions.push('Manter o excelente trabalho e considerar promoção');
      }

      // 6. Verificar colaborador novo sem produtividade
      if (monthsWorked < 3 && productivity < 30) {
        issues.push('Colaborador novo com dificuldades de adaptação');
        recommended_actions.push('Intensificar acompanhamento e mentoria');
      }

      performances.push({
        id: employee.id,
        name: employee.name,
        email: employee.email,
        role: employee.role,
        status: employee.status,
        avatar: employee.avatar,
        start_date: employee.start_date,
        team_id: employee.team_id,
        skills: employee.skills,
        totalTasks: employeeTasks.length,
        completedTasks: completedTasks.length,
        inProgressTasks: inProgressTasks.length,
        pendingTasks: pendingTasks.length,
        overdueTasks: overdueTasks.length,
        productivity,
        avgProgress,
        monthsWorked,
        issues,
        status_type,
        recommended_actions,
        workload_level
      });
    });

    // Ordenar por status (críticos primeiro)
    setEmployeePerformances(performances.sort((a, b) => {
      const statusOrder = { critical: 0, needs_attention: 1, good: 2, excellent: 3 };
      return statusOrder[a.status_type] - statusOrder[b.status_type];
    }));
  };

  const handleCreateTask = (employee: EmployeePerformance) => {
    const alertData = {
      type: employee.status_type === 'critical' ? 'danger' : 'warning',
      description: `Colaborador ${employee.name}: ${employee.issues.join(', ')} - ${employee.recommended_actions[0] || 'Revisar situação'}`,
      campaign_id: undefined,
      client_id: undefined,
      id: `employee_performance_${employee.id}`
    };

    convertAlertToTask(alertData);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'critical': return 'bg-destructive text-destructive-foreground';
      case 'needs_attention': return 'bg-warning text-warning-foreground';
      case 'excellent': return 'bg-success text-success-foreground';
      default: return 'bg-secondary text-secondary-foreground';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'critical': return AlertTriangle;
      case 'needs_attention': return TrendingDown;
      case 'excellent': return Award;
      default: return TrendingUp;
    }
  };

  const getWorkloadColor = (level: string) => {
    switch (level) {
      case 'overloaded': return 'text-destructive';
      case 'high': return 'text-warning';
      case 'low': return 'text-muted-foreground';
      default: return 'text-success';
    }
  };

  // Usar dados filtrados para métricas quando há filtros ativos
  const dataToUse = Object.keys(activeFilters).length > 0 ? filteredData : employeePerformances;

  const criticalCount = dataToUse.filter(emp => emp.status_type === 'critical').length;
  const needsAttentionCount = dataToUse.filter(emp => emp.status_type === 'needs_attention').length;
  const excellentCount = dataToUse.filter(emp => emp.status_type === 'excellent').length;
  const avgProductivity = dataToUse.length > 0 
    ? dataToUse.reduce((sum, emp) => sum + emp.productivity, 0) / dataToUse.length 
    : 0;

  // Preparar dados únicos para filtros
  const uniqueRoles = Array.from(new Set(employeePerformances.map(emp => emp.role)))
    .sort()
    .map(role => ({ value: role, label: role }));

  const primaryFilters: FilterConfig[] = [
    {
      id: 'status',
      label: 'Status de Performance',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os status' },
        { value: 'critical', label: 'Crítico' },
        { value: 'needs_attention', label: 'Precisa Atenção' },
        { value: 'good', label: 'Bom' },
        { value: 'excellent', label: 'Excelente' }
      ],
      placeholder: 'Todos os status'
    },
    {
      id: 'funcao',
      label: 'Função',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as funções' },
        ...uniqueRoles
      ],
      placeholder: 'Todas as funções'
    },
    {
      id: 'carga-trabalho',
      label: 'Carga de Trabalho',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os níveis' },
        { value: 'overloaded', label: 'Sobrecarregado' },
        { value: 'high', label: 'Alta' },
        { value: 'normal', label: 'Normal' },
        { value: 'low', label: 'Baixa' }
      ],
      placeholder: 'Todos os níveis'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'produtividade-minima',
      label: 'Produtividade Mínima',
      type: 'select',
      options: [
        { value: 'sem-limite', label: 'Sem limite' },
        { value: '90', label: '90%+' },
        { value: '80', label: '80%+' },
        { value: '70', label: '70%+' },
        { value: '50', label: '50%+' }
      ],
      placeholder: 'Sem limite'
    },
    {
      id: 'tipo-problema',
      label: 'Tipo de Problema',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os tipos' },
        { value: 'baixa-produtividade', label: 'Baixa Produtividade' },
        { value: 'sobrecarga', label: 'Sobrecarga' },
        { value: 'sem-tarefas', label: 'Sem Tarefas' },
        { value: 'tarefas-atrasadas', label: 'Tarefas Atrasadas' }
      ],
      placeholder: 'Todos os tipos'
    }
  ];

  return (
    <ReportLayout
      title="Relatório RH - Colaboradores"
      description="Análise de performance e produtividade da equipe"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Configure os parâmetros para análise de colaboradores"
    >
      <div className="space-y-6">
        {/* Resumo */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <MetricCard
            title="Situação Crítica"
            value={criticalCount}
            trend={criticalCount > 0 ? "down" : "neutral"}
            subtitle="Requerem ação imediata"
          />
          <MetricCard
            title="Precisam Atenção"
            value={needsAttentionCount}
            trend={needsAttentionCount > 0 ? "down" : "neutral"}
            subtitle="Monitoramento necessário"
          />
          <MetricCard
            title="Performance Excelente"
            value={excellentCount}
            trend={excellentCount > 0 ? "up" : "neutral"}
            subtitle="Top performers"
          />
          <MetricCard
            title="Produtividade Média"
            value={`${avgProductivity.toFixed(1)}%`}
            trend={avgProductivity > 75 ? "up" : avgProductivity > 60 ? "neutral" : "down"}
            subtitle="Da equipe"
          />
        </div>

        {/* Lista de Colaboradores */}
        <div className="grid gap-4">
          {filteredData.length === 0 ? (
            <Card>
              <CardContent className="p-6 text-center">
                <Users className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
                <h3 className="text-lg font-semibold mb-2">Nenhum colaborador encontrado</h3>
                <p className="text-muted-foreground">
                  {Object.keys(activeFilters).length > 0 
                    ? 'Nenhum colaborador corresponde aos filtros selecionados.'
                    : 'Não há colaboradores cadastrados no momento.'
                  }
                </p>
              </CardContent>
            </Card>
          ) : (
            filteredData.map((employee) => {
              const StatusIcon = getStatusIcon(employee.status_type);
              const yearsWorked = Math.floor(employee.monthsWorked / 12);
              const remainingMonths = employee.monthsWorked % 12;
              const timeString = yearsWorked > 0 
                ? `${yearsWorked}a ${remainingMonths}m`
                : `${remainingMonths}m`;

              return (
                <Card key={employee.id} className={`border-l-4 ${
                  employee.status_type === 'critical' ? 'border-l-destructive' : 
                  employee.status_type === 'needs_attention' ? 'border-l-warning' :
                  employee.status_type === 'excellent' ? 'border-l-success' : 'border-l-primary'
                }`}>
                  <CardHeader className="pb-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        <StatusIcon className={`w-5 h-5 ${
                          employee.status_type === 'critical' ? 'text-destructive' : 
                          employee.status_type === 'needs_attention' ? 'text-warning' :
                          employee.status_type === 'excellent' ? 'text-success' : 'text-primary'
                        }`} />
                        <div className="flex items-center gap-3">
                          {employee.avatar ? (
                            <img 
                              src={employee.avatar} 
                              alt={employee.name}
                              className="w-10 h-10 rounded-full"
                            />
                          ) : (
                            <div className="w-10 h-10 rounded-full bg-muted flex items-center justify-center">
                              <User className="w-5 h-5 text-muted-foreground" />
                            </div>
                          )}
                          <div>
                            <CardTitle className="text-lg">{employee.name}</CardTitle>
                            <p className="text-sm text-muted-foreground">
                              {employee.role} • {employee.email}
                            </p>
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Badge className={getStatusColor(employee.status_type)}>
                          {employee.status_type === 'critical' ? 'CRÍTICO' : 
                           employee.status_type === 'needs_attention' ? 'ATENÇÃO' :
                           employee.status_type === 'excellent' ? 'EXCELENTE' : 'BOM'}
                        </Badge>
                        <Badge variant="outline">
                          {timeString} na empresa
                        </Badge>
                        {employee.issues.length > 0 && (
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleCreateTask(employee)}
                          >
                            <Target className="w-4 h-4 mr-2" />
                            Criar Tarefa
                          </Button>
                        )}
                      </div>
                    </div>
                  </CardHeader>

                  <CardContent className="space-y-4">
                    {/* Problemas Identificados */}
                    {employee.issues.length > 0 && (
                      <div>
                        <h4 className={`font-semibold mb-2 ${
                          employee.status_type === 'critical' ? 'text-destructive' : 'text-warning'
                        }`}>
                          Problemas Identificados:
                        </h4>
                        <div className="space-y-1">
                          {employee.issues.map((issue, index) => (
                            <div key={index} className="flex items-center gap-2 text-sm text-muted-foreground">
                              <AlertTriangle className={`w-4 h-4 ${
                                employee.status_type === 'critical' ? 'text-destructive' : 'text-warning'
                              }`} />
                              <span>{issue}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Recomendações */}
                    {employee.recommended_actions.length > 0 && (
                      <div>
                        <h4 className="font-semibold mb-2 text-primary">Ações Recomendadas:</h4>
                        <div className="space-y-1">
                          {employee.recommended_actions.map((action, index) => (
                            <div key={index} className="flex items-start gap-2 text-sm">
                              <div className="w-2 h-2 bg-primary rounded-full mt-2 flex-shrink-0" />
                              <span className="text-muted-foreground">{action}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Informações Adicionais */}
                    <div className="flex items-center gap-4 text-sm">
                      <Badge variant="outline">
                        Status: {employee.status}
                      </Badge>
                      <Badge variant="outline" className={getWorkloadColor(employee.workload_level)}>
                        Carga: {employee.workload_level === 'overloaded' ? 'Sobrecarregado' :
                               employee.workload_level === 'high' ? 'Alta' :
                               employee.workload_level === 'low' ? 'Baixa' : 'Normal'}
                      </Badge>
                      {employee.skills && (
                        <Badge variant="outline">
                          Skills: {employee.skills}
                        </Badge>
                      )}
                    </div>

                    {/* Métricas de Performance */}
                    <div className="grid grid-cols-5 gap-4 pt-4 border-t">
                      <div className="text-center">
                        <div className={`text-2xl font-bold ${
                          employee.productivity >= 90 ? 'text-success' :
                          employee.productivity >= 70 ? 'text-primary' :
                          employee.productivity >= 50 ? 'text-warning' : 'text-destructive'
                        }`}>
                          {employee.productivity.toFixed(1)}%
                        </div>
                        <div className="text-xs text-muted-foreground">Produtividade</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold">
                          {employee.totalTasks}
                        </div>
                        <div className="text-xs text-muted-foreground">Total Tarefas</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-success">
                          {employee.completedTasks}
                        </div>
                        <div className="text-xs text-muted-foreground">Concluídas</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-primary">
                          {employee.inProgressTasks}
                        </div>
                        <div className="text-xs text-muted-foreground">Em Progresso</div>
                      </div>
                      <div className="text-center">
                        <div className={`text-2xl font-bold ${employee.overdueTasks > 0 ? 'text-destructive' : 'text-muted-foreground'}`}>
                          {employee.overdueTasks}
                        </div>
                        <div className="text-xs text-muted-foreground">Atrasadas</div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              );
            })
          )}
        </div>
      </div>
    </ReportLayout>
  );
};

export default RelatorioRHColaboradores;

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ReportLayout, FilterConfig } from "@/components/reports/ReportLayout";
import { MetricCard } from "@/components/reports/MetricCard";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useTasks } from "@/hooks/useTasks";
import { useTaskStats } from "@/hooks/useTaskStats";
import { useTaskAutomation } from "@/hooks/useTaskAutomation";
import { 
  CheckCircle, 
  Clock, 
  AlertTriangle, 
  Calendar,
  Target,
  TrendingUp,
  Plus,
  User
} from "lucide-react";

interface TaskAnalysis {
  id: string;
  title: string;
  description: string;
  status: string;
  priority: string;
  assigned_to?: string;
  deadline?: string;
  progress: number;
  created_at: string;
  team_id?: string;
  analysisStatus: 'excellent' | 'good' | 'needs_attention' | 'critical';
  issues: string[];
  recommendations: string[];
  daysOverdue: number;
  efficiency: number;
}

const RelatorioTarefasPlanner = () => {
  const { tasks } = useTasks();
  const taskStats = useTaskStats();
  const { convertAlertToTask } = useTaskAutomation();

  const [tasksAnalysis, setTasksAnalysis] = useState<TaskAnalysis[]>([]);
  const [filteredData, setFilteredData] = useState<TaskAnalysis[]>([]);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});

  const primaryFilters: FilterConfig[] = [
    {
      id: 'status-analise',
      label: 'Status de Análise',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os status' },
        { value: 'critical', label: 'Crítico' },
        { value: 'needs_attention', label: 'Precisa de Atenção' },
        { value: 'good', label: 'Bom' },
        { value: 'excellent', label: 'Excelente' }
      ],
      placeholder: 'Todos os status'
    },
    {
      id: 'status-tarefa',
      label: 'Status da Tarefa',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todas as tarefas' },
        { value: 'todo', label: 'Pendentes' },
        { value: 'progress', label: 'Em Progresso' },
        { value: 'done', label: 'Concluídas' }
      ],
      placeholder: 'Todas as tarefas'
    },
    {
      id: 'prioridade',
      label: 'Prioridade',
      type: 'select',
      options: [
        { value: 'todas', label: 'Todas as prioridades' },
        { value: 'high', label: 'Alta' },
        { value: 'medium', label: 'Média' },
        { value: 'low', label: 'Baixa' }
      ],
      placeholder: 'Todas as prioridades'
    }
  ];

  const secondaryFilters: FilterConfig[] = [
    {
      id: 'tipo-problema',
      label: 'Tipo de Problema',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os problemas' },
        { value: 'atrasada', label: 'Tarefas Atrasadas' },
        { value: 'sem_progresso', label: 'Sem Progresso' },
        { value: 'alta_prioridade_parada', label: 'Alta Prioridade Parada' },
        { value: 'prazo_apertado', label: 'Prazo Apertado' }
      ],
      placeholder: 'Todos os problemas'
    },
    {
      id: 'progresso-minimo',
      label: 'Progresso Mínimo',
      type: 'select',
      options: [
        { value: 'todos', label: 'Todos os progressos' },
        { value: '80', label: '80%+' },
        { value: '60', label: '60%+' },
        { value: '40', label: '40%+' },
        { value: '20', label: '20%+' }
      ],
      placeholder: 'Todos os progressos'
    }
  ];

  const analyzeTasks = () => {
    const today = new Date();

    const analysis: TaskAnalysis[] = tasks.map(task => {
      const createdDate = new Date(task.created_at);
      const dueDate = task.deadline ? new Date(task.deadline) : null;
      const daysOverdue = dueDate && dueDate < today 
        ? Math.floor((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24))
        : 0;

      const daysSinceCreated = Math.floor((today.getTime() - createdDate.getTime()) / (1000 * 60 * 60 * 24));
      const expectedProgress = Math.min(100, daysSinceCreated * 10); // 10% por dia esperado
      const efficiency = expectedProgress > 0 ? (task.progress / expectedProgress) * 100 : 100;

      // Identificar problemas
      const issues: string[] = [];
      if (daysOverdue > 0) issues.push(`Atrasada há ${daysOverdue} dias`);
      if (task.progress === 0 && daysSinceCreated > 2) issues.push('Sem progresso há mais de 2 dias');
      if (task.priority === 'high' && task.status === 'todo') issues.push('Alta prioridade não iniciada');
      if (dueDate && (dueDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24) < 2 && task.progress < 80) {
        issues.push('Prazo apertado com baixo progresso');
      }
      if (task.status === 'progress' && task.progress < 20 && daysSinceCreated > 3) {
        issues.push('Em progresso mas com baixo avanço');
      }

      // Determinar status
      const analysisStatus: TaskAnalysis['analysisStatus'] = 
        daysOverdue > 3 || (task.priority === 'high' && task.status === 'todo') ? 'critical' :
        issues.length >= 2 || daysOverdue > 0 ? 'needs_attention' :
        efficiency >= 100 && task.progress > 50 ? 'excellent' : 'good';

      // Gerar recomendações
      const recommendations: string[] = [];
      if (daysOverdue > 0) recommendations.push('Revisar prazo e realocar recursos');
      if (task.progress === 0) recommendations.push('Iniciar execução imediatamente');
      if (task.priority === 'high' && task.status === 'todo') recommendations.push('Priorizar início desta tarefa');
      if (efficiency < 50) recommendations.push('Revisar escopo e remover impedimentos');
      if (!task.user_id) recommendations.push('Atribuir responsável');

      return {
        id: task.id,
        title: task.title,
        description: task.description,
        status: task.status,
        priority: task.priority,
        assigned_to: task.user_id,
        deadline: task.deadline,
        progress: task.progress,
        created_at: task.created_at,
        team_id: task.team_id,
        analysisStatus,
        issues,
        recommendations,
        daysOverdue,
        efficiency: Math.round(efficiency)
      };
    });

    setTasksAnalysis(analysis);
  };

  const handleFilterChange = (filterId: string, value: string) => {
    const newFilters = { ...activeFilters, [filterId]: value };
    setActiveFilters(newFilters);

    let filtered = tasksAnalysis;

    // Filtro por status de análise
    if (newFilters['status-analise'] && newFilters['status-analise'] !== 'todos') {
      filtered = filtered.filter(task => task.analysisStatus === newFilters['status-analise']);
    }

    // Filtro por status da tarefa
    if (newFilters['status-tarefa'] && newFilters['status-tarefa'] !== 'todos') {
      filtered = filtered.filter(task => task.status === newFilters['status-tarefa']);
    }

    // Filtro por prioridade
    if (newFilters['prioridade'] && newFilters['prioridade'] !== 'todas') {
      filtered = filtered.filter(task => task.priority === newFilters['prioridade']);
    }

    // Filtro por tipo de problema
    if (newFilters['tipo-problema'] && newFilters['tipo-problema'] !== 'todos') {
      const problemMap: Record<string, string> = {
        'atrasada': 'Atrasada',
        'sem_progresso': 'Sem progresso',
        'alta_prioridade_parada': 'Alta prioridade não iniciada',
        'prazo_apertado': 'Prazo apertado'
      };
      const problemText = problemMap[newFilters['tipo-problema']];
      if (problemText) {
        filtered = filtered.filter(task => task.issues.some(issue => issue.includes(problemText)));
      }
    }

    // Filtro por progresso mínimo
    if (newFilters['progresso-minimo'] && newFilters['progresso-minimo'] !== 'todos') {
      const minProgress = parseInt(newFilters['progresso-minimo']);
      filtered = filtered.filter(task => task.progress >= minProgress);
    }

    setFilteredData(filtered);
  };

  const handleCreateTask = async (task: TaskAnalysis) => {
    const taskTitle = `Resolver problemas da tarefa: ${task.title}`;
    const taskDescription = `Problemas: ${task.issues.join(', ')}. Recomendações: ${task.recommendations.join(', ')}`;

    await convertAlertToTask({
      title: taskTitle,
      description: taskDescription,
      priority: task.analysisStatus === 'critical' ? 'high' : 'medium',
      type: 'improvement'
    });
  };

  const getStatusColor = (status: TaskAnalysis['analysisStatus']) => {
    switch (status) {
      case 'excellent': return 'text-green-600';
      case 'good': return 'text-blue-600';
      case 'needs_attention': return 'text-yellow-600';
      case 'critical': return 'text-red-600';
      default: return 'text-gray-600';
    }
  };

  const getStatusBadge = (status: TaskAnalysis['analysisStatus']) => {
    const variants = {
      excellent: 'default',
      good: 'secondary',
      needs_attention: 'outline',
      critical: 'destructive'
    } as const;

    const labels = {
      excellent: 'Excelente',
      good: 'Bom',
      needs_attention: 'Precisa de Atenção',
      critical: 'Crítico'
    };

    return (
      <Badge variant={variants[status]}>
        {labels[status]}
      </Badge>
    );
  };

  const getStatusIcon = (status: TaskAnalysis['analysisStatus']) => {
    switch (status) {
      case 'excellent': return <CheckCircle className="w-4 h-4 text-green-600" />;
      case 'good': return <Target className="w-4 h-4 text-blue-600" />;
      case 'needs_attention': return <Clock className="w-4 h-4 text-yellow-600" />;
      case 'critical': return <AlertTriangle className="w-4 h-4 text-red-600" />;
      default: return <Calendar className="w-4 h-4 text-gray-600" />;
    }
  };

  const getPriorityBadge = (priority: string) => {
    const variants = {
      high: 'destructive',
      medium: 'outline',
      low: 'secondary'
    } as const;

    const labels = {
      high: 'Alta',
      medium: 'Média',
      low: 'Baixa'
    };

    return (
      <Badge variant={variants[priority as keyof typeof variants] || 'outline'}>
        {labels[priority as keyof typeof labels] || priority}
      </Badge>
    );
  };

  useEffect(() => {
    if (tasks.length > 0) {
      analyzeTasks();
    }
  }, [tasks]);

  useEffect(() => {
    setFilteredData(tasksAnalysis);
  }, [tasksAnalysis]);

  // Métricas de resumo baseadas nos dados filtrados
  const filteredMetrics = {
    totalTasks: filteredData.length,
    criticalTasks: filteredData.filter(t => t.analysisStatus === 'critical').length,
    overdueTasks: filteredData.filter(t => t.daysOverdue > 0).length,
    avgEfficiency: filteredData.length > 0 
      ? Math.round(filteredData.reduce((acc, t) => acc + t.efficiency, 0) / filteredData.length)
      : 0
  };

  return (
    <ReportLayout
      title="Relatório de Tarefas do Planner"
      description="Análise detalhada de performance e eficiência das tarefas"
      primaryFilters={primaryFilters}
      secondaryFilters={secondaryFilters}
      onFilterChange={handleFilterChange}
      filterDescription="Use os filtros para analisar tarefas específicas e identificar gargalos"
    >
      {/* Métricas de resumo */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <MetricCard
          title="Total de Tarefas"
          value={filteredMetrics.totalTasks}
          subtitle="Tarefas analisadas"
        />
        <MetricCard
          title="Tarefas Críticas"
          value={filteredMetrics.criticalTasks}
          trend={filteredMetrics.criticalTasks > 0 ? "down" : "up"}
          subtitle="Precisam de atenção imediata"
        />
        <MetricCard
          title="Tarefas Atrasadas"
          value={filteredMetrics.overdueTasks}
          trend={filteredMetrics.overdueTasks > 0 ? "down" : "up"}
          subtitle="Fora do prazo"
        />
        <MetricCard
          title="Eficiência Média"
          value={`${filteredMetrics.avgEfficiency}%`}
          trend={filteredMetrics.avgEfficiency >= 80 ? "up" : "down"}
          subtitle="Taxa de progresso esperado"
        />
      </div>

      {/* Lista de tarefas analisadas */}
      <div className="space-y-4">
        {filteredData.length > 0 ? (
          filteredData.map((task) => (
            <Card key={task.id} className="hover:shadow-md transition-shadow">
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <CardTitle className="text-lg">{task.title}</CardTitle>
                      {getPriorityBadge(task.priority)}
                    </div>
                    <CardDescription>{task.description}</CardDescription>
                  </div>
                  <div className="flex items-center gap-2">
                    {getStatusIcon(task.analysisStatus)}
                    {getStatusBadge(task.analysisStatus)}
                  </div>
                </div>
              </CardHeader>

              <CardContent className="space-y-4">
                {/* Problemas identificados */}
                {task.issues.length > 0 && (
                  <div>
                    <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                      <AlertTriangle className="w-4 h-4" />
                      Problemas Identificados
                    </h4>
                    <ul className="space-y-1">
                      {task.issues.map((issue, index) => (
                        <li key={index} className="text-sm text-destructive flex items-center gap-2">
                          <div className="w-1 h-1 rounded-full bg-destructive" />
                          {issue}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Recomendações */}
                {task.recommendations.length > 0 && (
                  <div>
                    <h4 className="font-medium text-sm text-muted-foreground mb-2 flex items-center gap-2">
                      <Target className="w-4 h-4" />
                      Recomendações
                    </h4>
                    <ul className="space-y-1">
                      {task.recommendations.map((rec, index) => (
                        <li key={index} className="text-sm text-muted-foreground flex items-center gap-2">
                          <div className="w-1 h-1 rounded-full bg-primary" />
                          {rec}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Métricas */}
                <div>
                  <h4 className="font-medium text-sm text-muted-foreground mb-3 flex items-center gap-2">
                    <TrendingUp className="w-4 h-4" />
                    Métricas da Tarefa
                  </h4>
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    <div className="text-center">
                      <div className="text-lg font-bold text-foreground">{task.progress}%</div>
                      <div className="text-xs text-muted-foreground">Progresso</div>
                    </div>
                    <div className="text-center">
                      <div className={`text-lg font-bold ${getStatusColor(task.analysisStatus)}`}>
                        {task.efficiency}%
                      </div>
                      <div className="text-xs text-muted-foreground">Eficiência</div>
                    </div>
                    <div className="text-center">
                      <div className="text-lg font-bold text-foreground">
                        {task.daysOverdue > 0 ? task.daysOverdue : 0}
                      </div>
                      <div className="text-xs text-muted-foreground">Dias Atraso</div>
                    </div>
                    <div className="text-center">
                      <div className="text-lg font-bold text-foreground">
                        {task.status === 'done' ? 'Concluída' : 
                         task.status === 'progress' ? 'Em Progresso' : 'Pendente'}
                      </div>
                      <div className="text-xs text-muted-foreground">Status</div>
                    </div>
                    <div className="text-center">
                      <div className="text-lg font-bold text-foreground">
                        {task.assigned_to ? '✓' : '✗'}
                      </div>
                      <div className="text-xs text-muted-foreground">Responsável</div>
                    </div>
                  </div>
                </div>

                {/* Botão de ação para tarefas problemáticas */}
                {(task.analysisStatus === 'critical' || task.analysisStatus === 'needs_attention') && (
                  <div className="flex justify-end pt-2">
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => handleCreateTask(task)}
                      className="flex items-center gap-2"
                    >
                      <Plus className="w-4 h-4" />
                      Criar Tarefa de Melhoria
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>
          ))
        ) : (
          <Card>
            <CardContent className="text-center py-8">
              <Calendar className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
              <h3 className="text-lg font-medium text-foreground mb-2">
                Nenhuma tarefa encontrada
              </h3>
              <p className="text-muted-foreground">
                Ajuste os filtros para ver mais resultados ou verifique se há tarefas cadastradas.
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </ReportLayout>
  );
};

export default RelatorioTarefasPlanner;
